def app_config_to_meta_dict(app: AppConfig | dict[str, Any]) -> dict[str, Any]:
    if isinstance(app, AppConfig):
        return app.model_dump(by_alias=True, exclude_none=True)
    return app

# --- helper: fastmcp.apps.config.AppConfig ---
class AppConfig(BaseModel):
    resource_uri: str | None = Field(default=None, alias='resourceUri', description='URI of the UI resource (typically ui:// scheme). Tools only.')
    visibility: list[Literal['app', 'model']] | None = Field(default=None, description="Where this tool is visible: 'app', 'model', or both. Tools only.")
    csp: ResourceCSP | None = Field(default=None, description='Content Security Policy for the app iframe')
    permissions: ResourcePermissions | None = Field(default=None, description='Iframe sandbox permissions')
    domain: str | None = Field(default=None, description='Domain for the iframe')
    prefers_border: bool | None = Field(default=None, alias='prefersBorder', description='Whether the UI prefers a visible border')
    model_config = {'populate_by_name': True, 'extra': 'allow'}

class ResourcePermissions(BaseModel):
    camera: dict[str, Any] | None = Field(default=None, description='Request camera access')
    microphone: dict[str, Any] | None = Field(default=None, description='Request microphone access')
    geolocation: dict[str, Any] | None = Field(default=None, description='Request geolocation access')
    clipboard_write: dict[str, Any] | None = Field(default=None, alias='clipboardWrite', description='Request clipboard-write access')
    model_config = {'populate_by_name': True, 'extra': 'allow'}

class Choice(FastMCPApp):

    def __init__(self, name: str='Choice', *, title: str='Choose an Option', variant: Literal['default', 'outline', 'destructive', 'success', 'info']='outline') -> None:
        super().__init__(name)
        self._title = title
        self._variant = variant
        self._register_tools()

    def __repr__(self) -> str:
        return f'Choice({self.name!r})'

    def _register_tools(self) -> None:
        provider = self

        @self.ui()
        def choose(prompt: str, options: list[str], title: str | None=None) -> PrefabApp:
            _title = title or provider._title
            with Card(css_class='max-w-lg mx-auto') as view:
                with CardHeader():
                    H3(_title)
                with CardContent():
                    Text(prompt, css_class='font-medium')
                with CardFooter():
                    with If(STATE.decided):
                        Muted('Response sent.')
                    with If(~STATE.decided):
                        with Column(gap=2, css_class='w-full'):
                            for option in options:
                                Button(option, variant=provider._variant, css_class='w-full justify-start', on_click=[SendMessage(f'"{prompt}" — I selected: {option}'), SetState('decided', True)])
            return PrefabApp(view=view, state={'decided': False})

class FormInput(FastMCPApp):

    def __init__(self, model: type[pydantic.BaseModel], *, name: str | None=None, title: str | None=None, submit_text: str='Submit', tool_name: str | None=None, on_submit: Callable[..., str] | None=None, send_message: bool=False) -> None:
        app_name = name or model.__name__
        super().__init__(app_name)
        self._model = model
        self._title = title or model.__name__
        self._submit_text = submit_text
        self._tool_name = tool_name or f'collect_{model.__name__.lower()}'
        self._on_submit = on_submit
        self._send_message = send_message
        self._register_tools()

    def __repr__(self) -> str:
        return f'FormInput({self._model.__name__!r})'

    def _register_tools(self) -> None:
        provider = self
        model = self._model

        @self.tool()
        def submit_form(data: dict[str, Any] | None=None) -> str:
            if data is None:
                data = {}
            data = _backfill_boolean_defaults(model, data)
            validated = model.model_validate(data)
            if provider._on_submit is not None:
                return provider._on_submit(validated)
            return json.dumps(validated.model_dump(mode='json'))

        @self.ui(name=provider._tool_name, description=f'Collect {model.__name__} information from the user via a form. Call this tool when you need the user to provide {model.__name__} data. The user will see a validated form. After calling this tool, STOP and wait for the user to submit.')
        def collect_input(prompt: str, title: str | None=None, submit_text: str | None=None) -> PrefabApp:
            _title = title or provider._title
            _submit = submit_text or provider._submit_text
            with Card(css_class='max-w-lg mx-auto') as view:
                with CardHeader():
                    H3(_title)
                with CardContent(), Column(gap=4):
                    Muted(prompt)
                    on_success_actions: list[Any] = [SetState('submitted', True)]
                    if provider._send_message:
                        on_success_actions.insert(0, SendMessage(RESULT))
                    Form.from_model(model, submit_label=_submit, on_submit=[CallTool('submit_form', on_success=on_success_actions)])
                with CardFooter(), If(STATE.submitted):
                    Muted('Submitted.')
            return PrefabApp(view=view, state={'submitted': False})

# --- helper: fastmcp.apps.form._backfill_boolean_defaults ---
def _backfill_boolean_defaults(model: type[pydantic.BaseModel], data: dict[str, Any]) -> dict[str, Any]:
    for name, field_info in model.model_fields.items():
        if name in data:
            continue
        if field_info.annotation is bool:
            if field_info.default is not pydantic.fields.PydanticUndefined:
                data[name] = field_info.default
            else:
                data[name] = False
    return data

