@app.command
async def run(server_spec: str | None=None, *server_args: str, transport: Annotated[run_module.TransportType | None, cyclopts.Parameter(name=['--transport', '-t'], help='Transport protocol to use')]=None, host: Annotated[str | None, cyclopts.Parameter('--host', help='Host to bind to when using http transport (default: 127.0.0.1)')]=None, port: Annotated[int | None, cyclopts.Parameter(name=['--port', '-p'], help='Port to bind to when using http transport (default: 8000)')]=None, path: Annotated[str | None, cyclopts.Parameter('--path', help='The route path for the server (default: /mcp/ for http transport, /sse/ for sse transport)')]=None, log_level: Annotated[Literal['DEBUG', 'INFO', 'WARNING', 'ERROR', 'CRITICAL'] | None, cyclopts.Parameter(name=['--log-level', '-l'], help='Log level')]=None, no_banner: Annotated[bool, cyclopts.Parameter('--no-banner', help="Don't show the server banner")]=False, python: Annotated[str | None, cyclopts.Parameter('--python', help='Python version to use (e.g., 3.10, 3.11)')]=None, with_packages: Annotated[list[str] | None, cyclopts.Parameter('--with', help='Additional packages to install (can be used multiple times)')]=None, project: Annotated[Path | None, cyclopts.Parameter('--project', help='Run the command within the given project directory')]=None, with_requirements: Annotated[Path | None, cyclopts.Parameter('--with-requirements', help='Requirements file to install dependencies from')]=None, skip_source: Annotated[bool, cyclopts.Parameter('--skip-source', help='Skip source preparation step (use when source is already prepared)')]=False, skip_env: Annotated[bool, cyclopts.Parameter('--skip-env', help='Skip environment configuration (for internal use when already in a uv environment)')]=False, reload: Annotated[bool, cyclopts.Parameter('--reload', negative='--no-reload', help='Enable auto-reload on file changes (development mode)')]=False, reload_dir: Annotated[list[Path] | None, cyclopts.Parameter('--reload-dir', help='Directories to watch for changes (default: current directory)')]=None, stateless: Annotated[bool, cyclopts.Parameter('--stateless', help='Run in stateless mode (no session, used internally for reload)')]=False, module: Annotated[bool, cyclopts.Parameter(name=['--module', '-m'], help='Run a Python module (python -m <module>) instead of importing a server object')]=False) -> None:
    if module:
        if server_spec is None:
            logger.error('A module name is required when using --module / -m')
            sys.exit(1)
        ignored_options: list[str] = []
        if transport is not None:
            ignored_options.append('--transport')
        if host is not None:
            ignored_options.append('--host')
        if port is not None:
            ignored_options.append('--port')
        if path is not None:
            ignored_options.append('--path')
        if ignored_options:
            logger.warning(f"Options {', '.join(ignored_options)} are ignored in module mode (-m). The module manages its own server startup.")
        env_builder = None
        if not skip_env and (not is_already_in_uv_subprocess()):
            from fastmcp.utilities.mcp_server_config.v1.environments.uv import UVEnvironment
            env = UVEnvironment(python=python, dependencies=with_packages or None, requirements=with_requirements, project=project)
            test_cmd = ['test']
            if env.build_command(test_cmd) != test_cmd:
                env_builder = env.build_command
        if reload:
            reload_cmd = ['fastmcp', 'run', server_spec, '--module', '--no-reload']
            if log_level:
                reload_cmd.extend(['--log-level', log_level])
            if no_banner:
                reload_cmd.append('--no-banner')
            if env_builder is not None:
                reload_cmd.append('--skip-env')
            if server_args:
                reload_cmd.append('--')
                reload_cmd.extend(server_args)
            if env_builder is not None:
                reload_cmd = env_builder(reload_cmd)
            await run_module.run_with_reload(reload_cmd, reload_dirs=reload_dir, is_stdio=True)
            return
        run_module.run_module_command(server_spec, env_command_builder=env_builder, extra_args=list(server_args) if server_args else None)
        return
    if skip_env or is_already_in_uv_subprocess():
        skip_env = True
    try:
        config, server_spec = load_and_merge_config(server_spec, python=python, with_packages=with_packages or [], with_requirements=with_requirements, project=project, transport=transport, host=host, port=port, path=path, log_level=log_level, server_args=list(server_args) if server_args else None)
    except FileNotFoundError:
        sys.exit(1)
    final_transport = transport if transport is not None else config.deployment.transport
    final_host = host if host is not None else config.deployment.host
    final_port = port if port is not None else config.deployment.port
    final_path = path if path is not None else config.deployment.path
    final_log_level = log_level if log_level is not None else config.deployment.log_level
    final_server_args = server_args or config.deployment.args
    final_no_banner = no_banner if no_banner else not fastmcp.settings.show_server_banner
    logger.debug('Running server or client', extra={'server_spec': server_spec, 'transport': final_transport, 'host': final_host, 'port': final_port, 'path': final_path, 'log_level': final_log_level, 'server_args': list(final_server_args) if final_server_args else []})
    if reload:
        if final_transport == 'sse':
            logger.warning('--reload is not supported with SSE transport (sessions are lost on restart). Use streamable-http transport instead, or use --no-reload. Running without reload.')
        else:
            reload_cmd = ['fastmcp', 'run', server_spec]
            if final_transport:
                reload_cmd.extend(['--transport', final_transport])
            if final_transport != 'stdio':
                if final_host is not None:
                    reload_cmd.extend(['--host', final_host])
                if final_port is not None:
                    reload_cmd.extend(['--port', str(final_port)])
                if final_path is not None:
                    reload_cmd.extend(['--path', final_path])
            if final_log_level:
                reload_cmd.extend(['--log-level', final_log_level])
            if final_no_banner:
                reload_cmd.append('--no-banner')
            reload_cmd.append('--no-reload')
            reload_cmd.append('--stateless')
            test_cmd = ['test']
            needs_uv = config.environment.build_command(test_cmd) != test_cmd and (not skip_env)
            if needs_uv:
                reload_cmd.append('--skip-env')
            if final_server_args:
                reload_cmd.append('--')
                reload_cmd.extend(final_server_args)
            if needs_uv:
                reload_cmd = config.environment.build_command(reload_cmd)
            is_stdio = final_transport in ('stdio', None)
            await run_module.run_with_reload(reload_cmd, reload_dirs=reload_dir, is_stdio=is_stdio)
            return
    test_cmd = ['test']
    needs_uv = config.environment.build_command(test_cmd) != test_cmd and (not skip_env)
    if needs_uv:
        inner_cmd = ['fastmcp', 'run', server_spec]
        if final_transport:
            inner_cmd.extend(['--transport', final_transport])
        if final_transport != 'stdio':
            if final_host is not None:
                inner_cmd.extend(['--host', final_host])
            if final_port is not None:
                inner_cmd.extend(['--port', str(final_port)])
            if final_path is not None:
                inner_cmd.extend(['--path', final_path])
        if final_log_level:
            inner_cmd.extend(['--log-level', final_log_level])
        if final_no_banner:
            inner_cmd.append('--no-banner')
        inner_cmd.append('--skip-env')
        if final_server_args:
            inner_cmd.append('--')
            inner_cmd.extend(final_server_args)
        cmd = config.environment.build_command(inner_cmd)
        env = os.environ | {'FASTMCP_UV_SPAWNED': '1'}
        logger.debug(f"Running command: {' '.join(cmd)}")
        try:
            process = subprocess.run(cmd, check=True, env=env)
            sys.exit(process.returncode)
        except subprocess.CalledProcessError as e:
            logger.exception(f'Failed to run: {e}', extra={'server_spec': server_spec, 'error': str(e), 'returncode': e.returncode})
            sys.exit(e.returncode)
    else:
        try:
            await run_module.run_command(server_spec=server_spec, transport=final_transport, host=final_host, port=final_port, path=final_path, log_level=final_log_level, server_args=list(final_server_args) if final_server_args else [], show_banner=not final_no_banner, skip_source=skip_source, stateless=stateless)
        except Exception as e:
            logger.exception(f'Failed to run: {e}', extra={'server_spec': server_spec, 'error': str(e)})
            sys.exit(1)

