def coerce_value(raw: str, schema: dict[str, Any]) -> Any:
    schema_type = schema.get('type', 'string')
    if schema_type == 'integer':
        try:
            return int(raw)
        except ValueError:
            raise ValueError(f'Expected integer, got {raw!r}') from None
    if schema_type == 'number':
        try:
            return float(raw)
        except ValueError:
            raise ValueError(f'Expected number, got {raw!r}') from None
    if schema_type == 'boolean':
        if raw.lower() in ('true', '1', 'yes'):
            return True
        if raw.lower() in ('false', '0', 'no'):
            return False
        raise ValueError(f'Expected boolean, got {raw!r}')
    if schema_type in ('array', 'object'):
        try:
            return json.loads(raw)
        except json.JSONDecodeError:
            raise ValueError(f'Expected JSON {schema_type}, got {raw!r}') from None
    return raw

def format_tool_signature(tool: mcp.types.Tool) -> str:
    params: list[str] = []
    schema = tool.inputSchema
    properties = schema.get('properties', {})
    required = set(schema.get('required', []))
    for prop_name, prop_schema in properties.items():
        type_str = _json_schema_type_to_str(prop_schema)
        if prop_name in required:
            params.append(f'{prop_name}: {type_str}')
        else:
            default = prop_schema.get('default')
            default_repr = repr(default) if default is not None else '...'
            params.append(f'{prop_name}: {type_str} = {default_repr}')
    sig = f"{tool.name}({', '.join(params)})"
    if tool.outputSchema:
        ret = _json_schema_type_to_str(tool.outputSchema)
        sig += f' -> {ret}'
    return sig

# --- helper: fastmcp.cli.client._json_schema_type_to_str ---
def _json_schema_type_to_str(schema: dict[str, Any]) -> str:
    if 'anyOf' in schema:
        parts = [_json_schema_type_to_str(s) for s in schema['anyOf']]
        return ' | '.join(parts)
    schema_type = schema.get('type', 'any')
    if isinstance(schema_type, list):
        return ' | '.join((_JSON_SCHEMA_TYPE_MAP.get(t, t) for t in schema_type))
    return _JSON_SCHEMA_TYPE_MAP.get(schema_type, schema_type)

async def call_command(server_spec: Annotated[str | None, cyclopts.Parameter(help='Server URL, Python file, MCPConfig JSON, or .js file')]=None, target: Annotated[str, cyclopts.Parameter(help='Tool name, resource URI, or prompt name (with --prompt)')]='', *arguments: str, command: Annotated[str | None, cyclopts.Parameter('--command', help="Stdio command to connect to (e.g. 'npx -y @mcp/server')")]=None, transport: Annotated[Literal['http', 'sse'] | None, cyclopts.Parameter(name=['--transport', '-t'], help='Force transport type for URL targets (http or sse)')]=None, prompt: Annotated[bool, cyclopts.Parameter('--prompt', help='Treat target as a prompt name')]=False, input_json: Annotated[str | None, cyclopts.Parameter('--input-json', help='JSON string of arguments (merged with key=value args)')]=None, json_output: Annotated[bool, cyclopts.Parameter('--json', help='Output raw JSON result')]=False, timeout: Annotated[float | None, cyclopts.Parameter('--timeout', help='Connection timeout in seconds')]=None, auth: Annotated[str | None, cyclopts.Parameter('--auth', help="Auth method: 'oauth', a bearer token string, or 'none' to disable")]=None) -> None:
    if not target:
        console.print('[bold red]Error:[/bold red] Missing target.\n\nUsage: fastmcp call <server> <target> [key=value ...]\n\n  target can be a tool name, a resource URI, or a prompt name (with --prompt).\n\nUse [cyan]fastmcp list <server>[/cyan] to see available tools.')
        sys.exit(1)
    resolved = resolve_server_spec(server_spec, command=command, transport=transport)
    client = _build_client(resolved, timeout=timeout, auth=auth)
    try:
        async with client:
            if prompt:
                await _handle_prompt(client, target, arguments, input_json, json_output)
            elif '://' in target:
                await _handle_resource(client, target, json_output)
