# --- helper: fastmcp.cli.client._build_client ---
def _build_client(resolved: str | dict[str, Any] | ClientTransport, *, timeout: float | None=None, auth: str | None=None) -> Client:
    if auth == 'none':
        effective_auth: str | None = None
    elif auth is not None:
        effective_auth = auth
    elif _is_http_target(resolved):
        effective_auth = 'oauth'
    else:
        effective_auth = None
    return Client(resolved, timeout=timeout, auth=effective_auth, elicitation_handler=_terminal_elicitation_handler)

# --- helper: fastmcp.cli.client._handle_prompt ---
async def _handle_prompt(client: Client, prompt_name: str, arguments: tuple[str, ...], input_json: str | None, json_output: bool) -> None:
    parsed_args = parse_tool_arguments(arguments, input_json, {'type': 'object'})
    prompts = await client.list_prompts()
    prompt_map = {p.name: p for p in prompts}
    if prompt_name not in prompt_map:
        close_matches = difflib.get_close_matches(prompt_name, prompt_map.keys(), n=3, cutoff=0.5)
        msg = f'Prompt [cyan]{prompt_name}[/cyan] not found.'
        if close_matches:
            suggestions = ', '.join((f'[cyan]{m}[/cyan]' for m in close_matches))
            msg += f' Did you mean: {suggestions}?'
        console.print(f'[bold red]Error:[/bold red] {msg}')
        sys.exit(1)
    result = await client.get_prompt(prompt_name, parsed_args or None)
    if json_output:
        data: dict[str, Any] = {}
        if result.description:
            data['description'] = result.description
        data['messages'] = [{'role': msg.role, 'content': _content_block_to_dict(msg.content)} for msg in result.messages]
        console.print_json(json.dumps(data))
        return
    for msg in result.messages:
        console.print(f'[bold]{_sanitize_untrusted_text(msg.role)}:[/bold]')
        if isinstance(msg.content, mcp.types.TextContent):
            console.print(f'  {_sanitize_untrusted_text(msg.content.text)}')
        elif isinstance(msg.content, mcp.types.ImageContent):
            size = len(msg.content.data) * 3 // 4
            console.print(f'  [dim][Image: {msg.content.mimeType}, ~{size} bytes][/dim]')
        else:
            console.print(f'  {_sanitize_untrusted_text(str(msg.content))}')
        console.print()

# --- helper: fastmcp.cli.client._handle_resource ---
async def _handle_resource(client: Client, uri: str, json_output: bool) -> None:
    contents = await client.read_resource(uri)
    if json_output:
        data = []
        for block in contents:
            if isinstance(block, mcp.types.TextResourceContents):
                data.append({'uri': str(block.uri), 'mimeType': block.mimeType, 'text': block.text})
            elif isinstance(block, mcp.types.BlobResourceContents):
                data.append({'uri': str(block.uri), 'mimeType': block.mimeType, 'blob': block.blob})
        console.print_json(json.dumps(data))
        return
    for block in contents:
        if isinstance(block, mcp.types.TextResourceContents):
            console.print(_sanitize_untrusted_text(block.text))
        elif isinstance(block, mcp.types.BlobResourceContents):
            size = len(block.blob) * 3 // 4
            console.print(f'[dim][Blob: {block.mimeType}, ~{size} bytes][/dim]')

# --- helper: fastmcp.cli.client._handle_tool_call ---
async def _handle_tool_call(client: Client, tool_name: str, arguments: tuple[str, ...], input_json: str | None, json_output: bool) -> None:
    tools = await client.list_tools()
    tool_map = {t.name: t for t in tools}
    if tool_name not in tool_map:
        close_matches = difflib.get_close_matches(tool_name, tool_map.keys(), n=3, cutoff=0.5)
        msg = f'Tool [cyan]{tool_name}[/cyan] not found.'
        if close_matches:
            suggestions = ', '.join((f'[cyan]{m}[/cyan]' for m in close_matches))
            msg += f' Did you mean: {suggestions}?'
        console.print(f'[bold red]Error:[/bold red] {msg}')
        sys.exit(1)
    tool = tool_map[tool_name]
    parsed_args = parse_tool_arguments(arguments, input_json, tool.inputSchema)
    required = set(tool.inputSchema.get('required', []))
    provided = set(parsed_args.keys())
    missing = required - provided
    if missing:
        missing_str = ', '.join((f'[cyan]{m}[/cyan]' for m in sorted(missing)))
        console.print(f'[bold red]Error:[/bold red] Missing required arguments: {missing_str}')
        console.print()
        sig = format_tool_signature(tool)
        console.print(f'  [dim]{sig}[/dim]')
        sys.exit(1)
    result = await client.call_tool(tool_name, parsed_args, raise_on_error=False)
    if json_output:
        console.print_json(json.dumps(_call_result_to_dict(result)))
    else:
        _format_call_result_text(result)
    if result.is_error:
        sys.exit(1)

# --- helper: fastmcp.cli.client.resolve_server_spec ---
def resolve_server_spec(server_spec: str | None, *, command: str | None=None, transport: str | None=None) -> str | dict[str, Any] | ClientTransport:
    if command is not None and server_spec is not None:
        console.print('[bold red]Error:[/bold red] Cannot use both a server spec and --command')
        sys.exit(1)
    if command is not None:
        return _build_stdio_from_command(command)
    if server_spec is None:
        console.print('[bold red]Error:[/bold red] Provide a server spec or use --command')
        sys.exit(1)
    assert isinstance(server_spec, str)
    spec: str = server_spec
    if spec.startswith(('http://', 'https://')):
        if transport == 'sse' and (not spec.rstrip('/').endswith('/sse')):
            spec = spec.rstrip('/') + '/sse'
        return spec
    path = Path(spec)
    is_file = path.is_file() or (not path.is_dir() and spec.endswith(('.py', '.js', '.json')))
    if is_file:
        if spec.endswith('.json'):
            return _resolve_json_spec(path)
        if spec.endswith('.py'):
            resolved_path = path.resolve()
            return StdioTransport(command='fastmcp', args=['run', str(resolved_path), '--no-banner'])
        return spec
    try:
        return resolve_name(spec)
    except ValueError as exc:
        console.print(f'[bold red]Error:[/bold red] {exc}')
        sys.exit(1)

