def parse_tool_arguments(raw_args: tuple[str, ...], input_json: str | None, input_schema: dict[str, Any]) -> dict[str, Any]:
    if len(raw_args) == 1 and raw_args[0].startswith('{') and (input_json is None):
        input_json = raw_args[0]
        raw_args = ()
    result: dict[str, Any] = {}
    if input_json is not None:
        try:
            parsed = json.loads(input_json)
        except json.JSONDecodeError as exc:
            console.print(f'[bold red]Error:[/bold red] Invalid --input-json: {exc}')
            sys.exit(1)
        if not isinstance(parsed, dict):
            console.print('[bold red]Error:[/bold red] --input-json must be a JSON object')
            sys.exit(1)
        result.update(parsed)
    properties = input_schema.get('properties', {})
    for arg in raw_args:
        if '=' not in arg:
            console.print(f'[bold red]Error:[/bold red] Invalid argument [cyan]{arg}[/cyan] — expected key=value')
            sys.exit(1)
        key, value = arg.split('=', 1)
        prop_schema = properties.get(key, {})
        try:
            result[key] = coerce_value(value, prop_schema)
        except ValueError as exc:
            console.print(f'[bold red]Error:[/bold red] Argument [cyan]{key}[/cyan]: {exc}')
            sys.exit(1)
    return result

