def find_claude_command() -> str | None:
    claude_in_path = shutil.which('claude')
    if claude_in_path:
        try:
            result = subprocess.run([claude_in_path, '--version'], check=True, capture_output=True, text=True)
            if 'Claude Code' in result.stdout:
                return claude_in_path
        except (subprocess.CalledProcessError, FileNotFoundError):
            pass
    potential_paths = [Path.home() / '.claude' / 'local' / 'claude', Path('/usr/local/bin/claude'), Path.home() / '.npm-global' / 'bin' / 'claude']
    for path in potential_paths:
        if path.exists():
            try:
                result = subprocess.run([str(path), '--version'], check=True, capture_output=True, text=True)
                if 'Claude Code' in result.stdout:
                    return str(path)
            except (subprocess.CalledProcessError, FileNotFoundError):
                continue
    return None

def parse_env_var(env_var: str) -> tuple[str, str]:
    if '=' not in env_var:
