async def run_with_reload(cmd: list[str], reload_dirs: list[Path] | None=None, is_stdio: bool=False) -> None:
    watch_paths = reload_dirs or [Path.cwd()]
    process: asyncio.subprocess.Process | None = None
    first_run = True
    if is_stdio:
        logger.info('Reload mode enabled (using stateless sessions)')
    else:
        logger.info('Reload mode enabled (using stateless HTTP). Some features requiring bidirectional communication (like elicitation) are not available.')
    shutdown_event = asyncio.Event()
    loop = asyncio.get_running_loop()

    def signal_handler() -> None:
        logger.info('Received shutdown signal, stopping...')
        shutdown_event.set()
    if sys.platform != 'win32':
        loop.add_signal_handler(signal.SIGTERM, signal_handler)
        loop.add_signal_handler(signal.SIGINT, signal_handler)
    try:
        while not shutdown_event.is_set():
            if first_run or '--no-banner' in cmd:
                run_cmd = cmd
            else:
                run_cmd = [*cmd, '--no-banner']
            first_run = False
            process = await asyncio.create_subprocess_exec(*run_cmd, stdin=None, stdout=None, stderr=None, start_new_session=sys.platform != 'win32')
            watch_task = asyncio.create_task(anext(aiter(awatch(*watch_paths, watch_filter=_watch_filter))))
            wait_task = asyncio.create_task(process.wait())
            shutdown_task = asyncio.create_task(shutdown_event.wait())
            done, pending = await asyncio.wait([watch_task, wait_task, shutdown_task], return_when=asyncio.FIRST_COMPLETED)
            for task in pending:
                task.cancel()
                with contextlib.suppress(asyncio.CancelledError):
                    await task
            if shutdown_task in done:
                break
            if wait_task in done:
                code = wait_task.result()
                if code != 0:
                    logger.error(f'Server exited with code {code}, waiting for file change...')
                else:
                    logger.info('Server exited, waiting for file change...')
                watch_task = asyncio.create_task(anext(aiter(awatch(*watch_paths, watch_filter=_watch_filter))))
                shutdown_task = asyncio.create_task(shutdown_event.wait())
                done, pending = await asyncio.wait([watch_task, shutdown_task], return_when=asyncio.FIRST_COMPLETED)
                for task in pending:
                    task.cancel()
                    with contextlib.suppress(asyncio.CancelledError):
                        await task
                if shutdown_task in done:
                    break
                logger.info('Detected changes, restarting...')
            else:
                changes = watch_task.result()
                logger.info(f'Detected changes in {len(changes)} file(s), restarting...')
                await _terminate_process(process)
    except KeyboardInterrupt:
        logger.info('Received shutdown signal, stopping...')
    finally:
        if sys.platform != 'win32':
            loop.remove_signal_handler(signal.SIGTERM)
            loop.remove_signal_handler(signal.SIGINT)
        if process and process.returncode is None:
            await _terminate_process(process)

# --- helper: fastmcp.cli.run._terminate_process ---
async def _terminate_process(process: asyncio.subprocess.Process) -> None:
    if process.returncode is not None:
        return
    pid = process.pid
    if sys.platform != 'win32':
        with contextlib.suppress(ProcessLookupError, OSError):
            os.killpg(os.getpgid(pid), signal.SIGTERM)
        try:
            await asyncio.wait_for(process.wait(), timeout=3.0)
            return
        except asyncio.TimeoutError:
            pass
        with contextlib.suppress(ProcessLookupError, OSError):
            os.killpg(os.getpgid(pid), signal.SIGKILL)
    else:
        process.kill()
    await process.wait()

# --- helper: fastmcp.cli.run._watch_filter ---
def _watch_filter(_change: Change, path: str) -> bool:
    return any((path.endswith(ext) for ext in WATCHED_EXTENSIONS))

