def create_oauth_callback_server(port: int, callback_path: str='/callback', server_url: str | None=None, result_container: OAuthCallbackResult | None=None, result_ready: anyio.Event | None=None) -> Server:

    def store_result_once(*, code: str | None=None, state: str | None=None, error: Exception | None=None) -> None:
        if result_container is None or result_ready is None or result_ready.is_set():
            return
        result_container.code = code
        result_container.state = state
        result_container.error = error
        result_ready.set()

    async def callback_handler(request: Request):
        query_params = dict(request.query_params)
        callback_response = CallbackResponse.from_dict(query_params)
        if callback_response.error:
            error_desc = callback_response.error_description or 'Unknown error'
            if callback_response.error == 'access_denied':
                user_message = 'Access was denied by the authorization server.'
            else:
                user_message = f'Authorization failed: {error_desc}'
            store_result_once(error=RuntimeError(user_message))
            return create_secure_html_response(create_callback_html(user_message, is_success=False), status_code=400)
        if not callback_response.code:
            user_message = 'No authorization code was received from the server.'
            store_result_once(error=RuntimeError(user_message))
            return create_secure_html_response(create_callback_html(user_message, is_success=False), status_code=400)
        if callback_response.state is None:
            user_message = 'The OAuth server did not return the expected state parameter.'
            store_result_once(error=RuntimeError(user_message))
            return create_secure_html_response(create_callback_html(user_message, is_success=False), status_code=400)
        store_result_once(code=callback_response.code, state=callback_response.state)
        return create_secure_html_response(create_callback_html('', is_success=True, server_url=server_url))
    app = Starlette(routes=[Route(callback_path, callback_handler)])
    return Server(Config(app=app, host='127.0.0.1', port=port, lifespan='off', log_level='warning', ws='websockets-sansio'))

