class FastMCPTransport(ClientTransport):

    def __init__(self, mcp: FastMCP | FastMCP1Server, raise_exceptions: bool=False):
        self.server = mcp
        self.raise_exceptions = raise_exceptions

    @contextlib.asynccontextmanager
    async def connect_session(self, **session_kwargs: Unpack[SessionKwargs]) -> AsyncIterator[ClientSession]:
        async with create_client_server_memory_streams() as (client_streams, server_streams):
            client_read, client_write = client_streams
            server_read, server_write = server_streams
            exception_to_raise: BaseException | None = None
            async with _enter_server_lifespan(server=self.server):
                async with anyio.create_task_group() as tg:
                    tg.start_soon(lambda: self.server._mcp_server.run(server_read, server_write, self.server._mcp_server.create_initialization_options(), raise_exceptions=self.raise_exceptions))
                    try:
                        async with ClientSession(read_stream=client_read, write_stream=client_write, **session_kwargs) as client_session:
                            yield client_session
                    except BaseException as e:
                        exception_to_raise = e
                    finally:
                        tg.cancel_scope.cancel()
            if exception_to_raise is not None:
                raise exception_to_raise

    def __repr__(self) -> str:
        return f"<FastMCPTransport(server='{self.server.name}')>"

# --- helper: fastmcp.client.transports.memory._enter_server_lifespan ---
@contextlib.asynccontextmanager
async def _enter_server_lifespan(server: FastMCP | FastMCP1Server) -> AsyncIterator[None]:
    if isinstance(server, FastMCP):
        async with server._lifespan_manager():
            yield
    else:
        yield

class PromptTask(Task[mcp.types.GetPromptResult]):

    def __init__(self, client: Client, task_id: str, prompt_name: str, immediate_result: mcp.types.GetPromptResult | None=None):
        super().__init__(client, task_id, immediate_result)
        self._prompt_name = prompt_name

    async def result(self) -> mcp.types.GetPromptResult:
        if self._cached_result is not None:
            return self._cached_result
        if self._is_immediate:
            assert self._immediate_result is not None
            result = self._immediate_result
        else:
            self._check_client_connected()
            await self._wait_terminal()
            mcp_result = await self._client.get_task_result(self._task_id)
            result = mcp.types.GetPromptResult.model_validate(mcp_result)
        self._cached_result = result
        return result

# --- helper: fastmcp.client.tasks.Task ---
class Task(abc.ABC, Generic[TaskResultT]):

    def __init__(self, client: Client, task_id: str, immediate_result: TaskResultT | None=None):
        self._client = client
        self._task_id = task_id
        self._immediate_result = immediate_result
        self._is_immediate = immediate_result is not None
        self._status_cache: GetTaskResult | None = None
        self._status_event: asyncio.Event | None = None
        self._status_callbacks: list[Callable[[GetTaskResult], None | Awaitable[None]]] = []
        self._cached_result: TaskResultT | None = None

    def _check_client_connected(self) -> None:
        if self._is_immediate:
            return
        try:
            _ = self._client.session
        except RuntimeError as e:
            raise RuntimeError("Cannot access task results outside client context. Task futures must be used within 'async with client:' block.") from e

    @property
    def task_id(self) -> str:
        return self._task_id

    @property
    def returned_immediately(self) -> bool:
        return self._is_immediate

    def _handle_status_notification(self, status: GetTaskResult) -> None:
        self._status_cache = status
        if self._status_event is not None:
            self._status_event.set()
        for callback in self._status_callbacks:
            try:
                result = callback(status)
                if inspect.isawaitable(result):
                    asyncio.create_task(result)
            except Exception as e:
                logger.warning(f'Task callback error: {e}', exc_info=True)

    def on_status_change(self, callback: Callable[[GetTaskResult], None | Awaitable[None]]) -> None:
        self._status_callbacks.append(callback)

    async def status(self) -> GetTaskResult:
        self._check_client_connected()
        if self._is_immediate:
            now = datetime.now(timezone.utc)
            return GetTaskResult(taskId=self._task_id, status='completed', createdAt=now, lastUpdatedAt=now, ttl=None, pollInterval=1000)
        if self._status_cache is not None:
            cached = self._status_cache
            return cached
        self._status_cache = await self._client.get_task_status(self._task_id)
        return self._status_cache

    @abc.abstractmethod
    async def result(self) -> TaskResultT:
        ...

    async def wait(self, *, state: str | None=None, timeout: float=300.0) -> GetTaskResult:
        self._check_client_connected()
        if self._is_immediate:
            return await self.status()
        if self._status_event is None:
            self._status_event = asyncio.Event()
        start = time.time()
        in_progress_states = {'working'}
        poll_interval = 0.5
        while True:
            if self._status_cache:
                current = self._status_cache.status
                if state is None:
                    if current not in in_progress_states:
                        return self._status_cache
                elif current == state:
                    return self._status_cache
            elapsed = time.time() - start
            if elapsed >= timeout:
                raise TimeoutError(f"Task {self._task_id} did not reach {state or 'terminal state'} within {timeout}s")
            remaining = timeout - elapsed
            try:
                await asyncio.wait_for(self._status_event.wait(), timeout=min(poll_interval, remaining))
                self._status_event.clear()
            except asyncio.TimeoutError:
                self._status_cache = await self._client.get_task_status(self._task_id)

    async def _wait_terminal(self, timeout: float=300.0) -> GetTaskResult:
        terminal_states = {'completed', 'failed', 'cancelled'}
        status = await self.wait(timeout=timeout)
        while status.status not in terminal_states:
            self._status_cache = None
            status = await self.wait(timeout=timeout)
        return status

    async def cancel(self) -> None:
        if self._is_immediate:
            return
        self._check_client_connected()
        await self._client.cancel_task(self._task_id)
        self._status_cache = None

    def __await__(self):
        return self.result().__await__()

