def infer_transport(transport: ClientTransport | FastMCP | FastMCP1Server | AnyUrl | Path | MCPConfig | dict[str, Any] | str) -> ClientTransport:
    if isinstance(transport, ClientTransport):
        return transport
    elif isinstance(transport, FastMCP | FastMCP1Server):
        inferred_transport = FastMCPTransport(mcp=cast(FastMCP[Any] | FastMCP1Server, transport))
    elif isinstance(transport, Path | str) and Path(transport).exists():
        if str(transport).endswith('.py'):
            inferred_transport = PythonStdioTransport(script_path=cast(Path, transport))
        elif str(transport).endswith('.js'):
            inferred_transport = NodeStdioTransport(script_path=cast(Path, transport))
        else:
            raise ValueError(f'Unsupported script type: {transport}')
    elif isinstance(transport, AnyUrl | str) and str(transport).startswith('http'):
        inferred_transport_type = infer_transport_type_from_url(cast(AnyUrl | str, transport))
        if inferred_transport_type == 'sse':
            inferred_transport = SSETransport(url=cast(AnyUrl | str, transport))
        else:
            inferred_transport = StreamableHttpTransport(url=cast(AnyUrl | str, transport))
    elif isinstance(transport, dict | MCPConfig):
        inferred_transport = MCPConfigTransport(config=cast(dict | MCPConfig, transport))
    else:
        raise ValueError(f'Could not infer a valid transport from: {transport}')
    logger.debug(f'Inferred transport: {inferred_transport}')
    return inferred_transport

class GoogleGenaiSamplingHandler:

    def __init__(self, default_model: str, client: GoogleGenaiClient | None=None, thinking_budget: int | None=None) -> None:
        self.client: GoogleGenaiClient = client or GoogleGenaiClient()
        self.default_model: str = default_model
        self.thinking_budget: int | None = thinking_budget

    async def __call__(self, messages: list[SamplingMessage], params: SamplingParams, context: RequestContext[ServerSession, LifespanContextT] | RequestContext[ClientSession, LifespanContextT]) -> CreateMessageResult | CreateMessageResultWithTools:
        contents: list[Content] = _convert_messages_to_google_genai_content(messages)
        google_tools: list[GoogleTool] | None = None
        tool_config: ToolConfig | None = None
        if params.tools:
            google_tools = [_convert_tool_to_google_genai(tool) for tool in params.tools]
            tool_config = _convert_tool_choice_to_google_genai(params.toolChoice)
        selected_model = self._get_model(model_preferences=params.modelPreferences)
        thinking_config = ThinkingConfig(thinking_budget=self.thinking_budget) if self.thinking_budget is not None else None
        response: GenerateContentResponse = await self.client.aio.models.generate_content(model=selected_model, contents=contents, config=GenerateContentConfig(system_instruction=params.systemPrompt, temperature=params.temperature, max_output_tokens=params.maxTokens, stop_sequences=params.stopSequences, thinking_config=thinking_config, tools=google_tools, tool_config=tool_config))
        if params.tools:
            return _response_to_result_with_tools(response, selected_model)
        return _response_to_create_message_result(response, selected_model)

    def _get_model(self, model_preferences: ModelPreferences | None) -> str:
        if model_preferences and model_preferences.hints:
            for hint in model_preferences.hints:
                if hint.name and hint.name.startswith('gemini'):
                    return hint.name
        return self.default_model

# --- helper: fastmcp.client.sampling.handlers.google_genai._convert_messages_to_google_genai_content ---
def _convert_messages_to_google_genai_content(messages: Sequence[SamplingMessage]) -> list[Content]:
    google_messages: list[Content] = []
    for message in messages:
        content = message.content
        if isinstance(content, list):
            parts: list[Part] = [_sampling_content_to_google_genai_part(item) for item in content]
            if message.role == 'user':
                google_messages.append(UserContent(parts=parts))
            elif message.role == 'assistant':
                google_messages.append(ModelContent(parts=parts))
            else:
                msg = f'Invalid message role: {message.role}'
                raise ValueError(msg)
            continue
        part = _sampling_content_to_google_genai_part(content)
        if message.role == 'user':
            google_messages.append(UserContent(parts=[part]))
        elif message.role == 'assistant':
            google_messages.append(ModelContent(parts=[part]))
        else:
            msg = f'Invalid message role: {message.role}'
            raise ValueError(msg)
    return google_messages

# --- helper: fastmcp.client.sampling.handlers.google_genai._convert_tool_choice_to_google_genai ---
def _convert_tool_choice_to_google_genai(tool_choice: ToolChoice | None) -> ToolConfig:
    if tool_choice is None:
        return ToolConfig(function_calling_config=FunctionCallingConfig(mode=FunctionCallingConfigMode.AUTO))
    if tool_choice.mode == 'required':
        return ToolConfig(function_calling_config=FunctionCallingConfig(mode=FunctionCallingConfigMode.ANY))
    if tool_choice.mode == 'none':
        return ToolConfig(function_calling_config=FunctionCallingConfig(mode=FunctionCallingConfigMode.NONE))
    return ToolConfig(function_calling_config=FunctionCallingConfig(mode=FunctionCallingConfigMode.AUTO))

# --- helper: fastmcp.client.sampling.handlers.google_genai._convert_tool_to_google_genai ---
def _convert_tool_to_google_genai(tool: MCPTool) -> GoogleTool:
    from fastmcp.utilities.json_schema import compress_schema
    schema = compress_schema(tool.inputSchema, prune_titles=True)
    return GoogleTool(function_declarations=[FunctionDeclaration(name=tool.name, description=tool.description or '', parameters_json_schema=schema)])

# --- helper: fastmcp.client.sampling.handlers.google_genai._response_to_create_message_result ---
def _response_to_create_message_result(response: GenerateContentResponse, model: str) -> CreateMessageResult:
    if not (text := response.text):
        candidate = _get_candidate_from_response(response)
        has_thoughts = candidate.content and candidate.content.parts and all((getattr(p, 'thought', False) for p in candidate.content.parts))
        if has_thoughts:
            msg = 'Model returned only thinking/reasoning content with no response text.'
        else:
            msg = f'No content in response (finish_reason={candidate.finish_reason})'
        raise ValueError(msg)
    return CreateMessageResult(content=TextContent(type='text', text=text), role='assistant', model=model)

# --- helper: fastmcp.client.sampling.handlers.google_genai._response_to_result_with_tools ---
def _response_to_result_with_tools(response: GenerateContentResponse, model: str) -> CreateMessageResultWithTools:
    candidate = _get_candidate_from_response(response)
    stop_reason: StopReason
    finish_reason = candidate.finish_reason
    has_function_calls = False
    if candidate.content and candidate.content.parts:
        for part in candidate.content.parts:
            if part.function_call is not None:
                has_function_calls = True
                break
    if has_function_calls:
        stop_reason = 'toolUse'
    elif finish_reason == 'STOP':
        stop_reason = 'endTurn'
    elif finish_reason == 'MAX_TOKENS':
        stop_reason = 'maxTokens'
    else:
        stop_reason = 'endTurn'
    content: list[SamplingMessageContentBlock] = []
    if candidate.content and candidate.content.parts:
        for part in candidate.content.parts:
            if part.text and (not part.thought):
                content.append(TextContent(type='text', text=part.text))
            elif part.function_call is not None:
                fc = part.function_call
                fc_name: str = fc.name or 'unknown'
                content.append(ToolUseContent(type='tool_use', id=f'{fc_name}_{uuid4().hex[:8]}', name=fc_name, input=dict(fc.args) if fc.args else {}))
    if not content:
        finish = candidate.finish_reason if candidate else 'unknown'
        msg = f'No content in response from completion (finish_reason={finish})'
        raise ValueError(msg)
    return CreateMessageResultWithTools(content=content, role='assistant', model=model, stopReason=stop_reason)

class GetSchemas:

    def __init__(self, *, name: str='get_schema', default_detail: ToolDetailLevel | None=None) -> None:
        self._name = name
        self._default_detail: ToolDetailLevel = default_detail or 'detailed'

    def __call__(self, get_catalog: GetToolCatalog) -> Tool:
        default_detail = self._default_detail

        async def get_schema(tools: Annotated[list[str], 'List of tool names to get schemas for'], detail: Annotated[ToolDetailLevel, "'brief' for names and descriptions, 'detailed' for parameter schemas as markdown, 'full' for complete JSON schemas"]=default_detail, ctx: Context=None) -> str:
            catalog = await get_catalog(ctx)
            catalog_by_name = {t.name: t for t in catalog}
            matched = [catalog_by_name[n] for n in tools if n in catalog_by_name]
            not_found = [n for n in tools if n not in catalog_by_name]
            if not matched and not_found:
                return f"Tools not found: {', '.join(not_found)}"
            if detail == 'full':
                data = serialize_tools_for_output_json(matched)
                if not_found:
                    data.append({'not_found': not_found})
                return json.dumps(data, indent=2)
            result = _render_tools(matched, detail)
            if not_found:
                result += f"\n\nTools not found: {', '.join(not_found)}"
            return result
        return Tool.from_function(fn=get_schema, name=self._name)

# --- helper: fastmcp.experimental.transforms.code_mode._render_tools ---
def _render_tools(tools: Sequence[Tool], detail: ToolDetailLevel) -> str:
    if not tools:
        if detail == 'full':
            return json.dumps([], indent=2)
        return 'No tools matched the query.'
    if detail == 'full':
        return json.dumps(serialize_tools_for_output_json(tools), indent=2)
    if detail == 'detailed':
        return serialize_tools_for_output_markdown(tools)
    lines: list[str] = []
    for tool in tools:
        desc = f': {tool.description}' if tool.description else ''
        lines.append(f'- {tool.name}{desc}')
    return '\n'.join(lines)

