class RemoteMCPServer(BaseModel):
    url: str
    transport: Literal['http', 'streamable-http', 'sse'] | None = None
    headers: dict[str, str] = Field(default_factory=dict)
    auth: Annotated[str | Literal['oauth'] | httpx.Auth | None, Field(description='Either a string representing a Bearer token, the literal "oauth" to use OAuth authentication, or an httpx.Auth instance for custom authentication.')] = None
