class GetTags:

    def __init__(self, *, name: str='tags', default_detail: Literal['brief', 'full'] | None=None) -> None:
        self._name = name
        self._default_detail: Literal['brief', 'full'] = default_detail or 'brief'

    def __call__(self, get_catalog: GetToolCatalog) -> Tool:
        default_detail = self._default_detail

        async def tags(detail: Annotated[Literal['brief', 'full'], "Level of detail: 'brief' for tag names and counts, 'full' for tools listed under each tag"]=default_detail, ctx: Context=None) -> str:
            catalog = await get_catalog(ctx)
            by_tag: dict[str, list[Tool]] = {}
            for tool in catalog:
                if tool.tags:
                    for tag in tool.tags:
                        by_tag.setdefault(tag, []).append(tool)
                else:
                    by_tag.setdefault('untagged', []).append(tool)
            if not by_tag:
                return 'No tools available.'
            if detail == 'brief':
                lines = [f"- {tag} ({len(tools)} tool{('s' if len(tools) != 1 else '')})" for tag, tools in sorted(by_tag.items())]
                return '\n'.join(lines)
            blocks: list[str] = []
            for tag, tools in sorted(by_tag.items()):
                lines = [f'### {tag}']
                for tool in tools:
                    desc = f': {tool.description}' if tool.description else ''
                    lines.append(f'- {tool.name}{desc}')
                blocks.append('\n'.join(lines))
            return '\n\n'.join(blocks)
        return Tool.from_function(fn=tags, name=self._name)

