implementation:
def prompt(name_or_fn: str | Callable[..., Any] | None=None, *, name: str | None=None, version: str | int | None=None, title: str | None=None, description: str | None=None, icons: list[Icon] | None=None, tags: set[str] | None=None, meta: dict[str, Any] | None=None, task: bool | TaskConfig | None=None, auth: AuthCheck | list[AuthCheck] | None=None) -> Any:
    if isinstance(name_or_fn, classmethod):
        raise TypeError('To decorate a classmethod, use @classmethod above @prompt. See https://gofastmcp.com/servers/prompts#using-with-methods')

    def create_prompt(fn: Callable[..., Any], prompt_name: str | None) -> FunctionPrompt:
        prompt_meta = PromptMeta(name=prompt_name, version=version, title=title, description=description, icons=icons, tags=tags, meta=meta, task=resolve_task_config(task), auth=auth)
        return FunctionPrompt.from_function(fn, metadata=prompt_meta)

    def attach_metadata(fn: F, prompt_name: str | None) -> F:
        metadata = PromptMeta(name=prompt_name, version=version, title=title, description=description, icons=icons, tags=tags, meta=meta, task=task, auth=auth)
        target = fn.__func__ if hasattr(fn, '__func__') else fn
        target.__fastmcp__ = metadata
        return fn

    def decorator(fn: F, prompt_name: str | None) -> F:
        if fastmcp.settings.decorator_mode == 'object':
            warnings.warn("decorator_mode='object' is deprecated and will be removed in a future version. Decorators now return the original function with metadata attached.", FastMCPDeprecationWarning, stacklevel=4)
            return create_prompt(fn, prompt_name)
        return attach_metadata(fn, prompt_name)
    if inspect.isroutine(name_or_fn):
        return decorator(name_or_fn, name)
    elif isinstance(name_or_fn, str):
        if name is not None:
            raise TypeError('Cannot specify name both as first argument and keyword')
        prompt_name = name_or_fn
    elif name_or_fn is None:
        prompt_name = name
    else:
        raise TypeError(f'Invalid first argument: {type(name_or_fn)}')

    def wrapper(fn: F) -> F:
        return decorator(fn, prompt_name)
    return wrapper

# --- helper: fastmcp.prompts.function_prompt.FunctionPrompt ---
class FunctionPrompt(Prompt):
    fn: SkipJsonSchema[Callable[..., Any]]

    @classmethod
    def from_function(cls, fn: Callable[..., Any], *, metadata: PromptMeta | None=None, name: str | None=None, version: str | int | None=None, title: str | None=None, description: str | None=None, icons: list[Icon] | None=None, tags: set[str] | None=None, meta: dict[str, Any] | None=None, task: bool | TaskConfig | None=None, auth: AuthCheck | list[AuthCheck] | None=None) -> FunctionPrompt:
        individual_params_provided = any((x is not None for x in [name, version, title, description, icons, tags, meta, task, auth]))
        if metadata is not None and individual_params_provided:
            raise TypeError("Cannot pass both 'metadata' and individual parameters to from_function(). Use metadata alone or individual parameters alone.")
        if metadata is None:
            metadata = PromptMeta(name=name, version=version, title=title, description=description, icons=icons, tags=tags, meta=meta, task=task, auth=auth)
        func_name = metadata.name or getattr(fn, '__name__', None) or fn.__class__.__name__
        if func_name == '<lambda>':
            raise ValueError('You must provide a name for lambda functions')
        sig = inspect.signature(fn)
        for param in sig.parameters.values():
            if param.kind == inspect.Parameter.VAR_POSITIONAL:
                raise ValueError('Functions with *args are not supported as prompts')
            if param.kind == inspect.Parameter.VAR_KEYWORD:
                raise ValueError('Functions with **kwargs are not supported as prompts')
        outer_docstring = parse_docstring(fn)
        task_value = metadata.task
        if task_value is None:
            task_config = TaskConfig(mode='forbidden')
        elif isinstance(task_value, bool):
            task_config = TaskConfig.from_bool(task_value)
        else:
            task_config = task_value
        task_config.validate_function(fn, func_name)
        if not inspect.isroutine(fn) and (not isinstance(fn, functools.partial)):
            fn = fn.__call__
        if isinstance(fn, staticmethod):
            fn = fn.__func__
        inner_docstring = parse_docstring(fn)
        parsed_docstring = ParsedDocstring(description=outer_docstring.description or inner_docstring.description, parameters=inner_docstring.parameters)
        description = metadata.description if metadata.description is not None else parsed_docstring.description
        fn = transform_context_annotations(fn)
        wrapped_fn = without_injected_parameters(fn)
        type_adapter = get_cached_typeadapter(wrapped_fn)
        parameters = type_adapter.json_schema()
        parameters = compress_schema(parameters, prune_titles=True)
        if parsed_docstring.parameters:
            properties = parameters.get('properties', {})
            for param_name, param_desc in parsed_docstring.parameters.items():
                if param_name in properties and 'description' not in properties[param_name]:
                    properties[param_name]['description'] = param_desc
        arguments: list[PromptArgument] = []
        if 'properties' in parameters:
            for param_name, param in parameters['properties'].items():
                arg_description = param.get('description')
                if param_name in sig.parameters:
                    sig_param = sig.parameters[param_name]
                    if sig_param.annotation != inspect.Parameter.empty and sig_param.annotation is not str:
                        try:
                            param_adapter = get_cached_typeadapter(sig_param.annotation)
                            param_schema = param_adapter.json_schema()
                            schema_str = json.dumps(param_schema, separators=(',', ':'))
                            schema_note = f'Provide as a JSON string matching the following schema: {schema_str}'
                            if arg_description:
                                arg_description = f'{arg_description}\n\n{schema_note}'
                            else:
                                arg_description = schema_note
                        except Exception as e:
                            logger.debug('Failed to generate schema for prompt argument %s: %s', param_name, e)
                arguments.append(PromptArgument(name=param_name, description=arg_description, required=param_name in parameters.get('required', [])))
        return cls(name=func_name, version=str(metadata.version) if metadata.version is not None else None, title=metadata.title, description=description, icons=metadata.icons, arguments=arguments, tags=metadata.tags or set(), fn=wrapped_fn, meta=metadata.meta, task_config=task_config, auth=metadata.auth)

    def _convert_string_arguments(self, kwargs: dict[str, Any]) -> dict[str, Any]:
        from fastmcp.server.dependencies import without_injected_parameters
        wrapper_fn = without_injected_parameters(self.fn)
        sig = inspect.signature(wrapper_fn)
        converted_kwargs = {}
        for param_name, param_value in kwargs.items():
            if param_name in sig.parameters:
                param = sig.parameters[param_name]
                if (param.annotation == inspect.Parameter.empty or param.annotation is str) or not isinstance(param_value, str):
                    converted_kwargs[param_name] = param_value
                else:
                    try:
                        adapter = get_cached_typeadapter(param.annotation)
                        try:
                            converted_kwargs[param_name] = adapter.validate_json(param_value)
                        except (ValueError, TypeError, pydantic_core.ValidationError):
                            converted_kwargs[param_name] = adapter.validate_python(param_value)
                    except (ValueError, TypeError, pydantic_core.ValidationError) as e:
                        raise PromptError(f"Could not convert argument '{param_name}' with value '{param_value}' to expected type {param.annotation}. Error: {e}") from e
            else:
                converted_kwargs[param_name] = param_value
        return converted_kwargs

    async def render(self, arguments: dict[str, Any] | None=None) -> PromptResult:
        if self.arguments:
            required = {arg.name for arg in self.arguments if arg.required}
            provided = set(arguments or {})
            missing = required - provided
            if missing:
                raise ValueError(f'Missing required arguments: {missing}')
        try:
            kwargs = arguments.copy() if arguments else {}
            kwargs = self._convert_string_arguments(kwargs)
            sig = inspect.signature(self.fn)
            valid_params = set(sig.parameters.keys())
            kwargs = {k: v for k, v in kwargs.items() if k in valid_params}
            type_adapter = get_cached_typeadapter(self.fn)
            if is_coroutine_function(self.fn):
                result = await type_adapter.validate_python(kwargs)
            else:
                result = await call_sync_fn_in_threadpool(type_adapter.validate_python, kwargs)
                if inspect.isawaitable(result):
                    result = await result
            return self.convert_result(result)
        except Exception as e:
            logger.exception(f'Error rendering prompt {self.name}')
            raise PromptError(f'Error rendering prompt {self.name!r}: {e}') from e

    def register_with_docket(self, docket: Docket) -> None:
        if not self.task_config.supports_tasks():
            return
        docket.register(self.fn, names=[self.key])

    async def add_to_docket(self, docket: Docket, arguments: dict[str, Any] | None, *, fn_key: str | None=None, task_key: str | None=None, **kwargs: Any) -> Execution:
        lookup_key = fn_key or self.key
        if task_key:
            kwargs['key'] = task_key
        return await docket.add(lookup_key, **kwargs)(**arguments or {})

