class MontySandboxProvider:

    def __init__(self, *, limits: 'ResourceLimits | None'=None) -> None:
        self.limits = limits

    async def run(self, code: str, *, inputs: dict[str, Any] | None=None, external_functions: dict[str, Callable[..., Any]] | None=None) -> Any:
        try:
            pydantic_monty = importlib.import_module('pydantic_monty')
        except ModuleNotFoundError as exc:
            raise ImportError('CodeMode requires pydantic-monty for the Monty sandbox provider. Install it with `fastmcp[code-mode]` or pass a custom SandboxProvider.') from exc
        inputs = inputs or {}
        async_functions = {key: _ensure_async(value) for key, value in (external_functions or {}).items()}
        monty = pydantic_monty.Monty(code, inputs=list(inputs))
        return await monty.run_async(inputs=inputs or None, external_functions=async_functions or None, limits=self.limits)

