def build_regex(template: str) -> re.Pattern[str] | None:
    template_without_query = re.sub('\\{\\?[^}]+\\}', '', template)
    parts = re.split('(\\{[^}]+\\})', template_without_query)
    pattern = ''
    for part in parts:
        if part.startswith('{') and part.endswith('}'):
            name = part[1:-1]
            if name.endswith('*'):
                name = name[:-1]
                pattern += f'(?P<{name}>.+)'
            else:
                pattern += f'(?P<{name}>[^/]+)'
        else:
            pattern += re.escape(part)
    try:
        return re.compile(f'^{pattern}$')
    except re.error:
        return None

def extract_query_params(uri_template: str) -> set[str]:
    match = re.search('\\{\\?([^}]+)\\}', uri_template)
    if match:
        return {p.strip() for p in match.group(1).split(',')}
    return set()

