def resource(uri: str, *, name: str | None=None, version: str | int | None=None, title: str | None=None, description: str | None=None, icons: list[Icon] | None=None, mime_type: str | None=None, tags: set[str] | None=None, annotations: Annotations | dict[str, Any] | None=None, meta: dict[str, Any] | None=None, task: bool | TaskConfig | None=None, auth: AuthCheck | list[AuthCheck] | None=None) -> Callable[[F], F]:
    if isinstance(annotations, dict):
        annotations = Annotations(**annotations)
    if inspect.isroutine(uri):
        raise TypeError("The @resource decorator requires a URI. Use @resource('uri') instead of @resource")

    def create_resource(fn: Callable[..., Any]) -> FunctionResource | ResourceTemplate:
        from fastmcp.resources.template import ResourceTemplate
        from fastmcp.server.dependencies import without_injected_parameters
        resolved = resolve_task_config(task)
        has_uri_params = '{' in uri and '}' in uri
        wrapper_fn = without_injected_parameters(fn)
        has_func_params = bool(inspect.signature(wrapper_fn).parameters)
        resource_meta = ResourceMeta(uri=uri, name=name, version=version, title=title, description=description, icons=icons, tags=tags, mime_type=mime_type, annotations=annotations, meta=meta, task=resolved, auth=auth)
        if has_uri_params or has_func_params:
            return ResourceTemplate.from_function(fn=fn, uri_template=uri, name=name, version=version, title=title, description=description, icons=icons, mime_type=mime_type, tags=tags, annotations=annotations, meta=meta, task=resolved, auth=auth)
        else:
            return FunctionResource.from_function(fn, metadata=resource_meta)

    def attach_metadata(fn: F) -> F:
        metadata = ResourceMeta(uri=uri, name=name, version=version, title=title, description=description, icons=icons, tags=tags, mime_type=mime_type, annotations=annotations, meta=meta, task=task, auth=auth)
        target = fn.__func__ if hasattr(fn, '__func__') else fn
        target.__fastmcp__ = metadata
        return fn

    def decorator(fn: F) -> F:
        if fastmcp.settings.decorator_mode == 'object':
            warnings.warn("decorator_mode='object' is deprecated and will be removed in a future version. Decorators now return the original function with metadata attached.", FastMCPDeprecationWarning, stacklevel=3)
            return create_resource(fn)
        return attach_metadata(fn)
    return decorator

