class MultiAuth(AuthProvider):

    def __init__(self, *, server: AuthProvider | None=None, verifiers: list[TokenVerifier] | TokenVerifier | None=None, base_url: AnyHttpUrl | str | None=None, resource_base_url: AnyHttpUrl | str | None=None, required_scopes: list[str] | None=None):
        if verifiers is None:
            verifiers = []
        elif isinstance(verifiers, TokenVerifier):
            verifiers = [verifiers]
        if server is None and (not verifiers):
            raise ValueError('MultiAuth requires at least a server or one verifier')
        effective_base_url = base_url or (server.base_url if server else None)
        effective_resource_base_url = resource_base_url or (server.resource_base_url if server else None)
        effective_scopes = required_scopes if required_scopes is not None else server.required_scopes if server else None
        super().__init__(base_url=effective_base_url, resource_base_url=effective_resource_base_url, required_scopes=effective_scopes)
        self.server = server
        self.verifiers = list(verifiers)
        if resource_base_url is not None and self.server is not None:
            self.server.resource_base_url = self.resource_base_url
        self._sources: list[AuthProvider] = []
        if self.server is not None:
            self._sources.append(self.server)
        self._sources.extend(self.verifiers)

    async def verify_token(self, token: str) -> AccessToken | None:
        for source in self._sources:
            try:
                result = await source.verify_token(token)
                if result is not None:
                    return result
            except Exception:
                logger.debug('Token verification failed for %s, trying next source', type(source).__name__, exc_info=True)
        return None

    def set_mcp_path(self, mcp_path: str | None) -> None:
        super().set_mcp_path(mcp_path)
        if self.server is not None:
            self.server.set_mcp_path(mcp_path)
        for verifier in self.verifiers:
            verifier.set_mcp_path(mcp_path)

    def get_routes(self, mcp_path: str | None=None) -> list[Route]:
        if self.server is not None:
            return self.server.get_routes(mcp_path)
        return []

    def get_well_known_routes(self, mcp_path: str | None=None) -> list[Route]:
        if self.server is not None:
            return self.server.get_well_known_routes(mcp_path)
        return []

