class TokenHandler(_SDKTokenHandler):

    async def handle(self, request: Any):
        response = await super().handle(request)
        if response.status_code == 401:
            try:
                body = json.loads(response.body)
                if body.get('error') == 'unauthorized_client':
                    return PydanticJSONResponse(content=TokenErrorResponse(error='invalid_client', error_description=body.get('error_description')), status_code=401, headers={'Cache-Control': 'no-store', 'Pragma': 'no-cache'})
            except (json.JSONDecodeError, AttributeError):
                pass
        if response.status_code == 400:
            try:
                body = json.loads(response.body)
                if body.get('error') == 'invalid_grant':
                    return PydanticJSONResponse(content=TokenErrorResponse(error='invalid_grant', error_description=body.get('error_description')), status_code=401, headers={'Cache-Control': 'no-store', 'Pragma': 'no-cache'})
            except (json.JSONDecodeError, AttributeError):
                pass
        return response

