            parsed = urlparse(uri)
            if not parsed.scheme:
                raise ValueError(f'CIMD redirect_uri must have a scheme (e.g. http:// or https://): {uri!r}')
            if not parsed.netloc and (not uri.startswith('urn:')):
                raise ValueError(f'CIMD redirect_uri must have a host: {uri!r}')
        return v

async def run_auth_checks(checks: AuthCheck | list[AuthCheck], ctx: AuthContext) -> bool:
    check_list = [checks] if not isinstance(checks, list) else checks
    check_list = cast(list[AuthCheck], check_list)
    for check in check_list:
        try:
            result = check(ctx)
            if inspect.isawaitable(result):
                result = await result
            if not result:
                return False
        except AuthorizationError:
            raise
        except Exception:
            logger.warning(f"Auth check {getattr(check, '__name__', repr(check))} raised an unexpected exception", exc_info=True)
            return False
    return True

