class AzureJWTVerifier(JWTVerifier):

    def __init__(self, *, client_id: str, tenant_id: str, required_scopes: list[str] | None=None, identifier_uri: str | None=None, base_authority: str='login.microsoftonline.com'):
        self._identifier_uri = identifier_uri or f'api://{client_id}'
        multi_tenant_values = {'organizations', 'consumers', 'common'}
        issuer: str | None = None if tenant_id in multi_tenant_values else f'https://{base_authority}/{tenant_id}/v2.0'
        super().__init__(jwks_uri=f'https://{base_authority}/{tenant_id}/discovery/v2.0/keys', issuer=issuer, audience=[client_id, self._identifier_uri], algorithm='RS256', required_scopes=required_scopes)

    @property
    def scopes_supported(self) -> list[str]:
        if not self.required_scopes:
            return []
        prefixed = []
        for scope in self.required_scopes:
            if scope in OIDC_SCOPES or '://' in scope or '/' in scope:
                prefixed.append(scope)
            else:
                prefixed.append(f'{self._identifier_uri}/{scope}')
        return prefixed

