# --- helper: fastmcp.server.auth.providers.clerk.ClerkTokenVerifier ---
class ClerkTokenVerifier(TokenVerifier):

    def __init__(self, *, domain: str, client_id: str | None=None, client_secret: str | None=None, required_scopes: list[str] | None=None, timeout_seconds: int=10, http_client: httpx.AsyncClient | None=None):
        super().__init__(required_scopes=required_scopes)
        self.domain = domain.rstrip('/')
        self._client_id = client_id
        self._client_secret = client_secret
        self.timeout_seconds = timeout_seconds
        self._http_client = http_client
        self._userinfo_url = f'https://{self.domain}/oauth/userinfo'
        self._introspection_url = f'https://{self.domain}/oauth/token_info'

    async def verify_token(self, token: str) -> AccessToken | None:
        try:
            async with contextlib.nullcontext(self._http_client) if self._http_client is not None else httpx.AsyncClient(timeout=self.timeout_seconds) as client:
                introspect_data_payload: dict = {'token': token}
                introspect_kwargs: dict = {'data': introspect_data_payload, 'headers': {'User-Agent': 'FastMCP-Clerk-OAuth'}}
                if self._client_id and self._client_secret:
                    introspect_kwargs['auth'] = (self._client_id, self._client_secret)
                elif self._client_id:
                    introspect_data_payload['client_id'] = self._client_id
                introspect_response = await client.post(self._introspection_url, **introspect_kwargs)
                if introspect_response.status_code != 200:
                    logger.debug('Clerk introspection failed: %d', introspect_response.status_code)
                    return None
                introspect_data = introspect_response.json()
                if 'active' not in introspect_data or not introspect_data['active']:
                    logger.debug("Clerk introspection: token inactive or missing 'active' field")
                    return None
                scope_str = introspect_data.get('scope', '')
                token_scopes = scope_str.split() if scope_str else []
                aud = introspect_data.get('aud') or introspect_data.get('client_id')
                expires_at: int | None = None
                exp = introspect_data.get('exp')
                if exp is not None:
                    with contextlib.suppress(ValueError, TypeError):
                        expires_at = int(exp)
                if self._client_id and aud != self._client_id:
                    logger.debug('Clerk token audience mismatch: got %s, expected %s', aud, self._client_id)
                    return None
                if self.required_scopes:
                    if not token_scopes:
                        logger.debug('Clerk token missing scope information; cannot verify required scopes %s', self.required_scopes)
                        return None
                    token_scopes_set = set(token_scopes)
                    required_scopes_set = set(self.required_scopes)
                    if not required_scopes_set.issubset(token_scopes_set):
                        logger.debug('Clerk token missing required scopes. Has %s, needs %s', token_scopes_set, required_scopes_set)
                        return None
                sub = introspect_data.get('sub')
                user_data: dict = {}
                try:
                    userinfo_response = await client.get(self._userinfo_url, headers={'Authorization': f'Bearer {token}', 'User-Agent': 'FastMCP-Clerk-OAuth'})
                    if userinfo_response.status_code == 200:
                        user_data = userinfo_response.json()
                        if not sub:
                            sub = user_data.get('sub')
                except Exception as e:
                    logger.debug('Clerk userinfo call failed: %s', e)
                if not sub:
                    logger.debug("Clerk token missing 'sub' claim")
                    return None
                access_token = AccessToken(token=token, client_id=aud or sub, scopes=token_scopes, expires_at=expires_at, claims={'sub': sub, 'aud': aud, 'email': user_data.get('email'), 'email_verified': user_data.get('email_verified'), 'name': user_data.get('name'), 'picture': user_data.get('picture'), 'given_name': user_data.get('given_name'), 'family_name': user_data.get('family_name'), 'preferred_username': user_data.get('preferred_username'), 'iss': user_data.get('iss'), 'clerk_user_data': user_data or None})
                logger.debug('Clerk token verified successfully for sub=%s', sub)
                return access_token
        except httpx.RequestError as e:
            logger.debug('Failed to verify Clerk token: %s', e)
            return None
        except Exception as e:
            logger.debug('Clerk token verification error: %s', e)
            return None

class AzureProvider(OAuthProxy):

    def __init__(self, *, client_id: str, client_secret: str | None=None, tenant_id: str, required_scopes: list[str], base_url: str, resource_base_url: AnyHttpUrl | str | None=None, identifier_uri: str | None=None, issuer_url: str | None=None, redirect_path: str | None=None, additional_authorize_scopes: list[str] | None=None, allowed_client_redirect_uris: list[str] | None=None, client_storage: AsyncKeyValue | None=None, jwt_signing_key: str | bytes | None=None, require_authorization_consent: bool | Literal['external']=True, consent_csp_policy: str | None=None, forward_resource: bool=True, base_authority: str='login.microsoftonline.com', http_client: httpx.AsyncClient | None=None, enable_cimd: bool=True) -> None:
        parsed_required_scopes = parse_scopes(required_scopes)
        parsed_additional_scopes: list[str] = parse_scopes(additional_authorize_scopes) or [] if additional_authorize_scopes else []
        if 'offline_access' not in parsed_additional_scopes:
            parsed_additional_scopes = [*parsed_additional_scopes, 'offline_access']
