        self._base_authority = base_authority
        self._obo_credentials: OrderedDict[str, OnBehalfOfCredential] = OrderedDict()
        self._obo_max_credentials: int = 128
        self.identifier_uri = identifier_uri or f'api://{client_id}'
        self.additional_authorize_scopes: list[str] = parsed_additional_scopes
        issuer = f'https://{base_authority}/{tenant_id}/v2.0'
        jwks_uri = f'https://{base_authority}/{tenant_id}/discovery/v2.0/keys'
        validation_scopes = [s for s in parsed_required_scopes or [] if s not in OIDC_SCOPES]
        if not validation_scopes:
            raise ValueError("AzureProvider requires at least one non-OIDC scope in required_scopes (e.g., 'read', 'write'). OIDC scopes like 'openid', 'profile', 'email', and 'offline_access' are not included in Azure access token claims and cannot be used for scope enforcement.")
        token_verifier = JWTVerifier(jwks_uri=jwks_uri, issuer=issuer, audience=[client_id, self.identifier_uri], algorithm='RS256', required_scopes=validation_scopes, http_client=http_client)
        authorization_endpoint = f'https://{base_authority}/{tenant_id}/oauth2/v2.0/authorize'
        token_endpoint = f'https://{base_authority}/{tenant_id}/oauth2/v2.0/token'
