        authority_info = ''
        if base_authority != 'login.microsoftonline.com':
            authority_info = f' using authority {base_authority}'
        logger.info('Initialized Azure OAuth provider for client %s with tenant %s%s%s', client_id, tenant_id, f' and identifier_uri {self.identifier_uri}' if self.identifier_uri else '', authority_info)

    async def authorize(self, client: OAuthClientInformationFull, params: AuthorizationParams) -> str:
        params_to_use = params
        if hasattr(params, 'resource'):
            original_resource = getattr(params, 'resource', None)
            if original_resource is not None:
                params_to_use = params.model_copy(update={'resource': None})
                if original_resource:
                    logger.debug("Filtering out 'resource' parameter '%s' for Azure AD v2.0 (use scopes instead)", original_resource)
