    def __init__(self, claim_name: str):
        self.claim_name = claim_name

    async def __aenter__(self) -> str:
        token = get_access_token()
        if token is None:
            raise RuntimeError(f"No access token available. Cannot extract claim '{self.claim_name}'.")
        value = token.claims.get(self.claim_name)
        if value is None:
            raise RuntimeError(f"Claim '{self.claim_name}' not found in access token. Available claims: {list(token.claims.keys())}")
        return str(value)

    async def __aexit__(self, exc_type: type[BaseException] | None, exc_value: BaseException | None, traceback: TracebackType | None) -> None:
        pass

def get_http_request() -> Request:
    request = None
    with contextlib.suppress(LookupError):
        request = request_ctx.get().request
    if request is None:
        request = _current_http_request.get()
    if request is None:
        snapshot = _get_task_snapshot_sync()
        task_headers = snapshot.http_headers if snapshot else None
        if task_headers:
            request = Request({'type': 'http', 'http_version': '1.1', 'method': 'POST', 'scheme': 'http', 'path': '/', 'raw_path': b'/', 'query_string': b'', 'headers': [(name.encode('latin-1'), value.encode('latin-1')) for name, value in task_headers.items()], 'client': None, 'server': None, 'root_path': ''})
    if request is None:
        raise RuntimeError('No active HTTP request found.')
    return request

