# --- helper: fastmcp.server.elicitation.validate_elicitation_json_schema ---
def validate_elicitation_json_schema(schema: dict[str, Any]) -> None:
    ALLOWED_TYPES = {'string', 'number', 'integer', 'boolean'}
    if schema.get('type') != 'object':
        raise TypeError(f"Elicitation schema must be an object schema, got type '{schema.get('type')}'. Elicitation schemas are limited to flat objects with primitive properties only.")
    properties = schema.get('properties', {})
    for prop_name, prop_schema in properties.items():
        prop_type = prop_schema.get('type')
        if isinstance(prop_type, list):
            if 'null' in prop_type:
                prop_type = [t for t in prop_type if t != 'null']
                if len(prop_type) == 1:
                    prop_type = prop_type[0]
        elif prop_schema.get('nullable', False):
            continue
        if 'const' in prop_schema:
            continue
        if 'enum' in prop_schema:
            continue
        if '$ref' in prop_schema:
            ref_path = prop_schema['$ref']
            if ref_path.startswith('#/$defs/'):
                def_name = ref_path[8:]
                ref_def = schema.get('$defs', {}).get(def_name, {})
                if 'enum' in ref_def:
                    continue
                ref_type = ref_def.get('type')
                if ref_type in ALLOWED_TYPES:
                    continue
            raise TypeError(f"Elicitation schema field '{prop_name}' contains a reference '{ref_path}' that could not be validated. Only references to enum types or primitive types are allowed.")
        if 'oneOf' in prop_schema or 'anyOf' in prop_schema:
            union_schemas = prop_schema.get('oneOf', []) + prop_schema.get('anyOf', [])
            for union_schema in union_schemas:
                if 'const' in union_schema or 'enum' in union_schema:
                    continue
                union_type = union_schema.get('type')
                if union_type not in ALLOWED_TYPES:
                    raise TypeError(f"Elicitation schema field '{prop_name}' has union type '{union_type}' which is not a primitive type. Only {ALLOWED_TYPES} are allowed in elicitation schemas.")
            continue
        if prop_type == 'array':
            items_schema = prop_schema.get('items', {})
            if items_schema.get('type') == 'object':
                raise TypeError(f"Elicitation schema field '{prop_name}' is an array of objects, but arrays of objects are not allowed. Elicitation schemas must be flat objects with primitive properties only.")
            if 'enum' in items_schema:
                continue
            if 'oneOf' in items_schema or 'anyOf' in items_schema:
                union_schemas = items_schema.get('oneOf', []) + items_schema.get('anyOf', [])
                if union_schemas and all(('const' in s for s in union_schemas)):
                    continue
            raise TypeError(f"Elicitation schema field '{prop_name}' is an array, but arrays are only allowed when items are enums (for multi-select). Only enum arrays are supported in elicitation schemas.")
        if prop_type == 'object':
            raise TypeError(f"Elicitation schema field '{prop_name}' is an object, but nested objects are not allowed. Elicitation schemas must be flat objects with primitive properties only.")
        if prop_type not in ALLOWED_TYPES:
            raise TypeError(f"Elicitation schema field '{prop_name}' has type '{prop_type}' which is not a primitive type. Only {ALLOWED_TYPES} are allowed in elicitation schemas.")

