def parse_elicit_response_type(response_type: Any, response_title: str | None=None, response_description: str | None=None) -> ElicitConfig:
    has_response_metadata = response_title is not None or response_description is not None
    if response_type is None:
        if has_response_metadata:
            raise TypeError('response_title and response_description are not supported when response_type is None, because the elicitation schema has no fields to label.')
        return ElicitConfig(schema={'type': 'object', 'properties': {}}, response_type=None, is_raw=False)
    if isinstance(response_type, dict):
        config = _parse_dict_syntax(response_type)
    elif isinstance(response_type, list):
        config = _parse_list_syntax(response_type)
    elif get_origin(response_type) is list:
        config = _parse_generic_list(response_type)
    elif _is_scalar_type(response_type):
        config = _parse_scalar_type(response_type)
    else:
        if has_response_metadata:
            raise TypeError('response_title and response_description are only supported when response_type is a scalar, Literal, Enum, or the dict/list shorthand forms. For BaseModel or dataclass response types, use Field(title=..., description=...) on the individual fields.')
        return ElicitConfig(schema=get_elicitation_schema(response_type), response_type=response_type, is_raw=False)
    if has_response_metadata:
        _apply_value_metadata(config.schema, response_title, response_description)
    return config

# --- helper: fastmcp.server.elicitation.ElicitConfig ---
@dataclass
class ElicitConfig:
    schema: dict[str, Any]
    response_type: type | None
    is_raw: bool

# --- helper: fastmcp.server.elicitation._apply_value_metadata ---
def _apply_value_metadata(schema: dict[str, Any], title: str | None, description: str | None) -> None:
    value_schema = schema.get('properties', {}).get('value')
    if value_schema is None:
        return
    if title is not None:
        value_schema['title'] = title
    if description is not None:
        value_schema['description'] = description

# --- helper: fastmcp.server.elicitation._is_scalar_type ---
def _is_scalar_type(response_type: Any) -> bool:
    return response_type in {bool, int, float, str} or get_origin(response_type) is Literal or (isinstance(response_type, type) and issubclass(response_type, Enum))

# --- helper: fastmcp.server.elicitation._parse_dict_syntax ---
def _parse_dict_syntax(d: dict[str, Any]) -> ElicitConfig:
    if not d:
        raise ValueError('Dict response_type cannot be empty.')
    enum_schema = _dict_to_enum_schema(d, multi_select=False)
    return ElicitConfig(schema={'type': 'object', 'properties': {'value': enum_schema}, 'required': ['value']}, response_type=None, is_raw=True)

# --- helper: fastmcp.server.elicitation._parse_generic_list ---
def _parse_generic_list(response_type: Any) -> ElicitConfig:
    wrapped = ScalarElicitationType[response_type]
    return ElicitConfig(schema=get_elicitation_schema(wrapped), response_type=wrapped, is_raw=False)

# --- helper: fastmcp.server.elicitation._parse_list_syntax ---
def _parse_list_syntax(lst: list[Any]) -> ElicitConfig:
    if len(lst) == 1 and isinstance(lst[0], list) and lst[0] and all((isinstance(item, str) for item in lst[0])):
        return ElicitConfig(schema={'type': 'object', 'properties': {'value': {'type': 'array', 'items': {'enum': lst[0]}}}, 'required': ['value']}, response_type=None, is_raw=True)
    if len(lst) == 1 and isinstance(lst[0], dict) and lst[0]:
        enum_schema = _dict_to_enum_schema(lst[0], multi_select=True)
        return ElicitConfig(schema={'type': 'object', 'properties': {'value': {'type': 'array', 'items': enum_schema}}, 'required': ['value']}, response_type=None, is_raw=True)
    if lst and all((isinstance(item, str) for item in lst)):
        choice_literal: type[Any] = cast(type[Any], Literal[tuple(lst)])
        wrapped = ScalarElicitationType[choice_literal]
        return ElicitConfig(schema=get_elicitation_schema(wrapped), response_type=wrapped, is_raw=False)
    raise ValueError(f'Invalid list response_type format. Received: {lst}')

# --- helper: fastmcp.server.elicitation._parse_scalar_type ---
def _parse_scalar_type(response_type: Any) -> ElicitConfig:
    wrapped = ScalarElicitationType[response_type]
    return ElicitConfig(schema=get_elicitation_schema(wrapped), response_type=wrapped, is_raw=False)

# --- helper: fastmcp.server.elicitation.get_elicitation_schema ---
def get_elicitation_schema(response_type: type[T]) -> dict[str, Any]:
    schema = get_cached_typeadapter(response_type).json_schema(schema_generator=ElicitationJsonSchema)
    schema = compress_schema(schema)
    validate_elicitation_json_schema(schema)
    return schema

