def create_streamable_http_app(server: FastMCP[LifespanResultT], streamable_http_path: str, event_store: EventStore | None=None, retry_interval: int | None=None, auth: AuthProvider | None=None, json_response: bool=False, stateless_http: bool=False, debug: bool=False, routes: list[BaseRoute] | None=None, middleware: list[Middleware] | None=None) -> StarletteWithLifespan:
    server_routes: list[BaseRoute] = []
    server_middleware: list[Middleware] = []
    streamable_http_app = StreamableHTTPASGIApp(None)
    if auth:
        auth_middleware = auth.get_middleware()
        auth_routes = auth.get_routes(mcp_path=streamable_http_path)
        server_routes.extend(auth_routes)
        server_middleware.extend(auth_middleware)
        resource_url = auth._get_resource_url(streamable_http_path)
        resource_metadata_url = build_resource_metadata_url(resource_url) if resource_url else None
        http_methods = ['POST', 'DELETE'] if stateless_http else ['GET', 'POST', 'DELETE']
        server_routes.append(Route(streamable_http_path, endpoint=RequireAuthMiddleware(streamable_http_app, auth.required_scopes, resource_metadata_url), methods=http_methods))
    else:
        http_methods = ['POST', 'DELETE'] if stateless_http else None
        server_routes.append(Route(streamable_http_path, endpoint=streamable_http_app, methods=http_methods))
    if routes:
        server_routes.extend(routes)
    server_routes.extend(server._get_additional_http_routes())
    if middleware:
        server_middleware.extend(middleware)

    @asynccontextmanager
    async def lifespan(app: Starlette) -> AsyncGenerator[None, None]:
        streamable_http_app.session_manager = StreamableHTTPSessionManager(app=server._mcp_server, event_store=event_store, retry_interval=retry_interval, json_response=json_response, stateless=stateless_http)
        async with server._lifespan_manager(), streamable_http_app.session_manager.run():
            yield
    app = create_base_app(routes=server_routes, middleware=server_middleware, debug=debug, lifespan=lifespan)
    app.state.fastmcp_server = server
    app.state.path = streamable_http_path
    app.state.transport_type = 'streamable-http'
    return app

