class StreamableHTTPASGIApp:

    def __init__(self, session_manager: StreamableHTTPSessionManager | None):
        self.session_manager = session_manager

    async def __call__(self, scope: Scope, receive: Receive, send: Send) -> None:
        try:
            if self.session_manager is None:
                raise RuntimeError('Task group is not initialized. Make sure to use run().')
            await self.session_manager.handle_request(scope, receive, send)
        except RuntimeError as e:
            if str(e) == 'Task group is not initialized. Make sure to use run().':
                logger.error(f'Original RuntimeError from mcp library: {e}', exc_info=True)
                new_error_message = "FastMCP's StreamableHTTPSessionManager task group was not initialized. This commonly occurs when the FastMCP application's lifespan is not passed to the parent ASGI application (e.g., FastAPI or Starlette). Please ensure you are setting `lifespan=mcp_app.lifespan` in your parent app's constructor, where `mcp_app` is the application instance returned by `fastmcp_instance.http_app()`. \\nFor more details, see the FastMCP ASGI integration documentation: https://gofastmcp.com/deployment/asgi"
                raise RuntimeError(f'{new_error_message}\\nOriginal error: {e}') from e
            else:
                raise

