class RetryMiddleware(Middleware):

    def __init__(self, max_retries: int=3, base_delay: float=1.0, max_delay: float=60.0, backoff_multiplier: float=2.0, retry_exceptions: tuple[type[Exception], ...]=(ConnectionError, TimeoutError), logger: logging.Logger | None=None):
        self.max_retries = max_retries
        self.base_delay = base_delay
        self.max_delay = max_delay
        self.backoff_multiplier = backoff_multiplier
        self.retry_exceptions = retry_exceptions
        self.logger = logger or logging.getLogger('fastmcp.retry')

    def _should_retry(self, error: Exception) -> bool:
        if isinstance(error, self.retry_exceptions):
            return True
        cause = error.__cause__
        return cause is not None and isinstance(cause, self.retry_exceptions)

    def _calculate_delay(self, attempt: int) -> float:
        delay = self.base_delay * self.backoff_multiplier ** attempt
        return min(delay, self.max_delay)

    async def on_request(self, context: MiddlewareContext, call_next: CallNext) -> Any:
        last_error = None
        for attempt in range(self.max_retries + 1):
            try:
                return await call_next(context)
            except Exception as error:
                last_error = error
                if attempt == self.max_retries or not self._should_retry(error):
                    break
                delay = self._calculate_delay(attempt)
                self.logger.warning(f'Request {context.method} failed (attempt {attempt + 1}/{self.max_retries + 1}): {type(error).__name__}: {error!s}. Retrying in {delay:.1f}s...')
                await anyio.sleep(delay)
        if last_error:
            raise last_error

