# Middleware that short-circuits the chain based on context
class ShortCircuitMiddleware(Middleware):
    def __call__(self, context: dict, call_next: Callable[[dict], Any]) -> Any:
        if context.get("authenticated") is False:
            return {"status": 401, "error": "unauthenticated"}
        return call_next(context)

