    return {"status": 200, "user": ctx.get("user")}

wrapper = make_middleware_wrapper(middleware=ShortCircuitMiddleware(), call_next=handler)

print(wrapper({"authenticated": False}))
print(wrapper({"authenticated": True, "user": "alice"}))

