def parse_hashed_backend_name(name: str) -> tuple[str, str] | None:
    if len(name) <= HASH_LENGTH + 1:
        return None
    prefix = name[:HASH_LENGTH]
    if name[HASH_LENGTH] != '_':
        return None
    if not all((c in '0123456789abcdef' for c in prefix)):
        return None
    return (prefix, name[HASH_LENGTH + 1:])

def parse_hashed_resource_uri(uri: str) -> str | None:
    prefix = 'ui://prefab/tool/'
    suffix = '/renderer.html'
    if not uri.startswith(prefix) or not uri.endswith(suffix):
        return None
    h = uri[len(prefix):-len(suffix)]
    if len(h) != HASH_LENGTH or not all((c in '0123456789abcdef' for c in h)):
        return None
    return h

def dedupe_with_versions(components: Sequence[C], key_fn: Callable[[C], str]) -> list[C]:
    by_key: dict[str, list[C]] = {}
    for c in components:
        by_key.setdefault(key_fn(c), []).append(c)
    result: list[C] = []
    for versions in by_key.values():
        highest: C = cast(C, max(versions, key=version_sort_key))
        if any((c.version is not None for c in versions)):
            all_versions = sorted([c.version for c in versions if c.version is not None], key=parse_version_key, reverse=True)
            meta = highest.meta or {}
            highest = highest.model_copy(update={'meta': {**meta, 'fastmcp': {**meta.get('fastmcp', {}), 'versions': all_versions}}})
        result.append(highest)
    return result

# --- helper: fastmcp.utilities.versions.parse_version_key ---
def parse_version_key(version: str | None) -> VersionKey:
    return VersionKey(version)

# --- helper: fastmcp.utilities.versions.version_sort_key ---
def version_sort_key(component: FastMCPComponent) -> VersionKey:
    return parse_version_key(component.version)

class ResourceDecoratorMixin:

    def add_resource(self: LocalProvider, resource: Resource | ResourceTemplate | Callable[..., Any]) -> Resource | ResourceTemplate:
        enabled = True
        if not isinstance(resource, (Resource, ResourceTemplate)):
            from fastmcp.decorators import get_fastmcp_meta
            from fastmcp.resources.function_resource import ResourceMeta
            from fastmcp.server.dependencies import without_injected_parameters
            meta = get_fastmcp_meta(resource)
            if meta is not None and isinstance(meta, ResourceMeta):
                resolved_task = meta.task if meta.task is not None else False
                enabled = meta.enabled
                has_uri_params = '{' in meta.uri and '}' in meta.uri
                wrapper_fn = without_injected_parameters(resource)
                has_func_params = bool(inspect.signature(wrapper_fn).parameters)
                if has_uri_params or has_func_params:
                    resource = ResourceTemplate.from_function(fn=resource, uri_template=meta.uri, name=meta.name, version=meta.version, title=meta.title, description=meta.description, icons=meta.icons, mime_type=meta.mime_type, tags=meta.tags, annotations=meta.annotations, meta=meta.meta, task=resolved_task, auth=meta.auth)
                else:
                    resource = Resource.from_function(fn=resource, uri=meta.uri, name=meta.name, version=meta.version, title=meta.title, description=meta.description, icons=meta.icons, mime_type=meta.mime_type, tags=meta.tags, annotations=meta.annotations, meta=meta.meta, task=resolved_task, auth=meta.auth)
            else:
                raise TypeError(f"Expected Resource, ResourceTemplate, or @resource-decorated function, got {type(resource).__name__}. Use @resource('uri') decorator or pass a Resource/ResourceTemplate instance.")
        self._add_component(resource)
        if not enabled:
            self.disable(keys={resource.key})
        return resource

    def add_template(self: LocalProvider, template: ResourceTemplate) -> ResourceTemplate:
        return self._add_component(template)

    def resource(self: LocalProvider, uri: str, *, name: str | None=None, version: str | int | None=None, title: str | None=None, description: str | None=None, icons: list[mcp.types.Icon] | None=None, mime_type: str | None=None, tags: set[str] | None=None, enabled: bool=True, annotations: Annotations | dict[str, Any] | None=None, meta: dict[str, Any] | None=None, task: bool | TaskConfig | None=None, auth: AuthCheck | list[AuthCheck] | None=None) -> Callable[[F], F]:
        if isinstance(annotations, dict):
            annotations = Annotations(**annotations)
        if inspect.isroutine(uri):
            raise TypeError("The @resource decorator was used incorrectly. It requires a URI as the first argument. Use @resource('uri') instead of @resource")
        resolved_task: bool | TaskConfig = task if task is not None else False

        def decorator(fn: AnyFunction) -> Any:
            try:
                params = list(inspect.signature(fn).parameters.keys())
            except (ValueError, TypeError):
                params = []
            if params and params[0] in ('self', 'cls'):
                fn_name = getattr(fn, '__name__', 'function')
                raise TypeError(f"The function '{fn_name}' has '{params[0]}' as its first parameter. Use the standalone @resource decorator and register the bound method:\n\n    from fastmcp.resources import resource\n\n    class MyClass:\n        @resource('{uri}')\n        def {fn_name}(...):\n            ...\n\n    obj = MyClass()\n    mcp.add_resource(obj.{fn_name})\n\nSee https://gofastmcp.com/servers/resources#using-with-methods")
            if fastmcp.settings.decorator_mode == 'object':
                create_resource = standalone_resource(uri, name=name, version=version, title=title, description=description, icons=icons, mime_type=mime_type, tags=tags, annotations=annotations, meta=meta, task=resolved_task, auth=auth)
                obj = create_resource(fn)
                assert isinstance(obj, (Resource, ResourceTemplate))
                if isinstance(obj, ResourceTemplate):
                    self.add_template(obj)
                    if not enabled:
                        self.disable(keys={obj.key})
                else:
                    self.add_resource(obj)
                    if not enabled:
                        self.disable(keys={obj.key})
                return obj
            else:
                from fastmcp.resources.function_resource import ResourceMeta
                metadata = ResourceMeta(uri=uri, name=name, version=version, title=title, description=description, icons=icons, tags=tags, mime_type=mime_type, annotations=annotations, meta=meta, task=task, auth=auth, enabled=enabled)
                target = fn.__func__ if hasattr(fn, '__func__') else fn
                target.__fastmcp__ = metadata
                self.add_resource(fn)
                return fn
        return decorator

