class OpenAPIResourceTemplate(ResourceTemplate):
    task_config: TaskConfig = TaskConfig(mode='forbidden')

    def __init__(self, client: httpx.AsyncClient, route: HTTPRoute, director: RequestDirector, uri_template: str, name: str, description: str, parameters: dict[str, Any], tags: set[str] | None=None, mime_type: str=_DEFAULT_MIME_TYPE):
        super().__init__(uri_template=uri_template, name=name, description=description, parameters=parameters, tags=tags or set(), mime_type=mime_type)
        self._client = client
        self._route = route
        self._director = director

    def __repr__(self) -> str:
        return f'OpenAPIResourceTemplate(name={self.name!r}, uri_template={self.uri_template!r}, path={self._route.path})'

    async def create_resource(self, uri: str, params: dict[str, Any], context: Context | None=None) -> Resource:
        uri_parts = [f'{key}={value}' for key, value in params.items()]
        return OpenAPIResource(client=self._client, route=self._route, director=self._director, uri=uri, name=f"{self.name}-{'-'.join(uri_parts)}", description=self.description or f'Resource for {self._route.path}', mime_type=self.mime_type, tags=set(self._route.tags or []))

# --- helper: fastmcp.server.providers.openapi.components.OpenAPIResource ---
class OpenAPIResource(Resource):
    task_config: TaskConfig = TaskConfig(mode='forbidden')

    def __init__(self, client: httpx.AsyncClient, route: HTTPRoute, director: RequestDirector, uri: str, name: str, description: str, mime_type: str='application/json', tags: set[str] | None=None):
        super().__init__(uri=AnyUrl(uri), name=name, description=description, mime_type=mime_type, tags=tags or set())
        self._client = client
        self._route = route
        self._director = director

    def __repr__(self) -> str:
        return f'OpenAPIResource(name={self.name!r}, uri={self.uri!r}, path={self._route.path})'

    async def read(self) -> ResourceResult:
        try:
            path = self._route.path
            resource_uri = str(self.uri)
            if '{' in path and '}' in path:
                parts = resource_uri.split('/')
                if len(parts) > 1:
                    path_params = {}
                    param_matches = re.findall('\\{([^}]+)\\}', path)
                    if param_matches:
                        param_matches.sort(reverse=True)
                        expected_param_count = len(parts) - 1
                        for i, param_name in enumerate(param_matches):
                            if i < expected_param_count:
                                param_value = parts[-1 - i]
                                path_params[param_name] = param_value
                    for param_name, param_value in path_params.items():
                        path = path.replace(f'{{{param_name}}}', str(param_value))
            headers: dict[str, str] = {}
            if self._client.headers:
                headers.update(self._client.headers)
            mcp_headers = get_http_headers()
            if mcp_headers:
                headers.update(mcp_headers)
            response = await self._client.request(method=self._route.method, url=path, headers=headers)
            response.raise_for_status()
            content_type = response.headers.get('content-type', '').lower()
            if 'application/json' in content_type:
                result = response.json()
                return ResourceResult(contents=[ResourceContent(content=json.dumps(result), mime_type='application/json')])
            elif any((ct in content_type for ct in ['text/', 'application/xml'])):
                return ResourceResult(contents=[ResourceContent(content=response.text, mime_type=self.mime_type)])
            else:
                return ResourceResult(contents=[ResourceContent(content=response.content, mime_type=self.mime_type)])
        except httpx.HTTPStatusError as e:
            error_message = f'HTTP error {e.response.status_code}: {e.response.reason_phrase}'
            try:
                error_data = e.response.json()
                error_message += f' - {error_data}'
            except (json.JSONDecodeError, ValueError):
                if e.response.text:
                    error_message += f' - {e.response.text}'
            raise ValueError(error_message) from e
        except httpx.TimeoutException as e:
            raise ValueError(f'HTTP request timed out ({type(e).__name__})') from e
        except httpx.RequestError as e:
            raise ValueError(f'Request error ({type(e).__name__}): {e!s}') from e

def parse_frontmatter(content: str) -> tuple[dict[str, Any], str]:
    if not content.startswith('---'):
        return ({}, content)
    end_match = re.search('\\n---\\s*\\n', content[3:])
    if not end_match:
        return ({}, content)
    frontmatter_text = content[3:3 + end_match.start()]
    remaining = content[3 + end_match.end():]
    frontmatter: dict[str, Any] = {}
    for line in frontmatter_text.strip().split('\n'):
        if ':' in line:
            key, _, value = line.partition(':')
            key = key.strip()
            value = value.strip()
            if value.startswith('"') and value.endswith('"') or (value.startswith("'") and value.endswith("'")):
                value = value[1:-1]
            if value.startswith('[') and value.endswith(']'):
                items = value[1:-1].split(',')
                value = [item.strip().strip('"\'') for item in items if item.strip()]
            frontmatter[key] = value
    return (frontmatter, remaining)

