from types import SimpleNamespace
import fastmcp.server.providers.proxy as proxy

# Prepare a LogMessage instance in a way that works whether LogMessage is a class or not.
# Try to use the real LogMessage constructor if available; otherwise craft a compatible object.
try:
    LogMessage = getattr(proxy, "LogMessage")
    # Try common constructor patterns seen in many libraries.
    try:
        # pattern: LogMessage(message: str)
        msg = LogMessage("Player joined the proxy")
    except TypeError:
        try:
            # pattern: LogMessage(text: str)
            msg = LogMessage(text="Player joined the proxy")
        except TypeError:
            try:
                # pattern: dataclass-like with fields (message, level)
                msg = LogMessage(message="Player joined the proxy", level="INFO")
            except TypeError:
                # fallback: create a plain instance and set attributes
                msg = LogMessage()
                if not hasattr(msg, "message"):
                    setattr(msg, "message", "Player joined the proxy")
except Exception:
    # If the real LogMessage class isn't importable or instantiable, create a lightweight compatible object.
    LogMessage = SimpleNamespace
    msg = LogMessage(message="Player joined the proxy", level="INFO")

# Call the API exactly as named.
proxy.default_proxy_log_handler(msg)
print("default_proxy_log_handler called")

