        arguments = [PromptArgument(name=arg.name, description=arg.description, required=arg.required or False) for arg in mcp_prompt.arguments or []]
        return cls(client_factory=client_factory, name=mcp_prompt.name, title=mcp_prompt.title, description=mcp_prompt.description, arguments=arguments, icons=mcp_prompt.icons, meta=mcp_prompt.meta, tags=get_fastmcp_metadata(mcp_prompt.meta).get('tags', []), task_config=TaskConfig(mode='forbidden'))

    async def render(self, arguments: dict[str, Any]) -> PromptResult:
        backend_name = self._backend_name or self.name
        with client_span(f'prompts/get {backend_name}', 'prompts/get', backend_name) as span:
            span.set_attribute('fastmcp.provider.type', 'ProxyProvider')
            client = await self._get_client()
            async with client:
                result = await client.get_prompt(backend_name, arguments)
            messages = [Message(content=m.content, role=m.role) for m in result.messages]
            return PromptResult(messages=messages, description=result.description, meta=result.meta)

    def get_span_attributes(self) -> dict[str, Any]:
