async def execute_tools(tool_calls: list[ToolUseContent], tool_map: dict[str, SamplingTool], mask_error_details: bool=False, tool_concurrency: int | None=None) -> list[ToolResultContent]:
    if tool_concurrency is not None and tool_concurrency < 0:
        raise ValueError(f'tool_concurrency must be None, 0 (unlimited), or a positive integer, got {tool_concurrency}')

    async def _execute_single_tool(tool_use: ToolUseContent) -> ToolResultContent:
        tool = tool_map.get(tool_use.name)
        if tool is None:
            return ToolResultContent(type='tool_result', toolUseId=tool_use.id, content=[TextContent(type='text', text=f"Error: Unknown tool '{tool_use.name}'")], isError=True)
        try:
            result_value = await tool.run(tool_use.input)
            return ToolResultContent(type='tool_result', toolUseId=tool_use.id, content=[TextContent(type='text', text=str(result_value))])
        except ToolError as e:
            logger.exception(f"Error calling sampling tool '{tool_use.name}'")
            return ToolResultContent(type='tool_result', toolUseId=tool_use.id, content=[TextContent(type='text', text=str(e))], isError=True)
        except Exception as e:
            logger.exception(f"Error calling sampling tool '{tool_use.name}'")
            if mask_error_details:
                error_text = f"Error executing tool '{tool_use.name}'"
            else:
                error_text = f"Error executing tool '{tool_use.name}': {e}"
            return ToolResultContent(type='tool_result', toolUseId=tool_use.id, content=[TextContent(type='text', text=error_text)], isError=True)
    requires_sequential = any((tool.sequential for tool_use in tool_calls if (tool := tool_map.get(tool_use.name)) is not None))
    if tool_concurrency is None or requires_sequential:
        tool_results: list[ToolResultContent] = []
        for tool_use in tool_calls:
            result = await _execute_single_tool(tool_use)
            tool_results.append(result)
        return tool_results
    if tool_concurrency == 0:
        return await gather(*[_execute_single_tool(tc) for tc in tool_calls])
    else:
        semaphore = anyio.Semaphore(tool_concurrency)

        async def bounded_execute(tool_use: ToolUseContent) -> ToolResultContent:
            async with semaphore:
                return await _execute_single_tool(tool_use)
        return await gather(*[bounded_execute(tc) for tc in tool_calls])

def prepare_messages(messages: str | Sequence[str | SamplingMessage]) -> list[SamplingMessage]:
    if isinstance(messages, str):
        return [SamplingMessage(content=TextContent(text=messages, type='text'), role='user')]
    else:
        return [SamplingMessage(content=TextContent(text=m, type='text'), role='user') if isinstance(m, str) else m for m in messages]

class ProxyTemplate(ResourceTemplate):
    task_config: TaskConfig = TaskConfig(mode='forbidden')
    _backend_uri_template: str | None = None

    def __init__(self, client_factory: ClientFactoryT, **kwargs: Any):
        super().__init__(**kwargs)
        self._client_factory = client_factory

    async def _get_client(self) -> Client:
        client = self._client_factory()
        if inspect.isawaitable(client):
            client = cast(Client, await client)
        return client

    def model_copy(self, **kwargs: Any) -> ProxyTemplate:
        update = kwargs.get('update', {})
        if 'uri_template' in update and self._backend_uri_template is None:
            update = {**update, '_backend_uri_template': self.uri_template}
            kwargs['update'] = update
        return super().model_copy(**kwargs)

    @classmethod
    def from_mcp_template(cls, client_factory: ClientFactoryT, mcp_template: mcp.types.ResourceTemplate) -> ProxyTemplate:
        return cls(client_factory=client_factory, uri_template=mcp_template.uriTemplate, name=mcp_template.name, title=mcp_template.title, description=mcp_template.description, mime_type=mcp_template.mimeType or 'text/plain', icons=mcp_template.icons, parameters={}, meta=mcp_template.meta, tags=get_fastmcp_metadata(mcp_template.meta).get('tags', []), task_config=TaskConfig(mode='forbidden'))

    async def create_resource(self, uri: str, params: dict[str, Any], context: Context | None=None) -> ProxyResource:
        backend_template = self._backend_uri_template or self.uri_template
        parameterized_uri = backend_template.format(**{k: quote(v, safe='') for k, v in params.items()})
        client = await self._get_client()
        async with client:
            result = await client.read_resource(parameterized_uri)
        if not result:
            raise ResourceError(f'Remote server returned empty content for {parameterized_uri}')
        contents: list[ResourceContent] = []
        for item in result:
            if isinstance(item, TextResourceContents):
                contents.append(ResourceContent(content=item.text, mime_type=item.mimeType, meta=item.meta))
            elif isinstance(item, BlobResourceContents):
                contents.append(ResourceContent(content=base64.b64decode(item.blob), mime_type=item.mimeType, meta=item.meta))
            else:
                raise ResourceError(f'Unsupported content type: {type(item)}')
        cached_content = ResourceResult(contents=contents)
        return ProxyResource(client_factory=self._client_factory, uri=parameterized_uri, name=self.name, title=self.title, description=self.description, mime_type=result[0].mimeType, icons=self.icons, meta=self.meta, tags=get_fastmcp_metadata(self.meta).get('tags', []), _cached_content=cached_content)

    def get_span_attributes(self) -> dict[str, Any]:
        return super().get_span_attributes() | {'fastmcp.provider.type': 'ProxyProvider', 'fastmcp.proxy.backend_uri_template': self._backend_uri_template}

# --- helper: fastmcp.server.providers.proxy.ProxyResource ---
class ProxyResource(Resource):
    task_config: TaskConfig = TaskConfig(mode='forbidden')
    _cached_content: ResourceResult | None = None
    _backend_uri: str | None = None

    def __init__(self, client_factory: ClientFactoryT, *, _cached_content: ResourceResult | None=None, **kwargs):
        super().__init__(**kwargs)
        self._client_factory = client_factory
        self._cached_content = _cached_content

    async def _get_client(self) -> Client:
        client = self._client_factory()
        if inspect.isawaitable(client):
            client = cast(Client, await client)
        return client

    def model_copy(self, **kwargs: Any) -> ProxyResource:
        update = kwargs.get('update', {})
        if 'uri' in update and self._backend_uri is None:
            update = {**update, '_backend_uri': str(self.uri)}
            kwargs['update'] = update
        return super().model_copy(**kwargs)

    @classmethod
    def from_mcp_resource(cls, client_factory: ClientFactoryT, mcp_resource: mcp.types.Resource) -> ProxyResource:
        return cls(client_factory=client_factory, uri=mcp_resource.uri, name=mcp_resource.name, title=mcp_resource.title, description=mcp_resource.description, mime_type=mcp_resource.mimeType or 'text/plain', icons=mcp_resource.icons, meta=mcp_resource.meta, tags=get_fastmcp_metadata(mcp_resource.meta).get('tags', []), task_config=TaskConfig(mode='forbidden'))

    async def read(self) -> ResourceResult:
        if self._cached_content is not None:
            return self._cached_content
        backend_uri = self._backend_uri or str(self.uri)
        with client_span(f'resources/read {backend_uri}', 'resources/read', backend_uri, resource_uri=backend_uri) as span:
            span.set_attribute('fastmcp.provider.type', 'ProxyProvider')
            client = await self._get_client()
            async with client:
                result = await client.read_resource(backend_uri)
            if not result:
                raise ResourceError(f'Remote server returned empty content for {backend_uri}')
            contents: list[ResourceContent] = []
            for item in result:
                if isinstance(item, TextResourceContents):
                    contents.append(ResourceContent(content=item.text, mime_type=item.mimeType, meta=item.meta))
                elif isinstance(item, BlobResourceContents):
                    contents.append(ResourceContent(content=base64.b64decode(item.blob), mime_type=item.mimeType, meta=item.meta))
                else:
                    raise ResourceError(f'Unsupported content type: {type(item)}')
            return ResourceResult(contents=contents)

    def get_span_attributes(self) -> dict[str, Any]:
        return super().get_span_attributes() | {'fastmcp.provider.type': 'ProxyProvider', 'fastmcp.proxy.backend_uri': self._backend_uri}

def prepare_tools(tools: Sequence[SamplingTool | FunctionTool | TransformedTool | Callable[..., Any]] | None) -> list[SamplingTool] | None:
    if tools is None:
        return None
    sampling_tools: list[SamplingTool] = []
    for t in tools:
        if isinstance(t, SamplingTool):
            sampling_tools.append(t)
        elif isinstance(t, (FunctionTool, TransformedTool)):
            sampling_tools.append(SamplingTool.from_callable_tool(t))
        elif callable(t):
            sampling_tools.append(SamplingTool.from_function(t))
        else:
            raise TypeError(f'Expected SamplingTool, FunctionTool, TransformedTool, or callable, got {type(t)}')
    return sampling_tools if sampling_tools else None

class SamplingTool(FastMCPBaseModel):
    name: str
    description: str | None = None
    parameters: dict[str, Any]
    fn: Callable[..., Any]
    sequential: bool = False
    model_config = ConfigDict(arbitrary_types_allowed=True)

    async def run(self, arguments: dict[str, Any] | None=None) -> Any:
        if arguments is None:
            arguments = {}
        result = self.fn(**arguments)
        if inspect.isawaitable(result):
            result = await result
        return result

    def _to_sdk_tool(self) -> SDKTool:
        return SDKTool(name=self.name, description=self.description, inputSchema=self.parameters)

    @classmethod
    def from_function(cls, fn: Callable[..., Any], *, name: str | None=None, description: str | None=None, sequential: bool=False) -> SamplingTool:
        parsed = ParsedFunction.from_function(fn, validate=True)
        if name is None and parsed.name == '<lambda>':
            raise ValueError('You must provide a name for lambda functions')
        return cls(name=name or parsed.name, description=description if description is not None else parsed.description, parameters=parsed.input_schema, fn=parsed.fn, sequential=sequential)

    @classmethod
    def from_callable_tool(cls, tool: FunctionTool | TransformedTool, *, name: str | None=None, description: str | None=None) -> SamplingTool:
        if not isinstance(tool, (FunctionTool, TransformedTool)):
            raise TypeError(f'Expected FunctionTool or TransformedTool, got {type(tool).__name__}. Only callable tools can be converted to SamplingTools.')

        async def wrapper(**kwargs: Any) -> Any:
            if tool.auth is not None:
                from fastmcp.server.context import _current_transport
                is_stdio = _current_transport.get() == 'stdio'
                if not is_stdio:
                    token = get_access_token()
                    ctx = AuthContext(token=token, component=tool)
                    if not await run_auth_checks(tool.auth, ctx):
                        raise AuthorizationError(f"Authorization failed for tool '{tool.name}': insufficient permissions")
            result = await tool.run(kwargs)
            if isinstance(result, ToolResult):
                if result.structured_content is not None:
                    if tool.output_schema and tool.output_schema.get('x-fastmcp-wrap-result'):
                        return result.structured_content.get('result')
                    else:
                        return result.structured_content
                if result.content and len(result.content) > 0:
                    first_content = result.content[0]
                    if isinstance(first_content, TextContent):
                        return first_content.text
            return result
        fn = wrapper
        return cls(name=name or tool.name, description=description or tool.description, parameters=tool.parameters, fn=fn)

def version_sort_key(component: FastMCPComponent) -> VersionKey:
    return parse_version_key(component.version)

# --- helper: fastmcp.utilities.versions.VersionKey ---
@total_ordering
class VersionKey:
    __slots__ = ('_is_none', '_is_pep440', '_parsed', '_raw')

    def __init__(self, version: str | None) -> None:
        self._raw = version
        self._is_none = version is None
        self._is_pep440 = False
        self._parsed: Version | str | None = None
        if version is not None:
            normalized = version.lstrip('v') if version.startswith('v') else version
            try:
                self._parsed = Version(normalized)
                self._is_pep440 = True
            except InvalidVersion:
                self._parsed = version

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, VersionKey):
            return NotImplemented
        if self._is_none and other._is_none:
            return True
        if self._is_none != other._is_none:
            return False
        if self._is_pep440 and other._is_pep440:
            return self._parsed == other._parsed
        if not self._is_pep440 and (not other._is_pep440):
            return self._parsed == other._parsed
        return False

    def __lt__(self, other: object) -> bool:
        if not isinstance(other, VersionKey):
            return NotImplemented
        if self._is_none and other._is_none:
            return False
        if self._is_none:
            return True
        if other._is_none:
            return False
        if self._is_pep440 and other._is_pep440:
            assert isinstance(self._parsed, Version)
            assert isinstance(other._parsed, Version)
            return self._parsed < other._parsed
        if not self._is_pep440 and (not other._is_pep440):
            assert isinstance(self._parsed, str)
            assert isinstance(other._parsed, str)
            return self._parsed < other._parsed
        return self._is_pep440

    def __repr__(self) -> str:
        return f'VersionKey({self._raw!r})'

# --- helper: fastmcp.utilities.versions.parse_version_key ---
def parse_version_key(version: str | None) -> VersionKey:
    return VersionKey(version)

