async def sample_impl(context: Context, messages: str | Sequence[str | SamplingMessage], *, system_prompt: str | None=None, temperature: float | None=None, max_tokens: int | None=None, model_preferences: ModelPreferences | str | list[str] | None=None, tools: Sequence[SamplingTool | FunctionTool | TransformedTool | Callable[..., Any]] | None=None, result_type: type[ResultT] | None=None, mask_error_details: bool | None=None, tool_concurrency: int | None=None) -> SamplingResult[ResultT]:
    max_iterations = 100
    sampling_tools = prepare_tools(tools)
    tool_choice: str | None = None
    if result_type is not None and result_type is not str:
        final_response_tool = create_final_response_tool(result_type)
        sampling_tools = list(sampling_tools) if sampling_tools else []
        sampling_tools.append(final_response_tool)
        tool_choice = 'required'
    current_messages: str | Sequence[str | SamplingMessage] = messages
    text_response_retries = 0
    consecutive_validation_failures = 0
    for _iteration in range(max_iterations):
        step = await sample_step_impl(context, messages=current_messages, system_prompt=system_prompt, temperature=temperature, max_tokens=max_tokens, model_preferences=model_preferences, tools=sampling_tools, tool_choice=tool_choice, mask_error_details=mask_error_details, tool_concurrency=tool_concurrency)
        had_final_response = False
        if result_type is not None and result_type is not str and step.is_tool_use:
            for tool_call in step.tool_calls:
                if tool_call.name == 'final_response':
                    had_final_response = True
                    type_adapter = get_cached_typeadapter(result_type)
                    input_data = tool_call.input
                    original_schema = compress_schema(type_adapter.json_schema(), prune_titles=True)
                    if original_schema.get('type') != 'object' and isinstance(input_data, dict) and ('value' in input_data):
                        input_data = input_data['value']
                    try:
                        validated_result = type_adapter.validate_python(input_data)
                        text = json.dumps(type_adapter.dump_python(validated_result, mode='json'))
                        return SamplingResult(text=text, result=validated_result, history=step.history)
                    except ValidationError as e:
                        consecutive_validation_failures += 1
                        if consecutive_validation_failures > _MAX_VALIDATION_RETRIES:
                            raise RuntimeError(f'Structured output validation failed {consecutive_validation_failures} consecutive times for type {result_type.__name__}: {e}') from e
                        step.history.append(SamplingMessage(role='user', content=[ToolResultContent(type='tool_result', toolUseId=tool_call.id, content=[TextContent(type='text', text=f'Validation error: {e}. Please try again with valid data.')], isError=True)]))
        if not had_final_response:
            consecutive_validation_failures = 0
        if not step.is_tool_use:
            if result_type is not None and result_type is not str:
                text_response_retries += 1
                if text_response_retries > _MAX_TEXT_RESPONSE_RETRIES:
                    raise RuntimeError(f'Expected structured output of type {result_type.__name__}, but the LLM returned a text response instead of calling the final_response tool ({text_response_retries} attempts).')
                step.history.append(SamplingMessage(role='user', content=TextContent(type='text', text='You must call the `final_response` tool to provide your answer. Do not respond with text — use the tool.')))
                current_messages = step.history
                continue
            return SamplingResult(text=step.text, result=cast(ResultT, step.text if step.text else ''), history=step.history)
        current_messages = step.history
        if result_type is None or result_type is str:
            tool_choice = None
    raise RuntimeError(f'Sampling exceeded maximum iterations ({max_iterations})')

# --- helper: fastmcp.server.sampling.run.SamplingResult ---
@dataclass
class SamplingResult(Generic[ResultT]):
    text: str | None
    result: ResultT
    history: list[SamplingMessage]

# --- helper: fastmcp.server.sampling.run.create_final_response_tool ---
def create_final_response_tool(result_type: type) -> SamplingTool:
    type_adapter = get_cached_typeadapter(result_type)
    schema = type_adapter.json_schema()
    schema = compress_schema(schema, prune_titles=True)
    if schema.get('type') != 'object':
        schema = {'type': 'object', 'properties': {'value': schema}, 'required': ['value']}

    def final_response(**kwargs: Any) -> dict[str, Any]:
        return kwargs
    return SamplingTool(name='final_response', description='Call this tool to provide your final response. Use this when you have completed the task and are ready to return the result.', parameters=schema, fn=final_response)

# --- helper: fastmcp.server.sampling.run.prepare_tools ---
def prepare_tools(tools: Sequence[SamplingTool | FunctionTool | TransformedTool | Callable[..., Any]] | None) -> list[SamplingTool] | None:
    if tools is None:
        return None
    sampling_tools: list[SamplingTool] = []
    for t in tools:
        if isinstance(t, SamplingTool):
            sampling_tools.append(t)
        elif isinstance(t, (FunctionTool, TransformedTool)):
            sampling_tools.append(SamplingTool.from_callable_tool(t))
        elif callable(t):
            sampling_tools.append(SamplingTool.from_function(t))
        else:
            raise TypeError(f'Expected SamplingTool, FunctionTool, TransformedTool, or callable, got {type(t)}')
    return sampling_tools if sampling_tools else None

# --- helper: fastmcp.server.sampling.run.sample_step_impl ---
async def sample_step_impl(context: Context, messages: str | Sequence[str | SamplingMessage], *, system_prompt: str | None=None, temperature: float | None=None, max_tokens: int | None=None, model_preferences: ModelPreferences | str | list[str] | None=None, tools: Sequence[SamplingTool | FunctionTool | TransformedTool | Callable[..., Any]] | None=None, tool_choice: ToolChoiceOption | str | None=None, auto_execute_tools: bool=True, mask_error_details: bool | None=None, tool_concurrency: int | None=None) -> SampleStep:
    current_messages = prepare_messages(messages)
    sampling_tools = prepare_tools(tools)
    sdk_tools: list[SDKTool] | None = [t._to_sdk_tool() for t in sampling_tools] if sampling_tools else None
    tool_map: dict[str, SamplingTool] = {t.name: t for t in sampling_tools} if sampling_tools else {}
    use_fallback = determine_handler_mode(context, bool(sampling_tools))
    effective_tool_choice: ToolChoice | None = None
    if tool_choice is not None:
        if tool_choice not in ('auto', 'required', 'none'):
            raise ValueError(f"Invalid tool_choice: {tool_choice!r}. Must be 'auto', 'required', or 'none'.")
        effective_tool_choice = ToolChoice(mode=cast(Literal['auto', 'required', 'none'], tool_choice))
    effective_max_tokens = max_tokens if max_tokens is not None else 512
    if use_fallback:
        response = await call_sampling_handler(context, current_messages, system_prompt=system_prompt, temperature=temperature, max_tokens=effective_max_tokens, model_preferences=model_preferences, sdk_tools=sdk_tools, tool_choice=effective_tool_choice)
    else:
        response = await context.session.create_message(messages=current_messages, system_prompt=system_prompt, temperature=temperature, max_tokens=effective_max_tokens, model_preferences=_parse_model_preferences(model_preferences), tools=sdk_tools, tool_choice=effective_tool_choice, related_request_id=context.request_id)
    is_tool_use_response = isinstance(response, CreateMessageResultWithTools) and response.stopReason == 'toolUse'
    current_messages.append(SamplingMessage(role='assistant', content=response.content))
    if not is_tool_use_response:
        return SampleStep(response=response, history=current_messages)
    if not auto_execute_tools:
        return SampleStep(response=response, history=current_messages)
    step_tool_calls = extract_tool_calls(response)
    if step_tool_calls:
        effective_mask = mask_error_details if mask_error_details is not None else settings.mask_error_details
        tool_results: list[ToolResultContent] = await execute_tools(step_tool_calls, tool_map, mask_error_details=effective_mask, tool_concurrency=tool_concurrency)
        if tool_results:
            current_messages.append(SamplingMessage(role='user', content=cast(list[SamplingMessageContentBlock], tool_results)))
    return SampleStep(response=response, history=current_messages)

@dataclass
class TaskMeta:
    ttl: int | None = None
    fn_key: str | None = None

@dataclass
class TaskConfig:
    mode: TaskMode = 'optional'
    poll_interval: timedelta = DEFAULT_POLL_INTERVAL

    @classmethod
    def from_bool(cls, value: bool) -> TaskConfig:
        return cls(mode='optional' if value else 'forbidden')

    def supports_tasks(self) -> bool:
        return self.mode != 'forbidden'

    def validate_function(self, fn: Callable[..., Any], name: str) -> None:
        if not self.supports_tasks():
            return
        from fastmcp.server.dependencies import require_docket
        require_docket(f"`task=True` on function '{name}'")
        fn_to_check = fn
        if not inspect.isroutine(fn) and (not isinstance(fn, functools.partial)) and callable(fn):
            fn_to_check = fn.__call__
        if isinstance(fn_to_check, staticmethod):
            fn_to_check = fn_to_check.__func__
        if not is_coroutine_function(fn_to_check):
            raise ValueError(f"'{name}' uses a sync function but has task execution enabled. Background tasks require async functions.")

def get_task_context() -> TaskContextInfo | None:
    from fastmcp.server.dependencies import is_docket_available
    if not is_docket_available():
        return None
    from docket.dependencies import current_execution
    try:
        execution = current_execution.get()
        key_parts = parse_task_key(execution.key)
        return TaskContextInfo(task_id=key_parts['client_task_id'], task_scope=key_parts['task_scope'])
    except LookupError:
        return None
    except (ValueError, KeyError):
        return None

