implementation:
def get_task_scope() -> str | None:
    from fastmcp.server.dependencies import get_access_token
    token = get_access_token()
    if token is None:
        return None
    sub = token.claims.get('sub') if token.claims else None
    if sub:
        return f'{token.client_id}|{sub}'
    return token.client_id

def get_task_session(session_id: str) -> ServerSession | None:
    ref = _task_sessions.get(session_id)
    if ref is None:
        return None
    session = ref()
    if session is None:
        _task_sessions.pop(session_id, None)
    return session

@dataclass(frozen=True, slots=True)
class TaskContextSnapshot:
    access_token_json: str | None = None
    http_headers: dict[str, str] | None = None
    origin_request_id: str | None = None
    session_id: str | None = None

    @classmethod
    def capture(cls) -> TaskContextSnapshot:
        from fastmcp.server.dependencies import get_access_token, get_context, get_http_headers
        access_token = get_access_token()
        ctx = get_context()
        request_context = ctx.request_context
        try:
            session_id = ctx.session_id
        except RuntimeError:
            session_id = None
        return cls(access_token_json=access_token.model_dump_json() if access_token else None, http_headers=get_http_headers(include_all=True) or None, origin_request_id=str(request_context.request_id) if request_context is not None else None, session_id=session_id)

    @classmethod
    def from_json(cls, raw: str | bytes) -> TaskContextSnapshot:
        if isinstance(raw, bytes):
            raw = raw.decode()
        parsed = json.loads(raw)
        headers = parsed.get('http_headers')
        if isinstance(headers, dict):
            headers = {str(k).lower(): str(v) for k, v in headers.items()}
        return cls(access_token_json=parsed.get('access_token_json'), http_headers=headers, origin_request_id=parsed.get('origin_request_id'), session_id=parsed.get('session_id'))

    def to_json(self) -> str:
        return json.dumps({'access_token_json': self.access_token_json, 'http_headers': self.http_headers, 'origin_request_id': self.origin_request_id, 'session_id': self.session_id})

    async def save(self, docket: Docket, task_scope: str | None, task_id: str, ttl_seconds: int) -> None:
        key = docket.key(_snapshot_redis_key(task_scope, task_id))
        async with docket.redis() as redis:
            await redis.set(key, self.to_json(), ex=ttl_seconds)

# --- helper: fastmcp.server.tasks.context._snapshot_redis_key ---
def _snapshot_redis_key(task_scope: str | None, task_id: str) -> str:
    return f'{task_redis_prefix(task_scope)}:{task_id}:snapshot'

