async def elicit_for_task(task_id: str, session: ServerSession | None, message: str, schema: dict[str, Any], fastmcp: FastMCP) -> mcp.types.ElicitResult:
    docket = fastmcp._docket
    if docket is None:
        raise RuntimeError("Background task elicitation requires Docket. Ensure 'fastmcp[tasks]' is installed and the server has task-enabled components.")
    request_id = str(uuid.uuid4())
    task_context = get_task_context()
    if task_context is not None:
        task_scope = task_context.task_scope
        session_id = getattr(session, '_fastmcp_state_prefix', None) or get_task_session_id()
    else:
        raise RuntimeError('Cannot determine task scope for elicitation. This typically means elicit_for_task() was called outside a Docket worker context.')
    request_key, response_key, status_key = _elicit_keys(task_scope, task_id)
    elicit_request = {'request_id': request_id, 'message': message, 'schema': schema}
    async with docket.redis() as redis:
        await redis.set(docket.key(request_key), json.dumps(elicit_request), ex=ELICIT_TTL_SECONDS)
        await redis.set(docket.key(status_key), 'waiting', ex=ELICIT_TTL_SECONDS)
    timestamp = datetime.now(timezone.utc).isoformat()
    notification_dict = {'method': 'notifications/tasks/status', 'params': {'taskId': task_id, 'status': 'input_required', 'statusMessage': message, 'createdAt': timestamp, 'lastUpdatedAt': timestamp, 'ttl': ELICIT_TTL_SECONDS * 1000}, '_meta': {'io.modelcontextprotocol/related-task': {'taskId': task_id, 'status': 'input_required', 'statusMessage': message, 'task_scope': task_scope, 'elicitation': {'requestId': request_id, 'message': message, 'requestedSchema': schema}}}}
    if session_id is None:
        logger.warning('No session_id available for task %s, cannot deliver elicitation notification', task_id)
        return mcp.types.ElicitResult(action='cancel', content=None)
    try:
        await push_notification(session_id, notification_dict, docket)
    except Exception as e:
        logger.warning('Failed to queue input_required notification for task %s, cancelling elicitation: %s', task_id, e)
        try:
            async with docket.redis() as redis:
                await redis.delete(docket.key(request_key), docket.key(status_key))
        except Exception:
            pass
        return mcp.types.ElicitResult(action='cancel', content=None)
    max_wait_seconds = ELICIT_TTL_SECONDS
    try:
        async with docket.redis() as redis:
            result = await cast(Any, redis.blpop([docket.key(response_key)], timeout=max_wait_seconds))
            if result:
                _key, response_data = result
                response = json.loads(response_data)
                await redis.delete(docket.key(request_key), docket.key(status_key))
                return mcp.types.ElicitResult(action=response.get('action', 'accept'), content=response.get('content'))
    except Exception as e:
        logger.warning('BLPOP failed for task %s elicitation, falling back to cancel: %s', task_id, e)
    try:
        async with docket.redis() as redis:
            await redis.delete(docket.key(request_key), docket.key(response_key), docket.key(status_key))
    except Exception as cleanup_error:
        logger.debug('Failed to clean up elicitation keys for task %s (will expire via TTL): %s', task_id, cleanup_error)
    return mcp.types.ElicitResult(action='cancel', content=None)

# --- helper: fastmcp.server.tasks.elicitation._elicit_keys ---
def _elicit_keys(task_scope: str | None, task_id: str) -> tuple[str, str, str]:
    prefix = f'{task_redis_prefix(task_scope)}:{task_id}:elicit'
    return (f'{prefix}:request', f'{prefix}:response', f'{prefix}:status')

