def build_task_key(task_scope: str | None, client_task_id: str, task_type: str, component_identifier: str) -> str:
    encoded_identifier = quote(component_identifier, safe='')
    if task_scope is None:
        return f'{_ANON_TAG}:{client_task_id}:{task_type}:{encoded_identifier}'
    encoded_scope = quote(task_scope, safe='')
    return f'{_AUTH_TAG}:{encoded_scope}:{client_task_id}:{task_type}:{encoded_identifier}'

def get_client_task_id_from_key(task_key: str) -> str:
    return parse_task_key(task_key)['client_task_id']

# --- helper: fastmcp.server.tasks.keys.parse_task_key ---
def parse_task_key(task_key: str) -> TaskKeyParts:
    tag, _, rest = task_key.partition(':')
    if tag not in _VALID_TAGS or not rest:
        raise ValueError(f'Invalid task key format: {task_key}. Expected leading tag in {_VALID_TAGS}.')
    if tag == _ANON_TAG:
        parts = rest.split(':', 2)
        if len(parts) != 3:
            raise ValueError(f'Invalid anonymous task key: {task_key}. Expected: anon:{{client_task_id}}:{{task_type}}:{{component_identifier}}')
        client_task_id, task_type, encoded_identifier = parts
        return {'task_scope': None, 'client_task_id': client_task_id, 'task_type': task_type, 'component_identifier': unquote(encoded_identifier)}
    parts = rest.split(':', 3)
    if len(parts) != 4:
        raise ValueError(f'Invalid authenticated task key: {task_key}. Expected: auth:{{enc_scope}}:{{client_task_id}}:{{task_type}}:{{component_identifier}}')
    encoded_scope, client_task_id, task_type, encoded_identifier = parts
    return {'task_scope': unquote(encoded_scope), 'client_task_id': client_task_id, 'task_type': task_type, 'component_identifier': unquote(encoded_identifier)}

