def get_auth_span_attributes() -> dict[str, str]:
    from fastmcp.server.dependencies import get_access_token
    attrs: dict[str, str] = {}
    try:
        token = get_access_token()
        if token:
            if token.client_id:
                attrs['enduser.id'] = token.client_id
            if token.scopes:
                attrs['enduser.scope'] = ' '.join(token.scopes)
    except RuntimeError:
        pass
    return attrs

class GetResourceNext(Protocol):

    def __call__(self, uri: str, *, version: VersionSpec | None=None) -> Awaitable[Resource | None]:
        ...

class VersionFilter(Transform):

    def __init__(self, *, version_gte: str | None=None, version_lt: str | None=None, include_unversioned: bool=True) -> None:
        if version_gte is None and version_lt is None:
            raise ValueError('At least one of version_gte or version_lt must be specified')
        self.version_gte = version_gte
        self.version_lt = version_lt
        self.include_unversioned = include_unversioned
        self._spec = VersionSpec(gte=version_gte, lt=version_lt)

    def __repr__(self) -> str:
        parts = []
        if self.version_gte:
            parts.append(f'version_gte={self.version_gte!r}')
        if self.version_lt:
            parts.append(f'version_lt={self.version_lt!r}')
        if not self.include_unversioned:
            parts.append('include_unversioned=False')
        return f"VersionFilter({', '.join(parts)})"

    async def list_tools(self, tools: Sequence[Tool]) -> Sequence[Tool]:
        return [t for t in tools if self._spec.matches(t.version, match_none=self.include_unversioned)]

    async def get_tool(self, name: str, call_next: GetToolNext, *, version: VersionSpec | None=None) -> Tool | None:
        return await call_next(name, version=self._spec.intersect(version))

    async def list_resources(self, resources: Sequence[Resource]) -> Sequence[Resource]:
        return [r for r in resources if self._spec.matches(r.version, match_none=self.include_unversioned)]

    async def get_resource(self, uri: str, call_next: GetResourceNext, *, version: VersionSpec | None=None) -> Resource | None:
        return await call_next(uri, version=self._spec.intersect(version))

    async def list_resource_templates(self, templates: Sequence[ResourceTemplate]) -> Sequence[ResourceTemplate]:
        return [t for t in templates if self._spec.matches(t.version, match_none=self.include_unversioned)]

    async def get_resource_template(self, uri: str, call_next: GetResourceTemplateNext, *, version: VersionSpec | None=None) -> ResourceTemplate | None:
        return await call_next(uri, version=self._spec.intersect(version))

    async def list_prompts(self, prompts: Sequence[Prompt]) -> Sequence[Prompt]:
        return [p for p in prompts if self._spec.matches(p.version, match_none=self.include_unversioned)]

    async def get_prompt(self, name: str, call_next: GetPromptNext, *, version: VersionSpec | None=None) -> Prompt | None:
        return await call_next(name, version=self._spec.intersect(version))

