async def check_background_task(component: Tool | Resource | ResourceTemplate | Prompt, task_type: TaskType, arguments: dict[str, Any] | None=None, task_meta: TaskMeta | None=None) -> mcp.types.CreateTaskResult | None:
    task_config = component.task_config
    entity_label = f"{type(component).__name__} '{component.title or component.key}'"
    if task_config.mode == 'required' and (not task_meta):
        raise McpError(ErrorData(code=METHOD_NOT_FOUND, message=f'{entity_label} requires task-augmented execution'))
    if not task_config.supports_tasks() and task_meta:
        raise McpError(ErrorData(code=METHOD_NOT_FOUND, message=f'{entity_label} does not support task-augmented execution'))
    if not task_meta:
        return None
    fn_key = task_meta.fn_key or component.key
    return await submit_to_docket(task_type, fn_key, component, arguments, task_meta)

class ResourcesAsTools(Transform):

    def __init__(self, provider: Provider) -> None:
        from fastmcp.server.server import FastMCP
        if not isinstance(provider, FastMCP):
            raise TypeError(f"ResourcesAsTools requires a FastMCP server instance, not a {type(provider).__name__}. The generated tools route through the server's middleware chain at runtime for auth and visibility. Pass your FastMCP server: ResourcesAsTools(mcp)")
        self._provider = provider

    def __repr__(self) -> str:
        return f'ResourcesAsTools({self._provider!r})'

    async def list_tools(self, tools: Sequence[Tool]) -> Sequence[Tool]:
        return [*tools, self._make_list_resources_tool(), self._make_read_resource_tool()]

    async def get_tool(self, name: str, call_next: GetToolNext, *, version: VersionSpec | None=None) -> Tool | None:
        if name == 'list_resources':
            return self._make_list_resources_tool()
        if name == 'read_resource':
            return self._make_read_resource_tool()
        return await call_next(name, version=version)

    def _make_list_resources_tool(self) -> Tool:

        async def list_resources() -> str:
            ctx = get_context()
            resources = await ctx.fastmcp.list_resources()
            templates = await ctx.fastmcp.list_resource_templates()
            result: list[dict[str, Any]] = []
            for r in resources:
                result.append({'uri': str(r.uri), 'name': r.name, 'description': r.description, 'mime_type': r.mime_type})
            for t in templates:
                result.append({'uri_template': t.uri_template, 'name': t.name, 'description': t.description})
            return json.dumps(result, indent=2)
        return Tool.from_function(fn=list_resources, annotations=_DEFAULT_ANNOTATIONS)

    def _make_read_resource_tool(self) -> Tool:

        async def read_resource(uri: Annotated[str, 'The URI of the resource to read']) -> str:
            ctx = get_context()
            result = await ctx.fastmcp.read_resource(uri)
            return _format_result(result)
        return Tool.from_function(fn=read_resource, annotations=_DEFAULT_ANNOTATIONS)

# --- helper: fastmcp.server.transforms.resources_as_tools._format_result ---
def _format_result(result: Any) -> str:
    if len(result.contents) == 1:
        content = result.contents[0].content
        if isinstance(content, bytes):
            return base64.b64encode(content).decode()
        return content
    return json.dumps([{'content': c.content if isinstance(c.content, str) else base64.b64encode(c.content).decode(), 'mime_type': c.mime_type} for c in result.contents])

class PromptsAsTools(Transform):

    def __init__(self, provider: Provider) -> None:
        from fastmcp.server.server import FastMCP
        if not isinstance(provider, FastMCP):
            raise TypeError(f"PromptsAsTools requires a FastMCP server instance, not a {type(provider).__name__}. The generated tools route through the server's middleware chain at runtime for auth and visibility. Pass your FastMCP server: PromptsAsTools(mcp)")
        self._provider = provider

    def __repr__(self) -> str:
        return f'PromptsAsTools({self._provider!r})'

    async def list_tools(self, tools: Sequence[Tool]) -> Sequence[Tool]:
        return [*tools, self._make_list_prompts_tool(), self._make_get_prompt_tool()]

    async def get_tool(self, name: str, call_next: GetToolNext, *, version: VersionSpec | None=None) -> Tool | None:
        if name == 'list_prompts':
            return self._make_list_prompts_tool()
        if name == 'get_prompt':
            return self._make_get_prompt_tool()
        return await call_next(name, version=version)

    def _make_list_prompts_tool(self) -> Tool:

        async def list_prompts() -> str:
            ctx = get_context()
            prompts = await ctx.fastmcp.list_prompts()
            result: list[dict[str, Any]] = []
            for p in prompts:
                result.append({'name': p.name, 'description': p.description, 'arguments': [{'name': arg.name, 'description': arg.description, 'required': arg.required} for arg in p.arguments or []]})
            return json.dumps(result, indent=2)
        return Tool.from_function(fn=list_prompts)

    def _make_get_prompt_tool(self) -> Tool:

        async def get_prompt(name: Annotated[str, 'The name of the prompt to get'], arguments: Annotated[dict[str, Any] | None, 'Optional arguments for the prompt']=None) -> str:
            ctx = get_context()
            result = await ctx.fastmcp.render_prompt(name, arguments=arguments or {})
            return _format_prompt_result(result)
        return Tool.from_function(fn=get_prompt)

# --- helper: fastmcp.server.transforms.prompts_as_tools._format_prompt_result ---
def _format_prompt_result(result: Any) -> str:
    messages = []
    for msg in result.messages:
        if isinstance(msg.content, TextContent):
            content = msg.content.text
        else:
            content = msg.content.model_dump(mode='json', exclude_none=True)
        messages.append({'role': msg.role, 'content': content})
    return json.dumps({'messages': messages}, indent=2)

