class Namespace(Transform):

    def __init__(self, prefix: str) -> None:
        self._prefix = prefix
        self._name_prefix = f'{prefix}_'

    def __repr__(self) -> str:
        return f'Namespace({self._prefix!r})'

    def _transform_name(self, name: str) -> str:
        return f'{self._name_prefix}{name}'

    def _reverse_name(self, name: str) -> str | None:
        if name.startswith(self._name_prefix):
            return name[len(self._name_prefix):]
        return None

    def _transform_uri(self, uri: str) -> str:
        match = _URI_PATTERN.match(uri)
        if match:
            protocol, path = match.groups()
            return f'{protocol}{self._prefix}/{path}'
        return uri

    def _reverse_uri(self, uri: str) -> str | None:
        match = _URI_PATTERN.match(uri)
        if match:
            protocol, path = match.groups()
            prefix = f'{self._prefix}/'
            if path.startswith(prefix):
                return f'{protocol}{path[len(prefix):]}'
            return None
        return None

    async def list_tools(self, tools: Sequence[Tool]) -> Sequence[Tool]:
        return [t.model_copy(update={'name': self._transform_name(t.name)}) for t in tools]

    async def get_tool(self, name: str, call_next: GetToolNext, *, version: VersionSpec | None=None) -> Tool | None:
        original = self._reverse_name(name)
        if original is None:
            return None
        tool = await call_next(original, version=version)
        if tool:
            return tool.model_copy(update={'name': name})
        return None

    async def list_resources(self, resources: Sequence[Resource]) -> Sequence[Resource]:
        return [r.model_copy(update={'uri': self._transform_uri(str(r.uri))}) for r in resources]

    async def get_resource(self, uri: str, call_next: GetResourceNext, *, version: VersionSpec | None=None) -> Resource | None:
        original = self._reverse_uri(uri)
        if original is None:
            return None
        resource = await call_next(original, version=version)
        if resource:
            return resource.model_copy(update={'uri': uri})
        return None

    async def list_resource_templates(self, templates: Sequence[ResourceTemplate]) -> Sequence[ResourceTemplate]:
        return [t.model_copy(update={'uri_template': self._transform_uri(t.uri_template)}) for t in templates]

    async def get_resource_template(self, uri: str, call_next: GetResourceTemplateNext, *, version: VersionSpec | None=None) -> ResourceTemplate | None:
        original = self._reverse_uri(uri)
        if original is None:
            return None
        template = await call_next(original, version=version)
        if template:
            return template.model_copy(update={'uri_template': self._transform_uri(template.uri_template)})
        return None

    async def list_prompts(self, prompts: Sequence[Prompt]) -> Sequence[Prompt]:
        return [p.model_copy(update={'name': self._transform_name(p.name)}) for p in prompts]

    async def get_prompt(self, name: str, call_next: GetPromptNext, *, version: VersionSpec | None=None) -> Prompt | None:
        original = self._reverse_name(name)
        if original is None:
            return None
        prompt = await call_next(original, version=version)
        if prompt:
            return prompt.model_copy(update={'name': name})
        return None

class RegexSearchTransform(BaseSearchTransform):

    def _make_search_tool(self) -> Tool:
        transform = self

        async def search_tools(pattern: Annotated[str, 'Regex pattern to match against tool names, descriptions, and parameters'], ctx: Context=None) -> str | list[dict[str, Any]]:
            hidden = await transform._get_visible_tools(ctx)
            results = await transform._search(hidden, pattern)
            return await transform._render_results(results)
        return Tool.from_function(fn=search_tools, name=self._search_tool_name)

    async def _search(self, tools: Sequence[Tool], query: str) -> Sequence[Tool]:
        try:
            compiled = re.compile(query, re.IGNORECASE)
        except re.error:
            return []
        matches: list[Tool] = []
        for tool in tools:
            text = _extract_searchable_text(tool)
            if compiled.search(text):
                matches.append(tool)
                if len(matches) >= self._max_results:
                    break
        return matches

