class Visibility(Transform):

    def __init__(self, enabled: bool, *, names: set[str] | None=None, keys: set[str] | None=None, version: VersionSpec | None=None, tags: set[str] | None=None, components: set[Literal['tool', 'resource', 'template', 'prompt']] | None=None, match_all: bool=False) -> None:
        self._enabled = enabled
        self.names = names
        self.keys = keys
        self.version = version
        self.tags = tags
        self.components = components
        self.match_all = match_all

    def __repr__(self) -> str:
        action = 'enable' if self._enabled else 'disable'
        if self.match_all:
            return f'Visibility({self._enabled}, match_all=True)'
        parts = []
        if self.names:
            parts.append(f'names={set(self.names)}')
        if self.keys:
            parts.append(f'keys={set(self.keys)}')
        if self.version:
            parts.append(f'version={self.version!r}')
        if self.components:
            parts.append(f'components={set(self.components)}')
        if self.tags:
            parts.append(f'tags={set(self.tags)}')
        if parts:
            return f"Visibility({action}, {', '.join(parts)})"
        return f'Visibility({action})'

    def _matches(self, component: FastMCPComponent) -> bool:
        if self.match_all:
            return True
        if self.names is None and self.keys is None and (self.version is None) and (self.components is None) and (self.tags is None):
            return False
        if self.components is not None:
            component_type = component.key.split(':')[0]
            if component_type not in self.components:
                return False
        if self.keys is not None:
            if component.key not in self.keys:
                return False
        if self.names is not None:
            matches_name = component.name in self.names
            matches_uri = False
            if isinstance(component, Resource):
                matches_uri = str(component.uri) in self.names
            elif isinstance(component, ResourceTemplate):
                matches_uri = component.uri_template in self.names
            if not (matches_name or matches_uri):
                return False
        if self.version is not None and (not self.version.matches(component.version, match_none=False)):
            return False
        return self.tags is None or bool(component.tags & self.tags)

    def _mark_component(self, component: T) -> T:
        if not self._matches(component):
            return component
        if component.meta is None:
            new_meta = {_FASTMCP_KEY: {_INTERNAL_KEY: {'visibility': self._enabled}}}
        else:
            old_fastmcp = component.meta.get(_FASTMCP_KEY, {})
            old_internal = old_fastmcp.get(_INTERNAL_KEY, {})
            new_internal = {**old_internal, 'visibility': self._enabled}
            new_fastmcp = {**old_fastmcp, _INTERNAL_KEY: new_internal}
            new_meta = {**component.meta, _FASTMCP_KEY: new_fastmcp}
        return component.model_copy(update={'meta': new_meta})

    async def list_tools(self, tools: Sequence[Tool]) -> Sequence[Tool]:
        return [self._mark_component(t) for t in tools]

    async def get_tool(self, name: str, call_next: GetToolNext, *, version: VersionSpec | None=None) -> Tool | None:
        tool = await call_next(name, version=version)
        if tool is None:
            return None
        return self._mark_component(tool)

    async def list_resources(self, resources: Sequence[Resource]) -> Sequence[Resource]:
        return [self._mark_component(r) for r in resources]

    async def get_resource(self, uri: str, call_next: GetResourceNext, *, version: VersionSpec | None=None) -> Resource | None:
        resource = await call_next(uri, version=version)
        if resource is None:
            return None
        return self._mark_component(resource)

    async def list_resource_templates(self, templates: Sequence[ResourceTemplate]) -> Sequence[ResourceTemplate]:
        return [self._mark_component(t) for t in templates]

    async def get_resource_template(self, uri: str, call_next: GetResourceTemplateNext, *, version: VersionSpec | None=None) -> ResourceTemplate | None:
        template = await call_next(uri, version=version)
        if template is None:
            return None
        return self._mark_component(template)

    async def list_prompts(self, prompts: Sequence[Prompt]) -> Sequence[Prompt]:
        return [self._mark_component(p) for p in prompts]

    async def get_prompt(self, name: str, call_next: GetPromptNext, *, version: VersionSpec | None=None) -> Prompt | None:
        prompt = await call_next(name, version=version)
        if prompt is None:
            return None
        return self._mark_component(prompt)

class BM25SearchTransform(BaseSearchTransform):

    def __init__(self, *, max_results: int=5, always_visible: list[str] | None=None, search_tool_name: str='search_tools', call_tool_name: str='call_tool', search_result_serializer: SearchResultSerializer | None=None) -> None:
        super().__init__(max_results=max_results, always_visible=always_visible, search_tool_name=search_tool_name, call_tool_name=call_tool_name, search_result_serializer=search_result_serializer)
        self._index = _BM25Index()
        self._indexed_tools: Sequence[Tool] = ()
        self._last_hash: str = ''

    def _make_search_tool(self) -> Tool:
        transform = self

        async def search_tools(query: Annotated[str, 'Natural language query to search for tools'], ctx: Context=None) -> str | list[dict[str, Any]]:
            hidden = await transform._get_visible_tools(ctx)
            results = await transform._search(hidden, query)
            return await transform._render_results(results)
        return Tool.from_function(fn=search_tools, name=self._search_tool_name)

    async def _search(self, tools: Sequence[Tool], query: str) -> Sequence[Tool]:
        current_hash = _catalog_hash(tools)
        if current_hash != self._last_hash:
            documents = [_extract_searchable_text(t) for t in tools]
            new_index = _BM25Index(self._index.k1, self._index.b)
            new_index.build(documents)
            self._index, self._indexed_tools, self._last_hash = (new_index, tools, current_hash)
        indices = self._index.query(query, self._max_results)
        return [self._indexed_tools[i] for i in indices]

# --- helper: fastmcp.server.transforms.search.bm25._BM25Index ---
class _BM25Index:

    def __init__(self, k1: float=1.5, b: float=0.75) -> None:
        self.k1 = k1
        self.b = b
        self._doc_tokens: list[list[str]] = []
        self._doc_lengths: list[int] = []
        self._avg_dl: float = 0.0
        self._df: dict[str, int] = {}
        self._tf: list[dict[str, int]] = []
        self._n: int = 0

    def build(self, documents: list[str]) -> None:
        self._doc_tokens = [_tokenize(doc) for doc in documents]
        self._doc_lengths = [len(tokens) for tokens in self._doc_tokens]
        self._n = len(documents)
        self._avg_dl = sum(self._doc_lengths) / self._n if self._n else 0.0
        self._df = {}
        self._tf = []
        for tokens in self._doc_tokens:
            tf: dict[str, int] = {}
            seen: set[str] = set()
            for token in tokens:
                tf[token] = tf.get(token, 0) + 1
                if token not in seen:
                    self._df[token] = self._df.get(token, 0) + 1
                    seen.add(token)
            self._tf.append(tf)

    def query(self, text: str, top_k: int) -> list[int]:
        query_tokens = _tokenize(text)
        if not query_tokens or not self._n:
            return []
        scores: list[float] = [0.0] * self._n
        for token in query_tokens:
            if token not in self._df:
                continue
            idf = math.log((self._n - self._df[token] + 0.5) / (self._df[token] + 0.5) + 1.0)
            for i in range(self._n):
                tf = self._tf[i].get(token, 0)
                if tf == 0:
                    continue
                dl = self._doc_lengths[i]
                numerator = tf * (self.k1 + 1)
                denominator = tf + self.k1 * (1 - self.b + self.b * dl / self._avg_dl)
                scores[i] += idf * numerator / denominator
        ranked = sorted(range(self._n), key=lambda i: scores[i], reverse=True)
        return [i for i in ranked[:top_k] if scores[i] > 0]

# --- helper: fastmcp.server.transforms.search.bm25._catalog_hash ---
def _catalog_hash(tools: Sequence[Tool]) -> str:
    key = '|'.join(sorted((_extract_searchable_text(t) for t in tools)))
    return hashlib.sha256(key.encode()).hexdigest()

def inject_trace_context(meta: dict[str, Any] | None=None) -> dict[str, Any] | None:
    carrier: dict[str, str] = {}
    propagate.inject(carrier)
    trace_meta: dict[str, Any] = {}
    if 'traceparent' in carrier:
        trace_meta[TRACE_PARENT_KEY] = carrier['traceparent']
    if 'tracestate' in carrier:
        trace_meta[TRACE_STATE_KEY] = carrier['tracestate']
    if trace_meta:
        return {**(meta or {}), **trace_meta}
    return meta

async def save_visibility_rules(context: Context, rules: list[dict[str, Any]], *, components: set[Literal['tool', 'resource', 'template', 'prompt']] | None=None) -> None:
    await context.set_state('_visibility_rules', rules)
    if components is None or 'tool' in components:
        await context.send_notification(mcp.types.ToolListChangedNotification())
    if components is None or 'resource' in components or 'template' in components:
        await context.send_notification(mcp.types.ResourceListChangedNotification())
    if components is None or 'prompt' in components:
        await context.send_notification(mcp.types.PromptListChangedNotification())

