@dataclass
class ParsedFunction:
    fn: Callable[..., Any]
    name: str
    description: str | None
    input_schema: dict[str, Any]
    output_schema: dict[str, Any] | None
    return_type: Any = None

    @classmethod
    def from_function(cls, fn: Callable[..., Any], exclude_args: list[str] | None=None, validate: bool=True, wrap_non_object_output_schema: bool=True) -> ParsedFunction:
        if validate:
            sig = inspect.signature(fn)
            for param in sig.parameters.values():
                if param.kind == inspect.Parameter.VAR_POSITIONAL:
                    raise ValueError('Functions with *args are not supported as tools')
                if param.kind == inspect.Parameter.VAR_KEYWORD:
                    raise ValueError('Functions with **kwargs are not supported as tools')
            if exclude_args:
                for arg_name in exclude_args:
                    if arg_name not in sig.parameters:
                        raise ValueError(f"Parameter '{arg_name}' in exclude_args does not exist in function.")
                    param = sig.parameters[arg_name]
                    if param.default == inspect.Parameter.empty:
                        raise ValueError(f"Parameter '{arg_name}' in exclude_args must have a default value.")
        fn_name = getattr(fn, '__name__', None) or fn.__class__.__name__
        outer_docstring = parse_docstring(fn)
        if not inspect.isroutine(fn) and (not isinstance(fn, functools.partial)):
            fn = fn.__call__
        if isinstance(fn, staticmethod):
            fn = fn.__func__
        inner_docstring = parse_docstring(fn)
        parsed_docstring = ParsedDocstring(description=outer_docstring.description or inner_docstring.description, parameters=inner_docstring.parameters)
        fn = transform_context_annotations(fn)
        wrapper_fn = without_injected_parameters(fn)
        if exclude_args:
            wrapper_fn = create_function_without_params(wrapper_fn, list(exclude_args))
        input_type_adapter = get_cached_typeadapter(wrapper_fn)
        input_schema = input_type_adapter.json_schema()
        prune_params = list(exclude_args) if exclude_args else None
        input_schema = compress_schema(input_schema, prune_params=prune_params, prune_titles=True)
        if parsed_docstring.parameters:
            properties = input_schema.get('properties', {})
            for param_name, param_desc in parsed_docstring.parameters.items():
                if param_name in properties and 'description' not in properties[param_name]:
                    properties[param_name]['description'] = param_desc
        output_schema = None
        sig = inspect.signature(fn)
        output_type = sig.return_annotation
        if isinstance(output_type, str):
            try:
                type_hints = get_type_hints(fn, include_extras=True)
                output_type = type_hints.get('return', output_type)
            except Exception as e:
                logger.debug('Failed to resolve type hint for return annotation: %s', e)
        original_output_type = output_type
        if output_type not in (inspect._empty, None, Any, ...):
            if _contains_bytes_type(output_type):
                output_type = _UnserializableType
            if _PREFAB_TYPES and _contains_prefab_type(output_type):
                output_type = _UnserializableType
            if is_class_member_of_type(output_type, ToolResult):
                output_type = _UnserializableType
            clean_output_type = replace_type(output_type, dict.fromkeys((Image, Audio, File, ToolResult, mcp.types.TextContent, mcp.types.ImageContent, mcp.types.AudioContent, mcp.types.ResourceLink, mcp.types.EmbeddedResource, *_PREFAB_TYPES), _UnserializableType))
            try:
                type_adapter = get_cached_typeadapter(clean_output_type)
                base_schema = type_adapter.json_schema(mode='serialization')
                if wrap_non_object_output_schema and (not _is_object_schema(base_schema)):
                    wrapped_type = _WrappedResult[clean_output_type]
                    wrapped_adapter = get_cached_typeadapter(wrapped_type)
                    output_schema = wrapped_adapter.json_schema(mode='serialization')
                    output_schema['x-fastmcp-wrap-result'] = True
                else:
                    output_schema = base_schema
                output_schema = compress_schema(output_schema, prune_titles=True)
            except PydanticSchemaGenerationError as e:
                if '_UnserializableType' not in str(e):
                    logger.debug(f'Unable to generate schema for type {output_type!r}')
        return cls(fn=fn, name=fn_name, description=parsed_docstring.description, input_schema=input_schema, output_schema=output_schema or None, return_type=original_output_type)

# --- helper: fastmcp.tools.function_parsing._UnserializableType ---
class _UnserializableType:
    pass

# --- helper: fastmcp.tools.function_parsing._WrappedResult ---
@dataclass
class _WrappedResult(Generic[T]):
    result: T

# --- helper: fastmcp.tools.function_parsing._contains_bytes_type ---
def _contains_bytes_type(tp: Any) -> bool:
    if tp is bytes:
        return True
    origin = get_origin(tp)
    if origin is Union or origin is types.UnionType or origin is Annotated:
        return any((_contains_bytes_type(a) for a in get_args(tp)))
    return False

# --- helper: fastmcp.tools.function_parsing._contains_prefab_type ---
def _contains_prefab_type(tp: Any) -> bool:
    if isinstance(tp, type) and issubclass(tp, _PREFAB_TYPES):
        return True
    origin = get_origin(tp)
    if origin is Union or origin is types.UnionType or origin is Annotated:
        return any((_contains_prefab_type(a) for a in get_args(tp)))
    return False

# --- helper: fastmcp.tools.function_parsing._is_object_schema ---
def _is_object_schema(schema: dict[str, Any], *, _root_schema: dict[str, Any] | None=None, _seen_refs: set[str] | None=None) -> bool:
    root_schema = _root_schema or schema
    seen_refs = _seen_refs or set()
    if schema.get('type') == 'object':
        return True
    if 'properties' in schema:
        return True
    ref = schema.get('$ref')
    if not isinstance(ref, str) or not ref.startswith('#/'):
        return False
    if ref in seen_refs:
        return False
    pointer = ref.removeprefix('#/')
    segments = pointer.split('/')
    target: Any = root_schema
    for segment in segments:
        unescaped = segment.replace('~1', '/').replace('~0', '~')
        if not isinstance(target, dict) or unescaped not in target:
            return False
        target = target[unescaped]
    target_schema = target
    if not isinstance(target_schema, dict):
        return False
    return _is_object_schema(target_schema, _root_schema=root_schema, _seen_refs=seen_refs | {ref})

