@dataclass(kw_only=True)
class ArgTransform:
    name: str | NotSetT = NotSet
    description: str | NotSetT = NotSet
    default: Any | NotSetT = NotSet
    default_factory: Callable[[], Any] | NotSetT = NotSet
    type: Any | NotSetT = NotSet
    hide: bool = False
    required: Literal[True] | NotSetT = NotSet
    examples: Any | NotSetT = NotSet

    def __post_init__(self):
        has_default = self.default is not NotSet
        has_factory = self.default_factory is not NotSet
        if has_default and has_factory:
            raise ValueError("Cannot specify both 'default' and 'default_factory' in ArgTransform. Use either 'default' for a static value or 'default_factory' for a callable.")
        if has_factory and (not self.hide):
            raise ValueError("default_factory can only be used with hide=True. Visible parameters must use static 'default' values since JSON schema cannot represent dynamic factories.")
        if self.required is True and (has_default or has_factory):
            raise ValueError("Cannot specify 'required=True' with 'default' or 'default_factory'. Required parameters cannot have defaults.")
        if self.hide and self.required is True:
            raise ValueError("Cannot specify both 'hide=True' and 'required=True'. Hidden parameters cannot be required since clients cannot provide them.")
        if self.required is False:
            raise ValueError("Cannot specify 'required=False'. Set a default value instead.")

def decode_jwt_header(token: str) -> dict[str, Any]:
    return _decode_jwt_part(token, 0)

# --- helper: fastmcp.utilities.auth._decode_jwt_part ---
def _decode_jwt_part(token: str, part_index: int) -> dict[str, Any]:
    parts = token.split('.')
    if len(parts) != 3:
        raise ValueError('Invalid JWT format (expected 3 parts)')
    part_b64 = parts[part_index]
    part_b64 += '=' * (-len(part_b64) % 4)
    return json.loads(base64.urlsafe_b64decode(part_b64))

async def forward(**kwargs: Any) -> ToolResult:
    tool = _current_tool.get()
    if tool is None:
        raise RuntimeError('forward() can only be called within a transformed tool')
    return await tool.forwarding_fn(**kwargs)

def is_coroutine_function(fn: Any) -> bool:
    while isinstance(fn, functools.partial):
        fn = fn.func
    return inspect.iscoroutinefunction(fn)

def parse_scopes(value: Any) -> list[str] | None:
    if value is None or value == '':
        return None if value is None else []
    if isinstance(value, list):
        return [str(v).strip() for v in value if str(v).strip()]
    if isinstance(value, str):
        value = value.strip()
        if not value:
            return []
        if value.startswith('['):
            try:
                data = json.loads(value)
                if isinstance(data, list):
                    return [str(v).strip() for v in data if str(v).strip()]
            except Exception:
                pass
        return [s.strip() for s in value.replace(',', ' ').split() if s.strip()]
    return value

