async def gather(*awaitables: Awaitable[T], return_exceptions: bool=False) -> list[T] | list[T | BaseException]:
    results: list[T | BaseException] = [None] * len(awaitables)

    async def run_at(i: int, aw: Awaitable[T]) -> None:
        try:
            results[i] = await aw
        except BaseException as e:
            if return_exceptions:
                results[i] = e
            else:
                raise
    async with anyio.create_task_group() as tg:
        for i, aw in enumerate(awaitables):
            tg.start_soon(run_at, i, aw)
    return results

