def get_fastmcp_metadata(meta: dict[str, Any] | None) -> FastMCPMeta:
    if not meta:
        return {}
    for key in ('fastmcp', '_fastmcp'):
        metadata = meta.get(key)
        if isinstance(metadata, dict):
            return cast(FastMCPMeta, metadata)
