# --- helper: fastmcp.utilities.components.FastMCPMeta ---
class FastMCPMeta(TypedDict, total=False):
    tags: list[str]
    version: str
    versions: list[str]

class FastMCPComponent(FastMCPBaseModel):
    KEY_PREFIX: ClassVar[str] = ''

    def __init_subclass__(cls, **kwargs: Any) -> None:
        super().__init_subclass__(**kwargs)
        if not cls.KEY_PREFIX:
            import warnings
            warnings.warn(f'{cls.__name__} does not define KEY_PREFIX. Component keys will not be type-prefixed, which may cause collisions.', UserWarning, stacklevel=2)
    name: str = Field(description='The name of the component.')
    version: Annotated[str | None, BeforeValidator(_coerce_version)] = Field(default=None, description='Optional version identifier for this component. Multiple versions of the same component (same name) can coexist.')
    title: str | None = Field(default=None, description='The title of the component for display purposes.')
    description: str | None = Field(default=None, description='The description of the component.')
    icons: list[Icon] | None = Field(default=None, description='Optional list of icons for this component to display in user interfaces.')
    tags: Annotated[set[str], BeforeValidator(_convert_set_default_none)] = Field(default_factory=set, description='Tags for the component.')
    meta: dict[str, Any] | None = Field(default=None, description='Meta information about the component')
    task_config: Annotated[TaskConfig, Field(description='Background task execution configuration (SEP-1686).')] = Field(default_factory=lambda: TaskConfig(mode='forbidden'))

    @classmethod
    def make_key(cls, identifier: str) -> str:
        if cls.KEY_PREFIX:
            return f'{cls.KEY_PREFIX}:{identifier}'
        return identifier

    @property
    def key(self) -> str:
        base_key = self.make_key(self.name)
        return f"{base_key}@{self.version or ''}"

    def get_meta(self) -> dict[str, Any]:
        meta = dict(self.meta) if self.meta else {}
        fastmcp_meta: FastMCPMeta = {'tags': sorted(self.tags)}
        if self.version is not None:
            fastmcp_meta['version'] = self.version
        if (upstream_meta := meta.get('fastmcp')) is not None:
            if not isinstance(upstream_meta, dict):
                raise TypeError("meta['fastmcp'] must be a dict")
            public_upstream = {k: v for k, v in upstream_meta.items() if not k.startswith('_')}
            fastmcp_meta = cast(FastMCPMeta, public_upstream | fastmcp_meta)
        meta['fastmcp'] = fastmcp_meta
        return meta

    def __eq__(self, other: object) -> bool:
        if type(self) is not type(other):
            return False
        if not isinstance(other, type(self)):
            return False
        return self.model_dump() == other.model_dump()

    def __repr__(self) -> str:
        parts = [f'name={self.name!r}']
        if self.version:
            parts.append(f'version={self.version!r}')
        parts.extend([f'title={self.title!r}', f'description={self.description!r}', f'tags={self.tags}'])
        return f"{self.__class__.__name__}({', '.join(parts)})"

    def enable(self) -> None:
        raise NotImplementedError(f"Component.enable() was removed in FastMCP 3.0. Use server.enable(keys=['{self.key}']) instead.")

    def disable(self) -> None:
        raise NotImplementedError(f"Component.disable() was removed in FastMCP 3.0. Use server.disable(keys=['{self.key}']) instead.")

    def copy(self) -> Self:
        return self.model_copy()

    def register_with_docket(self, docket: Docket) -> None:
        pass

    async def add_to_docket(self, docket: Docket, *args: Any, **kwargs: Any) -> Execution:
        if not self.task_config.supports_tasks():
            raise RuntimeError(f"Cannot add {self.__class__.__name__} '{self.name}' to docket: task execution not supported")
        raise NotImplementedError(f'{self.__class__.__name__} does not implement add_to_docket()')

    def get_span_attributes(self) -> dict[str, Any]:
        return {'fastmcp.component.key': self.key}

# --- helper: fastmcp.utilities.components.FastMCPMeta ---
class FastMCPMeta(TypedDict, total=False):
    tags: list[str]
    version: str
    versions: list[str]

# --- helper: fastmcp.utilities.components._coerce_version ---
def _coerce_version(v: str | int | float | None) -> str | None:
    if v is None:
        return None
    if isinstance(v, bool):
        raise TypeError(f'Version must be a string, int, or float, got bool: {v!r}')
    if not isinstance(v, (str, int, float)):
        raise TypeError(f'Version must be a string, int, or float, got {type(v).__name__}: {v!r}')
    version = str(v)
    if '@' in version:
        raise ValueError(f"Version string cannot contain '@' (used as key delimiter): {version!r}")
    return version

# --- helper: fastmcp.utilities.components._convert_set_default_none ---
def _convert_set_default_none(maybe_set: set[T] | Sequence[T] | None) -> set[T]:
    if maybe_set is None:
        return set()
    if isinstance(maybe_set, set):
        return maybe_set
    return set(maybe_set)

