def json_schema_to_type(schema: Mapping[str, Any] | bool, name: str | None=None) -> type:
    if schema is True:
        return Any
    if schema is False:
        return _UnsatisfiableType
    schema = _normalize_yaml_types(schema)
    if schema.get('type') == 'object':
        return _object_schema_to_type(schema, schemas=schema, name=name)
    elif name:
        raise ValueError(f'Can not apply name to non-object schema: {name}')
    result = _schema_to_type(schema, schemas=schema)
    return result

# --- helper: fastmcp.utilities.json_schema_type._normalize_yaml_types ---
def _normalize_yaml_types(obj: Any) -> Any:
    if isinstance(obj, datetime):
        return obj.isoformat()
    if isinstance(obj, date):
        return obj.isoformat()
    if isinstance(obj, dict):
        return {str(k) if not isinstance(k, str) else k: _normalize_yaml_types(v) for k, v in obj.items()}
    if isinstance(obj, list):
        return [_normalize_yaml_types(v) for v in obj]
    return obj

# --- helper: fastmcp.utilities.json_schema_type._object_schema_to_type ---
def _object_schema_to_type(schema: Mapping[str, Any], schemas: Mapping[str, Any], name: str | None=None) -> type:
    has_properties = bool(schema.get('properties'))
    additional_props = schema.get('additionalProperties')
    class_name = name if name is not None else schema.get('title')
    if not has_properties and additional_props:
        if additional_props is True:
            return dict[str, Any]
        value_type = _schema_to_type(additional_props, schemas)
        return cast(type[Any], dict[str, value_type])
    if not has_properties and (not additional_props):
        return dict[str, Any]
    if has_properties and additional_props is True:
        return _create_pydantic_model(schema, class_name, schemas)
    return _create_dataclass(schema, class_name, schemas)

# --- helper: fastmcp.utilities.json_schema_type._schema_to_type ---
def _schema_to_type(schema: Mapping[str, Any] | bool, schemas: Mapping[str, Any]) -> type | ForwardRef:
    if schema is True:
        return Any
    if schema is False:
        return _UnsatisfiableType
    if not schema:
        return object
    if 'type' not in schema and 'properties' in schema:
        return _create_dataclass(schema, schema.get('title', '<unknown>'), schemas)
    if '$ref' in schema:
        ref = schema['$ref']
        if ref == '#':
            return ForwardRef(schema.get('title', 'Root'))
        return _schema_to_type(_resolve_ref(ref, schemas), schemas)
    if 'const' in schema:
        return Literal[schema['const']]
    if 'enum' in schema:
        return _create_enum(f'Enum_{len(_classes)}', schema['enum'])
    if 'anyOf' in schema:
        types: list[type | Any] = [_schema_to_type(subschema, schemas) for subschema in schema['anyOf']]
        has_null = type(None) in types
        types = [t for t in types if t is not type(None)]
        if len(types) == 0:
            return type(None)
        elif len(types) == 1:
            if has_null:
                return types[0] | None
            else:
                return types[0]
        elif has_null:
            return Union[*types, type(None)]
        else:
            return Union[tuple(types)]
    schema_type = schema.get('type')
    if not schema_type:
        return Any
    if isinstance(schema_type, list):
        types: list[type | Any] = []
        for t in schema_type:
            type_schema = dict(schema)
            type_schema['type'] = t
            types.append(_schema_to_type(type_schema, schemas))
        has_null = type(None) in types
        types = [t for t in types if t is not type(None)]
        if has_null:
            if len(types) == 1:
                return types[0] | None
            else:
                return Union[*types, type(None)]
        return Union[tuple(types)]
    return _get_from_type_handler(schema, schemas)(schema)

