implementation:
def compress_schema(schema: dict[str, Any], prune_params: list[str] | None=None, prune_additional_properties: bool=False, prune_titles: bool=False, dereference: bool=False) -> dict[str, Any]:
    if dereference:
        schema = dereference_refs(schema)
    schema = resolve_root_ref(schema)
    for param in prune_params or []:
        schema = _prune_param(schema, param=param)
    schema = _single_pass_optimize(schema, prune_titles=prune_titles, prune_additional_properties=prune_additional_properties, prune_defs=True)
    return schema

# --- helper: fastmcp.utilities.json_schema._prune_param ---
def _prune_param(schema: dict[str, Any], param: str) -> dict[str, Any]:
    props = schema.get('properties', {})
    removed = props.pop(param, None)
    if removed is None:
        return schema
    schema['properties'] = props
    if param in schema.get('required', []):
        schema['required'].remove(param)
        if not schema['required']:
            schema.pop('required')
    return schema

# --- helper: fastmcp.utilities.json_schema._single_pass_optimize ---
def _single_pass_optimize(schema: dict[str, Any], prune_titles: bool=False, prune_additional_properties: bool=False, prune_defs: bool=True) -> dict[str, Any]:
    if not (prune_defs or prune_titles or prune_additional_properties):
        return schema
    root_refs: set[str] = set()
    def_dependencies: defaultdict[str, list[str]] = defaultdict(list)
    defs = schema.get('$defs')

    def traverse_and_clean(node: object, current_def_name: str | None=None, skip_defs_section: bool=False, depth: int=0, in_schema: bool=True) -> None:
        if depth > 50:
            return
        if isinstance(node, dict):
            if prune_defs:
                ref = node.get('$ref')
                if isinstance(ref, str) and ref.startswith('#/$defs/'):
                    referenced_def = ref.split('/')[-1]
                    if current_def_name:
                        def_dependencies[referenced_def].append(current_def_name)
                    else:
                        root_refs.add(referenced_def)
            if in_schema:
                if prune_titles and 'title' in node and isinstance(node['title'], str) and (any((k in node for k in _SCHEMA_KEYWORDS)) or all((k in _METADATA_KEYS for k in node))):
                    node.pop('title')
                if prune_additional_properties and node.get('additionalProperties') is False:
                    node.pop('additionalProperties')
            for key, value in node.items():
                if skip_defs_section and key == '$defs':
                    continue
                if not in_schema:
                    traverse_and_clean(value, current_def_name, depth=depth + 1, in_schema=False)
                    continue
                if key in _SUBSCHEMA_MAP_KEYS and isinstance(value, dict):
                    for sub_schema in value.values():
                        traverse_and_clean(sub_schema, current_def_name, depth=depth + 1, in_schema=True)
                    continue
                if key in _LITERAL_KEYWORDS:
                    continue
                if key in _SUBSCHEMA_LIST_KEYS and isinstance(value, list):
                    for item in value:
                        traverse_and_clean(item, current_def_name, depth=depth + 1, in_schema=True)
                    continue
                if key in _SUBSCHEMA_VALUE_KEYS:
                    traverse_and_clean(value, current_def_name, depth=depth + 1, in_schema=True)
                    continue
                traverse_and_clean(value, current_def_name, depth=depth + 1, in_schema=False)
        elif isinstance(node, list):
            for item in node:
                traverse_and_clean(item, current_def_name, depth=depth + 1, in_schema=in_schema)
    traverse_and_clean(schema, skip_defs_section=True, in_schema=True)
    if prune_defs and defs:
        for def_name, def_schema in defs.items():
            traverse_and_clean(def_schema, current_def_name=def_name, in_schema=True)

        def is_def_used(def_name: str, visiting: set[str] | None=None) -> bool:
            if def_name in root_refs:
                return True
            referencing_defs = def_dependencies.get(def_name, [])
            if referencing_defs:
                if visiting is None:
                    visiting = set()
                if def_name in visiting:
                    return False
                visiting = visiting | {def_name}
                for referencing_def in referencing_defs:
                    if referencing_def not in visiting and is_def_used(referencing_def, visiting):
                        return True
            return False
        for def_name in list(defs.keys()):
            if not is_def_used(def_name):
                defs.pop(def_name)
        if not defs:
            schema.pop('$defs', None)
    return schema

# --- helper: fastmcp.utilities.json_schema.dereference_refs ---
def dereference_refs(schema: dict[str, Any]) -> dict[str, Any]:
    schema = _strip_remote_refs(schema)
    if _defs_have_cycles(schema.get('$defs', {})):
        return resolve_root_ref(schema)
    try:
        dereferenced = replace_refs(schema, proxies=False, lazy_load=False)
        defs = schema.get('$defs', {})
        merged = _merge_ref_siblings(schema, dereferenced, defs)
        assert isinstance(merged, dict)
        dereferenced = merged
        if '$defs' in dereferenced:
            dereferenced = {k: v for k, v in dereferenced.items() if k != '$defs'}
        dereferenced = _strip_discriminator(dereferenced)
        return dereferenced
    except JsonRefError:
        return resolve_root_ref(schema)

# --- helper: fastmcp.utilities.json_schema.resolve_root_ref ---
def resolve_root_ref(schema: dict[str, Any]) -> dict[str, Any]:
    if '$ref' in schema and '$defs' in schema and ('type' not in schema):
        ref = schema['$ref']
        if isinstance(ref, str) and ref.startswith('#/$defs/'):
            def_name = ref.split('/')[-1]
            defs = schema['$defs']
            if def_name in defs:
                resolved = dict(defs[def_name])
                resolved['$defs'] = defs
                return resolved
    return schema

