annotations = getattr(FastMCPInfo, "__annotations__", {})
kwargs = {}
for name, ann in annotations.items():
    # choose a simple default based on common annotation names/types
    if name in ("name", "version") or getattr(ann, "__name__", str(ann)) in ("str", "typing.Text"):
        kwargs[name] = "example"
    elif getattr(ann, "__name__", str(ann)) in ("dict", "typing.Dict") or name in ("annotations", "meta"):
        kwargs[name] = {}
    elif getattr(ann, "__name__", str(ann)) in ("list", "typing.List", "typing.Sequence") or name == "tags":
