    args: list[str] | None = Field(default=None, description='Arguments to pass to the server (after --)', examples=[['--config', 'config.json', '--debug']])

    def apply_runtime_settings(self, config_path: Path | None=None) -> None:
        import os
        from pathlib import Path
        if self.env:
            for key, value in self.env.items():
                interpolated_value = self._interpolate_env_vars(value)
                os.environ[key] = interpolated_value
        if self.cwd:
            cwd_path = Path(self.cwd)
            if not cwd_path.is_absolute() and config_path:
                cwd_path = (config_path.parent / cwd_path).resolve()
            os.chdir(cwd_path)

    def _interpolate_env_vars(self, value: str) -> str:

        def replace_var(match: re.Match) -> str:
            var_name = match.group(1)
            return os.environ.get(var_name, match.group(0))
        return re.sub('\\$\\{([^}]+)\\}', replace_var, value)

def format_array_parameter(values: list, parameter_name: str, is_query_parameter: bool=False) -> str | list:
    if all((isinstance(item, str | int | float | bool) for item in values)):
        return ','.join((str(v) for v in values))
    try:
        formatted_parts = []
        for item in values:
            if isinstance(item, dict):
                item_parts = []
                for k, v in item.items():
                    item_parts.append(f'{k}:{v}')
                formatted_parts.append('.'.join(item_parts))
            else:
                formatted_parts.append(str(item))
        return ','.join(formatted_parts)
    except Exception as e:
        param_type = 'query' if is_query_parameter else 'path'
        logger.warning(f"Failed to format complex array {param_type} parameter '{parameter_name}': {e}")
        if is_query_parameter:
            return values
        else:
            str_value = str(values).replace('[', '').replace(']', '').replace("'", '').replace('"', '')
            return str_value

