class RequestDirector:

    def __init__(self, spec: SchemaPath):
        self._spec = spec

    def build(self, route: HTTPRoute, flat_args: dict[str, Any], base_url: str='http://localhost') -> httpx.Request:
        logger.debug(f'Building request for {route.method} {route.path} with args: {flat_args}')
        path_params, query_params, header_params, body = self._unflatten_arguments(route, flat_args)
        logger.debug(f'Unflattened - path: {path_params}, query: {query_params}, headers: {header_params}, body: {body}')
        query_params = self._serialize_query_params(route, query_params)
        url = self._build_url(route.path, path_params, base_url)
        method: str = route.method.upper()
        params = query_params if query_params else None
        headers = header_params if header_params else None
        json_body: dict[str, Any] | list[Any] | None = None
        content: str | bytes | None = None
        declared_content_type: str | None = None
        if route.request_body and route.request_body.content_schema:
            declared_content_type = next(iter(route.request_body.content_schema))
        if body is not None:
            if isinstance(body, dict | list):
                if declared_content_type is not None and declared_content_type != 'application/json' and ('json' in declared_content_type):
                    content = _json.dumps(body, allow_nan=False).encode('utf-8')
                    headers = dict(headers) if headers else {}
                    headers['Content-Type'] = declared_content_type
                else:
                    json_body = body
            else:
                content = body
        return httpx.Request(method=method, url=url, params=params, headers=headers, json=json_body, content=content)

    def _unflatten_arguments(self, route: HTTPRoute, flat_args: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], Any]:
        path_params = {}
        query_params = {}
        header_params = {}
        body_props = {}
        if hasattr(route, 'parameter_map') and route.parameter_map:
            for arg_name, value in flat_args.items():
                if value is None:
                    continue
                if arg_name not in route.parameter_map:
                    logger.warning(f"Argument '{arg_name}' not found in parameter map for {route.operation_id}")
                    continue
                mapping = route.parameter_map[arg_name]
                location = mapping['location']
                openapi_name = mapping['openapi_name']
                if location == 'path':
                    path_params[openapi_name] = value
                elif location == 'query':
                    query_params[openapi_name] = value
                elif location == 'header':
                    header_params[openapi_name] = value
                elif location == 'body':
                    body_props[openapi_name] = value
                else:
                    logger.warning(f"Unknown parameter location '{location}' for {arg_name}")
        else:
            logger.debug('No parameter map available, using fallback mapping')
            param_locations = {}
            for param in route.parameters:
                param_locations[param.name] = param.location
            for arg_name, value in flat_args.items():
                if value is None:
                    continue
                if '__' in arg_name:
                    base_name, location = arg_name.rsplit('__', 1)
                    if location in ['path', 'query', 'header']:
                        if location == 'path':
                            path_params[base_name] = value
                        elif location == 'query':
                            query_params[base_name] = value
                        elif location == 'header':
                            header_params[base_name] = value
                        continue
                if arg_name in param_locations:
                    location = param_locations[arg_name]
                    if location == 'path':
                        path_params[arg_name] = value
                    elif location == 'query':
                        query_params[arg_name] = value
                    elif location == 'header':
                        header_params[arg_name] = value
                else:
                    body_props[arg_name] = value
        body = None
        if body_props:
            if route.request_body and route.request_body.content_schema and (len(route.request_body.content_schema) > 0):
                content_type = next(iter(route.request_body.content_schema))
                body_schema = route.request_body.content_schema[content_type]
                if isinstance(body_schema, dict) and body_schema.get('type') == 'object':
                    body = body_props
                elif len(body_props) == 1:
                    body = next(iter(body_props.values()))
                else:
                    body = body_props
            else:
                body = body_props
        return (path_params, query_params, header_params, body)
    _STYLE_DELIMITERS: ClassVar[dict[str, str]] = {'form': ',', 'spaceDelimited': ' ', 'pipeDelimited': '|'}

    def _serialize_query_params(self, route: HTTPRoute, query_params: dict[str, Any]) -> dict[str, Any]:
        if not query_params:
            return query_params
        param_lookup: dict[str, ParameterInfo] = {p.name: p for p in route.parameters if p.location == 'query'}
        serialized: dict[str, Any] = {}
        for key, value in query_params.items():
            param_info = param_lookup.get(key)
            if param_info is not None:
                explode = param_info.explode if param_info.explode is not None else True
                if isinstance(value, dict):
                    if not value:
                        continue
                    if explode:
                        for k, v in value.items():
                            serialized[_query_scalar_to_str(k)] = _query_scalar_to_str(v)
                    else:
                        style = param_info.style or 'form'
                        delimiter = self._STYLE_DELIMITERS.get(style, ',')
                        parts: list[str] = []
                        for k, v in value.items():
                            parts.append(_query_scalar_to_str(k))
                            parts.append(_query_scalar_to_str(v))
                        serialized[key] = delimiter.join(parts)
                    continue
                if not explode:
                    style = param_info.style or 'form'
                    delimiter = self._STYLE_DELIMITERS.get(style, ',')
                    if isinstance(value, list):
                        if not value:
                            continue
                        serialized[key] = delimiter.join((_query_scalar_to_str(v) for v in value))
                        continue
            serialized[key] = value
        return serialized

    def _build_url(self, path_template: str, path_params: dict[str, Any], base_url: str) -> str:
        url_path = path_template
        for param_name, param_value in path_params.items():
            placeholder = f'{{{param_name}}}'
            if placeholder in url_path:
                safe_value = quote(str(param_value), safe='').replace('.', '%2E')
                url_path = url_path.replace(placeholder, safe_value)
        return urljoin(base_url.rstrip('/') + '/', url_path.lstrip('/'))

# --- helper: fastmcp.utilities.openapi.director._query_scalar_to_str ---
def _query_scalar_to_str(value: Any) -> str:
    if isinstance(value, bool):
        return 'true' if value else 'false'
    return str(value)

