def generate_example_from_schema(schema: JsonSchema | None) -> Any:
    if not schema or not isinstance(schema, dict):
        return 'unknown'
    if 'default' in schema:
        return schema['default']
    if 'enum' in schema and isinstance(schema['enum'], list) and schema['enum']:
        return schema['enum'][0]
    if 'examples' in schema and isinstance(schema['examples'], list) and schema['examples']:
        return schema['examples'][0]
    if 'example' in schema:
        return schema['example']
    schema_type = schema.get('type')
    if schema_type == 'object':
        result = {}
        properties = schema.get('properties', {})
        if isinstance(properties, dict):
            required_props = set(schema.get('required', []))
            props_to_include = list(properties.keys())[:3]
            for prop_name in props_to_include:
                if prop_name in properties:
                    result[prop_name] = generate_example_from_schema(properties[prop_name])
            for req_prop in required_props:
                if req_prop not in result and req_prop in properties:
                    result[req_prop] = generate_example_from_schema(properties[req_prop])
        return result if result else {'key': 'value'}
    elif schema_type == 'array':
        items_schema = schema.get('items')
        if isinstance(items_schema, dict):
            item_example = generate_example_from_schema(items_schema)
            return [item_example] if item_example is not None else []
        return ['example_item']
    elif schema_type == 'string':
        format_type = schema.get('format')
        if format_type == 'date-time':
            return '2024-01-01T12:00:00Z'
        if format_type == 'date':
            return '2024-01-01'
        if format_type == 'email':
            return 'user@example.com'
        if format_type == 'uuid':
            return '123e4567-e89b-12d3-a456-426614174000'
        if format_type == 'byte':
            return 'ZXhhbXBsZQ=='
        return 'string'
    elif schema_type == 'integer':
        return 1
    elif schema_type == 'number':
        return 1.5
    elif schema_type == 'boolean':
        return True
    elif schema_type == 'null':
        return None
    return 'unknown_type'

