def convert_openapi_schema_to_json_schema(schema: dict[str, Any], openapi_version: str | None=None, remove_read_only: bool=False, remove_write_only: bool=False, convert_one_of_to_any_of: bool=True) -> dict[str, Any]:
    if not isinstance(schema, dict):
        return schema
    needs_conversion = any((field in schema for field in OPENAPI_SPECIFIC_FIELDS)) or (remove_read_only and _has_read_only_properties(schema)) or (remove_write_only and _has_write_only_properties(schema)) or (convert_one_of_to_any_of and 'oneOf' in schema) or _needs_recursive_processing(schema, openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of)
    if not needs_conversion:
        return schema
    result = schema.copy()
    if openapi_version and openapi_version.startswith('3.0'):
        result = _convert_nullable_field(result)
    if convert_one_of_to_any_of and 'oneOf' in result:
        result['anyOf'] = result.pop('oneOf')
    for field in OPENAPI_SPECIFIC_FIELDS:
        result.pop(field, None)
    if remove_read_only or remove_write_only:
        result = _filter_properties_by_access(result, remove_read_only, remove_write_only)
    for field_name, field_type in RECURSIVE_FIELDS.items():
        if field_name in result:
            if field_type is dict and isinstance(result[field_name], dict):
                if field_name in ('properties', '$defs', '$definitions'):
                    result[field_name] = {name: convert_openapi_schema_to_json_schema(sub_schema, openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of) if isinstance(sub_schema, dict) else sub_schema for name, sub_schema in result[field_name].items()}
                else:
                    result[field_name] = convert_openapi_schema_to_json_schema(result[field_name], openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of)
            elif field_type is list and isinstance(result[field_name], list):
                result[field_name] = [convert_openapi_schema_to_json_schema(item, openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of) if isinstance(item, dict) else item for item in result[field_name]]
    return result

# --- helper: fastmcp.utilities.openapi.json_schema_converter._convert_nullable_field ---
def _convert_nullable_field(schema: dict[str, Any]) -> dict[str, Any]:
    if 'nullable' not in schema:
        return schema
    result = schema.copy()
    nullable_value = result.pop('nullable')
    if not nullable_value:
        return result
    if 'type' in result:
        current_type = result['type']
        if isinstance(current_type, str):
            result['type'] = [current_type, 'null']
        elif isinstance(current_type, list) and 'null' not in current_type:
            result['type'] = [*current_type, 'null']
    elif 'oneOf' in result:
        result['anyOf'] = [*result.pop('oneOf'), {'type': 'null'}]
    elif 'anyOf' in result:
        if not any((item.get('type') == 'null' for item in result['anyOf'])):
            result['anyOf'].append({'type': 'null'})
    elif 'allOf' in result:
        result['anyOf'] = [{'allOf': result.pop('allOf')}, {'type': 'null'}]
    if 'enum' in result and None not in result['enum']:
        result['enum'] = result['enum'] + [None]
    return result

# --- helper: fastmcp.utilities.openapi.json_schema_converter._filter_properties_by_access ---
def _filter_properties_by_access(schema: dict[str, Any], remove_read_only: bool, remove_write_only: bool) -> dict[str, Any]:
    if 'properties' not in schema:
        return schema
    result = schema.copy()
    filtered_properties = {}
    for prop_name, prop_schema in result['properties'].items():
        if not isinstance(prop_schema, dict):
            filtered_properties[prop_name] = prop_schema
            continue
        should_remove = remove_read_only and prop_schema.get('readOnly') or (remove_write_only and prop_schema.get('writeOnly'))
        if not should_remove:
            filtered_properties[prop_name] = prop_schema
    result['properties'] = filtered_properties
    if 'required' in result and filtered_properties:
        result['required'] = [prop for prop in result['required'] if prop in filtered_properties]
        if not result['required']:
            result.pop('required')
    return result

# --- helper: fastmcp.utilities.openapi.json_schema_converter._has_read_only_properties ---
def _has_read_only_properties(schema: dict[str, Any]) -> bool:
    if 'properties' not in schema:
        return False
    return any((isinstance(prop, dict) and prop.get('readOnly') for prop in schema['properties'].values()))

# --- helper: fastmcp.utilities.openapi.json_schema_converter._has_write_only_properties ---
def _has_write_only_properties(schema: dict[str, Any]) -> bool:
    if 'properties' not in schema:
        return False
    return any((isinstance(prop, dict) and prop.get('writeOnly') for prop in schema['properties'].values()))

# --- helper: fastmcp.utilities.openapi.json_schema_converter._needs_recursive_processing ---
def _needs_recursive_processing(schema: dict[str, Any], openapi_version: str | None, remove_read_only: bool, remove_write_only: bool, convert_one_of_to_any_of: bool) -> bool:
    for field_name, field_type in RECURSIVE_FIELDS.items():
        if field_name in schema:
            if field_type is dict and isinstance(schema[field_name], dict):
                if field_name in ('properties', '$defs', '$definitions'):
                    for sub_schema in schema[field_name].values():
                        if isinstance(sub_schema, dict):
                            nested_needs_conversion = any((field in sub_schema for field in OPENAPI_SPECIFIC_FIELDS)) or (remove_read_only and sub_schema.get('readOnly')) or (remove_write_only and sub_schema.get('writeOnly')) or (convert_one_of_to_any_of and 'oneOf' in sub_schema) or _needs_recursive_processing(sub_schema, openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of)
                            if nested_needs_conversion:
                                return True
                else:
                    nested_needs_conversion = any((field in schema[field_name] for field in OPENAPI_SPECIFIC_FIELDS)) or (remove_read_only and _has_read_only_properties(schema[field_name])) or (remove_write_only and _has_write_only_properties(schema[field_name])) or (convert_one_of_to_any_of and 'oneOf' in schema[field_name]) or _needs_recursive_processing(schema[field_name], openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of)
                    if nested_needs_conversion:
                        return True
            elif field_type is list and isinstance(schema[field_name], list):
                for item in schema[field_name]:
                    if isinstance(item, dict):
                        nested_needs_conversion = any((field in item for field in OPENAPI_SPECIFIC_FIELDS)) or (remove_read_only and _has_read_only_properties(item)) or (remove_write_only and _has_write_only_properties(item)) or (convert_one_of_to_any_of and 'oneOf' in item) or _needs_recursive_processing(item, openapi_version, remove_read_only, remove_write_only, convert_one_of_to_any_of)
                        if nested_needs_conversion:
                            return True
    return False

def extract_output_schema_from_responses(responses: dict[str, ResponseInfo], schema_definitions: dict[str, Any] | None=None, openapi_version: str | None=None) -> dict[str, Any] | None:
    if not responses:
        return None
    success_codes = ['200', '201', '202', '204']
    response_info = None
    for status_code in success_codes:
        if status_code in responses:
            response_info = responses[status_code]
            break
    if response_info is None:
        for status_code, resp_info in responses.items():
            if status_code.startswith('2'):
                response_info = resp_info
                break
    if response_info is None or not response_info.content_schema:
        return None
    json_compatible_types = ['application/json', 'application/vnd.api+json', 'application/hal+json', 'application/ld+json', 'text/json']
    schema = None
    for content_type in json_compatible_types:
        if content_type in response_info.content_schema:
            schema = response_info.content_schema[content_type]
            break
    if schema is None and response_info.content_schema:
        first_content_type = next(iter(response_info.content_schema))
        schema = response_info.content_schema[first_content_type]
        logger.debug(f'Using non-JSON content type for output schema: {first_content_type}')
    if not schema or not isinstance(schema, dict):
        return None
    output_schema = _replace_ref_with_defs(schema)
    if '$ref' in output_schema and schema_definitions:
        ref_path = output_schema['$ref']
        if ref_path.startswith('#/$defs/'):
            schema_name = ref_path.split('/')[-1]
            if schema_name in schema_definitions:
                output_schema = _replace_ref_with_defs(schema_definitions[schema_name])
    if openapi_version and openapi_version.startswith('3'):
        output_schema = convert_openapi_schema_to_json_schema(output_schema, openapi_version)
    if output_schema.get('type') != 'object':
        wrapped_schema = {'type': 'object', 'properties': {'result': output_schema}, 'required': ['result'], 'x-fastmcp-wrap-result': True}
        output_schema = wrapped_schema
    if schema_definitions:
        processed_defs = schema_definitions.copy()
        for name, schema in processed_defs.items():
            if isinstance(schema, dict):
                processed_defs[name] = _replace_ref_with_defs(schema)
        if openapi_version and openapi_version.startswith('3'):
            for def_name in list(processed_defs.keys()):
                processed_defs[def_name] = convert_openapi_schema_to_json_schema(processed_defs[def_name], openapi_version)
        output_schema['$defs'] = processed_defs
    return output_schema

# --- helper: fastmcp.utilities.openapi.schemas._replace_ref_with_defs ---
def _replace_ref_with_defs(info: dict[str, Any], description: str | None=None) -> dict[str, Any]:
    schema = info.copy()
    if (ref_path := schema.get('$ref')):
        if isinstance(ref_path, str):
            if ref_path.startswith('#/components/schemas/'):
                schema_name = ref_path.split('/')[-1]
                schema['$ref'] = f'#/$defs/{schema_name}'
            elif not ref_path.startswith('#/'):
                raise ValueError(f"External or non-local reference not supported: {ref_path}. FastMCP only supports local schema references starting with '#/'. Please include all schema definitions within the OpenAPI document.")
    elif (properties := schema.get('properties')):
        if '$ref' in properties:
            schema['properties'] = _replace_ref_with_defs(properties)
        else:
            schema['properties'] = {prop_name: _replace_ref_with_defs(prop_schema) for prop_name, prop_schema in properties.items()}
    elif (item_schema := schema.get('items')):
        schema['items'] = _replace_ref_with_defs(item_schema)
    for section in ['anyOf', 'allOf', 'oneOf']:
        if section in schema:
            schema[section] = [_replace_ref_with_defs(item) for item in schema[section]]
    if (additionalProperties := schema.get('additionalProperties')):
        if not isinstance(additionalProperties, bool):
            schema['additionalProperties'] = _replace_ref_with_defs(additionalProperties)
    if (property_names := schema.get('propertyNames')):
        if isinstance(property_names, dict):
            schema['propertyNames'] = _replace_ref_with_defs(property_names)
    if (pattern_properties := schema.get('patternProperties')):
        if isinstance(pattern_properties, dict):
            schema['patternProperties'] = {pattern: _replace_ref_with_defs(subschema) if isinstance(subschema, dict) else subschema for pattern, subschema in pattern_properties.items()}
    if info.get('description', description) and (not schema.get('description')):
        schema['description'] = description
    return schema

