def clean_schema_for_display(schema: JsonSchema | None) -> JsonSchema | None:
    if not schema or not isinstance(schema, dict):
        return schema
    cleaned = schema.copy()
    fields_to_remove = ['allOf', 'anyOf', 'oneOf', 'not', 'nullable', 'discriminator', 'readOnly', 'writeOnly', 'deprecated', 'xml', 'externalDocs']
    for field in fields_to_remove:
        if field in cleaned:
            cleaned.pop(field)
    if 'properties' in cleaned:
        cleaned['properties'] = {k: clean_schema_for_display(v) for k, v in cleaned['properties'].items()}
        if not cleaned['properties']:
            cleaned.pop('properties')
    if 'items' in cleaned:
        cleaned['items'] = clean_schema_for_display(cleaned['items'])
        if not cleaned['items']:
            cleaned.pop('items')
    if 'additionalProperties' in cleaned:
        if isinstance(cleaned['additionalProperties'], dict):
            cleaned['additionalProperties'] = clean_schema_for_display(cleaned['additionalProperties'])
        elif cleaned['additionalProperties'] is True:
            pass
    return cleaned

def paginate_sequence(items: Sequence[T], cursor: str | None, page_size: int) -> tuple[list[T], str | None]:
    offset = 0
    if cursor:
        state = CursorState.decode(cursor)
        offset = state.offset
    end = offset + page_size
    page = list(items[offset:end])
    next_cursor = None
    if end < len(items):
        next_cursor = CursorState(offset=end).encode()
    return (page, next_cursor)

# --- helper: fastmcp.utilities.pagination.CursorState ---
@dataclass
class CursorState:
    offset: int

    def encode(self) -> str:
        data = json.dumps({'o': self.offset})
        return base64.urlsafe_b64encode(data.encode()).decode()

    @classmethod
    def decode(cls, cursor: str) -> CursorState:
        try:
            data = json.loads(base64.urlsafe_b64decode(cursor.encode()).decode())
            return cls(offset=data['o'])
        except (json.JSONDecodeError, KeyError, ValueError, TypeError, binascii.Error) as e:
            raise ValueError(f'Invalid cursor: {cursor}') from e

