class Image:

    def __init__(self, path: str | Path | None=None, data: bytes | None=None, format: str | None=None, annotations: Annotations | None=None):
        if path is None and data is None:
            raise ValueError('Either path or data must be provided')
        if path is not None and data is not None:
            raise ValueError('Only one of path or data can be provided')
        self.path = self._get_expanded_path(path)
        self.data = data
        self._format = format
        self._mime_type = self._get_mime_type()
        self.annotations = annotations

    @staticmethod
    def _get_expanded_path(path: str | Path | None) -> Path | None:
        return Path(os.path.expandvars(str(path))).expanduser() if path else None

    def _get_mime_type(self) -> str:
        if self._format:
            return f'image/{self._format.lower()}'
        if self.path:
            mimetypes.add_type('image/webp', '.webp')
            resp = mimetypes.guess_type(self.path, strict=False)
            if resp and resp[0] is not None:
                return resp[0]
            return 'application/octet-stream'
        return 'image/png'

    def _get_data(self) -> str:
        if self.path:
            with open(self.path, 'rb') as f:
                data = base64.b64encode(f.read()).decode()
        elif self.data is not None:
            data = base64.b64encode(self.data).decode()
        else:
            raise ValueError('No image data available')
        return data

    def to_image_content(self, mime_type: str | None=None, annotations: Annotations | None=None) -> mcp.types.ImageContent:
        data = self._get_data()
        return mcp.types.ImageContent(type='image', data=data, mimeType=mime_type or self._mime_type, annotations=annotations or self.annotations)

    def to_data_uri(self, mime_type: str | None=None) -> str:
        data = self._get_data()
        return f'data:{mime_type or self._mime_type};base64,{data}'

