import langgraph.errors

# Example 2: call ErrorCode() and inspect behavior; handle both callable and Enum-case.
# This script shows value lookup and name lookup patterns commonly used with Enums.
try:
    ec = langgraph.errors.ErrorCode()
    print('ErrorCode() returned:', ec)
    # If returned object supports indexing by name (unlikely), try a lookup
    try:
        val = ec['UNKNOWN']
        print("Lookup by name 'UNKNOWN':", val)
    except Exception:
        print("Instance does not support name lookup via __getitem__")
except TypeError:
    # Treat ErrorCode as an Enum class
    EC = langgraph.errors.ErrorCode
    print('Using ErrorCode as Enum class:', EC)
    # Name lookup using bracket-style (EnumClass['NAME']) if members exist
    if hasattr(EC, '__members__') and 'UNKNOWN' in EC.__members__:
        print("EC['UNKNOWN'] =", EC['UNKNOWN'])
    else:
        # Fallback: show all defined members and do a value lookup if numeric values exist
        members = list(EC)
        print('Members:', members)
        if members:
            # value lookup via Enum(value) pattern: use first member's value
            try:
                v = members[0].value
                print('Value lookup EC(%r) ->' % v, EC(v))
            except Exception:
                print('Value lookup not supported')

