def identifier(obj: Any, name: str | None=None) -> str | None:
    from langgraph._internal._runnable import RunnableCallable, RunnableSeq
    from langgraph.pregel._read import PregelNode
    if isinstance(obj, PregelNode):
        obj = obj.bound
    if isinstance(obj, RunnableSeq):
        obj = obj.steps[0]
    if isinstance(obj, RunnableCallable):
        obj = obj.func
    if name is None:
        name = getattr(obj, '__qualname__', None)
    if name is None:
        name = getattr(obj, '__name__', None)
    if name is None:
        return None
    module_name = getattr(obj, '__module__', None)
    if module_name is None:
        return None
    return f'{module_name}.{name}'

class PregelNode:
    channels: str | list[str]
    "The channels that will be passed as input to `bound`.\n    If a str, the node will be invoked with its value if it isn't empty.\n    If a list, the node will be invoked with a dict of those channels' values."
    triggers: list[str]
    'If any of these channels is written to, this node will be triggered in\n    the next step.'
    mapper: Callable[[Any], Any] | None
    'A function to transform the input before passing it to `bound`.'
    writers: list[Runnable]
    'A list of writers that will be executed after `bound`, responsible for\n    taking the output of `bound` and writing it to the appropriate channels.'
    bound: Runnable[Any, Any]
    'The main logic of the node. This will be invoked with the input from \n    `channels`.'
    retry_policy: Sequence[RetryPolicy] | None
    'The retry policies to use when invoking the node.'
    cache_policy: CachePolicy | None
    'The cache policy to use when invoking the node.'
    tags: Sequence[str] | None
    'Tags to attach to the node for tracing.'
    metadata: Mapping[str, Any] | None
    'Metadata to attach to the node for tracing.'
    subgraphs: Sequence[PregelProtocol]
    'Subgraphs used by the node.'

    def __init__(self, *, channels: str | list[str], triggers: Sequence[str], mapper: Callable[[Any], Any] | None=None, writers: list[Runnable] | None=None, tags: list[str] | None=None, metadata: Mapping[str, Any] | None=None, bound: Runnable[Any, Any] | None=None, retry_policy: RetryPolicy | Sequence[RetryPolicy] | None=None, cache_policy: CachePolicy | None=None, subgraphs: Sequence[PregelProtocol] | None=None) -> None:
        self.channels = channels
        self.triggers = list(triggers)
        self.mapper = mapper
        self.writers = writers or []
        self.bound = bound if bound is not None else DEFAULT_BOUND
        self.cache_policy = cache_policy
        if isinstance(retry_policy, RetryPolicy):
            self.retry_policy = (retry_policy,)
        else:
            self.retry_policy = retry_policy
        self.tags = tags
        self.metadata = metadata
        if subgraphs is not None:
            self.subgraphs = subgraphs
        elif self.bound is not DEFAULT_BOUND:
            try:
                subgraph = find_subgraph_pregel(self.bound)
            except Exception:
                subgraph = None
            if subgraph:
                self.subgraphs = [subgraph]
            else:
                self.subgraphs = []
        else:
            self.subgraphs = []

    def copy(self, update: dict[str, Any]) -> PregelNode:
        attrs = {**self.__dict__, **update}
        attrs.pop('flat_writers', None)
        attrs.pop('node', None)
        attrs.pop('input_cache_key', None)
        return PregelNode(**attrs)

    @cached_property
    def flat_writers(self) -> list[Runnable]:
        writers = self.writers.copy()
        while len(writers) > 1 and isinstance(writers[-1], ChannelWrite) and isinstance(writers[-2], ChannelWrite):
            writers[-2] = ChannelWrite(writes=writers[-2].writes + writers[-1].writes)
            writers.pop()
        return writers

    @cached_property
    def node(self) -> Runnable[Any, Any] | None:
        writers = self.flat_writers
        if self.bound is DEFAULT_BOUND and (not writers):
            return None
        elif self.bound is DEFAULT_BOUND and len(writers) == 1:
            return writers[0]
        elif self.bound is DEFAULT_BOUND:
            return RunnableSeq(*writers)
        elif writers:
            return RunnableSeq(self.bound, *writers)
        else:
            return self.bound

    @cached_property
    def input_cache_key(self) -> INPUT_CACHE_KEY_TYPE:
        return (self.mapper, tuple(self.channels) if isinstance(self.channels, list) else (self.channels,))

    def invoke(self, input: Any, config: RunnableConfig | None=None, **kwargs: Any | None) -> Any:
        self_config: RunnableConfig = {'metadata': self.metadata, 'tags': self.tags}
        return self.bound.invoke(input, merge_configs(self_config, config), **kwargs)

    async def ainvoke(self, input: Any, config: RunnableConfig | None=None, **kwargs: Any | None) -> Any:
        self_config: RunnableConfig = {'metadata': self.metadata, 'tags': self.tags}
        return await self.bound.ainvoke(input, merge_configs(self_config, config), **kwargs)

    def stream(self, input: Any, config: RunnableConfig | None=None, **kwargs: Any | None) -> Iterator[Any]:
        self_config: RunnableConfig = {'metadata': self.metadata, 'tags': self.tags}
        yield from self.bound.stream(input, merge_configs(self_config, config), **kwargs)

    async def astream(self, input: Any, config: RunnableConfig | None=None, **kwargs: Any | None) -> AsyncIterator[Any]:
        self_config: RunnableConfig = {'metadata': self.metadata, 'tags': self.tags}
        async for item in self.bound.astream(input, merge_configs(self_config, config), **kwargs):
            yield item

