def task(__func_or_none__: Callable[P, Awaitable[T]] | Callable[P, T] | None=None, *, name: str | None=None, retry_policy: RetryPolicy | Sequence[RetryPolicy] | None=None, cache_policy: CachePolicy[Callable[P, str | bytes]] | None=None, **kwargs: Unpack[DeprecatedKwargs]) -> Callable[[Callable[P, Awaitable[T]] | Callable[P, T]], _TaskFunction[P, T]] | _TaskFunction[P, T]:
    if (retry := kwargs.get('retry', MISSING)) is not MISSING:
        warnings.warn('`retry` is deprecated and will be removed. Please use `retry_policy` instead.', category=LangGraphDeprecatedSinceV05, stacklevel=2)
        if retry_policy is None:
            retry_policy = retry
    retry_policies: Sequence[RetryPolicy] = () if retry_policy is None else (retry_policy,) if isinstance(retry_policy, RetryPolicy) else retry_policy

    def decorator(func: Callable[P, Awaitable[T]] | Callable[P, T]) -> Callable[P, SyncAsyncFuture[T]]:
        return _TaskFunction(func, retry_policy=retry_policies, cache_policy=cache_policy, name=name)
    if __func_or_none__ is not None:
        return decorator(__func_or_none__)
    return decorator

# --- helper: langgraph.func._TaskFunction ---
class _TaskFunction(Generic[P, T]):

    def __init__(self, func: Callable[P, Awaitable[T]] | Callable[P, T], *, retry_policy: Sequence[RetryPolicy], cache_policy: CachePolicy[Callable[P, str | bytes]] | None=None, name: str | None=None) -> None:
        if name is not None:
            if hasattr(func, '__func__'):
                instance_method = functools.partial(func.__func__, func.__self__)
                instance_method.__name__ = name
                func = instance_method
            else:
                func.__name__ = name
        self.func = func
        self.retry_policy = retry_policy
        self.cache_policy = cache_policy
        functools.update_wrapper(self, func)

    def __call__(self, *args: P.args, **kwargs: P.kwargs) -> SyncAsyncFuture[T]:
        return call(self.func, *args, retry_policy=self.retry_policy, cache_policy=self.cache_policy, **kwargs)

    def clear_cache(self, cache: BaseCache) -> None:
        if self.cache_policy is not None:
            cache.clear(((CACHE_NS_WRITES, identifier(self.func) or '__dynamic__'),))

    async def aclear_cache(self, cache: BaseCache) -> None:
        if self.cache_policy is not None:
            await cache.aclear(((CACHE_NS_WRITES, identifier(self.func) or '__dynamic__'),))

