class ChannelRead(RunnableCallable):
    channel: str | list[str]
    fresh: bool = False
    mapper: Callable[[Any], Any] | None = None

    def __init__(self, channel: str | list[str], *, fresh: bool=False, mapper: Callable[[Any], Any] | None=None, tags: list[str] | None=None) -> None:
        super().__init__(func=self._read, afunc=self._aread, tags=tags, name=None, trace=False)
        self.fresh = fresh
        self.mapper = mapper
        self.channel = channel

    def get_name(self, suffix: str | None=None, *, name: str | None=None) -> str:
        if name:
            pass
        elif isinstance(self.channel, str):
            name = f'ChannelRead<{self.channel}>'
        else:
            name = f"ChannelRead<{','.join(self.channel)}>"
        return super().get_name(suffix, name=name)

    def _read(self, _: Any, config: RunnableConfig) -> Any:
        return self.do_read(config, select=self.channel, fresh=self.fresh, mapper=self.mapper)

    async def _aread(self, _: Any, config: RunnableConfig) -> Any:
        return self.do_read(config, select=self.channel, fresh=self.fresh, mapper=self.mapper)

    @staticmethod
    def do_read(config: RunnableConfig, *, select: str | list[str], fresh: bool=False, mapper: Callable[[Any], Any] | None=None) -> Any:
        try:
            read: READ_TYPE = config[CONF][CONFIG_KEY_READ]
        except KeyError:
            raise RuntimeError('Not configured with a read functionMake sure to call in the context of a Pregel process')
        if mapper:
            return mapper(read(select, fresh))
        else:
            return read(select, fresh)

class RemoveUIMessage(TypedDict):
    type: Literal['remove-ui']
    id: str

def ui_message_reducer(left: list[AnyUIMessage] | AnyUIMessage, right: list[AnyUIMessage] | AnyUIMessage) -> list[AnyUIMessage]:
    if not isinstance(left, list):
        left = [left]
    if not isinstance(right, list):
        right = [right]
    merged = left.copy()
    merged_by_id = {m.get('id'): i for i, m in enumerate(merged)}
    ids_to_remove = set()
    for msg in right:
        msg_id = msg.get('id')
        if (existing_idx := merged_by_id.get(msg_id)) is not None:
            if msg.get('type') == 'remove-ui':
                ids_to_remove.add(msg_id)
            else:
                ids_to_remove.discard(msg_id)
                if cast(UIMessage, msg).get('metadata', {}).get('merge', False):
                    prev_msg = merged[existing_idx]
                    msg = msg.copy()
                    msg['props'] = {**prev_msg['props'], **msg['props']}
                merged[existing_idx] = msg
        else:
            if msg.get('type') == 'remove-ui':
                raise ValueError(f"Attempting to delete an UI message with an ID that doesn't exist ('{msg_id}')")
            merged_by_id[msg_id] = len(merged)
            merged.append(msg)
    merged = [m for m in merged if m.get('id') not in ids_to_remove]
    return merged

