@deprecated('ValidationNode is deprecated. Please use `create_agent` from `langchain.agents` with custom tool error handling.', category=LangGraphDeprecatedSinceV10)
class ValidationNode(RunnableCallable):

    def __init__(self, schemas: Sequence[BaseTool | type[BaseModel] | Callable], *, format_error: Callable[[BaseException, ToolCall, type[BaseModel]], str] | None=None, name: str='validation', tags: list[str] | None=None) -> None:
        super().__init__(self._func, None, name=name, tags=tags, trace=False)
        self._format_error = format_error or _default_format_error
        self.schemas_by_name: dict[str, type[BaseModel]] = {}
        for schema in schemas:
            if isinstance(schema, BaseTool):
                if schema.args_schema is None:
                    raise ValueError(f'Tool {schema.name} does not have an args_schema defined.')
                elif not isinstance(schema.args_schema, type) or not is_basemodel_subclass(schema.args_schema):
                    raise ValueError(f'Validation node only works with tools that have a pydantic BaseModel args_schema. Got {schema.name} with args_schema: {schema.args_schema}.')
                self.schemas_by_name[schema.name] = schema.args_schema
            elif isinstance(schema, type) and issubclass(schema, (BaseModel, BaseModelV1)):
                self.schemas_by_name[schema.__name__] = cast(type[BaseModel], schema)
            elif callable(schema):
                base_model = create_schema_from_function('Validation', schema)
                self.schemas_by_name[schema.__name__] = base_model
            else:
                raise ValueError(f'Unsupported input to ValidationNode. Expected BaseModel, tool or function. Got: {type(schema)}.')

    def _get_message(self, input: list[AnyMessage] | dict[str, Any]) -> tuple[str, AIMessage]:
        if isinstance(input, list):
            output_type = 'list'
            messages: list = input
        elif (messages := input.get('messages', [])):
            output_type = 'dict'
        else:
            raise ValueError('No message found in input')
        message: AnyMessage = messages[-1]
        if not isinstance(message, AIMessage):
            raise ValueError('Last message is not an AIMessage')
        return (output_type, message)

    def _func(self, input: list[AnyMessage] | dict[str, Any], config: RunnableConfig) -> Any:
        output_type, message = self._get_message(input)

        def run_one(call: ToolCall) -> ToolMessage:
            schema = self.schemas_by_name[call['name']]
            try:
                if issubclass(schema, BaseModel):
                    output = schema.model_validate(call['args'])
                    content = output.model_dump_json()
                elif issubclass(schema, BaseModelV1):
                    output = schema.validate(call['args'])
                    content = output.json()
                else:
                    raise ValueError(f'Unsupported schema type: {type(schema)}. Expected BaseModel or BaseModelV1.')
                return ToolMessage(content=content, name=call['name'], tool_call_id=cast(str, call['id']))
            except (ValidationError, ValidationErrorV1) as e:
                return ToolMessage(content=self._format_error(e, call, schema), name=call['name'], tool_call_id=cast(str, call['id']), additional_kwargs={'is_error': True})
        with get_executor_for_config(config) as executor:
            outputs = [*executor.map(run_one, message.tool_calls)]
            if output_type == 'list':
                return outputs
            else:
                return {'messages': outputs}

# --- helper: langgraph.prebuilt.tool_validator._default_format_error ---
def _default_format_error(error: BaseException, call: ToolCall, schema: type[BaseModel] | type[BaseModelV1]) -> str:
    return f'{repr(error)}\n\nRespond after fixing all validation errors.'

