def tools_condition(state: list[AnyMessage] | dict[str, Any] | BaseModel, messages_key: str='messages') -> Literal['tools', '__end__']:
    if isinstance(state, list):
        ai_message = state[-1]
    elif isinstance(state, dict) and (messages := state.get(messages_key, [])) or (messages := getattr(state, messages_key, [])):
        ai_message = messages[-1]
    else:
        msg = f'No messages found in input state to tool_edge: {state}'
        raise ValueError(msg)
    if hasattr(ai_message, 'tool_calls') and len(ai_message.tool_calls) > 0:
        return 'tools'
    return '__end__'

def map_debug_tasks(tasks: Iterable[PregelExecutableTask]) -> Iterator[TaskPayload]:
    for task in tasks:
        if task.config is not None and TAG_HIDDEN in task.config.get('tags', []):
            continue
        yield {'id': task.id, 'name': task.name, 'input': task.input, 'triggers': task.triggers}

def map_debug_checkpoint(config: RunnableConfig, channels: Mapping[str, BaseChannel], stream_channels: str | Sequence[str], metadata: CheckpointMetadata, tasks: Iterable[PregelExecutableTask], pending_writes: list[PendingWrite], parent_config: RunnableConfig | None, output_keys: str | Sequence[str]) -> Iterator[CheckpointPayload]:
    parent_ns = config[CONF].get(CONFIG_KEY_CHECKPOINT_NS, '')
    task_states: dict[str, RunnableConfig | StateSnapshot] = {}
    for task in tasks:
        if not task.subgraphs:
            continue
        task_ns = f'{task.name}{NS_END}{task.id}'
        if parent_ns:
            task_ns = f'{parent_ns}{NS_SEP}{task_ns}'
        task_states[task.id] = {CONF: {'thread_id': config[CONF]['thread_id'], CONFIG_KEY_CHECKPOINT_NS: task_ns}}
    yield {'config': rm_pregel_keys(patch_checkpoint_map(config, metadata)), 'parent_config': rm_pregel_keys(patch_checkpoint_map(parent_config, metadata)), 'values': read_channels(channels, stream_channels), 'metadata': metadata, 'next': [t.name for t in tasks], 'tasks': [{'id': t.id, 'name': t.name, 'error': t.error, 'state': t.state} if t.error else {'id': t.id, 'name': t.name, 'result': t.result, 'interrupts': tuple((asdict(i) for i in t.interrupts)), 'state': t.state} if t.result else {'id': t.id, 'name': t.name, 'interrupts': tuple((asdict(i) for i in t.interrupts)), 'state': t.state} for t in tasks_w_writes(tasks, pending_writes, task_states, output_keys)]}

# --- helper: langgraph.pregel.debug.rm_pregel_keys ---
def rm_pregel_keys(config: RunnableConfig | None) -> RunnableConfig | None:
    if config is None:
        return config
    return {'configurable': {k: v for k, v in config.get('configurable', {}).items() if not k.startswith('__pregel_')}}

# --- helper: langgraph.pregel.debug.tasks_w_writes ---
def tasks_w_writes(tasks: Iterable[PregelTask | PregelExecutableTask], pending_writes: list[PendingWrite] | None, states: dict[str, RunnableConfig | StateSnapshot] | None, output_keys: str | Sequence[str]) -> tuple[PregelTask, ...]:
    pending_writes = pending_writes or []
    out: list[PregelTask] = []
    for task in tasks:
        rtn = next((val for tid, chan, val in pending_writes if tid == task.id and chan == RETURN), MISSING)
        task_error = next((exc for tid, n, exc in pending_writes if tid == task.id and n == ERROR), None)
        task_interrupts = tuple((v for tid, n, vv in pending_writes if tid == task.id and n == INTERRUPT for v in (vv if isinstance(vv, Sequence) else [vv])))
        task_writes = [(chan, val) for tid, chan, val in pending_writes if tid == task.id and chan not in (ERROR, INTERRUPT, RETURN)]
        if rtn is not MISSING:
            task_result = rtn
        elif isinstance(output_keys, str):
            filtered_writes = [(chan, val) for chan, val in task_writes if chan == output_keys]
            mapped_writes = map_task_result_writes(filtered_writes)
            task_result = mapped_writes.get(str(output_keys)) if mapped_writes else None
        else:
            if isinstance(output_keys, str):
                output_keys = [output_keys]
            filtered_writes = [(chan, val) for chan, val in task_writes if chan in output_keys]
            mapped_writes = map_task_result_writes(filtered_writes)
            task_result = mapped_writes if filtered_writes else {}
        has_writes = rtn is not MISSING or any((w[0] == task.id and w[1] not in (ERROR, INTERRUPT) for w in pending_writes))
        out.append(PregelTask(task.id, task.name, task.path, task_error, task_interrupts, states.get(task.id) if states else None, task_result if has_writes else None))
    return tuple(out)

