class Send:
    __slots__ = ('node', 'arg')
    node: str
    arg: Any

    def __init__(self, /, node: str, arg: Any) -> None:
        self.node = node
        self.arg = arg

    def __hash__(self) -> int:
        return hash((self.node, self.arg))

    def __repr__(self) -> str:
        return f'Send(node={self.node!r}, arg={self.arg!r})'

    def __eq__(self, value: object) -> bool:
        return isinstance(value, Send) and self.node == value.node and (self.arg == value.arg)

@dataclass(frozen=True)
class GraphOutput(Generic[OutputT]):
    value: OutputT
    interrupts: tuple[Interrupt, ...] = ()

    def __getitem__(self, key: str) -> Any:
        warn('Accessing GraphOutput via `result[key]` is deprecated. Use `result.value` to access the output value directly, or `result.interrupts` for interrupts.', LangGraphDeprecatedSinceV11, stacklevel=2)
        if key == _INTERRUPT_KEY:
            return self.interrupts
        if isinstance(self.value, dict):
            return self.value[key]
        try:
            return getattr(self.value, key)
        except AttributeError:
            raise KeyError(key)

    def __contains__(self, key: object) -> bool:
        warn('Accessing GraphOutput via `key in result` is deprecated. Use `result.value` to access the output value directly, or `result.interrupts` for interrupts.', LangGraphDeprecatedSinceV11, stacklevel=2)
        if key == _INTERRUPT_KEY:
            return bool(self.interrupts)
        if isinstance(self.value, dict):
            return key in self.value
        return isinstance(key, str) and hasattr(self.value, key)

