class NucPairDist(AnalysisBase):
    _analysis_algorithm_is_parallelizable = True

    @classmethod
    def get_supported_backends(cls):
        return ('serial', 'multiprocessing', 'dask')
    _s1: mda.AtomGroup
    _s2: mda.AtomGroup
    _n_sel: int

    def __init__(self, selection1: List[mda.AtomGroup], selection2: List[mda.AtomGroup], **kwargs) -> None:
        super(NucPairDist, self).__init__(selection1[0].universe.trajectory, **kwargs)
        if len(selection1) != len(selection2):
            raise ValueError('Selections must be same length')
        self._n_sel: int = len(selection1)
        self._s1 = selection1[0]
        self._s2 = selection2[0]
        for i in range(1, self._n_sel):
            self._s1 += selection1[i]
            self._s2 += selection2[i]

    @staticmethod
    def select_strand_atoms(strand1: ResidueGroup, strand2: ResidueGroup, a1_name: str, a2_name: str, g_name: str='G', a_name: str='A', u_name: str='U', t_name: str='T', c_name: str='C') -> Tuple[List[mda.AtomGroup], List[mda.AtomGroup]]:
        pyrimidines: List[str] = [c_name, t_name, u_name]
        purines: List[str] = [a_name, g_name]
        sel1: List[mda.AtomGroup] = []
        sel2: List[mda.AtomGroup] = []
        for pair in zip(strand1.residues, strand2.residues):
            if pair[0].resname[0] in pyrimidines:
                a1, a2 = (a2_name, a1_name)
            elif pair[0].resname[0] in purines:
                a1, a2 = (a1_name, a2_name)
            else:
                raise ValueError(f'AtomGroup in {pair} is not a valid nucleic acid')
            ag1 = pair[0].atoms.select_atoms(f'name {a1}')
            ag2 = pair[1].atoms.select_atoms(f'name {a2}')
            if not all((len(ag) > 0 for ag in [ag1, ag2])):
                err_info: Tuple[Residue, str] = (pair[0], a1) if len(ag1) == 0 else (pair[1], a2)
                raise ValueError(f'{err_info[0]} returns an empty AtomGroupwith selection string "name {{a2}}"')
            sel1.append(ag1)
            sel2.append(ag2)
        return (sel1, sel2)

    def _prepare(self) -> None:
        self.results.distances: np.ndarray = np.zeros([self.n_frames, self._n_sel])

    def _single_frame(self) -> None:
        dist: np.ndarray = calc_bonds(self._s1.positions, self._s2.positions)
        self.results.distances[self._frame_index, :] = dist

    def _conclude(self) -> None:
        self.results['pair_distances'] = self.results['distances']

    def _get_aggregator(self):
        return ResultsGroup(lookup={'distances': ResultsGroup.ndarray_vstack})

@dataclass(frozen=True)
class MDAnalysisInferrer:
    MONATOMIC_CATION_CHARGES: ClassVar[Dict[int, int]] = {3: 1, 11: 1, 19: 1, 37: 1, 47: 1, 55: 1, 12: 2, 20: 2, 29: 2, 30: 2, 38: 2, 56: 2, 26: 2, 13: 3}
    STANDARDIZATION_REACTIONS: ClassVar[List[str]] = ['[C-;X2;H0:1]=[O:2]>>[C+0:1]=[O:2]', '[N-;X2;H1;$(N-[*^3]):1]>>[N+0:1]', '[#6-:1]-[#6:2]=[O:3]>>[#6+0:1]=[#6:2]-[O-:3]', '[C-;v3:1]-[#7+0;v3;H2:2]>>[#6+0:1]=[#7+:2]', '[#6+0;H0:1]=[#6+0:2]-[#7;X3:3]-[#6-;X3:4]>>[#6:1]=[#6:2]-[#7+:3]=[#6+0:4]', '[S;D4;!v6:1]-[*-:2]>>[S;v6:1]=[*+0:2]', '[#7+0;X3:1]-[*-:2]>>[#7+:1]=[*+0:2]']
    max_iter: int = 200
    sanitize: bool = True

    def __call__(self, mol: 'Chem.Mol') -> 'Chem.Mol':
        self._infer_bo_and_charges(mol)
        mol = self._standardize_patterns(mol)
        mol = reorder_atoms(mol)
        if self.sanitize:
            sanitize_mol(mol)
        return mol

    @classmethod
    def _atom_sorter(cls, atom: 'Chem.Atom') -> Tuple[int, int]:
        num_heavy_neighbors = len([neighbor for neighbor in atom.GetNeighbors() if neighbor.GetAtomicNum() > 1])
        return (-cls._get_nb_unpaired_electrons(atom)[0], num_heavy_neighbors)

    @classmethod
    def _infer_bo_and_charges(cls, mol: 'Chem.Mol') -> None:
        atoms = sorted([atom for atom in mol.GetAtoms() if atom.GetAtomicNum() > 1], key=cls._atom_sorter)
        for atom in atoms:
            if atom.GetDegree() == 0:
                atom.SetFormalCharge(cls.MONATOMIC_CATION_CHARGES.get(atom.GetAtomicNum(), -cls._get_nb_unpaired_electrons(atom)[0]))
                mol.UpdatePropertyCache(strict=False)
                continue
            nue = cls._get_nb_unpaired_electrons(atom)
            if len(nue) == 1 and nue[0] < 0:
                atom.SetFormalCharge(-nue[0])
                mol.UpdatePropertyCache(strict=False)
            if len(nue) == 1 and nue[0] <= 0:
                continue
            neighbors = sorted(atom.GetNeighbors(), reverse=True, key=lambda a: cls._get_nb_unpaired_electrons(a)[0])
            for na in neighbors:
                na_nue = cls._get_nb_unpaired_electrons(na)
                common_nue = min([i for i in [*nue, *na_nue] if i >= 0], default=0)
                if common_nue != 0:
                    bond = mol.GetBondBetweenAtoms(atom.GetIdx(), na.GetIdx())
                    order = common_nue + 1
                    bond.SetBondType(RDBONDORDER[order])
                    mol.UpdatePropertyCache(strict=False)
                    nue = cls._get_nb_unpaired_electrons(atom)
                    if any((n == 0 for n in nue)):
                        break
            nue = cls._get_nb_unpaired_electrons(atom)
            if not any((n == 0 for n in nue)):
                atom.SetFormalCharge(-nue[0])
                atom.SetNumRadicalElectrons(0)
                mol.UpdatePropertyCache(strict=False)

    @staticmethod
    def _get_nb_unpaired_electrons(atom: 'Chem.Atom') -> List[int]:
        expected_vs = PERIODIC_TABLE.GetValenceList(atom.GetAtomicNum())
        current_v = atom.GetTotalValence() - atom.GetFormalCharge()
        return [v - current_v for v in expected_vs]

    def _standardize_patterns(self, mol: 'Chem.Mol', max_iter: Optional[int]=None) -> 'Chem.Mol':
        if max_iter is None:
            max_iter = self.max_iter
        else:
            warnings.warn('Specifying `max_iter` is deprecated and will be removed in a future update. Directly create an instance of `MDAnalysisInferrer` with `MDAnalysisInferrer(max_iter=...)` instead.', DeprecationWarning)
        self._rebuild_conjugated_bonds(mol, max_iter)
        reactions = [ReactionFromSmarts(rxn) for rxn in self.STANDARDIZATION_REACTIONS]
        fragments = list(Chem.GetMolFrags(mol, asMols=True, sanitizeFrags=self.sanitize))
        for reactant in fragments:
            self._apply_reactions(reactions, reactant)
        newmol = fragments.pop(0)
        for fragment in fragments:
            newmol = Chem.CombineMols(newmol, fragment)
        return newmol

    @staticmethod
    def _apply_reactions(reactions: List['ChemicalReaction'], reactant: 'Chem.Mol') -> None:
        reactant.UpdatePropertyCache(strict=False)
        Chem.KekulizeIfPossible(reactant)
        for reaction in reactions:
            while reaction.RunReactantInPlace(reactant):
                reactant.UpdatePropertyCache(strict=False)
            reactant.UpdatePropertyCache(strict=False)
            Chem.KekulizeIfPossible(reactant)

    def _rebuild_conjugated_bonds(self, mol: 'Chem.Mol', max_iter: Optional[int]=None) -> None:
        max_iter = self.max_iter if max_iter is None else max_iter
        mol.UpdatePropertyCache(strict=False)
        Chem.KekulizeIfPossible(mol)
        pattern = Chem.MolFromSmarts('[*-{1-2}]-,=[*+0]=,#[*+0]')
        base_end_pattern = Chem.MolFromSmarts('[*-{1-2}]-,=[*+0]=,#[*+0]-,=[*-{1-2}]')
        odd_end_pattern = Chem.MolFromSmarts('[*-]-[*+0]=[*+0]-[*-,$([#7;X3;v3]),$([#6+0,#7+1]=O),$([S;D4;v4]-[O-])]')
        n_matches = len({match[0] for match in mol.GetSubstructMatches(pattern)})
        if n_matches == 0:
            return
        if n_matches == 1:
            end_pattern = odd_end_pattern
        else:
            end_pattern = base_end_pattern
        backtrack = []
        backtrack_cycles = 0
        for _ in range(max_iter):
            end_match = mol.GetSubstructMatch(end_pattern)
            if end_match:
                anion1, a1, a2, anion2 = end_match
                term_atom = mol.GetAtomWithIdx(anion2)
                if term_atom.GetAtomicNum() == 6 and term_atom.GetFormalCharge() == 0 or (term_atom.GetAtomicNum() == 7 and term_atom.GetFormalCharge() == 1):
                    for neighbor in term_atom.GetNeighbors():
                        bond = mol.GetBondBetweenAtoms(anion2, neighbor.GetIdx())
                        if neighbor.GetAtomicNum() == 8 and bond.GetBondTypeAsDouble() == 2:
                            bond.SetBondType(Chem.BondType.SINGLE)
                            neighbor.SetFormalCharge(-1)
                            break
                elif term_atom.GetAtomicNum() == 16 and term_atom.GetFormalCharge() == 0:
                    for neighbor in term_atom.GetNeighbors():
                        bond = mol.GetBondBetweenAtoms(anion2, neighbor.GetIdx())
                        if neighbor.GetAtomicNum() == 8 and neighbor.GetFormalCharge() == -1 and (bond.GetBondTypeAsDouble() == 1):
                            bond.SetBondType(Chem.BondType.DOUBLE)
                            neighbor.SetFormalCharge(0)
                            break
                else:
                    term_atom.SetFormalCharge(term_atom.GetFormalCharge() + 1)
                a = mol.GetAtomWithIdx(anion1)
                a.SetFormalCharge(a.GetFormalCharge() + 1)
                b = mol.GetBondBetweenAtoms(anion1, a1)
                b.SetBondType(RDBONDORDER[b.GetBondTypeAsDouble() + 1])
                b = mol.GetBondBetweenAtoms(a1, a2)
                b.SetBondType(RDBONDORDER[b.GetBondTypeAsDouble() - 1])
                b = mol.GetBondBetweenAtoms(a2, anion2)
                b.SetBondType(RDBONDORDER[b.GetBondTypeAsDouble() + 1])
                mol.UpdatePropertyCache(strict=False)
                continue
            matches = mol.GetSubstructMatches(pattern)
            if matches:
                for match in matches:
                    g = set(match)
                    if g in backtrack:
                        continue
                    anion, a1, a2 = match
                    backtrack.append(g)
                    break
                else:
                    if backtrack_cycles == 1:
                        end_pattern = odd_end_pattern
                    elif backtrack_cycles > 1:
                        mol.UpdatePropertyCache(strict=False)
                        return
                    match = matches[0]
                    anion, a1, a2 = match
                    backtrack = [set(match)]
                    backtrack_cycles += 1
                a = mol.GetAtomWithIdx(anion)
                a.SetFormalCharge(a.GetFormalCharge() + 1)
                a = mol.GetAtomWithIdx(a2)
                a.SetFormalCharge(a.GetFormalCharge() - 1)
                b = mol.GetBondBetweenAtoms(anion, a1)
                b.SetBondType(RDBONDORDER[b.GetBondTypeAsDouble() + 1])
                b = mol.GetBondBetweenAtoms(a1, a2)
                b.SetBondType(RDBONDORDER[b.GetBondTypeAsDouble() - 1])
                mol.UpdatePropertyCache(strict=False)
                n_matches = len({match[0] for match in matches})
                if n_matches == 1:
                    end_pattern = odd_end_pattern
                continue
            mol.UpdatePropertyCache(strict=False)
            return
        warnings.warn('The standardization could not be completed within a reasonable number of iterations')

