class WaterSelection(Selection):
    token = 'water'
    water_res = {'H2O', 'HOH', 'OH2', 'HHO', 'OHH', 'T3P', 'T4P', 'T5P', 'SOL', 'WAT', 'TIP', 'TIP2', 'TIP3', 'TIP4'}

    def _apply(self, group):
        resnames = group.universe._topology.resnames
        nmidx = resnames.nmidx[group.resindices]
