class DefaultGuesser(GuesserBase):
    context = 'default'

    def __init__(self, universe, box=None, vdwradii=None, fudge_factor=0.55, lower_bound=0.1, **kwargs):
        super().__init__(universe, box=box, vdwradii=vdwradii, fudge_factor=fudge_factor, lower_bound=lower_bound, **kwargs)
        self._guesser_methods = {'masses': self.guess_masses, 'types': self.guess_types, 'elements': self.guess_types, 'bonds': self.guess_bonds, 'angles': self.guess_angles, 'dihedrals': self.guess_dihedrals, 'impropers': self.guess_improper_dihedrals, 'aromaticities': self.guess_aromaticities}

    def guess_masses(self, atom_types=None, indices_to_guess=None):
        if atom_types is None:
            try:
                atom_types = self._universe.atoms.elements
            except NoDataError:
                try:
                    atom_types = self._universe.atoms.types
                except NoDataError:
                    try:
                        atom_types = self.guess_types(atom_types=self._universe.atoms.names)
                    except NoDataError:
                        raise NoDataError('there is no reference attributes (elements, types, or names) in this universe to guess mass from') from None
        if indices_to_guess is not None:
            atom_types = atom_types[indices_to_guess]
        masses = np.array([self.get_atom_mass(atom) for atom in atom_types], dtype=np.float64)
        return masses

    def get_atom_mass(self, element):
        try:
            return tables.masses[element]
        except KeyError:
            try:
                return tables.masses[element.upper()]
            except KeyError:
                warnings.warn("Unknown masses are set to 0.0 for current version, this will be deprecated in version 3.0.0 and replaced by Masse's no_value_label (np.nan)", PendingDeprecationWarning)
                return 0.0

    def guess_atom_mass(self, atomname):
        return self.get_atom_mass(self.guess_atom_element(atomname))

    def guess_types(self, atom_types=None, indices_to_guess=None):
        if atom_types is None:
            try:
                atom_types = self._universe.atoms.names
            except NoDataError:
                raise NoDataError('there is no reference attributes in this universe to guess types from') from None
        if indices_to_guess is not None:
            atom_types = atom_types[indices_to_guess]
        return np.array([self.guess_atom_element(atom) for atom in atom_types], dtype=object)

    def guess_atom_element(self, atomname):
        NUMBERS = re.compile('[0-9]')
        SYMBOLS = re.compile('[*+-]')
        if atomname == '':
            return ''
        try:
            return tables.atomelements[atomname.upper()]
        except KeyError:
            no_symbols = re.sub(SYMBOLS, '', atomname)
            name = re.sub(NUMBERS, '', no_symbols).upper()
            if name in tables.atomelements:
                return tables.atomelements[name]
            while name:
                if name in tables.elements:
                    return name
                if name[:-1] in tables.elements:
                    return name[:-1]
                if name[1:] in tables.elements:
                    return name[1:]
                if len(name) <= 2:
                    return name[0]
                name = name[:-1]
            return no_symbols

    def guess_bonds(self, atoms=None, coords=None):
        if atoms is None:
            atoms = self._universe.atoms
        if coords is None:
            coords = self._universe.atoms.positions
        if len(atoms) != len(coords):
            raise ValueError("'atoms' and 'coord' must be the same length")
        fudge_factor = self._kwargs.get('fudge_factor', 0.55)
        vdwradii = tables.vdwradii.copy()
        user_vdwradii = self._kwargs.get('vdwradii', None)
        if user_vdwradii:
            vdwradii.update(user_vdwradii)
        if hasattr(atoms, 'types'):
            atomtypes = atoms.types
        else:
            atomtypes = self.guess_types(atom_types=atoms.names)
        if not all((val in vdwradii for val in set(atomtypes))):
            raise ValueError('vdw radii for types: ' + ', '.join([t for t in set(atomtypes) if t not in vdwradii]) + '. These can be defined manually using the' + f" keyword 'vdwradii'")
        lower_bound = self._kwargs.get('lower_bound', 0.1)
        box = self._kwargs.get('box', None)
        if box is not None:
            box = np.asarray(box)
        max_vdw = max([vdwradii[t] for t in atomtypes])
        bonds = []
        pairs, dist = distances.self_capped_distance(coords, max_cutoff=2.0 * max_vdw, min_cutoff=lower_bound, box=box)
        for idx, (i, j) in enumerate(pairs):
            d = (vdwradii[atomtypes[i]] + vdwradii[atomtypes[j]]) * fudge_factor
            if dist[idx] < d:
                bonds.append((atoms[i].index, atoms[j].index))
        return tuple(bonds)

    def guess_angles(self, bonds=None):
        from ..core.universe import Universe
        angles_found = set()
        if bonds is None:
            if hasattr(self._universe.atoms, 'bonds'):
                bonds = self._universe.atoms.bonds
            else:
                temp_u = Universe.empty(n_atoms=len(self._universe.atoms))
                temp_u.add_bonds(self.guess_bonds(self._universe.atoms, self._universe.atoms.positions))
                bonds = temp_u.atoms.bonds
        for b in bonds:
            for atom in b:
                other_a = b.partner(atom)
                for other_b in atom.bonds:
                    if other_b != b:
                        third_a = other_b.partner(atom)
                        desc = tuple([other_a.index, atom.index, third_a.index])
                        if desc[0] > desc[-1]:
                            desc = desc[::-1]
                        angles_found.add(desc)
        return tuple(angles_found)

    def guess_dihedrals(self, angles=None):
        from ..core.universe import Universe
        if angles is None:
            if hasattr(self._universe.atoms, 'angles'):
                angles = self._universe.atoms.angles
            else:
                temp_u = Universe.empty(n_atoms=len(self._universe.atoms))
                temp_u.add_bonds(self.guess_bonds(self._universe.atoms, self._universe.atoms.positions))
                temp_u.add_angles(self.guess_angles(temp_u.atoms.bonds))
                angles = temp_u.atoms.angles
        dihedrals_found = set()
        for b in angles:
            a_tup = tuple([a.index for a in b])
            for atom, prefix in zip([b.atoms[0], b.atoms[-1]], [a_tup[::-1], a_tup]):
                for other_b in atom.bonds:
                    if not other_b.partner(atom) in b:
                        third_a = other_b.partner(atom)
                        desc = prefix + (third_a.index,)
                        if desc[0] > desc[-1]:
                            desc = desc[::-1]
                        dihedrals_found.add(desc)
        return tuple(dihedrals_found)

    def guess_improper_dihedrals(self, angles=None):
        from ..core.universe import Universe
        if angles is None:
            if hasattr(self._universe.atoms, 'angles'):
                angles = self._universe.atoms.angles
            else:
                temp_u = Universe.empty(n_atoms=len(self._universe.atoms))
                temp_u.add_bonds(self.guess_bonds(self._universe.atoms, self._universe.atoms.positions))
                temp_u.add_angles(self.guess_angles(temp_u.atoms.bonds))
                angles = temp_u.atoms.angles
        dihedrals_found = set()
        for b in angles:
            atom = b[1]
            a_tup = tuple([b[a].index for a in [1, 2, 0]])
            for other_b in atom.bonds:
                other_atom = other_b.partner(atom)
                if other_atom not in b:
                    desc = a_tup + (other_atom.index,)
                    if desc[0] > desc[-1]:
                        desc = desc[::-1]
                    dihedrals_found.add(desc)
        return tuple(dihedrals_found)

    def guess_atom_charge(self, atoms):
        return 0.0

    def guess_aromaticities(self, atomgroup=None):
        if atomgroup is None:
            atomgroup = self._universe.atoms
        mol = atomgroup.convert_to('RDKIT')
        return np.array([atom.GetIsAromatic() for atom in mol.GetAtoms()])

    def guess_gasteiger_charges(self, atomgroup):
        mol = atomgroup.convert_to('RDKIT')
        from rdkit.Chem.rdPartialCharges import ComputeGasteigerCharges
        ComputeGasteigerCharges(mol, throwOnParamFailure=True)
        return np.array([atom.GetDoubleProp('_GasteigerCharge') for atom in mol.GetAtoms()], dtype=np.float32)

@check_coords('reference', enforce_copy=False, reduce_result_if_single=False, check_lengths_match=False, allow_atomgroup=True)
def self_capped_distance(reference: Union[npt.NDArray, 'AtomGroup'], max_cutoff: float, min_cutoff: Optional[float]=None, box: Optional[npt.NDArray]=None, method: Optional[str]=None, return_distances: Optional[bool]=True, backend: Optional[str]='serial'):
    if box is not None:
        box = np.asarray(box, dtype=np.float32)
        if box.shape[0] != 6:
            raise ValueError('Box Argument is of incompatible type. The dimension should be either None or of the form [lx, ly, lz, alpha, beta, gamma]')
    reference_positions: npt.NDArray = reference
    function = _determine_method_self(reference_positions, max_cutoff, min_cutoff=min_cutoff, box=box, method=method)
    if function.__name__ == '_nsgrid_capped_self':
        return function(reference, max_cutoff, min_cutoff=min_cutoff, box=box, return_distances=return_distances)
    else:
        return function(reference, max_cutoff, min_cutoff=min_cutoff, box=box, return_distances=return_distances, backend=backend)

# --- helper: MDAnalysis.lib.distances._determine_method_self ---
def _determine_method_self(reference: npt.NDArray, max_cutoff: float, min_cutoff: Optional[float]=None, box: Optional[npt.NDArray]=None, method: Optional[str]=None):
    methods = {'bruteforce': _bruteforce_capped_self, 'pkdtree': _pkdtree_capped_self, 'nsgrid': _nsgrid_capped_self}
    if method is not None:
        return methods[method.lower()]
    if len(reference) < 100:
        return methods['bruteforce']
    if box is None:
        min_dim = np.array([reference.min(axis=0)])
        max_dim = np.array([reference.max(axis=0)])
        size = max_dim.max(axis=0) - min_dim.min(axis=0)
    elif np.all(box[3:] == 90.0):
        size = box[:3]
    else:
        tribox = triclinic_vectors(box)
        size = tribox.max(axis=0) - tribox.min(axis=0)
    if max_cutoff < 0.03 * size.min():
        return methods['pkdtree']
    else:
        return methods['nsgrid']

@check_coords('reference', 'configuration', enforce_copy=False, reduce_result_if_single=False, check_lengths_match=False, allow_atomgroup=True)
def capped_distance(reference: Union[npt.NDArray, 'AtomGroup'], configuration: Union[npt.NDArray, 'AtomGroup'], max_cutoff: float, min_cutoff: Optional[float]=None, box: Optional[npt.NDArray]=None, method: Optional[str]=None, return_distances: Optional[bool]=True, backend: Optional[str]='serial'):
    if box is not None:
        box = np.asarray(box, dtype=np.float32)
        if box.shape[0] != 6:
            raise ValueError('Box Argument is of incompatible type. The dimension should be either None or of the form [lx, ly, lz, alpha, beta, gamma]')
    reference_positions: npt.NDArray = reference
    configuration_positions: npt.NDArray = configuration
    function = _determine_method(reference_positions, configuration_positions, max_cutoff, min_cutoff=min_cutoff, box=box, method=method)
    if function.__name__ == '_nsgrid_capped':
        return function(reference, configuration, max_cutoff, min_cutoff=min_cutoff, box=box, return_distances=return_distances)
    else:
        return function(reference, configuration, max_cutoff, min_cutoff=min_cutoff, box=box, return_distances=return_distances, backend=backend)

# --- helper: MDAnalysis.lib.distances._determine_method ---
def _determine_method(reference: npt.NDArray, configuration: npt.NDArray, max_cutoff: float, min_cutoff: Optional[float]=None, box: Optional[npt.NDArray]=None, method: Optional[str]=None) -> Callable:
    methods = {'bruteforce': _bruteforce_capped, 'pkdtree': _pkdtree_capped, 'nsgrid': _nsgrid_capped}
    if method is not None:
        return methods[method.lower()]
    if len(reference) < 10 or len(configuration) < 10:
        return methods['bruteforce']
    elif len(reference) * len(configuration) >= 100000000.0:
        return methods['nsgrid']
    else:
        if box is None:
            min_dim = np.array([reference.min(axis=0), configuration.min(axis=0)])
            max_dim = np.array([reference.max(axis=0), configuration.max(axis=0)])
            size = max_dim.max(axis=0) - min_dim.min(axis=0)
        elif np.all(box[3:] == 90.0):
            size = box[:3]
        else:
            tribox = triclinic_vectors(box)
            size = tribox.max(axis=0) - tribox.min(axis=0)
        if np.any(max_cutoff > 0.3 * size):
            return methods['bruteforce']
        else:
            return methods['nsgrid']

