class Prism:

    def __init__(self, cell: np.ndarray, pbc: bool | np.ndarray=True, reduce_cell: bool=False, tolerance: float=1e-08):
        self.lammps_tilt = calc_rotated_cell(cell)
        self.rot_mat = np.linalg.solve(self.lammps_tilt, cell).T
        self.ase_cell = cell
        self.tolerance = tolerance
        self.pbc = tuple(np.zeros(3, bool) + pbc)
        self.lammps_cell = calc_reduced_cell(self.lammps_tilt, self.pbc)
        self.is_reduced = reduce_cell

    @property
    def cell(self) -> np.ndarray:
        return self.lammps_cell if self.is_reduced else self.lammps_tilt

    def get_lammps_prism(self) -> np.ndarray:
        return self.cell[(0, 1, 2, 1, 2, 2), (0, 1, 2, 0, 0, 1)]

    def update_cell(self, lammps_cell: np.ndarray) -> np.ndarray:
        transformation = np.linalg.solve(self.lammps_cell, self.lammps_tilt)
        if self.is_reduced:
            self.lammps_cell = lammps_cell
            self.lammps_tilt = lammps_cell @ transformation
        else:
            self.lammps_tilt = lammps_cell
            self.lammps_cell = calc_reduced_cell(self.lammps_tilt, self.pbc)
        new_ase_cell = self.lammps_tilt @ self.rot_mat.T
        new_vol = np.linalg.det(new_ase_cell)
        old_vol = np.linalg.det(self.ase_cell)
        test_residual = self.ase_cell.copy()
        test_residual *= (new_vol / old_vol) ** (1.0 / 3.0)
        test_residual -= new_ase_cell
        if any(np.linalg.norm(test_residual, axis=1) > 0.5 * np.linalg.norm(self.ase_cell, axis=1)):
            warnings.warn('Significant simulation cell changes from LAMMPS detected. Backtransformation to ASE might fail!')
        return new_ase_cell

    def vector_to_lammps(self, vec: np.ndarray, wrap: bool=False) -> np.ndarray:
        if wrap or self.is_reduced:
            return wrap_positions(vec @ self.rot_mat, cell=self.cell, pbc=self.pbc, eps=1e-18)
        return vec @ self.rot_mat

    def vector_to_ase(self, vec: np.ndarray, wrap: bool=False) -> np.ndarray:
        if wrap or self.is_reduced:
            fractional = np.linalg.solve(self.lammps_tilt.T, vec.T).T
            fractional -= np.floor(fractional) * self.pbc
            vec = fractional @ self.lammps_tilt
        return vec @ self.rot_mat.T

    def tensor2_to_ase(self, tensor: np.ndarray) -> np.ndarray:
        return self.rot_mat @ tensor @ self.rot_mat.T

    def is_skewed(self) -> bool:
        cell_sq = self.cell ** 2
        on_diag = np.sum(np.diag(cell_sq))
        off_diag = np.sum(np.tril(cell_sq, -1))
        return off_diag / on_diag > self.tolerance

# --- helper: ase.calculators.lammps.coordinatetransform.calc_reduced_cell ---
def calc_reduced_cell(cell: np.ndarray, pbc: np.ndarray | Sequence[bool]) -> np.ndarray:
    reduced_cell = cell.copy()
    flip_order = ((1, 0), (2, 1), (2, 0))
    for i, j in flip_order:
        if not pbc[j]:
            continue
        ratio = reduced_cell[i, j] / reduced_cell[j, j]
        if abs(ratio) > 0.5:
            reduced_cell[i] -= reduced_cell[j] * np.round(ratio)
    return reduced_cell

# --- helper: ase.calculators.lammps.coordinatetransform.calc_rotated_cell ---
def calc_rotated_cell(cell: np.ndarray) -> np.ndarray:
    ax, by, cz, bx, cx, cy = calc_box_parameters(cell)
    return np.array(((ax, 0.0, 0.0), (bx, by, 0.0), (cx, cy, cz)))

def calc_reduced_cell(cell: np.ndarray, pbc: np.ndarray | Sequence[bool]) -> np.ndarray:
    reduced_cell = cell.copy()
    flip_order = ((1, 0), (2, 1), (2, 0))
    for i, j in flip_order:
        if not pbc[j]:
            continue
        ratio = reduced_cell[i, j] / reduced_cell[j, j]
        if abs(ratio) > 0.5:
            reduced_cell[i] -= reduced_cell[j] * np.round(ratio)
    return reduced_cell

class RescaledCalculator(Calculator):
    implemented_properties = ['forces', 'energy', 'stress']

    def __init__(self, mm_calc, qm_lattice_constant, qm_bulk_modulus, mm_lattice_constant, mm_bulk_modulus):
        Calculator.__init__(self)
        self.mm_calc = mm_calc
        self.alpha = qm_lattice_constant / mm_lattice_constant
        self.beta = mm_bulk_modulus / qm_bulk_modulus / self.alpha ** 3

    def calculate(self, atoms, properties, system_changes):
        Calculator.calculate(self, atoms, properties, system_changes)
        scaled_atoms = atoms.copy()
        mm_cell = atoms.get_cell()
        scaled_atoms.set_cell(mm_cell / self.alpha, scale_atoms=True)
        results = {}
        if 'energy' in properties:
            energy = self.mm_calc.get_potential_energy(scaled_atoms)
            results['energy'] = energy / self.beta
        if 'forces' in properties:
            forces = self.mm_calc.get_forces(scaled_atoms)
            results['forces'] = forces / (self.beta * self.alpha)
        if 'stress' in properties:
            stress = self.mm_calc.get_stress(scaled_atoms)
            results['stress'] = stress / (self.beta * self.alpha ** 3)
        self.results = results

def combine_lj_lorenz_berthelot(sigmaqm, sigmamm, epsilonqm, epsilonmm):
    sigma = []
    epsilon = []
    if isinstance(sigmamm, Sequence):
        numcalcs = len(sigmamm)
    else:
        numcalcs = 1
        sigmamm = (sigmamm,)
        epsilonmm = (epsilonmm,)
    for cc in range(numcalcs):
        sigma_c = np.zeros((len(sigmaqm), len(sigmamm[cc])))
        epsilon_c = np.zeros_like(sigma_c)
        for ii in range(len(sigmaqm)):
            sigma_c[ii, :] = (sigmaqm[ii] + sigmamm[cc]) / 2
            epsilon_c[ii, :] = (epsilonqm[ii] * epsilonmm[cc]) ** 0.5
        sigma.append(sigma_c)
        epsilon.append(epsilon_c)
    if numcalcs == 1:
        sigma = np.array(sigma[0])
        epsilon = np.array(epsilon[0])
    return (sigma, epsilon)

def wrap(D, cell, pbc):
    for i, periodic in enumerate(pbc):
        if periodic:
            d = D[:, i]
            L = cell[i]
            d[:] = (d + L / 2) % L - L / 2

class SinglePointDFTCalculator(SinglePointCalculator):

    def __init__(self, atoms, efermi=None, bzkpts=None, ibzkpts=None, bz2ibz=None, kpts=None, **results):
        self.bz_kpts = bzkpts
        self.ibz_kpts = ibzkpts
        self.bz2ibz = bz2ibz
        self.eFermi = efermi
        SinglePointCalculator.__init__(self, atoms, **results)
        self.kpts = kpts

    def get_fermi_level(self):
        return self.eFermi

    def get_bz_to_ibz_map(self):
        return self.bz2ibz

    def get_bz_k_points(self):
        return self.bz_kpts

    def get_number_of_spins(self):
        if self.kpts is not None:
            nspin = set()
            for kpt in self.kpts:
                nspin.add(kpt.s)
            return len(nspin)
        return None

    def get_number_of_bands(self):
        values = {len(kpt.eps_n) for kpt in self.kpts}
        if not values:
            return None
        elif len(values) == 1:
            return values.pop()
        else:
            raise RuntimeError('Multiple array sizes')

    def get_spin_polarized(self):
        nos = self.get_number_of_spins()
        if nos is not None:
            return nos == 2
        return None

    def get_ibz_k_points(self):
        return self.ibz_kpts

    def get_kpt(self, kpt=0, spin=0):
        if self.kpts is not None:
            counter = 0
            for kpoint in self.kpts:
                if kpoint.s == spin:
                    if kpt == counter:
                        return kpoint
                    counter += 1
        return None

    def get_k_point_weights(self):
        if self.kpts is not None:
            weights = []
            for kpoint in self.kpts:
                if kpoint.s == 0:
                    weights.append(kpoint.weight)
            return np.array(weights)
        return None

    def get_occupation_numbers(self, kpt=0, spin=0):
        kpoint = self.get_kpt(kpt, spin)
        if kpoint is not None:
            if len(kpoint.f_n):
                return kpoint.f_n
        return None

    def get_eigenvalues(self, kpt=0, spin=0):
        kpoint = self.get_kpt(kpt, spin)
        if kpoint is not None:
            return kpoint.eps_n
        return None

    def get_homo_lumo(self):
        if self.kpts is None:
            raise RuntimeError('No kpts')
        eH = -np.inf
        eL = np.inf
        for spin in range(self.get_number_of_spins()):
            homo, lumo = self.get_homo_lumo_by_spin(spin)
            eH = max(eH, homo)
            eL = min(eL, lumo)
        return (eH, eL)

    def get_homo_lumo_by_spin(self, spin=0):
        if self.kpts is None:
            raise RuntimeError('No kpts')
        for kpt in self.kpts:
            if kpt.s == spin:
                break
        else:
            raise RuntimeError(f'No k-point with spin {spin}')
        if self.eFermi is None:
            raise RuntimeError('Fermi level is not available')
        eH = -1e+32
        eL = 1e+32
        for kpt in self.kpts:
            if kpt.s == spin:
                for e in kpt.eps_n:
                    if e <= self.eFermi:
                        eH = max(eH, e)
                    else:
                        eL = min(eL, e)
        return (eH, eL)

    def properties(self) -> Properties:
        return OutputPropertyWrapper(self).properties()

# --- helper: ase.calculators.singlepoint.OutputPropertyWrapper ---
class OutputPropertyWrapper:

    def __init__(self, calc):
        self.calc = calc

    @propertygetter
    def nspins(self):
        return self.calc.get_number_of_spins()

    @propertygetter
    def nbands(self):
        return self.calc.get_number_of_bands()

    @propertygetter
    def nkpts(self):
        return len(self.calc.kpts) // self.nspins

    def _build_eig_occ_array(self, getter):
        arr = np.empty((self.nspins, self.nkpts, self.nbands))
        for s in range(self.nspins):
            for k in range(self.nkpts):
                value = getter(spin=s, kpt=k)
                if value is None:
                    return None
                arr[s, k, :] = value
        return arr

    @propertygetter
    def eigenvalues(self):
        return self._build_eig_occ_array(self.calc.get_eigenvalues)

    @propertygetter
    def occupations(self):
        return self._build_eig_occ_array(self.calc.get_occupation_numbers)

    @propertygetter
    def fermi_level(self):
        return self.calc.get_fermi_level()

    @propertygetter
    def kpoint_weights(self):
        return self.calc.get_k_point_weights()

    @propertygetter
    def ibz_kpoints(self):
        return self.calc.get_ibz_k_points()

    def properties(self) -> Properties:
        dct = {}
        for name in ['eigenvalues', 'occupations', 'fermi_level', 'kpoint_weights', 'ibz_kpoints']:
            try:
                value = getattr(self, name)
            except PropertyNotPresent:
                pass
            else:
                dct[name] = value
        for name, value in self.calc.results.items():
            dct[name] = value
        return Properties(dct)

