class vdWTkatchenko09prl(Calculator, IOContext):

    def __init__(self, hirshfeld=None, vdwradii=None, calculator=None, Rmax=10.0, Ldecay=1.0, vdWDB_alphaC6=vdWDB_alphaC6, txt=None, sR=None, comm=world):
        self.hirshfeld = hirshfeld
        if calculator is None:
            self.calculator = self.hirshfeld.get_calculator()
        else:
            self.calculator = calculator
        if txt is None:
            txt = get_logging_file_descriptor(self.calculator)
        if hasattr(self.calculator, 'world'):
            self.comm = self.calculator.world
        else:
            self.comm = comm
        self.txt = self.openfile(file=txt, comm=self.comm)
        self.vdwradii = vdwradii
        self.vdWDB_alphaC6 = vdWDB_alphaC6
        self.Rmax = Rmax
        self.Ldecay = Ldecay
        self.atoms = None
        if sR is None:
            try:
                xc_name = self.calculator.get_xc_functional()
                self.sR = sR_opt[xc_name]
            except KeyError:
                raise ValueError('Tkatchenko-Scheffler dispersion correction not ' + f'implemented for {xc_name} functional')
        else:
            self.sR = sR
        self.d = 20
        Calculator.__init__(self)
        self.parameters['calculator'] = self.calculator.name
        self.parameters['xc'] = self.calculator.get_xc_functional()

    @property
    def implemented_properties(self):
        return self.calculator.implemented_properties

    def calculation_required(self, atoms, quantities):
        if self.calculator.calculation_required(atoms, quantities):
            return True
        for quantity in quantities:
            if quantity not in self.results:
                return True
        return False

    def calculate(self, atoms=None, properties=['energy', 'forces'], system_changes=[]):
        Calculator.calculate(self, atoms, properties, system_changes)
        self.update(atoms, properties)

    def update(self, atoms=None, properties=['energy', 'free_energy', 'forces']):
        if not self.calculation_required(atoms, properties):
            return
        if atoms is None:
            atoms = self.calculator.get_atoms()
        properties = list(properties)
        for name in ('energy', 'free_energy', 'forces'):
            if name not in properties:
                properties.append(name)
        for name in properties:
            self.results[name] = self.calculator.get_property(name, atoms)
        self.parameters['uncorrected_energy'] = self.results['energy']
        self.atoms = atoms.copy()
        if self.vdwradii is not None:
            vdwradii = self.vdwradii
            assert len(atoms) == len(vdwradii)
        else:
            vdwradii = []
            for atom in atoms:
                self.vdwradii.append(vdWDB_Grimme06jcc[atom.symbol][1])
        if self.hirshfeld is None:
            volume_ratios = [1.0] * len(atoms)
        elif hasattr(self.hirshfeld, '__len__'):
            assert len(atoms) == len(self.hirshfeld)
            volume_ratios = self.hirshfeld
        else:
            self.hirshfeld.initialize()
            volume_ratios = self.hirshfeld.get_effective_volume_ratios()
        na = len(atoms)
        C6eff_a = np.empty(na)
        alpha_a = np.empty(na)
        R0eff_a = np.empty(na)
        for a, atom in enumerate(atoms):
            alpha_a[a], C6eff_a[a] = self.vdWDB_alphaC6[atom.symbol]
            C6eff_a[a] *= Hartree * volume_ratios[a] ** 2 * Bohr ** 6
            R0eff_a[a] = vdwradii[a] * volume_ratios[a] ** (1 / 3.0)
        C6eff_aa = np.empty((na, na))
        for a in range(na):
            for b in range(a, na):
                C6eff_aa[a, b] = 2 * C6eff_a[a] * C6eff_a[b] / (alpha_a[b] / alpha_a[a] * C6eff_a[a] + alpha_a[a] / alpha_a[b] * C6eff_a[b])
                C6eff_aa[b, a] = C6eff_aa[a, b]
        pbc_c = atoms.get_pbc()
        EvdW = 0.0
        forces = 0.0 * self.results['forces']
        if pbc_c.any():
            tol = 1e-05
            Reff = self.Rmax + self.Ldecay * erfinv(1.0 - 2.0 * tol)
            n_list = neighbor_list(quantities='ijdDS', a=atoms, cutoff=Reff, self_interaction=False)
            atom_list = [[] for _ in range(len(atoms))]
            d_list = [[] for _ in range(len(atoms))]
            v_list = [[] for _ in range(len(atoms))]
            for k in range(len(n_list[0])):
                i = n_list[0][k]
                j = n_list[1][k]
                dist = n_list[2][k]
                vect = n_list[3][k]
                if j >= i:
                    atom_list[i].append(j)
                    d_list[i].append(dist)
                    v_list[i].append(vect)
        else:
            atom_list = []
            d_list = []
            v_list = []
            for i in range(len(atoms)):
                atom_list.append(range(i + 1, len(atoms)))
                d_list.append([atoms.get_distance(i, j) for j in range(i + 1, len(atoms))])
                v_list.append([atoms.get_distance(i, j, vector=True) for j in range(i + 1, len(atoms))])
        ms = myslice(len(atoms), self.comm)
        for i in range(len(atoms))[ms]:
            for j, r, vect in zip(atom_list[i], d_list[i], v_list[i]):
                r6 = r ** 6
                Edamp, Fdamp = self.damping(r, R0eff_a[i], R0eff_a[j], d=self.d, sR=self.sR)
                if pbc_c.any():
                    smooth = 0.5 * erfc((r - self.Rmax) / self.Ldecay)
                    smooth_der = -1.0 / np.sqrt(np.pi) / self.Ldecay * np.exp(-((r - self.Rmax) / self.Ldecay) ** 2)
                else:
                    smooth = 1.0
                    smooth_der = 0.0
                if i == j:
                    EvdW -= Edamp * C6eff_aa[i, j] / r6 / 2.0 * smooth
                else:
                    EvdW -= Edamp * C6eff_aa[i, j] / r6 * smooth
                if i != j:
                    force_ij = -((Fdamp - 6 * Edamp / r) * C6eff_aa[i, j] / r6 * smooth + Edamp * C6eff_aa[i, j] / r6 * smooth_der) * vect / r
                    forces[i] += force_ij
                    forces[j] -= force_ij
        EvdW = self.comm.sum_scalar(EvdW)
        self.comm.sum(forces)
        self.results['energy'] += EvdW
        self.results['free_energy'] += EvdW
        self.results['forces'] += forces
        if self.txt:
            print('\n' + self.__class__.__name__, file=self.txt)
            print(f'vdW correction: {EvdW}', file=self.txt)
            print(f"Energy:         {self.results['energy']}", file=self.txt)
            print('\nForces in eV/Ang:', file=self.txt)
            symbols = self.atoms.get_chemical_symbols()
            for ia, symbol in enumerate(symbols):
                print('%3d %-2s %10.5f %10.5f %10.5f' % ((ia, symbol) + tuple(self.results['forces'][ia])), file=self.txt)
            self.txt.flush()

    def damping(self, RAB, R0A, R0B, d=20, sR=0.94):
        scale = 1.0 / (sR * (R0A + R0B))
        x = RAB * scale
        chi = np.exp(-d * (x - 1.0))
        return (1.0 / (1.0 + chi), d * scale * chi / (1.0 + chi) ** 2)

class DatabaseProject:
    _ase_templates = Path('ase/db/templates')

    def __init__(self, name, title, *, key_descriptions, database, default_columns):
        self.name = name
        self.title = title
        self.uid_key = 'id'
        all_keys = database.get_all_key_names()
        key_descriptions = {**{key: KeyDescription(key) for key in all_keys}, **key_descriptions}
        for key, value in key_descriptions.items():
            assert isinstance(key, str), type(key)
            assert isinstance(value, KeyDescription), type(value)
        self.key_descriptions = key_descriptions
        self.database = database
        self.default_columns = default_columns

    def get_search_template(self):
        return self._ase_templates / 'search.html'

    def get_row_template(self):
        return self._ase_templates / 'row.html'

    def get_table_template(self):
        return self._ase_templates / 'table.html'

    def handle_query(self, args) -> str:
        return args['query']

    def row_to_dict(self, row):
        dct = row2dct(row, self.key_descriptions)
        dct['formula'] = Formula(row.formula).convert('abc').format('html')
        return dct

    def uid_to_row(self, uid):
        return self.database.get(f'{self.uid_key}={uid}')

    @classmethod
    def dummyproject(cls, **kwargs):

        class DummyDatabase:

            def select(self, *args, **kwargs):
                return iter([])

            def get_all_key_names(self):
                return set()
        _kwargs = dict(name='test', title='test', key_descriptions={}, database=DummyDatabase(), default_columns=[])
        _kwargs.update(kwargs)
        return cls(**_kwargs)

    @staticmethod
    def load_db_as_ase_project(name, database):
        from ase.db.core import get_key_descriptions
        from ase.db.table import all_columns
        return DatabaseProject(name=name, title=database.metadata.get('title', ''), key_descriptions=get_key_descriptions(), database=database, default_columns=all_columns)

def search_pubchem_raw(search, field, silent=False):
    suffix = 'sdf?record_type=3d'
    url = f'{base_url}/{field}/{search!s}/{suffix}' if field == 'conformers' else f'{base_url}/compound/{field}/{search!s}/{suffix}'
    try:
        r = urllib.request.urlopen(url)
    except HTTPError as e:
        raise ValueError(f'the search term {search} could not be found for the field {field}') from e
    except URLError as e:
        raise ValueError("Couldn't reach the pubchem servers, check your internet connection") from e
    if field != 'conformers' and (not silent):
        conformer_ids = available_conformer_search(search, field)
        if len(conformer_ids) > 1:
            warnings.warn(f'The structure "{search}" has more than one conformer in PubChem. By default, the first conformer is returned, please ensure you are using the structure you intend to or use the `ase.data.pubchem.pubchem_conformer_search` function')
    return r.read().decode('utf-8')

# --- helper: ase.data.pubchem.available_conformer_search ---
def available_conformer_search(search, field) -> list:
    suffix = 'conformers/JSON'
    url = f'{base_url}/compound/{field}/{search!s}/{suffix}'
    try:
        r = urllib.request.urlopen(url)
    except HTTPError as e:
        err = ValueError(f'the search term {search} could not be found for the field {field}')
        raise err from e
    except URLError as e:
        err = ValueError("Couldn't reach the pubchem servers, check your internet connection")
        raise err from e
    record = r.read().decode('utf-8')
    record = json.loads(record)
    return record['InformationList']['Information'][0]['ConformerID']

