# --- helper: ase.data.pubchem.pubchem_search ---
def pubchem_search(*args, **kwargs) -> PubchemData:
    search, field = analyze_input(*args, **kwargs)
    raw_pubchem = search_pubchem_raw(search, field)
    atoms, data = parse_pubchem_raw(raw_pubchem)
    return PubchemData(atoms, data)

def bandgap(calc=None, direct=False, spin=_deprecated, eigenvalues=None, efermi=None, output=None, kpts=None):
    if spin is not _deprecated:
        raise RuntimeError(spin_error)
    if calc:
        kpts = calc.get_ibz_k_points()
        nk = len(kpts)
        ns = calc.get_number_of_spins()
        eigenvalues = np.array([[calc.get_eigenvalues(kpt=k, spin=s) for k in range(nk)] for s in range(ns)])
        if efermi is None:
            efermi = calc.get_fermi_level()
    efermi = efermi or 0.0
    gapinfo = GapInfo(eigenvalues - efermi)
    e_skn = gapinfo.eigenvalues
    if eigenvalues.ndim == 2:
        e_skn = e_skn[np.newaxis]
    if not np.isfinite(e_skn).all():
        raise ValueError('Bad eigenvalues!')
    gap, (s1, k1, n1), (s2, k2, n2) = _bandgap(e_skn, direct)
    if eigenvalues.ndim != 3:
        p1 = (k1, n1)
        p2 = (k2, n2)
    else:
        p1 = (s1, k1, n1)
        p2 = (s2, k2, n2)
    return (gap, p1, p2)

# --- helper: ase.dft.bandgap.GapInfo ---
@dataclass
class GapInfo:
    eigenvalues: np.ndarray

    def __post_init__(self):
        self._gapinfo = _bandgap(self.eigenvalues, direct=False)
        self._direct_gapinfo = _bandgap(self.eigenvalues, direct=True)

    @classmethod
    def fromcalc(cls, calc):
        kpts = calc.get_ibz_k_points()
        nk = len(kpts)
        ns = calc.get_number_of_spins()
        eigenvalues = np.array([[calc.get_eigenvalues(kpt=k, spin=s) for k in range(nk)] for s in range(ns)])
        efermi = calc.get_fermi_level()
        return cls(eigenvalues - efermi)

    def gap(self):
        return self._gapinfo

    def direct_gap(self):
        return self._direct_gapinfo

    @property
    def is_metallic(self) -> bool:
        return self._gapinfo[0] == 0.0

    @property
    def gap_is_direct(self) -> bool:
        return self._gapinfo[1:] == self._direct_gapinfo[1:]

    def description(self, *, ibz_kpoints=None) -> str:
        lines: list[str] = []
        add = lines.append

        def skn(skn):
            description = 's={}, k={}, n={}'.format(*skn)
            if ibz_kpoints is not None:
                coordtxt = '[{:.2f}, {:.2f}, {:.2f}]'.format(*ibz_kpoints[skn[1]])
                description = f'{description}, {coordtxt}'
            return f'({description})'
        gap, skn1, skn2 = self.gap()
        direct_gap, skn_direct1, skn_direct2 = self.direct_gap()
        if self.is_metallic:
            add('No gap')
        else:
            add(f'Gap: {gap:.3f} eV')
            add('Transition (v -> c):')
            add(f'  {skn(skn1)} -> {skn(skn2)}')
        if self.gap_is_direct:
            add('No difference between direct/indirect transitions')
        else:
            add('Direct/indirect transitions are different')
            add(f'Direct gap: {direct_gap:.3f} eV')
            if skn_direct1[0] == skn_direct2[0]:
                add(f'Transition at: {skn(skn_direct1)}')
            else:
                transition = skn((f'{skn_direct1[0]}->{skn_direct2[0]}', *skn_direct1[1:]))
                add(f'Transition at: {transition}')
        return '\n'.join(lines)

# --- helper: ase.dft.bandgap._bandgap ---
def _bandgap(e_skn, direct):
    ns, nk, nb = e_skn.shape
    s1 = s2 = k1 = k2 = n1 = n2 = None
    N_sk = (e_skn < 0.0).sum(2)
    if ns == 1:
        if np.ptp(N_sk[0]) > 0:
            return (0.0, (None, None, None), (None, None, None))
    elif (np.ptp(N_sk, axis=1) > 0).any():
        return (0.0, (None, None, None), (None, None, None))
    if (N_sk == 0).any() or (N_sk == nb).any():
        raise ValueError('Too few bands!')
    e_skn = np.array([[e_skn[s, k, N_sk[s, k] - 1:N_sk[s, k] + 1] for k in range(nk)] for s in range(ns)])
    ev_sk = e_skn[:, :, 0]
    ec_sk = e_skn[:, :, 1]
    if ns == 1:
        s1 = 0
        s2 = 0
        gap, k1, k2 = find_gap(ev_sk[0], ec_sk[0], direct)
        n1 = N_sk[0, 0] - 1
        n2 = n1 + 1
        return (gap, (0, k1, n1), (0, k2, n2))
    gap, k1, k2 = find_gap(ev_sk.ravel(), ec_sk.ravel(), direct)
    if direct:
        for s in [0, 1]:
            g, k, _ = find_gap(ev_sk[s], ec_sk[1 - s], direct)
            if g < gap:
                gap = g
                k1 = k + nk * s
                k2 = k + nk * (1 - s)
    if gap > 0.0:
        s1, k1 = divmod(k1, nk)
        s2, k2 = divmod(k2, nk)
        n1 = N_sk[s1, k1] - 1
        n2 = N_sk[s2, k2]
        return (gap, (s1, k1, n1), (s2, k2, n2))
    return (0.0, (None, None, None), (None, None, None))

class SpacePlot:
    axis_dim = 3
    point_options: dict[str, Any] = {}

    def __init__(self, *, azim: float | None=None, elev: float | None=None):

        class Arrow3D(FancyArrowPatch):

            def __init__(self, ax, xs, ys, zs, *args, **kwargs):
                FancyArrowPatch.__init__(self, (0, 0), (0, 0), *args, **kwargs)
                self._verts3d = (xs, ys, zs)
                self.ax = ax

            def draw(self, renderer):
                xs3d, ys3d, zs3d = self._verts3d
                xs, ys, _zs = proj3d.proj_transform(xs3d, ys3d, zs3d, self.ax.axes.M)
                self.set_positions((xs[0], ys[0]), (xs[1], ys[1]))
                FancyArrowPatch.draw(self, renderer)

            def do_3d_projection(self, *_, **__):
                return 0
        self.arrow3d = Arrow3D
        self.azim: float = pi / 5 if azim is None else azim
        self.elev: float = pi / 6 if elev is None else elev
        self.view = [sin(self.azim) * cos(self.elev), cos(self.azim) * cos(self.elev), sin(self.elev)]

    def new_axes(self, fig):
        return fig.add_subplot(projection='3d')

    def draw_arrow(self, ax: Axes3D, vector, **kwargs):
        ax.add_artist(self.arrow3d(ax, [0, vector[0]], [0, vector[1]], [0, vector[2]], mutation_scale=20, arrowstyle='-|>', **kwargs))

    def adjust_view(self, ax, minp, maxp, symmetric=True):
        import matplotlib.pyplot as plt
        ax.view_init(azim=np.rad2deg(self.azim), elev=np.rad2deg(self.elev))
        fig = ax.get_figure()
        xx = plt.figaspect(1.0)
        fig.set_figheight(xx[1])
        fig.set_figwidth(xx[0])
        ax.set_proj_type('ortho')
        minp0 = 0.9 * minp
        maxp0 = 0.9 * maxp
        ax.set_xlim3d(minp0, maxp0)
        ax.set_ylim3d(minp0, maxp0)
        ax.set_zlim3d(minp0, maxp0)
        ax.set_box_aspect([1, 1, 1])

    def label_options(self, point):
        return dict(ha='center', va='bottom')

def bz_plot(cell: Cell, vectors: bool=False, paths=None, points=None, azim: float | None=None, elev: float | None=None, scale=1, interactive: bool=False, transforms: list | None=None, repeat: tuple[int, int] | tuple[int, int, int]=(1, 1, 1), pointstyle: dict | None=None, ax=None, show=False, **kwargs):
    import matplotlib.pyplot as plt
    if pointstyle is None:
        pointstyle = {}
    if transforms is None:
        transforms = [Rotation.from_rotvec((0, 0, 0))]
    cell = cell.copy()
    dimensions = cell.rank
    if dimensions == 3:
        plotter: SpacePlot | FlatPlot = SpacePlot(azim=azim, elev=elev)
    else:
        plotter = FlatPlot()
    assert dimensions > 0, 'No BZ for 0D!'
    if ax is None:
        ax = plotter.new_axes(plt.gcf())
    assert not np.array(cell)[dimensions:, :].any()
    assert not np.array(cell)[:, dimensions:].any()
    icell = cell.reciprocal()
    kpoints = points
    bz1 = bz_vertices(icell, dim=dimensions)
    if len(repeat) == 2:
        repeat = (repeat[0], repeat[1], 1)
    maxp = 0.0
    minp = 0.0
    for bz_i in bz_index(repeat):
        for points, normal in bz1:
            shift = np.dot(np.array(icell).T, np.array(bz_i))
            for transform in transforms:
                shift = transform.apply(shift)
            ls = '-'
            xyz = np.concatenate([points, points[:1]])
            for transform in transforms:
                xyz = transform.apply(xyz)
            x, y, z = xyz.T
            x, y, z = (x + shift[0], y + shift[1], z + shift[2])
            if dimensions == 3:
                if normal @ plotter.view < 0 and (not interactive):
                    ls = ':'
            if plotter.axis_dim == 2:
                ax.plot(x, y, c='k', ls=ls, **kwargs)
            else:
                ax.plot(x, y, z, c='k', ls=ls, **kwargs)
            maxp = max(maxp, x.max(), y.max(), z.max())
            minp = min(minp, x.min(), y.min(), z.min())
    if vectors:
        for transform in transforms:
            icell = transform.apply(icell)
        assert isinstance(icell, np.ndarray)
        for i in range(dimensions):
            plotter.draw_arrow(ax, icell[i], color='k')
        if dimensions == 3:
            maxp = max(maxp, 0.6 * icell.max())
        else:
            maxp = max(maxp, icell.max())
    if paths is not None:
        for names, points in paths:
            for transform in transforms:
                points = transform.apply(points)
            coords = np.array(points).T[:plotter.axis_dim, :]
            ax.plot(*coords, c='r', ls='-')
            for name, point in zip(names, points):
                name = normalize_name(name)
                point = point[:plotter.axis_dim]
                ax.text(*point, f'$\\mathrm{{{name}}}$', color='g', **plotter.label_options(point))
    if kpoints is not None:
        kw = {'c': 'b', **plotter.point_options, **pointstyle}
        for transform in transforms:
            kpoints = transform.apply(kpoints)
        ax.scatter(*kpoints[:, :plotter.axis_dim].T, **kw)
    ax.set_axis_off()
    if repeat == (1, 1, 1):
        plotter.adjust_view(ax, minp, maxp)
    else:
        plotter.adjust_view(ax, minp, maxp, symmetric=False)
    if show:
        plt.show()
    return ax

