                self._verts3d = (xs, ys, zs)
                self.ax = ax

            def draw(self, renderer):
                xs3d, ys3d, zs3d = self._verts3d
                xs, ys, _zs = proj3d.proj_transform(xs3d, ys3d, zs3d, self.ax.axes.M)
                self.set_positions((xs[0], ys[0]), (xs[1], ys[1]))
                FancyArrowPatch.draw(self, renderer)

            def do_3d_projection(self, *_, **__):
                return 0
        self.arrow3d = Arrow3D
        self.azim: float = pi / 5 if azim is None else azim
        self.elev: float = pi / 6 if elev is None else elev
        self.view = [sin(self.azim) * cos(self.elev), cos(self.azim) * cos(self.elev), sin(self.elev)]

    def new_axes(self, fig):
        return fig.add_subplot(projection='3d')

    def draw_arrow(self, ax: Axes3D, vector, **kwargs):
        ax.add_artist(self.arrow3d(ax, [0, vector[0]], [0, vector[1]], [0, vector[2]], mutation_scale=20, arrowstyle='-|>', **kwargs))

    def adjust_view(self, ax, minp, maxp, symmetric=True):
        import matplotlib.pyplot as plt
        ax.view_init(azim=np.rad2deg(self.azim), elev=np.rad2deg(self.elev))
        fig = ax.get_figure()
        xx = plt.figaspect(1.0)
        fig.set_figheight(xx[1])
        fig.set_figwidth(xx[0])
        ax.set_proj_type('ortho')
        minp0 = 0.9 * minp
        maxp0 = 0.9 * maxp
        ax.set_xlim3d(minp0, maxp0)
        ax.set_ylim3d(minp0, maxp0)
        ax.set_zlim3d(minp0, maxp0)
        ax.set_box_aspect([1, 1, 1])

    def label_options(self, point):
        return dict(ha='center', va='bottom')

# --- helper: ase.dft.bz.bz_index ---
def bz_index(repeat):
    if len(repeat) == 2:
        repeat = (repeat[0], repeat[1], 1)
    assert len(repeat) == 3
    assert repeat[0] != 0
    assert repeat[1] != 0
    assert repeat[2] != 0
    repeat_along_a = range(0, repeat[0]) if repeat[0] > 0 else range(0, repeat[0], -1)
    repeat_along_b = range(0, repeat[1]) if repeat[1] > 0 else range(0, repeat[1], -1)
    repeat_along_c = range(0, repeat[2]) if repeat[2] > 0 else range(0, repeat[2], -1)
    return product(repeat_along_a, repeat_along_b, repeat_along_c)

# --- helper: ase.dft.bz.bz_vertices ---
def bz_vertices(icell, dim=3):
    from scipy.spatial import Voronoi
    icell = icell.copy()
    if dim < 3:
        icell[2, 2] = 0.001
    if dim < 2:
        icell[1, 1] = 0.001
    indices = (np.indices((3, 3, 3)) - 1).reshape((3, 27))
    G = np.dot(icell.T, indices).T
    vor = Voronoi(G)
    bz1 = []
    for vertices, points in zip(vor.ridge_vertices, vor.ridge_points):
        if -1 not in vertices and 13 in points:
            normal = G[points].sum(0)
            normal /= (normal ** 2).sum() ** 0.5
            bz1.append((vor.vertices[vertices], normal))
    return bz1

# --- helper: ase.dft.bz.normalize_name ---
def normalize_name(name):
    if name == 'G':
        return '\\Gamma'
    if len(name) > 1:
        import re
        m = re.match('^(\\D+?)(\\d*)$', name)
        if m is None:
            raise ValueError(f'Bad label: {name}')
        name, num = m.group(1, 2)
        if num:
            name = f'{name}_{{{num}}}'
    return name

def search_for_gamma_point(kpts):
    gamma_idx = np.argmin([np.linalg.norm(kpt) for kpt in kpts])
    if np.linalg.norm(kpts[gamma_idx]) >= 1e-14:
        gamma_idx = None
    return gamma_idx

def mindistance2monkhorstpack(atoms, *, min_distance, maxperdim=16, even=True):
    return _mindistance2monkhorstpack(atoms.cell, atoms.pbc, min_distance, maxperdim, even)

# --- helper: ase.dft.kpoints._mindistance2monkhorstpack ---
def _mindistance2monkhorstpack(cell, pbc_c, min_distance, maxperdim, even):
    from ase.neighborlist import NeighborList
    step = 2 if even else 1
    nl = NeighborList([min_distance / 2], skin=0.0, self_interaction=False, bothways=False)

    def check(nkpts_c):
        nl.update(Atoms('H', cell=cell @ np.diag(nkpts_c), pbc=pbc_c))
        return len(nl.get_neighbors(0)[1]) == 0

    def generate_mpgrids():
        ranges = [range(step, maxperdim + 1, step) if pbc else range(1, 2) for pbc in pbc_c]
        nkpts_nc = np.column_stack([*map(np.ravel, np.meshgrid(*ranges))])
        yield from sorted(nkpts_nc, key=np.prod)
    try:
        return next(filter(check, generate_mpgrids()))
    except StopIteration:
        raise ValueError('Could not find a proper k-point grid for the system. Try running with a larger maxperdim.')

