class Namelist(UserDict):

    def __getitem__(self, key):
        return super().__getitem__(key.lower())

    def __setitem__(self, key, value):
        super().__setitem__(key.lower(), Namelist(value) if isinstance(value, MutableMapping) else value)

    def __delitem__(self, key):
        super().__delitem__(key.lower())

    @staticmethod
    def search_key(to_find, keys):
        for section in keys:
            for key in keys[section]:
                if re.match(f'({key})\\b(\\(+.*\\)+)?$', to_find):
                    return section

    def to_string(self, indent=0, list_form=False):
        pwi = []
        for key, value in self.items():
            if isinstance(value, (Namelist, dict)):
                pwi.append(f"{' ' * indent}&{key.upper()}\n")
                pwi.extend(Namelist.to_string(value, indent=indent + 3))
                pwi.append(f"{' ' * indent}/\n")
            elif value is True:
                pwi.append(f"{' ' * indent}{key:16} = .true.\n")
            elif value is False:
                pwi.append(f"{' ' * indent}{key:16} = .false.\n")
            elif isinstance(value, Path):
                pwi.append(f"{' ' * indent}{key:16} = '{value}'\n")
            else:
                pwi.append(f"{' ' * indent}{key:16} = {value!r}\n")
        if list_form:
            return pwi
        else:
            return ''.join(pwi)

    def to_nested(self, binary='pw', warn=False, **kwargs):
        keys = ALL_KEYS[binary]
        constructed_namelist = {section: self.pop(section, {}) for section in keys}
        constructed_namelist.update({key: value for key, value in self.items() if isinstance(value, Namelist)})
        unused_keys = []
        for arg_key in list(self):
            section = Namelist.search_key(arg_key, keys)
            value = self.pop(arg_key)
            if section:
                constructed_namelist[section][arg_key] = value
            else:
                unused_keys.append(arg_key)
        for arg_key in list(kwargs):
            section = Namelist.search_key(arg_key, keys)
            value = kwargs.pop(arg_key)
            if section:
                warnings.warn('Use of kwarg(s) as keyword(s) is deprecated,use input_data instead', DeprecationWarning)
                constructed_namelist[section][arg_key] = value
            else:
                unused_keys.append(arg_key)
        if unused_keys and warn:
            warnings.warn(f"Unused keys: {', '.join(unused_keys)}", UserWarning)
        for section in constructed_namelist:
            sorted_section = {}

            def sorting_rule(item):
                return keys[section].index(item.split('(')[0]) if item.split('(')[0] in keys.get(section, {}) else float('inf')
            for key in sorted(constructed_namelist[section], key=sorting_rule):
                sorted_section[key] = constructed_namelist[section][key]
            constructed_namelist[section] = sorted_section
        super().update(Namelist(constructed_namelist))

def save_calc_results(atoms, calc=None, calc_prefix=None, remove_atoms_calc=False, force=False):
    if calc is None:
        calc_use = atoms.calc
    else:
        calc_use = calc
    if calc_use is None:
        return (None, None)
    if calc_prefix is None:
        calc_prefix = calc_use.__class__.__name__ + '_'
    per_config_results = {}
    per_atom_results = {}
    for prop, value in calc_use.results.items():
        if prop in per_config_properties:
            per_config_results[calc_prefix + prop] = value
        elif prop in per_atom_properties:
            per_atom_results[calc_prefix + prop] = value
    if not force:
        if any((key in atoms.info for key in per_config_results)):
            raise KeyError('key from calculator already exists in atoms.info')
        if any((key in atoms.arrays for key in per_atom_results)):
            raise KeyError('key from calculator already exists in atoms.arrays')
    atoms.info.update(per_config_results)
    atoms.arrays.update(per_atom_results)
    if remove_atoms_calc and calc is None:
        atoms.calc = None

def output_column_format(atoms, columns, arrays, write_info=True):
    fmt_map = {'d': ('R', '%16.8f'), 'f': ('R', '%16.8f'), 'i': ('I', '%8d'), 'O': ('S', '%s'), 'S': ('S', '%s'), 'U': ('S', '%-2s'), 'b': ('L', ' %.1s')}
    lattice_str = 'Lattice="' + ' '.join([str(x) for x in np.reshape(atoms.cell.T, 9, order='F')]) + '"'
    property_names = []
    property_types = []
    property_ncols = []
    dtypes = []
    formats = []
    for column in columns:
        array = arrays[column]
        dtype = array.dtype
        property_name = PROPERTY_NAME_MAP.get(column, column)
        property_type, fmt = fmt_map[dtype.kind]
        property_names.append(property_name)
        property_types.append(property_type)
        if len(array.shape) == 1 or (len(array.shape) == 2 and array.shape[1] == 1):
            ncol = 1
            dtypes.append((column, dtype))
        else:
            ncol = array.shape[1]
            for c in range(ncol):
                dtypes.append((column + str(c), dtype))
        formats.extend([fmt] * ncol)
        property_ncols.append(ncol)
    props_str = ':'.join([':'.join(x) for x in zip(property_names, property_types, [str(nc) for nc in property_ncols])])
    comment_str = ''
    if atoms.cell.any():
        comment_str += lattice_str + ' '
    comment_str += f'Properties={props_str}'
    info = {}
    if write_info:
        info.update(atoms.info)
    info['pbc'] = atoms.get_pbc()
    comment_str += ' ' + key_val_dict_to_str(info)
    dtype = np.dtype(dtypes)
    fmt = ' '.join(formats) + '\n'
    return (comment_str, property_ncols, dtype, fmt)

# --- helper: ase.io.extxyz.key_val_dict_to_str ---
def key_val_dict_to_str(dct, sep=' '):

    def array_to_string(key, val):
        if key in SPECIAL_3_3_KEYS:
            val = val.reshape(val.size, order='F')
        if val.dtype.kind in ['i', 'f', 'b']:
            if len(val.shape) == 0:
                val = str(known_types_to_str(val))
            elif len(val.shape) == 1:
                val = ' '.join((str(known_types_to_str(v)) for v in val))
        return val

    def known_types_to_str(val):
        if isinstance(val, (bool, np.bool_)):
            return 'T' if val else 'F'
        elif isinstance(val, numbers.Real):
            return f'{val}'
        elif isinstance(val, Spacegroup):
            return val.symbol
        else:
            return val
    if len(dct) == 0:
        return ''
    string = ''
    for key in dct:
        val = dct[key]
        if isinstance(val, np.ndarray):
            val = array_to_string(key, val)
        else:
            val = known_types_to_str(val)
        if val is not None and (not isinstance(val, str)):
            if isinstance(val, np.ndarray):
                val = val.tolist()
            try:
                val = '_JSON ' + json.dumps(val)
            except TypeError:
                warnings.warn('Skipping unhashable information {}'.format(key))
                continue
        key = escape(key)
        eq = '='
        if val is None:
            val = ''
            eq = ''
        val = escape(val)
        string += f'{key}{eq}{val}{sep}'
    return string.strip()

def get_chunks(lines: Iterable[str]) -> Iterator[list[str]]:
    finished = False
    relaxation_finished = False
    relaxation = False
    chunk_endings = ['ORCA TERMINATED NORMALLY', 'ORCA GEOMETRY RELAXATION STEP']
    chunk_lines = []
    for line in lines:
        if any([ending in line for ending in chunk_endings]):
            chunk_lines.append(line)
            yield chunk_lines
            chunk_lines = []
        else:
            chunk_lines.append(line)
        if 'ORCA TERMINATED NORMALLY' in line:
            finished = True
        if 'THE OPTIMIZATION HAS CONVERGED' in line:
            relaxation_finished = True
        if 'ORCA SCF GRADIENT CALCULATION' in line:
            relaxation = True
    if not finished and (not relaxation):
        raise ParseError('Error: Calculation did not finish!')
    elif not finished and relaxation:
        warnings.warn('Calculation did not finish!')
    elif not relaxation_finished and relaxation:
        warnings.warn('Geometry optimization did not converge!')

def read_center_of_mass(lines: list[str]) -> np.ndarray | None:
    com = None
    for line in lines:
        if 'The origin for moment calculation is the CENTER OF MASS' in line:
            line = re.sub('[(),]', '', line)
            com = np.array([float(_) for _ in line.split()[-3:]])
    if com is not None:
        return com * Bohr
    return com

def read_dipole(lines: list[str]) -> np.ndarray | None:
    dipole = None
    for line in lines:
        if 'Total Dipole Moment' in line:
            dipole = np.array([float(x) for x in line.split()[-3:]]) * Bohr
    return dipole

def serialize_property_v2000(prop: str, data: list[tuple[int, int]]) -> str:
    block = ''
    chunks = [data[i:i + 8] for i in range(0, len(data), 8)]
    for chunk in chunks:
        block += f'M  {prop:3}{len(chunk):3}'
        for i_atom, value in chunk:
            block += f' {i_atom:3} {value:3}'
        block += '\n'
    return block

def connectivity2bonds(connectivity: np.ndarray) -> list[tuple[int, int]]:
    idcs0, idcs1 = np.nonzero(np.triu(connectivity, k=1))
    return list(zip(idcs0, idcs1))

def get_cell_vertex_points(cell, disp=(0.0, 0.0, 0.0)):
    cell_vertices = np.empty((2, 2, 2, 3))
    displacement = np.array(disp)
    for c1 in range(2):
        for c2 in range(2):
            for c3 in range(2):
                cell_vertices[c1, c2, c3] = [c1, c2, c3] @ cell + displacement
    cell_vertices.shape = (8, 3)
    return cell_vertices

