def parse_poscar_scaling_factor(line: str) -> np.ndarray:
    scale = []
    for _ in line.split()[:3]:
        try:
            scale.append(float(_))
        except ValueError:
            break
    if len(scale) not in {1, 3}:
        raise RuntimeError('The number of scaling factors must be 1 or 3.')
