def translate(thing, x, y, z):
    return element('transform', translation=f'{x} {y} {z}', child=thing)

def x3d_wireframe_box(box):
    a, b, c = box
    faces = [wireframe_face(a, b), wireframe_face(a, b, origin=c), wireframe_face(a, c), wireframe_face(a, c, origin=b)]
    return group(faces)

# --- helper: ase.io.x3d.group ---
def group(things):
    return element('group', children=things)

# --- helper: ase.io.x3d.wireframe_face ---
def wireframe_face(vec1, vec2, origin=(0, 0, 0)):
    x1, y1, z1 = vec1
    x2, y2, z2 = vec2
    material = element('material', diffuseColor='0 0 0')
    appearance = element('appearance', child=material)
    points = [(0, 0, 0), (x1, y1, z1), (x1 + x2, y1 + y2, z1 + z2), (x2, y2, z2), (0, 0, 0)]
    points = ' '.join((f'{x} {y} {z}' for x, y, z in points))
    coordinates = element('coordinate', point=points)
    lineset = element('lineset', vertexCount='5', child=coordinates)
    shape = element('shape', children=(appearance, lineset))
    x, y, z = origin
    return translate(shape, x, y, z)

def match_to_lattice(cell, latname: str, pbc=None) -> list[Match]:
    from ase.geometry.bravais_type_engine import niggli_op_table
    cell = Cell.ascell(cell)
    matcher = LatticeMatcher(cell=cell, pbc=pbc, eps=1000000.0, niggli_eps=1e-05)
    return matcher.match(latname, niggli_op_table[latname])

# --- helper: ase.lattice.LatticeMatcher ---
class LatticeMatcher:

    def __init__(self, cell, pbc=None, *, eps, niggli_eps=None):
        self.orig_cell = cell
        if pbc is None:
            pbc = cell.mask()
        self.pbc = cell.any(1) & pbc2pbc(pbc)
        self.cell = cell.uncomplete(pbc)
        self.eps = eps
        if niggli_eps is None:
            niggli_eps = eps
        self.niggli_cell, self.niggli_op = self.cell.niggli_reduce(eps=niggli_eps)
        self.memory = {}

    def match(self, latname, operations):
        matches = []
        for op_key in operations:
            checker_and_op = self.memory.get(op_key)
            if checker_and_op is None:
                op_3x3 = np.array(op_key).reshape(3, 3)
                candidate = Cell(np.linalg.inv(op_3x3.T) @ self.niggli_cell)
                checker = NormalizedLatticeMatcher(candidate, eps=self.eps)
                self.memory[op_key] = (checker, op_3x3)
            else:
                checker, op_3x3 = checker_and_op
            lat, error = checker.query(latname)
            if lat is None or error > self.eps:
                continue
            op = op_3x3 @ np.linalg.inv(self.niggli_op)
            matches.append(Match(lat, op, error))
        return matches

# --- helper: ase.lattice.Match ---
@dataclass
class Match:
    lat: BravaisLattice
    op: np.ndarray
    error: float

    @cached_property
    def orthogonality_defect(self) -> float:
        cell = self.lat.tocell().complete()
        return np.prod(cell.lengths()) / cell.volume

class Lattice(Atoms, MillerInfo):
    pass

# --- helper: ase.lattice.bravais.MillerInfo ---
class MillerInfo:

    def miller_to_direction(self, miller):
        return np.dot(miller, self.millerbasis)

class IsotropicMTKBarostat:

    def __init__(self, num_atoms_global: int, temperature_K: float, pdamp: float, pchain: int=3, ploop: int=1):
        self._num_atoms_global = num_atoms_global
        self._pdamp = pdamp
        self._pchain = pchain
        self._ploop = ploop
        self._kT = ase.units.kB * temperature_K
        self._W = (3 * self._num_atoms_global + 3) * self._kT * self._pdamp ** 2
        assert pchain >= 1
        self._R = np.zeros(self._pchain)
        self._R[0] = 9 * self._kT * self._pdamp ** 2
        self._R[1:] = self._kT * self._pdamp ** 2
        self._xi = np.zeros(self._pchain)
        self._p_xi = np.zeros(self._pchain)

    @property
    def W(self) -> float:
        return self._W

    def get_barostat_energy(self) -> float:
        energy = +np.sum(0.5 * self._p_xi ** 2 / self._R) + self._kT * np.sum(self._xi)
        return float(energy)

    def integrate_nhc_baro(self, p_eps: float, delta: float) -> float:
        for _ in range(self._ploop):
            for coeff in FOURTH_ORDER_COEFFS:
                p_eps = self._integrate_nhc_baro_loop(p_eps, coeff * delta / self._ploop)
        return p_eps

    def _integrate_nhc_baro_loop(self, p_eps: float, delta: float) -> float:
        delta2 = delta / 2
        delta4 = delta / 4
        for j in range(self._pchain):
            self._integrate_p_xi_j(p_eps, self._pchain - j - 1, delta2, delta4)
        self._integrate_xi(delta)
        p_eps = self._integrate_nhc_p_eps(p_eps, delta)
        for j in range(self._pchain):
            self._integrate_p_xi_j(p_eps, j, delta2, delta4)
        return p_eps

    def _integrate_p_xi_j(self, p_eps: float, j: int, delta2: float, delta4: float) -> None:
        if j < self._pchain - 1:
            self._p_xi[j] *= np.exp(-delta4 * self._p_xi[j + 1] / self._R[j + 1])
        if j == 0:
            g_j = p_eps ** 2 / self._W - self._kT
        else:
            g_j = self._p_xi[j - 1] ** 2 / self._R[j - 1] - self._kT
        self._p_xi[j] += delta2 * g_j
        if j < self._pchain - 1:
            self._p_xi[j] *= np.exp(-delta4 * self._p_xi[j + 1] / self._R[j + 1])

    def _integrate_xi(self, delta: float) -> None:
        self._xi += delta * self._p_xi / self._R

    def _integrate_nhc_p_eps(self, p_eps: float, delta: float) -> float:
        p_eps_new = p_eps * float(np.exp(-delta * self._p_xi[0] / self._R[0]))
        return p_eps_new

class LangevinBAOAB(MolecularDynamics):

    def __init__(self, atoms, timestep, *, temperature_K=None, externalstress=None, hydrostatic=False, T_tau=None, P_tau=None, P_mass=None, P_mass_factor=1.0, disable_cell_langevin=False, rng=None, **kwargs):
        super().__init__(atoms, timestep, **kwargs)
        self._set_externalstress_hydrostatic(externalstress, hydrostatic)
        self.disable_cell_langevin = disable_cell_langevin
        if temperature_K is not None:
            if rng is None:
                seed = secrets.randbits(128)
                self.rng = np.random.default_rng(seed)
                warnings.warn(f'No rng provided, generated one with seed={seed} from secrets.randbits')
            elif not isinstance(rng, np.random.Generator):
                self.rng = np.random.default_rng(rng)
            else:
                self.rng = rng
            if T_tau is None:
                T_tau = 50.0 * self.dt
                warnings.warn(f'Got `temperature_K` but missing `T_tau`, defaulting to 50 * `timstep` = {T_tau}')
        self.T_tau = T_tau
        if self.T_tau is not None and self.T_tau <= 0:
            raise ValueError(f'Invalid T_tau {self.T_tau} <= 0')
        self.gamma_mod = 0.0
        if self.externalstress is not None:
            self._set_P_tau(P_tau)
            if self.P_tau is not None and self.P_tau <= 0:
                raise ValueError(f'Invalid P_tau {self.P_tau} <= 0')
            self.p_eps = 0.0
            if len(self.atoms.constraints) != 0:
                warnings.warn('WARNING: LangevinBAOAB has not been tested with constraints')
            self.Ndof = self.atoms.get_number_of_degrees_of_freedom()
            self._set_barostat_mass(P_mass, P_mass_factor)
        self.set_temperature(temperature_K, from_init=True)
        self._update_accel()
        if self.externalstress is not None:
            self._update_force_eps()

    def _set_externalstress_hydrostatic(self, externalstress, hydrostatic):
        self.hydrostatic = hydrostatic
        if externalstress is None:
            self.externalstress = externalstress
            return None
        externalstress = np.asarray(externalstress)
        if externalstress.shape == ():
            externalstress = externalstress.reshape(-1)
        if self.hydrostatic:
            if externalstress.shape != (1,):
                raise ValueError(f"externalstress must be scalar when hydrostatic, got '{externalstress}' with shape {externalstress.shape}")
            externalstress = externalstress[0]
        else:
            match externalstress.shape:
                case [1]:
                    externalstress = externalstress * np.identity(3)
                case [3]:
                    externalstress = np.diag(externalstress)
                case [6]:
                    externalstress = voigt_6_to_full_3x3_stress(externalstress)
                case [3, 3]:
                    pass
                case '_':
                    raise ValueError(f'externalstress must be scalar, 3-vector (diagonal), 6-vector (Voigt), or 3x3 matrix, got "{externalstress}" with shape {externalstress.shape}')
        self.externalstress = externalstress

    def _set_P_tau(self, P_tau):
        if P_tau is None:
            if self.T_tau is not None:
                P_tau = 20.0 * self.T_tau
                warnings.warn(f'Got `externalstress` but missing `P_tau`, got `T_tau`, defaulting to 20 * `T_tau` = {P_tau}')
            else:
                P_tau = 1000.0 * self.dt
                warnings.warn(f'Got `externalstress` but missing `P_tau` and `T_tau`, defaulting to 1000 * `timestep` = {P_tau}')
        self.P_tau = P_tau

    def _set_barostat_mass(self, P_mass, P_mass_factor):
        if P_mass is None:
            if not self.P_tau > 0:
                raise ValueError('Heuristic used for P_mass requires P_tau > 0')
            C = 1.66 * units.fs
            barostat_mass = (self.P_tau / 4.0 / C * len(self.atoms) ** (1.0 / 6.0)) ** 2
            warnings.warn(f'Using heuristic P_mass {barostat_mass} from P_tau {self.P_tau}')
            barostat_mass *= P_mass_factor
        else:
            barostat_mass = P_mass
        self.barostat_mass = barostat_mass

    def set_temperature(self, temperature_K, from_init=False):
        self.temperature_K = temperature_K
        self.gamma = 0.0
        self.barostat_gamma = 0.0
        if self.temperature_K is None:
            return
        if self.T_tau is None or self.T_tau <= 0:
            raise RuntimeError(f'Got temperature {self.temperature_K}, but Langevin time-scale T_tau {self.T_tau} is invalud')
        self.gamma = 1.0 / self.T_tau
        sigma = np.sqrt(2.0 * self.gamma * units.kB * self.temperature_K)
        self.BAOAB_prefactor = sigma / np.sqrt(2.0 * self.gamma) * np.sqrt(1.0 - np.exp(-2.0 * self.gamma * self.dt))
        if self.externalstress is not None and (not self.disable_cell_langevin):
            self.barostat_gamma = 1.0 / self.P_tau
            sigma = np.sqrt(2.0 * self.barostat_gamma * units.kB * self.temperature_K)
            self._barostat_BAOAB_prefactor = sigma / np.sqrt(2.0 * self.barostat_gamma) * np.sqrt(1.0 - np.exp(-2.0 * self.barostat_gamma * self.dt)) * np.sqrt(self.barostat_mass)

    def _update_accel(self):
        self.accel = (self.atoms.get_forces().T / self.atoms.get_masses()).T

    def _update_force_eps(self):
        volume = self.atoms.get_volume()
        if self.hydrostatic:
            KE = self.atoms.get_kinetic_energy()
            Tr_virial = -volume * np.trace(self.atoms.get_stress(voigt=False))
            X = 1.0 / (3.0 * volume) * (2.0 * KE + Tr_virial)
            self.force_eps = 3.0 * volume * (X + self.externalstress) + 3.0 / self.Ndof * 2.0 * KE
        else:
            mom = self.atoms.get_momenta()
            kinetic_stress_contrib = mom.T / self.atoms.get_masses() @ mom
            virial = -volume * self.atoms.get_stress(voigt=False)
            X = 1.0 / volume * (kinetic_stress_contrib + virial)
            self.force_eps = volume * (X + self.externalstress) + 1.0 / self.Ndof * np.trace(kinetic_stress_contrib) * np.identity(3)

    def _BAOAB_B(self):
        dvel = 0.5 * self.dt * self.accel
        self.atoms.set_velocities(self.atoms.get_velocities() + dvel)

    def _barostat_BAOAB_B(self):
        self.p_eps += 0.5 * self.dt * self.force_eps

    def _BAOAB_A(self):
        self.atoms.positions += 0.5 * self.dt * self.atoms.get_velocities()

    def _barostat_BAOAB_A(self):
        if self.hydrostatic:
            volume = self.atoms.get_volume()
            new_volume = volume * np.exp(0.5 * self.dt * 3.0 * self.p_eps / self.barostat_mass)
            new_cell = self.atoms.cell * (new_volume / volume) ** (1.0 / 3.0)
        else:
            new_cell = self.atoms.cell @ expm(0.5 * self.dt * self.p_eps / self.barostat_mass).T
        self.atoms.set_cell(new_cell, True)

    def _BAOAB_OU(self, drag_gamma_mod=0.0):
        if self.gamma == 0 and np.all(drag_gamma_mod == 0):
            return
        vel = self.atoms.get_velocities()
        if self.hydrostatic:
            vel *= np.exp(-(self.gamma + drag_gamma_mod) * self.dt)
        else:
            vel = vel @ expm(-(self.gamma * np.identity(3) + drag_gamma_mod) * self.dt).T
        if self.gamma != 0:
            vel_shape = self.atoms.positions.shape
            masses = self.atoms.get_masses()
            vel += self.BAOAB_prefactor * (self.rng.normal(size=vel_shape).T / np.sqrt(masses)).T
        self.atoms.set_velocities(vel)

    def _barostat_BAOAB_OU(self):
        if self.barostat_gamma == 0:
            return
        self.p_eps *= np.exp(-self.barostat_gamma * self.dt)
        if self.hydrostatic:
            self.p_eps += self._barostat_BAOAB_prefactor * self.rng.normal()
        else:
            random_force = self.rng.normal(size=(3, 3))
            random_force += random_force.T
            random_force /= 2
            self.p_eps += self._barostat_BAOAB_prefactor * random_force

    def _barostat_BAOAB_OU_gamma_mod(self):
        if self.hydrostatic:
            return (1.0 + 3.0 / self.Ndof) * self.p_eps / self.barostat_mass
        else:
            return (self.p_eps + 1.0 / self.Ndof * np.trace(self.p_eps)) / self.barostat_mass

    def step(self):
        if self.externalstress is not None:
            self._barostat_BAOAB_B()
        self._BAOAB_B()
        if self.externalstress is not None:
            self._barostat_BAOAB_A()
        self._BAOAB_A()
        if self.externalstress is not None:
            self.gamma_mod = self._barostat_BAOAB_OU_gamma_mod()
        self._BAOAB_OU(self.gamma_mod)
        if self.externalstress is not None:
            self._barostat_BAOAB_OU()
        self._BAOAB_A()
        if self.externalstress is not None:
            self._barostat_BAOAB_A()
        self._update_accel()
        if self.externalstress is not None:
            self._update_force_eps()
        self._BAOAB_B()
        if self.externalstress is not None:
            self._barostat_BAOAB_B()

class MTKBarostat:

    def __init__(self, num_atoms_global: int, temperature_K: float, pdamp: float, pchain: int=3, ploop: int=1, mask: tuple[bool, bool, bool] | None=None):
        self._num_atoms_global = num_atoms_global
        self._pdamp = pdamp
        self._pchain = pchain
        self._ploop = ploop
        self._cell_dof = 9 if mask is None else sum(mask)
        self._kT = ase.units.kB * temperature_K
        self._W = (self._num_atoms_global + 1) * self._kT * self._pdamp ** 2
        assert pchain >= 1
        self._R = np.zeros(self._pchain)
        self._R[0] = self._cell_dof * self._kT * self._pdamp ** 2
        self._R[1:] = self._kT * self._pdamp ** 2
        self._xi = np.zeros(self._pchain)
        self._p_xi = np.zeros(self._pchain)

    @property
    def W(self) -> float:
        return self._W

    def get_barostat_energy(self) -> float:
        energy = np.sum(self._p_xi ** 2 / self._R) / 2 + self._cell_dof * self._kT * self._xi[0] + self._kT * np.sum(self._xi[1:])
        return float(energy)

    def integrate_nhc_baro(self, p_cell: np.ndarray, delta: float) -> np.ndarray:
        for _ in range(self._ploop):
            for coeff in FOURTH_ORDER_COEFFS:
                p_cell = self._integrate_nhc_baro_loop(p_cell, coeff * delta / self._ploop)
        return p_cell

    def _integrate_nhc_baro_loop(self, p_cell: np.ndarray, delta: float) -> np.ndarray:
        delta2 = delta / 2
        delta4 = delta / 4
        for j in range(self._pchain):
            self._integrate_p_xi_j(p_cell, self._pchain - j - 1, delta2, delta4)
        self._integrate_xi(delta)
        self._integrate_nhc_p_cell(p_cell, delta)
        for j in range(self._pchain):
            self._integrate_p_xi_j(p_cell, j, delta2, delta4)
        return p_cell

    def _integrate_p_xi_j(self, p_cell: np.ndarray, j: int, delta2: float, delta4: float) -> None:
        if j < self._pchain - 1:
            self._p_xi[j] *= np.exp(-delta4 * self._p_xi[j + 1] / self._R[j + 1])
        if j == 0:
            g_j = np.sum(p_cell ** 2) / self._W - self._cell_dof * self._kT
        else:
            g_j = self._p_xi[j - 1] ** 2 / self._R[j - 1] - self._kT
        self._p_xi[j] += delta2 * g_j
        if j < self._pchain - 1:
            self._p_xi[j] *= np.exp(-delta4 * self._p_xi[j + 1] / self._R[j + 1])

    def _integrate_xi(self, delta: float) -> None:
        for j in range(self._pchain):
            self._xi[j] += delta * self._p_xi[j] / self._R[j]

    def _integrate_nhc_p_cell(self, p_cell: np.ndarray, delta: float) -> None:
        p_cell *= np.exp(-delta * self._p_xi[0] / self._R[0])

class NoseHooverChainThermostat:

    def __init__(self, num_atoms_global: int, masses: np.ndarray, temperature_K: float, tdamp: float, tchain: int=3, tloop: int=1):
        self._num_atoms_global = num_atoms_global
        self._masses = masses
        self._tdamp = tdamp
        self._tchain = tchain
        self._tloop = tloop
        self._kT = ase.units.kB * temperature_K
        assert tchain >= 1
        self._Q = np.zeros(tchain)
        self._Q[0] = 3 * self._num_atoms_global * self._kT * tdamp ** 2
        self._Q[1:] = self._kT * tdamp ** 2
        self._eta = np.zeros(self._tchain)
        self._p_eta = np.zeros(self._tchain)

    def get_thermostat_energy(self) -> float:
        energy = 3 * self._num_atoms_global * self._kT * self._eta[0] + self._kT * np.sum(self._eta[1:]) + np.sum(0.5 * self._p_eta ** 2 / self._Q)
        return float(energy)

    def integrate_nhc(self, p: np.ndarray, delta: float) -> np.ndarray:
        for _ in range(self._tloop):
            for coeff in FOURTH_ORDER_COEFFS:
                p = self._integrate_nhc_loop(p, coeff * delta / self._tloop)
        return p

    def _integrate_p_eta_j(self, p: np.ndarray, j: int, delta2: float, delta4: float) -> None:
        if j < self._tchain - 1:
            self._p_eta[j] *= np.exp(-delta4 * self._p_eta[j + 1] / self._Q[j + 1])
        if j == 0:
            g_j = np.sum(p ** 2 / self._masses) - 3 * self._num_atoms_global * self._kT
        else:
            g_j = self._p_eta[j - 1] ** 2 / self._Q[j - 1] - self._kT
        self._p_eta[j] += delta2 * g_j
        if j < self._tchain - 1:
            self._p_eta[j] *= np.exp(-delta4 * self._p_eta[j + 1] / self._Q[j + 1])

    def _integrate_eta(self, delta: float) -> None:
        self._eta += delta * self._p_eta / self._Q

    def _integrate_nhc_p(self, p: np.ndarray, delta: float) -> None:
        p *= np.exp(-delta * self._p_eta[0] / self._Q[0])

    def _integrate_nhc_loop(self, p: np.ndarray, delta: float) -> np.ndarray:
        delta2 = delta / 2
        delta4 = delta / 4
        for j in range(self._tchain):
            self._integrate_p_eta_j(p, self._tchain - j - 1, delta2, delta4)
        self._integrate_eta(delta)
        self._integrate_nhc_p(p, delta)
        for j in range(self._tchain):
            self._integrate_p_eta_j(p, j, delta2, delta4)
        return p

class MaskedMTKNPT(MTKNPT):

    def __init__(self, *args, mask: tuple[bool, bool, bool], **kwargs):
        self.mask = mask
        super().__init__(*args, **kwargs)

    def _init_cell_momenta(self) -> None:
        self._h0_basis = self._h / np.linalg.norm(self._h, axis=1)[:, None]
        self._p_c = np.zeros(3)

    @property
    def mask(self) -> tuple[bool, bool, bool]:
        return self._mask

    @mask.setter
    def mask(self, mask: tuple[bool, bool, bool]) -> None:
        self._mask = mask

    @property
    def _p_g(self) -> np.ndarray:
        return self._p_c * self._h0_basis.T @ self._h0_basis

    @_p_g.setter
    def _p_g(self, value: np.ndarray) -> None:
        raise AttributeError()

    def _get_cell_kinetic_energy(self) -> float:
        return float(np.sum(self._p_c ** 2) / (2 * self._barostat.W))

    def _integrate_p_cell(self, delta: float) -> None:
        stress = self._get_stress()
        volume = self._get_volume()
        particle_dof = 3 * self._num_atoms_global
        kinetic_term = np.sum(self._p ** 2 / self.masses) / particle_dof
        pv_tensor = volume * (stress - self._pressure_au * np.eye(3))
        gc = np.diag(self._h0_basis @ pv_tensor @ self._h0_basis.T) + kinetic_term
        self._p_c[self.mask] += delta * gc[self.mask]

    def _integrate_p_cell_by_barostat(self, delta: float) -> None:
        self._p_c = self._barostat.integrate_nhc_baro(self._p_c, delta)

# --- helper: ase.md.nose_hoover_chain.MTKNPT ---
class MTKNPT(MolecularDynamics):

    def __init__(self, atoms: Atoms, timestep: float, temperature_K: float, pressure_au: float, tdamp: float, pdamp: float, tchain: int=3, pchain: int=3, tloop: int=1, ploop: int=1, **kwargs):
        super().__init__(atoms=atoms, timestep=timestep, **kwargs)
        assert self.masses.shape == (len(self.atoms), 1)
        if len(atoms.constraints) > 0:
            raise NotImplementedError('Current implementation does not support constraints')
        self._num_atoms_global = self.atoms.get_global_number_of_atoms()
        self._thermostat = NoseHooverChainThermostat(num_atoms_global=self._num_atoms_global, masses=self.masses, temperature_K=temperature_K, tdamp=tdamp, tchain=tchain, tloop=tloop)
        self._barostat = MTKBarostat(num_atoms_global=self._num_atoms_global, temperature_K=temperature_K, pdamp=pdamp, pchain=pchain, ploop=ploop, mask=self.mask)
        self._temperature_K = temperature_K
        self._pressure_au = pressure_au
        self._kT = ase.units.kB * self._temperature_K
        self._q = self.atoms.get_positions()
        self._p = self.atoms.get_momenta()
        self._h = np.array(self.atoms.get_cell())
        self._init_cell_momenta()

    @property
    def mask(self) -> tuple[bool, bool, bool] | None:
        return None

    @mask.setter
    def mask(self, mask: tuple[bool, bool, bool]) -> None:
        raise AttributeError()

    def _init_cell_momenta(self) -> None:
        self._p_g = np.zeros((3, 3))

    def step(self) -> None:
        dt2 = self.dt / 2
        self._integrate_p_cell_by_barostat(dt2)
        self._p = self._thermostat.integrate_nhc(self._p, dt2)
        self._integrate_p_cell(dt2)
        self._integrate_p(dt2)
        self._integrate_q(self.dt)
        self._integrate_q_cell(self.dt)
        self._integrate_p(dt2)
        self._integrate_p_cell(dt2)
        self._p = self._thermostat.integrate_nhc(self._p, dt2)
        self._integrate_p_cell_by_barostat(dt2)
        self._update_atoms()

    def get_conserved_energy(self) -> float:
        conserved_energy = self.atoms.get_total_energy() + self._thermostat.get_thermostat_energy() + self._barostat.get_barostat_energy() + self._get_cell_kinetic_energy() + self._pressure_au * self._get_volume()
        return float(conserved_energy)

    def _update_atoms(self) -> None:
        self.atoms.set_positions(self._q)
        self.atoms.set_momenta(self._p)
        self.atoms.set_cell(self._h, scale_atoms=False)

    def _get_volume(self) -> float:
        return np.abs(np.linalg.det(self._h))

    def _get_forces(self) -> np.ndarray:
        self._update_atoms()
        return self.atoms.get_forces(md=True)

    def _get_stress(self) -> np.ndarray:
        self._update_atoms()
        stress = self.atoms.get_stress(voigt=False, include_ideal_gas=True)
        return -stress

    def _get_cell_kinetic_energy(self) -> float:
        return float(np.sum(self._p_g ** 2) / (2 * self._barostat.W))

    def _integrate_q(self, delta: float) -> None:
        eigvals, U = np.linalg.eigh(self._p_g)
        x = self._q @ U
        y = self._p @ U
        sol = x * np.exp(eigvals * delta / self._barostat.W)[None, :] + delta * y / self.masses * exprel(eigvals * delta / self._barostat.W)[None, :]
        self._q = sol @ U.T

    def _integrate_p(self, delta: float) -> None:
        forces = self._get_forces()
        eigvals, U = np.linalg.eigh(self._p_g)
        kappas = eigvals + np.trace(self._p_g) / (3 * self._num_atoms_global)
        y = self._p @ U
        sol = y * np.exp(-kappas * delta / self._barostat.W)[None, :] + delta * (forces @ U) * exprel(-kappas * delta / self._barostat.W)[None, :]
        self._p = sol @ U.T

    def _integrate_q_cell(self, delta: float) -> None:
        eigvals, U = np.linalg.eigh(self._p_g)
        n = self._h @ U
        sol = n * np.exp(eigvals * delta / self._barostat.W)[None, :]
        self._h = sol @ U.T

    def _integrate_p_cell(self, delta: float) -> None:
        stress = self._get_stress()
        volume = self._get_volume()
        particle_dof = 3 * self._num_atoms_global
        kinetic_term = np.sum(self._p ** 2 / self.masses) / particle_dof
        pv_tensor = volume * (stress - self._pressure_au * np.eye(3))
        G = pv_tensor + kinetic_term * np.eye(3)
        self._p_g += delta * G

    def _integrate_p_cell_by_barostat(self, delta: float) -> None:
        self._p_g = self._barostat.integrate_nhc_baro(self._p_g, delta)

class IsotropicMTKNPT(MolecularDynamics):

    def __init__(self, atoms: Atoms, timestep: float, temperature_K: float, pressure_au: float, tdamp: float, pdamp: float, tchain: int=3, pchain: int=3, tloop: int=1, ploop: int=1, **kwargs):
        super().__init__(atoms=atoms, timestep=timestep, **kwargs)
        assert self.masses.shape == (len(self.atoms), 1)
        if len(atoms.constraints) > 0:
            raise NotImplementedError('Current implementation does not support constraints')
        self._num_atoms_global = self.atoms.get_global_number_of_atoms()
        self._thermostat = NoseHooverChainThermostat(num_atoms_global=self._num_atoms_global, masses=self.masses, temperature_K=temperature_K, tdamp=tdamp, tchain=tchain, tloop=tloop)
        self._barostat = IsotropicMTKBarostat(num_atoms_global=self._num_atoms_global, temperature_K=temperature_K, pdamp=pdamp, pchain=pchain, ploop=ploop)
        self._temperature_K = temperature_K
        self._pressure_au = pressure_au
        self._kT = ase.units.kB * self._temperature_K
        self._volume0 = self.atoms.get_volume()
        self._cell0 = np.array(self.atoms.get_cell())
        self._q = self.atoms.get_positions()
        self._p = self.atoms.get_momenta()
        self._eps = 0.0
        self._p_eps = 0.0

    def step(self) -> None:
        dt2 = self.dt / 2
        self._p_eps = self._barostat.integrate_nhc_baro(self._p_eps, dt2)
        self._p = self._thermostat.integrate_nhc(self._p, dt2)
        self._integrate_p_cell(dt2)
        self._integrate_p(dt2)
        self._integrate_q(self.dt)
        self._integrate_q_cell(self.dt)
        self._integrate_p(dt2)
        self._integrate_p_cell(dt2)
        self._p = self._thermostat.integrate_nhc(self._p, dt2)
        self._p_eps = self._barostat.integrate_nhc_baro(self._p_eps, dt2)
        self._update_atoms()

    def get_conserved_energy(self) -> float:
        conserved_energy = self.atoms.get_potential_energy(force_consistent=True) + self.atoms.get_kinetic_energy() + self._thermostat.get_thermostat_energy() + self._barostat.get_barostat_energy() + self._p_eps * self._p_eps / (2 * self._barostat.W) + self._pressure_au * self._get_volume()
        return float(conserved_energy)

    def _update_atoms(self) -> None:
        self.atoms.set_positions(self._q)
        self.atoms.set_momenta(self._p)
        cell = self._cell0 * np.exp(self._eps)
        self.atoms.set_cell(cell, scale_atoms=False)

    def _get_volume(self) -> float:
        return self._volume0 * np.exp(3 * self._eps)

    def _get_forces(self) -> np.ndarray:
        self._update_atoms()
        return self.atoms.get_forces(md=True)

    def _get_pressure(self) -> np.ndarray:
        self._update_atoms()
        stress = self.atoms.get_stress(voigt=False, include_ideal_gas=True)
        pressure = -np.trace(stress) / 3
        return pressure

    def _integrate_q(self, delta: float) -> None:
        x = delta * self._p_eps / self._barostat.W
        self._q = self._q * np.exp(x) + self._p * delta / self.masses * exprel(x)

    def _integrate_p(self, delta: float) -> None:
        x = (1 + 1 / self._num_atoms_global) * self._p_eps * delta / self._barostat.W
        forces = self._get_forces()
        self._p = self._p * np.exp(-x) + delta * forces * exprel(-x)

    def _integrate_q_cell(self, delta: float) -> None:
        self._eps += delta * self._p_eps / self._barostat.W

    def _integrate_p_cell(self, delta: float) -> None:
        pressure = self._get_pressure()
        volume = self._get_volume()
        G = 3 * volume * (pressure - self._pressure_au) + np.sum(self._p ** 2 / self.masses) / self._num_atoms_global
        self._p_eps += delta * G

# --- helper: ase.md.nose_hoover_chain.IsotropicMTKBarostat ---
class IsotropicMTKBarostat:

    def __init__(self, num_atoms_global: int, temperature_K: float, pdamp: float, pchain: int=3, ploop: int=1):
        self._num_atoms_global = num_atoms_global
        self._pdamp = pdamp
        self._pchain = pchain
        self._ploop = ploop
        self._kT = ase.units.kB * temperature_K
        self._W = (3 * self._num_atoms_global + 3) * self._kT * self._pdamp ** 2
        assert pchain >= 1
        self._R = np.zeros(self._pchain)
        self._R[0] = 9 * self._kT * self._pdamp ** 2
        self._R[1:] = self._kT * self._pdamp ** 2
        self._xi = np.zeros(self._pchain)
        self._p_xi = np.zeros(self._pchain)

    @property
    def W(self) -> float:
        return self._W

    def get_barostat_energy(self) -> float:
        energy = +np.sum(0.5 * self._p_xi ** 2 / self._R) + self._kT * np.sum(self._xi)
        return float(energy)

    def integrate_nhc_baro(self, p_eps: float, delta: float) -> float:
        for _ in range(self._ploop):
            for coeff in FOURTH_ORDER_COEFFS:
                p_eps = self._integrate_nhc_baro_loop(p_eps, coeff * delta / self._ploop)
        return p_eps

    def _integrate_nhc_baro_loop(self, p_eps: float, delta: float) -> float:
        delta2 = delta / 2
        delta4 = delta / 4
        for j in range(self._pchain):
            self._integrate_p_xi_j(p_eps, self._pchain - j - 1, delta2, delta4)
        self._integrate_xi(delta)
        p_eps = self._integrate_nhc_p_eps(p_eps, delta)
        for j in range(self._pchain):
            self._integrate_p_xi_j(p_eps, j, delta2, delta4)
        return p_eps

    def _integrate_p_xi_j(self, p_eps: float, j: int, delta2: float, delta4: float) -> None:
        if j < self._pchain - 1:
            self._p_xi[j] *= np.exp(-delta4 * self._p_xi[j + 1] / self._R[j + 1])
        if j == 0:
            g_j = p_eps ** 2 / self._W - self._kT
        else:
            g_j = self._p_xi[j - 1] ** 2 / self._R[j - 1] - self._kT
        self._p_xi[j] += delta2 * g_j
        if j < self._pchain - 1:
            self._p_xi[j] *= np.exp(-delta4 * self._p_xi[j + 1] / self._R[j + 1])

    def _integrate_xi(self, delta: float) -> None:
        self._xi += delta * self._p_xi / self._R

    def _integrate_nhc_p_eps(self, p_eps: float, delta: float) -> float:
        p_eps_new = p_eps * float(np.exp(-delta * self._p_xi[0] / self._R[0]))
        return p_eps_new

# --- helper: ase.md.nose_hoover_chain.NoseHooverChainThermostat ---
class NoseHooverChainThermostat:

    def __init__(self, num_atoms_global: int, masses: np.ndarray, temperature_K: float, tdamp: float, tchain: int=3, tloop: int=1):
        self._num_atoms_global = num_atoms_global
        self._masses = masses
        self._tdamp = tdamp
        self._tchain = tchain
        self._tloop = tloop
        self._kT = ase.units.kB * temperature_K
        assert tchain >= 1
        self._Q = np.zeros(tchain)
        self._Q[0] = 3 * self._num_atoms_global * self._kT * tdamp ** 2
        self._Q[1:] = self._kT * tdamp ** 2
        self._eta = np.zeros(self._tchain)
        self._p_eta = np.zeros(self._tchain)

    def get_thermostat_energy(self) -> float:
        energy = 3 * self._num_atoms_global * self._kT * self._eta[0] + self._kT * np.sum(self._eta[1:]) + np.sum(0.5 * self._p_eta ** 2 / self._Q)
        return float(energy)

    def integrate_nhc(self, p: np.ndarray, delta: float) -> np.ndarray:
        for _ in range(self._tloop):
            for coeff in FOURTH_ORDER_COEFFS:
                p = self._integrate_nhc_loop(p, coeff * delta / self._tloop)
        return p

    def _integrate_p_eta_j(self, p: np.ndarray, j: int, delta2: float, delta4: float) -> None:
        if j < self._tchain - 1:
            self._p_eta[j] *= np.exp(-delta4 * self._p_eta[j + 1] / self._Q[j + 1])
        if j == 0:
            g_j = np.sum(p ** 2 / self._masses) - 3 * self._num_atoms_global * self._kT
        else:
            g_j = self._p_eta[j - 1] ** 2 / self._Q[j - 1] - self._kT
        self._p_eta[j] += delta2 * g_j
        if j < self._tchain - 1:
            self._p_eta[j] *= np.exp(-delta4 * self._p_eta[j + 1] / self._Q[j + 1])

    def _integrate_eta(self, delta: float) -> None:
        self._eta += delta * self._p_eta / self._Q

    def _integrate_nhc_p(self, p: np.ndarray, delta: float) -> None:
        p *= np.exp(-delta * self._p_eta[0] / self._Q[0])

    def _integrate_nhc_loop(self, p: np.ndarray, delta: float) -> np.ndarray:
        delta2 = delta / 2
        delta4 = delta / 4
        for j in range(self._tchain):
            self._integrate_p_eta_j(p, self._tchain - j - 1, delta2, delta4)
        self._integrate_eta(delta)
        self._integrate_nhc_p(p, delta)
        for j in range(self._tchain):
            self._integrate_p_eta_j(p, j, delta2, delta4)
        return p

class NoseHooverChainNVT(MolecularDynamics):

    def __init__(self, atoms: Atoms, timestep: float, temperature_K: float, tdamp: float, tchain: int=3, tloop: int=1, **kwargs):
        super().__init__(atoms=atoms, timestep=timestep, **kwargs)
        assert self.masses.shape == (len(self.atoms), 1)
        num_atoms = self.atoms.get_global_number_of_atoms()
        self._thermostat = NoseHooverChainThermostat(num_atoms_global=num_atoms, masses=self.masses, temperature_K=temperature_K, tdamp=tdamp, tchain=tchain, tloop=tloop)
        self._q = self.atoms.get_positions()
        self._p = self.atoms.get_momenta()

    def step(self) -> None:
        dt2 = self.dt / 2
        self._p = self._thermostat.integrate_nhc(self._p, dt2)
        self._integrate_p(dt2)
        self._integrate_q(self.dt)
        self._integrate_p(dt2)
        self._p = self._thermostat.integrate_nhc(self._p, dt2)
        self._update_atoms()

    def get_conserved_energy(self) -> float:
        conserved_energy = self.atoms.get_potential_energy(force_consistent=True) + self.atoms.get_kinetic_energy() + self._thermostat.get_thermostat_energy()
        return float(conserved_energy)

    def _update_atoms(self) -> None:
        self.atoms.set_positions(self._q)
        self.atoms.set_momenta(self._p)

    def _get_forces(self) -> np.ndarray:
        self._update_atoms()
        return self.atoms.get_forces(md=True)

    def _integrate_q(self, delta: float) -> None:
        self._q += delta * self._p / self.masses

    def _integrate_p(self, delta: float) -> None:
        forces = self._get_forces()
        self._p += delta * forces

# --- helper: ase.md.nose_hoover_chain.NoseHooverChainThermostat ---
class NoseHooverChainThermostat:

    def __init__(self, num_atoms_global: int, masses: np.ndarray, temperature_K: float, tdamp: float, tchain: int=3, tloop: int=1):
        self._num_atoms_global = num_atoms_global
        self._masses = masses
        self._tdamp = tdamp
        self._tchain = tchain
        self._tloop = tloop
        self._kT = ase.units.kB * temperature_K
        assert tchain >= 1
        self._Q = np.zeros(tchain)
        self._Q[0] = 3 * self._num_atoms_global * self._kT * tdamp ** 2
        self._Q[1:] = self._kT * tdamp ** 2
        self._eta = np.zeros(self._tchain)
        self._p_eta = np.zeros(self._tchain)

    def get_thermostat_energy(self) -> float:
        energy = 3 * self._num_atoms_global * self._kT * self._eta[0] + self._kT * np.sum(self._eta[1:]) + np.sum(0.5 * self._p_eta ** 2 / self._Q)
        return float(energy)

    def integrate_nhc(self, p: np.ndarray, delta: float) -> np.ndarray:
        for _ in range(self._tloop):
            for coeff in FOURTH_ORDER_COEFFS:
                p = self._integrate_nhc_loop(p, coeff * delta / self._tloop)
        return p

    def _integrate_p_eta_j(self, p: np.ndarray, j: int, delta2: float, delta4: float) -> None:
        if j < self._tchain - 1:
            self._p_eta[j] *= np.exp(-delta4 * self._p_eta[j + 1] / self._Q[j + 1])
        if j == 0:
            g_j = np.sum(p ** 2 / self._masses) - 3 * self._num_atoms_global * self._kT
        else:
            g_j = self._p_eta[j - 1] ** 2 / self._Q[j - 1] - self._kT
        self._p_eta[j] += delta2 * g_j
        if j < self._tchain - 1:
            self._p_eta[j] *= np.exp(-delta4 * self._p_eta[j + 1] / self._Q[j + 1])

    def _integrate_eta(self, delta: float) -> None:
        self._eta += delta * self._p_eta / self._Q

    def _integrate_nhc_p(self, p: np.ndarray, delta: float) -> None:
        p *= np.exp(-delta * self._p_eta[0] / self._Q[0])

    def _integrate_nhc_loop(self, p: np.ndarray, delta: float) -> np.ndarray:
        delta2 = delta / 2
        delta4 = delta / 4
        for j in range(self._tchain):
            self._integrate_p_eta_j(p, self._tchain - j - 1, delta2, delta4)
        self._integrate_eta(delta)
        self._integrate_nhc_p(p, delta)
        for j in range(self._tchain):
            self._integrate_p_eta_j(p, j, delta2, delta4)
        return p

class NVTBerendsen(MolecularDynamics):

    def __init__(self, atoms: Atoms, timestep: float, temperature: float | None=None, taut: float | None=None, fixcm: bool=True, *, temperature_K: float | None=None, **kwargs):
        if 'communicator' in kwargs:
            msg = '`communicator` has been deprecated since ASE 3.25.0 and will be removed in ASE 3.26.0. Use `comm` instead.'
            warnings.warn(msg, FutureWarning)
            kwargs['comm'] = kwargs.pop('communicator')
        MolecularDynamics.__init__(self, atoms, timestep, **kwargs)
        if taut is None:
            raise TypeError("Missing 'taut' argument.")
        self.taut = taut
        self.temperature = self._process_temperature(temperature, temperature_K, 'K')
        self.fix_com = fixcm

    def set_taut(self, taut):
        self.taut = taut

    def get_taut(self):
        return self.taut

    def set_temperature(self, temperature=None, *, temperature_K=None):
        self.temperature = self._process_temperature(temperature, temperature_K, 'K')

    def get_temperature(self):
        return self.temperature

    def set_timestep(self, timestep):
        self.dt = timestep

    def get_timestep(self):
        return self.dt

    def scale_velocities(self):
        tautscl = self.dt / self.taut
        old_temperature = self.atoms.get_temperature()
        scl_temperature = np.sqrt(1.0 + (self.temperature / old_temperature - 1.0) * tautscl)
        if scl_temperature > 1.1:
            scl_temperature = 1.1
        if scl_temperature < 0.9:
            scl_temperature = 0.9
        p = self.atoms.get_momenta()
        p = scl_temperature * p
        self.atoms.set_momenta(p)
        return

    def step(self, forces=None):
        self.scale_velocities()
        atoms = self.atoms
        if forces is None:
            forces = atoms.get_forces(md=True)
        p = self.atoms.get_momenta()
        p += 0.5 * self.dt * forces
        if self.fix_com:
            psum = p.sum(axis=0) / float(len(p))
            p = p - psum
        self.atoms.set_positions(self.atoms.get_positions() + self.dt * p / self.atoms.get_masses()[:, np.newaxis])
        self.atoms.set_momenta(p)
        forces = self.atoms.get_forces(md=True)
        atoms.set_momenta(self.atoms.get_momenta() + 0.5 * self.dt * forces)
        return forces

class ASENEBMethod(NEBMethod):

    def get_tangent(self, state, spring1, spring2, i):
        imax = self.neb.imax
        if i < imax:
            tangent = spring2.t
        elif i > imax:
            tangent = spring1.t
        else:
            tangent = spring1.t + spring2.t
        return tangent

    def add_image_force(self, state, tangential_force, tangent, imgforce, spring1, spring2, i):
        tangent_mag = np.vdot(tangent, tangent) or 1
        factor = tangent / tangent_mag
        imgforce -= tangential_force * factor
        imgforce -= np.vdot(spring1.t * spring1.k - spring2.t * spring2.k, tangent) * factor

