        ...

    @abstractmethod
    def add_image_force(self, state, tangential_force, tangent, imgforce, spring1, spring2, i):
        ...

    def adjust_positions(self, positions):
        return positions

class MinModeControl(IOContext):
    parameters: dict[str, Any] = {}

    def __init__(self, logfile='-', eigenmode_logfile=None, comm=world, **kwargs):
        for key in kwargs:
            if key not in self.parameters:
                e = f'Invalid parameter >>{key}<< with value >>{kwargs[key]!s}<< in {self.__class__.__name__}'
                raise ValueError(e)
            else:
                self.set_parameter(key, kwargs[key], log=False)
        self.initialize_logfiles(comm=comm, logfile=logfile, eigenmode_logfile=eigenmode_logfile)
        self.counters = {'forcecalls': 0, 'rotcount': 0, 'optcount': 0}
        self.log()

    def initialize_logfiles(self, comm, logfile=None, eigenmode_logfile=None):
        self.logfile = self.openfile(file=logfile, comm=comm)
        self.eigenmode_logfile = self.openfile(file=eigenmode_logfile, comm=comm)

    def log(self, parameter=None):
        pass

    def set_parameter(self, parameter, value, log=True):
        if parameter not in self.parameters:
            e = f'Invalid parameter >>{parameter}<< with value >>{value!s}<<'
            raise ValueError(e)
        self.parameters[parameter] = value
        if log:
            self.log(parameter)

    def get_parameter(self, parameter):
        if parameter not in self.parameters:
            e = f'Invalid parameter >>{parameter}<<'
            raise ValueError(e)
        return self.parameters[parameter]

    def get_logfile(self):
        return self.logfile

    def get_eigenmode_logfile(self):
        return self.eigenmode_logfile

    def get_counter(self, counter):
        return self.counters[counter]

    def increment_counter(self, counter):
        self.counters[counter] += 1

    def reset_counter(self, counter):
        self.counters[counter] = 0

    def reset_all_counters(self):
        for key in self.counters:
            self.counters[key] = 0

class BaseSplineMethod(NEBMethod):

    def __init__(self, neb):
