class NEBOptimizer(Optimizer):

    def __init__(self, neb, restart=None, logfile='-', trajectory=None, master=None, append_trajectory=False, method='ODE', alpha=0.01, verbose=0, rtol=0.1, C1=0.01, C2=2.0):
        super().__init__(atoms=neb, restart=restart, logfile=logfile, trajectory=trajectory, master=master, append_trajectory=append_trajectory)
        self.neb = neb
        method = method.lower()
        methods = ['ode', 'static', 'krylov']
        if method not in methods:
            raise ValueError(f'method must be one of {methods}')
        self.method = method
        self.alpha = alpha
        self.verbose = verbose
        self.rtol = rtol
        self.C1 = C1
        self.C2 = C2

    def force_function(self, X):
        positions = X.reshape((self.neb.nimages - 2) * self.neb.natoms, 3)
        self.neb.set_positions(positions)
        forces = self.neb.get_forces().reshape(-1)
        return forces

    def get_residual(self, F=None, X=None):
        return self.neb.get_residual()

    def log(self):
        fmax = self.get_residual()
        T = time.localtime()
        if self.logfile is not None:
            name = f'{self.__class__.__name__}[{self.method}]'
            if self.nsteps == 0:
                args = (' ' * len(name), 'Step', 'Time', 'fmax')
                msg = '%s  %4s %8s %12s\n' % args
                self.logfile.write(msg)
            args = (name, self.nsteps, T[3], T[4], T[5], fmax)
            msg = '%s:  %3d %02d:%02d:%02d %12.4f\n' % args
            self.logfile.write(msg)

    def callback(self, X, F=None):
        self.log()
        self.call_observers()
        self.nsteps += 1

    def run_ode(self, fmax):
        try:
            ode12r(self.force_function, self.neb.get_positions().reshape(-1), fmax=fmax, rtol=self.rtol, C1=self.C1, C2=self.C2, steps=self.max_steps, verbose=self.verbose, callback=self.callback, residual=self.get_residual)
            return True
        except OptimizerConvergenceError:
            return False

    def run_static(self, fmax):
        X = self.neb.get_positions().reshape(-1)
        for _ in range(self.max_steps):
            F = self.force_function(X)
            if self.neb.get_residual() <= fmax:
                return True
            X += self.alpha * F
            self.callback(X)
        return False

    def run(self, fmax=0.05, steps=DEFAULT_MAX_STEPS, method=None):
        self.max_steps = steps
        if method is None:
            method = self.method
        if method == 'ode':
            return self.run_ode(fmax)
        elif method == 'static':
            return self.run_static(fmax)
        else:
            raise ValueError(f'unknown method: {self.method}')

class ODE12r(SciPyOptimizer):

    def __init__(self, atoms: Atoms, logfile: IO | str='-', trajectory: str | None=None, callback_always: bool=False, alpha: float=1.0, precon: str | None=None, verbose: int=0, rtol: float=0.01, **kwargs):
        super().__init__(atoms, logfile, trajectory, callback_always, alpha, **kwargs)
        self._actual_atoms = atoms
        from ase.optimize.precon.precon import make_precon
        self.precon = make_precon(precon)
        self.verbose = verbose
        self.rtol = rtol

    def apply_precon(self, Fn, X):
        self.optimizable.set_x(X)
        Fn, Rn = self.precon.apply(Fn, self._actual_atoms)
        return (Fn, Rn)

    def call_fmin(self, fmax, steps):
        ode12r(lambda x: -self.fprime(x), self.x0(), fmax=fmax, steps=steps, verbose=self.verbose, apply_precon=self.apply_precon, callback=self.callback, converged=lambda gradient, X: self.gradient_converged(gradient), rtol=self.rtol)

# --- helper: ase.optimize.ode.ode12r ---
def ode12r(f, X0, h=None, verbose=1, fmax=1e-06, maxtol=1000.0, steps=100, rtol=0.1, C1=0.01, C2=2.0, hmin=1e-10, extrapolate=3, callback=None, apply_precon=None, converged=None, residual=None):
    X = X0
    Fn = f(X)
    if callback is None:

        def callback(X):
            pass
    if residual is None:

        def residual(F, X):
            return np.linalg.norm(F, np.inf)
    Rn = residual(Fn, X)
    if apply_precon is None:

        def apply_precon(F, X):
            return (F, residual(F, X))
    Fp, Rp = apply_precon(Fn, X)

    def log(*args):
        if verbose >= 1:
            print(*args)

    def debug(*args):
        if verbose >= 2:
            print(*args)
    if converged is None:

        def converged(F, X):
            return residual(F, X) <= fmax
    if converged(Fn, X):
        log('ODE12r terminates successfully after 0 iterations')
        return X
    if Rn >= maxtol:
        raise OptimizerConvergenceError(f'ODE12r: Residual {Rn} is too large at iteration 0')
    r = residual(Fp, X)
    if h is None:
        h = 0.5 * rtol ** 0.5 / r
        h = max(h, hmin)
    for nit in range(1, steps + 1):
        Xnew = X + h * Fp
        Fn_new = f(Xnew)
        Rn_new = residual(Fn_new, Xnew)
        Fp_new, Rp_new = apply_precon(Fn_new, Xnew)
        e = 0.5 * h * (Fp_new - Fp)
        err = np.linalg.norm(e, np.inf)
        accept = Rp_new <= Rp * (1 - C1 * h) or (Rp_new <= Rp * C2 and err <= rtol)
        y = Fp - Fp_new
        if extrapolate == 1:
            h_ls = h * (Fp @ y) / (y @ y)
        elif extrapolate == 2:
            h_ls = h * (Fp @ Fp_new) / (Fp @ y + 1e-10)
        elif extrapolate == 3:
            h_ls = h * (Fp @ y) / (y @ y + 1e-10)
        else:
            raise ValueError(f'invalid extrapolate value: {extrapolate}. Must be 1, 2 or 3')
        if np.isnan(h_ls) or h_ls < hmin:
            h_ls = np.inf
        h_err = h * 0.5 * np.sqrt(rtol / err)
        if accept:
            X = Xnew
            Rn = Rn_new
            Fn = Fn_new
            Fp = Fp_new
            Rp = Rp_new
            callback(X)
            if Rn >= maxtol:
                raise OptimizerConvergenceError(f'ODE12r: Residual {Rn} is too large at iteration number {nit}')
            if converged(Fn, X):
                log(f'ODE12r: terminates successfully after {nit} iterations.')
                return X
            h = max(0.25 * h, min(4 * h, h_err, h_ls))
            debug(f'ODE12r:      accept: new h = {h}, |F| = {Rp}')
            debug(f'ODE12r:                hls = {h_ls}')
            debug(f'ODE12r:               herr = {h_err}')
        else:
            h = max(0.1 * h, min(0.25 * h, h_err, h_ls))
            debug(f'ODE12r:      reject: new h = {h}')
            debug(f'ODE12r:               |Fnew| = {Rp_new}')
            debug(f'ODE12r:               |Fold| = {Rp}')
            debug(f'ODE12r:        |Fnew|/|Fold| = {Rp_new / Rp}')
        if abs(h) <= hmin:
            raise OptimizerConvergenceError(f'ODE12r terminates unsuccessfully Step size {h} too small')

class BaseDynamics(IOContext):

    def __init__(self, atoms: Atoms, logfile: IO | Path | str | None=None, trajectory: str | Path | None=None, append_trajectory: bool=False, master: bool | None=None, comm=world, *, loginterval: int=1):
        self.atoms = atoms
        self.logfile = Log(logfile, comm=comm)
        self.observers: list[tuple[Callable, int, tuple, dict[str, Any]]] = []
        self.nsteps = 0
        self.max_steps = 0
        self.comm = comm
        self._orig_trajectory = trajectory
        self._master = master
        if trajectory is None or hasattr(trajectory, 'write'):
            pass
        else:
            trajectory = Path(trajectory)
            if comm.rank == 0 and (not append_trajectory):
                trajectory.unlink(missing_ok=True)
        if trajectory is not None:
            self.attach(self._traj_write_image, interval=loginterval, description={'interval': loginterval})
        self.trajectory = trajectory

    def todict(self) -> dict[str, Any]:
        raise NotImplementedError

    @contextmanager
    def _opentraj(self):
        from ase.io.trajectory import Trajectory
        assert self._orig_trajectory is not None
        if hasattr(self._orig_trajectory, 'write'):
            yield self._orig_trajectory
            return
        with Trajectory(self._orig_trajectory, master=self._master, mode='a', comm=self.comm) as traj:
            yield traj

    def _traj_write_image(self, description: dict):
        with self._opentraj() as traj:
            traj.set_description(self.todict() | description)
            traj.write(self.atoms.__ase_optimizable__())

    def _traj_is_empty(self):
        with self._opentraj() as traj:
            return len(traj) == 0

    def _get_gradient(self, forces=None):
        if forces is not None:
            warnings.warn('Please do not pass forces to step().  This argument will be removed in ase 3.28.0.')
            return -forces.ravel()
        return self.optimizable.get_gradient()

    def get_number_of_steps(self):
        return self.nsteps

    def insert_observer(self, function, position=0, interval=1, *args, **kwargs):
        if not isinstance(function, Callable):
            function = function.write
        self.observers.insert(position, (function, interval, args, kwargs))

    def attach(self, function, interval=1, *args, **kwargs):
        if not isinstance(function, Callable):
            function = function.write
        self.observers.append((function, interval, args, kwargs))

    def call_observers(self):
        for function, interval, args, kwargs in self.observers:
            call = False
            if interval > 0:
                if self.nsteps % interval == 0:
                    call = True
            elif interval <= 0:
                if self.nsteps == abs(interval):
                    call = True
            if call:
                function(*args, **kwargs)

