class SciPyOptimizer(Optimizer):

    def __init__(self, atoms: Atoms, logfile: IO | str='-', trajectory: str | None=None, callback_always: bool=False, alpha: float=70.0, **kwargs):
        restart = None
        super().__init__(atoms, restart, logfile, trajectory, **kwargs)
        self.force_calls = 0
        self.callback_always = callback_always
        self.H0 = alpha
        self.max_steps = 0

    def x0(self):
        return self.optimizable.get_x()

    def f(self, x):
        self.optimizable.set_x(x)
        return self.optimizable.get_value() / self.H0

    def fprime(self, x):
        self.optimizable.set_x(x)
        self.force_calls += 1
        if self.callback_always:
            self.callback(x)
        return self.optimizable.get_gradient() / self.H0

    def callback(self, x):
        if self.nsteps < self.max_steps:
            self.nsteps += 1
        gradient = self.optimizable.get_gradient()
        self.log(gradient)
        self.call_observers()
        if self.gradient_converged(gradient):
            raise Converged

    def run(self, fmax=0.05, steps=100000000):
        self.fmax = fmax
        try:
            if self.nsteps == 0:
                gradient = self.optimizable.get_gradient()
                self.log(gradient)
                self.call_observers()
            self.max_steps = steps + self.nsteps
            self.call_fmin(fmax / self.H0, steps)
        except Converged:
            pass
        gradient = self.optimizable.get_gradient()
        return self.gradient_converged(gradient)

    def dump(self, data):
        pass

    def load(self):
        pass

    def call_fmin(self, fmax, steps):
        raise NotImplementedError

class AsapCommWrapper:

    def __init__(self, world):
        self.world = world

    def __getattr__(self, attr):
        return getattr(self.world, attr)

    def sum_scalar(self, a, root=-1):
        buf = np.array([a])
        self.world.sum(buf, root=root)
        return buf[0]

class MPI:

    def __init__(self):
        self.comm = None

    def __getattr__(self, name):
        if name == '__setstate__':
            raise AttributeError(name)
        if self.comm is None:
            self.comm = _get_comm()
        return getattr(self.comm, name)

# --- helper: ase.parallel._get_comm ---
def _get_comm():
    if 'mpi4py' in sys.modules:
        return MPI4PY()
    if '_gpaw' in sys.modules:
        world = _gpaw_world()
        if world is not None:
            return world
    if '_asap' in sys.modules:
        world = _asap_world()
        if world is not None:
            return world
    return DummyMPI()

class SciPyFminCG(SciPyOptimizer):

    def call_fmin(self, fmax, steps):
        output = opt.fmin_cg(self.f, self.x0(), fprime=self.fprime, gtol=fmax * 0.1, norm=np.inf, maxiter=steps, full_output=1, disp=0, callback=self.callback)
        warnflag = output[-1]
        if warnflag == 2:
            raise OptimizerConvergenceError('Warning: Desired error not necessarily achieved due to precision loss')

