class OptimizerConvergenceError(Exception):
    pass

# --- helper: ase.optimize.sciopt.SciPyOptimizer ---
class SciPyOptimizer(Optimizer):

    def __init__(self, atoms: Atoms, logfile: IO | str='-', trajectory: str | None=None, callback_always: bool=False, alpha: float=70.0, **kwargs):
        restart = None
        super().__init__(atoms, restart, logfile, trajectory, **kwargs)
        self.force_calls = 0
        self.callback_always = callback_always
        self.H0 = alpha
        self.max_steps = 0

    def x0(self):
        return self.optimizable.get_x()

    def f(self, x):
        self.optimizable.set_x(x)
        return self.optimizable.get_value() / self.H0

    def fprime(self, x):
        self.optimizable.set_x(x)
        self.force_calls += 1
        if self.callback_always:
            self.callback(x)
        return self.optimizable.get_gradient() / self.H0

    def callback(self, x):
        if self.nsteps < self.max_steps:
            self.nsteps += 1
        gradient = self.optimizable.get_gradient()
        self.log(gradient)
        self.call_observers()
        if self.gradient_converged(gradient):
            raise Converged

    def run(self, fmax=0.05, steps=100000000):
        self.fmax = fmax
        try:
            if self.nsteps == 0:
                gradient = self.optimizable.get_gradient()
                self.log(gradient)
                self.call_observers()
            self.max_steps = steps + self.nsteps
            self.call_fmin(fmax / self.H0, steps)
        except Converged:
            pass
        gradient = self.optimizable.get_gradient()
        return self.gradient_converged(gradient)

    def dump(self, data):
        pass

    def load(self):
        pass

    def call_fmin(self, fmax, steps):
        raise NotImplementedError

def register_parallel_cleanup_function():
    if world.size == 1:
        return

    def cleanup(sys=sys, time=time, world=world):
        error = getattr(sys, 'last_type', None)
        if error:
            sys.stdout.flush()
            sys.stderr.write(('ASE CLEANUP (node %d): %s occurred.  ' + 'Calling MPI_Abort!\n') % (world.rank, error))
            sys.stderr.flush()
            time.sleep(3)
            world.abort(42)
    atexit.register(cleanup)

class SciPyGradientlessOptimizer(Optimizer):

    def __init__(self, atoms: Atoms, logfile: IO | str='-', trajectory: str | None=None, callback_always: bool=False, **kwargs):
        restart = None
        super().__init__(atoms, restart, logfile, trajectory, **kwargs)
        self.function_calls = 0
        self.callback_always = callback_always

    def x0(self):
        return self.optimizable.get_x().reshape(-1)

    def f(self, x):
        self.optimizable.set_x(x)
        self.function_calls += 1
        return self.optimizable.get_value()

    def callback(self, x):
        self.call_observers()
        self.nsteps += 1

    def run(self, ftol=0.01, xtol=0.01, steps=100000000):
        self.xtol = xtol
        self.ftol = ftol
        self.callback(None)
        try:
            self.call_fmin(xtol, ftol, steps)
        except Converged:
            pass
        return self.converged()

    def dump(self, data):
        pass

    def load(self):
        pass

    def call_fmin(self, xtol, ftol, steps):
        raise NotImplementedError

