# --- helper: ase.pourbaix.parse_formula ---
def parse_formula(formula: str, fmt: str='metal'):
    aq = formula.endswith('(aq)')
    charge = formula.count('+') - formula.count('-')
    formula_strip = formula.replace('(aq)', '').rstrip('+-')
    formula_obj = Formula(formula_strip, format=fmt)
    return (formula_obj, charge, aq)

def get_elasticity_tensor(atoms, h=0.001, verbose=False):
    cell0 = atoms.cell.copy()
    C_ijkl = np.zeros((3, 3, 3, 3))
    f = voigt_6_to_full_3x3_stress
    for k in range(3):
        for l in range(3):
            strain = np.eye(3)
            strain[k, l] += h
            atoms.set_cell(cell0 @ strain, scale_atoms=True)
            stressp_ij = f(atoms.get_stress())
            strain[k, l] -= 2 * h
            atoms.set_cell(cell0 @ strain, scale_atoms=True)
            stressm_ij = f(atoms.get_stress())
            C_ijkl[k, l] = (stressp_ij - stressm_ij) / (2 * h)
    if verbose:
        for i in range(3):
            for j in range(3):
                print(f'C_ijkl[{i}, {j}] =')
                for k in range(3):
                    for l in range(3):
                        print(round(C_ijkl[i, j, k, l], 2), end=' ')
                    print()
                print()
            print()
    return C_ijkl

# --- helper: ase.stress.voigt_6_to_full_3x3_stress ---
def voigt_6_to_full_3x3_stress(stress_vector):
    s1, s2, s3, s4, s5, s6 = np.transpose(stress_vector)
    return np.transpose([[s1, s6, s5], [s6, s2, s4], [s5, s4, s3]])

def get_product_combos(reactant, refs):
    ref_elem = reactant._main_elements
    allcombos = [[] for _ in range(len(ref_elem))]
    for ref in refs.values():
        contained = ref.contains(ref_elem)
        for w in np.argwhere(contained).flatten():
            allcombos[w].append(ref)
    return [np.unique(combo) for combo in product(*allcombos)]

class BaseThermoChem(ABC):

    def __init__(self, vib_energies: Sequence[float] | None=None, atoms: Atoms | None=None, modes: Sequence[AbstractMode] | None=None, spin: float | None=None) -> None:
        if vib_energies is None and modes is None:
            raise ValueError('Either vib_energies or modes must be provided.')
        elif modes:
            self.modes = modes
        else:
            self._vib_energies = vib_energies
        self.referencepressure = 100000.0
        if atoms:
            if atoms.pbc.any():
                raise ValueError('Atoms object should not have periodic boundary conditions for BaseThermoChem.')
            self.atoms = atoms
        self.spin = spin

    @classmethod
    def from_transition_state(cls, vib_energies: Sequence[complex], *args, **kwargs) -> 'BaseThermoChem':
        if sum(np.iscomplex(vib_energies)):
            with catch_warnings():
                simplefilter('ignore')
                vib_e, n_imag = _clean_vib_energies(vib_energies, True)
            if n_imag != 1:
                raise ValueError('Not exactly one imaginary frequency found.')
        else:
            raise ValueError('No imaginary frequencies found in vib_energies.')
        thermo = cls(vib_e, *args, **kwargs)
        return thermo

    @staticmethod
    def combine_contributions(contrib_dicts: Sequence[dict[str, float]]) -> dict[str, float]:
        ret: dict[str, float] = {}
        for contrib_dict in contrib_dicts:
            for key, value in contrib_dict.items():
                if key in ret:
                    ret[key] += value
                else:
                    ret[key] = value
        return ret

    def print_contributions(self, contributions: dict[str, float], verbose: bool) -> None:
        if verbose:
            fmt = '{:<15s}{:13.3f} eV'
            for key, value in contributions.items():
                if key.startswith('_'):
                    key.replace('_', '... ')
                self._vprint(fmt.format(key, value))

    @abstractmethod
    def get_internal_energy(self, temperature: float, verbose: bool) -> float:
        raise NotImplementedError

    @abstractmethod
    def get_entropy(self, temperature: float, pressure: float=units.bar, verbose: bool=True) -> float:
        raise NotImplementedError

    @property
    def vib_energies(self) -> np.ndarray:
        if hasattr(self, 'modes'):
            return np.array([mode.energy for mode in self.modes])
        elif hasattr(self, '_vib_energies'):
            return np.array(self._vib_energies)
        else:
            raise AttributeError('No vibrational energies available.')

    @vib_energies.setter
    def vib_energies(self, value: Sequence[float]) -> None:
        warn('The vib_energies attribute is deprecated and will be removed in afuture release. Please use the modes attribute instead.Setting this outside the constructor will not update the modes', DeprecationWarning)
        self._vib_energies = value

    def get_ZPE_correction(self) -> float:
        return 0.5 * np.sum(self.vib_energies)

    @staticmethod
    def get_ideal_translational_energy(temperature: float) -> float:
        return 3.0 / 2.0 * units.kB * temperature

    @staticmethod
    def get_ideal_rotational_energy(geometry: _GEOMETRY_OPTIONS, temperature: float) -> float:
        if geometry == 'nonlinear':
            Cv_r = 3.0 / 2.0 * units.kB
        elif geometry == 'linear':
            Cv_r = units.kB
        elif geometry == 'monatomic':
            Cv_r = 0.0
        else:
            raise ValueError('Invalid geometry: %s' % geometry)
        return Cv_r * temperature

    def get_ideal_trans_entropy(self, atoms: Atoms, temperature: float) -> float:
        mass = sum(atoms.get_masses()) * units._amu
        S_t = (2 * np.pi * mass * units._k * temperature / units._hplanck ** 2) ** (3.0 / 2)
        S_t *= units._k * temperature / self.referencepressure
        S_t = units.kB * (np.log(S_t) + 5.0 / 2.0)
        return S_t

    def get_vib_energy_contribution(self, temperature: float) -> float:
        kT = units.kB * temperature
        dU = 0.0
        for energy in self.vib_energies:
            dU += energy / (np.exp(energy / kT) - 1.0)
        return dU

    def get_vib_entropy_contribution(self, temperature: float, return_list: bool=False) -> float | Sequence[float]:
        kT = units.kB * temperature
        S_v = 0.0
        energies = np.array(self.vib_energies)
        energies /= kT
        S_v = energies / (np.exp(energies) - 1.0) - np.log(1.0 - np.exp(-energies))
        S_v *= units.kB
        if return_list:
            return S_v
        else:
            return np.sum(S_v)

    def _vprint(self, text):
        if self.verbose:
            sys.stdout.write(text + os.linesep)

    def get_ideal_entropy(self, temperature: float, translation: bool=False, vibration: bool=False, rotation: bool=False, geometry: _GEOMETRY_OPTIONS | None=None, electronic: bool=False, pressure: float | None=None, symmetrynumber: int | None=None) -> _FLOATWITHDICT:
        if geometry in ['linear', 'nonlinear'] and symmetrynumber is None:
            raise ValueError('Symmetry number required for linear and nonlinear molecules.')
        if not hasattr(self, 'atoms'):
            raise ValueError('Atoms object required for ideal entropy calculation.')
        if electronic and self.spin is None:
            raise ValueError('Spin value required for electronic entropy calculation.')
        S: float = 0.0
        ret = {}
        if translation:
            S_t = self.get_ideal_trans_entropy(self.atoms, temperature)
            ret['S_t'] = S_t
            S += S_t
            if pressure:
                S_p = -units.kB * np.log(pressure / self.referencepressure)
                S += S_p
                ret['S_p'] = S_p
        if rotation:
            if geometry == 'monatomic':
                S_r = 0.0
            elif geometry == 'nonlinear':
                inertias = self.atoms.get_moments_of_inertia() * units._amu / 10000000000.0 ** 2
                S_r = np.sqrt(np.pi * np.prod(inertias)) / symmetrynumber
                S_r *= (8.0 * np.pi ** 2 * units._k * temperature / units._hplanck ** 2) ** (3.0 / 2.0)
                S_r = units.kB * (np.log(S_r) + 3.0 / 2.0)
            elif geometry == 'linear':
                inertias = self.atoms.get_moments_of_inertia() * units._amu / (10.0 ** 10) ** 2
                inertia = max(inertias)
                S_r = 8 * np.pi ** 2 * inertia * units._k * temperature / symmetrynumber / units._hplanck ** 2
                S_r = units.kB * (np.log(S_r) + 1.0)
            else:
                raise RuntimeError(f'Invalid geometry: {geometry}')
            S += S_r
            ret['S_r'] = S_r
        if electronic:
            assert self.spin is not None
            S_e = units.kB * np.log(2 * self.spin + 1)
            S += S_e
            ret['S_e'] = S_e
        if vibration:
            S_v = self.get_vib_entropy_contribution(temperature, return_list=False)
            assert isinstance(S_v, float)
            S += S_v
            ret['S_v'] = S_v
        return (S, ret)

