# --- helper: ase.thermochemistry._clean_vib_energies ---
def _clean_vib_energies(vib_energies: Sequence[complex], ignore_imag_modes: bool=False) -> tuple[Sequence[float], int]:
    if ignore_imag_modes:
        n_vib_energies = len(vib_energies)
        vib_energies = [np.real(v) for v in vib_energies if np.real(v) > 0]
        n_imag = n_vib_energies - len(vib_energies)
        if n_imag > 0:
            warn(f'{n_imag} imag modes removed', UserWarning)
    else:
        if sum(np.iscomplex(vib_energies)):
            raise ValueError('Imaginary vibrational energies are present.')
        n_imag = 0
    ret = [np.real(v) for v in vib_energies]
    return (ret, n_imag)

def get_python_package_path_description(package, default='module has no path') -> str:
    try:
        p = list(package.__path__)
        if p:
            return str(p[0])
        else:
            return default
    except Exception as ex:
        return f'{default} ({ex})'

