implementation:
def check_imports(expression: str, *, forbidden_modules: list[str]=[], max_module_count: int | None=None, max_nonstdlib_module_count: int | None=None, do_print: bool=False) -> None:
    modules = exec_and_check_modules(expression)
    if do_print:
        print('all modules:')
        pprint(sorted(modules))
    for module_pattern in forbidden_modules:
        r = re.compile(module_pattern)
        for module in modules:
            assert not r.fullmatch(module), f'{module} was imported'
    if max_nonstdlib_module_count is not None:
        assert sys.version_info >= (3, 10), 'Python 3.10+ required'
        nonstdlib_modules = []
        for module in modules:
            if module.split('.')[0] in sys.stdlib_module_names:
                continue
            nonstdlib_modules.append(module)
        if do_print:
            print('nonstdlib modules:')
            pprint(sorted(nonstdlib_modules))
        module_count = len(nonstdlib_modules)
        assert module_count <= max_nonstdlib_module_count, f'too many nonstdlib modules loaded: {module_count}/{max_nonstdlib_module_count}'
    if max_module_count is not None:
        module_count = len(modules)
        assert module_count <= max_module_count, f'too many modules loaded: {module_count}/{max_module_count}'

# --- helper: ase.utils.checkimports.exec_and_check_modules ---
def exec_and_check_modules(expression: str) -> set[str]:
    null = os.devnull
    command = f"import sys; stdout = sys.stdout; sys.stdout = open({null!r}, 'w'); {expression}; sys.stdout = stdout; modules = list(sys.modules); import json; print(json.dumps(modules))"
    proc = run([sys.executable, '-c', command], capture_output=True, universal_newlines=True, check=True)
    return set(json.loads(proc.stdout))

class MSRRHOThermo(QuasiHarmonicThermo):

    def __init__(self, vib_energies: Sequence[complex], atoms: Atoms, potentialenergy: float=0.0, tau: float=35.0, nu_scal: float=1.0, treat_int_energy: bool=False, modes: Sequence[AbstractMode] | None=None) -> None:
        if atoms.pbc.any():
            raise ValueError('Atoms object should not have periodic boundary conditions for MSRRHOThermo.')
        inertia = np.mean(atoms.get_moments_of_inertia())
        self.atoms = atoms
        vib_e: Sequence[float]
        vib_e = [np.imag(v) if np.iscomplex(v) else np.real(v) for v in vib_energies]
        self.nu_scal = nu_scal
        vib_e_scaled = [float(v) for v in np.multiply(vib_e, nu_scal)]
        if modes is None:
            modes = [RRHOMode(energy, inertia, tau=tau, treat_int_energy=treat_int_energy) for energy in vib_e_scaled]
        super().__init__(vib_e_scaled, potentialenergy=potentialenergy, ignore_imag_modes=False, modes=modes, raise_to=0.0)
        self.treat_int_energy = treat_int_energy

