# --- helper: ase.thermochemistry.QuasiHarmonicThermo ---
class QuasiHarmonicThermo(HarmonicThermo):

    @staticmethod
    def _raise(input: Sequence[float], raise_to: float) -> Sequence[float]:
        return [raise_to if x < raise_to else x for x in input]

    def __init__(self, vib_energies: Sequence[complex], potentialenergy: float=0.0, ignore_imag_modes: bool=False, modes: Sequence[AbstractMode] | None=None, raise_to: float=100 * units.invcm) -> None:
        vib_energies, _ = _clean_vib_energies(vib_energies, ignore_imag_modes)
        vib_energies = self._raise(vib_energies, raise_to)
        if modes is None:
            modes = [HarmonicMode(energy) for energy in vib_energies]
        super().__init__(vib_energies, potentialenergy=potentialenergy, ignore_imag_modes=ignore_imag_modes, modes=modes)

# --- helper: ase.thermochemistry.RRHOMode ---
class RRHOMode(HarmonicMode):

    def __init__(self, energy: float, mean_inertia: float, tau: float=35.0, treat_int_energy: bool=False) -> None:
        if np.iscomplex(energy):
            raise ValueError('Imaginary frequencies are not allowed in RRHO mode.')
        super().__init__(energy)
        self._mean_inertia = mean_inertia
        self._tau = tau
        self._alpha = 4
        self.treat_int_energy = treat_int_energy

    @property
    def frequency(self) -> float:
        return self.energy / units.invcm

    def _head_gordon_damp(self, freq: float) -> float:
        return 1 / (1 + (self._tau / freq) ** self._alpha)

    def _apply_head_gordon_damp(self, freq: float, large_part: float, small_part: float) -> float:
        part_one = self._head_gordon_damp(freq) * large_part
        part_two = (1 - self._head_gordon_damp(freq)) * small_part
        return part_one + part_two

    def get_RRHO_entropy_r(self, temperature: float) -> float:
        kT = units._k * temperature
        R = units._k * units._Nav
        B_av = self._mean_inertia / (units.kg * units.m ** 2)
        omega = units._c * self.frequency * 100.0
        mu = units._hplanck / (8 * np.pi ** 2 * omega)
        mu_prime = mu * B_av / (mu + B_av)
        x = np.sqrt(8 * np.pi ** 3 * mu_prime * kT / units._hplanck ** 2)
        if x == 0.0:
            log_x = 0.0
        else:
            log_x = np.log(x)
        S_r = R * (0.5 + log_x)
        S_r *= units.J / units._Nav
        return S_r

    def get_entropy(self, temperature: float, contributions: bool) -> _FLOAT_OR_FLOATWITHDICT:
        ret = {}
        ret['_S_vib_v'] = self.get_vib_entropy_contribution(temperature)
        ret['_S_vib_r'] = self.get_RRHO_entropy_r(temperature)
        ret['S_vib_damped'] = self._apply_head_gordon_damp(self.frequency, ret['_S_vib_v'], ret['_S_vib_r'])
        if contributions:
            return (ret['S_vib_damped'], ret)
        else:
            return ret['S_vib_damped']

    def get_rrho_internal_energy_v_contribution(self, temperature: float) -> float:
        theta = self.energy / units.kB
        E_v = 0.5 + 1 / (np.exp(theta / temperature) - 1)
        E_v *= self.energy
        return E_v

    @staticmethod
    def get_rrho_internal_energy_r_contribution(temperature: float) -> float:
        R = units._k * units._Nav
        E_r = R * temperature / 2
        E_r *= units.J / units._Nav
        return E_r

    def get_internal_energy(self, temperature: float, contributions: bool) -> _FLOAT_OR_FLOATWITHDICT:
        if self.treat_int_energy:
            ret = {}
            ret['_dU_vib_v'] = self.get_rrho_internal_energy_v_contribution(temperature)
            ret['_dU_vib_r'] = self.get_rrho_internal_energy_r_contribution(temperature)
            ret['dU_vib_damped'] = self._apply_head_gordon_damp(self.frequency, ret['_dU_vib_v'], ret['_dU_vib_r'])
            if contributions:
                return (ret['dU_vib_damped'], ret)
            else:
                return ret['dU_vib_damped']
        else:
            return super().get_internal_energy(temperature, contributions)

def string2index(stridx: str) -> int | slice | str:
    if ':' not in stridx:
        try:
            return int(stridx)
        except ValueError:
            return stridx
    i = [None if s == '' else int(s) for s in stridx.split(':')]
    return slice(*i)

def ptable(spacing=2.5):
    zmax = 118
    z_values = np.arange(1, zmax + 1)
    positions = np.zeros((len(z_values), 3))
    x, y = (1, 1)
    for z in z_values:
        if z == 2:
            x += 16
        if z == 5 or z == 13:
            x += 10
        if z == 57 or z == 89:
            y += 3
        if z == 72 or z == 104:
            y -= 3
            x -= 14
        positions[z - 1] = (x, -y, 0)
        x += 1
        if x > 18:
            x = 1
            y += 1
    atoms = Atoms(z_values, positions * spacing)
    return atoms

