class CartesianRepresentationAttribute(Attribute):

    def __init__(self, default=None, secondary_attribute='', unit=None, **kwargs):
        super().__init__(default, secondary_attribute, **kwargs)
        self.unit = unit

    def convert_input(self, value):
        if isinstance(value, list) and len(value) == 3 and all((v == 0 for v in value)) and (self.unit is not None):
            return (CartesianRepresentation(np.zeros(3) * self.unit), True)
        else:
            if hasattr(value, 'xyz') and value.xyz.unit == self.unit:
                return (value, False)
            converted = True
            value = getattr(value, 'xyz', value)
            if not hasattr(value, 'unit'):
                raise TypeError(f'tried to set a {self.__class__.__name__} with something that does not have a unit.')
            value = value.to(self.unit)
            cartrep = CartesianRepresentation(value, copy=False)
            return (cartrep, converted)

