class QuantityAttribute(Attribute):

    def __init__(self, default=None, secondary_attribute='', unit=None, shape=None, **kwargs):
        if default is None and unit is None:
            raise ValueError('Either a default quantity value must be provided, or a unit must be provided to define a QuantityAttribute.')
        if default is not None and unit is None:
            unit = default.unit
        self.unit = unit
        self.shape = shape
        default = self.convert_input(default)[0]
        super().__init__(default, secondary_attribute, **kwargs)

    def convert_input(self, value):
        if value is None:
            return (None, False)
        if not hasattr(value, 'unit') and self.unit != u.dimensionless_unscaled and np.any(value != 0):
            raise TypeError('Tried to set a QuantityAttribute with something that does not have a unit.')
        oldvalue = value
        value = u.Quantity(oldvalue, self.unit, copy=COPY_IF_NEEDED)
        if self.shape is not None and value.shape != self.shape:
            if value.shape == () and oldvalue == 0:
                value = np.broadcast_to(value, self.shape, subok=True)
            else:
                raise ValueError(f'The provided value has shape "{value.shape}", but should have shape "{self.shape}"')
        converted = oldvalue is not value
        return (value, converted)

