# --- helper: astropy.coordinates.representation.cylindrical.CylindricalRepresentation ---
class CylindricalRepresentation(BaseRepresentation):
    attr_classes = {'rho': u.Quantity, 'phi': Angle, 'z': u.Quantity}

    def __init__(self, rho, phi=None, z=None, differentials=None, copy=True):
        super().__init__(rho, phi, z, copy=copy, differentials=differentials)
        if not self._rho.unit.is_equivalent(self._z.unit):
            raise u.UnitsError('rho and z should have matching physical types')

    @property
    def rho(self):
        return self._rho

    @property
    def phi(self):
        return self._phi

    @property
    def z(self):
        return self._z

    def unit_vectors(self):
        sinphi, cosphi = (np.sin(self.phi), np.cos(self.phi))
        l = np.broadcast_to(1.0, self.shape)
        return {'rho': CartesianRepresentation(cosphi, sinphi, 0, copy=COPY_IF_NEEDED), 'phi': CartesianRepresentation(-sinphi, cosphi, 0, copy=COPY_IF_NEEDED), 'z': CartesianRepresentation(0, 0, l, unit=u.one, copy=COPY_IF_NEEDED)}

    def scale_factors(self):
        rho = self.rho / u.radian
        l = np.broadcast_to(1.0 * u.one, self.shape, subok=True)
        return {'rho': l, 'phi': rho, 'z': l}

    @classmethod
    def from_cartesian(cls, cart):
        rho = np.hypot(cart.x, cart.y)
        phi = np.arctan2(cart.y, cart.x)
        z = cart.z
        return cls(rho=rho, phi=phi, z=z, copy=False)

    def to_cartesian(self):
        x = self.rho * np.cos(self.phi)
        y = self.rho * np.sin(self.phi)
        z = self.z
        return CartesianRepresentation(x=x, y=y, z=z, copy=False)

    def _scale_operation(self, op, *args):
        if any((differential.base_representation is not self.__class__ for differential in self.differentials.values())):
            return super()._scale_operation(op, *args)
        phi_op, _, rho_op = _spherical_op_funcs(op, *args)
        z_op = lambda x: op(x, *args)
        result = self.__class__(rho_op(self.rho), phi_op(self.phi), z_op(self.z), copy=COPY_IF_NEEDED)
        for key, differential in self.differentials.items():
            new_comps = (op(getattr(differential, comp)) for op, comp in zip((rho_op, operator.pos, z_op), differential.components))
            result.differentials[key] = differential.__class__(*new_comps, copy=False)
        return result

    def represent_as(self, other_class, differential_class=None):
        if isinstance(other_class, type):
            if issubclass(other_class, PhysicsSphericalRepresentation):
                diffs = self._re_represent_differentials(other_class, differential_class)
                r = np.hypot(self.rho, self.z)
                return other_class(r=r, theta=np.arctan2(self.rho, self.z), phi=self.phi, differentials=diffs)
        return super().represent_as(other_class, differential_class)

def is_rotation_or_reflection(matrix, atol=None):
    if atol is None:
        atol = 5 * np.finfo(matrix.dtype).eps if np.issubdtype(matrix.dtype, np.floating) else 1e-15
    return np.isclose(matrix @ matrix.swapaxes(-2, -1), np.identity(matrix.shape[-1]), atol=atol).all(axis=(-2, -1))

def get_body(body, time, location=None, ephemeris=None):
    if location is None:
        location = time.location
    if location is not None:
        obsgeoloc, obsgeovel = location.get_gcrs_posvel(time)
    else:
        obsgeoloc, obsgeovel = (None, None)
    cartrep = _get_apparent_body_position(body, time, ephemeris, obsgeoloc)
    icrs = ICRS(cartrep)
    gcrs = icrs.transform_to(GCRS(obstime=time, obsgeoloc=obsgeoloc, obsgeovel=obsgeovel))
    return SkyCoord(gcrs)

# --- helper: astropy.coordinates.solar_system._get_apparent_body_position ---
def _get_apparent_body_position(body, time, ephemeris, obsgeoloc=None):
    if ephemeris is None:
        ephemeris = solar_system_ephemeris.get()
    delta_light_travel_time = 20.0 * u.s
    emitted_time = time
    light_travel_time = 0.0 * u.s
    earth_loc = get_body_barycentric('earth', time, ephemeris)
    if obsgeoloc is not None:
        earth_loc += obsgeoloc
    while np.any(np.fabs(delta_light_travel_time) > 1e-08 * u.s):
        body_loc = get_body_barycentric(body, emitted_time, ephemeris)
        earth_distance = (body_loc - earth_loc).norm()
        delta_light_travel_time = light_travel_time - earth_distance / speed_of_light
        light_travel_time = earth_distance / speed_of_light
        emitted_time = time - light_travel_time
    return get_body_barycentric(body, emitted_time, ephemeris)

@dataclass_decorator
class FlatCosmologyMixin(metaclass=ABCMeta):
    _parameters: ClassVar[MappingProxyType[str, Parameter]]
    _parameters_derived: ClassVar[MappingProxyType[str, Parameter]]

    def __init_subclass__(cls: type[_FlatCosmoT]) -> None:
        super().__init_subclass__()
        cls.__nonflatclass__

    @classmethod
    def _get_nonflat_cls(cls, kls: type[_CosmoT] | None=None) -> type[Cosmology] | None:
        _kls = cls if kls is None else kls
        nonflat: set[type[Cosmology]]
        nonflat = {b for b in _kls.__bases__ if issubclass(b, Cosmology) and (not issubclass(b, FlatCosmologyMixin))}
        if not nonflat:
            nonflat = {k for b in _kls.__bases__ if (k := cls._get_nonflat_cls(b)) is not None}
        if len(nonflat) > 1:
            raise TypeError(f'cannot create a consistent non-flat class resolution order for {_kls} with bases {nonflat} at the same inheritance level.')
        if not nonflat:
            return None
        return nonflat.pop()
    __nonflatclass__ = classproperty(_get_nonflat_cls, lazy=True, doc='Return the corresponding non-flat class.')

    @property
    def is_flat(self) -> Literal[True]:
        return True

    @property
    @abstractmethod
    def nonflat(self: _FlatCosmoT) -> _CosmoT:
        pass

    def clone(self, *, meta: CosmoMeta | None=None, to_nonflat: bool=False, **kwargs: Any) -> 'Cosmology':
        if to_nonflat:
            return self.nonflat.clone(meta=meta, **kwargs)
        return super().clone(meta=meta, **kwargs)

    def __equiv__(self, other: Any, /) -> bool:
        if isinstance(other, FlatCosmologyMixin):
            return super().__equiv__(other)
        if not issubclass(other.__class__, self.__nonflatclass__):
            return NotImplemented
        return self._parameters_all == other._parameters_all and all((np.all(getattr(self, k) == getattr(other, k)) for k in self.parameters)) and other.is_flat

