@dataclass_decorator
class Cosmology(metaclass=ABCMeta):
    _: KW_ONLY
    name: _NameField = _NameField()
    "The name of the cosmology realization, e.g. 'Planck2018' or `None`."
    meta: MetaData = MetaData()
    from_format: ClassVar = UnifiedReadWriteMethod(CosmologyFromFormat)
    to_format: ClassVar = UnifiedReadWriteMethod(CosmologyToFormat)
    read: ClassVar = UnifiedReadWriteMethod(CosmologyRead)
    write: ClassVar = UnifiedReadWriteMethod(CosmologyWrite)
    parameters = ParametersAttribute(attr_name='_parameters')
    'Immutable mapping of the Parameters.\n\n    If accessed from the class, this returns a mapping of the Parameter\n    objects themselves.  If accessed from an instance, this returns a\n    mapping of the values of the Parameters.\n    '
    _derived_parameters = ParametersAttribute(attr_name='_parameters_derived')
    'Immutable mapping of the derived Parameters.\n\n    If accessed from the class, this returns a mapping of the Parameter\n    objects themselves.  If accessed from an instance, this returns a\n    mapping of the values of the Parameters.\n    '
    _parameters: ClassVar = MappingProxyType[str, Parameter]({})
    _parameters_derived: ClassVar = MappingProxyType[str, Parameter]({})
    _parameters_all: ClassVar = frozenset[str]()
    __signature__: ClassVar[inspect.Signature | None] = None

    def __init_subclass__(cls) -> None:
        super().__init_subclass__()
        all_params = all_parameters(cls)
        cls._parameters = MappingProxyType({k: v for k, v in all_params.items() if not v.derived})
        cls._derived_parameters = MappingProxyType({k: v for k, v in all_params.items() if v.derived})
        cls._parameters_all = frozenset(all_params)
        if not inspect.isabstract(cls):
            cls._register_cls()

    @classmethod
    def _register_cls(cls) -> None:
        _COSMOLOGY_CLASSES[cls.__qualname__] = cls
        from astropy.cosmology._src.io.builtin.yaml import register_cosmology_yaml
        register_cosmology_yaml(cls)

    def __post_init__(self) -> None:
        pass

    @property
    @abstractmethod
    def is_flat(self) -> bool:
        raise NotImplementedError('is_flat is not implemented')

    def clone(self, *, meta: CosmoMeta | None=None, **kwargs: Any) -> 'Cosmology':
        if meta is None and (not kwargs):
            return self
        _modname = self.name + ' (modified)'
        kwargs.setdefault('name', _modname if self.name is not None else None)
        meta = meta if meta is not None else {}
        cloned = replace(self, meta=self.meta | meta, **kwargs)
        if cloned.name == _modname and (not meta) and cloned.is_equivalent(self):
            object.__setattr__(cloned, 'name', self.name)
        return cloned

    @classproperty
    def _init_has_kwargs(cls) -> bool:
        return next(reversed(cls.__signature__.parameters.values())).kind == inspect.Parameter.VAR_KEYWORD

    def is_equivalent(self, other: Any, /, *, format: bool | None | str=False) -> bool:
        from astropy.cosmology._src.funcs import cosmology_equal
        try:
            return cosmology_equal(self, other, format=(None, format), allow_equivalent=True)
        except Exception:
            return False

    def __equiv__(self, other: Any, /) -> bool:
        if other.__class__ is not self.__class__:
            return NotImplemented
        return self._parameters_all == other._parameters_all and all((np.all(getattr(self, k) == getattr(other, k)) for k in self._parameters_all))

    def __eq__(self, other: Any, /) -> bool:
        if other.__class__ is not self.__class__:
            return NotImplemented
        return self.name == other.name and self._parameters_all == other._parameters_all and all((np.all(getattr(self, k) == getattr(other, k)) for k in self._parameters_all))

    def __str__(self) -> str:
        name_str = '' if self.name is None else f'name="{self.name}", '
        param_strs = (f'{k!s}={v!s}' for k, v in self.parameters.items())
        return f"{type(self).__name__}({name_str}{', '.join(param_strs)})"

    def __astropy_table__(self, cls: type[Table], copy: bool, **kwargs: Any) -> Table:
        return self.to_format('astropy.table', cls=cls, **kwargs)

