def phi_amplitude_b_inside(Om0: float, Ok0: float, y1: float, y2: float, z: NDArray[np.number], /) -> NDArray[np.number]:
    return np.arcsin(np.sqrt((y1 - y2) / ((z + 1.0) * Om0 / abs(Ok0) + y1)))

# --- helper: astropy.cosmology._src.flrw.lambdacdm.phi_amplitude_b_outside ---
def phi_amplitude_b_outside(Om0: float, Ok0: float, kappa: float, y1: float, A: float, z: NDArray[np.number], /) -> NDArray[np.number]:
    return np.arccos(((z + 1.0) * Om0 / abs(Ok0) + kappa * y1 - A) / ((z + 1.0) * Om0 / abs(Ok0) + kappa * y1 + A))

class CurvatureComponent:

    @property
    @abc.abstractmethod
    def Ok0(self) -> float | np.floating:
        raise NotImplementedError

    @property
    @abc.abstractmethod
    def is_flat(self) -> bool:
        raise NotImplementedError

    @deprecated_keywords('z', since='7.0')
    def Ok(self, z: Quantity | ArrayLike) -> NDArray[np.floating]:
        z = aszarr(z)
        if self.Ok0 == 0:
            return np.zeros(getattr(z, 'shape', ()))
        return self.Ok0 * (z + 1.0) ** 2 * self.inv_efunc(z) ** 2

class HubbleParameter:
    H0: Quantity
    'Hubble Parameter at redshift 0.'
    efunc: Callable[[Any], NDArray[Any]]
    inv_efunc: Callable[[Any], FArray | float]

    @deprecated_keywords('z', since='7.0')
    def H(self, z: Quantity | ArrayLike) -> Quantity:
        return self.H0 * self.efunc(z)

    @cached_property
    def h(self) -> np.floating:
        return self.H0.to_value('km/(s Mpc)') / 100.0

    @cached_property
    def hubble_time(self) -> u.Quantity:
        return (1 / self.H0).to(u.Gyr)

    @cached_property
    def hubble_distance(self) -> u.Quantity:
        return (const.c / self.H0).to(u.Mpc)

class ScaleFactor:

    @property
    def scale_factor0(self) -> u.Quantity:
        return 1 << u.one

    @deprecated_keywords('z', since='7.0')
    def scale_factor(self, z: u.Quantity | ArrayLike) -> u.Quantity:
        return self.scale_factor0 / (aszarr(z) + 1)

