@dataclass_decorator
class wpwaCDM(FLRW):
    wp: Parameter = Parameter(default=-1.0, doc='Dark energy equation of state at the pivot redshift zp.', fvalidate='float')
    wa: Parameter = Parameter(default=0.0, doc='Negative derivative of dark energy equation of state w.r.t. a.', fvalidate='float')
    zp: Parameter = Parameter(default=0.0 * cu.redshift, doc='The pivot redshift, where w(z) = wp.', unit=cu.redshift)

    def __post_init__(self) -> None:
        super().__post_init__()
        apiv = 1.0 / (1.0 + self.zp.value)
        if self.Tcmb0.value == 0:
            inv_efunc_scalar = scalar_inv_efuncs.wpwacdm_inv_efunc_norel
            inv_efunc_scalar_args = (self.Om0, self.Ode0, self.Ok0, self.wp, apiv, self.wa)
        elif not self._nu_info.has_massive_nu:
            inv_efunc_scalar = scalar_inv_efuncs.wpwacdm_inv_efunc_nomnu
            inv_efunc_scalar_args = (self.Om0, self.Ode0, self.Ok0, self.Ogamma0 + self.Onu0, self.wp, apiv, self.wa)
        else:
            inv_efunc_scalar = scalar_inv_efuncs.wpwacdm_inv_efunc
            inv_efunc_scalar_args = (self.Om0, self.Ode0, self.Ok0, self.Ogamma0, self._nu_info.neff_per_nu, self._nu_info.n_massless_nu, self._nu_info.nu_y_list, self.wp, apiv, self.wa)
        object.__setattr__(self, '_inv_efunc_scalar', inv_efunc_scalar)
        object.__setattr__(self, '_inv_efunc_scalar_args', inv_efunc_scalar_args)

    @deprecated_keywords('z', since='7.0')
    def w(self, z: Quantity | ArrayLike) -> FArray:
        apiv = 1.0 / (1.0 + self.zp.value)
        return self.wp + self.wa * (apiv - 1.0 / (aszarr(z) + 1.0))

    @deprecated_keywords('z', since='7.0')
    def de_density_scale(self, z: Quantity | ArrayLike) -> FArray:
        z = aszarr(z)
        zp1 = z + 1.0
        apiv = 1.0 / (1.0 + self.zp.value)
        return zp1 ** (3.0 * (1.0 + self.wp + apiv * self.wa)) * exp(-3.0 * self.wa * z / zp1)

