        else:
            inv_efunc_scalar = scalar_inv_efuncs.wcdm_inv_efunc
            inv_efunc_scalar_args = (self.Om0, self.Ode0, self.Ok0, self.Ogamma0, self._nu_info.neff_per_nu, self._nu_info.n_massless_nu, self._nu_info.nu_y_list, self.w0)
        object.__setattr__(self, '_inv_efunc_scalar', inv_efunc_scalar)
        object.__setattr__(self, '_inv_efunc_scalar_args', inv_efunc_scalar_args)

    @deprecated_keywords('z', since='7.0')
    def w(self, z: Quantity | ArrayLike) -> FArray:
        return self.w0 * np.ones_like(aszarr(z))

    @deprecated_keywords('z', since='7.0')
    def de_density_scale(self, z: Quantity | ArrayLike) -> FArray:
        return (aszarr(z) + 1.0) ** (3.0 * (1.0 + self.w0))

    @deprecated_keywords('z', since='7.0')
    def efunc(self, z: Quantity | ArrayLike) -> FArray:
        Or = self.Ogamma0 + (self.Onu0 if not self._nu_info.has_massive_nu else self.Ogamma0 * self.nu_relative_density(z))
        zp1 = aszarr(z) + 1.0
        return sqrt(zp1 ** 2 * ((Or * zp1 + self.Om0) * zp1 + self.Ok0) + self.Ode0 * zp1 ** (3.0 * (1.0 + self.w0)))

    @deprecated_keywords('z', since='7.0')
    def inv_efunc(self, z: Quantity | ArrayLike) -> FArray:
        Or = self.Ogamma0 + (self.Onu0 if not self._nu_info.has_massive_nu else self.Ogamma0 * self.nu_relative_density(z))
        zp1 = aszarr(z) + 1.0
        return (zp1 ** 2 * ((Or * zp1 + self.Om0) * zp1 + self.Ok0) + self.Ode0 * zp1 ** (3.0 * (1.0 + self.w0))) ** (-0.5)

