def z_at_value(func, fval, zmin: ArrayLike=1e-08, zmax: ArrayLike=1000, ztol: ArrayLike=1e-08, maxfun: int | npt.NDArray[np.integer]=500, method: str | _CustomSolverCallable='Brent', bracket: npt.NDArray[np.void] | _BracketSingle | None=None, *, verbose: bool=False) -> Quantity:
    fval = np.asanyarray(fval)
    unit = getattr(fval, 'unit', 1)
    zmin = Quantity(zmin, cu.redshift).value
    zmax = Quantity(zmax, cu.redshift).value
    if not isinstance(bracket, np.ndarray):
        if bracket is not None and len(bracket) not in (2, 3):
            raise ValueError('`bracket` is not an array nor a 2 (or 3) element sequence.')
        else:
            bracket = np.array([bracket, ()], dtype=object)[:1].squeeze()
    if bracket.dtype != np.object_:
        raise TypeError(f"`bracket` has dtype {bracket.dtype}, not 'O'")
    with np.nditer([fval, zmin, zmax, ztol, maxfun, bracket, None], flags=['refs_ok'], op_flags=[*[['readonly']] * 6, ['writeonly', 'allocate', 'no_subtype']], op_dtypes=(*(None,) * 6, fval.dtype), casting='no') as it:
        for fv, zmn, zmx, zt, mfe, bkt, zs in it:
            zs[...] = _z_at_scalar_value(func, fv * unit, zmin=zmn, zmax=zmx, ztol=zt, maxfun=mfe, bracket=bkt.item(), method=method, verbose=verbose)
        result = it.operands[-1]
    return result << cu.redshift

