class _CustomSolverCallable(Protocol):

    def __call__(self, fun: Callable[..., Any], args: tuple[Any, ...], **kwargs: Any) -> 'scipy.optimize.OptimizeResult':
        ...

# --- helper: astropy.cosmology._src.funcs.optimize._z_at_scalar_value ---
def _z_at_scalar_value(func, fval: float | FArray | Quantity, zmin: float | FArray | Quantity=1e-08, zmax: float | FArray | Quantity=1000, ztol: float | FArray=1e-08, maxfun: int | npt.NDArray[np.integer]=500, method: str | _CustomSolverCallable='Brent', bracket: _BracketSingle | None=None, verbose: bool=False) -> float:
    from scipy.optimize import minimize_scalar
    opt = {'maxiter': maxfun, 'xtol': ztol}
    if callable(method):
        pass
    elif str(method).lower() == 'bounded':
        opt['xatol'] = opt.pop('xtol')
        if bracket is not None:
            warnings.warn(f"Option 'bracket' is ignored by method {method}.")
            bracket = None
    fval_zmin, fval_zmax = (func(zmin), func(zmax))
    nobracket = False
    if np.sign(fval - fval_zmin) != np.sign(fval_zmax - fval):
        if bracket is None:
            nobracket = True
        else:
            fval_brac = func(np.asanyarray(bracket))
            if np.sign(fval - fval_brac[0]) != np.sign(fval_brac[-1] - fval):
                nobracket = True
            else:
                zmin, zmax = (bracket[0], bracket[-1])
                fval_zmin, fval_zmax = fval_brac[[0, -1]]
    if nobracket:
        warnings.warn(f'fval is not bracketed by func(zmin)={fval_zmin} and func(zmax)={fval_zmax}. This means either there is no solution, or that there is more than one solution between zmin and zmax satisfying fval = func(z).', AstropyUserWarning)
    if isinstance(fval_zmin, Quantity):
        val = fval.to_value(fval_zmin.unit)
    else:
        val = fval
    if callable(method) or str(method).lower() not in {'brent', 'golden'}:
        bounds = (zmin, zmax)
    else:
        bounds = None

    def f(z):
        if z > zmax:
            return 1e+300 * (1.0 + z - zmax)
        elif z < zmin:
            return 1e+300 * (1.0 + zmin - z)
        elif isinstance(fval_zmin, Quantity):
            return abs(func(z).value - val)
        else:
            return abs(func(z) - val)
    res = minimize_scalar(f, method=method, bounds=bounds, bracket=bracket, options=opt)
    if not res.success:
        warnings.warn(f"Solver returned {res.get('status')}: {res.get('message', 'Unsuccessful')}\nPrecision {res.fun} reached after {res.nfev} function calls.", AstropyUserWarning)
    if verbose:
        print(res)
    if np.allclose(res.x, zmax):
        raise CosmologyError(f'Best guess z={res.x} is very close to the upper z limit {zmax}.\nTry re-running with a different zmax.')
    elif np.allclose(res.x, zmin):
        raise CosmologyError(f'Best guess z={res.x} is very close to the lower z limit {zmin}.\nTry re-running with a different zmin.')
    return res.x

