def table_to_hdu(table, character_as_bytes=False, name=None):
    from .column import python_to_tdisp
    from .connect import REMOVE_KEYWORDS, is_column_keyword
    hdr = None
    if table.has_mixin_columns:
        from astropy.table.column import BaseColumn
        from astropy.time import Time
        from astropy.units import Quantity
        from .fitstime import time_to_fits
        unsupported_cols = table.columns.not_isinstance((BaseColumn, Quantity, Time))
        if unsupported_cols:
            unsupported_names = [col.info.name for col in unsupported_cols]
            raise ValueError(f'cannot write table with mixin column(s) {unsupported_names}')
        time_cols = table.columns.isinstance(Time)
        if time_cols:
            table, hdr = time_to_fits(table)
    tarray = table.as_array()
    if isinstance(tarray, np.ma.MaskedArray):
        default_fill_value = np.ma.default_fill_value(tarray.dtype)
        for colname, (coldtype, _) in tarray.dtype.fields.items():
            if np.all(tarray.fill_value[colname] == default_fill_value[colname]):
                coltype = coldtype.subdtype[0].type if coldtype.subdtype else coldtype.type
                if issubclass(coltype, np.complexfloating):
                    tarray.fill_value[colname] = complex(np.nan, np.nan)
                elif issubclass(coltype, np.inexact):
                    tarray.fill_value[colname] = np.nan
                elif issubclass(coltype, np.character):
                    tarray.fill_value[colname] = ''
        table_hdu = BinTableHDU.from_columns(tarray.filled(), header=hdr, character_as_bytes=character_as_bytes)
        for col in table_hdu.columns:
            int_formats = ('B', 'I', 'J', 'K')
            if (col.format.format in int_formats or col.format.p_format in int_formats) and hasattr(table[col.name], 'mask'):
                fill_value = tarray[col.name].fill_value
                col.null = fill_value.astype(int)
    else:
        table_hdu = BinTableHDU.from_columns(tarray, header=hdr, character_as_bytes=character_as_bytes)
    if name is not None:
        table_hdu.name = name
    for col in table_hdu.columns:
        if table[col.name].info.format is not None:
            logical = table[col.name].info.dtype == bool
            tdisp_format = python_to_tdisp(table[col.name].info.format, logical_dtype=logical)
            if tdisp_format is not None:
                col.disp = tdisp_format
        unit = table[col.name].unit
        if unit is not None:
            from astropy.units import Unit
            from astropy.units.format.fits import UnitScaleError
            try:
                col.unit = unit.to_string(format='fits')
            except UnitScaleError:
                scale = unit.scale
                raise UnitScaleError(f"The column '{col.name}' could not be stored in FITS format because it has a scale '({str(scale)})' that is not recognized by the FITS standard. Either scale the data or change the units.")
            except ValueError:
                warning = f"The unit '{unit.to_string()}' could not be saved in native FITS format "
                if any(('SerializedColumn' in item and 'name: ' + col.name in item for item in table.meta.get('comments', []))):
                    warning += 'and hence will be lost to non-astropy fits readers. Within astropy, the unit can roundtrip using QTable, though one has to enable the unit before reading.'
                else:
                    warning += 'and cannot be recovered in reading. It can roundtrip within astropy by using QTable both to write and read back, though one has to enable the unit before reading.'
                warnings.warn(warning, AstropyUserWarning)
            else:
                Unit(col.unit, format='fits', parse_strict='warn')
    coord_meta = table.meta.pop('__coordinate_columns__', {})
    for col_name, col_info in coord_meta.items():
        col = table_hdu.columns[col_name]
        for attr in ('coord_type', 'coord_unit'):
            setattr(col, attr, col_info.get(attr, None))
        trpos = col_info.get('time_ref_pos', None)
        if trpos is not None:
            col.time_ref_pos = trpos
    for key, value in table.meta.items():
        if is_column_keyword(key.upper()) or key.upper() in REMOVE_KEYWORDS:
            warnings.warn(f'Meta-data keyword {key} will be ignored since it conflicts with a FITS reserved keyword', AstropyUserWarning)
            continue
        if key == 'comments':
            key = 'comment'
        if isinstance(value, list):
            for item in value:
                try:
                    table_hdu.header.append((key, item))
                except ValueError:
                    warnings.warn(f'Attribute `{key}` of type {type(value)} cannot be added to FITS Header - skipping', AstropyUserWarning)
        else:
            try:
                table_hdu.header[key] = value
            except ValueError:
                warnings.warn(f'Attribute `{key}` of type {type(value)} cannot be added to FITS Header - skipping', AstropyUserWarning)
    return table_hdu

