def process_object_data(col: ColumnECSV, str_vals: list[str] | npt.NDArray[np.str_], mask: npt.NDArray[np.bool_] | None) -> tuple[np.ndarray | np.ma.MaskedArray, tuple[int, ...]]:
    if mask is not None:
        for idx in np.nonzero(mask)[0]:
            str_vals[idx] = '0'
    col_vals = [json.loads(val) for val in str_vals]
    np_empty = np.empty if mask is None else np.ma.empty
    data_out = np_empty((len(col_vals),) + tuple(col.shape), dtype=object)
    data_out[...] = col_vals
    if mask is not None:
        data_out.mask = mask
    return (data_out, col.shape)

