def write_ecsv(tbl, output, engine='io.ascii', **kwargs):
    if engine != 'io.ascii':
        raise ValueError(f"engine={engine!r} is not a supported engine for writing, use 'io.ascii'")
    tbl.write(output, format='ascii.ecsv', **kwargs)

