def check_has_pyarrow():
    if not HAS_PYARROW:
        raise ModuleNotFoundError('pyarrow is required for astropy.io.misc.pyarrow.csv functions')

# --- helper: astropy.io.misc.pyarrow.csv.convert_pa_string_array_to_numpy ---
def convert_pa_string_array_to_numpy(arr: 'pyarrow.Array') -> NDArray:
    check_has_pyarrow()
    import pyarrow as pa
    import pyarrow.compute as pc
    max_length = pa.compute.max(pc.utf8_length(arr))
    out = np.empty(len(arr), dtype=f'U{max_length}')
    out[:] = arr.to_numpy()
    return out

# --- helper: astropy.io.misc.pyarrow.csv.pyarrow_zero ---
def pyarrow_zero(data_type: 'pyarrow.DataType'):
    check_has_pyarrow()
    import pyarrow as pa
    if pa.types.is_integer(data_type) or pa.types.is_floating(data_type):
        return 0
    elif pa.types.is_boolean(data_type):
        return False
    elif pa.types.is_string(data_type) or pa.types.is_large_string(data_type):
        return ''
    elif pa.types.is_binary(data_type) or pa.types.is_large_binary(data_type):
        return b''
    elif pa.types.is_date(data_type):
        return datetime.date(1970, 1, 1)
    elif pa.types.is_time(data_type):
        return datetime.time(0, 0, 0)
    elif pa.types.is_timestamp(data_type):
        return datetime.datetime(1970, 1, 1)
    elif pa.types.is_null(data_type):
        return None
    elif pa.types.is_decimal(data_type):
        import decimal
        return decimal.Decimal(0)
    else:
        raise NotImplementedError(f'No zero value defined for type: {data_type}')

