class FitInfoArrayContainer:

    def __init__(self, fit_info_array):
        self._fit_info_array = fit_info_array

    @property
    def shape(self):
        return self._fit_info_array.shape

    @property
    def ndim(self):
        return self._fit_info_array.ndim

    def __getitem__(self, item):
        result = self._fit_info_array[item]
        if hasattr(result, 'ndim'):
            return FitInfoArrayContainer(result)
        else:
            return result

    def get_property_as_array(self, name):
        array = None
        for index in np.ndindex(self._fit_info_array.shape):
            fit_info = self._fit_info_array[index]
            if fit_info is not None:
                value = np.array(getattr(fit_info, name))
                if array is None:
                    array = np.zeros(self.shape + value.shape, dtype=value.dtype)
                if value.shape != array.shape[self.ndim:]:
                    raise ValueError('Property {name} does not have consistent shape in all fit_info')
                array[index] = value
        return array

    @property
    def properties(self):
        for index in np.ndindex(self._fit_info_array.shape):
            fit_info = self._fit_info_array[index]
            if fit_info is not None:
                return tuple(sorted(fit_info))
        return ()

def fitter_to_model_params_array(model, fps, use_min_max_bounds=True, *, fit_param_indices=None):
    has_tied = model.has_tied
    has_bound = use_min_max_bounds and model.has_bounds
    if not (has_tied or model.has_fixed or has_bound):
        return fps
    bounds = model.bounds
    param_metrics = model._param_metrics
    parameters = np.empty(sum((m['size'] for m in param_metrics.values())), dtype=float)
    if fit_param_indices is None:
        _, fit_param_indices, _ = model_to_fit_params(model)
    offset = 0
    for idx, name in enumerate(model.param_names):
        metrics = param_metrics[name]
        slice_ = metrics['slice']
        if idx not in fit_param_indices:
            parameters[slice_] = getattr(model, name).value
            continue
        shape = metrics['shape']
        size = metrics['size']
        values = fps[offset:offset + size]
        bound = bounds[name]
        if has_bound and bound != (None, None):
            _min, _max = bound
            if _min is not None:
                values = np.fmax(values, _min)
            if _max is not None:
                values = np.fmin(values, _max)
        parameters[slice_] = values
        offset += size
    if has_tied:
        model.parameters = parameters
        for name in model.param_names:
            if model.tied[name]:
                value = model.tied[name](model)
                slice_ = param_metrics[name]['slice']
                parameters[slice_] = value
                model._array_to_parameters()
    return parameters

# --- helper: astropy.modeling.fitting.model_to_fit_params ---
def model_to_fit_params(model):
    fit_param_indices = list(range(len(model.param_names)))
    model_params = model.parameters
    model_bounds = list(model.bounds.values())
    if model.has_fixed or model.has_tied:
        params = list(model_params)
        param_metrics = model._param_metrics
        for idx, name in list(enumerate(model.param_names))[::-1]:
            if model.fixed[name] or model.tied[name]:
                slice_ = param_metrics[name]['slice']
                del params[slice_]
                del model_bounds[slice_]
                del fit_param_indices[idx]
        model_params = np.array(params)
    for idx, bound in enumerate(model_bounds):
        if bound[0] is None:
            lower = -np.inf
        else:
            lower = bound[0]
        if bound[1] is None:
            upper = np.inf
        else:
            upper = bound[1]
        model_bounds[idx] = (lower, upper)
    model_bounds = tuple(zip(*model_bounds))
    return (model_params, fit_param_indices, model_bounds)

