class Lorentz2D(Fittable2DModel):
    amplitude = Parameter(default=1, description='Peak value')
    x_0 = Parameter(default=0, description='Position of the peak in x')
    y_0 = Parameter(default=0, description='Position of the peak in y')
    fwhm = Parameter(default=1, description='Full width at half maximum')

    @staticmethod
    def evaluate(x, y, amplitude, x_0, y_0, fwhm):
        return amplitude * ((fwhm / 2.0) ** 2 / ((x - x_0) ** 2 + (y - y_0) ** 2 + (fwhm / 2.0) ** 2))

    @staticmethod
    def fit_deriv(x, y, amplitude, x_0, y_0, fwhm):
        gamma = fwhm / 2.0
        r2 = (x - x_0) ** 2 + (y - y_0) ** 2
        denom = gamma ** 2 + r2
        denom2 = denom ** 2
        d_amplitude = gamma ** 2 / denom
        d_x_0 = amplitude * gamma ** 2 * 2 * (x - x_0) / denom2
        d_y_0 = amplitude * gamma ** 2 * 2 * (y - y_0) / denom2
        d_fwhm = amplitude * (fwhm / 2) * r2 / denom2
        return [d_amplitude, d_x_0, d_y_0, d_fwhm]

    def bounding_box(self, factor=25):
        x0 = self.x_0
        y0 = self.y_0
        dx = factor * self.fwhm
        return ((x0 - dx, x0 + dx), (y0 - dx, y0 + dx))

    @property
    def input_units(self):
        x_unit = self.x_0.input_unit
        y_unit = self.y_0.input_unit
        if x_unit is None and y_unit is None:
            return None
        return {self.inputs[0]: x_unit, self.inputs[1]: y_unit}

    def _parameter_units_for_data_units(self, inputs_unit, outputs_unit):
        if inputs_unit[self.inputs[0]] != inputs_unit[self.inputs[1]]:
            raise UnitsError("Units of 'x' and 'y' inputs should match")
        return {'x_0': inputs_unit[self.inputs[0]], 'y_0': inputs_unit[self.inputs[0]], 'fwhm': inputs_unit[self.inputs[0]], 'amplitude': outputs_unit[self.outputs[0]]}

def bitfield_to_boolean_mask(bitfield, ignore_flags=0, flip_bits=None, good_mask_value=False, dtype=np.bool_, flag_name_map=None):
    bitfield = np.asarray(bitfield)
    if not np.issubdtype(bitfield.dtype, np.integer):
        raise TypeError('Input bitfield array must be of integer type.')
    ignore_mask = interpret_bit_flags(ignore_flags, flip_bits=flip_bits, flag_name_map=flag_name_map)
    if ignore_mask is None:
        if good_mask_value:
            mask = np.ones_like(bitfield, dtype=dtype)
        else:
            mask = np.zeros_like(bitfield, dtype=dtype)
        return mask
    ignore_mask = ignore_mask & _SUPPORTED_FLAGS
    ignore_mask = np.bitwise_not(ignore_mask, dtype=bitfield.dtype.type, casting='unsafe')
    mask = np.empty_like(bitfield, dtype=np.bool_)
    np.bitwise_and(bitfield, ignore_mask, out=mask, casting='unsafe')
    if good_mask_value:
        np.logical_not(mask, out=mask)
    return mask.astype(dtype=dtype, subok=False, copy=False)

# --- helper: astropy.nddata.bitmask.interpret_bit_flags ---
def interpret_bit_flags(bit_flags, flip_bits=None, flag_name_map=None):
    has_flip_bits = flip_bits is not None
    flip_bits = bool(flip_bits)
    allow_non_flags = False
    if _is_int(bit_flags):
        return ~int(bit_flags) if flip_bits else int(bit_flags)
    elif bit_flags is None:
        if has_flip_bits:
            raise TypeError("Keyword argument 'flip_bits' must be set to 'None' when input 'bit_flags' is None.")
        return None
    elif isinstance(bit_flags, str):
        if has_flip_bits:
            raise TypeError("Keyword argument 'flip_bits' is not permitted for comma-separated string lists of bit flags. Prepend '~' to the string to indicate bit-flipping.")
        bit_flags = str(bit_flags).strip()
        if bit_flags.upper() in ['', 'NONE', 'INDEF']:
            return None
        bitflip_pos = bit_flags.find('~')
        if bitflip_pos == 0:
            flip_bits = True
            bit_flags = bit_flags[1:].lstrip()
        else:
            if bitflip_pos > 0:
                raise ValueError('Bitwise-NOT must precede bit flag list.')
            flip_bits = False
        while True:
            nlpar = bit_flags.count('(')
            nrpar = bit_flags.count(')')
            if nlpar == 0 and nrpar == 0:
                break
            if nlpar != nrpar:
                raise ValueError('Unbalanced parentheses in bit flag list.')
            lpar_pos = bit_flags.find('(')
            rpar_pos = bit_flags.rfind(')')
            if lpar_pos > 0 or rpar_pos < len(bit_flags) - 1:
                raise ValueError('Incorrect syntax (incorrect use of parenthesis) in bit flag list.')
            bit_flags = bit_flags[1:-1].strip()
        if sum((k in bit_flags for k in '+,|')) > 1:
            raise ValueError("Only one type of bit flag separator may be used in one expression. Allowed separators are: '+', '|', or ','.")
        if ',' in bit_flags:
            bit_flags = bit_flags.split(',')
        elif '+' in bit_flags:
            bit_flags = bit_flags.split('+')
        elif '|' in bit_flags:
            bit_flags = bit_flags.split('|')
        else:
            if bit_flags == '':
                raise ValueError('Empty bit flag lists not allowed when either bitwise-NOT or parenthesis are present.')
            bit_flags = [bit_flags]
        bit_flags = [f.strip() for f in bit_flags]
        if flag_name_map is not None:
            try:
                int(bit_flags[0])
            except ValueError:
                bit_flags = [flag_name_map[f] for f in bit_flags]
        allow_non_flags = len(bit_flags) == 1
    elif hasattr(bit_flags, '__iter__'):
        if not all((_is_int(flag) for flag in bit_flags)):
            if flag_name_map is not None and all((isinstance(flag, str) for flag in bit_flags)):
                bit_flags = [flag_name_map[f] for f in bit_flags]
            else:
                raise TypeError("Every bit flag in a list must be either an integer flag value or a 'str' flag name.")
    else:
        raise TypeError("Unsupported type for argument 'bit_flags'.")
    bitset = set(map(int, bit_flags))
    if len(bitset) != len(bit_flags):
        warnings.warn('Duplicate bit flags will be ignored')
    bitmask = 0
    for v in bitset:
        if not _is_bit_flag(v) and (not allow_non_flags):
            raise ValueError(f'Input list contains invalid (not powers of two) bit flag: {v}')
        bitmask += v
    if flip_bits:
        bitmask = ~bitmask
    return bitmask

class Covariance(NDUncertainty):

    def __init__(self, array=None, data_shape=None, assume_symmetric=False, unit=None):
        if array is None:
            raise ValueError('Covariance object cannot be instantiated with None.')
        self._cov = triu(Covariance._ingest_matrix(array, assume_symmetric=assume_symmetric))
        self._var = self._cov.diagonal()
        self._data_shape = data_shape
        if self._data_shape is not None and np.prod(self._data_shape) != self.shape[0]:
            raise ValueError('Product of ``data_shape`` must match the covariance axis length.')
        self._data_index_map = None
        super().__init__(array=self._cov, copy=False, unit=unit)

    @staticmethod
    def _ingest_matrix(arr, assume_symmetric=False):
        _arr = _get_csr(arr)
        if _arr.ndim != 2:
            raise ValueError('Covariance arrays must be 2-dimensional.')
        if _arr.shape[0] != _arr.shape[1]:
            raise ValueError('Covariance matrices must be square.')
        if assume_symmetric:
            return _arr
        flip_diff = _arr - _arr.T
        if not np.allclose(flip_diff.data, np.zeros_like(flip_diff.data)):
            warnings.warn('Asymmetry detected in covariance/correlation matrix.  Matrix will be modified to be symmetric using its upper triangle.', AstropyUserWarning)
            _arr = triu(_arr) + triu(_arr, 1).T
        return _arr

    @property
    def shape(self):
        return self._cov.shape

    @property
    def nnz(self):
        return self.stored_nnz * 2 - self._cov.shape[0]

    @property
    def stored_nnz(self):
        return self._cov.nnz

    @property
    def variance(self):
        return self._var

    @variance.setter
    def variance(self, value):
        raise NotImplementedError('Directly setting variance values is not allowed for Covariance objects.')

    @property
    def uncertainty_type(self):
        return 'cov'

    @property
    def quantity(self):
        return Quantity(self.to_dense(), self.unit, copy=False, dtype=self._cov.dtype)

    def _data_unit_to_uncertainty_unit(self, value):
        return value ** 2

    def __repr__(self):
        return f'<{self.__class__.__name__}; shape = {self.shape}>'

    def _propagate_add(self, other_uncert, result_data, correlation):
        return None

    def _propagate_subtract(self, other_uncert, result_data, correlation):
        return None

    def _propagate_multiply(self, other_uncert, result_data, correlation):
        return None

    def _propagate_divide(self, other_uncert, result_data, correlation):
        return None

    @classmethod
    def from_samples(cls, samples, cov_tol=None, rho_tol=None, **kwargs):
        if samples.ndim != 2:
            raise ValueError('Input samples for covariance matrix must be a 2D array!')
        if samples.shape[1] < 2:
            raise ValueError('Fewer than two samples provided!')
        return Covariance.from_array(np.cov(samples), cov_tol=cov_tol, rho_tol=rho_tol, **kwargs)

    @classmethod
    def from_array(cls, covar, cov_tol=None, rho_tol=None, **kwargs):
        assume_symmetric = kwargs.pop('assume_symmetric', False)
        var, rho = Covariance.to_correlation(covar, assume_symmetric=assume_symmetric)
        if rho_tol is not None:
            rho = _impose_sparse_value_threshold(rho, rho_tol)
        _covar = Covariance.revert_correlation(var, rho, assume_symmetric=True)
        if cov_tol is not None:
            _covar = _impose_sparse_value_threshold(_covar, cov_tol)
        return cls(array=_covar, assume_symmetric=True, **kwargs)

    @classmethod
    def from_table(cls, triu_covar):
        if 'COVSHAPE' not in triu_covar.meta:
            raise ValueError('Table meta dictionary *must* contain COVSHAPE')
        shape = _parse_shape(triu_covar.meta['COVSHAPE'])
        data_shape = _parse_shape(triu_covar.meta['COVDSHP']) if 'COVDSHP' in triu_covar.meta else None
        nnz = len(triu_covar)
        if data_shape is None:
            i = triu_covar['INDXI'].data
            j = triu_covar['INDXJ'].data
        else:
            ndim = triu_covar['INDXI'].shape[1]
            if len(data_shape) != ndim:
                raise ValueError('Mismatch between COVDSHP keyword and tabulated data.')
            i = np.ravel_multi_index(triu_covar['INDXI'].data.T, data_shape)
            j = np.ravel_multi_index(triu_covar['INDXJ'].data.T, data_shape)
        unit = triu_covar.meta.get('BUNIT', None)
        cij = triu_covar['COVARIJ'].data
        cov = coo_matrix((cij.astype(cij.dtype.type), (i, j)), shape=shape).tocsr()
        return cls(array=cov, data_shape=data_shape, unit=unit, assume_symmetric=True)

    @classmethod
    def from_matrix_multiplication(cls, T, covar, **kwargs):
        if T.ndim != 2:
            raise ValueError('Input transfer matrix must be two-dimensional.')
        nx = T.shape[1]
        if covar.shape != (nx, nx) and covar.shape != (nx,):
            raise ValueError(f'Shape of input variance matrix must be either ({nx}, {nx}) or ({nx},).')
        _T = T if isinstance(T, csr_matrix) else csr_matrix(T)
        _covar = coo_matrix((covar, (np.arange(nx), np.arange(nx))), shape=(nx, nx)).tocsr() if covar.ndim == 1 else covar if isinstance(covar, csr_matrix) else csr_matrix(covar)
        return cls(_T.dot(_covar.dot(_T.transpose())).tocsr(), **kwargs)

    @classmethod
    def from_variance(cls, variance, **kwargs):
        return cls(csr_matrix(np.diagflat(variance)), **kwargs)

    def to_sparse(self, correlation=False):
        cov = triu(self._cov) + triu(self._cov, 1).T
        if not correlation:
            return cov
        return Covariance.to_correlation(cov, assume_symmetric=True)[1]

    def apply_new_variance(self, var):
        _var = np.asarray(var)
        if _var.shape != self._var.shape:
            raise ValueError(f'Provided variance has incorrect shape.  Expected {self._var.shape}, found {_var.shape}.')
        i, j, cij = find(self._cov)
        _cov = coo_matrix((cij * np.sqrt(_var[i] / self._var[i] * _var[j] / self._var[j]), (i, j)), shape=self.shape).tocsr()
        return Covariance(array=_cov, data_shape=self._data_shape, assume_symmetric=True)

    def copy(self):
        return Covariance(array=self._cov.copy(), data_shape=self._data_shape, assume_symmetric=True, unit=self.unit)

    def to_dense(self, correlation=False):
        return self.to_sparse(correlation=correlation).toarray()

    def find(self, correlation=False):
        return find(self.to_sparse(correlation=correlation))

    def covariance_to_data_indices(self, i, j):
        if self._data_shape is None:
            if np.any((i < 0) | (i > self.shape[0] - 1) | (j < 0) | (j > self.shape[1] - 1)):
                raise ValueError(f'Some indices not valid for covariance matrix with shape {self.shape}.')
            return (i, j)
        return (np.unravel_index(np.atleast_1d(i).ravel(), self._data_shape), np.unravel_index(np.atleast_1d(j).ravel(), self._data_shape))

    def data_to_covariance_indices(self, i, j):
        if self._data_shape is None:
            if np.any((i < 0) | (i > self.shape[0] - 1) | (j < 0) | (j > self.shape[1] - 1)):
                raise ValueError(f'Some indices not valid for covariance matrix with shape {self.shape}.')
            return (i, j)
        if len(i) != len(self.data_shape):
            raise ValueError(f'Length of input coordinate list (i) is incorrect; expected {len(self.data_shape)}, found {len(i)}')
        if len(j) != len(self.data_shape):
            raise ValueError(f'Length of input coordinate list (j) is incorrect; expected {len(self.data_shape)}, found {len(i)}')
        return (np.ravel_multi_index(i, self.data_shape), np.ravel_multi_index(j, self.data_shape))

    def coordinate_data(self, reshape=False):
        if reshape and self._data_shape is None:
            raise ValueError('If reshaping, the shape of the data before flattening to the covariance array (``data_shape``) must be defined.')
        i, j, cij = find(self._cov)
        if reshape:
            return (np.unravel_index(i, self._data_shape), np.unravel_index(j, self._data_shape), cij)
        return (i, j, cij)

    def to_table(self):
        meta = {}
        meta['COVSHAPE'] = str(self.shape)
        if self.unit is not None:
            meta['BUNIT'] = self.unit.to_string()
        reshape = self._data_shape is not None
        i, j, cij = self.coordinate_data(reshape=reshape)
        triu_nnz = cij.size
        if reshape:
            meta['COVDSHP'] = str(self._data_shape)
            i = np.column_stack(i)
            j = np.column_stack(j)
            coo_shape = (i.shape[1],)
        else:
            coo_shape = None
        return table.Table([table.Column(data=i, name='INDXI', dtype=int, length=triu_nnz, shape=coo_shape), table.Column(data=j, name='INDXJ', dtype=int, length=triu_nnz, shape=coo_shape), table.Column(data=cij, name='COVARIJ', dtype=float, length=triu_nnz)], meta=meta)

    @property
    def data_shape(self):
        return (self.shape[0],) if self._data_shape is None else self._data_shape

    @property
    def data_index_map(self):
        if self._data_index_map is None:
            self._data_index_map = np.arange(self.shape[0])
            if self._data_shape is not None:
                self._data_index_map = self._data_index_map.reshape(self._data_shape)
        return self._data_index_map

    def match_to_data_slice(self, data_slice):
        remap = self.data_index_map[data_slice]
        index = remap.ravel()
        return Covariance(self.to_sparse()[np.ix_(index, index)], data_shape=None if len(remap.shape) == 1 else remap.shape)

    @staticmethod
    def to_correlation(cov, assume_symmetric=False):
        _cov = Covariance._ingest_matrix(cov, assume_symmetric=assume_symmetric)
        var = _cov.diagonal()
        i, j, cij = find(_cov)
        rho = coo_matrix((cij / np.sqrt(var[i] * var[j]), (i, j)), shape=_cov.shape).tocsr()
        return (var, rho)

    @staticmethod
    def revert_correlation(var, rho, assume_symmetric=False):
        i, j, rhoij = find(Covariance._ingest_matrix(rho, assume_symmetric=assume_symmetric))
        return coo_matrix((rhoij * np.sqrt(var[i] * var[j]), (i, j)), shape=rho.shape).tocsr()

# --- helper: astropy.nddata.covariance._get_csr ---
def _get_csr(arr):
    if isspmatrix_csr(arr):
        return arr
    try:
        return csr_matrix(arr)
    except ValueError:
        raise TypeError('Input matrix is not a scipy.sparse.csr_matrix and could not be converted to one.')

# --- helper: astropy.nddata.covariance._impose_sparse_value_threshold ---
def _impose_sparse_value_threshold(arr, threshold):
    i, j, aij = find(arr)
    index = np.logical_not(np.absolute(aij) < threshold)
    if all(index):
        return arr
    return coo_matrix((aij[index], (i[index], j[index])), shape=arr.shape).tocsr()

# --- helper: astropy.nddata.covariance._parse_shape ---
def _parse_shape(shape):
    return tuple([int(n) for n in shape.strip('()').split(',') if len(n) > 0])

def add_array(array_large, array_small, position, *, limit_rounding_method=np.ceil):
    if all((large_shape >= small_shape for large_shape, small_shape in zip(array_large.shape, array_small.shape))):
        large_slices, small_slices = overlap_slices(array_large.shape, array_small.shape, position, limit_rounding_method=limit_rounding_method)
        array_large[large_slices] += array_small[small_slices]
        return array_large
    else:
        raise ValueError("Can't add array. Small array too large.")

# --- helper: astropy.nddata.utils.overlap_slices ---
def overlap_slices(large_array_shape, small_array_shape, position, mode='partial', *, limit_rounding_method=np.ceil):
    if mode not in ['partial', 'trim', 'strict']:
        raise ValueError('Mode can be only "partial", "trim", or "strict".')
    if np.isscalar(small_array_shape):
        small_array_shape = (small_array_shape,)
    if np.isscalar(large_array_shape):
        large_array_shape = (large_array_shape,)
    if np.isscalar(position):
        position = (position,)
    if any(~np.isfinite(position)):
        raise ValueError('Input position contains invalid values (NaNs or infs).')
    if len(small_array_shape) != len(large_array_shape):
        raise ValueError('"large_array_shape" and "small_array_shape" must have the same number of dimensions.')
    if len(small_array_shape) != len(position):
        raise ValueError('"position" must have the same number of dimensions as "small_array_shape".')
    if not callable(limit_rounding_method):
        raise ValueError('Limit rounding method must be a callable function.')
    try:
        indices_min = [int(limit_rounding_method(pos - small_shape / 2.0)) for pos, small_shape in zip(position, small_array_shape)]
    except (TypeError, ValueError) as exc:
        raise ValueError('Limit rounding method must accept a single number as input and return a single number.') from exc
    indices_max = [int(idx_min + small_shape) for idx_min, small_shape in zip(indices_min, small_array_shape)]
    for e_max in indices_max:
        if e_max < 0 or (e_max == 0 and small_array_shape != (0, 0)):
            raise NoOverlapError('Arrays do not overlap.')
    for e_min, large_shape in zip(indices_min, large_array_shape):
        if e_min >= large_shape:
            raise NoOverlapError('Arrays do not overlap.')
    if mode == 'strict':
        for e_min in indices_min:
            if e_min < 0:
                raise PartialOverlapError('Arrays overlap only partially.')
        for e_max, large_shape in zip(indices_max, large_array_shape):
            if e_max > large_shape:
                raise PartialOverlapError('Arrays overlap only partially.')
    slices_large = tuple((slice(max(0, indices_min), min(large_shape, indices_max)) for indices_min, indices_max, large_shape in zip(indices_min, indices_max, large_array_shape)))
    if mode == 'trim':
        slices_small = tuple((slice(0, slc.stop - slc.start) for slc in slices_large))
    else:
        slices_small = tuple((slice(max(0, -indices_min), min(large_shape - indices_min, indices_max - indices_min)) for indices_min, indices_max, large_shape in zip(indices_min, indices_max, large_array_shape)))
    return (slices_large, slices_small)

def extract_array(array_large, shape, position, mode='partial', fill_value=np.nan, return_position=False, *, limit_rounding_method=np.ceil):
    if np.isscalar(shape):
        shape = (shape,)
    if np.isscalar(position):
        position = (position,)
    if mode not in ['partial', 'trim', 'strict']:
        raise ValueError("Valid modes are 'partial', 'trim', and 'strict'.")
    large_slices, small_slices = overlap_slices(array_large.shape, shape, position, mode=mode, limit_rounding_method=limit_rounding_method)
    extracted_array = array_large[large_slices]
    if return_position:
        new_position = [i - s.start for i, s in zip(position, large_slices)]
    if extracted_array.shape != shape and mode == 'partial':
        extracted_array_large = np.zeros(shape, dtype=extracted_array.dtype)
        try:
            extracted_array_large[:] = fill_value
        except ValueError as exc:
            exc.args += ('fill_value is inconsistent with the data type of the input array (e.g., fill_value cannot be set to np.nan if the input array has integer type). Please change either the input array dtype or the fill_value.',)
            raise exc
        extracted_array_large[small_slices] = extracted_array
        extracted_array = extracted_array_large
        if return_position:
            new_position = [i + s.start for i, s in zip(new_position, small_slices)]
    if return_position:
        return (extracted_array, tuple(new_position))
    else:
        return extracted_array

