class Cutout2D:

    def __init__(self, data, position, size, wcs=None, mode='trim', fill_value=np.nan, copy=False, *, limit_rounding_method=np.ceil):
        if wcs is None:
            wcs = getattr(data, 'wcs', None)
        if isinstance(position, SkyCoord):
            if wcs is None:
                raise ValueError('wcs must be input if position is a SkyCoord')
            position = skycoord_to_pixel(position, wcs, mode='all')
        if np.isscalar(size):
            size = np.repeat(size, 2)
        if isinstance(size, u.Quantity):
            size = np.atleast_1d(size)
            if len(size) == 1:
                size = np.repeat(size, 2)
        if len(size) > 2:
            raise ValueError('size must have at most two elements')
        shape = np.zeros(2).astype(int)
        pixel_scales = None
        for axis, side in enumerate(size):
            if not isinstance(side, u.Quantity):
                shape[axis] = int(np.round(side))
            elif side.unit == u.pixel:
                shape[axis] = int(np.round(side.value))
            elif side.unit.physical_type == 'angle':
                if wcs is None:
                    raise ValueError('wcs must be input if any element of size has angular units')
                if pixel_scales is None:
                    pixel_scales = u.Quantity(proj_plane_pixel_scales(wcs), wcs.wcs.cunit[axis])
                shape[axis] = int(np.round((side / pixel_scales[axis]).decompose()))
            else:
                raise ValueError('shape can contain Quantities with only pixel or angular units')
        if not isinstance(data, (Section, CompImageSection)):
            data = np.asanyarray(data)
        pos_yx = position[::-1]
        cutout_data, input_position_cutout = extract_array(data, tuple(shape), pos_yx, mode=mode, fill_value=fill_value, return_position=True, limit_rounding_method=limit_rounding_method)
        if copy:
            cutout_data = np.copy(cutout_data)
        self.data = cutout_data
        self.input_position_cutout = input_position_cutout[::-1]
        slices_original, slices_cutout = overlap_slices(data.shape, shape, pos_yx, mode=mode, limit_rounding_method=limit_rounding_method)
        self.slices_original = slices_original
        self.slices_cutout = slices_cutout
        self.shape = self.data.shape
        self.input_position_original = position
        self.shape_input = shape
        (self.ymin_original, self.ymax_original), (self.xmin_original, self.xmax_original) = self.bbox_original
        (self.ymin_cutout, self.ymax_cutout), (self.xmin_cutout, self.xmax_cutout) = self.bbox_cutout
        self._origin_original_true = (self.origin_original[0] - self.slices_cutout[1].start, self.origin_original[1] - self.slices_cutout[0].start)
        if wcs is not None:
            self.wcs = deepcopy(wcs)
            self.wcs.wcs.crpix -= self._origin_original_true
            self.wcs.array_shape = self.data.shape
            if wcs.sip is not None:
                self.wcs.sip = Sip(wcs.sip.a, wcs.sip.b, wcs.sip.ap, wcs.sip.bp, wcs.sip.crpix - self._origin_original_true)
        else:
            self.wcs = None

    def to_original_position(self, cutout_position):
        return tuple((cutout_position[i] + self.origin_original[i] for i in [0, 1]))

    def to_cutout_position(self, original_position):
        return tuple((original_position[i] - self.origin_original[i] for i in [0, 1]))

    def plot_on_original(self, ax=None, fill=False, **kwargs):
        import matplotlib.patches as mpatches
        import matplotlib.pyplot as plt
        kwargs['fill'] = fill
        if ax is None:
            ax = plt.gca()
        height, width = self.shape
        hw, hh = (width / 2.0, height / 2.0)
        pos_xy = self.position_original - np.array([hw, hh])
        patch = mpatches.Rectangle(pos_xy, width, height, angle=0.0, **kwargs)
