def extract_array(array_large, shape, position, mode='partial', fill_value=np.nan, return_position=False, *, limit_rounding_method=np.ceil):
    if np.isscalar(shape):
        shape = (shape,)
    if np.isscalar(position):
        position = (position,)
    if mode not in ['partial', 'trim', 'strict']:
        raise ValueError("Valid modes are 'partial', 'trim', and 'strict'.")
    large_slices, small_slices = overlap_slices(array_large.shape, shape, position, mode=mode, limit_rounding_method=limit_rounding_method)
    extracted_array = array_large[large_slices]
    if return_position:
        new_position = [i - s.start for i, s in zip(position, large_slices)]
    if extracted_array.shape != shape and mode == 'partial':
        extracted_array_large = np.zeros(shape, dtype=extracted_array.dtype)
        try:
            extracted_array_large[:] = fill_value
        except ValueError as exc:
            exc.args += ('fill_value is inconsistent with the data type of the input array (e.g., fill_value cannot be set to np.nan if the input array has integer type). Please change either the input array dtype or the fill_value.',)
            raise exc
        extracted_array_large[small_slices] = extracted_array
        extracted_array = extracted_array_large
        if return_position:
            new_position = [i + s.start for i, s in zip(new_position, small_slices)]
    if return_position:
        return (extracted_array, tuple(new_position))
    else:
        return extracted_array

