def overlap_slices(large_array_shape, small_array_shape, position, mode='partial', *, limit_rounding_method=np.ceil):
    if mode not in ['partial', 'trim', 'strict']:
        raise ValueError('Mode can be only "partial", "trim", or "strict".')
    if np.isscalar(small_array_shape):
        small_array_shape = (small_array_shape,)
    if np.isscalar(large_array_shape):
        large_array_shape = (large_array_shape,)
    if np.isscalar(position):
        position = (position,)
    if any(~np.isfinite(position)):
        raise ValueError('Input position contains invalid values (NaNs or infs).')
    if len(small_array_shape) != len(large_array_shape):
        raise ValueError('"large_array_shape" and "small_array_shape" must have the same number of dimensions.')
    if len(small_array_shape) != len(position):
        raise ValueError('"position" must have the same number of dimensions as "small_array_shape".')
    if not callable(limit_rounding_method):
        raise ValueError('Limit rounding method must be a callable function.')
    try:
        indices_min = [int(limit_rounding_method(pos - small_shape / 2.0)) for pos, small_shape in zip(position, small_array_shape)]
    except (TypeError, ValueError) as exc:
        raise ValueError('Limit rounding method must accept a single number as input and return a single number.') from exc
    indices_max = [int(idx_min + small_shape) for idx_min, small_shape in zip(indices_min, small_array_shape)]
    for e_max in indices_max:
        if e_max < 0 or (e_max == 0 and small_array_shape != (0, 0)):
            raise NoOverlapError('Arrays do not overlap.')
    for e_min, large_shape in zip(indices_min, large_array_shape):
        if e_min >= large_shape:
            raise NoOverlapError('Arrays do not overlap.')
    if mode == 'strict':
        for e_min in indices_min:
            if e_min < 0:
                raise PartialOverlapError('Arrays overlap only partially.')
        for e_max, large_shape in zip(indices_max, large_array_shape):
            if e_max > large_shape:
                raise PartialOverlapError('Arrays overlap only partially.')
    slices_large = tuple((slice(max(0, indices_min), min(large_shape, indices_max)) for indices_min, indices_max, large_shape in zip(indices_min, indices_max, large_array_shape)))
    if mode == 'trim':
        slices_small = tuple((slice(0, slc.stop - slc.start) for slc in slices_large))
    else:
        slices_small = tuple((slice(max(0, -indices_min), min(large_shape - indices_min, indices_max - indices_min)) for indices_min, indices_max, large_shape in zip(indices_min, indices_max, large_array_shape)))
    return (slices_large, slices_small)

