def poisson_conf_interval(n: int | NDArray, interval: Literal['root-n', 'root-n-0', 'pearson', 'sherpagehrels', 'frequentist-confidence', 'kraft-burrows-nousek']='root-n', sigma: float=1.0, background: float=0.0, confidence_level: float | None=None) -> NDArray:
    if not np.isscalar(n):
        n = np.asanyarray(n)
    if interval == 'root-n':
        _check_poisson_conf_inputs(sigma, background, confidence_level, interval)
        conf_interval = np.array([n - np.sqrt(n), n + np.sqrt(n)])
    elif interval == 'root-n-0':
        _check_poisson_conf_inputs(sigma, background, confidence_level, interval)
        conf_interval = np.array([n - np.sqrt(n), n + np.sqrt(n)])
        if np.isscalar(n):
            if n == 0:
                conf_interval[1] = 1
        else:
            conf_interval[1, n == 0] = 1
    elif interval == 'pearson':
        _check_poisson_conf_inputs(sigma, background, confidence_level, interval)
        conf_interval = np.array([n + 0.5 - np.sqrt(n + 0.25), n + 0.5 + np.sqrt(n + 0.25)])
    elif interval == 'sherpagehrels':
        _check_poisson_conf_inputs(sigma, background, confidence_level, interval)
        conf_interval = np.array([n - 1 - np.sqrt(n + 0.75), n + 1 + np.sqrt(n + 0.75)])
    elif interval == 'frequentist-confidence':
        _check_poisson_conf_inputs(1.0, background, confidence_level, interval)
        import scipy.stats
        alpha = scipy.stats.norm.sf(sigma)
        conf_interval = np.array([0.5 * scipy.stats.chi2(2 * n).ppf(alpha), 0.5 * scipy.stats.chi2(2 * n + 2).isf(alpha)])
        if np.isscalar(n):
            if n == 0:
                conf_interval[0] = 0
        else:
            conf_interval[0, n == 0] = 0
    elif interval == 'kraft-burrows-nousek':
        if np.isscalar(n):
            if not isinstance(n, int):
                raise TypeError('Number of counts must be integer.')
        elif not issubclass(n.dtype.type, np.integer):
            raise TypeError('Number of counts must be integer.')
        if confidence_level is None:
            raise ValueError(f'Set confidence_level for method {interval}. (sigma is ignored.)')
        confidence_level = np.asanyarray(confidence_level)
        if np.any(confidence_level <= 0) or np.any(confidence_level >= 1):
            raise ValueError('confidence_level must be a number between 0 and 1.')
        background = np.asanyarray(background)
        if np.any(background < 0):
            raise ValueError('Background must be >= 0.')
        conf_interval = np.vectorize(_kraft_burrows_nousek, cache=True)(n, background, confidence_level)
        conf_interval = np.vstack(conf_interval)
    else:
        raise ValueError(f'Invalid method for Poisson confidence intervals: {interval}')
    return conf_interval

# --- helper: astropy.stats.funcs._check_poisson_conf_inputs ---
def _check_poisson_conf_inputs(sigma: float, background: float, confidence_level: float, name: Literal['root-n', 'root-n-0', 'pearson', 'sherpagehrels', 'frequentist-confidence', 'kraft-burrows-nousek']) -> None:
    if sigma != 1:
        raise ValueError(f'Only sigma=1 supported for interval {name}')
    if background != 0:
        raise ValueError(f'background not supported for interval {name}')
    if confidence_level is not None:
        raise ValueError(f'confidence_level not supported for interval {name}')

# --- helper: astropy.stats.funcs._kraft_burrows_nousek ---
def _kraft_burrows_nousek(N: int, B: float, CL: float) -> tuple[float, float]:
    if HAS_SCIPY:
        try:
            return _scipy_kraft_burrows_nousek(N, B, CL)
        except OverflowError:
            if not HAS_MPMATH:
                raise ValueError('Need mpmath package for input numbers this large.')
    if HAS_MPMATH:
        return _mpmath_kraft_burrows_nousek(N, B, CL)
    raise ImportError('Either scipy or mpmath are required.')

class TableLoc:

    def __init__(self, table: Table, index_id: tuple[str, ...] | None=None):
        self.table = table
        self.indices = table.indices
        self.index_id = index_id

    def __repr__(self):
        index_id = self.index_id
        if index_id is None:
            index_id = self.table.primary_key
        id_repr = index_id[0] if len(index_id) == 1 else index_id
        return f'<{self.__class__.__name__} index_id={repr(id_repr)} id(table)={id(self.table)}>'

    def with_index(self, *index_id):
        if len(index_id) == 1 and isinstance(index_id[0], (tuple, list)):
            index_id = tuple(index_id[0])
        return self.__class__(self.table, index_id)

    def _get_index_id_and_item(self, item):
        index_id = self.index_id
        if self.index_id is None:
            if isinstance(item, tuple):
                index_id, item = interpret_item_as_index_id_and_item(item)
            else:
                index_id = self.table.primary_key
        return (index_id, item)

    def _get_row_idxs_as_list(self, index_id: tuple, item, item_is_sequence: bool) -> list[int]:
        if len(self.indices) == 0:
            raise ValueError('Can only use TableLoc for a table with indices')
        index = self.indices[index_id]
        if isinstance(item, slice):
            start = None if item.start is None else (item.start,)
            stop = None if item.stop is None else (item.stop,)
            rows = index.range(start, stop)
        else:
            if not item_is_sequence:
                item = [item]
            rows = []
            for value in item:
                ii = index.find(value if isinstance(value, tuple) else (value,))
                if len(ii) == 0:
                    raise KeyError(f'No matches found for key {value}')
                else:
                    rows.extend(ii)
        return rows

    def _get_row_idxs_as_list_or_int(self, item) -> list[int] | int:
        index_id, item = self._get_index_id_and_item(item)
        item_is_sequence = isinstance(item, np.ndarray) and item.ndim > 0 or isinstance(item, list)
        if item_is_sequence and len(item) == 0:
            return []
        row_idxs = self._get_row_idxs_as_list(index_id, item, item_is_sequence)
        if not (item_is_sequence or isinstance(item, slice)) and len(row_idxs) == 1:
            row_idxs = row_idxs[0]
        return row_idxs

    def __getitem__(self, item) -> Table | Table.Row:
        rows = self._get_row_idxs_as_list_or_int(item)
        return self.table[rows]

    def __setitem__(self, key, value):
        rows = self._get_row_idxs_as_list_or_int(key)
        if hasattr(rows, '__len__'):
            if len(rows) == len(value):
                for row, val in zip(rows, value):
                    self.table[row] = val
            else:
                raise ValueError(f'Right side should contain {len(rows)} values')
        else:
            self.table[rows] = value

