def join(left, right, keys=None, join_type='inner', *, keys_left=None, keys_right=None, keep_order=False, uniq_col_name='{col_name}_{table_name}', table_names=['1', '2'], metadata_conflicts='warn', join_funcs=None):
    if not isinstance(left, Table):
        left = Table(left)
    if not isinstance(right, Table):
        right = Table(right)
    sort_table_index_key = '__astropy_table_keep_order_sort_index__'
    sort_table = None
    if keep_order:
        if join_type not in ['left', 'right', 'inner']:
            warnings.warn('keep_order=True is only supported for left, right, and inner joins', UserWarning, stacklevel=2)
        else:
            sort_table = right if join_type == 'right' else left
            sort_table[sort_table_index_key] = np.arange(len(sort_table))
    try:
        out = _join(left, right, keys, join_type, uniq_col_name, table_names, metadata_conflicts, join_funcs, keys_left=keys_left, keys_right=keys_right)
        if sort_table is not None:
            out.sort(sort_table_index_key)
            del out[sort_table_index_key]
    finally:
        if sort_table is not None:
            del sort_table[sort_table_index_key]
    _merge_table_meta(out, [left, right], metadata_conflicts=metadata_conflicts)
    return out

# --- helper: astropy.table.operations._join ---
def _join(left, right, keys=None, join_type='inner', uniq_col_name='{col_name}_{table_name}', table_names=['1', '2'], metadata_conflicts='warn', join_funcs=None, keys_left=None, keys_right=None):
    cartesian_index_name = '__table_cartesian_join_temp_index__'
    if join_type not in ('inner', 'outer', 'left', 'right', 'cartesian'):
        raise ValueError(f"The 'join_type' argument should be in 'inner', 'outer', 'left', 'right', or 'cartesian' (got '{join_type}' instead)")
    if join_type == 'cartesian':
        if keys:
            raise ValueError('cannot supply keys for a cartesian join')
        if join_funcs:
            raise ValueError('cannot supply join_funcs for a cartesian join')
        left = left.copy(copy_data=False)
        right = right.copy(copy_data=False)
        left[cartesian_index_name] = np.uint8(0)
        right[cartesian_index_name] = np.uint8(0)
        keys = (cartesian_index_name,)
    if keys_left is not None or keys_right is not None:
        left_orig = left
        right_orig = right
        left, right, keys = _join_keys_left_right(left, right, keys, keys_left, keys_right, join_funcs)
    if keys is None:
        keys = tuple((name for name in left.colnames if name in right.colnames))
        if len(keys) == 0:
            raise TableMergeError('No keys in common between left and right tables')
    elif isinstance(keys, str):
        keys = (keys,)
    for arr, arr_label in ((left, 'Left'), (right, 'Right')):
        for name in keys:
            if name not in arr.colnames:
                raise TableMergeError(f'{arr_label} table does not have key column {name!r}')
            if hasattr(arr[name], 'mask') and np.any(arr[name].mask):
                raise TableMergeError(f'{arr_label} key column {name!r} has missing values')
    if join_funcs is not None:
        if not all((key in keys for key in join_funcs)):
            raise ValueError(f'join_funcs keys {join_funcs.keys()} must be a subset of join keys {keys}')
        left, right, keys = _apply_join_funcs(left, right, keys, join_funcs)
    len_left, len_right = (len(left), len(right))
    if len_left == 0 or len_right == 0:
        raise ValueError('input tables for join must both have at least one row')
    try:
        idxs, idx_sort = _get_join_sort_idxs(keys, left, right)
    except NotImplementedError:
        raise TypeError('one or more key columns are not sortable')
    if keys_left is not None or keys_right is not None:
        keys = []
        left = left_orig
        right = right_orig
    col_name_map = get_col_name_map([left, right], keys, uniq_col_name, table_names)
    out_descrs = get_descrs([left, right], col_name_map)
    int_join_type = {'inner': 0, 'outer': 1, 'left': 2, 'right': 3, 'cartesian': 1}[join_type]
    masked, n_out, left_out, left_mask, right_out, right_mask = _np_utils.join_inner(idxs, idx_sort, len_left, int_join_type)
    out = _get_out_class([left, right])()
    for out_name, _dtype, _shape in out_descrs:
        if out_name == cartesian_index_name:
            continue
        left_name, right_name = col_name_map[out_name]
        if left_name and right_name:
            cols = [left[left_name], right[right_name]]
            col_cls = _get_out_class(cols)
            if not hasattr(col_cls.info, 'new_like'):
                raise NotImplementedError(f'join unavailable for mixin column type(s): {col_cls.__name__}')
            out[out_name] = col_cls.info.new_like(cols, n_out, metadata_conflicts, out_name)
            out[out_name][:] = np.where(right_mask, left[left_name].take(left_out), right[right_name].take(right_out))
            continue
        elif left_name:
            name, array, array_out, array_mask = (left_name, left, left_out, left_mask)
        elif right_name:
            name, array, array_out, array_mask = (right_name, right, right_out, right_mask)
        else:
            raise TableMergeError('Unexpected column names (maybe one is ""?)')
        col = array[name][array_out]
        if masked and np.any(array_mask):
            if isinstance(col, Column) and (not isinstance(col, MaskedColumn)):
                col = out.MaskedColumn(col, copy=False)
            if isinstance(col, Quantity) and (not isinstance(col, Masked)):
                col = Masked(col, copy=False)
            new_shape = (col.shape[0],) + (1,) * (len(col.shape) - 1)
            array_mask = array_mask.reshape(new_shape)
            array_mask = np.broadcast_to(array_mask, col.shape)
            try:
                col[array_mask] = col.info.mask_val
            except Exception as err:
                raise NotImplementedError(f"join requires masking column '{out_name}' but column type {col.__class__.__name__} does not support masking") from err
        out[out_name] = col
    return out

# --- helper: astropy.table.operations._merge_table_meta ---
def _merge_table_meta(out, tables, metadata_conflicts='warn'):
    out_meta = deepcopy(tables[0].meta)
    for table in tables[1:]:
        out_meta = metadata.merge(out_meta, table.meta, metadata_conflicts=metadata_conflicts)
    out.meta.update(out_meta)

def nanmean_reduceat(data, indices):
    unmasked, data_mask = get_data_and_mask(data)
    mask = np.isnan(unmasked)
    if data_mask is not None:
        mask |= data_mask
    if mask.any():
        unmasked = unmasked.copy()
        unmasked[mask] = 0
        counts = np.add.reduceat(~mask, indices)
        out_mask = counts <= 0
    else:
        counts = np.diff(indices, append=len(data))
        out_mask = None
    result = np.add.reduceat(unmasked, indices) / np.maximum(counts, 1)
    if out_mask is not None:
        result[out_mask] = np.nan
    if data_mask is not None:
        cls = Masked if isinstance(data, Masked) else data.__class__
        result = cls(result, mask=out_mask, copy=False)
    return result

def magnetic_flux_field(mu_r=1):
    mu0 = _si.mu0.value
    return Equivalency([(si.T, si.A / si.m, lambda x: x / (mu_r * mu0), lambda x: x * mu_r * mu0)], 'magnetic_flux_field')

# --- helper: astropy.units.equivalencies.Equivalency ---
class Equivalency(list):

    def __init__(self, equiv_list, name='', kwargs=None):
        super().__init__(equiv_list)
        self.name = [name]
        self.kwargs = [kwargs] if kwargs is not None else [{}]

    def __add__(self, other):
        if isinstance(other, Equivalency):
            new = self.__class__(super().__add__(other))
            new.name = self.name + other.name
            new.kwargs = self.kwargs + other.kwargs
            return new
        else:
            return super().__add__(other)

    def __eq__(self, other):
        return isinstance(other, self.__class__) and self.name == other.name and (self.kwargs == other.kwargs)

class DeprecatedUnitAction(StrEnum):
    SILENT = auto()
    WARN = auto()
    RAISE = auto()
    CONVERT = auto()

    @classmethod
    def _missing_(cls, value) -> Self | None:
        raise ValueError(f"invalid deprecation handling option: {value!r}. Valid options are {', '.join((repr(opt.value) for opt in cls))}.")

def def_unit(s: str | list[str], represents: UnitLike | None=None, doc: str | None=None, format: Mapping[str, str] | None=None, prefixes: bool | Iterable[UnitPrefix]=False, exclude_prefixes: Collection[str]=(), namespace: MutableMapping[str, object] | None=None) -> NamedUnit:
    if represents is not None:
        result = Unit(s, represents, namespace=namespace, doc=doc, format=format)
    else:
        result = IrreducibleUnit(s, namespace=namespace, doc=doc, format=format)
    if prefixes:
        _add_prefixes(result, excludes=exclude_prefixes, namespace=namespace, prefixes=prefixes)
    return result

# --- helper: astropy.units.core.IrreducibleUnit ---
class IrreducibleUnit(NamedUnit):

    def __reduce__(self):
        registry = get_current_unit_registry().registry
        return (_recreate_irreducible_unit, (self.__class__, list(self.names), self.name in registry), self.__getstate__())

    @property
    def represents(self) -> Self:
        return self

    def decompose(self, bases: Collection[UnitBase]=()) -> UnitBase:
        if len(bases) and self not in bases:
            for base in bases:
                try:
                    scale = self._to(base)
                except UnitsError:
                    pass
                else:
                    if is_effectively_unity(scale):
                        return base
                    else:
                        return CompositeUnit(scale, [base], [1], _error_check=False)
            raise UnitConversionError(f'Unit {self} can not be decomposed into the requested bases')
        return self

# --- helper: astropy.units.core.NamedUnit ---
class NamedUnit(UnitBase):

    def __init__(self, st: str | list[str] | tuple[list[str], list[str]], doc: str | None=None, format: Mapping[str, str] | None=None, namespace: MutableMapping[str, object] | None=None) -> None:
        if isinstance(st, (bytes, str)):
            self._names = [st]
            self._short_names = [st]
            self._long_names = []
        elif isinstance(st, tuple):
            if not len(st) == 2:
                raise ValueError('st must be string, list or 2-tuple')
            self._names = st[0] + [n for n in st[1] if n not in st[0]]
            if not len(self._names):
                raise ValueError('must provide at least one name')
            self._short_names = st[0][:]
            self._long_names = st[1][:]
        else:
            if len(st) == 0:
                raise ValueError('st list must have at least one entry')
            self._names = st[:]
            self._short_names = [st[0]]
            self._long_names = st[1:]
        self._format = {} if format is None else format
        self.__doc__ = self._generate_doc() if doc is None else textwrap.fill(textwrap.dedent(doc))
        self._inject(namespace)

    def _generate_doc(self) -> str:
        names = self.names
        if len(self.names) > 1:
            return f'{names[1]} ({names[0]})'
        else:
            return names[0]

    @deprecated(since='7.0', alternative='to_string()')
    def get_format_name(self, format):
        return self._get_format_name(format)

    def _get_format_name(self, format: str) -> str:
        return self._format.get(format, self.name)

    @property
    def names(self) -> list[str]:
        return self._names

    @property
    def name(self) -> str:
        return self._names[0]

    @property
    def aliases(self) -> list[str]:
        return self._names[1:]

    @property
    def short_names(self) -> list[str]:
        return self._short_names

    @property
    def long_names(self) -> list[str]:
        return self._long_names

    def _inject(self, namespace: MutableMapping[str, object] | None=None) -> None:
        if namespace is None:
            return
        for name in self._names:
            nfkc_name = unicodedata.normalize('NFKC', name)
            if nfkc_name in namespace and self != (obj := namespace[nfkc_name]):
                msg = f'the namespace already uses the name {name!r} for {obj!r}' if name == nfkc_name else f'the namespace already uses the NFKC normalized name {nfkc_name!r} for {obj!r}\n\nSee https://docs.python.org/3/reference/lexical_analysis.html#identifiers for more information.'
                raise ValueError(msg)
        for name in self._names:
            namespace[name] = self

# --- helper: astropy.units.core.Unit ---
class Unit(NamedUnit, metaclass=_UnitMetaClass):

    def __init__(self, st, represents=None, doc=None, format=None, namespace=None):
        represents = Unit(represents)
        self._represents = represents
        NamedUnit.__init__(self, st, namespace=namespace, doc=doc, format=format)

    @property
    def represents(self) -> UnitBase:
        return self._represents

    def decompose(self, bases: Collection[UnitBase]=()) -> UnitBase:
        return self._represents.decompose(bases=bases)

    def is_unity(self) -> bool:
        return self._represents.is_unity()

    @cached_property
    def _hash(self) -> int:
        return hash((self.name, self._represents))

    @classmethod
    def _from_physical_type_id(cls, physical_type_id: PhysicalTypeID) -> UnitBase:
        if len(physical_type_id) == 1 and physical_type_id[0][1] == 1:
            return cls(physical_type_id[0][0])
        bases = [cls(base) for base, _ in physical_type_id]
        powers = [power for _, power in physical_type_id]
        return CompositeUnit(1, bases, powers, _error_check=False)

# --- helper: astropy.units.core.UnitPrefix ---
class UnitPrefix(NamedTuple):
    symbols: tuple[str, ...]
    'The symbols of the prefix, to be combined with symbols of units.'
    names: tuple[str, ...]
    'The names of the prefix, to be combined with names of units.'
    factor: UnitScale
    'The multiplicative factor represented by the prefix.'

# --- helper: astropy.units.core._add_prefixes ---
def _add_prefixes(u: NamedUnit, excludes: Collection[str]=(), namespace: MutableMapping[str, object] | None=None, prefixes: bool | Iterable[UnitPrefix]=False) -> None:
    if prefixes is True:
        prefixes = si_prefixes
    elif prefixes is False:
        prefixes = []
    for short, full, factor in prefixes:
        names = []
        format = {}
        for prefix in short:
            if prefix in excludes:
                continue
            for alias in u.short_names:
                names.append(prefix + alias)
                if prefix == 'u':
                    format['latex'] = '\\mu ' + u._get_format_name('latex')
                    format['unicode'] = 'µ' + u._get_format_name('unicode')
                for key, val in u._format.items():
                    format.setdefault(key, prefix + val)
        for prefix in full:
            if prefix in excludes:
                continue
            for alias in u.long_names:
                names.append(prefix + alias)
        if names:
            PrefixUnit(names, CompositeUnit(factor, [u], [1], _error_check=False), namespace=namespace, format=format)

class FITS(Base, _GenericParserMixin):

    @classproperty(lazy=True)
    def _units(cls) -> dict[str, UnitBase]:
        from astropy import units as u
        names = {'Celsius': u.deg_C, 'deg C': u.deg_C, 'dbyte': u.Unit('dbyte', 0.1 * u.byte), 'as': u.attosecond}
        bases = ['m', 'g', 's', 'rad', 'sr', 'K', 'A', 'mol', 'cd', 'Hz', 'J', 'W', 'V', 'N', 'Pa', 'C', 'Ohm', 'S', 'F', 'Wb', 'T', 'H', 'lm', 'lx', 'a', 'yr', 'eV', 'pc', 'Jy', 'mag', 'R', 'bit', 'byte', 'G', 'barn']
        prefixes = ['y', 'z', 'a', 'f', 'p', 'n', 'u', 'm', 'c', 'd', '', 'da', 'h', 'k', 'M', 'G', 'T', 'P', 'E', 'Z', 'Y']
        for key in (prefix + base for base in bases for prefix in prefixes):
            if key not in names:
                names[key] = getattr(u, key)
        simple_units = ['deg', 'arcmin', 'arcsec', 'mas', 'min', 'h', 'd', 'Ry', 'solMass', 'u', 'solLum', 'solRad', 'AU', 'lyr', 'count', 'ct', 'photon', 'ph', 'pixel', 'pix', 'D', 'Sun', 'chan', 'bin', 'voxel', 'adu', 'beam', 'erg', 'Angstrom', 'angstrom']
        names.update(((unit, getattr(u, unit)) for unit in simple_units))
        return names

    @classmethod
    def to_string(cls, unit: UnitBase, fraction: bool | Literal['inline', 'multiline']=False, deprecations: DeprecatedUnitAction=DeprecatedUnitAction.WARN) -> str:
        unit = cls._decompose_to_known_units(unit)
        parts = []
        base = np.log10(unit.scale)
        if base % 1.0 != 0.0:
            raise UnitScaleError(f'The FITS unit format is not able to represent scales that are not powers of 10.  Multiply your data by {unit.scale:e}.')
        elif unit.scale != 1.0:
            parts.append(f'10**{int(base)}')
            unit = CompositeUnit(1, unit.bases, unit.powers)
        if unit.bases:
            parts.append(super().to_string(unit, fraction=fraction))
        return cls._scale_unit_separator.join(parts)

    @classmethod
    def parse(cls, s: str, debug: bool=False) -> UnitBase:
        result = cls._do_parse(s, debug)
        if hasattr(result, 'function_unit'):
            raise ValueError('Function units are not yet supported for FITS units.')
        return result

def future_keyword_only(names: list[str], *, since=list[str]) -> FunctionType:

    def decorate(raw_function):
        future_kwo_names = names
        if len(future_kwo_names) != len(since):
            raise ValueError(f'Expected names and since values with identical length. Got len(names)={len(names)!r} and len(since)={len(since)!r}')
        params = signature(raw_function).parameters
        params_names: list[str] = list(params)
        future_kwo_to_since = dict(zip(future_kwo_names, since))
        if any((n not in params for n in future_kwo_names)):
            unknown = sorted(set(future_kwo_names) - set(params_names))
            raise ValueError(f"The following arguments cannot be marked as future keyword-only because they were not found in the decorated function's signature: {', '.join(unknown)}")
        pos_or_kw_names = {n for n, p in params.items() if p.kind is p.POSITIONAL_OR_KEYWORD}
        if not pos_or_kw_names.issuperset(future_kwo_names):
            diff = sorted(set(future_kwo_names) - pos_or_kw_names)
            raise ValueError(f"The following arguments cannot be marked as future keyword-only because they are not currently positional-or-keyword: {', '.join(diff)}")
        future_kwo_positions = [params_names.index(n) for n in future_kwo_names]
        idx_min = min(future_kwo_positions)
        idx_max = max(future_kwo_positions) + 1
        while idx_max < len(params):
            p = params[params_names[idx_max]]
            if p.kind in (p.KEYWORD_ONLY, p.VAR_KEYWORD):
                break
            idx_max += 1
        if any((n not in future_kwo_names for n in list(params)[idx_min:idx_max])):
            broken = params_names[max(future_kwo_positions) + 1:idx_max]
            raise ValueError(f"The following positionally-allowed arguments were not marked as future keyword-only and would be broken under future keyword-only requirements: {', '.join(broken)}")

        @wraps(raw_function)
        def decorated_function(*args, **kwargs):
            if len(args) > idx_min:
                flagged_positions = range(idx_min, len(args))
                flagged_names = [params_names[pos] for pos in flagged_positions]
                depr_versions = [future_kwo_to_since[n] for n in flagged_names]
                if len(set(depr_versions)) == 1:
                    since_details = depr_versions[0]
                else:
                    since_details = ', '.join(depr_versions) + ', respectively'
                msg = f"The following arguments were received positionally, which will be disallowed in a future release: {', '.join(flagged_names)}\nPass them as keywords to suppress this warning. (deprecated since {since_details})"
                warnings.warn(msg, AstropyDeprecationWarning, stacklevel=2)
            return raw_function(*args, **kwargs)
        return decorated_function
    return decorate

def sanitize_power(p: UnitPowerLike) -> UnitPower:
    if p.__class__ is int:
        return p
    denom = getattr(p, 'denominator', None)
    if denom is None:
        p = maybe_simple_fraction(p)
        if isinstance(p, float):
            return p
        denom = p.denominator
    if denom == 1:
        return int(p.numerator)
    elif denom & denom - 1 == 0:
        p = float(p)
    return p

# --- helper: astropy.units.utils.maybe_simple_fraction ---
def maybe_simple_fraction(p: UnitPowerLike, max_denominator: int=100) -> UnitPower:
    if p.__class__ is int or p.__class__ is Fraction:
        return p
    if p == 0:
        return 0
    n, d = float(p).as_integer_ratio()
    a = n // d
    n0, d0 = (1, 0)
    n1, d1 = (a, 1)
    while d1 <= max_denominator:
        if _JUST_BELOW_UNITY <= n1 / (d1 * p) <= _JUST_ABOVE_UNITY:
            return Fraction(n1, d1)
        n, d = (d, n - a * d)
        a = n // d
        n0, n1 = (n1, n0 + a * n1)
        d0, d1 = (d1, d0 + a * d1)
    return float(p)

class MaskableShapedLikeNDArray(ShapedLikeNDArray):

    @property
    @abc.abstractmethod
    def masked(self):
        pass

    @property
    @abc.abstractmethod
    def mask(self):
        pass

    @property
    def unmasked(self):
        return self._apply(lambda x: getattr(x, 'unmasked', x))

    def filled(self, fill_value):
        unmasked = self.unmasked.copy()
        unmasked[self.mask] = fill_value
        return unmasked

def combine_masks(masks, *, out=None, where=True, copy=True):
    masks = [m if m.dtype.names is None else m != np.zeros((), dtype=m.dtype) for m in masks if m is not None and m is not False]
    if not masks:
        if out is None:
            return False
        else:
            np.copyto(out, False, where=where)
            return out
    if len(masks) == 1:
        if out is None:
            return masks[0].copy() if copy else masks[0]
        else:
            np.copyto(out, masks[0], where=where)
            return out
    result = np.logical_or(masks[0], masks[1], out=out, where=where)
    for mask in masks[2:]:
        result = np.logical_or(result, mask, out=out, where=where)
    return result

class MaskedRecarrayInfo(MaskedNDArrayInfo):

    def _represent_as_dict(self):
        masked_ndarray = self._parent.view(np.ndarray)
        return masked_ndarray.info._represent_as_dict()

# --- helper: astropy.utils.masked.core.MaskedNDArrayInfo ---
class MaskedNDArrayInfo(MaskedInfoBase, ParentDtypeInfo):
    attr_names = ParentDtypeInfo.attr_names | {'serialize_method'}
    _represent_as_dict_primary_data = 'data'

    def _represent_as_dict(self):
        out = super()._represent_as_dict()
        masked_array = self._parent
        method = self.serialize_method[self._serialize_context]
        if method == 'data_mask':
            out['data'] = masked_array.unmasked
            if np.any(masked_array.mask):
                out['mask'] = masked_array.mask
        elif method == 'null_value':
            out['data'] = np.ma.MaskedArray(masked_array.unmasked, mask=masked_array.mask)
        else:
            raise ValueError('serialize method must be either "data_mask" or "null_value"')
        return out

    def _construct_from_dict(self, map):
        map.setdefault('mask', getattr(map['data'], 'mask', False))
        return self._parent_cls.from_unmasked(**map)

def get_data_and_mask(array):
    mask = getattr(array, 'mask', None)
    if mask is None:
        return (array, None)
    try:
        return (array.unmasked, mask)
    except AttributeError as exc:
        if not isinstance(array, np.ma.MaskedArray):
            raise AttributeError(f"'{type(array).__name__}' object has a 'mask' attribute but not an 'unmasked' attribute (and is not an np.ma.MaskedArray instance).") from None
    if array is np.ma.masked:
        raise ValueError('cannot handle np.ma.masked.')
    return (array._data, mask)

def system_info() -> None:
    report_lines = (*_header('platform'), *_report_platform(), '', *_header('packages'), *_report_packages())
    print('\n'.join(report_lines))

# --- helper: astropy.utils.system_info._header ---
def _header(name: str) -> list[str]:
    return [name, '-' * len(name)]

# --- helper: astropy.utils.system_info._report_packages ---
def _report_packages() -> list[str]:
    pkgs = ['astropy', 'numpy', 'scipy', 'matplotlib', 'pandas']
    lines = [f"{p:<20} {('--' if find_spec(p) is None else version(p))}" for p in pkgs]
    try:
        import erfa
    except ImportError:
        v = '--'
    else:
        v = erfa.__version__
    p = 'pyerfa'
    lines.append(f'{p:<20} {v}')
    return lines

# --- helper: astropy.utils.system_info._report_platform ---
def _report_platform() -> list[str]:
    return [f'platform.platform() = {platform.platform()!r}', f'platform.version() = {platform.version()!r}', f'platform.python_version() = {platform.python_version()!r}']

def make_rgb(image_r, image_g, image_b, interval=ManualInterval(vmin=0, vmax=None), stretch=LinearStretch(), filename=None, output_dtype=np.uint8):
    map_ = RGBImageMapping(interval=interval, stretch=stretch)
    rgb = map_.make_rgb_image(image_r, image_g, image_b, output_dtype=output_dtype)
    if filename:
        import matplotlib.image
        matplotlib.image.imsave(filename, rgb, origin='lower')
    return rgb

# --- helper: astropy.visualization.basic_rgb.RGBImageMapping ---
class RGBImageMapping:

    def __init__(self, interval=ManualInterval(vmin=0, vmax=None), stretch=LinearStretch()):
        try:
            len(interval)
        except TypeError:
            interval = 3 * [interval]
        if len(interval) != 3:
            raise ValueError('please provide 1 or 3 instances for interval.')
        self.intervals = interval
        self.stretch = stretch

    def make_rgb_image(self, image_r, image_g, image_b, output_dtype=np.uint8):
        if output_dtype not in _OUTPUT_IMAGE_FORMATS:
            raise ValueError(f"'output_dtype' must be one of {_OUTPUT_IMAGE_FORMATS}!")
        image_r = np.asarray(image_r)
        image_g = np.asarray(image_g)
        image_b = np.asarray(image_b)
        if image_r.shape != image_g.shape or image_g.shape != image_b.shape:
            msg = 'The image shapes must match. r: {}, g: {} b: {}'
            raise ValueError(msg.format(image_r.shape, image_g.shape, image_b.shape))
        image_rgb = self.apply_mappings(image_r, image_g, image_b)
        if np.issubdtype(output_dtype, float):
            conv_images = self._convert_images_to_float(image_rgb, output_dtype)
        elif np.issubdtype(output_dtype, np.unsignedinteger):
            conv_images = self._convert_images_to_uint(image_rgb, output_dtype)
        return np.dstack(conv_images)

    def apply_mappings(self, image_r, image_g, image_b):
        image_rgb = [image_r, image_g, image_b]
        for i, img in enumerate(image_rgb):
            vmin, vmax = self.intervals[i].get_limits(img)
            img = np.array(img, copy=True, dtype=float)
            np.subtract(img, vmin, out=img)
            np.true_divide(img, vmax - vmin, out=img)
            img = np.clip(img, 0.0, 1.0, out=img)
            img = self.stretch(img, out=img, clip=False)
            image_rgb[i] = img
        return np.asarray(image_rgb)

    def _convert_images_to_float(self, image_rgb, output_dtype):
        return image_rgb.astype(output_dtype)

    def _convert_images_to_uint(self, image_rgb, output_dtype):
        pixmax = float(np.iinfo(output_dtype).max)
        image_rgb *= pixmax
        return image_rgb.astype(output_dtype)

class SymmetricInterval(BaseInterval):

    def __init__(self, radius=None, *, midpoint=0):
        self.radius = radius
        self.midpoint = midpoint

    def get_limits(self, values):
        radius = self.radius
        if radius is None:
            values = self._process_values(values)
            radius = np.max([np.max(values) - self.midpoint, self.midpoint - np.min(values)])
        return (self.midpoint - radius, self.midpoint + radius)

# --- helper: astropy.visualization.interval.BaseInterval ---
class BaseInterval(BaseTransform):

    @abc.abstractmethod
    def get_limits(self, values):
        raise NotImplementedError('Needs to be implemented in a subclass.')

    @staticmethod
    def _process_values(values):
        data, mask = get_data_and_mask(np.asanyarray(values))
        ok = np.isfinite(data)
        if mask is not None:
            ok &= ~mask
        return data[ok]

    def __call__(self, values, clip=True, out=None):
        vmin, vmax = self.get_limits(values)
        if out is None:
            values = np.subtract(values, float(vmin))
        else:
            if out.dtype.kind != 'f':
                raise TypeError('Can only do in-place scaling for floating-point arrays')
            values = np.subtract(values, float(vmin), out=out)
        if vmax - vmin != 0:
            np.true_divide(values, vmax - vmin, out=values)
        if clip:
            np.clip(values, 0.0, 1.0, out=values)
        return values

class AsymmetricPercentileInterval(BaseInterval):

    def __init__(self, lower_percentile=None, upper_percentile=None, n_samples=None):
        self.lower_percentile = lower_percentile if lower_percentile is not None else 0.0
        self.upper_percentile = upper_percentile if upper_percentile is not None else 100.0
        self.n_samples = n_samples

    def get_limits(self, values):
        values = self._process_values(values)
        if self.n_samples is not None and values.size > self.n_samples:
            values = np.random.choice(values, self.n_samples)
        vmin, vmax = np.percentile(values, (self.lower_percentile, self.upper_percentile))
        return (vmin, vmax)

