@future_keyword_only(['power', 'asinh_a', 'vmin', 'vmax', 'min_percent', 'max_percent', 'percent', 'clip', 'log_a', 'invalid', 'sinh_a'], since=['7.1'] * 11)
@deprecated_renamed_argument(['min_cut', 'max_cut'], ['vmin', 'vmax'], ['6.1', '6.1'])
def simple_norm(data, stretch='linear', power=1.0, asinh_a=0.1, vmin=None, vmax=None, min_percent=None, max_percent=None, percent=None, clip=False, log_a=1000, invalid=-1.0, sinh_a=0.3):
    simple_norm = SimpleNorm(stretch=stretch, percent=percent, min_percent=min_percent, max_percent=max_percent, vmin=vmin, vmax=vmax, power=power, log_a=log_a, asinh_a=asinh_a, sinh_a=sinh_a, clip=clip, invalid=invalid)
