# --- helper: astropy.visualization.mpl_normalize.SimpleNorm ---
class SimpleNorm:

    def __init__(self, stretch='linear', percent=None, *, min_percent=None, max_percent=None, vmin=None, vmax=None, power=1.0, log_a=1000, asinh_a=0.1, sinh_a=0.3, clip=False, invalid=-1.0):
        if percent is not None:
            interval = PercentileInterval(percent)
        elif min_percent is not None or max_percent is not None:
            interval = AsymmetricPercentileInterval(lower_percentile=min_percent, upper_percentile=max_percent)
        elif vmin is not None or vmax is not None:
            interval = ManualInterval(vmin, vmax)
        else:
            interval = MinMaxInterval()
        self.interval = interval
        if stretch == 'linear':
            stretch = LinearStretch()
        elif stretch == 'sqrt':
            stretch = SqrtStretch()
        elif stretch == 'power':
            stretch = PowerStretch(power)
        elif stretch == 'log':
            stretch = LogStretch(log_a)
        elif stretch == 'asinh':
            stretch = AsinhStretch(asinh_a)
        elif stretch == 'sinh':
            stretch = SinhStretch(sinh_a)
        else:
            raise ValueError(f'Unknown stretch: {stretch}.')
        self.stretch = stretch
        self.clip = clip
        self.invalid = invalid

    def __call__(self, data):
        vmin, vmax = self.interval.get_limits(data)
        return ImageNormalize(vmin=vmin, vmax=vmax, stretch=self.stretch, clip=self.clip, invalid=self.invalid)

    def imshow(self, data, ax=None, **kwargs):
        import matplotlib.pyplot as plt
        if ax is None:
            ax = plt.gca()
        if 'norm' in kwargs:
            raise ValueError('This class already defines the norm. Use matplotlib.pyplot.imshow directly to use your norm.')
        return ax.imshow(data, norm=self(data), **kwargs)

def allclose(a, b, rtol=1e-05, atol=None, equal_nan=False) -> bool:
    return np.allclose(*_unquantify_allclose_arguments(a, b, rtol, atol), equal_nan)

# --- helper: astropy.units.quantity._unquantify_allclose_arguments ---
def _unquantify_allclose_arguments(actual, desired, rtol, atol):
    actual = Quantity(actual, subok=True, copy=COPY_IF_NEEDED)
    desired = Quantity(desired, subok=True, copy=COPY_IF_NEEDED)
    try:
        desired = desired.to(actual.unit)
    except UnitsError:
        raise UnitsError(f"Units for 'desired' ({desired.unit}) and 'actual' ({actual.unit}) are not convertible")
    if atol is None:
        atol = Quantity(0)
    else:
        atol = Quantity(atol, subok=True, copy=COPY_IF_NEEDED)
        try:
            atol = atol.to(actual.unit)
        except UnitsError:
            raise UnitsError(f"Units for 'atol' ({atol.unit}) and 'actual' ({actual.unit}) are not convertible")
    rtol = Quantity(rtol, subok=True, copy=COPY_IF_NEEDED)
    try:
        rtol = rtol.to(dimensionless_unscaled)
    except Exception:
        raise UnitsError("'rtol' should be dimensionless")
    return (actual.value, desired.value, rtol.value, atol.value)

class GroverBondVocabularyBuilder(VocabularyBuilder):
    BOND_FEATURES = ['BondType', 'Stereo', 'BondDir']

    def __init__(self, max_size: Optional[int]=None):
        self.specials = ('<pad>', '<other>')
        self.min_freq = 1
        self.size = max_size
        self.itos = list(self.specials)
        self.stoi = self._make_reverse_mapping(self.itos)
        self.pad_index = 0
        self.other_index = 1

    def build(self, dataset: Dataset, log_every_n: int=1000) -> None:
        counter: Dict[str, int] = Counter()
        logger.info('Starting to build bond vocabulary')
        for i, (x, _, _, _) in enumerate(dataset.itersamples()):
            if i % log_every_n == 0:
                logger.info('Computing contextual property of bonds in molecule %i' % i)
            if isinstance(x, str):
                smiles = x
            elif isinstance(x, np.ndarray):
                smiles = x.squeeze().item()
            mol = Chem.MolFromSmiles(smiles)
            for bond in mol.GetBonds():
                v = self.bond_to_vocab(mol, bond)
                counter[v] += 1
        logger.info('Completed enumeration of bond contextual properties.')
        words_and_frequencies = sorted(counter.items(), key=lambda tup: tup[0])
        words_and_frequencies.sort(key=lambda tup: tup[1], reverse=True)
        for word, freq in words_and_frequencies:
            if len(self.itos) == self.size:
                break
            self.itos.append(word)
        if self.size is None:
            self.size = len(self.itos)
        self.stoi = self._make_reverse_mapping(self.itos)
        logger.info('Completed building of bond vocabulary')

    def build_from_csv(self, csv_path: str, smiles_field: str, log_every_n: int=1000) -> None:
        counter: Dict[str, int] = Counter()
        logger.info('Starting to build bond vocabulary')
        chunksize = 8196
        for i, df in enumerate(pd.read_csv(csv_path, chunksize=chunksize)):
            row_count = i * chunksize
            for index, row in df.iterrows():
                if (row_count + i) % log_every_n == 0:
                    logger.info('Computing contextual property of bonds in molecule %i' % i)
                smiles = row[smiles_field]
                mol = Chem.MolFromSmiles(smiles)
                for bond in mol.GetBonds():
                    v = self.bond_to_vocab(mol, bond)
                    counter[v] += 1
            logger.info('Completed enumeration of bond contextual properties.')
        words_and_frequencies = sorted(counter.items(), key=lambda tup: tup[0])
        words_and_frequencies.sort(key=lambda tup: tup[1], reverse=True)
        for word, freq in words_and_frequencies:
            if len(self.itos) == self.size:
                break
            self.itos.append(word)
        if self.size is None:
            self.size = len(self.itos)
        self.stoi = self._make_reverse_mapping(self.itos)
        logger.info('Completed building of bond vocabulary')

    def save(self, fname: str) -> None:
        vocab = {'stoi': self.stoi, 'itos': self.itos, 'size': self.size}
        with open(fname, 'w') as f:
            json.dump(vocab, f)

    @classmethod
    def load(cls, fname: str) -> 'GroverBondVocabularyBuilder':
        with open(fname, 'r') as f:
            data = json.load(f)
        vocab = cls()
        vocab.stoi, vocab.itos, vocab.size = (data['stoi'], data['itos'], data['size'])
        return vocab

    @staticmethod
    def bond_to_vocab(mol: RDKitMol, bond: RDKitBond):
        bond_neighbors: Dict[str, int] = Counter()
        two_neighbors = (bond.GetBeginAtom(), bond.GetEndAtom())
        two_indices = [a.GetIdx() for a in two_neighbors]
        for nei_atom in two_neighbors:
            for a in nei_atom.GetNeighbors():
                a_idx = a.GetIdx()
                if a_idx in two_indices:
                    continue
                tmp_bond = mol.GetBondBetweenAtoms(nei_atom.GetIdx(), a_idx)
                bond_neighbors[str(nei_atom.GetSymbol()) + '-' + GroverBondVocabularyBuilder._get_bond_feature_name(tmp_bond)] += 1
        keys = list(bond_neighbors.keys())
        keys.sort()
        output = GroverBondVocabularyBuilder._get_bond_feature_name(bond)
        for k in keys:
            output = '%s_%s%d' % (output, k, bond_neighbors[k])
        return output

    @staticmethod
    def _get_bond_feature_name(bond: RDKitBond):
        ret = []
        for bond_feature in GroverBondVocabularyBuilder.BOND_FEATURES:
            fea = eval(f'bond.Get{bond_feature}')()
            ret.append(str(fea))
        return '(' + '-'.join(ret) + ')'

    def _make_reverse_mapping(self, itos):
        return {tok: i for i, tok in enumerate(itos)}

    def encode(self, mol: RDKitMol, bond: RDKitBond) -> str:
        return self.stoi.get(self.bond_to_vocab(mol, bond))

class GroverAtomVocabularyBuilder(VocabularyBuilder):

    def __init__(self, max_size: Optional[int]=None):
        self.specials = ('<pad>', '<other>')
        self.min_freq = 1
        self.size = max_size
        self.itos = list(self.specials)
        self.stoi = self._make_reverse_mapping(self.itos)
        self.pad_index = 0
        self.other_index = 1

    def build(self, dataset: Dataset, log_every_n: int=1000) -> None:
        counter: Dict[str, int] = Counter()
        logger.info('Starting to build atom vocabulary')
        for i, (x, _, _, _) in enumerate(dataset.itersamples()):
            if i % log_every_n == 0:
                logger.info('Computing contextual property of atoms in molecule %i' % i)
            if isinstance(x, str):
                smiles = x
            elif isinstance(x, np.ndarray):
                x = x.squeeze()
                assert x.ndim == 0, 'expected x attribute of dataset to be a 1-D array of SMILES strings'
                smiles = x.item()
            mol = Chem.MolFromSmiles(smiles)
            for atom in mol.GetAtoms():
                v = self.atom_to_vocab(mol, atom)
                counter[v] += 1
        logger.info('Completed enumeration of atom contextual properties.')
        words_and_frequencies = sorted(counter.items(), key=lambda tup: tup[0])
        words_and_frequencies.sort(key=lambda tup: tup[1], reverse=True)
        for word, freq in words_and_frequencies:
            if len(self.itos) == self.size:
                break
            self.itos.append(word)
        if self.size is None:
            self.size = len(self.itos)
        self.stoi = self._make_reverse_mapping(self.itos)
        logger.info('Completed building of atom vocabulary')

    def build_from_csv(self, csv_path: str, smiles_field: str, log_every_n: int=1000) -> None:
        counter: Dict[str, int] = Counter()
        logger.info('Starting to build atom vocabulary')
        chunksize = 8196
        for i, df in enumerate(pd.read_csv(csv_path, chunksize=chunksize)):
            for index, row in df.iterrows():
                if (i * chunksize + index) % log_every_n == 0:
                    logger.info('Computing contextual property of atoms in molecule %i' % i)
                smiles = row[smiles_field]
                mol = Chem.MolFromSmiles(smiles)
                for atom in mol.GetAtoms():
                    v = self.atom_to_vocab(mol, atom)
                    counter[v] += 1
        logger.info('Completed enumeration of atom contextual properties.')
        words_and_frequencies = sorted(counter.items(), key=lambda tup: tup[0])
        words_and_frequencies.sort(key=lambda tup: tup[1], reverse=True)
        for word, freq in words_and_frequencies:
            if len(self.itos) == self.size:
                break
            self.itos.append(word)
        if self.size is None:
            self.size = len(self.itos)
        self.stoi = self._make_reverse_mapping(self.itos)
        logger.info('Completed building of atom vocabulary')

    def save(self, fname: str) -> None:
        vocab = {'stoi': self.stoi, 'itos': self.itos, 'size': self.size}
        with open(fname, 'w') as f:
            json.dump(vocab, f)

    @classmethod
    def load(cls, fname: str) -> 'GroverAtomVocabularyBuilder':
        with open(fname, 'r') as f:
            data = json.load(f)
        vocab = cls()
        vocab.stoi, vocab.itos, vocab.size = (data['stoi'], data['itos'], data['size'])
        return vocab

    @staticmethod
    def atom_to_vocab(mol: RDKitMol, atom: RDKitAtom) -> str:
        atom_neighbors: Dict[str, int] = Counter()
        for a in atom.GetNeighbors():
            bond = mol.GetBondBetweenAtoms(atom.GetIdx(), a.GetIdx())
            atom_neighbors[str(a.GetSymbol()) + '-' + str(bond.GetBondType())] += 1
        keys = list(atom_neighbors.keys())
        keys.sort()
        output = atom.GetSymbol()
        for key in keys:
            output = '%s_%s%d' % (output, key, atom_neighbors[key])
        return output

    def _make_reverse_mapping(self, itos):
        return {tok: i for i, tok in enumerate(itos)}

    def encode(self, mol: RDKitMol, atom: RDKitAtom) -> str:
        return self.stoi.get(self.atom_to_vocab(mol, atom))

