class MAML(object):

    def __init__(self, learner: MetaLearner, learning_rate: Union[float, LearningRateSchedule]=0.001, optimization_steps: int=1, meta_batch_size: int=10, optimizer: Optimizer=Adam(), model_dir: Optional[str]=None, device: Optional[torch.device]=None):
        self.learner: MetaLearner = learner
        self.learning_rate: Union[float, LearningRateSchedule] = learning_rate
        self.optimization_steps: int = optimization_steps
        self.meta_batch_size: int = meta_batch_size
        self.optimizer: Optimizer = optimizer
        self._model_dir_is_temp: bool = False
        if model_dir is not None:
            if not os.path.exists(model_dir):
                os.makedirs(model_dir)
        else:
            model_dir = tempfile.mkdtemp()
            self._model_dir_is_temp = True
        self.model_dir = model_dir
        self.save_file: str = '%s/%s' % (self.model_dir, 'model')
        if device is None:
            if torch.cuda.is_available():
                device = torch.device('cuda')
            elif torch.backends.mps.is_available():
                device = torch.device('mps')
            else:
                device = torch.device('cpu')
        self.device: torch.device = device
        for param in learner.parameters():
            param = param.to(device)
            param.requires_grad_()
        self._global_step: int = 0
        self._pytorch_optimizer = self.optimizer._create_pytorch_optimizer(learner.parameters())
        if isinstance(self.optimizer.learning_rate, LearningRateSchedule):
            self._lr_schedule = self.optimizer.learning_rate._create_pytorch_schedule(self._pytorch_optimizer)
        else:
            self._lr_schedule = None
        task_optimizer: Optimizer = GradientDescent(learning_rate=self.learning_rate)
        self._pytorch_task_optimizer = task_optimizer._create_pytorch_optimizer(learner.parameters())
        if isinstance(task_optimizer.learning_rate, LearningRateSchedule):
            self._lr_schedule = task_optimizer.learning_rate._create_pytorch_schedule(self._pytorch_task_optimizer)
        else:
            self._lr_schedule = None

    def __del__(self):
        if '_model_dir_is_temp' in dir(self) and self._model_dir_is_temp:
            shutil.rmtree(self.model_dir)

    def fit(self, steps: int, max_checkpoints_to_keep: int=5, checkpoint_interval: int=600, restore: bool=False):
        if restore:
            self.restore()
        checkpoint_time: float = time.time()
        learner = self.learner
        variables: OneOrMany[torch.Tensor] = learner.variables
        for i in range(steps):
            self._pytorch_optimizer.zero_grad()
            for j in range(self.meta_batch_size):
                learner.select_task()
                updated_variables: OneOrMany[torch.Tensor] = variables
                for k in range(self.optimization_steps):
                    loss, _ = self.learner.compute_model(learner.get_batch(), updated_variables, True)
                    gradients: Tuple[torch.Tensor, ...] = torch.autograd.grad(loss, updated_variables, grad_outputs=torch.ones_like(loss), create_graph=True, retain_graph=True)
                    updated_variables = [v if g is None else v - self.learning_rate * g for v, g in zip(updated_variables, gradients)]
                meta_loss, _ = self.learner.compute_model(learner.get_batch(), updated_variables, True)
                meta_gradients: Tuple[torch.Tensor, ...] = torch.autograd.grad(meta_loss, variables, grad_outputs=torch.ones_like(meta_loss), retain_graph=True)
                if j == 0:
                    summed_gradients: Union[Tuple[torch.Tensor, ...], List[torch.Tensor]] = meta_gradients
                else:
                    summed_gradients = [s + g for s, g in zip(summed_gradients, meta_gradients)]
                ind: int = 0
                for param in self.learner.parameters():
                    param.grad = summed_gradients[ind]
                    ind = ind + 1
            self._pytorch_optimizer.step()
            if self._lr_schedule is not None:
                self._lr_schedule.step()
            if i == steps - 1 or time.time() >= checkpoint_time + checkpoint_interval:
                self.save_checkpoint(max_checkpoints_to_keep)
                checkpoint_time = time.time()

    def restore(self) -> None:
        last_checkpoint: Union[List[str], str] = sorted(self.get_checkpoints(self.model_dir))
        if len(last_checkpoint) == 0:
            raise ValueError('No checkpoint found')
        last_checkpoint = last_checkpoint[0]
        data: Any = torch.load(last_checkpoint, map_location=self.device)
        self.learner.__dict__ = data['model_state_dict']
        self.learning_rate = data['learning_rate']
        self._pytorch_optimizer.load_state_dict(data['optimizer_state_dict'])
        self._pytorch_task_optimizer.load_state_dict(data['task_optimizer_state_dict'])
        self._global_step = data['global_step']

    def train_on_current_task(self, optimization_steps: int=1, restore: bool=True):
        if restore:
            self.restore()
        variables: OneOrMany[torch.Tensor] = self.learner.variables
        task_optimizer: Optimizer = GradientDescent(learning_rate=self.learning_rate)
        self._pytorch_task_optimizer = task_optimizer._create_pytorch_optimizer(self.learner.parameters())
        if isinstance(task_optimizer.learning_rate, LearningRateSchedule):
            self._lr_schedule = task_optimizer.learning_rate._create_pytorch_schedule(self._pytorch_task_optimizer)
        else:
            self._lr_schedule = None
        for i in range(optimization_steps):
            self._pytorch_task_optimizer.zero_grad()
            inputs = self.learner.get_batch()
            loss, _ = self.learner.compute_model(inputs, variables, True)
            loss.backward()
            self._pytorch_task_optimizer.step()

    def predict_on_batch(self, inputs: OneOrMany[torch.Tensor]) -> Tuple[torch.Tensor, Sequence[torch.Tensor]]:
        return self.learner.compute_model(inputs, self.learner.variables, False)

    def save_checkpoint(self, max_checkpoints_to_keep: int=5, model_dir: Optional[str]=None) -> None:
        if model_dir is None:
            model_dir = self.model_dir
        if not os.path.exists(model_dir):
            os.makedirs(model_dir)
        data: Dict[str, Any] = {'model_state_dict': self.learner.__dict__, 'learning_rate': self.learning_rate, 'optimizer_state_dict': self._pytorch_optimizer.state_dict(), 'task_optimizer_state_dict': self._pytorch_task_optimizer.state_dict(), 'global_step': self._global_step}
        temp_file: str = os.path.join(model_dir, 'temp_checkpoint.pt')
        torch.save(data, temp_file)
        paths: List[str] = [os.path.join(model_dir, 'checkpoint%d.pt' % (i + 1)) for i in range(max_checkpoints_to_keep)]
        if os.path.exists(paths[-1]):
            os.remove(paths[-1])
        for i in reversed(range(max_checkpoints_to_keep - 1)):
            if os.path.exists(paths[i]):
                os.rename(paths[i], paths[i + 1])
        os.rename(temp_file, paths[0])

    def get_checkpoints(self, model_dir: Optional[str]=None) -> List[str]:
        if model_dir is None:
            model_dir = self.model_dir
        files: List[str] = sorted(os.listdir(model_dir))
        files = [f for f in files if f.startswith('checkpoint') and f.endswith('.pt')]
        return [os.path.join(model_dir, f) for f in files]

def get_negative_expectation(q_samples, measure='JSD', average_loss=True):
    import math
    import torch
    log_2 = math.log(2.0)
    if measure == 'GAN':
        Eq = torch.nn.functional.softplus(-q_samples) + q_samples
    elif measure == 'JSD':
        Eq = torch.nn.functional.softplus(-q_samples) + q_samples - log_2
    elif measure == 'X2':
        Eq = -0.5 * (torch.sqrt(q_samples ** 2) + 1.0) ** 2
    elif measure == 'KL':
        Eq = torch.exp(q_samples)
    elif measure == 'RKL':
        Eq = q_samples - 1.0
    elif measure == 'DV':
        Eq = log_sum_exp(q_samples, 0) - math.log(q_samples.size(0))
    elif measure == 'H2':
        Eq = torch.exp(q_samples) - 1.0
    elif measure == 'W1':
        Eq = q_samples
    else:
        raise ValueError('Unknown measure: {}'.format(measure))
    if average_loss:
        return Eq.mean()
    else:
        return Eq

# --- helper: deepchem.models.losses.log_sum_exp ---
def log_sum_exp(x, axis=None):
    import torch
    x_max = torch.max(x, axis)[0]
    y = torch.log(torch.exp(x - x_max).sum(axis)) + x_max
    return y

def get_positive_expectation(p_samples, measure='JSD', average_loss=True):
    import math
    import torch
    log_2 = math.log(2.0)
    if measure == 'GAN':
        Ep = -torch.nn.functional.softplus(-p_samples)
    elif measure == 'JSD':
        Ep = log_2 - torch.nn.functional.softplus(-p_samples)
    elif measure == 'X2':
        Ep = p_samples ** 2
    elif measure == 'KL':
        Ep = p_samples + 1.0
    elif measure == 'RKL':
        Ep = -torch.exp(-p_samples)
    elif measure == 'DV':
        Ep = p_samples
    elif measure == 'H2':
        Ep = 1.0 - torch.exp(-p_samples)
    elif measure == 'W1':
        Ep = p_samples
    else:
        raise ValueError('Unknown measure: {}'.format(measure))
    if average_loss:
        return Ep.mean()
    else:
        return Ep

class ScaledDotProductAttention(nn.Module):

    def __init__(self):
        self.epsilon = -1000000000.0
        super(ScaledDotProductAttention, self).__init__()

    def forward(self, query: torch.Tensor, key: torch.Tensor, value: torch.Tensor, mask: Optional[torch.Tensor]=None, dropout: Optional[nn.Dropout]=None):
        d_k = query.size(-1)
        scores = torch.matmul(query, key.transpose(-2, -1)) / math.sqrt(d_k)
        if mask is not None:
            scores = scores.masked_fill(mask == 0, self.epsilon)
        p_attn = scores.softmax(dim=-1)
        if dropout is not None:
            p_attn = dropout(p_attn)
        return (torch.matmul(p_attn, value), p_attn)

class SelfAttention(nn.Module):

    def __init__(self, in_features, out_features, hidden_size=128):
        super(SelfAttention, self).__init__()
        self.w1 = torch.nn.Parameter(torch.FloatTensor(hidden_size, in_features))
        self.w2 = torch.nn.Parameter(torch.FloatTensor(out_features, hidden_size))
        self.reset_parameters()

    def reset_parameters(self):
        nn.init.xavier_normal_(self.w1)
        nn.init.xavier_normal_(self.w2)

    def forward(self, X):
        x = torch.tanh(torch.matmul(self.w1, X.transpose(1, 0)))
        x = torch.matmul(self.w2, x)
        attn = torch.nn.functional.softmax(x, dim=-1)
        x = torch.matmul(attn, X)
        return (x, attn)

class GNN(torch.nn.Module):

    def __init__(self, node_type_embedding, chirality_embedding, gconvs, batch_norms, dropout, jump_knowledge, init_emb=False):
        super(GNN, self).__init__()
        self.node_type_embedding = node_type_embedding
        self.chirality_embedding = chirality_embedding
        self.gconv = gconvs
        self.batch_norms = batch_norms
        self.dropout = dropout
        self.num_layer = len(gconvs)
        self.jump_knowledge = jump_knowledge
        if init_emb:
            torch.nn.init.xavier_uniform_(self.node_type_embedding.weight.data)
            torch.nn.init.xavier_uniform_(self.chirality_embedding.weight.data)

    def forward(self, data: BatchGraphData):
        node_feats = data.node_features[:, 0].long()
        chiral_feats = data.node_features[:, 1].long()
        node_emb = self.node_type_embedding(node_feats)
        chir_emb = self.chirality_embedding(chiral_feats)
        x = node_emb + chir_emb
        h_list = [x]
        for i, conv_layer in enumerate(self.gconv):
            if isinstance(conv_layer, (GINEConv, GATConv)):
                h = conv_layer(h_list[i], data.edge_index, data.edge_features)
            elif isinstance(conv_layer, (GCNConv, SAGEConv)):
                h = conv_layer(h_list[i], data.edge_index)
            h = self.batch_norms[i](h)
            h = F.dropout(F.relu(h), self.dropout, training=self.training)
            if i == self.num_layer - 1:
                h = F.dropout(h, self.dropout, training=self.training)
            else:
                h = F.dropout(F.relu(h), self.dropout, training=self.training)
            h_list.append(h)
        if self.jump_knowledge == 'concat':
            node_representation = torch.cat(h_list, dim=1)
        elif self.jump_knowledge == 'last':
            node_representation = h_list[-1]
        elif self.jump_knowledge == 'max':
            h_list = [h.unsqueeze_(0) for h in h_list]
            node_representation = torch.max(torch.cat(h_list, dim=0), dim=0)[0]
        elif self.jump_knowledge == 'sum':
            h_list = [h.unsqueeze_(0) for h in h_list]
            node_representation = torch.sum(torch.cat(h_list, dim=0), dim=0)[0]
        return (node_representation, data)

class LocalGlobalDiscriminator(nn.Module):

    def __init__(self, hidden_dim):
        super().__init__()
        self.weight = nn.Parameter(torch.Tensor(hidden_dim, hidden_dim))
        self.reset_parameters()

    def reset_parameters(self):
        size = self.weight.size(0)
        uniform(size, self.weight)

    def forward(self, x, summary):
        h = torch.matmul(summary, self.weight)
        return torch.sum(x * h, dim=1)

class GroverAtomVocabPredictor(nn.Module):

    def __init__(self, vocab_size: int, in_features: int=128):
        super(GroverAtomVocabPredictor, self).__init__()
        self.linear = nn.Linear(in_features, vocab_size)
        self.logsoftmax = nn.LogSoftmax(dim=1)

    def forward(self, embeddings):
        return self.logsoftmax(self.linear(embeddings))

class GroverBondVocabPredictor(nn.Module):

    def __init__(self, vocab_size: int, in_features: int=128):
        super(GroverBondVocabPredictor, self).__init__()
        self.linear = nn.Linear(in_features, vocab_size)
        self.linear_rev = nn.Linear(in_features, vocab_size)
        self.logsoftmax = nn.LogSoftmax(dim=1)

    def forward(self, embeddings):
        nm_bonds = embeddings.shape[0]
        ids1 = list(range(0, nm_bonds, 2))
        ids2 = list(range(1, nm_bonds, 2))
        logits = self.linear(embeddings[ids1]) + self.linear_rev(embeddings[ids2])
        return self.logsoftmax(logits)

class GroverMPNEncoder(nn.Module):

    def __init__(self, atom_messages: bool, init_message_dim: int, hidden_size: int, depth: int, undirected: bool, attach_feats: bool, attached_feat_fdim: int=0, bias: bool=True, dropout: float=0.2, activation: str='relu', input_layer: str='fc', dynamic_depth: str='none'):
        super(GroverMPNEncoder, self).__init__()
        if input_layer == 'none':
            assert init_message_dim == hidden_size
        assert dynamic_depth in ['uniform', 'truncnorm', 'none'], 'dynamic depth should be one of uniform, truncnorm, none'
        self.init_message_dim = init_message_dim
        self.depth = depth
        self.input_layer = input_layer
        self.layers_per_message = 1
        self.undirected = undirected
        self.atom_messages = atom_messages
        self.attached_feat = attach_feats
        assert dynamic_depth in ['none', 'truncnorm', 'uniform'], 'If dynamic depth, it should be truncnorm or uniform'
        self.dynamic_depth = dynamic_depth
        self.dropout_layer = nn.Dropout(p=dropout)
        if activation == 'relu':
            self.act_func = nn.ReLU()
        else:
            raise ValueError('Only ReLU activation function is supported')
        if self.input_layer == 'fc':
            self.W_i = nn.Linear(self.init_message_dim, hidden_size, bias=bias)
            w_h_input_size = hidden_size
        elif input_layer == 'none':
            w_h_input_size = self.init_message_dim
        if self.attached_feat:
            w_h_input_size += attached_feat_fdim
        self.W_h = nn.Linear(w_h_input_size, hidden_size, bias=bias)

    def forward(self, init_messages, init_attached_features, a2nei, a2attached, b2a=None, b2revb=None, adjs=None) -> torch.FloatTensor:
        if self.input_layer == 'fc':
            message = self.act_func(self.W_i(init_messages))
        elif self.input_layer == 'none':
            message = init_messages
        attached_feats = init_attached_features
        if self.training and self.dynamic_depth != 'none':
            if self.dynamic_depth == 'uniform':
                ndepth = abs(int(np.random.uniform(self.depth - 3, self.depth + 3)))
            elif self.dynamic_depth == 'truncnorm':
                mu, sigma = (self.depth, 1)
                lower, upper = (mu - 3 * sigma, mu + 3 * sigma)
                X = stats.truncnorm((lower - mu) / sigma, (upper - mu) / sigma, loc=mu, scale=sigma)
                ndepth = int(X.rvs(1)[0])
        else:
            ndepth = self.depth
        for _ in range(ndepth - 1):
            if self.undirected:
                message = (message + message[b2revb]) / 2
            nei_message = _select_neighbor_and_aggregate(message, a2nei)
            a_message = nei_message
            if self.attached_feat:
                attached_nei_feats = _select_neighbor_and_aggregate(attached_feats, a2attached)
                a_message = torch.cat((nei_message, attached_nei_feats), dim=1)
            if not self.atom_messages:
                rev_message = message[b2revb]
                if self.attached_feat:
                    atom_rev_message = attached_feats[b2a[b2revb]]
                    rev_message = torch.cat((rev_message, atom_rev_message), dim=1)
                message = a_message[b2a] - rev_message
            else:
                message = a_message
            message = self.W_h(message)
            message = self.dropout_layer(self.act_func(message))
        return message

