def _select_neighbor_and_aggregate(feature, index):
    neighbor = _index_select_nd(feature, index)
    return neighbor.sum(dim=1)

class GroverEmbedding(nn.Module):

    def __init__(self, node_fdim, edge_fdim, hidden_size=128, depth=1, undirected=False, dropout=0.2, activation='relu', num_mt_block=1, num_heads=4, bias=False, res_connection=False):
        super(GroverEmbedding, self).__init__()
        self.encoders = GroverTransEncoder(hidden_size=hidden_size, edge_fdim=edge_fdim, node_fdim=node_fdim, depth=depth, undirected=undirected, dropout=dropout, activation=activation, num_mt_block=num_mt_block, num_heads=num_heads, bias=bias, res_connection=res_connection)

    def forward(self, graph_batch: List[torch.Tensor]):
        output = self.encoders(graph_batch)
        return {'atom_from_atom': output[0][0], 'bond_from_atom': output[0][1], 'atom_from_bond': output[1][0], 'bond_from_bond': output[1][1]}

# --- helper: deepchem.models.torch_models.grover_layers.GroverTransEncoder ---
class GroverTransEncoder(nn.Module):

    def __init__(self, node_fdim: int, edge_fdim: int, depth: int=3, undirected: bool=False, num_mt_block: int=2, num_heads: int=2, hidden_size: int=64, dropout: float=0.2, res_connection: bool=True, bias: bool=True, activation: str='relu'):
        super(GroverTransEncoder, self).__init__()
        self.hidden_size = hidden_size
        self.edge_fdim = edge_fdim
        self.node_fdim = node_fdim
        self.edge_blocks = nn.ModuleList()
        self.node_blocks = nn.ModuleList()
        for i in range(num_mt_block):
            if i == 0:
                node_input_fdim, edge_input_fdim = (node_fdim, edge_fdim)
            else:
                node_input_fdim, edge_input_fdim = (hidden_size, hidden_size)
            self.edge_blocks.append(GroverMTBlock(num_heads=num_heads, input_dim=edge_input_fdim, hidden_size=hidden_size, activation=activation, dropout=dropout, bias=bias, atom_messages=False, res_connection=res_connection, depth=depth, undirected=undirected))
            self.node_blocks.append(GroverMTBlock(num_heads=num_heads, input_dim=node_input_fdim, hidden_size=hidden_size, activation=activation, dropout=dropout, bias=bias, atom_messages=True, res_connection=res_connection, depth=depth, undirected=undirected))
        self.ffn_atom_from_atom = PositionwiseFeedForward(d_input=self.hidden_size + node_fdim, d_hidden=self.hidden_size * 4, d_output=self.hidden_size, n_layers=2, activation=activation, dropout_p=dropout)
        self.ffn_atom_from_bond = PositionwiseFeedForward(d_input=self.hidden_size + node_fdim, d_hidden=self.hidden_size * 4, d_output=self.hidden_size, n_layers=2, activation=activation, dropout_p=dropout)
        self.ffn_bond_from_atom = PositionwiseFeedForward(d_input=self.hidden_size + edge_fdim, d_hidden=self.hidden_size * 4, d_output=self.hidden_size, n_layers=2, activation=activation, dropout_p=dropout)
        self.ffn_bond_from_bond = PositionwiseFeedForward(d_input=self.hidden_size + edge_fdim, d_hidden=self.hidden_size * 4, d_output=self.hidden_size, n_layers=2, activation=activation, dropout_p=dropout)
        self.atom_from_atom_sublayer = SublayerConnection(size=self.hidden_size, dropout_p=dropout)
        self.atom_from_bond_sublayer = SublayerConnection(size=self.hidden_size, dropout_p=dropout)
        self.bond_from_atom_sublayer = SublayerConnection(size=self.hidden_size, dropout_p=dropout)
        self.bond_from_bond_sublayer = SublayerConnection(size=self.hidden_size, dropout_p=dropout)
        if activation == 'relu':
            self.act_func_node = nn.ReLU()
            self.act_func_edge = nn.ReLU()
        else:
            raise ValueError('Only relu activation is supported')
        self.dropout_layer = nn.Dropout(p=dropout)

    def _pointwise_feed_forward_to_atom_embedding(self, emb_output, atom_feat, index, ffn_layer):
        aggr_output = _select_neighbor_and_aggregate(emb_output, index)
        aggr_outputx = torch.cat([atom_feat, aggr_output], dim=1)
        return (ffn_layer(aggr_outputx), aggr_outputx)

    def _pointwise_feed_forward_to_bond_embedding(self, emb_output, bond_feat, a2nei, b2revb, ffn_layer):
        aggr_output = _select_neighbor_and_aggregate(emb_output, a2nei)
        aggr_output = self._remove_rev_bond_message(emb_output, aggr_output, b2revb)
        aggr_outputx = torch.cat([bond_feat, aggr_output], dim=1)
        return (ffn_layer(aggr_outputx), aggr_outputx)

    @staticmethod
    def _remove_rev_bond_message(original_message, aggr_message, b2revb):
        rev_message = original_message[b2revb]
        return aggr_message - rev_message

    def _atom_bond_transform(self, to_atom=True, atomwise_input=None, bondwise_input=None, original_f_atoms=None, original_f_bonds=None, a2a=None, a2b=None, b2a=None, b2revb=None):
        if to_atom:
            atomwise_input, _ = self._pointwise_feed_forward_to_atom_embedding(atomwise_input, original_f_atoms, a2a, self.ffn_atom_from_atom)
            atom_in_atom_out = self.atom_from_atom_sublayer(None, atomwise_input)
            bondwise_input, _ = self._pointwise_feed_forward_to_atom_embedding(bondwise_input, original_f_atoms, a2b, self.ffn_atom_from_bond)
            bond_in_atom_out = self.atom_from_bond_sublayer(None, bondwise_input)
            return (atom_in_atom_out, bond_in_atom_out)
        else:
            atom_list_for_bond = torch.cat([b2a.unsqueeze(dim=1), a2a[b2a]], dim=1)
            atomwise_input, _ = self._pointwise_feed_forward_to_bond_embedding(atomwise_input, original_f_bonds, atom_list_for_bond, b2a[b2revb], self.ffn_bond_from_atom)
            atom_in_bond_out = self.bond_from_atom_sublayer(None, atomwise_input)
            bond_list_for_bond = a2b[b2a]
            bondwise_input, _ = self._pointwise_feed_forward_to_bond_embedding(bondwise_input, original_f_bonds, bond_list_for_bond, b2revb, self.ffn_bond_from_bond)
            bond_in_bond_out = self.bond_from_bond_sublayer(None, bondwise_input)
            return (atom_in_bond_out, bond_in_bond_out)

    def forward(self, batch):
        f_atoms, f_bonds, a2b, b2a, b2revb, a_scope, b_scope, a2a = batch
        node_batch = (f_atoms, f_bonds, a2b, b2a, b2revb, a_scope, b_scope, a2a)
        edge_batch = (f_atoms, f_bonds, a2b, b2a, b2revb, a_scope, b_scope, a2a)
        original_f_atoms, original_f_bonds = (f_atoms, f_bonds)
        for nb in self.node_blocks:
            node_batch = nb(node_batch)
        for eb in self.edge_blocks:
            edge_batch = eb(edge_batch)
        atom_output, _, _, _, _, _, _, _ = node_batch
        _, bond_output, _, _, _, _, _, _ = edge_batch
        atom_embeddings = self._atom_bond_transform(to_atom=True, atomwise_input=atom_output, bondwise_input=bond_output, original_f_atoms=original_f_atoms, original_f_bonds=original_f_bonds, a2a=a2a, a2b=a2b, b2a=b2a, b2revb=b2revb)
        bond_embeddings = self._atom_bond_transform(to_atom=False, atomwise_input=atom_output, bondwise_input=bond_output, original_f_atoms=original_f_atoms, original_f_bonds=original_f_bonds, a2a=a2a, a2b=a2b, b2a=b2a, b2revb=b2revb)
        return ((atom_embeddings[0], bond_embeddings[0]), (atom_embeddings[1], bond_embeddings[1]))

class GroverAttentionHead(nn.Module):

    def __init__(self, hidden_size: int=128, bias: bool=True, depth: int=1, dropout: float=0.0, undirected: bool=False, atom_messages: bool=False):
        super(GroverAttentionHead, self).__init__()
        self.atom_messages = atom_messages
        self.mpn_q = GroverMPNEncoder(atom_messages=atom_messages, init_message_dim=hidden_size, attached_feat_fdim=hidden_size, hidden_size=hidden_size, bias=bias, depth=depth, dropout=dropout, undirected=undirected, attach_feats=False, input_layer='none', dynamic_depth='truncnorm')
        self.mpn_k = GroverMPNEncoder(atom_messages=atom_messages, init_message_dim=hidden_size, attached_feat_fdim=hidden_size, hidden_size=hidden_size, bias=bias, depth=depth, dropout=dropout, undirected=undirected, attach_feats=False, input_layer='none', dynamic_depth='truncnorm')
        self.mpn_v = GroverMPNEncoder(atom_messages=atom_messages, init_message_dim=hidden_size, attached_feat_fdim=hidden_size, hidden_size=hidden_size, bias=bias, depth=depth, dropout=dropout, undirected=undirected, attach_feats=False, input_layer='none', dynamic_depth='truncnorm')

    def forward(self, f_atoms, f_bonds, a2b, a2a, b2a, b2revb):
        if self.atom_messages:
            init_messages = f_atoms
            init_attached_features = f_bonds
            a2nei = a2a
            a2attached = a2b
            b2a = b2a
            b2revb = b2revb
        else:
            init_messages = f_bonds
            init_attached_features = f_atoms
            a2nei = a2b
            a2attached = a2a
            b2a = b2a
            b2revb = b2revb
        q = self.mpn_q(init_messages=init_messages, init_attached_features=init_attached_features, a2nei=a2nei, a2attached=a2attached, b2a=b2a, b2revb=b2revb)
        k = self.mpn_k(init_messages=init_messages, init_attached_features=init_attached_features, a2nei=a2nei, a2attached=a2attached, b2a=b2a, b2revb=b2revb)
        v = self.mpn_v(init_messages=init_messages, init_attached_features=init_attached_features, a2nei=a2nei, a2attached=a2attached, b2a=b2a, b2revb=b2revb)
        return (q, k, v)

