        return self.fc2(F.relu(self.fc1(y)))

class InfoGraphStar(torch.nn.Module):

    def __init__(self, encoder, unsup_encoder, ff1, ff2, fc1, fc2, local_d, global_d, mode='regression', num_tasks=1, num_classes=2, init_emb=False):
        super().__init__()
        self.encoder = encoder
        self.unsup_encoder = unsup_encoder
        self.ff1 = ff1
        self.ff2 = ff2
        self.fc1 = fc1
        self.fc2 = fc2
        self.local_d = local_d
        self.global_d = global_d
        self.mode = mode
        self.num_tasks = num_tasks
        self.num_classes = num_classes
        if init_emb:
            self.init_emb()

    def init_emb(self):
        for m in self.modules():
            if isinstance(m, nn.Linear):
                torch.nn.init.xavier_uniform_(m.weight.data)
                if m.bias is not None:
                    m.bias.data.fill_(0.0)

    def forward(self, data):
        out, M = self.encoder(data)
        out = F.relu(self.fc1(out))
        pred = self.fc2(out)
