            pred = torch.reshape(pred, (-1, self.num_tasks, self.num_classes))
        return pred

class GroverReadout(nn.Module):

    def __init__(self, rtype: str='mean', in_features: int=128, attn_hidden_size: int=32, attn_out_size: int=32):
        super(GroverReadout, self).__init__()
        self.cached_zero_vector = nn.Parameter(torch.zeros(in_features), requires_grad=False)
        self.rtype = rtype
        if rtype == 'self_attention':
            self.attn = SelfAttention(hidden_size=attn_hidden_size, in_features=in_features, out_features=attn_out_size)

    def forward(self, graph_embeddings: torch.Tensor, scope: List[List]) -> torch.Tensor:
        embeddings: List[torch.Tensor] = []
        for _, (a_start, a_size) in enumerate(scope):
            if a_size == 0:
                embeddings.append(self.cached_zero_vector)
            else:
                embedding = graph_embeddings.narrow(0, a_start, a_size)
                if self.rtype == 'self_attention':
                    embedding, attn = self.attn(embedding)
                    embedding = embedding.flatten()
                elif self.rtype == 'mean':
                    embedding = embedding.sum(dim=0) / a_size
                embeddings.append(embedding)
        graph_embeddings = torch.stack(embeddings, dim=0)
        return graph_embeddings

class MultilayerPerceptron(nn.Module):

    def __init__(self, d_input: int, d_output: int, d_hidden: Optional[tuple]=None, dropout: float=0.0, batch_norm: bool=False, batch_norm_momentum: float=0.1, activation_fn: Union[Callable, str]='relu', skip_connection: bool=False, weighted_skip: bool=True):
        super(MultilayerPerceptron, self).__init__()
        self.d_input = d_input
        self.d_hidden = d_hidden
        self.d_output = d_output
        self.dropout = nn.Dropout(dropout)
        self.batch_norm = batch_norm
        self.batch_norm_momentum = batch_norm_momentum
        self.activation_fn = get_activation(activation_fn)
        self.model = nn.Sequential(*self.build_layers())
        self.skip = nn.Linear(d_input, d_output) if skip_connection else None
        self.weighted_skip = weighted_skip

    def build_layers(self):
        layer_list = []
        layer_dim = self.d_input
        if self.d_hidden is not None:
            for d in self.d_hidden:
                layer_list.append(nn.Linear(layer_dim, d))
                layer_list.append(self.dropout)
                if self.batch_norm:
                    layer_list.append(nn.BatchNorm1d(d, momentum=self.batch_norm_momentum))
                layer_dim = d
        layer_list.append(nn.Linear(layer_dim, self.d_output))
        return layer_list

    def forward(self, x: Tensor) -> Tensor:
        input = x
        for layer in self.model:
            x = layer(x)
            if isinstance(layer, nn.Linear):
                x = self.activation_fn(x)
        if self.skip is not None:
            if not self.weighted_skip:
                return x + input
            else:
                return x + self.skip(input)
        else:
            return x

class SeqToSeqModel(TorchModel):
    sequence_end = object()

    def __init__(self, input_tokens: List, output_tokens: List, max_output_length: int, encoder_layers: int=4, decoder_layers: int=4, batch_size: int=100, embedding_dimension: int=512, dropout: float=0.0, reverse_input: bool=True, variational: bool=False, annealing_start_step: int=5000, annealing_final_step: int=10000, **kwargs):
