        self._n_output_tokens = len(output_tokens)
        self._max_output_length = max_output_length
        self.batch_size = batch_size
        self._embedding_dimension = embedding_dimension
        self._dropout = dropout
        self._reverse_input = reverse_input
        self._variational = variational
        self._annealing_start_step = annealing_start_step
        self._annealing_final_step = annealing_final_step
        self.model: nn.Module = SeqToSeq(n_input_tokens=self._n_input_tokens, n_output_tokens=self._n_output_tokens, max_output_length=self._max_output_length, encoder_layers=encoder_layers, decoder_layers=decoder_layers, batch_size=self.batch_size, embedding_dimension=self._embedding_dimension, dropout=self._dropout, variational=self._variational, annealing_start_step=self._annealing_start_step, annealing_final_step=self._annealing_final_step)
        super(SeqToSeqModel, self).__init__(self.model, self._create_loss(), output_types=['prediction', 'embedding'], batch_size=self.batch_size, **kwargs)

    def _create_loss(self):
        if self._variational:
            loss = sum(self.model.randomizer.loss_list)
        else:
            loss = torch.tensor(0.0)

        def loss_fn(outputs, labels, weights):
            output = outputs[0].view(-1, outputs[0].size(-1))
            target = labels[0].view(-1)
            loss_ = nn.NLLLoss()(torch.log(output.to(torch.float32)), target.to(torch.int64))
            return loss + loss_
        return loss_fn

    def fit_sequences(self, sequences: List[str], max_checkpoints_to_keep: int=5, checkpoint_interval: int=1000, restore: bool=False):
        loss = self.fit_generator(self._generate_batches(sequences), max_checkpoints_to_keep=max_checkpoints_to_keep, checkpoint_interval=checkpoint_interval, restore=restore)
        return loss

    def predict_from_sequences(self, sequences: List[str], beam_width=5):
        result = []
        for batch in batch_elements(sequences, self.batch_size):
            features = create_input_array(batch, self._max_output_length, self._reverse_input, self.batch_size, self._input_dict, SeqToSeqModel.sequence_end)
            probs = self.predict_on_generator([((features, np.array(self.get_global_step())), None, None)])
            for i in range(len(batch)):
                result.append(self._beam_search(probs[i], beam_width))
        return result

    def predict_embedding(self, sequences: List[str]):
        result = []
        for batch in batch_elements(sequences, self.batch_size):
            features = create_input_array(batch, self._max_output_length, self._reverse_input, self.batch_size, self._input_dict, SeqToSeqModel.sequence_end)
            probs = self.predict_on_generator([((features, np.array(self.get_global_step())), None, None)], output_types=['embedding'])
            for i in range(len(batch)):
                result.append(probs[i])
        return result

    def predict_from_embedding(self, embeddings: List[np.ndarray], beam_width=5):
        result = []
        for batch in batch_elements(embeddings, self.batch_size):
            embedding_array = np.zeros((self.batch_size, self._embedding_dimension), dtype=np.float32)
            for i, e in enumerate(batch):
                embedding_array[i] = e
            probs, _ = self.model.decoder([torch.tensor(embedding_array, device=self.device), None])
            probs = probs.cpu().detach().numpy()
            for i in range(len(batch)):
                result.append(self._beam_search(probs[i], beam_width))
        return result

    def _beam_search(self, probs: np.ndarray, beam_width: int):
        if beam_width == 1:
            s = []
            for i in range(len(probs)):
                token = self._output_tokens[np.argmax(probs[i])]
                if token == SeqToSeqModel.sequence_end:
                    break
                s.append(token)
            return s
        logprobs = np.log(probs)
        candidates: List = [(0.0, 0.0, [])]
        for i in range(len(logprobs)):
            new_candidates: List = []
            for c in candidates:
                if len(c[2]) > 0 and c[2][-1] == SeqToSeqModel.sequence_end:
                    if len(new_candidates) < beam_width:
                        heappush(new_candidates, c)
                    else:
                        heappushpop(new_candidates, c)
                else:
                    for j, logprob in enumerate(logprobs[i]):
                        new_logprob = logprob + c[1]
                        newc = (new_logprob / (len(c[2]) + 1), new_logprob, c[2] + [self._output_tokens[j]])
                        if len(new_candidates) < beam_width:
                            heappush(new_candidates, newc)
                        else:
                            heappushpop(new_candidates, newc)
            candidates = new_candidates
        return sorted(candidates)[-1][2][:-1]

    def _generate_batches(self, sequences: List[str]):
        for batch in batch_elements(sequences, self.batch_size):
            inputs = []
            outputs = []
            for input, output in batch:
                inputs.append(input)
                outputs.append(output)
            for i in range(len(inputs), self.batch_size):
                inputs.append([])
                outputs.append([])
            features = create_input_array(inputs, self._max_output_length, self._reverse_input, self.batch_size, self._input_dict, SeqToSeqModel.sequence_end)
            labels = create_output_array(outputs, self._max_output_length, self.batch_size, self._output_dict, SeqToSeqModel.sequence_end)
            yield ([features, np.array(self.get_global_step())], [labels], [])

# --- helper: deepchem.models.torch_models.seqtoseq.SeqToSeq ---
class SeqToSeq(nn.Module):

    def __init__(self, n_input_tokens: int, n_output_tokens: int, max_output_length: int, encoder_layers: int=4, decoder_layers: int=4, batch_size: int=100, embedding_dimension: int=512, dropout: float=0.0, variational: bool=False, annealing_start_step: int=5000, annealing_final_step: int=10000):
        super(SeqToSeq, self).__init__()
        self._variational = variational
        self.encoder = EncoderRNN(n_input_tokens, embedding_dimension, encoder_layers, dropout)
        self.decoder = DecoderRNN(embedding_dimension, n_output_tokens, decoder_layers, max_output_length, batch_size)
        if variational:
            self.randomizer = VariationalRandomizer(embedding_dimension, annealing_start_step, annealing_final_step)

    def forward(self, inputs: List):
        input, global_step = inputs
        _, embedding = self.encoder(input.to(torch.long))
        self.encoder.training = False
        _, self._embedding = self.encoder(input.to(torch.long))
        self.encoder.training = True
        if self._variational:
            embedding = self.randomizer([self._embedding, global_step])
            self._embedding = self.randomizer([self._embedding, global_step], training=False)
        output, _ = self.decoder([embedding, None])
        return (output, self._embedding)

