class ValGrad:

    def __init__(self, value: torch.Tensor, grad: Optional[torch.Tensor]=None, lapl: Optional[torch.Tensor]=None, kin: Optional[torch.Tensor]=None):
        self.value = value
        self.grad = grad
        self.lapl = lapl
        self.kin = kin

    def __add__(self, b):
        return ValGrad(value=self.value + b.value, grad=self.grad + b.grad if self.grad is not None else None, lapl=self.lapl + b.lapl if self.lapl is not None else None, kin=self.kin + b.kin if self.kin is not None else None)

    def __mul__(self, f: Union[float, int, torch.Tensor]):
        if isinstance(f, torch.Tensor):
            assert f.numel() == 1, 'ValGrad multiplication with tensor can only be done with 1-element tensor'
        return ValGrad(value=self.value * f, grad=self.grad * f if self.grad is not None else None, lapl=self.lapl * f if self.lapl is not None else None, kin=self.kin * f if self.kin is not None else None)

    def __repr__(self):
        return f'ValGrad(value={self.value}, grad={self.grad}, lapl={self.lapl}, kin={self.kin})'

