# --- helper: deepchem.utils.dft_utils.grid.radial_grid.get_grid_transform ---
def get_grid_transform(s0: Union[str, BaseGridTransform]) -> BaseGridTransform:
    if isinstance(s0, BaseGridTransform):
        return s0
    else:
        s = s0.lower()
        if s == 'logm3':
            return LogM3Transformation()
        elif s == 'de2':
            return DE2Transformation()
        elif s == 'treutlerm4':
            return TreutlerM4Transformation()
        else:
            raise RuntimeError('Unknown grid transformation: %s' % s0)

# --- helper: deepchem.utils.dft_utils.grid.radial_grid.get_xw_integration ---
def get_xw_integration(n: int, s0: str) -> Tuple[np.ndarray, np.ndarray]:
    s = s0.lower()
    if s == 'chebyshev':
        np1 = n + 1.0
        icount = np.arange(n, 0, -1)
        ipn1 = icount * np.pi / np1
        sin_ipn1 = np.sin(ipn1)
        sin_ipn1_2 = sin_ipn1 * sin_ipn1
        xcheb = (np1 - 2 * icount) / np1 + 2 / np.pi * (1 + 2.0 / 3 * sin_ipn1 * sin_ipn1) * np.cos(ipn1) * sin_ipn1
        wcheb = 16.0 / (3 * np1) * sin_ipn1_2 * sin_ipn1_2
        return (xcheb, wcheb)
    elif s == 'chebyshev2':
        np1 = n + 1.0
        icount = np.arange(n, 0, -1)
        ipn1 = icount * np.pi / np1
        sin_ipn1 = np.sin(ipn1)
        xcheb = np.cos(ipn1)
        wcheb = np.pi / np1 * sin_ipn1
        return (xcheb, wcheb)
    elif s == 'uniform':
        x = np.linspace(-1, 1, n)
        w = np.ones(n) * (x[1] - x[0])
        w[0] *= 0.5
        w[-1] *= 0.5
        return (x, w)
    else:
        avail = ['chebyshev', 'chebyshev2', 'uniform']
        raise RuntimeError('Unknown grid_integrator: %s. Available: %s' % (s0, avail))

class TreutlerM4Transformation(BaseGridTransform):

    def __init__(self, xi: float=1.0, alpha: float=0.6, eps: float=1e-15):
        self._xi = xi
        self._alpha = alpha
        self._ln2 = np.log(2.0 + eps)
        self._eps = eps

    def x2r(self, x: torch.Tensor) -> torch.Tensor:
        a = 1.0 + self._eps
        r = self._xi / self._ln2 * (a + x) ** self._alpha * (self._ln2 - torch.log1p(-x + self._eps))
        return r

    def get_drdx(self, x: torch.Tensor) -> torch.Tensor:
        a = 1.0 + self._eps
        fac = self._xi / self._ln2 * (a + x) ** self._alpha
        r1 = fac / (1 - x + self._eps)
        r2 = fac * self._alpha / (a + x) * (self._ln2 - torch.log1p(-x + self._eps))
        return r2 + r1

# --- helper: deepchem.utils.dft_utils.grid.radial_grid.BaseGridTransform ---
class BaseGridTransform(object):

    @abstractmethod
