def get_grid_transform(s0: Union[str, BaseGridTransform]) -> BaseGridTransform:
    if isinstance(s0, BaseGridTransform):
        return s0
    else:
        s = s0.lower()
        if s == 'logm3':
            return LogM3Transformation()
        elif s == 'de2':
