# --- helper: deepchem.utils.dft_utils.grid.radial_grid.BaseGridTransform ---
class BaseGridTransform(object):

    @abstractmethod
    def x2r(self, x: torch.Tensor) -> torch.Tensor:
        pass

    @abstractmethod
    def get_drdx(self, x: torch.Tensor) -> torch.Tensor:
        pass

# --- helper: deepchem.utils.dft_utils.grid.radial_grid.DE2Transformation ---
class DE2Transformation(BaseGridTransform):

    def __init__(self, alpha: float=1.0, rmin: float=1e-07, rmax: float=20):
        assert rmin < 1.0
        self.alpha = alpha
        self.xmin = -np.log(-np.log(rmin))
        self.xmax = np.log(rmax) / alpha

    def x2r(self, x: torch.Tensor) -> torch.Tensor:
        xnew = 0.5 * (x * (self.xmax - self.xmin) + (self.xmax + self.xmin))
        r = torch.exp(self.alpha * xnew - torch.exp(-xnew))
        return r

    def get_drdx(self, x: torch.Tensor) -> torch.Tensor:
        r = self.x2r(x)
        xnew = 0.5 * (x * (self.xmax - self.xmin) + (self.xmax + self.xmin))
        return r * (self.alpha + torch.exp(-xnew)) * (0.5 * (self.xmax - self.xmin))

# --- helper: deepchem.utils.dft_utils.grid.radial_grid.LogM3Transformation ---
class LogM3Transformation(BaseGridTransform):

    def __init__(self, ra: float=1.0, eps: float=1e-15):
        self.ra = ra
        self.eps = eps
        self.ln2 = np.log(2.0 + eps)

    def x2r(self, x: torch.Tensor) -> torch.Tensor:
        return self.ra * (1 - torch.log1p(-x + self.eps) / self.ln2)

    def get_drdx(self, x: torch.Tensor) -> torch.Tensor:
        return self.ra / self.ln2 / (1 - x + self.eps)

# --- helper: deepchem.utils.dft_utils.grid.radial_grid.TreutlerM4Transformation ---
class TreutlerM4Transformation(BaseGridTransform):

    def __init__(self, xi: float=1.0, alpha: float=0.6, eps: float=1e-15):
        self._xi = xi
        self._alpha = alpha
        self._ln2 = np.log(2.0 + eps)
        self._eps = eps

    def x2r(self, x: torch.Tensor) -> torch.Tensor:
        a = 1.0 + self._eps
        r = self._xi / self._ln2 * (a + x) ** self._alpha * (self._ln2 - torch.log1p(-x + self._eps))
        return r

    def get_drdx(self, x: torch.Tensor) -> torch.Tensor:
        a = 1.0 + self._eps
        fac = self._xi / self._ln2 * (a + x) ** self._alpha
        r1 = fac / (1 - x + self._eps)
        r2 = fac * self._alpha / (a + x) * (self._ln2 - torch.log1p(-x + self._eps))
        return r2 + r1

class Lattice(object):

    def __init__(self, a: torch.Tensor):
        assert a.ndim == 2
        assert a.shape[0] == 3
        assert a.shape[-1] == 3
        self.ndim = a.shape[0]
        self.a = a
        self.device = a.device
        self.dtype = a.dtype

    def lattice_vectors(self) -> torch.Tensor:
        return self.a

    def recip_vectors(self) -> torch.Tensor:
        return torch.inverse(self.a.transpose(-2, -1)) * (2 * np.pi)

    def volume(self) -> torch.Tensor:
        return torch.det(self.a)

    @property
    def params(self) -> Tuple[torch.Tensor, ...]:
        return (self.a,)

    def get_lattice_ls(self, rcut: float, exclude_zeros: bool=False) -> torch.Tensor:
        a = self.lattice_vectors()
        return self._generate_lattice_vectors(a, rcut, exclude_zeros=exclude_zeros)

    def get_gvgrids(self, gcut: float, exclude_zeros: bool=False) -> Tuple[torch.Tensor, torch.Tensor]:
        b = self.recip_vectors()
        gvgrids = self._generate_lattice_vectors(b, gcut, exclude_zeros=exclude_zeros)
        weights = torch.zeros(gvgrids.shape[0], dtype=self.dtype, device=self.device)
        weights = weights + torch.abs(torch.det(b)) / (2 * np.pi) ** 3
        return (gvgrids, weights)

    def estimate_ewald_eta(self, precision: float) -> float:
        vol = float(self.volume().detach())
        eta0 = np.sqrt(np.pi) / vol ** (1.0 / 3)
        eta = eta0 * erfcinv(0.5 * precision) / erfcinv(precision)
        return round(eta * 10) / 10

    def _generate_lattice_vectors(self, a: torch.Tensor, rcut: float, exclude_zeros: bool) -> torch.Tensor:
        b = torch.inverse(a.transpose(-2, -1))
        heights_inv = torch.norm(b, dim=-1).detach().numpy()
        nimgs = (rcut * heights_inv + 1.1).astype(np.int32)
        n1_0 = torch.arange(-nimgs[0], nimgs[0] + 1, dtype=torch.int32, device=self.device)
        n1_1 = torch.arange(-nimgs[1], nimgs[1] + 1, dtype=torch.int32, device=self.device)
        n1_2 = torch.arange(-nimgs[2], nimgs[2] + 1, dtype=torch.int32, device=self.device)
        ls = n1_2[:, None] * a[0, :]
        ls = ls + n1_1[:, None, None] * a[1, :]
        ls = ls + n1_0[:, None, None, None] * a[2, :]
        ls = ls.view(-1, ls.shape[-1])
        ls = ls[ls.norm(dim=-1) <= rcut * 1.05, :]
        if exclude_zeros:
            ls = ls[torch.any(ls != 0, dim=-1), :]
        return ls

