class AddBaseXC(BaseXC):

    def __init__(self, a: BaseXC, b: BaseXC) -> None:
        self.a = a
        self.b = b
        self._family = max(a.family, b.family)

    @property
    def family(self):
        return self._family

    def get_vxc(self, densinfo: Union[ValGrad, SpinParam[ValGrad]]) -> Union[ValGrad, SpinParam[ValGrad]]:
        avxc = self.a.get_vxc(densinfo)
        bvxc = self.b.get_vxc(densinfo)
        if isinstance(densinfo, ValGrad):
            return avxc + bvxc
        else:
            return SpinParam(u=avxc.u + bvxc.u, d=avxc.d + bvxc.d)

    def get_edensityxc(self, densinfo: Union[ValGrad, SpinParam[ValGrad]]) -> torch.Tensor:
        return self.a.get_edensityxc(densinfo) + self.b.get_edensityxc(densinfo)

    def getparamnames(self, methodname: str, prefix: str='') -> List[str]:
        return self.a.getparamnames(methodname, prefix=prefix + 'a.') + self.b.getparamnames(methodname, prefix=prefix + 'b.')

# --- helper: deepchem.utils.dft_utils.xc.base_xc.BaseXC ---
class BaseXC(EditableModule):

    @abstractproperty
    def family(self) -> int:
        pass

    @abstractmethod
    def get_edensityxc(self, densinfo: Union[ValGrad, SpinParam[ValGrad]]) -> torch.Tensor:
        pass

    def get_vxc(self, densinfo: Union[ValGrad, SpinParam[ValGrad]]):
        with self._enable_grad_densinfo(densinfo):
            with torch.enable_grad():
                edensity = self.get_edensityxc(densinfo)
            grad_outputs = torch.ones_like(edensity)
            grad_enabled = torch.is_grad_enabled()
            if not isinstance(densinfo, ValGrad):
                if self.family == 1:
                    params = (densinfo.u.value, densinfo.d.value)
                    dedn_u, dedn_d = torch.autograd.grad(edensity, params, create_graph=grad_enabled, grad_outputs=grad_outputs)
                    return SpinParam(u=ValGrad(value=dedn_u), d=ValGrad(value=dedn_d))
                elif self.family == 2:
                    params = (densinfo.u.value, densinfo.d.value, densinfo.u.grad, densinfo.d.grad)
                    dedn_u, dedn_d, dedg_u, dedg_d = torch.autograd.grad(edensity, params, create_graph=grad_enabled, grad_outputs=grad_outputs)
                    return SpinParam(u=ValGrad(value=dedn_u, grad=dedg_u), d=ValGrad(value=dedn_d, grad=dedg_d))
                elif self.family == 4:
                    params = (densinfo.u.value, densinfo.d.value, densinfo.u.grad, densinfo.d.grad, densinfo.u.lapl, densinfo.d.lapl, densinfo.u.kin, densinfo.d.kin)
                    dedn_u, dedn_d, dedg_u, dedg_d, dedl_u, dedl_d, dedk_u, dedk_d = torch.autograd.grad(edensity, params, create_graph=grad_enabled, grad_outputs=grad_outputs, allow_unused=True)
                    dedl_u = dedl_u if dedl_u is not None else torch.zeros_like(dedn_u)
                    dedk_u = dedk_u if dedk_u is not None else torch.zeros_like(dedn_u)
                    dedl_d = dedl_d if dedl_d is not None else torch.zeros_like(dedn_d)
                    dedk_d = dedk_d if dedk_d is not None else torch.zeros_like(dedn_d)
                    return SpinParam(u=ValGrad(value=dedn_u, grad=dedg_u, lapl=dedl_u, kin=dedk_u), d=ValGrad(value=dedn_d, grad=dedg_d, lapl=dedl_d, kin=dedk_d))
                else:
                    raise NotImplementedError('Default polarized vxc for family %s is not implemented' % self.family)
            elif self.family == 1:
                dedn, = torch.autograd.grad(edensity, densinfo.value, create_graph=grad_enabled, grad_outputs=grad_outputs)
                return ValGrad(value=dedn)
            elif self.family == 2:
                assert densinfo.grad is not None
                dedn, dedg = torch.autograd.grad(edensity, [densinfo.value, densinfo.grad], create_graph=grad_enabled, grad_outputs=grad_outputs)
                return ValGrad(value=dedn, grad=dedg)
            elif self.family == 4:
                assert densinfo.grad is not None
                assert densinfo.lapl is not None
                assert densinfo.kin is not None
                dedn, dedg, dedl, dedk = torch.autograd.grad(edensity, [densinfo.value, densinfo.grad, densinfo.lapl, densinfo.kin], create_graph=grad_enabled, grad_outputs=grad_outputs, allow_unused=True)
                dedl = dedl if dedl is not None else torch.zeros_like(dedn)
                dedk = dedk if dedk is not None else torch.zeros_like(dedn)
                return ValGrad(value=dedn, grad=dedg, lapl=dedl, kin=dedk)
            else:
                raise NotImplementedError('Default vxc for family %d is not implemented' % self.family)

    def getparamnames(self, methodname: str, prefix: str='') -> List[str]:
        if methodname == 'get_vxc':
            return self.getparamnames('get_edensityxc', prefix=prefix)
        else:
            raise KeyError('Unknown methodname: %s' % methodname)

    @contextmanager
    def _enable_grad_densinfo(self, densinfo: Union[ValGrad, SpinParam[ValGrad]]) -> Iterator:

        def _get_set_grad(vars: List[torch.Tensor]) -> List[bool]:
            reqgrads = []
            for var in vars:
                reqgrads.append(var.requires_grad)
                var.requires_grad_()
            return reqgrads

        def _restore_grad(reqgrads: List[bool], vars: List[torch.Tensor]) -> None:
            for reqgrad, var in zip(reqgrads, vars):
                if not reqgrad:
                    var.requires_grad_(False)
        if not isinstance(densinfo, ValGrad):
            params = [densinfo.u.value, densinfo.d.value]
            if self.family >= 2:
                assert densinfo.u.grad is not None
                assert densinfo.d.grad is not None
                params.extend([densinfo.u.grad, densinfo.d.grad])
            if self.family >= 3:
                assert densinfo.u.lapl is not None
                assert densinfo.d.lapl is not None
                assert densinfo.u.kin is not None
                assert densinfo.d.kin is not None
                params.extend([densinfo.u.lapl, densinfo.d.lapl, densinfo.u.kin, densinfo.d.kin])
        else:
            params = [densinfo.value]
            if self.family >= 2:
                assert densinfo.grad is not None
                params.append(densinfo.grad)
            if self.family >= 3:
                assert densinfo.lapl is not None
                assert densinfo.kin is not None
                params.extend([densinfo.lapl, densinfo.kin])
        try:
            reqgrads = _get_set_grad(params)
            yield
        finally:
            _restore_grad(reqgrads, params)

    def __add__(self, other: Any) -> Any:
        return AddBaseXC(self, other)

    def __mul__(self, other: Union[float, int, torch.Tensor]):
        if isinstance(other, float) or isinstance(other, int):
            return MulBaseXC(self, float(other))
        elif isinstance(other, torch.Tensor):
            return MulBaseXC(self, other)
        else:
            raise ValueError('BaseXC can only be multiplied with float or tensor')

    def __rmul__(self, other: Union[float, int, torch.Tensor]):
        return self.__mul__(other)

