def get_method(algname: str, methods: Mapping[str, Callable], method: Union[str, Callable]) -> Callable:
    if isinstance(method, str):
        methodname = method.lower()
        if methodname in methods:
            return methods[methodname]
        else:
            raise RuntimeError('Unknown %s method: %s' % (algname, method))
    elif hasattr(method, '__call__'):
        return method
    elif method is None:
        assert False, 'Internal assert failed, method in get_method is not supposedto be None. If this shows, then the corresponding function fails to set the default method'
    else:
        raise TypeError('Invalid method type: %s. Only str and callable are accepted.' % type(method))

class BroydenSecond(BroydenFirst):

    def _update(self, x: torch.Tensor, y: torch.Tensor, dx: torch.Tensor, dy: torch.Tensor, dxnorm: torch.Tensor, dynorm: torch.Tensor):
        self._reduce()
        v = dy
        c = dx - self.Gm.mv(dy)
        d = v / (dynorm * dynorm)
        self.Gm = self.Gm.append(c, d)

