def _nonlin_solver(fcn: Callable, x0: torch.Tensor, params, method: str, alpha=None, uv0=None, max_rank=None, maxiter=None, f_tol=None, f_rtol=None, x_tol=None, x_rtol=None, line_search=True, verbose=False, custom_terminator=None, **unused):
    if method == 'broyden1':
        jacobian = BroydenFirst(alpha=alpha, uv0=uv0, max_rank=max_rank)
    elif method == 'broyden2':
        jacobian = BroydenSecond(alpha=alpha, uv0=uv0, max_rank=max_rank)
    elif method == 'linearmixing':
        jacobian = LinearMixing(alpha=alpha)
    else:
        raise RuntimeError('Unknown method: %s' % method)
    if maxiter is None:
        maxiter = 100 * (torch.numel(x0) + 1)
    if line_search is True:
        line_search = 'armijo'
    elif line_search is False:
        line_search = None
    x_is_complex = torch.is_complex(x0)

    def _ravel(x: torch.Tensor) -> torch.Tensor:
        if x_is_complex:
            return torch.cat((x.real, x.imag), dim=0).reshape(-1)
        else:
            return x.reshape(-1)

    def _pack(x: torch.Tensor) -> torch.Tensor:
        if x_is_complex:
            n = len(x) // 2
            xreal, ximag = (x[:n], x[n:])
            x = xreal + 1j * ximag
        return x.reshape(xshape)
    xshape = x0.shape

    def func(x):
        return _ravel(fcn(_pack(x), *params))
    x = _ravel(x0)
    y = func(x)
    y_norm = y.norm()
    stop_cond = custom_terminator if custom_terminator is not None else TerminationCondition(f_tol, f_rtol, y_norm, x_tol, x_rtol)
    if y_norm == 0:
        return x.reshape(xshape)
    jacobian.setup(x, y, func)
    gamma = 0.9
    eta_max = 0.9999
    eta_threshold = 0.1
    eta = 0.001
    converge = False
    best_ynorm = y_norm
    best_x = x
    best_dxnorm = x.norm()
    best_iter = 0
    for i in range(maxiter):
        tol = min(eta, eta * y_norm)
        dx = -jacobian.solve(y, tol=tol)
        dx_norm = dx.norm()
        if dx_norm == 0:
            raise ValueError('Jacobian inversion yielded zero vector. This indicates a bug in the Jacobian approximation.')
        if line_search:
            s, xnew, ynew, y_norm_new = _nonline_line_search(func, x, y, dx, search_type=line_search)
        else:
            xnew = x + dx
            ynew = func(xnew)
            y_norm_new = ynew.norm()
        if y_norm_new < best_ynorm:
            best_x = xnew
            best_dxnorm = dx_norm
            best_ynorm = y_norm_new
            best_iter = i + 1
        jacobian.update(xnew.clone(), ynew)
        to_stop = stop_cond.check(xnew, ynew, dx)
        if verbose:
            if i < 10 or i % 10 == 0 or to_stop:
                print('%6d: |dx|=%.3e, |f|=%.3e' % (i, dx_norm, y_norm))
        if to_stop:
            converge = True
            break
        eta_A = float(gamma * (y_norm_new / y_norm) ** 2)
        gamma_eta2 = gamma * eta * eta
        if gamma_eta2 < eta_threshold:
            eta = min(eta_max, eta_A)
        else:
            eta = min(eta_max, max(eta_A, gamma_eta2))
        y_norm = y_norm_new
        x = xnew
        y = ynew
    if not converge:
        msg = 'The rootfinder does not converge after %d iterations. Best |dx|=%.3e, |f|=%.3e at iter %d' % (maxiter, best_dxnorm, best_ynorm, best_iter)
        warnings.warn(ConvergenceWarning(msg))
        x = best_x
    return _pack(x)

# --- helper: deepchem.utils.differentiation_utils.optimize.rootsolver.TerminationCondition ---
class TerminationCondition(object):

    def __init__(self, f_tol: float, f_rtol: float, f0_norm: float, x_tol: float, x_rtol: float):
        if f_tol is None:
            f_tol = 1e-06
        if f_rtol is None:
            f_rtol = float('inf')
        if x_tol is None:
            x_tol = 1e-06
        if x_rtol is None:
            x_rtol = float('inf')
        self.f_tol = f_tol
        self.f_rtol = f_rtol
        self.x_tol = x_tol
        self.x_rtol = x_rtol
        self.f0_norm = f0_norm

    def check(self, x: torch.Tensor, y: torch.Tensor, dx: torch.Tensor) -> bool:
        xnorm = x.norm()
        ynorm = y.norm()
        dxnorm = dx.norm()
        xtcheck = dxnorm < self.x_tol
        xrcheck = dxnorm < self.x_rtol * xnorm
        ytcheck = ynorm < self.f_tol
        yrcheck = ynorm < self.f_rtol * self.f0_norm
        return xtcheck and xrcheck and ytcheck and yrcheck

# --- helper: deepchem.utils.differentiation_utils.optimize.rootsolver._nonline_line_search ---
def _nonline_line_search(func: Callable, x: torch.Tensor, y: torch.Tensor, dx: torch.Tensor, search_type='armijo', rdiff=1e-08, smin=0.01):
    tmp_s = [0]
    tmp_y = [y]
    tmp_phi = [y.norm() ** 2]
    s_norm = x.norm() / dx.norm()

    def phi(s, store=True):
        if s == tmp_s[0]:
            return tmp_phi[0]
        xt = x + s * dx
        v = func(xt)
        p = _safe_norm(v) ** 2
        if store:
            tmp_s[0] = s
            tmp_phi[0] = p
            tmp_y[0] = v
        return p

    def derphi(s):
        ds = (torch.abs(s) + s_norm + 1) * rdiff
        return (phi(s + ds, store=False) - phi(s)) / ds
    if search_type == 'armijo':
        s, phi1 = _scalar_search_armijo(phi, tmp_phi[0], -tmp_phi[0], amin=smin)
    if s is None:
        s = 1.0
    x = x + s * dx
    if s == tmp_s[0]:
        y = tmp_y[0]
    else:
        y = func(x)
    y_norm = y.norm()
    return (s, x, y, y_norm)

