class TerminationCondition(object):

    def __init__(self, f_tol: float, f_rtol: float, f0_norm: float, x_tol: float, x_rtol: float):
        if f_tol is None:
            f_tol = 1e-06
        if f_rtol is None:
            f_rtol = float('inf')
        if x_tol is None:
            x_tol = 1e-06
        if x_rtol is None:
            x_rtol = float('inf')
        self.f_tol = f_tol
        self.f_rtol = f_rtol
        self.x_tol = x_tol
        self.x_rtol = x_rtol
        self.f0_norm = f0_norm

    def check(self, x: torch.Tensor, y: torch.Tensor, dx: torch.Tensor) -> bool:
        xnorm = x.norm()
        ynorm = y.norm()
        dxnorm = dx.norm()
        xtcheck = dxnorm < self.x_tol
        xrcheck = dxnorm < self.x_rtol * xnorm
        ytcheck = ynorm < self.f_tol
        yrcheck = ynorm < self.f_rtol * self.f0_norm
        return xtcheck and xrcheck and ytcheck and yrcheck

# --- helper: deepchem.utils.differentiation_utils.optimize.rootsolver._nonline_line_search ---
def _nonline_line_search(func: Callable, x: torch.Tensor, y: torch.Tensor, dx: torch.Tensor, search_type='armijo', rdiff=1e-08, smin=0.01):
    tmp_s = [0]
    tmp_y = [y]
    tmp_phi = [y.norm() ** 2]
    s_norm = x.norm() / dx.norm()

    def phi(s, store=True):
        if s == tmp_s[0]:
            return tmp_phi[0]
        xt = x + s * dx
        v = func(xt)
        p = _safe_norm(v) ** 2
        if store:
            tmp_s[0] = s
            tmp_phi[0] = p
            tmp_y[0] = v
        return p

    def derphi(s):
        ds = (torch.abs(s) + s_norm + 1) * rdiff
        return (phi(s + ds, store=False) - phi(s)) / ds
    if search_type == 'armijo':
        s, phi1 = _scalar_search_armijo(phi, tmp_phi[0], -tmp_phi[0], amin=smin)
    if s is None:
        s = 1.0
    x = x + s * dx
    if s == tmp_s[0]:
        y = tmp_y[0]
    else:
        y = func(x)
    y_norm = y.norm()
    return (s, x, y, y_norm)

