# --- helper: deepchem.utils.differentiation_utils.pure_function._check_identical_objs ---
def _check_identical_objs(objs1: List, objs2: List) -> bool:
    for obj1, obj2 in zip(objs1, objs2):
        if id(obj1) != id(obj2):
            return False
    return True

