    else:
        return lambda fcn: MultiSiblingPureFunction(pfuncs, fcntocall=fcn)

# --- helper: deepchem.utils.differentiation_utils.pure_function.MultiSiblingPureFunction ---
class MultiSiblingPureFunction(PureFunction):

    def __init__(self, fcns: Sequence[Callable], fcntocall: Callable):
        self.pfuncs = [get_pure_function(fcn) for fcn in fcns]
        self.npfuncs = len(self.pfuncs)
        super().__init__(fcntocall)

    def _get_all_obj_params_init(self) -> List:
        res: List[Union[torch.Tensor, torch.nn.Parameter]] = []
        self.cumsum_idx = [0] * (self.npfuncs + 1)
        for i, pfunc in enumerate(self.pfuncs):
            objparams = pfunc._get_all_obj_params_init()
            res = res + objparams
            self.cumsum_idx[i + 1] = self.cumsum_idx[i] + len(objparams)
        return res

    def _set_all_obj_params(self, allobjparams: List):
        for i, pfunc in enumerate(self.pfuncs):
            pfunc._set_all_obj_params(allobjparams[self.cumsum_idx[i]:self.cumsum_idx[i + 1]])

# --- helper: deepchem.utils.differentiation_utils.pure_function.PureFunction ---
class PureFunction(object):

    def __init__(self, fcntocall: Callable):
        self._state_change_allowed = True
        self._allobjparams = self._get_all_obj_params_init()
        self._uniq = Uniquifier(self._allobjparams)
        self._cur_objparams = self._uniq.get_unique_objs()
        self._fcntocall = fcntocall
        self._restore_stack: List[Tuple[List, bool]] = []

    def __call__(self, *params):
        return self._fcntocall(*params)

    @abstractmethod
    def _get_all_obj_params_init(self) -> List:
        pass

    @abstractmethod
    def _set_all_obj_params(self, allobjparams: List):
        pass

    def objparams(self) -> List:
        return self._cur_objparams

    def set_objparams(self, objparams: List):
        identical = _check_identical_objs(objparams, self._cur_objparams)
        self._restore_stack.append((self._cur_objparams, identical))
        if not identical:
            allobjparams = self._uniq.map_unique_objs(objparams)
            self._set_all_obj_params(allobjparams)
            self._cur_objparams = list(objparams)

    def restore_objparams(self):
        old_objparams, identical = self._restore_stack.pop(-1)
        if not identical:
            allobjparams = self._uniq.map_unique_objs(old_objparams)
            self._set_all_obj_params(allobjparams)
            self._cur_objparams = old_objparams

    @contextmanager
    def useobjparams(self, objparams: List):
        if not self._state_change_allowed:
            raise RuntimeError('The state change is disabled')
        try:
            self.set_objparams(objparams)
            yield
        finally:
            self.restore_objparams()

    @contextmanager
    def disable_state_change(self):
        try:
            prev_status = self._state_change_allowed
            self._state_change_allowed = False
            yield
        finally:
            self._state_change_allowed = prev_status

# --- helper: deepchem.utils.differentiation_utils.pure_function.SingleSiblingPureFunction ---
class SingleSiblingPureFunction(PureFunction):

    def __init__(self, fcn: Callable, fcntocall: Callable):
        self.pfunc = get_pure_function(fcn)
        super().__init__(fcntocall)

    def _get_all_obj_params_init(self) -> List:
        return self.pfunc._get_all_obj_params_init()

    def _set_all_obj_params(self, allobjparams: List):
        self.pfunc._set_all_obj_params(allobjparams)

def get_batchdims(A: LinearOperator, B: torch.Tensor, E: Union[torch.Tensor, None], M: Union[LinearOperator, None]):
    batchdims = [A.shape[:-2], B.shape[:-2]]
    if E is not None:
        batchdims.append(E.shape[:-1])
        if M is not None:
            batchdims.append(M.shape[:-2])
    return get_bcasted_dims(*batchdims)

def get_largest_eival(Afcn: Callable, x: torch.Tensor) -> torch.Tensor:
    niter = 10
    rtol = 0.001
    atol = 1e-06
    xnorm_prev = None
    for i in range(niter):
        x = Afcn(x)
        xnorm = x.norm(dim=-2, keepdim=True)
        if i > 0:
            dnorm = torch.abs(xnorm_prev - xnorm)
            if torch.all(dnorm <= rtol * xnorm + atol):
                break
        xnorm_prev = xnorm
        if i < niter - 1:
            x = x / xnorm
    return xnorm

def gmres(A: LinearOperator, B: torch.Tensor, E: Optional[torch.Tensor]=None, M: Optional[LinearOperator]=None, posdef: Optional[bool]=None, max_niter: Optional[int]=None, rtol: float=1e-06, atol: float=1e-08, eps: float=1e-12, **unused) -> torch.Tensor:
    converge = False
    nr, ncols = (A.shape[-1], B.shape[-1])
    if max_niter is None:
        max_niter = int(nr)
    batchdims = get_batchdims(A, B, E, M)
    if torch.allclose(B, B * 0, rtol=rtol, atol=atol):
        x0 = torch.zeros((*batchdims, nr, ncols), dtype=A.dtype, device=A.device)
        return x0
    need_hermit = False
    A_fcn, AT_fcn, B2, col_swapped = setup_linear_problem(A, B, E, M, batchdims, posdef, need_hermit)
    B_norm = B2.norm(dim=-2, keepdim=True)
    stop_matrix = torch.max(rtol * B_norm, atol * torch.ones_like(B_norm))
    x0shape = (ncols, *batchdims, nr, 1) if col_swapped else (*batchdims, nr, ncols)
    x0 = torch.zeros(x0shape, dtype=A.dtype, device=A.device)
    r = B2 - A_fcn(x0)
    best_resid = r.norm(dim=-2, keepdim=True)
    best_resid = best_resid.max().item()
    best_res = x0
    q = torch.empty([max_niter] + list(r.shape), dtype=A.dtype, device=A.device)
    q[0] = r / safedenom(r.norm(dim=-2, keepdim=True), eps)
    h = torch.zeros((*batchdims, ncols, max_niter + 1, max_niter), dtype=A.dtype, device=A.device)
    h = h.reshape((-1, ncols, max_niter + 1, max_niter))
    for k in range(min(nr, max_niter)):
        y = A_fcn(q[k])
        for j in range(k + 1):
            h[..., j, k] = dot(q[j], y).reshape(-1, ncols)
            y = y - h[..., j, k].reshape(*batchdims, 1, ncols) * q[j]
        h[..., k + 1, k] = torch.linalg.norm(y, dim=-2)
        if torch.any(h[..., k + 1, k]) != 0 and k != max_niter - 1:
            q[k + 1] = y.reshape(-1, nr, ncols) / h[..., k + 1, k].reshape(-1, 1, ncols)
            q[k + 1] = q[k + 1].reshape(*batchdims, nr, ncols)
        b = torch.zeros((*batchdims, ncols, k + 1), dtype=A.dtype, device=A.device)
        b = b.reshape(-1, ncols, k + 1)
        b[..., 0] = torch.linalg.norm(r, dim=-2)
        rk = torch.linalg.lstsq(h[..., :k + 1, :k], b)[0]
        res = torch.empty([])
        for i in range(k):
            res = res + q[i] * rk[..., i].reshape(*batchdims, 1, ncols) + x0 if res.size() else q[i] * rk[..., i].reshape(*batchdims, 1, ncols) + x0
        if res.size():
            resid = B2 - A_fcn(res)
            resid_norm = resid.norm(dim=-2, keepdim=True)
            max_resid_norm = resid_norm.max().item()
            if max_resid_norm < best_resid:
                best_resid = max_resid_norm
                best_res = res
            if torch.all(resid_norm < stop_matrix):
                converge = True
                break
    if not converge:
        msg = 'Convergence is not achieved after %d iterations. Max norm of resid: %.3e' % (max_niter, best_resid)
        warnings.warn(ConvergenceWarning(msg))
    res = best_res
    return res

# --- helper: deepchem.utils.differentiation_utils.solve.dot ---
def dot(r: torch.Tensor, z: torch.Tensor) -> torch.Tensor:
    return torch.einsum('...rc,...rc->...c', r.conj(), z).unsqueeze(-2)

# --- helper: deepchem.utils.differentiation_utils.solve.get_batchdims ---
def get_batchdims(A: LinearOperator, B: torch.Tensor, E: Union[torch.Tensor, None], M: Union[LinearOperator, None]):
    batchdims = [A.shape[:-2], B.shape[:-2]]
    if E is not None:
        batchdims.append(E.shape[:-1])
        if M is not None:
            batchdims.append(M.shape[:-2])
    return get_bcasted_dims(*batchdims)

# --- helper: deepchem.utils.differentiation_utils.solve.safedenom ---
def safedenom(r: torch.Tensor, eps: float) -> torch.Tensor:
    r[r == 0] = eps
    return r

# --- helper: deepchem.utils.differentiation_utils.solve.setup_linear_problem ---
def setup_linear_problem(A: LinearOperator, B: torch.Tensor, E: Optional[torch.Tensor], M: Optional[LinearOperator], batchdims: Sequence[int], posdef: Optional[bool], need_hermit: bool) -> Tuple[Callable[[torch.Tensor], torch.Tensor], Callable[[torch.Tensor], torch.Tensor], torch.Tensor, bool]:
    if E is None:

        def A_fcn(x):
            return A.mm(x)

        def AT_fcn(x):
            return A.rmm(x)
        B_new = B
        col_swapped = False
    else:
        if M is None:
            BAs, BBs, BEs = normalize_bcast_dims(A.shape[:-2], B.shape[:-2], E.shape[:-1])
        else:
            BAs, BBs, BEs, BMs = normalize_bcast_dims(A.shape[:-2], B.shape[:-2], E.shape[:-1], M.shape[:-2])
        E = E.reshape(*BEs, *E.shape[-1:])
        E_new = E.unsqueeze(0).transpose(-1, 0).unsqueeze(-1)
        B = B.reshape(*BBs, *B.shape[-2:])
        B_new = B.unsqueeze(0).transpose(-1, 0)

        def A_fcn(x):
            Ax = A.mm(x)
            Mx = M.mm(x) if M is not None else x
            MxE = Mx * E_new
            return Ax - MxE

        def AT_fcn(x):
            ATx = A.rmm(x)
            MTx = M.rmm(x) if M is not None else x
            MTxE = MTx * E_new
            return ATx - MTxE
        col_swapped = True
    if need_hermit:
        is_hermit = A.is_hermitian and (M is None or M.is_hermitian)
        if not is_hermit:
            posdef = False
    if posdef is None:
        nr, ncols = B.shape[-2:]
        x0shape = (ncols, *batchdims, nr, 1) if col_swapped else (*batchdims, nr, ncols)
        x0 = torch.randn(x0shape, dtype=A.dtype, device=A.device)
        x0 = x0 / x0.norm(dim=-2, keepdim=True)
        largest_eival = get_largest_eival(A_fcn, x0)
        negeival = largest_eival <= 0
        if torch.all(negeival):
            posdef = False
        else:
            offset = torch.clamp(largest_eival, min=0.0)

            def A_fcn2(x):
                return A_fcn(x) - offset * x
            mostneg_eival = get_largest_eival(A_fcn2, x0)
            posdef = bool(torch.all(torch.logical_or(-mostneg_eival <= offset, negeival)).item())
    if posdef:
        return (A_fcn, AT_fcn, B_new, col_swapped)
    else:

        def A_new_fcn(x):
            return AT_fcn(A_fcn(x))
        B2 = AT_fcn(B_new)
        return (A_new_fcn, A_new_fcn, B2, col_swapped)

