def setup_precond(precond: Optional[LinearOperator]=None) -> Callable[[torch.Tensor], torch.Tensor]:
    if isinstance(precond, LinearOperator):

        def precond_fcn(x):
            return precond.mm(x)
    elif precond is None:

        def precond_fcn(x):
            return x
    else:
        raise TypeError('precond can only be LinearOperator or None')
    return precond_fcn

def safedenom(r: torch.Tensor, eps: float) -> torch.Tensor:
    r[r == 0] = eps
    return r

def exacteig(A: LinearOperator, neig: int, mode: str, M: Optional[LinearOperator]) -> Tuple[torch.Tensor, torch.Tensor]:
    Amatrix = A.fullmatrix()
    if M is None:
        evals, evecs = degen_symeig.apply(Amatrix)
        return _take_eigpairs(evals, evecs, neig, mode)
    else:
        Mmatrix = M.fullmatrix()
        L = torch.linalg.cholesky(Mmatrix)
        Linv = torch.inverse(L)
        LinvT = Linv.transpose(-2, -1).conj()
        A2 = torch.matmul(Linv, torch.matmul(Amatrix, LinvT))
        evals, evecs = degen_symeig.apply(A2)
        evals, evecs = _take_eigpairs(evals, evecs, neig, mode)
        evecs = torch.matmul(LinvT, evecs)
        return (evals, evecs)

# --- helper: deepchem.utils.differentiation_utils.symeig._take_eigpairs ---
def _take_eigpairs(eival: torch.Tensor, eivec: torch.Tensor, neig: int, mode: str):
    if mode == 'lowest':
        eival = eival[..., :neig]
        eivec = eivec[..., :neig]
    else:
        eival = eival[..., -neig:]
        eivec = eivec[..., -neig:]
    return (eival, eivec)

# --- helper: deepchem.utils.differentiation_utils.symeig.degen_symeig ---
class degen_symeig(torch.autograd.Function):

    @staticmethod
    def forward(ctx, A):
        eival, eivec = torch.linalg.eigh(A)
        ctx.save_for_backward(eival, eivec)
        return (eival, eivec)

    @staticmethod
    def backward(ctx, grad_eival, grad_eivec):
        eival, eivec = ctx.saved_tensors
        min_threshold = torch.finfo(eival.dtype).eps ** 0.6
        eivect = eivec.transpose(-2, -1).conj()
        if grad_eivec is not None:
            F = eival.unsqueeze(-2) - eival.unsqueeze(-1)
            idx = torch.abs(F) <= min_threshold
            F[idx] = float('inf')
            F = F.pow(-1)
            F = F * torch.matmul(eivect, grad_eivec)
            result = torch.matmul(eivec, torch.matmul(F, eivect))
        else:
            result = torch.zeros_like(eivec)
        if grad_eival is not None:
            result += torch.matmul(eivec, grad_eival.unsqueeze(-1) * eivect)
        result = (result + result.transpose(-2, -1).conj()) * 0.5
        return result

def davidson(A: LinearOperator, neig: int, mode: str, M: Optional[LinearOperator]=None, max_niter: int=1000, nguess: Optional[int]=None, v_init: str='randn', max_addition: Optional[int]=None, min_eps: float=1e-06, verbose: bool=False, **unused) -> Tuple[torch.Tensor, torch.Tensor]:
    if nguess is None:
        nguess = neig
    if max_addition is None:
        max_addition = neig
    na = A.shape[-1]
    if M is None:
        bcast_dims = A.shape[:-2]
    else:
        bcast_dims = get_bcasted_dims(A.shape[:-2], M.shape[:-2])
    dtype = A.dtype
    device = A.device
    prev_eigvalT = None
    V = _set_initial_v(v_init.lower(), dtype, device, bcast_dims, na, nguess, M=M)
    best_resid: Union[float, torch.Tensor] = float('inf')
    AV = A.mm(V)
    for i in range(max_niter):
        VT = V.transpose(-2, -1)
        T = torch.matmul(VT, AV)
        eigvalT, eigvecT = torch.linalg.eigh(T)
        eigvalT, eigvecT = _take_eigpairs(eigvalT, eigvecT, neig, mode)
        eigvecA = torch.matmul(V, eigvecT)
        AVs = torch.matmul(AV, eigvecT)
        LVs = eigvalT.unsqueeze(-2) * eigvecA
        if M is not None:
            LVs = M.mm(LVs)
        resid = AVs - LVs
        max_resid = resid.abs().max()
        if prev_eigvalT is not None:
            deigval = eigvalT - prev_eigvalT
            max_deigval = deigval.abs().max()
            if verbose:
                print('Iter %3d (guess size: %d): resid: %.3e, devals: %.3e' % (i + 1, nguess, max_resid, max_deigval))
        if max_resid < best_resid:
            best_resid = max_resid
            best_eigvals = eigvalT
            best_eigvecs = eigvecA
        if max_resid < min_eps:
            break
        if AV.shape[-1] == AV.shape[-2]:
            break
        prev_eigvalT = eigvalT
        t = -resid
        t = to_fortran_order(t)
        Vnew = torch.cat((V, t), dim=-1)
        if Vnew.shape[-1] > Vnew.shape[-2]:
            Vnew = Vnew[..., :Vnew.shape[-2]]
        nadd = Vnew.shape[-1] - V.shape[-1]
        nguess = nguess + nadd
        if M is not None:
            MV_ = M.mm(Vnew)
            V, R = tallqr(Vnew, MV=MV_)
        else:
            V, R = tallqr(Vnew)
        AVnew = A.mm(V[..., -nadd:])
        AVnew = to_fortran_order(AVnew)
        AV = torch.cat((AV, AVnew), dim=-1)
    eigvals = best_eigvals
    eigvecs = best_eigvecs
    return (eigvals, eigvecs)

# --- helper: deepchem.utils.differentiation_utils.symeig._set_initial_v ---
def _set_initial_v(vinit_type: str, dtype: torch.dtype, device: torch.device, batch_dims: Sequence, na: int, nguess: int, M: Optional[LinearOperator]=None) -> torch.Tensor:
    torch.manual_seed(12421)
    if vinit_type == 'eye':
        nbatch = functools.reduce(lambda x, y: x * y, batch_dims, 1)
        V = torch.eye(na, nguess, dtype=dtype, device=device).unsqueeze(0).repeat(nbatch, 1, 1).reshape(*batch_dims, na, nguess)
    elif vinit_type == 'randn':
        V = torch.randn((*batch_dims, na, nguess), dtype=dtype, device=device)
    elif vinit_type == 'random' or vinit_type == 'rand':
        V = torch.rand((*batch_dims, na, nguess), dtype=dtype, device=device)
    else:
        raise ValueError('Unknown v_init type: %s' % vinit_type)
    if isinstance(M, LinearOperator):
        V, R = tallqr(V, MV=M.mm(V))
    else:
        V, R = tallqr(V)
    return V

# --- helper: deepchem.utils.differentiation_utils.symeig._take_eigpairs ---
def _take_eigpairs(eival: torch.Tensor, eivec: torch.Tensor, neig: int, mode: str):
    if mode == 'lowest':
        eival = eival[..., :neig]
        eivec = eivec[..., :neig]
    else:
        eival = eival[..., -neig:]
        eivec = eivec[..., -neig:]
    return (eival, eivec)

class degen_symeig(torch.autograd.Function):

    @staticmethod
    def forward(ctx, A):
        eival, eivec = torch.linalg.eigh(A)
        ctx.save_for_backward(eival, eivec)
        return (eival, eivec)

    @staticmethod
    def backward(ctx, grad_eival, grad_eivec):
        eival, eivec = ctx.saved_tensors
        min_threshold = torch.finfo(eival.dtype).eps ** 0.6
        eivect = eivec.transpose(-2, -1).conj()
        if grad_eivec is not None:
            F = eival.unsqueeze(-2) - eival.unsqueeze(-1)
            idx = torch.abs(F) <= min_threshold
            F[idx] = float('inf')
            F = F.pow(-1)
            F = F * torch.matmul(eivect, grad_eivec)
            result = torch.matmul(eivec, torch.matmul(F, eivect))
        else:
            result = torch.zeros_like(eivec)
        if grad_eival is not None:
            result += torch.matmul(eivec, grad_eival.unsqueeze(-1) * eivect)
        result = (result + result.transpose(-2, -1).conj()) * 0.5
        return result

def ortho(A: torch.Tensor, B: torch.Tensor, *, D: Optional[torch.Tensor]=None, M: Optional[LinearOperator]=None, mright: bool=False) -> torch.Tensor:
    if D is None:
        str1 = '...rc,...rc->...c'
        Bconj = B.conj()
        if M is None:
            return A - torch.einsum(str1, A, Bconj).unsqueeze(-2) * B
        elif mright:
            return A - torch.einsum(str1, M.mm(A), Bconj).unsqueeze(-2) * B
        else:
            return A - M.mm(torch.einsum(str1, A, Bconj).unsqueeze(-2) * B)
    else:
        BH = B.transpose(-2, -1).conj()
        if M is None:
            DBHA = D * torch.matmul(BH, A)
            return A - torch.matmul(B, DBHA)
        elif mright:
            DBHA = D * torch.matmul(BH, M.mm(A))
            return A - torch.matmul(B, DBHA)
        else:
            DBHA = D * torch.matmul(BH, A)
            return A - M.mm(torch.matmul(B, DBHA))

def svd(A: LinearOperator, k: Optional[int]=None, mode: str='uppest', bck_options: Mapping[str, Any]={}, method: Union[str, Callable, None]=None, **fwd_options) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    m = A.shape[-2]
    n = A.shape[-1]
    if m < n:
        AAsym = A.matmul(A.H, is_hermitian=True)
    else:
        AAsym = A.H.matmul(A, is_hermitian=True)
    eivals, eivecs = symeig(AAsym, k, mode, bck_options=bck_options, method=method, **fwd_options)
    eivals = torch.clamp(eivals, min=0.0)
    s = torch.sqrt(eivals)
    sdiv = torch.clamp(s, min=1e-12).unsqueeze(-2)
    if m < n:
        u = eivecs
        v = A.rmm(u) / sdiv
    else:
        v = eivecs
        u = A.mm(v) / sdiv
    vh = v.transpose(-2, -1).conj()
    return (u, s, vh)

# --- helper: deepchem.utils.differentiation_utils.symeig.symeig ---
def symeig(A: LinearOperator, neig: Optional[int]=None, mode: str='lowest', M: Optional[LinearOperator]=None, bck_options: Mapping[str, Any]={}, method: Union[str, Callable, None]=None, **fwd_options) -> Tuple[torch.Tensor, torch.Tensor]:
    assert A.is_hermitian, 'The linear operator A must be Hermitian'
    assert not torch.is_grad_enabled() or A.is_getparamnames_implemented, 'The _getparamnames(self, prefix) of linear operator A must be implemented if using symeig with grad enabled'
    if M is not None:
        assert M.is_hermitian, 'The linear operator M must be Hermitian'
        assert M.shape[-1] == A.shape[-1], 'The shape of A & M must match (A: %s, M: %s)' % (A.shape, M.shape)
        assert not torch.is_grad_enabled() or M.is_getparamnames_implemented, 'The _getparamnames(self, prefix) of linear operator M must be implemented if using symeig with grad enabled'
    mode = mode.lower()
    if mode == 'uppermost':
        mode = 'uppest'
    if method is None:
        if isinstance(A, MatrixLinearOperator) and (M is None or isinstance(M, MatrixLinearOperator)):
            method = 'exacteig'
        else:
            method = 'exacteig'
    if neig is None:
        neig = A.shape[-1]
    if method == 'exacteig':
        return exacteig(A, neig, mode, M)
    else:
        fwd_options['method'] = method
        params = A.getlinopparams()
        mparams = M.getlinopparams() if M is not None else []
        na = len(params)
        return symeig_torchfcn.apply(A, neig, mode, M, fwd_options, bck_options, na, *params, *mparams)

def change_basis_real_to_complex(k: int, dtype: Optional[torch.dtype]=None, device: Optional[torch.device]=None) -> torch.Tensor:
    q = torch.zeros((2 * k + 1, 2 * k + 1), dtype=torch.complex128)
    for m in range(-k, 0):
        q[k + m, k + abs(m)] = 1 / 2 ** 0.5
        q[k + m, k - abs(m)] = complex(-1j / 2 ** 0.5)
    q[k, k] = 1
    for m in range(1, k + 1):
        q[k + m, k + abs(m)] = (-1) ** m / 2 ** 0.5
        q[k + m, k - abs(m)] = complex(1j * (-1) ** m / 2 ** 0.5)
    q = (-1j) ** k * q
    if dtype is None:
        default_type = torch.empty(0).dtype
        if default_type == torch.float32:
            dtype = torch.complex64
        elif default_type == torch.float64:
            dtype = torch.complex128
    if device is None:
        device = torch.empty(0).device
    return q.to(dtype=dtype, device=device, copy=True, memory_format=torch.contiguous_format)

def aggregate_std(h, **kwargs):
    return torch.sqrt(aggregate_var(h) + EPS)

# --- helper: deepchem.utils.graph_utils.aggregate_var ---
def aggregate_var(h, **kwargs):
    h_mean_squares = torch.mean(h * h, dim=-2)
    h_mean = torch.mean(h, dim=-2)
    var = torch.relu(h_mean_squares - h_mean * h_mean)
    return var

def aggregate_var(h, **kwargs):
    h_mean_squares = torch.mean(h * h, dim=-2)
    h_mean = torch.mean(h, dim=-2)
    var = torch.relu(h_mean_squares - h_mean * h_mean)
    return var

