def indent(s, nspace):
    spaces = ' ' * nspace
    lines = [spaces + c if i > 0 else c for i, c in enumerate(s.split('\n'))]
    return '\n'.join(lines)

def get_atom_mass(atom_z: int) -> float:
    try:
        atomic_mass = atom_masses[atom_z]
    except KeyError:
        raise KeyError('Element Does Not Exists or Not Documented: %d' % atom_z)
