def get_period(atom_z: int) -> int:
    period: int = 0
    if atom_z <= 2:
        period = 1
    elif atom_z <= 10:
        period = 2
    elif atom_z <= 18:
        period = 3
    elif atom_z <= 36:
        period = 4
