class TensorNonTensorSeparator(object):

    def __init__(self, params: Sequence, varonly: bool=True):
        self.tensor_idxs = []
        self.tensor_params = []
        self.nontensor_idxs = []
        self.nontensor_params = []
        self.nparams = len(params)
        for i, p in enumerate(params):
            if isinstance(p, torch.Tensor) and (varonly and p.requires_grad or not varonly):
                self.tensor_idxs.append(i)
                self.tensor_params.append(p)
            else:
                self.nontensor_idxs.append(i)
                self.nontensor_params.append(p)
        self.alltensors = len(self.tensor_idxs) == self.nparams

    def get_tensor_params(self):
        return self.tensor_params

    def ntensors(self):
        return len(self.tensor_idxs)

    def nnontensors(self):
        return len(self.nontensor_idxs)

    def reconstruct_params(self, tensor_params, nontensor_params=None):
        if nontensor_params is None:
            nontensor_params = self.nontensor_params
        if len(tensor_params) + len(nontensor_params) != self.nparams:
            raise ValueError('The total length of tensor and nontensor params do not match with the expected length: %d instead of %d' % (len(tensor_params) + len(nontensor_params), self.nparams))
        if self.alltensors:
            return tensor_params
        params = [None for _ in range(self.nparams)]
        for nidx, p in zip(self.nontensor_idxs, nontensor_params):
            params[nidx] = p
        for idx, p in zip(self.tensor_idxs, tensor_params):
            params[idx] = p
        return params

def get_memory(a: torch.Tensor) -> int:
    size = a.numel() * a.element_size()
    return size

def gaussian_integral(n: int, alpha: Union[float, torch.Tensor]) -> Union[float, torch.Tensor]:
    n1 = (n + 1) * 0.5
    return scipy.special.gamma(n1) / (2 * alpha ** n1)

def get_np_dtype(dtype: torch.dtype) -> Any:
    if dtype == torch.float32:
        return np.float32
    elif dtype == torch.float64:
        return np.float64
    elif dtype == torch.complex64:
        return np.complex64
    elif dtype == torch.complex128:
        return np.complex128
    else:
        raise TypeError('Unknown type: %s' % dtype)

def segment_sum(data: torch.Tensor, segment_ids: torch.Tensor) -> torch.Tensor:
    if not all((segment_ids[i] <= segment_ids[i + 1] for i in range(len(segment_ids) - 1))):
        raise AssertionError('elements of segment_ids must be sorted')
    if len(segment_ids.shape) != 1:
        raise AssertionError('segment_ids have be a 1-D tensor')
    if data.shape[0] != segment_ids.shape[0]:
        raise AssertionError('segment_ids should be the same size as dimension 0 of input.')
    num_segments = len(torch.unique(segment_ids))
    out_tensor = unsorted_segment_sum(data, segment_ids, num_segments)
    return out_tensor

# --- helper: deepchem.utils.pytorch_utils.unsorted_segment_sum ---
def unsorted_segment_sum(data: torch.Tensor, segment_ids: torch.Tensor, num_segments: int) -> torch.Tensor:
    if len(segment_ids.shape) != 1:
        raise AssertionError('segment_ids have be a 1-D tensor')
    if data.shape[0] != segment_ids.shape[0]:
        raise AssertionError('segment_ids should be the same size as dimension 0 of input.')
    s = torch.prod(torch.tensor(data.shape[1:])).long()
    segment_ids = segment_ids.repeat_interleave(s).view(segment_ids.shape[0], *data.shape[1:])
    assert data.shape == segment_ids.shape
    shape: List[int] = [num_segments] + list(data.shape[1:])
    tensor: torch.Tensor = torch.zeros(*shape).scatter_add(0, segment_ids, data.float())
    tensor = tensor.type(data.dtype)
    return tensor

def tallqr(V, MV=None):
    if MV is None:
        MV = V
    VTV = torch.matmul(V.transpose(-2, -1), MV)
    R = torch.linalg.cholesky(VTV.transpose(-2, -1).conj()).transpose(-2, -1).conj()
    Rinv = torch.inverse(R)
    Q = torch.matmul(V, Rinv)
    return (Q, R)

def to_fortran_order(V):
    if V.is_contiguous():
        return V.transpose(-2, -1).contiguous().transpose(-2, -1)
    elif V.transpose(-2, -1).is_contiguous():
        return V
    else:
        raise RuntimeError('Only the last two dimensions can be made Fortran order.')

def get_floor_and_ceil(aa: Union[int, float]) -> Tuple[int, int]:
    if isinstance(aa, int):
        ceil_a: int = aa
        floor_a: int = aa
    else:
        ceil_a = int(math.ceil(aa))
        floor_a = int(math.floor(aa))
    return (floor_a, ceil_a)

def occnumber(a: ZType, n: Optional[int]=None, dtype: torch.dtype=torch.double, device: torch.device=torch.device('cpu')) -> torch.Tensor:
    if isinstance(a, torch.Tensor):
        assert a.numel() == 1
        floor_a, ceil_a = get_floor_and_ceil(a.item())
    else:
        floor_a, ceil_a = get_floor_and_ceil(a)
    if n is None:
        nlength = ceil_a
    else:
        nlength = n
        assert nlength >= ceil_a, 'The length of occupation number must be at least %d' % ceil_a
    if isinstance(a, torch.Tensor):
        res = _OccNumber.apply(a, floor_a, ceil_a, nlength, dtype, device)
    else:
        res = _construct_occ_number(a, floor_a, ceil_a, nlength, dtype=dtype, device=device)
    return res

# --- helper: deepchem.utils.safeops_utils._OccNumber ---
class _OccNumber(torch.autograd.Function):

    @staticmethod
    def forward(self, a: torch.Tensor, floor_a: int, ceil_a: int, nlength: int, dtype: torch.dtype, device: torch.device) -> torch.Tensor:
        res = _construct_occ_number(float(a.item()), floor_a, ceil_a, nlength, dtype=dtype, device=device)
        self.ceil_a = ceil_a
        return res

    @staticmethod
    def backward(self, grad_res: torch.Tensor):
        grad_a = grad_res[self.ceil_a - 1]
        return (grad_a,) + (None,) * 5

# --- helper: deepchem.utils.safeops_utils._construct_occ_number ---
def _construct_occ_number(a: float, floor_a: int, ceil_a: int, nlength: int, dtype: torch.dtype, device: torch.device) -> torch.Tensor:
    res = torch.zeros(nlength, dtype=dtype, device=device)
    res[:floor_a] = 1
    if ceil_a > floor_a:
        res[ceil_a - 1] = a - floor_a
    return res

# --- helper: deepchem.utils.safeops_utils.get_floor_and_ceil ---
def get_floor_and_ceil(aa: Union[int, float]) -> Tuple[int, int]:
    if isinstance(aa, int):
        ceil_a: int = aa
        floor_a: int = aa
    else:
        ceil_a = int(math.ceil(aa))
        floor_a = int(math.floor(aa))
    return (floor_a, ceil_a)

def safedenom(r: torch.Tensor, eps: float) -> torch.Tensor:
    r[r == 0] = eps
    return r

def safepow(a: torch.Tensor, p: torch.Tensor, eps: float=1e-12) -> torch.Tensor:
    if torch.any(a < 0):
        raise RuntimeError('safepow only works for positive base')
    base = torch.sqrt(a * a + eps * eps)
    return base ** p

class VolumetricData(MSONable):

    def __init__(self, structure: Structure | IStructure, data: dict[str, NDArray], distance_matrix: dict | None=None, data_aug: dict[str, NDArray] | None=None) -> None:
        self.structure = structure
        self.is_spin_polarized: bool = len(data) >= 2
        self.is_soc: bool = len(data) >= 4
        self.data: dict[str, NDArray] = {k: np.asarray(v) for k, v in data.items()}
        self.dim = self.data['total'].shape
        self.data_aug = data_aug or {}
        self.ngridpts = self.dim[0] * self.dim[1] * self.dim[2]
        self._spin_data: dict[Spin, NDArray] = {}
        self._distance_matrix = distance_matrix if distance_matrix is not None else {}
        self.xpoints = np.linspace(0.0, 1.0, num=self.dim[0])
        self.ypoints = np.linspace(0.0, 1.0, num=self.dim[1])
        self.zpoints = np.linspace(0.0, 1.0, num=self.dim[2])
        self.interpolator = RegularGridInterpolator((self.xpoints, self.ypoints, self.zpoints), self.data['total'], bounds_error=True)
        self.name = 'VolumetricData'

    def __add__(self, other) -> Self:
        return self.linear_add(other, 1.0)

    def __radd__(self, other) -> Self:
        if other == 0 or other is None:
            return self
        if isinstance(other, self.__class__):
            return self.__add__(other)
        raise TypeError(f"Unsupported operand type(s) for +: '{type(other).__name__}' and '{type(self).__name__}'")

    def __sub__(self, other) -> Self:
        return self.linear_add(other, -1.0)

    @property
    def spin_data(self) -> dict[Spin, NDArray]:
        if not self._spin_data:
            spin_data = {}
            spin_data[Spin.up] = 0.5 * (self.data['total'] + self.data.get('diff', 0))
            spin_data[Spin.down] = 0.5 * (self.data['total'] - self.data.get('diff', 0))
            self._spin_data = spin_data
        return self._spin_data

    def get_axis_grid(self, ind: int) -> list[float]:
        ng = self.dim
        num_pts = ng[ind]
        lengths = self.structure.lattice.abc
        return [i / num_pts * lengths[ind] for i in range(num_pts)]

    def copy(self) -> Self:
        return type(self)(self.structure, {k: v.copy() for k, v in self.data.items()}, distance_matrix=self._distance_matrix, data_aug=self.data_aug)

    def linear_add(self, other, scale_factor: float=1.0) -> Self:
        if self.structure != other.structure:
            warnings.warn('Structures are different. Make sure you know what you are doing...', stacklevel=2)
        if list(self.data) != list(other.data):
            raise ValueError('Data have different keys! Maybe one is spin-polarized and the other is not?')
        data = {}
        for k in self.data:
            data[k] = self.data[k] + scale_factor * other.data[k]
        new = deepcopy(self)
        new.data = data
        new.data_aug = {}
        return new

    def scale(self, factor: float) -> None:
        for k in self.data:
            self.data[k] = np.multiply(self.data[k], factor)

    def value_at(self, x: float, y: float, z: float) -> float:
        return self.interpolator([x, y, z])[0]

    def linear_slice(self, p1: ArrayLike, p2: ArrayLike, n=100):
        p1 = np.asarray(p1)
        p2 = np.asarray(p2)
        if p1.shape != (3,) or p2.shape != (3,):
            raise ValueError(f'lengths of p1 and p2 should be 3, got {len(p1)} and {len(p2)}')
        x_pts = np.linspace(p1[0], p2[0], num=n)
        y_pts = np.linspace(p1[1], p2[1], num=n)
        z_pts = np.linspace(p1[2], p2[2], num=n)
        return [self.value_at(x_pts[i], y_pts[i], z_pts[i]) for i in range(n)]

    def get_integrated_diff(self, ind: int, radius: float, nbins: int=1) -> NDArray:
        if not self.is_spin_polarized:
            radii = [radius / nbins * (i + 1) for i in range(nbins)]
            data = np.zeros((nbins, 2))
            data[:, 0] = radii
            return data
        struct = self.structure
        a = self.dim
        self._distance_matrix = {} if self._distance_matrix is None else self._distance_matrix
        if ind not in self._distance_matrix or self._distance_matrix[ind]['max_radius'] < radius:
            coords = []
            for x, y, z in itertools.product(*(list(range(i)) for i in a)):
                coords.append([x / a[0], y / a[1], z / a[2]])
            sites_dist = struct.lattice.get_points_in_sphere(coords, struct[ind].coords, radius)
            self._distance_matrix[ind] = {'max_radius': radius, 'data': np.array(sites_dist, dtype=object)}
        data = self._distance_matrix[ind]['data']
        inds = data[:, 1] <= radius
        dists = data[inds, 1]
        data_inds = np.rint(np.mod(list(data[inds, 0]), 1) * np.tile(a, (len(dists), 1))).astype(int)
        vals = [self.data['diff'][x, y, z] for x, y, z in data_inds]
        hist, edges = np.histogram(dists, bins=nbins, range=(0, radius), weights=vals)
        data = np.zeros((nbins, 2))
        data[:, 0] = edges[1:]
        data[:, 1] = [sum(hist[0:i + 1]) / self.ngridpts for i in range(nbins)]
        return data

    def get_average_along_axis(self, ind: int) -> NDArray:
        total_spin_dens = self.data['total']
        ng = self.dim
        if ind == 0:
            total = np.sum(np.sum(total_spin_dens, axis=1), 1)
        elif ind == 1:
            total = np.sum(np.sum(total_spin_dens, axis=0), 1)
        else:
            total = np.sum(np.sum(total_spin_dens, axis=0), 0)
        return total / ng[(ind + 1) % 3] / ng[(ind + 2) % 3]

    def to_hdf5(self, filename: PathLike) -> None:
        import h5py
        with h5py.File(str(filename), mode='w') as file:
            ds = file.create_dataset('lattice', (3, 3), dtype='float')
            ds[...] = self.structure.lattice.matrix
            ds = file.create_dataset('Z', (len(self.structure.species),), dtype='i')
            ds[...] = np.array([sp.Z for sp in self.structure.species])
            ds = file.create_dataset('fcoords', self.structure.frac_coords.shape, dtype='float')
            ds[...] = self.structure.frac_coords
            dt = h5py.special_dtype(vlen=str)
            ds = file.create_dataset('species', (len(self.structure.species),), dtype=dt)
            ds[...] = [str(sp) for sp in self.structure.species]
            grp = file.create_group('vdata')
            for k in self.data:
                ds = grp.create_dataset(k, self.data[k].shape, dtype='float')
                ds[...] = self.data[k]
            file.attrs['name'] = self.name
            file.attrs['structure_json'] = orjson.dumps(self.structure.as_dict()).decode()

    @classmethod
    def from_hdf5(cls, filename: PathLike, **kwargs) -> Self:
        import h5py
        with h5py.File(str(filename), mode='r') as file:
            data = {k: np.asarray(v) for k, v in file['vdata'].items()}
            data_aug = None
            if 'vdata_aug' in file:
                data_aug = {k: np.asarray(v) for k, v in file['vdata_aug'].items()}
            structure = Structure.from_dict(orjson.loads(file.attrs['structure_json']))
            return cls(structure, data=data, data_aug=data_aug, **kwargs)

    def to_cube(self, filename: PathLike, comment: str='') -> None:
        with zopen(filename, mode='wt', encoding='utf-8') as file:
            file = cast('TextIO', file)
            file.write(f'# Cube file for {self.structure.formula} generated by Pymatgen\n')
            file.write(f'# {comment}\n')
            file.write(f'\t {len(self.structure)} 0.000000 0.000000 0.000000\n')
            for idx in range(3):
                lattice_matrix = self.structure.lattice.matrix[idx] / self.dim[idx] * ang_to_bohr
                file.write(f'\t {self.dim[idx]} {lattice_matrix[0]:.6f} {lattice_matrix[1]:.6f} {lattice_matrix[2]:.6f}\n')
            for site in self.structure:
                file.write(f'\t {Element(site.species_string).Z} 0.000000 {ang_to_bohr * site.coords[0]} {ang_to_bohr * site.coords[1]} {ang_to_bohr * site.coords[2]} \n')
            for idx, dat in enumerate(self.data['total'].flatten(), start=1):
                file.write(f"{(' ' if dat > 0 else '')}{dat:.6e} ")
                if idx % 6 == 0:
                    file.write('\n')

    @classmethod
    def from_cube(cls, filename: PathLike) -> Self:
        with zopen(filename, mode='rt', encoding='utf-8') as f:
            lines = f.readlines()
        n_atoms = int(lines[2].split()[0])

        def parse_voxel(line):
            parts = line.split()
            return (int(parts[0]), np.array(parts[1:], dtype=float) * bohr_to_angstrom)
        num_x_voxels, voxel_x = parse_voxel(lines[3])
        num_y_voxels, voxel_y = parse_voxel(lines[4])
        num_z_voxels, voxel_z = parse_voxel(lines[5])
        atom_data_start = 6
        atom_data_end = atom_data_start + n_atoms
        sites = [Site(line.split()[0], np.array(line.split()[2:], dtype=float) * bohr_to_angstrom) for line in lines[atom_data_start:atom_data_end]]
        structure = Structure(lattice=[voxel_x * num_x_voxels, voxel_y * num_y_voxels, voxel_z * num_z_voxels], species=[site.specie for site in sites], coords=[site.coords for site in sites], coords_are_cartesian=True)
        volumetric_data_start = atom_data_end
        volumetric_data_lines = lines[volumetric_data_start:]
        volumetric_data = np.fromstring(' '.join(volumetric_data_lines), sep=' ', dtype=float)
        data = volumetric_data.reshape((num_x_voxels, num_y_voxels, num_z_voxels))
        return cls(structure=structure, data={'total': data})

class VolumetricData(BaseVolumetricData):

    @staticmethod
    def parse_file(filename: PathLike) -> tuple[Poscar, dict, dict]:
        poscar_read = False
        poscar_string: list[str] = []
        dataset: NDArray = np.zeros((1, 1, 1))
        all_dataset: list[NDArray] = []
        all_dataset_aug: dict[int, list[str]] = {}
        dim: list[int] = []
        dimline = ''
        read_dataset = False
        ngrid_pts = 0
        data_count = 0
        poscar = None
        with zopen(filename, mode='rt', encoding='utf-8') as file:
            for line in file:
                original_line = line
                line = line.strip()
                if read_dataset:
                    for tok in line.split():
                        if data_count < ngrid_pts:
                            no_x = data_count // dim[0]
                            dataset[data_count % dim[0], no_x % dim[1], no_x // dim[1]] = float(tok)
                            data_count += 1
                    if data_count >= ngrid_pts:
                        read_dataset = False
                        data_count = 0
                        all_dataset.append(dataset)
                elif not poscar_read:
                    if line != '' or len(poscar_string) == 0:
                        poscar_string.append(line)
                    elif line == '':
                        poscar = Poscar.from_str('\n'.join(poscar_string))
                        poscar_read = True
                elif not dim:
                    dim = [int(i) for i in line.split()]
                    ngrid_pts = dim[0] * dim[1] * dim[2]
                    dimline = line
                    read_dataset = True
                    dataset = np.zeros(dim)
                elif line == dimline:
                    read_dataset = True
                    dataset = np.zeros(dim)
                else:
                    key = len(all_dataset) - 1
                    if key not in all_dataset_aug:
                        all_dataset_aug[key] = []
                    all_dataset_aug[key].append(original_line)
            if len(all_dataset) == 4:
                data = {'total': all_dataset[0], 'diff_x': all_dataset[1], 'diff_y': all_dataset[2], 'diff_z': all_dataset[3]}
                data_aug = {'total': all_dataset_aug.get(0), 'diff_x': all_dataset_aug.get(1), 'diff_y': all_dataset_aug.get(2), 'diff_z': all_dataset_aug.get(3)}
                diff_xyz = np.array([data['diff_x'], data['diff_y'], data['diff_z']])
                diff_xyz = diff_xyz.reshape((3, dim[0] * dim[1] * dim[2]))
                ref_direction = np.array([1.01, 1.02, 1.03])
                ref_sign = np.sign(np.dot(ref_direction, diff_xyz))
                diff = np.multiply(np.linalg.norm(diff_xyz, axis=0), ref_sign)
                data['diff'] = diff.reshape((dim[0], dim[1], dim[2]))
            elif len(all_dataset) == 2:
                data = {'total': all_dataset[0], 'diff': all_dataset[1]}
                data_aug = {'total': all_dataset_aug.get(0), 'diff': all_dataset_aug.get(1)}
            else:
                data = {'total': all_dataset[0]}
                data_aug = {'total': all_dataset_aug.get(0)}
            return (poscar, data, data_aug)

    def write_file(self, file_name: PathLike, vasp4_compatible: bool=False) -> None:

        def format_fortran_float(flt: float) -> str:
            flt_str = f'{flt:.10E}'
            if flt >= 0:
                return f'0.{flt_str[0]}{flt_str[2:12]}E{int(flt_str[13:]) + 1:+03}'
            return f'-.{flt_str[1]}{flt_str[3:13]}E{int(flt_str[14:]) + 1:+03}'

        def write_spin(data_type: str) -> None:
            lines = []
            count = 0
            file.write(f'   {dim[0]}   {dim[1]}   {dim[2]}\n')
            for k, j, i in itertools.product(list(range(dim[2])), list(range(dim[1])), list(range(dim[0]))):
                lines.append(format_fortran_float(self.data[data_type][i, j, k]))
                count += 1
                if count % 5 == 0:
                    file.write(' ' + ''.join(lines) + '\n')
                    lines = []
                else:
                    lines.append(' ')
            if count % 5 != 0:
                file.write(' ' + ''.join(lines) + ' \n')
            data: list | NDArray = self.data_aug.get(data_type, []) if self.data_aug is not None else []
            if isinstance(data, Iterable):
                file.write(''.join(data))
        with zopen(file_name, mode='wt', encoding='utf-8') as file:
            poscar = Poscar(self.structure)
            comment = getattr(self, 'name', poscar.comment)
            lines = f'{comment}\n'
            lines += '   1.00000000000000\n'
            for vec in self.structure.lattice.matrix:
                lines += f' {vec[0]:12.6f}{vec[1]:12.6f}{vec[2]:12.6f}\n'
            if not vasp4_compatible:
                lines += ''.join((f'{s:5}' for s in poscar.site_symbols)) + '\n'
            lines += ''.join((f'{x:6}' for x in poscar.natoms)) + '\n'
            lines += 'Direct\n'
            for site in self.structure:
                dim, b, c = site.frac_coords
                lines += f'{dim:10.6f}{b:10.6f}{c:10.6f}\n'
            lines += ' \n'
            file.write(lines)
            dim = self.dim
            write_spin('total')
            if self.is_spin_polarized:
                if self.is_soc:
                    write_spin('diff_x')
                    write_spin('diff_y')
                    write_spin('diff_z')
                else:
                    write_spin('diff')

def get_symmetrically_distinct_miller_indices(structure: Structure | IStructure, max_index: int, return_hkil: bool=False) -> list:
    rng = list(range(-max_index, max_index + 1))[::-1]
    conv_hkl_list = [miller for miller in itertools.product(rng, rng, rng) if any((i != 0 for i in miller))]
    conv_hkl_list = sorted(conv_hkl_list, key=lambda x: max(np.abs(x)))
    spg_analyzer = SpacegroupAnalyzer(structure)
    if spg_analyzer.get_crystal_system() == 'trigonal':
        transf = spg_analyzer.get_conventional_to_primitive_transformation_matrix()
        miller_list: list[tuple[int, int, int]] = [hkl_transformation(transf, hkl) for hkl in conv_hkl_list]
        prim_structure = SpacegroupAnalyzer(structure).get_primitive_standard_structure()
        symm_ops = prim_structure.lattice.get_recp_symmetry_operation()
    else:
        miller_list = conv_hkl_list
        symm_ops = structure.lattice.get_recp_symmetry_operation()
    unique_millers: list = []
    unique_millers_conv: list = []
    for idx, miller in enumerate(miller_list):
        denom = abs(reduce(math.gcd, miller))
        miller = cast('tuple[int, int, int]', tuple((int(idx / denom) for idx in miller)))
        if not _is_in_miller_family(miller, unique_millers, symm_ops):
            if spg_analyzer.get_crystal_system() == 'trigonal':
                unique_millers.append(miller)
                denom = abs(reduce(math.gcd, conv_hkl_list[idx]))
                cmiller = tuple((int(idx / denom) for idx in conv_hkl_list[idx]))
                unique_millers_conv.append(cmiller)
            else:
                unique_millers.append(miller)
                unique_millers_conv.append(miller)
    if return_hkil and spg_analyzer.get_crystal_system() in {'trigonal', 'hexagonal'}:
        return [(hkl[0], hkl[1], -1 * hkl[0] - hkl[1], hkl[2]) for hkl in unique_millers_conv]
    return unique_millers_conv

# --- helper: pymatgen.core.surface._is_in_miller_family ---
def _is_in_miller_family(miller_index: tuple[int, int, int], miller_list: Sequence[tuple[int, int, int]], symm_ops: list) -> bool:
    return any((in_coord_list(miller_list, op.operate(miller_index)) for op in symm_ops))

# --- helper: pymatgen.core.surface.hkl_transformation ---
def hkl_transformation(transf: np.ndarray, miller_index: tuple[int, ...]) -> tuple[int, int, int]:

    def math_lcm(a: int, b: int) -> int:
        return a * b // math.gcd(a, b)
    reduced_transf = reduce(math_lcm, [int(1 / i) for i in itertools.chain(*transf) if i != 0]) * transf
    reduced_transf = reduced_transf.astype(int)
    transf_hkl = np.dot(reduced_transf, miller_index)
    divisor = abs(reduce(math.gcd, transf_hkl))
    transf_hkl = np.array([idx // divisor for idx in transf_hkl])
    if sum((idx < 0 for idx in transf_hkl)) > 1:
        transf_hkl *= -1
    return tuple(transf_hkl)

