class Compatibility(MSONable, abc.ABC):

    @abc.abstractmethod
    def get_adjustments(self, entry: AnyComputedEntry) -> list[EnergyAdjustment]:
        raise NotImplementedError

    def process_entry(self, entry: TypeVarAnyEntry, inplace: bool=True, **kwargs) -> TypeVarAnyEntry | None:
        if not inplace:
            entry = copy.deepcopy(entry)
        _entry: tuple[TypeVarAnyEntry, bool] | None = self._process_entry_inplace(entry, **kwargs)
        return _entry[0] if _entry is not None else None

    def _process_entry_inplace(self, entry: TypeVarAnyEntry, clean: bool=True, on_error: Literal['ignore', 'warn', 'raise']='ignore') -> tuple[TypeVarAnyEntry, bool] | None:
        ignore_entry: bool = False
        if clean:
            entry.energy_adjustments = []
        try:
            adjustments: list[EnergyAdjustment] = self.get_adjustments(entry)
        except CompatibilityError as exc:
            if on_error == 'raise':
                raise
            if on_error == 'warn':
                warnings.warn(str(exc), stacklevel=2)
            return None
        for e_adj in adjustments:
            if (e_adj.name, e_adj.cls, e_adj.value) in [(ea2.name, ea2.cls, ea2.value) for ea2 in entry.energy_adjustments]:
                pass
            elif (e_adj.name, e_adj.cls) in [(ea2.name, ea2.cls) for ea2 in entry.energy_adjustments]:
                ignore_entry = True
                warnings.warn(f'Entry {entry.entry_id} already has an energy adjustment called {e_adj.name}, but its value differs from the value of {e_adj.value:.3f} calculated here. This Entry will be discarded.', stacklevel=2)
            else:
                entry.energy_adjustments.append(e_adj)
        return (entry, ignore_entry)

    def process_entries(self, entries: TypeVarAnyEntry | list[TypeVarAnyEntry], clean: bool=True, verbose: bool=False, inplace: bool=True, n_workers: int=1, on_error: Literal['ignore', 'warn', 'raise']='ignore') -> list[TypeVarAnyEntry]:
        if isinstance(entries, ComputedEntry):
            entries = [entries]
        processed_entry_list: list[TypeVarAnyEntry] = []
        if not inplace:
            entries = copy.deepcopy(entries)
        if n_workers == 1:
            for entry in tqdm(entries, disable=not verbose):
                result = self._process_entry_inplace(entry, clean, on_error)
                if result is None:
                    continue
                entry, ignore_entry = result
                if not ignore_entry:
                    processed_entry_list.append(entry)
        elif not inplace:
            with tqdm_joblib(tqdm(total=len(entries), disable=not verbose)), set_python_warnings('ignore'):
                results = Parallel(n_jobs=n_workers)((delayed(self._process_entry_inplace)(entry, clean, on_error) for entry in entries))
            for result in results:
                if result is None:
                    continue
                entry, ignore_entry = result
                if not ignore_entry:
                    processed_entry_list.append(entry)
        else:
            raise ValueError("Parallel processing is not possible with for 'inplace=True'")
        return processed_entry_list

    def explain(self, entry: ComputedEntry) -> None:
        print(f'The uncorrected energy of {entry.composition} is {entry.uncorrected_energy:.3f} eV ({entry.uncorrected_energy / entry.composition.num_atoms:.3f} eV/atom).')
        if len(entry.energy_adjustments) > 0:
            print('The following energy adjustments have been applied to this entry:')
            for adj in entry.energy_adjustments:
                print(f'\t\t{adj.name}: {adj.value:.3f} eV ({adj.value / entry.composition.num_atoms:.3f} eV/atom)')
        elif entry.correction == 0:
            print('No energy adjustments have been applied to this entry.')
        print(f'The final energy after adjustments is {entry.energy:.3f} eV ({entry.energy_per_atom:.3f} eV/atom).')

