def GetUniqueCombinations(choices, classes):
    assert len(choices) == len(classes)
    combos = set()
    for choice in itertools.product(*choices):
        if len(set(choice)) != len(choice):
            continue
        combos.add(tuple(sorted(((cls, ch) for cls, ch in zip(classes, choice)))))
    return [list(combo) for combo in sorted(combos)]

def compute_distance_matrix(data, n_pts, dist_func):
    dist_matrix = np.zeros((n_pts, n_pts))
    for i in range(n_pts):
        for j in range(i):
            dist_matrix[i, j] = dist_matrix[j, i] = dist_func(data[i], data[j])
    return dist_matrix

def getElementFromFlatMatrix(matrix, i, j):
    if i == j:
        return 0.0
    if i > j:
        i, j = (j, i)
    return matrix[j * (j - 1) // 2 + i]

