# --- helper: rdkit.Chem.RegistrationHash._CanonicalizeSGroups ---
def _CanonicalizeSGroups(mol, dataFieldNames=None, sortAtomAndBondOrder=True):
    dataFieldNames = dataFieldNames or ['Atrop']
    atRanks, bndOrder = _GetCanonicalAtomRanksAndBonds(mol)
    res = []
    for sg in Chem.GetMolSubstanceGroups(mol):
        lres = None
        if sg.GetProp('TYPE') == 'DAT':
            lres = _CanonicalizeDataSGroup(sg, atRanks, bndOrder, dataFieldNames, sortAtomAndBondOrder)
        elif sg.GetProp('TYPE') == 'SRU':
            lres = _CanonicalizeSRUSGroup(mol, sg, atRanks, bndOrder, sortAtomAndBondOrder)
        elif sg.GetProp('TYPE') == 'COP':
            lres = _CanonicalizeCOPSGroup(sg, atRanks, sortAtomAndBondOrder)
        if lres is not None:
            res.append(lres)
    if len(res) > 1:
        tres = sorted((tuple(x.items()) for x in res))
        res = tuple((dict(x) for x in tres))
        idxmap = {}
        for i, itm in enumerate(res):
            if 'index' in itm:
                idxmap[itm['index']] = i + 1
                itm['index'] = i + 1
        for i, itm in enumerate(res):
            if 'PARENT' in itm:
                itm['PARENT'] = idxmap[itm['PARENT']]
    return json.dumps(res)

# --- helper: rdkit.Chem.RegistrationHash._RemoveUnnecessaryHs ---
def _RemoveUnnecessaryHs(rdk_mol, preserve_stereogenic_hs=False):
    remove_hs_params = Chem.RemoveHsParameters()
    remove_hs_params.updateExplicitCount = True
    remove_hs_params.removeDefiningBondStereo = not preserve_stereogenic_hs
    edited_mol = Chem.rdmolops.RemoveHs(rdk_mol, remove_hs_params, sanitize=False)
    edited_mol.UpdatePropertyCache(False)
    return edited_mol

# --- helper: rdkit.Chem.RegistrationHash._StripAtomMapLabels ---
def _StripAtomMapLabels(mol):
    for at in mol.GetAtoms():
        at.ClearProp(ATOM_PROP_MAP_NUMBER)

class OnFlySymMatrix:

    def __init__(self, get_row: Callable[[Any], np.ndarray], shape: tuple[int, int], *, rows: MutableMapping[Any, np.ndarray] | None=None, restrict_array: np.ndarray | None=None):
        self.get_row = get_row
        self.shape = shape
        self.rows = {} if rows is None else rows
        self.restrict_array = restrict_array

    def __getitem__(self, index):
        if isinstance(index, int | np.integer):
            if self.restrict_array is None:
                glob_index = index
            else:
                glob_index = self.restrict_array[index]
            if glob_index not in self.rows:
                self.rows[glob_index] = self.get_row(glob_index)
            row = self.rows[glob_index]
            if self.restrict_array is None:
                return row
            else:
                return row[self.restrict_array]
        else:
            if self.restrict_array is None:
                glob_index_0, glob_index_1 = index
            else:
                glob_index_0 = self.restrict_array[index[0]]
                glob_index_1 = self.restrict_array[index[1]]
            if glob_index_0 not in self.rows:
                self.rows[glob_index_0] = self.get_row(glob_index_0)
            return self.rows[glob_index_0][glob_index_1]

    def restrict(self, index_array):
        new_shape = (index_array.shape[0], index_array.shape[0])
        return OnFlySymMatrix(self.get_row, new_shape, rows=self.rows, restrict_array=index_array)

def aggregate(adata: AnnData, by: str | Collection[str], func: AggType | Iterable[AggType], *, axis: Literal['obs', 0, 'var', 1] | None=None, mask: NDArray[np.bool_] | str | None=None, dof: int=1, layer: str | None=None, obsm: str | None=None, varm: str | None=None) -> AnnData:
    if not isinstance(adata, AnnData):
        msg = f'sc.get.aggregate is currently only implemented for AnnData input, was passed {type(adata)}.'
        raise NotImplementedError(msg)
    if axis is None:
        axis = 1 if varm else 0
    axis, axis_name = _resolve_axis(axis)
    mask = _check_mask(adata, mask, axis_name)
    data = adata.X
    if sum((p is not None for p in [varm, obsm, layer])) > 1:
        msg = 'Please only provide one (or none) of varm, obsm, or layer'
        raise TypeError(msg)
    if varm is not None:
        if axis != 1:
            msg = 'varm can only be used when axis is 1'
            raise ValueError(msg)
        data = adata.varm[varm]
    elif obsm is not None:
        if axis != 0:
            msg = 'obsm can only be used when axis is 0'
            raise ValueError(msg)
        data = adata.obsm[obsm]
    elif layer is not None:
        data = adata.layers[layer]
        if axis == 1:
            data = data.T
    elif axis == 1:
        data = data.T
    dim_df = getattr(adata, axis_name)
    categorical, new_label_df = _combine_categories(dim_df, by)
    layers = _aggregate(data, by=categorical, func=func, mask=mask, dof=dof)
    if obsm or varm:
        if isinstance(data, pd.DataFrame):
            var = pd.DataFrame(index=data.columns)
        else:
            var = pd.DataFrame(index=pd.RangeIndex(data.shape[1]).astype(str))
    else:
        var = getattr(adata, 'var' if axis == 0 else 'obs')
    result = AnnData(layers=layers, obs=new_label_df, var=var)
    if axis == 1:
        return result.T
    else:
        return result

# --- helper: scanpy.get._aggregated._aggregate ---
@singledispatch
def _aggregate(data, by: pd.Categorical, func: AggType | Iterable[AggType], *, mask: NDArray[np.bool_] | None=None, dof: int=1):
    msg = f'Data type {type(data)} not supported for aggregation'
    raise NotImplementedError(msg)

# --- helper: scanpy.get._aggregated._combine_categories ---
def _combine_categories(label_df: pd.DataFrame, cols: Collection[str] | str) -> tuple[pd.Categorical, pd.DataFrame]:
    from itertools import product
    if isinstance(cols, str):
        cols = [cols]
    df = pd.DataFrame({c: pd.Categorical(label_df[c]).remove_unused_categories() for c in cols})
    n_categories = [len(df[c].cat.categories) for c in cols]
    code_combinations = np.indices(n_categories).reshape(len(n_categories), -1)
    result_categories = pd.Index(['_'.join(map(str, x)) for x in product(*[df[c].cat.categories for c in cols])])
    new_label_df = pd.DataFrame({c: pd.Categorical.from_codes(code_combinations[i], df[c].cat.categories) for i, c in enumerate(cols)}, index=result_categories)
    factors = np.ones(len(cols) + 1, dtype=np.int32)
    np.cumprod(n_categories[::-1], out=factors[1:])
    factors = factors[:-1][::-1]
    code_array = np.zeros((len(cols), df.shape[0]), dtype=np.int32)
    for i, c in enumerate(cols):
        code_array[i] = df[c].cat.codes
    code_array *= factors[:, None]
    result_categorical = pd.Categorical.from_codes(code_array.sum(axis=0), categories=result_categories)
    result_categorical = result_categorical.remove_unused_categories()
    new_label_df = new_label_df.loc[result_categorical.categories]
    return (result_categorical, new_label_df)

def is_valid_filename(filename: Path, *, return_ext: bool=False, ext: str | None=None) -> str | bool:
    ext_from_file = filename.suffixes
    if ext is not None:
        if not (joined_file_ext := '.'.join(ext_from_file)).endswith(ext):
            msg = f'{joined_file_ext} does not end in expected extension {ext}'
            raise ValueError(msg)
        return ext if return_ext else True
    if len(ext_from_file) > 2:
        logg.warning(f'Your filename has more than two extensions: {ext_from_file}.\nOnly considering the two last: {ext_from_file[-2:]}.')
        ext_from_file = ext_from_file[-2:]
    if len(ext_from_file) == 2 and ext_from_file[0][1:] in text_exts and (ext_from_file[1][1:] in ('gz', 'bz2')):
        return ext_from_file[0][1:] if return_ext else True
    elif ext_from_file and ext_from_file[-1][1:] in avail_exts:
        return ext_from_file[-1][1:] if return_ext else True
    elif ''.join(ext_from_file) == '.soft.gz':
        return 'soft.gz' if return_ext else True
    elif ''.join(ext_from_file) == '.mtx.gz':
        return 'mtx.gz' if return_ext else True
    elif not return_ext:
        return False
    msg = f'{filename!r} does not end on a valid extension.\nPlease, provide one of the available extensions.\n{avail_exts}\nText files with .gz and .bz2 extensions are also supported.'
    raise ValueError(msg)

