def leiden(adata: AnnData, resolution: float=1, *, restrict_to: tuple[str, Sequence[str]] | None=None, random_state: _LegacyRandom=0, key_added: str='leiden', adjacency: CSBase | None=None, directed: bool | None=None, use_weights: bool=True, n_iterations: int=-1, partition_type: type[MutableVertexPartition] | None=None, neighbors_key: str | None=None, obsp: str | None=None, copy: bool=False, flavor: Literal['leidenalg', 'igraph']='leidenalg', **clustering_args) -> AnnData | None:
    if flavor not in {'igraph', 'leidenalg'}:
        msg = f"flavor must be either 'igraph' or 'leidenalg', but {flavor!r} was passed"
        raise ValueError(msg)
    _utils.ensure_igraph()
    if flavor == 'igraph':
        if directed:
            msg = 'Cannot use igraph’s leiden implementation with a directed graph.'
            raise ValueError(msg)
        if partition_type is not None:
            msg = 'Do not pass in partition_type argument when using igraph.'
            raise ValueError(msg)
    else:
        try:
            import leidenalg
            msg = 'In the future, the default backend for leiden will be igraph instead of leidenalg.\n\n To achieve the future defaults please pass: flavor="igraph" and n_iterations=2.  directed must also be False to work with igraph\'s implementation.'
            _utils.warn_once(msg, FutureWarning, stacklevel=3)
        except ImportError as e:
            msg = 'Please install the leiden algorithm: `conda install -c conda-forge leidenalg` or `pip3 install leidenalg`.'
            raise ImportError(msg) from e
    clustering_args = dict(clustering_args)
    start = logg.info('running Leiden clustering')
    adata = adata.copy() if copy else adata
    if adjacency is None:
        adjacency = _utils._choose_graph(adata, obsp, neighbors_key)
    if restrict_to is not None:
        restrict_key, restrict_categories = restrict_to
        adjacency, restrict_indices = restrict_adjacency(adata, restrict_key, restrict_categories=restrict_categories, adjacency=adjacency)
    clustering_args['n_iterations'] = n_iterations
    if flavor == 'leidenalg':
        if resolution is not None:
            clustering_args['resolution_parameter'] = resolution
        directed = True if directed is None else directed
        g = _utils.get_igraph_from_adjacency(adjacency, directed=directed)
        if partition_type is None:
            partition_type = leidenalg.RBConfigurationVertexPartition
        if use_weights:
            clustering_args['weights'] = np.array(g.es['weight']).astype(np.float64)
        clustering_args['seed'] = random_state
        part = leidenalg.find_partition(g, partition_type, **clustering_args)
    else:
        g = _utils.get_igraph_from_adjacency(adjacency, directed=False)
        if use_weights:
            clustering_args['weights'] = 'weight'
        if resolution is not None:
            clustering_args['resolution'] = resolution
        clustering_args.setdefault('objective_function', 'modularity')
        with set_igraph_random_state(random_state):
            part = g.community_leiden(**clustering_args)
    groups = np.array(part.membership)
    if restrict_to is not None:
        if key_added == 'leiden':
            key_added += '_R'
        groups = rename_groups(adata, key_added=key_added, restrict_key=restrict_key, restrict_categories=restrict_categories, restrict_indices=restrict_indices, groups=groups)
    adata.obs[key_added] = pd.Categorical(values=groups.astype('U'), categories=natsorted(map(str, np.unique(groups))))
    adata.uns[key_added] = {}
    adata.uns[key_added]['params'] = dict(resolution=resolution, random_state=random_state, n_iterations=n_iterations)
    logg.info('    finished', time=start, deep=f'found {len(np.unique(groups))} clusters and added\n    {key_added!r}, the cluster labels (adata.obs, categorical)')
    return adata if copy else None

