@set_module('numpy.fft')
def rfftfreq(n, d=1.0, device=None):
    if not isinstance(n, integer_types):
        raise ValueError('n should be an integer')
    val = 1.0 / (n * d)
    N = n // 2 + 1
    results = arange(0, N, dtype=int, device=device)
    return results * val

@finalize_array_function_like
@set_module('numpy')
def full(shape, fill_value, dtype=None, order='C', *, device=None, like=None):
    if like is not None:
        return _full_with_like(like, shape, fill_value, dtype=dtype, order=order, device=device)
    if dtype is None:
        fill_value = asarray(fill_value)
        dtype = fill_value.dtype
    a = empty(shape, dtype, order, device=device)
    multiarray.copyto(a, fill_value, casting='unsafe')
    return a

def argsort(a, axis=np._NoValue, kind=None, order=None, endwith=True, fill_value=None, *, stable=None):
    a = np.asanyarray(a)
    if axis is np._NoValue:
        axis = _deprecate_argsort_axis(a)
    if isinstance(a, MaskedArray):
        return a.argsort(axis=axis, kind=kind, order=order, endwith=endwith, fill_value=fill_value, stable=None)
    else:
        return a.argsort(axis=axis, kind=kind, order=order, stable=None)

# --- helper: numpy.ma.core._deprecate_argsort_axis ---
def _deprecate_argsort_axis(arr):
    if arr.ndim <= 1:
