                index = _extract_index(arrays)
        else:
            index = ensure_index(index)
        if midxs and (not is_integer_dtype(dtype)):
            for i in midxs:
                arr = construct_1d_arraylike_from_scalar(arrays[i], len(index), dtype if dtype is not None else np.dtype('object'))
