@set_module('pandas')
def concat(objs: Iterable[Series | DataFrame] | Mapping[HashableT, Series | DataFrame], *, axis: Axis=0, join: str='outer', ignore_index: bool=False, keys: Iterable[Hashable] | None=None, levels=None, names: list[HashableT] | None=None, verify_integrity: bool=False, sort: bool | lib.NoDefault=lib.no_default, copy: bool | lib.NoDefault=lib.no_default) -> DataFrame | Series:
    if ignore_index and keys is not None:
        raise ValueError(f'Cannot set ignore_index={ignore_index!r} and specify keys. Either should be used.')
    if copy is not lib.no_default:
        warnings.warn('The copy keyword is deprecated and will be removed in a future version. Copy-on-Write is active in pandas since 3.0 which utilizes a lazy copy mechanism that defers copies until necessary. Use .copy() to make an eager copy if necessary.', Pandas4Warning, stacklevel=find_stack_level())
    if join == 'outer':
        intersect = False
    elif join == 'inner':
        intersect = True
    else:
        raise ValueError('Only can inner (intersect) or outer (union) join the other axis')
    objs, keys, ndims = _clean_keys_and_objs(objs, keys)
    if sort is lib.no_default:
        if axis == 0:
            non_concat_axis = [obj.columns if isinstance(obj, ABCDataFrame) else Index([obj.name]) for obj in objs]
        else:
            non_concat_axis = [obj.index for obj in objs]
        if intersect or any((not isinstance(index, DatetimeIndex) for index in non_concat_axis)) or all((prev is curr for prev, curr in pairwise(non_concat_axis))) or (all((prev[-1] <= curr[0] and prev.is_monotonic_increasing for prev, curr in pairwise(non_concat_axis) if not prev.empty and (not curr.empty))) and non_concat_axis[-1].is_monotonic_increasing):
            sort = False
    elif not is_bool(sort):
        raise ValueError(f"The 'sort' keyword only accepts boolean values; {sort} was passed.")
    else:
        sort = bool(sort)
    sample, objs = _get_sample_object(objs, ndims, keys, names, levels, intersect)
    if sample.ndim == 1:
        from pandas import DataFrame
        bm_axis = DataFrame._get_axis_number(axis)
        is_frame = False
        is_series = True
    else:
        bm_axis = sample._get_axis_number(axis)
        is_frame = True
        is_series = False
        bm_axis = sample._get_block_manager_axis(bm_axis)
    if len(ndims) > 1:
        objs = _sanitize_mixed_ndim(objs, sample, ignore_index, bm_axis)
    orig_axis = axis
    axis = 1 - bm_axis if is_frame else 0
    names = names or getattr(keys, 'names', None)
    result = _get_result(objs, is_series, bm_axis, ignore_index, intersect, sort, keys, levels, verify_integrity, names, axis)
    if sort is lib.no_default:
        if orig_axis == 0:
            non_concat_axis = [obj.columns if isinstance(obj, ABCDataFrame) else Index([obj.name]) for obj in objs]
        else:
            non_concat_axis = [obj.index for obj in objs]
        no_sort_result_index = union_indexes(non_concat_axis, sort=False)
        orig = result.index if orig_axis == 1 else result.columns
        if not no_sort_result_index.equals(orig):
            msg = 'Sorting by default when concatenating all DatetimeIndex is deprecated.  In the future, pandas will respect the default of `sort=False`. Specify `sort=True` or `sort=False` to silence this message. If you see this warnings when not directly calling concat, report a bug to pandas.'
            warnings.warn(msg, Pandas4Warning, stacklevel=find_stack_level())
    return result

class ADBCDatabase(PandasSQL):

    def __init__(self, con) -> None:
        self.con = con

    @contextmanager
    def run_transaction(self):
        with self.con.cursor() as cur:
            try:
                yield cur
            except Exception:
                self.con.rollback()
                raise
            self.con.commit()

    def execute(self, sql: str | Select | TextClause, params=None):
        from adbc_driver_manager import Error
        if not isinstance(sql, str):
            raise TypeError('Query must be a string unless using sqlalchemy.')
        args = [] if params is None else [params]
        cur = self.con.cursor()
        try:
            cur.execute(sql, *args)
            return cur
        except Error as exc:
            try:
                self.con.rollback()
            except Error as inner_exc:
                ex = DatabaseError(f'Execution failed on sql: {sql}\n{exc}\nunable to rollback')
                raise ex from inner_exc
            ex = DatabaseError(f"Execution failed on sql '{sql}': {exc}")
            raise ex from exc

    def read_table(self, table_name: str, index_col: str | list[str] | None=None, coerce_float: bool=True, parse_dates=None, columns=None, schema: str | None=None, chunksize: int | None=None, dtype_backend: DtypeBackend | Literal['numpy']='numpy') -> DataFrame | Iterator[DataFrame]:
        if coerce_float is not True:
            raise NotImplementedError("'coerce_float' is not implemented for ADBC drivers")
        if chunksize:
            raise NotImplementedError("'chunksize' is not implemented for ADBC drivers")
        if columns:
            if index_col:
                index_select = maybe_make_list(index_col)
            else:
                index_select = []
            to_select = index_select + columns
            select_list = ', '.join((f'"{x}"' for x in to_select))
        else:
            select_list = '*'
        if schema:
            stmt = f'SELECT {select_list} FROM {schema}.{table_name}'
        else:
            stmt = f'SELECT {select_list} FROM {table_name}'
        with self.execute(stmt) as cur:
            pa_table = cur.fetch_arrow_table()
            df = arrow_table_to_pandas(pa_table, dtype_backend=dtype_backend)
        return _wrap_result_adbc(df, index_col=index_col, parse_dates=parse_dates)

    def read_query(self, sql: str, index_col: str | list[str] | None=None, coerce_float: bool=True, parse_dates=None, params=None, chunksize: int | None=None, dtype: DtypeArg | None=None, dtype_backend: DtypeBackend | Literal['numpy']='numpy') -> DataFrame | Iterator[DataFrame]:
        if coerce_float is not True:
            raise NotImplementedError("'coerce_float' is not implemented for ADBC drivers")
        if params:
            raise NotImplementedError("'params' is not implemented for ADBC drivers")
        if chunksize:
            raise NotImplementedError("'chunksize' is not implemented for ADBC drivers")
        with self.execute(sql) as cur:
            pa_table = cur.fetch_arrow_table()
            df = arrow_table_to_pandas(pa_table, dtype_backend=dtype_backend)
        return _wrap_result_adbc(df, index_col=index_col, parse_dates=parse_dates, dtype=dtype)
    read_sql = read_query

    def to_sql(self, frame, name: str, if_exists: Literal['fail', 'replace', 'append', 'delete_rows']='fail', index: bool=True, index_label=None, schema: str | None=None, chunksize: int | None=None, dtype: DtypeArg | None=None, method: Literal['multi'] | Callable | None=None, engine: str='auto', **engine_kwargs) -> int | None:
        pa = import_optional_dependency('pyarrow')
        from adbc_driver_manager import Error
        if index_label:
            raise NotImplementedError("'index_label' is not implemented for ADBC drivers")
        if chunksize:
            raise NotImplementedError("'chunksize' is not implemented for ADBC drivers")
        if dtype:
            raise NotImplementedError("'dtype' is not implemented for ADBC drivers")
        if method:
            raise NotImplementedError("'method' is not implemented for ADBC drivers")
        if engine != 'auto':
            raise NotImplementedError("engine != 'auto' not implemented for ADBC drivers")
        if schema:
            table_name = f'{schema}.{name}'
        else:
            table_name = name
        mode = 'create'
        if self.has_table(name, schema):
            if if_exists == 'fail':
                raise ValueError(f"Table '{table_name}' already exists.")
            elif if_exists == 'replace':
                sql_statement = f'DROP TABLE {table_name}'
                self.execute(sql_statement).close()
            elif if_exists == 'append':
                mode = 'append'
            elif if_exists == 'delete_rows':
                mode = 'append'
                self.delete_rows(name, schema)
        try:
            tbl = pa.Table.from_pandas(frame, preserve_index=index)
        except pa.ArrowNotImplementedError as exc:
            raise ValueError('datatypes not supported') from exc
        with self.con.cursor() as cur:
            try:
                total_inserted = cur.adbc_ingest(table_name=name, data=tbl, mode=mode, db_schema_name=schema)
            except Error as exc:
                raise DatabaseError(f'Failed to insert records on table={name} with mode={mode!r}') from exc
        self.con.commit()
        return total_inserted

    def has_table(self, name: str, schema: str | None=None) -> bool:
        meta = self.con.adbc_get_objects(db_schema_filter=schema, table_name_filter=name).read_all()
        for catalog_schema in meta['catalog_db_schemas'].to_pylist():
            if not catalog_schema:
                continue
            for schema_record in catalog_schema:
                if not schema_record:
                    continue
                for table_record in schema_record['db_schema_tables']:
                    if table_record['table_name'] == name:
                        return True
        return False

    def delete_rows(self, name: str, schema: str | None=None) -> None:
        table_name = f'{schema}.{name}' if schema else name
        if self.has_table(name, schema):
            self.execute(f'DELETE FROM {table_name}').close()

    def _create_sql_schema(self, frame: DataFrame, table_name: str, keys: list[str] | None=None, dtype: DtypeArg | None=None, schema: str | None=None) -> str:
        raise NotImplementedError('not implemented for adbc')

