@xp_capabilities(cpu_only=True, xfail_backends=[('dask.array', 'lacks nd fancy indexing'), ('jax.numpy', 'immutable arrays'), ('array_api_strict', 'fancy indexing __setitem__')])
class Akima1DInterpolator(CubicHermiteSpline):
    __class_getitem__ = None

    def __init__(self, x, y, axis=0, *, method: Literal['akima', 'makima']='akima', extrapolate: bool | None=None):
        if method not in {'akima', 'makima'}:
            raise NotImplementedError(f'`method`={method} is unsupported.')
        xp = array_namespace(x, y)
        x, dx, y, axis, _ = prepare_input(x, y, axis, xp=xp)
        if xp.isdtype(y.dtype, 'complex floating'):
            msg = '`Akima1DInterpolator` only works with real values for `y`. If you are trying to use the real components of the passed array, use `np.real` on the array before passing to `Akima1DInterpolator`.'
            raise ValueError(msg)
        extrapolate = False if extrapolate is None else extrapolate
        if y.shape[0] == 2:
            xv = xp.reshape(x, (x.shape[0],) + (1,) * (y.ndim - 1))
            hk = xv[1:, ...] - xv[:-1, ...]
            mk = (y[1:, ...] - y[:-1, ...]) / hk
            t = xp.zeros_like(y)
            t[...] = mk
        else:
            m = xp.empty((x.shape[0] + 3,) + y.shape[1:])
            dx = dx[(slice(None),) + (None,) * (y.ndim - 1)]
            m[2:-2, ...] = xp.diff(y, axis=0) / dx
            m[1, ...] = 2.0 * m[2, ...] - m[3, ...]
            m[0, ...] = 2.0 * m[1, ...] - m[2, ...]
            m[-2, ...] = 2.0 * m[-3, ...] - m[-4, ...]
            m[-1, ...] = 2.0 * m[-2, ...] - m[-3, ...]
            t = 0.5 * (m[3:, ...] + m[:-3, ...])
            dm = xp.abs(xp.diff(m, axis=0))
            if method == 'makima':
                pm = xp.abs(m[1:, ...] + m[:-1, ...])
                f1 = dm[2:, ...] + 0.5 * pm[2:, ...]
                f2 = dm[:-2, ...] + 0.5 * pm[:-2, ...]
            else:
                f1 = dm[2:, ...]
                f2 = dm[:-2, ...]
            break_mult = 1e-09
            f12 = f1 + f2
            mmax = xp.max(f12) if xp_size(f12) > 0 else -xp.inf
            ind = xp.nonzero(f12 > break_mult * mmax)
            x_ind, y_ind = (ind[0], ind[1:])
            t[ind] = m[(x_ind + 1,) + y_ind] + f2[ind] / f12[ind] * (m[(x_ind + 2,) + y_ind] - m[(x_ind + 1,) + y_ind])
        super().__init__(x, y, t, axis=0, extrapolate=extrapolate)
        self.axis = axis

    def extend(self, c, x, right=True):
        raise NotImplementedError('Extending a 1-D Akima interpolator is not yet implemented')

    @classmethod
    def from_spline(cls, tck, extrapolate=None):
        raise NotImplementedError('This method does not make sense for an Akima interpolator.')

    @classmethod
    def from_bernstein_basis(cls, bp, extrapolate=None):
        raise NotImplementedError('This method does not make sense for an Akima interpolator.')

