@xp_capabilities(cpu_only=True, jax_jit=False, skip_backends=[('dask.array', 'https://github.com/data-apis/array-api-extra/issues/488')])
class CubicHermiteSpline(PPoly):

    def __init__(self, x, y, dydx, axis=0, extrapolate=None):
        xp = array_namespace(x, y, dydx)
        if extrapolate is None:
            extrapolate = True
        x, dx, y, axis, dydx = prepare_input(x, y, axis, dydx, xp=xp)
        dxr = xp.reshape(dx, (dx.shape[0],) + (1,) * (y.ndim - 1))
        slope = xp.diff(y, axis=0) / dxr
        t = (dydx[:-1, ...] + dydx[1:, ...] - 2 * slope) / dxr
        c = xp.stack((t / dxr, (slope - dydx[:-1, ...]) / dxr - t, dydx[:-1, ...], y[:-1, ...]))
        super().__init__(c, x, extrapolate=extrapolate)
        self.axis = axis

# --- helper: scipy.interpolate._cubic.prepare_input ---
def prepare_input(x, y, axis, dydx=None, xp=None):
    x, y = map(xp.asarray, (x, y))
    if xp.isdtype(x.dtype, 'complex floating'):
        raise ValueError('`x` must contain real values.')
    x = xp.astype(x, xp.float64)
    if xp.isdtype(y.dtype, 'complex floating'):
        dtype = xp.complex128
    else:
        dtype = xp.float64
    if dydx is not None:
        dydx = xp.asarray(dydx)
        if y.shape != dydx.shape:
            raise ValueError('The shapes of `y` and `dydx` must be identical.')
        if xp.isdtype(dydx.dtype, 'complex floating'):
            dtype = xp.complex128
        dydx = xp.astype(dydx, dtype, copy=False)
    y = xp.astype(y, dtype, copy=False)
    axis = axis % y.ndim
    if x.ndim != 1:
        raise ValueError('`x` must be 1-dimensional.')
    if x.shape[0] < 2:
        raise ValueError('`x` must contain at least 2 elements.')
    if x.shape[0] != y.shape[axis]:
        raise ValueError(f"The length of `y` along `axis`={axis} doesn't match the length of `x`")
    if not xp.all(xp.isfinite(x)):
        raise ValueError('`x` must contain only finite values.')
    if not xp.all(xp.isfinite(y)):
        raise ValueError('`y` must contain only finite values.')
    if dydx is not None and (not xp.all(xp.isfinite(dydx))):
        raise ValueError('`dydx` must contain only finite values.')
    dx = xp.diff(x)
    if xp.any(dx <= 0):
        raise ValueError('`x` must be strictly increasing sequence.')
    y = xp.moveaxis(y, axis, 0)
    if dydx is not None:
        dydx = xp.moveaxis(dydx, axis, 0)
    return (x, dx, y, axis, dydx)

class BarycentricInterpolator(_Interpolator1DWithDerivatives):

    @_transition_to_rng('random_state', replace_doc=False)
    def __init__(self, xi, yi=None, axis=0, *, wi=None, rng=None):
        super().__init__(xi, yi, axis)
        rng = check_random_state(rng)
        self.xi = np.asarray(xi, dtype=np.float64)
        self.set_yi(yi)
        self.n = len(self.xi)
        self._diff_cij = None
        if wi is not None:
            self.wi = wi
        else:
            self._inv_capacity = 4.0 / (np.max(self.xi) - np.min(self.xi))
            permute = rng.permutation(self.n)
            inv_permute = np.zeros(self.n, dtype=np.int32)
            inv_permute[permute] = np.arange(self.n)
            self.wi = np.zeros(self.n)
            for i in range(self.n):
                dist = self._inv_capacity * (self.xi[i] - self.xi[permute])
                dist[inv_permute[i]] = 1.0
                prod = np.prod(dist)
                if prod == 0.0:
                    raise ValueError('Interpolation points xi must be distinct.')
                self.wi[i] = 1.0 / prod

    def set_yi(self, yi, axis=None):
        if yi is None:
            self.yi = None
            return
        self._set_yi(yi, xi=self.xi, axis=axis)
        self.yi = self._reshape_yi(yi)
        self.n, self.r = self.yi.shape
        self._diff_baryint = None

    def add_xi(self, xi, yi=None):
        if yi is not None:
            if self.yi is None:
                raise ValueError('No previous yi value to update!')
            yi = self._reshape_yi(yi, check=True)
            self.yi = np.vstack((self.yi, yi))
        elif self.yi is not None:
            raise ValueError('No update to yi provided!')
        old_n = self.n
        self.xi = np.concatenate((self.xi, xi))
        self.n = len(self.xi)
        self.wi **= -1
        old_wi = self.wi
        self.wi = np.zeros(self.n)
        self.wi[:old_n] = old_wi
        for j in range(old_n, self.n):
            self.wi[:j] *= self._inv_capacity * (self.xi[j] - self.xi[:j])
            self.wi[j] = np.multiply.reduce(self._inv_capacity * (self.xi[:j] - self.xi[j]))
        self.wi **= -1
        self._diff_cij = None
        self._diff_baryint = None

    def __call__(self, x):
        return _Interpolator1D.__call__(self, x)

    def _evaluate(self, x):
        if x.size == 0:
            p = np.zeros((0, self.r), dtype=self.dtype)
        else:
            c = x[..., np.newaxis] - self.xi
            z = c == 0
            c[z] = 1
            c = self.wi / c
            with np.errstate(divide='ignore'):
                p = np.dot(c, self.yi) / np.sum(c, axis=-1)[..., np.newaxis]
            r = np.nonzero(z)
            if len(r) == 1:
                if len(r[0]) > 0:
                    p = self.yi[r[0][0]]
            else:
                p[r[:-1]] = self.yi[r[-1]]
        return p

    def derivative(self, x, der=1):
        x, x_shape = self._prepare_x(x)
        y = self._evaluate_derivatives(x, der + 1, all_lower=False)
        return self._finish_y(y, x_shape)

    def _evaluate_derivatives(self, x, der=None, all_lower=True):
        if not all_lower and (x.size == 0 or self.r == 0):
            return np.zeros((0, self.r), dtype=self.dtype)
        if not all_lower and der == 1:
            return self._evaluate(x)
        if not all_lower and der > self.n:
            return np.zeros((len(x), self.r), dtype=self.dtype)
        if der is None:
            der = self.n
        if all_lower and (x.size == 0 or self.r == 0):
            return np.zeros((der, len(x), self.r), dtype=self.dtype)
        if self._diff_cij is None:
            c = self.xi[:, np.newaxis] - self.xi
            np.fill_diagonal(c, 1)
            c = self.wi / (c * self.wi[..., np.newaxis])
            np.fill_diagonal(c, 0)
            d = -c.sum(axis=1)
            np.fill_diagonal(c, d)
            self._diff_cij = c
        if self._diff_baryint is None:
            self._diff_baryint = BarycentricInterpolator(xi=self.xi, yi=self._diff_cij @ self.yi, wi=self.wi)
            self._diff_baryint._diff_cij = self._diff_cij
        if all_lower:
            cn = np.zeros((der, len(x), self.r), dtype=self.dtype)
            for d in range(der):
                cn[d, :, :] = self._evaluate_derivatives(x, d + 1, all_lower=False)
            return cn
        return self._diff_baryint._evaluate_derivatives(x, der - 1, all_lower=False)

