class _Interpolator1D:
    __slots__ = ('_y_axis', '_y_extra_shape', 'dtype')
    __class_getitem__ = classmethod(GenericAlias)

    def __init__(self, xi=None, yi=None, axis=None):
        self._y_axis = axis
