            self._set_yi(yi, xi=xi, axis=axis)

    def __call__(self, x):
        x, x_shape = self._prepare_x(x)
        y = self._evaluate(x)
        return self._finish_y(y, x_shape)

    def _evaluate(self, x):
        raise NotImplementedError()

    def _prepare_x(self, x):
        x = _asarray_validated(x, check_finite=False, as_inexact=True)
        x_shape = x.shape
        return (x.ravel(), x_shape)

    def _finish_y(self, y, x_shape):
        y = y.reshape(x_shape + self._y_extra_shape)
        if self._y_axis != 0 and x_shape != ():
            nx = len(x_shape)
            ny = len(self._y_extra_shape)
            s = list(range(nx, nx + self._y_axis)) + list(range(nx)) + list(range(nx + self._y_axis, nx + ny))
            y = y.transpose(s)
        return y

    def _reshape_yi(self, yi, check=False):
        yi = np.moveaxis(np.asarray(yi), self._y_axis, 0)
        if check and yi.shape[1:] != self._y_extra_shape:
            ok_shape = f'{self._y_extra_shape[-self._y_axis:]!r} + (N,) + {self._y_extra_shape[:-self._y_axis]!r}'
            raise ValueError(f'Data must be of shape {ok_shape}')
