class _Interpolator1DWithDerivatives(_Interpolator1D):

    def derivatives(self, x, der=None):
        x, x_shape = self._prepare_x(x)
        y = self._evaluate_derivatives(x, der)
        y = y.reshape((y.shape[0],) + x_shape + self._y_extra_shape)
        if self._y_axis != 0 and x_shape != ():
            nx = len(x_shape)
            ny = len(self._y_extra_shape)
            s = [0] + list(range(nx + 1, nx + self._y_axis + 1)) + list(range(1, nx + 1)) + list(range(nx + 1 + self._y_axis, nx + ny + 1))
            y = y.transpose(s)
        return y

    def derivative(self, x, der=1):
        x, x_shape = self._prepare_x(x)
        y = self._evaluate_derivatives(x, der + 1)
        return self._finish_y(y[der], x_shape)

    def _evaluate_derivatives(self, x, der=None):
        raise NotImplementedError()

@xp_capabilities(out_of_scope=True)
class RectBivariateSpline(BivariateSpline):

    def __init__(self, x, y, z, bbox=[None] * 4, kx=3, ky=3, s=0, maxit=20):
        x, y, bbox = (ravel(x), ravel(y), ravel(bbox))
        z = np.asarray(z)
        if not np.all(diff(x) > 0.0):
            raise ValueError('x must be strictly increasing')
        if not np.all(diff(y) > 0.0):
            raise ValueError('y must be strictly increasing')
        if not x.size == z.shape[0]:
            raise ValueError('x dimension of z must have same number of elements as x')
        if not y.size == z.shape[1]:
            raise ValueError('y dimension of z must have same number of elements as y')
        if not bbox.shape == (4,):
            raise ValueError('bbox shape should be (4,)')
        if s is not None and (not s >= 0.0):
            raise ValueError('s should be s >= 0.0')
        z = ravel(z)
        xb, xe, yb, ye = bbox
        with FITPACK_LOCK:
            nx, tx, ny, ty, c, fp, ier = dfitpack.regrid_smth(x, y, z, xb, xe, yb, ye, kx, ky, s, maxit)
        if ier not in [0, -1, -2]:
            msg = _surfit_messages.get(ier, f'ier={ier}')
            raise ValueError(msg)
        self.fp = fp
        self.tck = (tx[:nx], ty[:ny], c[:(nx - kx - 1) * (ny - ky - 1)])
        self.degrees = (kx, ky)

# --- helper: scipy.interpolate._fitpack2.BivariateSpline ---
@xp_capabilities(out_of_scope=True)
class BivariateSpline(_BivariateSplineBase):

    def ev(self, xi, yi, dx=0, dy=0):
        return self.__call__(xi, yi, dx=dx, dy=dy, grid=False)

    def integral(self, xa, xb, ya, yb):
        tx, ty, c = self.tck[:3]
        kx, ky = self.degrees
        with FITPACK_LOCK:
            return dfitpack.dblint(tx, ty, c, kx, ky, xa, xb, ya, yb)

    @staticmethod
    def _validate_input(x, y, z, w, kx, ky, eps):
        x, y, z = (np.asarray(x), np.asarray(y), np.asarray(z))
        if not x.size == y.size == z.size:
            raise ValueError('x, y, and z should have a same length')
        if w is not None:
            w = np.asarray(w)
            if x.size != w.size:
                raise ValueError('x, y, z, and w should have a same length')
            elif not np.all(w >= 0.0):
                raise ValueError('w should be positive')
        if eps is not None and (not 0.0 < eps < 1.0):
            raise ValueError('eps should be between (0, 1)')
        if not x.size >= (kx + 1) * (ky + 1):
            raise ValueError('The length of x, y and z should be at least (kx+1) * (ky+1)')
        return (x, y, z, w)

@xp_capabilities(cpu_only=True, jax_jit=False, skip_backends=[('dask.array', 'https://github.com/data-apis/array-api-extra/issues/488')])
class RegularGridInterpolator:
    _SPLINE_DEGREE_MAP = {'slinear': 1, 'cubic': 3, 'quintic': 5, 'pchip': 3, 'slinear_legacy': 1, 'cubic_legacy': 3, 'quintic_legacy': 5}
    _SPLINE_METHODS_recursive = {'slinear_legacy', 'cubic_legacy', 'quintic_legacy', 'pchip'}
    _SPLINE_METHODS_ndbspl = {'slinear', 'cubic', 'quintic'}
    _SPLINE_METHODS = list(_SPLINE_DEGREE_MAP.keys())
    _ALL_METHODS = ['linear', 'nearest'] + _SPLINE_METHODS
    __class_getitem__ = classmethod(GenericAlias)

    def __init__(self, points, values, method='linear', bounds_error=True, fill_value=np.nan, *, solver=None, solver_args=None):
        if method not in self._ALL_METHODS:
            raise ValueError(f"Method '{method}' is not defined")
        elif method in self._SPLINE_METHODS:
            self._validate_grid_dimensions(points, method)
        try:
            xp = array_namespace(*points, values)
        except Exception as e:
            xp = array_namespace(*points)
            try:
                xp_v = array_namespace(values)
            except Exception:
                pass
            else:
                if xp_v != xp:
                    raise e
        self._asarray = xp.asarray
        self.method = method
        self._spline = None
        self.bounds_error = bounds_error
        self._grid, self._descending_dimensions = _check_points(points)
        self._values = self._check_values(values)
        self._check_dimensionality(self._grid, self._values)
        self.fill_value = self._check_fill_value(self._values, fill_value)
        if self._descending_dimensions:
            self._values = np.flip(values, axis=self._descending_dimensions)
        if self.method == 'pchip' and np.iscomplexobj(self._values):
            msg = '`PchipInterpolator` only works with real values. If you are trying to use the real components of the passed array, use `np.real` on the array before passing to `RegularGridInterpolator`.'
            raise ValueError(msg)
        if method in self._SPLINE_METHODS_ndbspl:
            if solver_args is None:
                solver_args = {}
            self._spline = self._construct_spline(method, solver, **solver_args)
        elif solver is not None or solver_args:
            raise ValueError(f"method ={method!r} does not accept the 'solver' argument. Got  solver = {solver!r} and with arguments {solver_args}.")

    def _construct_spline(self, method, solver=None, **solver_args):
        if solver is None:
            solver = ssl.gcrotmk
        spl = make_ndbspl(self._grid, self._values, self._SPLINE_DEGREE_MAP[method], solver=solver, **solver_args)
        return spl

    def _check_dimensionality(self, grid, values):
        _check_dimensionality(grid, values)

    def _check_points(self, points):
        return _check_points(points)

    def _check_values(self, values):
        if is_array_api_obj(values):
            values = np.asarray(values)
        if not hasattr(values, 'ndim'):
            values = np.asarray(values)
        if hasattr(values, 'dtype') and hasattr(values, 'astype'):
            if not np.issubdtype(values.dtype, np.inexact):
                values = values.astype(float)
        return values

    def _check_fill_value(self, values, fill_value):
        if fill_value is not None:
            fill_value_dtype = np.asarray(fill_value).dtype
            if hasattr(values, 'dtype') and (not np.can_cast(fill_value_dtype, values.dtype, casting='same_kind')):
                raise ValueError("fill_value must be either 'None' or of a type compatible with values")
        return fill_value

    def __call__(self, xi, method=None, *, nu=None):
        _spline = self._spline
        method = self.method if method is None else method
        is_method_changed = self.method != method
        if method not in self._ALL_METHODS:
            raise ValueError(f"Method '{method}' is not defined")
        if is_method_changed and method in self._SPLINE_METHODS_ndbspl:
            _spline = self._construct_spline(method)
        if nu is not None and method not in self._SPLINE_METHODS_ndbspl:
            raise ValueError(f'Can only compute derivatives for methods {self._SPLINE_METHODS_ndbspl}, got method ={method!r}.')
        xi, xi_shape, ndim, nans, out_of_bounds = self._prepare_xi(xi)
        if method == 'linear':
            indices, norm_distances = self._find_indices(xi.T)
            if ndim == 2 and hasattr(self._values, 'dtype') and (self._values.ndim == 2) and self._values.flags.writeable and (self._values.dtype in (np.float64, np.complex128)) and (self._values.dtype.byteorder == '='):
                out = np.empty(indices.shape[1], dtype=self._values.dtype)
                result = evaluate_linear_2d(self._values, indices, norm_distances, self._grid, out)
            else:
                result = self._evaluate_linear(indices, norm_distances)
        elif method == 'nearest':
            indices, norm_distances = self._find_indices(xi.T)
            result = self._evaluate_nearest(indices, norm_distances)
        elif method in self._SPLINE_METHODS:
            if is_method_changed:
                self._validate_grid_dimensions(self._grid, method)
            if method in self._SPLINE_METHODS_recursive:
                result = self._evaluate_spline(xi, method)
            else:
                result = _spline(xi, nu=nu)
        if not self.bounds_error and self.fill_value is not None:
            result[out_of_bounds] = self.fill_value
        if np.any(nans):
            result[nans] = np.nan
        return self._asarray(result.reshape(xi_shape[:-1] + self._values.shape[ndim:]))

    @property
    def grid(self):
        return tuple((self._asarray(p) for p in self._grid))

    @property
    def values(self):
        return self._asarray(self._values)

    def _prepare_xi(self, xi):
        ndim = len(self._grid)
        xi = _ndim_coords_from_arrays(xi, ndim=ndim)
        if xi.shape[-1] != ndim:
            raise ValueError(f'The requested sample points xi have dimension {xi.shape[-1]} but this RegularGridInterpolator has dimension {ndim}')
        xi_shape = xi.shape
        xi = xi.reshape(-1, xi_shape[-1])
        xi = np.asarray(xi, dtype=float)
        nans = np.any(np.isnan(xi), axis=-1)
        if self.bounds_error:
            for i, p in enumerate(xi.T):
                if not np.logical_and(np.all(self._grid[i][0] <= p), np.all(p <= self._grid[i][-1])):
                    raise ValueError(f'One of the requested xi is out of bounds in dimension {i}')
            out_of_bounds = None
        else:
            out_of_bounds = self._find_out_of_bounds(xi.T)
        return (xi, xi_shape, ndim, nans, out_of_bounds)

    def _evaluate_linear(self, indices, norm_distances):
        vslice = (slice(None),) + (None,) * (self._values.ndim - len(indices))
        shift_norm_distances = [1 - yi for yi in norm_distances]
        shift_indices = [i + 1 for i in indices]
        zipped1 = zip(indices, shift_norm_distances)
        zipped2 = zip(shift_indices, norm_distances)
        hypercube = itertools.product(*zip(zipped1, zipped2))
        value = np.array([0.0])
        for h in hypercube:
            edge_indices, weights = zip(*h)
            weight = np.array([1.0])
            for w in weights:
                weight = weight * w
            term = np.asarray(self._values[edge_indices]) * weight[vslice]
            value = value + term
        return value

    def _evaluate_nearest(self, indices, norm_distances):
        idx_res = [np.where(yi <= 0.5, i, i + 1) for i, yi in zip(indices, norm_distances)]
        return self._values[tuple(idx_res)]

    def _validate_grid_dimensions(self, points, method):
        k = self._SPLINE_DEGREE_MAP[method]
        for i, point in enumerate(points):
            ndim = len(np.atleast_1d(point))
            if ndim <= k:
                raise ValueError(f'There are {ndim} points in dimension {i}, but method {method} requires at least  {k + 1} points per dimension.')

    def _evaluate_spline(self, xi, method):
        if xi.ndim == 1:
            xi = xi.reshape((1, xi.size))
        m, n = xi.shape
        axes = tuple(range(self._values.ndim))
        axx = axes[:n][::-1] + axes[n:]
        values = self._values.transpose(axx)
        if method == 'pchip':
            _eval_func = self._do_pchip
        else:
            _eval_func = self._do_spline_fit
        k = self._SPLINE_DEGREE_MAP[method]
        last_dim = n - 1
        first_values = _eval_func(self._grid[last_dim], values, xi[:, last_dim], k)
        shape = (m, *self._values.shape[n:])
        result = np.empty(shape, dtype=self._values.dtype)
        for j in range(m):
            folded_values = first_values[j, ...]
            for i in range(last_dim - 1, -1, -1):
                folded_values = _eval_func(self._grid[i], folded_values, xi[j, i], k)
            result[j, ...] = folded_values
        return result

    @staticmethod
    def _do_spline_fit(x, y, pt, k):
        local_interp = make_interp_spline(x, y, k=k, axis=0)
        values = local_interp(pt)
        return values

    @staticmethod
    def _do_pchip(x, y, pt, k):
        local_interp = PchipInterpolator(x, y, axis=0)
        values = local_interp(pt)
        return values

    def _find_indices(self, xi):
        return find_indices(self._grid, xi)

    def _find_out_of_bounds(self, xi):
        out_of_bounds = np.zeros(xi.shape[1], dtype=bool)
        for x, grid in zip(xi, self._grid):
            out_of_bounds += x < grid[0]
            out_of_bounds += x > grid[-1]
        return out_of_bounds

# --- helper: scipy.interpolate._rgi._check_dimensionality ---
def _check_dimensionality(points, values):
    if len(points) > values.ndim:
        raise ValueError(f'There are {len(points)} point arrays, but values has {values.ndim} dimensions')
    for i, p in enumerate(points):
        if not np.asarray(p).ndim == 1:
            raise ValueError(f'The points in dimension {i} must be 1-dimensional')
        if not values.shape[i] == len(p):
            raise ValueError(f'There are {len(p)} points and {values.shape[i]} values in dimension {i}')

# --- helper: scipy.interpolate._rgi._check_points ---
def _check_points(points):
    descending_dimensions = []
    grid = []
    for i, p in enumerate(points):
        p = np.asarray(p, dtype=float)
        if not np.all(p[1:] > p[:-1]):
            if np.all(p[1:] < p[:-1]):
                descending_dimensions.append(i)
                p = np.flip(p)
            else:
                raise ValueError(f'The points in dimension {i} must be strictly ascending or descending')
        p = np.ascontiguousarray(p)
        grid.append(p)
    return (tuple(grid), tuple(descending_dimensions))

@xp_capabilities(cpu_only=True, jax_jit=False, skip_backends=[('dask.array', 'https://github.com/data-apis/array-api-extra/issues/488')])
class NdBSpline:
    __class_getitem__ = classmethod(GenericAlias)

    def __init__(self, t, c, k, *, extrapolate=None):
        self._k, self._indices_k1d, (self._t, self._len_t) = _preprocess_inputs(k, t)
        self._asarray = array_namespace(c, *t).asarray
        if extrapolate is None:
            extrapolate = True
        self.extrapolate = bool(extrapolate)
        self._c = np.asarray(c)
        ndim = self._t.shape[0]
        if self._c.ndim < ndim:
            raise ValueError(f'Coefficients must be at least {ndim}-dimensional.')
        for d in range(ndim):
            td = self.t[d]
            kd = self.k[d]
            n = td.shape[0] - kd - 1
            if self._c.shape[d] != n:
                raise ValueError(f'Knots, coefficients and degree in dimension {d} are inconsistent: got {self._c.shape[d]} coefficients for {len(td)} knots, need at least {n} for k={k}.')
        dt = _get_dtype(self._c.dtype)
        self._c = np.ascontiguousarray(self._c, dtype=dt)

    @property
    def k(self):
        return tuple(self._k)

    @property
    def t(self):
        return tuple((self._asarray(self._t[d, :self._len_t[d]]) for d in range(self._t.shape[0])))

    @property
    def c(self):
        return self._asarray(self._c)

    def __call__(self, xi, *, nu=None, extrapolate=None):
        ndim = self._t.shape[0]
        if extrapolate is None:
            extrapolate = self.extrapolate
        extrapolate = bool(extrapolate)
        if nu is None:
            nu = np.zeros((ndim,), dtype=np.int64)
        else:
            nu = np.asarray(nu, dtype=np.int64)
            if nu.ndim != 1 or nu.shape[0] != ndim:
                raise ValueError(f'invalid number of derivative orders nu = {nu!r} for ndim = {len(self.t)}.')
            if any(nu < 0):
                raise ValueError(f'derivatives must be positive, got nu = {nu!r}')
        xi = np.asarray(xi, dtype=float)
        xi_shape = xi.shape
        xi = xi.reshape(-1, xi_shape[-1])
        xi = np.ascontiguousarray(xi)
        if xi_shape[-1] != ndim:
            raise ValueError(f'Shapes: xi.shape={xi_shape} and ndim={ndim}')
        was_complex = self._c.dtype.kind == 'c'
        cc = self._c
        if was_complex and self._c.ndim == ndim:
            cc = self._c[..., None]
        cc = cc.view(float)
        c1 = cc.reshape(cc.shape[:ndim] + (-1,))
        c1r = c1.ravel()
        _strides_c1 = np.asarray([s // c1.dtype.itemsize for s in c1.strides], dtype=np.int64)
        num_c_tr = c1.shape[-1]
        out = _dierckx.evaluate_ndbspline(xi, self._t, self._len_t, self._k, nu, extrapolate, c1r, num_c_tr, _strides_c1, self._indices_k1d)
        out = out.view(self._c.dtype)
        out = out.reshape(xi_shape[:-1] + self._c.shape[ndim:])
        return self._asarray(out)

    @classmethod
    def design_matrix(cls, xvals, t, k, extrapolate=True):
        xvals = np.asarray(xvals, dtype=float)
        ndim = xvals.shape[-1]
        if len(t) != ndim:
            raise ValueError(f'Data and knots are inconsistent: len(t) = {len(t)} for  ndim = {ndim!r}.')
        k, _indices_k1d, (_t, len_t) = _preprocess_inputs(k, t)
        c_shape = tuple((len_t[d] - k[d] - 1 for d in range(ndim)))
        cs = c_shape[1:] + (1,)
        cstrides = np.cumprod(cs[::-1], dtype=np.int64)[::-1].copy()
        data, indices, indptr = _dierckx._coloc_nd(xvals, _t, len_t, k, _indices_k1d, cstrides)
        return csr_array((data, indices, indptr))

    def _bspline_derivative_along_axis(self, c, t, k, axis, nu=1):
        c = np.moveaxis(c, axis, 0)
        n = c.shape[0]
        trailing_shape = c.shape[1:]
        c_flat = c.reshape(n, -1)
        new_c_list = []
        new_t = None
        for i in range(c_flat.shape[1]):
            if k >= nu:
                b = BSpline.construct_fast(t, c_flat[:, i], k)
                db = b.derivative(nu)
                db.c = db.c[:len(db.t) - db.k - 1]
            else:
                db = BSpline.construct_fast(t, np.zeros(len(t) - 1), 0)
            if new_t is None:
                new_t = db.t
            new_c_list.append(db.c)
        new_c = np.stack(new_c_list, axis=1).reshape((len(new_c_list[0]),) + trailing_shape)
        new_c = np.moveaxis(new_c, 0, axis)
        return (new_c, new_t)

    def derivative(self, nu):
        nu_arr = np.asarray(nu, dtype=np.int64)
        ndim = len(self.t)
        if nu_arr.ndim != 1 or nu_arr.shape[0] != ndim:
            raise ValueError(f'invalid number of derivative orders nu = {nu!r} for ndim = {len(self.t)}.')
        if any(nu_arr < 0):
            raise ValueError(f'derivative orders must be positive, got nu = {nu!r}')
        t_new = [self._t[d, :self._len_t[d]] for d in range(self._t.shape[0])]
        k_new = list(self.k)
        c_new = self._c.copy()
        for axis, n in enumerate(nu_arr):
            if n == 0:
                continue
            c_new, t_new[axis] = self._bspline_derivative_along_axis(c_new, t_new[axis], k_new[axis], axis, nu=n)
            k_new[axis] = max(k_new[axis] - n, 0)
        return NdBSpline(tuple((self._asarray(t) for t in t_new)), self._asarray(c_new), tuple(k_new), extrapolate=self.extrapolate)

# --- helper: scipy.interpolate._ndbspline._get_dtype ---
def _get_dtype(dtype):
    if np.issubdtype(dtype, np.complexfloating):
        return np.complex128
    else:
        return np.float64

# --- helper: scipy.interpolate._ndbspline._preprocess_inputs ---
def _preprocess_inputs(k, t_tpl):
    if not isinstance(t_tpl, tuple):
        raise ValueError(f'Expect `t` to be a tuple of array-likes. Got {t_tpl} instead.')
    ndim = len(t_tpl)
    try:
        len(k)
    except TypeError:
        k = (k,) * ndim
    k = np.asarray([operator.index(ki) for ki in k], dtype=np.int64)
    if len(k) != ndim:
        raise ValueError(f'len(t) = {len(t_tpl)} != len(k) = {len(k)!r}.')
    ndim = len(t_tpl)
    for d in range(ndim):
        td = np.asarray(t_tpl[d])
        kd = k[d]
        n = td.shape[0] - kd - 1
        if kd < 0:
            raise ValueError(f'Spline degree in dimension {d} cannot be negative.')
        if td.ndim != 1:
            raise ValueError(f'Knot vector in dimension {d} must be one-dimensional.')
        if n < kd + 1:
            raise ValueError(f'Need at least {2 * kd + 2} knots for degree {kd} in dimension {d}.')
        if (np.diff(td) < 0).any():
            raise ValueError(f'Knots in dimension {d} must be in a non-decreasing order.')
        if len(np.unique(td[kd:n + 1])) < 2:
            raise ValueError(f'Need at least two internal knots in dimension {d}.')
        if not np.isfinite(td).all():
            raise ValueError(f'Knots in dimension {d} should not have nans or infs.')
    shape = tuple((kd + 1 for kd in k))
    indices = np.unravel_index(np.arange(prod(shape)), shape)
    _indices_k1d = np.asarray(indices, dtype=np.int64).T.copy()
    t_tpl = [np.asarray(t) for t in t_tpl]
    ndim = len(t_tpl)
    len_t = [len(ti) for ti in t_tpl]
    _t = np.empty((ndim, max(len_t)), dtype=float)
    _t.fill(np.nan)
    for d in range(ndim):
        _t[d, :len(t_tpl[d])] = t_tpl[d]
    len_t = np.asarray(len_t, dtype=np.int64)
    return (k, _indices_k1d, (_t, len_t))

def barycentric_interpolate(xi, yi, x, axis=0, *, der=0, rng=None):
    P = BarycentricInterpolator(xi, yi, axis=axis, rng=rng)
    if der == 0:
        return P(x)
    elif _isscalar(der):
        return P.derivative(x, der=der)
    else:
        return P.derivatives(x, der=np.amax(der) + 1)[der]

# --- helper: scipy.interpolate._polyint.BarycentricInterpolator ---
class BarycentricInterpolator(_Interpolator1DWithDerivatives):

    @_transition_to_rng('random_state', replace_doc=False)
    def __init__(self, xi, yi=None, axis=0, *, wi=None, rng=None):
        super().__init__(xi, yi, axis)
        rng = check_random_state(rng)
        self.xi = np.asarray(xi, dtype=np.float64)
        self.set_yi(yi)
        self.n = len(self.xi)
        self._diff_cij = None
        if wi is not None:
            self.wi = wi
        else:
            self._inv_capacity = 4.0 / (np.max(self.xi) - np.min(self.xi))
            permute = rng.permutation(self.n)
            inv_permute = np.zeros(self.n, dtype=np.int32)
            inv_permute[permute] = np.arange(self.n)
            self.wi = np.zeros(self.n)
            for i in range(self.n):
                dist = self._inv_capacity * (self.xi[i] - self.xi[permute])
                dist[inv_permute[i]] = 1.0
                prod = np.prod(dist)
                if prod == 0.0:
                    raise ValueError('Interpolation points xi must be distinct.')
                self.wi[i] = 1.0 / prod

    def set_yi(self, yi, axis=None):
        if yi is None:
            self.yi = None
            return
        self._set_yi(yi, xi=self.xi, axis=axis)
        self.yi = self._reshape_yi(yi)
        self.n, self.r = self.yi.shape
        self._diff_baryint = None

    def add_xi(self, xi, yi=None):
        if yi is not None:
            if self.yi is None:
                raise ValueError('No previous yi value to update!')
            yi = self._reshape_yi(yi, check=True)
            self.yi = np.vstack((self.yi, yi))
        elif self.yi is not None:
            raise ValueError('No update to yi provided!')
        old_n = self.n
        self.xi = np.concatenate((self.xi, xi))
        self.n = len(self.xi)
        self.wi **= -1
        old_wi = self.wi
        self.wi = np.zeros(self.n)
        self.wi[:old_n] = old_wi
        for j in range(old_n, self.n):
            self.wi[:j] *= self._inv_capacity * (self.xi[j] - self.xi[:j])
            self.wi[j] = np.multiply.reduce(self._inv_capacity * (self.xi[:j] - self.xi[j]))
        self.wi **= -1
        self._diff_cij = None
        self._diff_baryint = None

    def __call__(self, x):
        return _Interpolator1D.__call__(self, x)

    def _evaluate(self, x):
        if x.size == 0:
            p = np.zeros((0, self.r), dtype=self.dtype)
        else:
            c = x[..., np.newaxis] - self.xi
            z = c == 0
            c[z] = 1
            c = self.wi / c
            with np.errstate(divide='ignore'):
                p = np.dot(c, self.yi) / np.sum(c, axis=-1)[..., np.newaxis]
            r = np.nonzero(z)
            if len(r) == 1:
                if len(r[0]) > 0:
                    p = self.yi[r[0][0]]
            else:
                p[r[:-1]] = self.yi[r[-1]]
        return p

    def derivative(self, x, der=1):
        x, x_shape = self._prepare_x(x)
        y = self._evaluate_derivatives(x, der + 1, all_lower=False)
        return self._finish_y(y, x_shape)

    def _evaluate_derivatives(self, x, der=None, all_lower=True):
        if not all_lower and (x.size == 0 or self.r == 0):
            return np.zeros((0, self.r), dtype=self.dtype)
        if not all_lower and der == 1:
            return self._evaluate(x)
        if not all_lower and der > self.n:
            return np.zeros((len(x), self.r), dtype=self.dtype)
        if der is None:
            der = self.n
        if all_lower and (x.size == 0 or self.r == 0):
            return np.zeros((der, len(x), self.r), dtype=self.dtype)
        if self._diff_cij is None:
            c = self.xi[:, np.newaxis] - self.xi
            np.fill_diagonal(c, 1)
            c = self.wi / (c * self.wi[..., np.newaxis])
            np.fill_diagonal(c, 0)
            d = -c.sum(axis=1)
            np.fill_diagonal(c, d)
            self._diff_cij = c
        if self._diff_baryint is None:
            self._diff_baryint = BarycentricInterpolator(xi=self.xi, yi=self._diff_cij @ self.yi, wi=self.wi)
            self._diff_baryint._diff_cij = self._diff_cij
        if all_lower:
            cn = np.zeros((der, len(x), self.r), dtype=self.dtype)
            for d in range(der):
                cn[d, :, :] = self._evaluate_derivatives(x, d + 1, all_lower=False)
            return cn
        return self._diff_baryint._evaluate_derivatives(x, der - 1, all_lower=False)

# --- helper: scipy.interpolate._polyint._isscalar ---
def _isscalar(x):
    return np.isscalar(x) or (hasattr(x, 'shape') and x.shape == ())

@xp_capabilities(cpu_only=True, jax_jit=False, allow_dask_compute=True)
def generate_knots(x, y, *, w=None, xb=None, xe=None, k=3, s=0, nest=None, bc_type=None):
    xp = array_namespace(x, y, w)
    bc_type = _validate_bc_type(bc_type)
    periodic = bc_type == 'periodic'
    if s == 0:
        if nest is not None or w is not None:
            raise ValueError('s == 0 is interpolation only')
        if periodic and k > 1:
            t = _periodic_knots(x, k)
        else:
            t = _not_a_knot(x, k)
        yield xp.asarray(t)
        return
    x, y, w, k, s, xb, xe = _validate_inputs(x, y, w, k, s, xb, xe, parametric=np.ndim(y) == 2, periodic=periodic)
    yield from _generate_knots_impl(x, y, w, xb, xe, k, s, nest, periodic, xp=xp)

# --- helper: scipy.interpolate._fitpack_repro._generate_knots_impl ---
def _generate_knots_impl(x, y, w, xb, xe, k, s, nest, periodic, xp=np):
    acc = s * TOL
    m = x.size
    if nest is None:
        if periodic:
            nest = max(m + 2 * k, 2 * k + 3)
        else:
            nest = max(m + k + 1, 2 * k + 3)
    elif nest < 2 * (k + 1):
        raise ValueError(f'`nest` too small: nest = {nest!r} < 2*(k+1) = {2 * (k + 1)}.')
    if not periodic:
        nmin = 2 * (k + 1)
        nmax = m + k + 1
    else:
        nmin = 2 * (k + 1)
        nmax = m + 2 * k
    per = xe - xb
    if periodic:
        t = np.zeros(nmin, dtype=float)
        for i in range(0, k + 1):
            t[i] = x[0] - (k - i) * per
            t[i + k + 1] = x[m - 1] + i * per
        _, fp = _get_residuals(x, y, t, k, w, periodic=periodic)
        if fp - s < acc or nmax == nmin:
            yield t
            return
    else:
        fp = 0.0
        fpold = 0.0
    if not periodic:
        t = np.asarray([xb] * (k + 1) + [xe] * (k + 1), dtype=float)
    else:
        t = np.zeros(2 * k + 3, dtype=float)
        t[k + 1] = x[(m + 1) // 2 - 1]
        nplus = 1
    n = t.shape[0]
    for iter in range(m):
        if periodic:
            n = t.shape[0]
            t[k] = xb
            t[n - k - 1] = xe
            for j in range(1, k + 1):
                t[k - j] = t[n - k - j - 1] - per
                t[n - k + j - 1] = t[k + j] + per
        yield xp.asarray(t)
        fpold = fp
        residuals, fp = _get_residuals(x, y, t, k, w=w, periodic=periodic)
        fpms = fp - s
        if abs(fpms) < acc or fpms < 0:
            return
        if n == nmin:
            nplus = 1
        else:
            delta = fpold - fp
            npl1 = int(nplus * fpms / delta) if delta > acc else nplus * 2
            nplus = min(nplus * 2, max(npl1, nplus // 2, 1))
        for j in range(nplus):
            t = add_knot(x, t, k, residuals)
            n = t.shape[0]
            if n >= nmax:
                if not periodic:
                    t = _not_a_knot(x, k)
                else:
                    t = _periodic_knots(x, k)
                yield xp.asarray(t)
                return
            if n >= nest:
                yield xp.asarray(t)
                return
            if j < nplus - 1:
                residuals, _ = _get_residuals(x, y, t, k, w=w, periodic=periodic)
    return

# --- helper: scipy.interpolate._fitpack_repro._validate_bc_type ---
def _validate_bc_type(bc_type):
    if bc_type is None:
        return 'not-a-knot'
    if bc_type not in ('not-a-knot', 'periodic'):
        raise ValueError(f"Only 'not-a-knot' and 'periodic' boundary conditions are recognised, found {bc_type}")
    return bc_type

# --- helper: scipy.interpolate._fitpack_repro._validate_inputs ---
def _validate_inputs(x, y, w, k, s, xb, xe, parametric, periodic=False):
    x = np.asarray(x, dtype=float)
    y = np.asarray(y, dtype=float)
    if not x.flags.c_contiguous:
        x = x.copy()
    if not y.flags.c_contiguous:
        y = y.copy()
    if w is None:
        w = np.ones_like(x, dtype=float)
    else:
        w = np.asarray(w, dtype=float)
        if not w.flags.c_contiguous:
            w = w.copy()
        if w.ndim != 1:
            raise ValueError(f'w.ndim = {w.ndim!r} not implemented yet.')
        if (w < 0).any():
            raise ValueError('Weights must be non-negative')
        if w.sum() == 0:
            raise ValueError('All weights are zero.')
    if y.ndim == 0 or y.ndim > 2:
        raise ValueError(f'y.ndim = {y.ndim!r} not supported (must be 1 or 2.)')
    parametric = bool(parametric)
    if parametric:
        if y.ndim != 2:
            raise ValueError(f'y.ndim = {y.ndim!r} != 2 not supported with parametric ={parametric!r}.')
    else:
        if y.ndim != 1:
            raise ValueError(f'y.ndim = {y.ndim!r} != 1 not supported with parametric ={parametric!r}.')
        y = y[:, None]
    if w.shape[0] != x.shape[0]:
        raise ValueError(f'Weights is incompatible: w.shape ={w.shape!r} != {x.shape}.')
    if x.shape[0] != y.shape[0]:
        raise ValueError(f'Data is incompatible: x.shape = {x.shape!r} and y.shape = {y.shape!r}.')
    if x.ndim != 1 or (x[1:] < x[:-1]).any():
        raise ValueError('Expect `x` to be an ordered 1D sequence.')
    k = operator.index(k)
    if s < 0:
        raise ValueError(f'`s` must be non-negative. Got s = {s!r}')
    if xb is None:
        xb = min(x)
    if xe is None:
        xe = max(x)
    if periodic and (not np.allclose(y[0], y[-1], atol=1e-15)):
        raise ValueError("First and last points does not match which is required for `bc_type='periodic'`.")
    return (x, y, w, k, s, xb, xe)

@xp_capabilities(cpu_only=True, jax_jit=False, allow_dask_compute=True)
def make_splprep(x, *, w=None, u=None, ub=None, ue=None, k=3, s=0, t=None, nest=None, bc_type=None):
    bc_type = _validate_bc_type(bc_type)
    periodic = bc_type == 'periodic'
    if isinstance(x, list):
        xp = array_namespace(*x, w, u, t)
    else:
        xp = array_namespace(x, w, u, t)
    x = xp.stack(x, axis=1)
    if u is None:
        dp = (x[1:, :] - x[:-1, :]) ** 2
        u = xp.cumulative_sum(xp.sqrt(xp.sum(dp, axis=1)))
        u = concat_1d(xp, 0.0, u / u[-1])
    if s == 0:
        if t is not None or w is not None or nest is not None:
            raise ValueError('s==0 is for interpolation only')
        return (make_interp_spline(u, x.T, k=k, axis=1), u)
    u, x, w, k, s, ub, ue = _validate_inputs(u, x, w, k, s, ub, ue, parametric=True, periodic=periodic)
    if t is not None:
        t = xp.asarray(t)
    spl = _make_splrep_impl(u, x, w, ub, ue, k, s, t, nest, periodic=periodic, xp=xp)
    cc = spl.c.T
    spl1 = BSpline(spl.t, cc, spl.k, axis=1)
    return (spl1, xp.asarray(u))

# --- helper: scipy.interpolate._fitpack_repro._make_splrep_impl ---
def _make_splrep_impl(x, y, w, xb, xe, k, s, t, nest, periodic, xp=np):
    acc = s * TOL
    m = x.size
    if nest is None:
        if periodic:
            nest = max(m + 2 * k, 2 * k + 3)
        else:
            nest = max(m + k + 1, 2 * k + 3)
    else:
        if nest < 2 * (k + 1):
            raise ValueError(f'`nest` too small: nest = {nest!r} < 2*(k+1) = {2 * (k + 1)}.')
        if t is not None:
            raise ValueError('Either supply `t` or `nest`.')
    if t is None:
        gen = _generate_knots_impl(x, y, w, xb, xe, k, s, nest, periodic)
        t = list(gen)[-1]
    else:
        fpcheck(x, t, k, periodic=periodic)
    if t.shape[0] == 2 * (k + 1):
        _, _, c, _, _ = _lsq_solve_qr(x, y, t, k, w, periodic=periodic)
        t, c = (xp.asarray(t), xp.asarray(c))
        return BSpline(t, c, k)
    if periodic:
        R, A1, A2, Z, Y, _, p, _ = _lsq_solve_qr_for_root_rati_periodic(x, y, t, k, w)
    else:
        R, Y, _, _, _ = _lsq_solve_qr(x, y, t, k, w, periodic=periodic)
    nc = t.shape[0] - k - 1
    if not periodic:
        p = nc / R[:, 0].sum()
    _, fp = _get_residuals(x, y, t, k, w, periodic=periodic)
    fpinf = fp - s
    if not periodic:
        _, fp0 = _get_residuals(x, y, np.array([xb] * (k + 1) + [xe] * (k + 1)), k, w)
        fp0 = fp0 - s
    else:
        per = xe - xb
        tc = np.zeros(2 * (k + 1), dtype=float)
        for i in range(0, k + 1):
            tc[i] = x[0] - (k - i) * per
            tc[i + k + 1] = x[m - 1] + i * per
        _, fp0 = _get_residuals(x, y, tc, k, w, periodic=periodic)
        fp0 = fp0 - s
    bracket = ((0, fp0), (np.inf, fpinf))
    if not periodic:
        f = F(x, y, t, k=k, s=s, w=w, R=R, Y=Y)
    else:
        f = Fperiodic(x, y, t, k=k, s=s, w=w, R=R, Y=Y, A1=A1, A2=A2, Z=Z)
    _ = root_rati(f, p, bracket, acc)
    t, c, k = f.spl.tck
    axis, extrap = (f.spl.axis, f.spl.extrapolate)
    t, c = (xp.asarray(t), xp.asarray(c))
    spl = BSpline.construct_fast(t, c, k, axis=axis, extrapolate=extrap)
    return spl

