        pocon, posv = get_lapack_funcs(('pocon', 'posv'), (a1, b1))
        lu, x, info = posv(a1, b1, lower=lower, overwrite_a=overwrite_a, overwrite_b=overwrite_b)
        _solve_check(n, info)
        rcond, info = pocon(lu, anorm)
    _solve_check(n, info, lamch, rcond)
