def black_tophat(input, size=None, footprint=None, structure=None, output=None, mode='reflect', cval=0.0, origin=0, *, axes=None):
    input = np.asarray(input)
    if size is not None and footprint is not None:
        warnings.warn('ignoring size because footprint is set', UserWarning, stacklevel=2)
    tmp = grey_dilation(input, size, footprint, structure, None, mode, cval, origin, axes=axes)
    tmp = grey_erosion(tmp, size, footprint, structure, output, mode, cval, origin, axes=axes)
    if tmp is None:
        tmp = output
    if input.dtype == np.bool_ and tmp.dtype == np.bool_:
        np.bitwise_xor(tmp, input, out=tmp)
    else:
        np.subtract(tmp, input, out=tmp)
    return tmp

