            sz = structure.shape[ii]
        elif np.isscalar(size):
            sz = size
        else:
            sz = size[ii]
        if not sz & 1:
            origin[ii] -= 1
    return _filters._min_or_max_filter(input, size, footprint, structure, output, mode, cval, origin, 0, axes=axes)

