def _minimize_newtoncg(fun, x0, args=(), jac=None, hess=None, hessp=None, callback=None, xtol=1e-05, eps=_epsilon, maxiter=None, disp=False, return_all=False, c1=0.0001, c2=0.9, workers=None, **unknown_options):
    _check_unknown_options(unknown_options)
    if jac is None:
        raise ValueError('Jacobian is required for Newton-CG method')
    fhess_p = hessp
    fhess = hess
    avextol = xtol
    epsilon = eps
    retall = return_all
    x0 = asarray(x0).flatten()
    sf = _prepare_scalar_function(fun, x0, jac, args=args, epsilon=eps, hess=hess, workers=workers)
    f = sf.fun
    fprime = sf.grad
    _h = sf.hess(x0)
    if hess in FD_METHODS or isinstance(_h, LinearOperator):
        fhess = None

        def _hessp(x, p, *args):
            return sf.hess(x).dot(p)
        fhess_p = _hessp

    def terminate(warnflag, msg):
        if disp:
            _print_success_message_or_warn(warnflag, msg)
            print(f'         Current function value: {old_fval:f}')
            print(f'         Iterations: {k:d}')
            print(f'         Function evaluations: {sf.nfev:d}')
            print(f'         Gradient evaluations: {sf.ngev:d}')
            print(f'         Hessian evaluations: {hcalls:d}')
        fval = old_fval
        result = OptimizeResult(fun=fval, jac=gfk, nfev=sf.nfev, njev=sf.ngev, nhev=hcalls, status=warnflag, success=warnflag == 0, message=msg, x=xk, nit=k)
        if retall:
            result['allvecs'] = allvecs
        return result
    hcalls = 0
    if maxiter is None:
        maxiter = len(x0) * 200
    cg_maxiter = 20 * len(x0)
    xtol = len(x0) * avextol
    update_l1norm = np.finfo(float).max
    xk = np.copy(x0)
    if retall:
        allvecs = [xk]
    k = 0
    gfk = None
    old_fval = f(x0)
    old_old_fval = None
    float64eps = np.finfo(np.float64).eps
    while update_l1norm > xtol:
        if k >= maxiter:
            msg = 'Warning: ' + _status_message['maxiter']
            return terminate(1, msg)
        b = -fprime(xk)
        maggrad = np.linalg.norm(b, ord=1)
        eta = min(0.5, math.sqrt(maggrad))
        termcond = eta * maggrad
        xsupi = zeros(len(x0), dtype=x0.dtype)
        ri = -b
        psupi = -ri
        i = 0
        dri0 = np.dot(ri, ri)
        if fhess is not None:
            A = sf.hess(xk)
            hcalls += 1
        for k2 in range(cg_maxiter):
            if np.add.reduce(np.abs(ri)) <= termcond:
                break
            if fhess is None:
                if fhess_p is None:
                    Ap = approx_fhess_p(xk, psupi, fprime, epsilon)
                else:
                    Ap = fhess_p(xk, psupi, *args)
                    hcalls += 1
            else:
                Ap = A.dot(psupi)
            Ap = asarray(Ap).squeeze()
            curv = np.dot(psupi, Ap)
            if 0 <= curv <= 3 * float64eps:
                break
            elif curv < 0:
                if i > 0:
                    break
                else:
                    xsupi = dri0 / -curv * b
                    break
            alphai = dri0 / curv
            xsupi += alphai * psupi
            ri += alphai * Ap
            dri1 = np.dot(ri, ri)
            betai = dri1 / dri0
            psupi = -ri + betai * psupi
            i += 1
            dri0 = dri1
        else:
            msg = "Warning: CG iterations didn't converge. The Hessian is not positive definite."
            return terminate(3, msg)
        pk = xsupi
        gfk = -b
        try:
            alphak, fc, gc, old_fval, old_old_fval, gfkp1 = _line_search_wolfe12(f, fprime, xk, pk, gfk, old_fval, old_old_fval, c1=c1, c2=c2)
        except _LineSearchError:
            msg = 'Warning: ' + _status_message['pr_loss']
            return terminate(2, msg)
        update = alphak * pk
        xk += update
        if retall:
            allvecs.append(xk)
        k += 1
        intermediate_result = OptimizeResult(x=xk, fun=old_fval)
        if _call_callback_maybe_halt(callback, intermediate_result):
            return terminate(5, '')
        update_l1norm = np.linalg.norm(update, ord=1)
    else:
        if np.isnan(old_fval) or np.isnan(update_l1norm):
            return terminate(3, _status_message['nan'])
        msg = _status_message['success']
        return terminate(0, msg)

# --- helper: scipy.optimize._optimize._wrap_callback ---
def _wrap_callback(callback, method=None):
    if callback is None or method in {'tnc', 'cobyla', 'cobyqa'}:
        return callback
    sig = wrapped_inspect_signature(callback)
    if set(sig.parameters) == {'intermediate_result'}:

        def wrapped_callback(res):
            return callback(intermediate_result=res)
    elif method == 'trust-constr':

        def wrapped_callback(res):
            return callback(np.copy(res.x), res)
    elif method == 'differential_evolution':

        def wrapped_callback(res):
            return callback(np.copy(res.x), res.convergence)
    else:

        def wrapped_callback(res):
            return callback(np.copy(res.x))
    wrapped_callback.stop_iteration = False
    return wrapped_callback

def buttap(N, *, xp=None, device=None):
    if xp is None:
        xp = np_compat
    if abs(int(N)) != N:
        raise ValueError('Filter order must be a nonnegative integer')
    z = xp.asarray([], device=device, dtype=xp.float64)
    m = xp.arange(-N + 1, N, 2, device=device, dtype=xp.float64)
    p = -xp.exp(1j * xp.pi * m / (2 * N))
    k = 1.0
    return (z, p, k)

def besselap(N, norm='phase', *, xp=None, device=None):
    if xp is None:
        xp = np_compat
    if abs(int(N)) != N:
        raise ValueError('Filter order must be a nonnegative integer')
    N = int(N)
    if N == 0:
        p = []
        k = 1
    else:
        p = 1 / _bessel_zeros(N)
        a_last = _falling_factorial(2 * N, N) // 2 ** N
        if norm in ('delay', 'mag'):
            k = a_last
            if norm == 'mag':
                norm_factor = _norm_factor(p, k)
                p /= norm_factor
                k = norm_factor ** (-N) * a_last
        elif norm == 'phase':
            p *= 10 ** (-math.log10(a_last) / N)
            k = 1
        else:
            raise ValueError('normalization not understood')
    z = xp.asarray([], device=device, dtype=xp.float64)
    return (z, xp.asarray(p, device=device, dtype=xp.complex128), float(k))

# --- helper: scipy.signal._filter_design._bessel_zeros ---
def _bessel_zeros(N):
    if N == 0:
        return np.asarray([])
    x0 = _campos_zeros(N)

    def f(x):
        return special.kve(N + 0.5, 1 / x)

    def fp(x):
        return special.kve(N - 0.5, 1 / x) / (2 * x ** 2) - special.kve(N + 0.5, 1 / x) / x ** 2 + special.kve(N + 1.5, 1 / x) / (2 * x ** 2)
    x = _aberth(f, fp, x0)
    for i in range(len(x)):
        x[i] = optimize.newton(f, x[i], fp, tol=1e-15)
    x = np.mean((x, x[::-1].conj()), 0)
    if abs(np.sum(x) + 1) > 1e-15:
        raise RuntimeError('Generated zeros are inaccurate')
    return x

# --- helper: scipy.signal._filter_design._falling_factorial ---
def _falling_factorial(x, n):
    val = 1
    for k in range(x - n + 1, x + 1):
        val *= k
    return val

# --- helper: scipy.signal._filter_design._norm_factor ---
def _norm_factor(p, k):
    p = np.asarray(p, dtype=np.complex128)

    def G(w):
        return np.abs(k / np.prod(1j * w - p))

    def cutoff(w):
        return G(w) - 1 / math.sqrt(2)
    return optimize.newton(cutoff, 1.5)

def cheb1ap(N, rp, *, xp=None, device=None):
    if xp is None:
        xp = np_compat
    if abs(int(N)) != N:
        raise ValueError('Filter order must be a nonnegative integer')
    elif N == 0:
        return (xp.asarray([], device=device, dtype=xp.float64), xp.asarray([], device=device, dtype=xp.complex128), 10 ** (-rp / 20))
    z = xp.asarray([], device=device, dtype=xp.float64)
    eps = math.sqrt(10 ** (0.1 * rp) - 1.0)
    mu = 1.0 / N * math.asinh(1 / eps)
    m = xp.arange(-N + 1, N, 2, dtype=xp.float64, device=device)
    theta = xp.pi * m / (2 * N)
    p = -xp.sinh(mu + 1j * theta)
    k = xp.real(xp.prod(-p, axis=0))
    if N % 2 == 0:
        k = k / math.sqrt(1 + eps * eps)
    return (z, p, k)

def chirp(t, f0, t1, f1, method='linear', phi=0, vertex_zero=True, *, complex=False):
    phase = _chirp_phase(t, f0, t1, f1, method, vertex_zero) + np.deg2rad(phi)
    return np.exp(1j * phase) if complex else np.cos(phase)

# --- helper: scipy.signal._waveforms._chirp_phase ---
def _chirp_phase(t, f0, t1, f1, method='linear', vertex_zero=True):
    t = asarray(t)
    f0 = float(f0)
    t1 = float(t1)
    f1 = float(f1)
    if method in ['linear', 'lin', 'li']:
        beta = (f1 - f0) / t1
        phase = 2 * pi * (f0 * t + 0.5 * beta * t * t)
    elif method in ['quadratic', 'quad', 'q']:
        beta = (f1 - f0) / t1 ** 2
        if vertex_zero:
            phase = 2 * pi * (f0 * t + beta * t ** 3 / 3)
        else:
            phase = 2 * pi * (f1 * t + beta * ((t1 - t) ** 3 - t1 ** 3) / 3)
    elif method in ['logarithmic', 'log', 'lo']:
        if f0 * f1 <= 0.0:
            raise ValueError('For a logarithmic chirp, f0 and f1 must be nonzero and have the same sign.')
        if f0 == f1:
            phase = 2 * pi * f0 * t
        else:
            beta = t1 / log(f1 / f0)
            phase = 2 * pi * beta * f0 * (pow(f1 / f0, t / t1) - 1.0)
    elif method in ['hyperbolic', 'hyp']:
        if f0 == 0 or f1 == 0:
            raise ValueError('For a hyperbolic chirp, f0 and f1 must be nonzero.')
        if f0 == f1:
            phase = 2 * pi * f0 * t
        else:
            sing = -f1 * t1 / (f0 - f1)
            phase = 2 * pi * (-sing * f0) * log(np.abs(1 - t / sing))
    else:
        raise ValueError(f"method must be 'linear', 'quadratic', 'logarithmic', or 'hyperbolic', but a value of {method!r} was given.")
    return phase

def cheb2ap(N, rs, *, xp=None, device=None):
    if xp is None:
        xp = np_compat
    if abs(int(N)) != N:
        raise ValueError('Filter order must be a nonnegative integer')
    elif N == 0:
        return (xp.asarray([], device=device, dtype=xp.complex128), xp.asarray([], device=device, dtype=xp.complex128), 1.0)
    de = 1.0 / math.sqrt(10 ** (0.1 * rs) - 1)
    mu = math.asinh(1.0 / de) / N
    if N % 2:
        m = xp.concat((xp.arange(-N + 1, 0, 2, dtype=xp.float64, device=device), xp.arange(2, N, 2, dtype=xp.float64, device=device)))
    else:
        m = xp.arange(-N + 1, N, 2, dtype=xp.float64, device=device)
    z = 1j / xp.sin(m * xp.pi / (2 * N))
    m1 = xp.arange(-N + 1, N, 2, dtype=xp.float64, device=device)
    theta1 = xp.pi * m1 / (2 * N)
    p = -1 / xp.sinh(mu + 1j * theta1)
    k = xp.real(xp.prod(-p, axis=0) / xp.prod(-z, axis=0))
    return (z, p, k)

def closest_STFT_dual_window(win: np.ndarray, hop: int, desired_dual: np.ndarray | None=None, *, scaled: bool=True) -> tuple[np.ndarray, float | complex]:
    if desired_dual is None:
        desired_dual = np.ones_like(win)
    if not (win.ndim == 1 and win.shape == desired_dual.shape):
        raise ValueError('Parameters `win` and `desired_dual` are not 1d arrays of ' + f'equal length (win.shape={win.shape!r}, desired_dual.shape={desired_dual.shape!r})!')
    if not all(np.isfinite(win)):
        raise ValueError('Parameter win must have finite entries!')
    if not all(np.isfinite(desired_dual)):
        raise ValueError('Parameter desired_dual must have finite entries!')
    if not (1 <= hop <= len(win) and isinstance(hop, int | np.integer)):
        raise ValueError(f'Parameter hop={hop!r} is not an integer between 1 and ' + f'len(win)={len(win)!r}!')
    w_d = _calc_dual_canonical_window(win, hop)
    wdd = win.conjugate() * desired_dual
    q_d = wdd.copy()
    for k_ in range(hop, len(win), hop):
        q_d[k_:] += wdd[:-k_]
        q_d[:-k_] += wdd[k_:]
    q_d = w_d * q_d
    if not scaled:
        return (w_d + desired_dual - q_d, 1.0)
    numerator = q_d.conjugate().T @ w_d
    denominator = q_d.T.real @ q_d.real + q_d.T.imag @ q_d.imag
    if not (abs(numerator) > 0 and denominator > np.finfo(w_d.dtype).resolution):
        raise ValueError('Unable to calculate scaled closest dual window due to numerically ' + 'unstable scaling factor! Try setting parameter `scaled` to False.')
    alpha = numerator / denominator
    return (w_d + alpha * (desired_dual - q_d), alpha)

# --- helper: scipy.signal._short_time_fft._calc_dual_canonical_window ---
def _calc_dual_canonical_window(win: np.ndarray, hop: int) -> np.ndarray:
    if hop > len(win):
        raise ValueError(f'hop={hop!r} is larger than window length of {len(win)}' + ' => STFT not invertible!')
    if issubclass(win.dtype.type, np.integer):
        raise ValueError("Parameter 'win' cannot be of integer type, but " + f'win.dtype={win.dtype!r} => STFT not invertible!')
    w2 = win.real ** 2 + win.imag ** 2
    DD = w2.copy()
    for k_ in range(hop, len(win), hop):
        DD[k_:] += w2[:-k_]
        DD[:-k_] += w2[k_:]
    relative_resolution = np.finfo(win.dtype).resolution * max(DD)
    if not np.all(DD >= relative_resolution):
        raise ValueError('Short-time Fourier Transform not invertible!')
    return win / DD

def coherence(x, y, fs=1.0, window='hann_periodic', nperseg=None, noverlap=None, nfft=None, detrend='constant', axis=-1):
    freqs, Pxx = welch(x, fs=fs, window=window, nperseg=nperseg, noverlap=noverlap, nfft=nfft, detrend=detrend, axis=axis)
    _, Pyy = welch(y, fs=fs, window=window, nperseg=nperseg, noverlap=noverlap, nfft=nfft, detrend=detrend, axis=axis)
    _, Pxy = csd(x, y, fs=fs, window=window, nperseg=nperseg, noverlap=noverlap, nfft=nfft, detrend=detrend, axis=axis)
    Cxy = np.abs(Pxy) ** 2 / Pxx / Pyy
    return (freqs, Cxy)

# --- helper: scipy.signal._spectral_py.csd ---
def csd(x, y, fs=1.0, window='hann_periodic', nperseg=None, noverlap=None, nfft=None, detrend='constant', return_onesided=True, scaling='density', axis=-1, average='mean'):
    same_data, axis = (y is x, int(axis))
    x = np.asarray(x)
    if not same_data:
        y = np.asarray(y)
        x_outer, y_outer = (list(x.shape), list(y.shape))
        x_outer.pop(axis)
        y_outer.pop(axis)
        try:
            outer_shape = np.broadcast_shapes(x_outer, y_outer)
        except ValueError as e:
            raise ValueError('x and y cannot be broadcast together.') from e
        if x.size == 0 or y.size == 0:
            out_shape = outer_shape + (min([x.shape[axis], y.shape[axis]]),)
            empty_out = np.moveaxis(np.empty(out_shape), -1, axis)
            return (empty_out, empty_out)
        out_dtype = np.result_type(x, y, np.complex64)
    else:
        if x.size == 0:
            return (np.empty(x.shape), np.empty(x.shape))
        out_dtype = np.result_type(x, np.complex64)
    n = x.shape[axis] if same_data else max(x.shape[axis], y.shape[axis])
    if isinstance(window, str) or isinstance(window, tuple):
        nperseg = int(nperseg) if nperseg is not None else 256
        if nperseg < 1:
            raise ValueError(f'Parameter nperseg={nperseg!r} is not a positive integer!')
        elif n < nperseg:
            warnings.warn(f'nperseg={nperseg!r} is greater than signal length max(len(x), ' + f'len(y)) = {n}, using nperseg = {n}', stacklevel=3)
            nperseg = n
        win = get_window(window, nperseg)
    else:
        win = np.asarray(window)
        if nperseg is None:
            nperseg = len(win)
    if nperseg != len(win):
        raise ValueError(f'nperseg={nperseg!r} does not equal len(win)={len(win)!r}')
    nfft = int(nfft) if nfft is not None else nperseg
    if nfft < nperseg:
        raise ValueError(f'nfft={nfft!r} must be greater than or equal to nperseg={nperseg!r}!')
    noverlap = int(noverlap) if noverlap is not None else nperseg // 2
    if noverlap >= nperseg:
        raise ValueError(f'noverlap={noverlap!r} must be less than nperseg={nperseg!r}!')
    if np.iscomplexobj(x) and return_onesided:
        return_onesided = False
    if x.shape[axis] < y.shape[axis]:
        z_shape = list(y.shape)
        z_shape[axis] = y.shape[axis] - x.shape[axis]
        x = np.concatenate((x, np.zeros(z_shape)), axis=axis)
    elif y.shape[axis] < x.shape[axis]:
        z_shape = list(x.shape)
        z_shape[axis] = x.shape[axis] - y.shape[axis]
        y = np.concatenate((y, np.zeros(z_shape)), axis=axis)
    fft_mode = cast(FFT_MODE_TYPE, 'onesided' if return_onesided else 'twosided')
    if scaling not in (scales := {'spectrum': 'magnitude', 'density': 'psd'}):
        raise ValueError(f'Parameter scaling={scaling!r} not in {scales}!')
    SFT = ShortTimeFFT(win, nperseg - noverlap, fs, fft_mode=fft_mode, mfft=nfft, scale_to=scales[scaling], phase_shift=None)
    Pxy = SFT.spectrogram(y, x, detr=None if detrend is False else detrend, p0=0, p1=(n - noverlap) // SFT.hop, k_offset=nperseg // 2, axis=axis)
    if return_onesided:
        f_axis = Pxy.ndim - 1 + axis if axis < 0 else axis
        Pxy = np.moveaxis(Pxy, f_axis, -1)
        Pxy[..., 1:-1 if SFT.mfft % 2 == 0 else None] *= 2
        Pxy = np.moveaxis(Pxy, -1, f_axis)
    if Pxy.shape[-1] > 1:
        if average == 'median':
            bias = _median_bias(Pxy.shape[-1])
            if np.iscomplexobj(Pxy):
                Pxy = np.median(np.real(Pxy), axis=-1) + np.median(np.imag(Pxy), axis=-1) * 1j
            else:
                Pxy = np.median(Pxy, axis=-1)
            Pxy /= bias
        elif average == 'mean':
            Pxy = Pxy.mean(axis=-1)
        else:
            raise ValueError(f"Parameter average={average!r} must be 'median' or 'mean'!")
    else:
        Pxy = np.reshape(Pxy, Pxy.shape[:-1])
    Pxy = Pxy.astype(out_dtype)
    if same_data:
        Pxy = Pxy.real
    return (SFT.f, Pxy)

