# --- helper: scipy.signal._spectral_py._median_bias ---
def _median_bias(n):
    ii_2 = 2 * np.arange(1.0, (n - 1) // 2 + 1)
    return 1 + np.sum(1.0 / (ii_2 + 1) - 1.0 / ii_2)

def firwin(numtaps, cutoff, *, width=None, window='hamming', pass_zero=True, scale=True, fs=None):
    xp = array_namespace(cutoff)
    fs = _validate_fs(fs, allow_none=True)
    fs = 2 if fs is None else fs
    nyq = 0.5 * fs
    cutoff = xp.asarray(cutoff, dtype=xp_default_dtype(xp))
    cutoff = xpx.atleast_nd(cutoff, ndim=1, xp=xp) / float(nyq)
    if cutoff.ndim > 1:
        raise ValueError('The cutoff argument must be at most one-dimensional.')
    if xp_size(cutoff) == 0:
        raise ValueError('At least one cutoff frequency must be given.')
    if xp.min(cutoff) <= 0 or xp.max(cutoff) >= 1:
        raise ValueError('Invalid cutoff frequency: frequencies must be greater than 0 and less than fs/2.')
    if xp.any(cutoff[1:] - cutoff[:-1] <= 0):
        raise ValueError('Invalid cutoff frequencies: the frequencies must be strictly increasing.')
    if width is not None:
        atten = kaiser_atten(numtaps, float(width) / nyq)
        beta = kaiser_beta(atten)
        window = ('kaiser', beta)
    if pass_zero in ('bandstop', 'lowpass'):
        if pass_zero == 'lowpass':
            if xp_size(cutoff) != 1:
                raise ValueError(f'cutoff must have one element if pass_zero=="lowpass", got {cutoff.shape}')
        elif xp_size(cutoff) <= 1:
            raise ValueError(f'cutoff must have at least two elements if pass_zero=="bandstop", got {cutoff.shape}')
        pass_zero = True
    elif pass_zero in ('bandpass', 'highpass'):
        if pass_zero == 'highpass':
            if xp_size(cutoff) != 1:
                raise ValueError(f'cutoff must have one element if pass_zero=="highpass", got {cutoff.shape}')
        elif xp_size(cutoff) <= 1:
            raise ValueError(f'cutoff must have at least two elements if pass_zero=="bandpass", got {cutoff.shape}')
        pass_zero = False
    elif not (pass_zero is True or pass_zero is False):
        raise ValueError(f"Parameter pass_zero={pass_zero!r} not in (True, False, 'bandpass', " + "'lowpass', 'highpass', 'bandstop')")
    pass_nyquist = (xp_size(cutoff) % 2 == 0) == pass_zero
    if pass_nyquist and numtaps % 2 == 0:
        raise ValueError('A filter with an even number of coefficients must have zero response at the Nyquist frequency.')
    cutoff = xp.concat((xp.zeros(int(pass_zero)), cutoff, xp.ones(int(pass_nyquist))))
    bands = xp.reshape(cutoff, (-1, 2))
    alpha = 0.5 * (numtaps - 1)
    m = xp.arange(0, numtaps, dtype=cutoff.dtype) - alpha
    h = 0
    for j in range(bands.shape[0]):
        left, right = (bands[j, 0], bands[j, 1])
        h += right * xpx.sinc(right * m, xp=xp)
        h -= left * xpx.sinc(left * m, xp=xp)
    win = get_window(window, numtaps, fftbins=False, xp=xp)
    h *= win
    if scale:
        left, right = bands[0, ...]
        if left == 0:
            scale_frequency = 0.0
        elif right == 1:
            scale_frequency = 1.0
        else:
            scale_frequency = 0.5 * (left + right)
        c = xp.cos(xp.pi * m * scale_frequency)
        s = xp.sum(h * c)
        h /= s
    return h

# --- helper: scipy.signal._fir_filter_design.kaiser_atten ---
def kaiser_atten(numtaps, width):
    a = 2.285 * (numtaps - 1) * np.pi * width + 7.95
    return a

# --- helper: scipy.signal._fir_filter_design.kaiser_beta ---
def kaiser_beta(a):
    if a > 50:
        beta = 0.1102 * (a - 8.7)
    elif a > 21:
        beta = 0.5842 * (a - 21) ** 0.4 + 0.07886 * (a - 21)
    else:
        beta = 0.0
    return beta

def firwin2(numtaps, freq, gain, *, nfreqs=None, window='hamming', antisymmetric=False, fs=None):
    xp = array_namespace(freq, gain)
    freq, gain = (xp.asarray(freq), xp.asarray(gain))
    fs = _validate_fs(fs, allow_none=True)
    fs = 2 if fs is None else fs
    nyq = 0.5 * fs
    if freq.shape[0] != gain.shape[0]:
        raise ValueError('freq and gain must be of same length.')
    if nfreqs is not None and numtaps >= nfreqs:
        raise ValueError(f'ntaps must be less than nfreqs, but firwin2 was called with ntaps={numtaps} and nfreqs={nfreqs}')
    if freq[0] != 0 or freq[-1] != nyq:
        raise ValueError('freq must start with 0 and end with fs/2.')
    d = freq[1:] - freq[:-1]
    if xp.any(d < 0):
        raise ValueError('The values in freq must be nondecreasing.')
    d2 = d[:-1] + d[1:]
    if xp.any(d2 == 0):
        raise ValueError('A value in freq must not occur more than twice.')
    if freq[1] == 0:
        raise ValueError('Value 0 must not be repeated in freq')
    if freq[-2] == nyq:
        raise ValueError('Value fs/2 must not be repeated in freq')
    if antisymmetric:
        if numtaps % 2 == 0:
            ftype = 4
        else:
            ftype = 3
    elif numtaps % 2 == 0:
        ftype = 2
    else:
        ftype = 1
    if ftype == 2 and gain[-1] != 0.0:
        raise ValueError('A Type II filter must have zero gain at the Nyquist frequency.')
    elif ftype == 3 and (gain[0] != 0.0 or gain[-1] != 0.0):
        raise ValueError('A Type III filter must have zero gain at zero and Nyquist frequencies.')
    elif ftype == 4 and gain[0] != 0.0:
        raise ValueError('A Type IV filter must have zero gain at zero frequency.')
    if nfreqs is None:
        nfreqs = 1 + 2 ** int(ceil(log(numtaps, 2)))
    if xp.any(d == 0):
        freq = xp.asarray(freq, copy=True)
        eps = xp.finfo(xp_default_dtype(xp)).eps * nyq
        for k in range(freq.shape[0] - 1):
            if freq[k] == freq[k + 1]:
                freq[k] = freq[k] - eps
                freq[k + 1] = freq[k + 1] + eps
        d = freq[1:] - freq[:-1]
        if xp.any(d <= 0):
            raise ValueError(f'freq cannot contain numbers that are too close (within eps * (fs/2): {eps}) to a repeated value')
    x = np.linspace(0.0, nyq, nfreqs)
    fx = np.interp(x, np.asarray(freq), np.asarray(gain))
    x = xp.asarray(x)
    fx = xp.asarray(fx)
    shift = xp.exp(-(numtaps - 1) / 2.0 * 1j * xp.pi * x / nyq)
    if ftype > 2:
        shift *= 1j
    fx2 = fx * shift
    out_full = irfft(fx2)
    if window is not None:
        wind = get_window(window, numtaps, fftbins=False, xp=xp)
    else:
        wind = 1
    out = out_full[:numtaps] * wind
    if ftype == 3:
        out[xp_size(out) // 2] = 0.0
    return out

def freqz_sos(sos, worN=512, whole=False, fs=2 * pi):
    xp = array_namespace(sos)
    fs = _validate_fs(fs, allow_none=False)
    sos, n_sections = _validate_sos(sos, xp)
    if n_sections == 0:
        raise ValueError('Cannot compute frequencies with no sections')
    h = 1.0
    for j in range(sos.shape[0]):
        row = sos[j, :]
        w, rowh = freqz(row[:3], row[3:], worN=worN, whole=whole, fs=fs)
        h *= rowh
    return (w, h)

# --- helper: scipy.signal._filter_design._validate_sos ---
def _validate_sos(sos, xp=None):
    if xp is None:
        xp = np
    sos = xp.asarray(sos)
    sos = xpx.atleast_nd(sos, ndim=2, xp=xp)
    if sos.ndim != 2:
        raise ValueError('sos array must be 2D')
    n_sections, m = sos.shape
    if m != 6:
        raise ValueError('sos array must be shape (n_sections, 6)')
    if not xp.all(sos[:, 3] == 1):
        raise ValueError('sos[:, 3] should be all ones')
    return (sos, n_sections)

# --- helper: scipy.signal._filter_design.freqz ---
def freqz(b, a=1, worN=512, whole=False, plot=None, fs=2 * pi, include_nyquist=False):
    xp = array_namespace(b, a)
    b, a = map(xp.asarray, (b, a))
    if xp.isdtype(a.dtype, 'integral'):
        a = xp.astype(a, xp_default_dtype(xp))
    res_dtype = xp.result_type(b, a)
    real_dtype = _real_dtype_for_complex(res_dtype, xp=xp)
    b = xpx.atleast_nd(b, ndim=1, xp=xp)
    a = xpx.atleast_nd(a, ndim=1, xp=xp)
    fs = _validate_fs(fs, allow_none=False)
    if worN is None:
        worN = 512
    h = None
    if _is_int_type(worN):
        N = operator.index(worN)
        del worN
        if N < 0:
            raise ValueError(f'worN must be nonnegative, got {N}')
        lastpoint = 2 * pi if whole else pi
        w = xp.linspace(0, lastpoint, N, endpoint=include_nyquist and (not whole), dtype=real_dtype)
        n_fft = N if whole else 2 * (N - 1) if include_nyquist else 2 * N
        if xp_size(a) == 1 and (b.ndim == 1 or b.shape[-1] == 1) and (n_fft >= b.shape[0]) and (n_fft > 0):
            if xp.isdtype(b.dtype, 'real floating') and xp.isdtype(a.dtype, 'real floating'):
                fft_func = sp_fft.rfft
            else:
                fft_func = sp_fft.fft
            h = fft_func(b, n=n_fft, axis=0)
            h = h[:min(N, h.shape[0]), ...]
            h /= a
            if fft_func is sp_fft.rfft and whole:
                stop = None if n_fft % 2 == 1 else -1
                h_flipped = xp.flip(h[1:stop, ...], axis=0)
                h = xp.concat((h, xp.conj(h_flipped)))
            if b.ndim > 1:
                h = h[..., 0]
                h = xp.moveaxis(h, 0, -1)
    else:
        if isinstance(worN, complex):
            worN = worN.real
        w = xpx.atleast_nd(xp.asarray(worN, dtype=res_dtype), ndim=1, xp=xp)
        if xp.isdtype(w.dtype, 'integral'):
            w = xp.astype(w, xp_default_dtype(xp))
        del worN
        w = 2 * pi * w / fs
    if h is None:
        zm1 = xp.exp(-1j * w)
        h = _pu.npp_polyval(zm1, b, tensor=False, xp=xp) / _pu.npp_polyval(zm1, a, tensor=False, xp=xp)
    w = w * (fs / (2 * pi))
    if plot is not None:
        plot(w, h)
    return (w, h)

def firwin_2d(hsize, window, *, fc=None, fs=2, circular=False, pass_zero=True, scale=True):
    if len(hsize) != 2:
        raise ValueError('hsize must be a 2-element tuple or list')
    if circular:
        if fc is None:
            raise ValueError('Cutoff frequency `fc` must be provided when `circular` is True')
        n_r = max(hsize[0], hsize[1]) * 8
        win_r = firwin(n_r, cutoff=fc, window=window, fs=fs)
        f1, f2 = np.meshgrid(np.linspace(-1, 1, hsize[0]), np.linspace(-1, 1, hsize[1]))
        r = np.sqrt(f1 ** 2 + f2 ** 2)
        win_2d = np.interp(r, np.linspace(0, 1, n_r), win_r)
        return win_2d
    if len(window) != 2:
        raise ValueError('window must be a 2-element tuple or list')
    row_filter = firwin(hsize[0], cutoff=fc, window=window[0], fs=fs)
    col_filter = firwin(hsize[1], cutoff=fc, window=window[1], fs=fs)
    return np.outer(row_filter, col_filter)

# --- helper: scipy.signal._fir_filter_design.firwin ---
def firwin(numtaps, cutoff, *, width=None, window='hamming', pass_zero=True, scale=True, fs=None):
    xp = array_namespace(cutoff)
    fs = _validate_fs(fs, allow_none=True)
    fs = 2 if fs is None else fs
    nyq = 0.5 * fs
    cutoff = xp.asarray(cutoff, dtype=xp_default_dtype(xp))
    cutoff = xpx.atleast_nd(cutoff, ndim=1, xp=xp) / float(nyq)
    if cutoff.ndim > 1:
        raise ValueError('The cutoff argument must be at most one-dimensional.')
    if xp_size(cutoff) == 0:
        raise ValueError('At least one cutoff frequency must be given.')
    if xp.min(cutoff) <= 0 or xp.max(cutoff) >= 1:
        raise ValueError('Invalid cutoff frequency: frequencies must be greater than 0 and less than fs/2.')
    if xp.any(cutoff[1:] - cutoff[:-1] <= 0):
        raise ValueError('Invalid cutoff frequencies: the frequencies must be strictly increasing.')
    if width is not None:
        atten = kaiser_atten(numtaps, float(width) / nyq)
        beta = kaiser_beta(atten)
        window = ('kaiser', beta)
    if pass_zero in ('bandstop', 'lowpass'):
        if pass_zero == 'lowpass':
            if xp_size(cutoff) != 1:
                raise ValueError(f'cutoff must have one element if pass_zero=="lowpass", got {cutoff.shape}')
        elif xp_size(cutoff) <= 1:
            raise ValueError(f'cutoff must have at least two elements if pass_zero=="bandstop", got {cutoff.shape}')
        pass_zero = True
    elif pass_zero in ('bandpass', 'highpass'):
        if pass_zero == 'highpass':
            if xp_size(cutoff) != 1:
                raise ValueError(f'cutoff must have one element if pass_zero=="highpass", got {cutoff.shape}')
        elif xp_size(cutoff) <= 1:
            raise ValueError(f'cutoff must have at least two elements if pass_zero=="bandpass", got {cutoff.shape}')
        pass_zero = False
    elif not (pass_zero is True or pass_zero is False):
        raise ValueError(f"Parameter pass_zero={pass_zero!r} not in (True, False, 'bandpass', " + "'lowpass', 'highpass', 'bandstop')")
    pass_nyquist = (xp_size(cutoff) % 2 == 0) == pass_zero
    if pass_nyquist and numtaps % 2 == 0:
        raise ValueError('A filter with an even number of coefficients must have zero response at the Nyquist frequency.')
    cutoff = xp.concat((xp.zeros(int(pass_zero)), cutoff, xp.ones(int(pass_nyquist))))
    bands = xp.reshape(cutoff, (-1, 2))
    alpha = 0.5 * (numtaps - 1)
    m = xp.arange(0, numtaps, dtype=cutoff.dtype) - alpha
    h = 0
    for j in range(bands.shape[0]):
        left, right = (bands[j, 0], bands[j, 1])
        h += right * xpx.sinc(right * m, xp=xp)
        h -= left * xpx.sinc(left * m, xp=xp)
    win = get_window(window, numtaps, fftbins=False, xp=xp)
    h *= win
    if scale:
        left, right = bands[0, ...]
        if left == 0:
            scale_frequency = 0.0
        elif right == 1:
            scale_frequency = 1.0
        else:
            scale_frequency = 0.5 * (left + right)
        c = xp.cos(xp.pi * m * scale_frequency)
        s = xp.sum(h * c)
        h /= s
    return h

def iirnotch(w0, Q, fs=2.0, *, xp=None, device=None):
    return _design_notch_peak_filter(w0, Q, 'notch', fs, xp=xp, device=device)

# --- helper: scipy.signal._filter_design._design_notch_peak_filter ---
def _design_notch_peak_filter(w0, Q, ftype, fs=2.0, *, xp=None, device=None):
    if xp is None:
        xp = np_compat
    fs = _validate_fs(fs, allow_none=False)
    w0 = float(w0)
    Q = float(Q)
    w0 = 2 * w0 / fs
    if w0 > 1.0 or w0 < 0.0:
        raise ValueError('w0 should be such that 0 < w0 < 1')
    bw = w0 / Q
    bw = bw * xp.pi
    w0 = w0 * xp.pi
    if ftype not in ('notch', 'peak'):
        raise ValueError('Unknown ftype.')
    beta = math.tan(bw / 2.0)
    gain = 1.0 / (1.0 + beta)
    if ftype == 'notch':
        b = gain * xp.asarray([1.0, -2.0 * math.cos(w0), 1.0], device=device)
    else:
        b = (1.0 - gain) * xp.asarray([1.0, 0.0, -1.0], device=device)
    a = xp.asarray([1.0, -2.0 * gain * math.cos(w0), 2.0 * gain - 1.0], device=device)
    return (b, a)

def iirpeak(w0, Q, fs=2.0, *, xp=None, device=None):
    return _design_notch_peak_filter(w0, Q, 'peak', fs, xp=xp, device=device)

# --- helper: scipy.signal._filter_design._design_notch_peak_filter ---
def _design_notch_peak_filter(w0, Q, ftype, fs=2.0, *, xp=None, device=None):
    if xp is None:
        xp = np_compat
    fs = _validate_fs(fs, allow_none=False)
    w0 = float(w0)
    Q = float(Q)
    w0 = 2 * w0 / fs
    if w0 > 1.0 or w0 < 0.0:
        raise ValueError('w0 should be such that 0 < w0 < 1')
    bw = w0 / Q
    bw = bw * xp.pi
    w0 = w0 * xp.pi
    if ftype not in ('notch', 'peak'):
        raise ValueError('Unknown ftype.')
    beta = math.tan(bw / 2.0)
    gain = 1.0 / (1.0 + beta)
    if ftype == 'notch':
        b = gain * xp.asarray([1.0, -2.0 * math.cos(w0), 1.0], device=device)
    else:
        b = (1.0 - gain) * xp.asarray([1.0, 0.0, -1.0], device=device)
    a = xp.asarray([1.0, -2.0 * gain * math.cos(w0), 2.0 * gain - 1.0], device=device)
    return (b, a)

def hilbert2(x, N=None, axes=(-2, -1)):
    xp = array_namespace(x)
    x = xpx.atleast_nd(xp.asarray(x), ndim=2, xp=xp)
    if xp.isdtype(x.dtype, 'complex floating'):
        raise ValueError('x must be real.')
    if len(axes) != 2:
        raise ValueError('axes must be a tuple of length 2')
    if axes[0] == axes[1]:
        raise ValueError('axes must contain 2 distinct axes')
    if N is None:
        N = (x.shape[axes[0]], x.shape[axes[1]])
    elif isinstance(N, int):
        if N <= 0:
            raise ValueError('N must be positive.')
        N = (N, N)
    elif len(N) != 2 or np.any(np.asarray(N) <= 0):
        raise ValueError('When given as a tuple, N must hold exactly two positive integers')
    Xf = sp_fft.fft2(x, N, axes=axes)
    Xf = xp.moveaxis(Xf, axes, (-2, -1))
    k0, k1 = ((N[0] + 1) // 2, (N[1] + 1) // 2)
    if k0 > 1:
        Xf[..., 1:k0, :] *= 2.0
    if k1 > 1:
        Xf[..., :, 1:k1] *= 2.0
    Xf[..., k0:, :] = 0.0
    Xf[..., :, k1:] = 0.0
    Xf = xp.moveaxis(Xf, (-2, -1), axes)
    x = sp_fft.ifft2(Xf, axes=axes)
    return x

def remez(numtaps, bands, desired, *, weight=None, type='bandpass', maxiter=25, grid_density=16, fs=None):
    xp = array_namespace(bands, desired, weight)
    bands = np.asarray(bands)
    desired = np.asarray(desired)
    if weight is not None:
        weight = np.asarray(weight)
    fs = _validate_fs(fs, allow_none=True)
    fs = 1.0 if fs is None else fs
    try:
        tnum = {'bandpass': 1, 'differentiator': 2, 'hilbert': 3}[type]
    except KeyError as e:
        raise ValueError("Type must be 'bandpass', 'differentiator', or 'hilbert'") from e
    if weight is None:
        weight = [1] * len(desired)
    bands = np.asarray(bands).copy()
    result = _sigtools._remez(numtaps, bands, desired, weight, tnum, fs, maxiter, grid_density)
    return xp.asarray(result)

def istft(Zxx, fs=1.0, window='hann_periodic', nperseg=None, noverlap=None, nfft=None, input_onesided=True, boundary=True, time_axis=-1, freq_axis=-2, scaling='spectrum'):
    Zxx = np.asarray(Zxx) + 0j
    freq_axis = int(freq_axis)
    time_axis = int(time_axis)
    if Zxx.ndim < 2:
        raise ValueError('Input stft must be at least 2d!')
    if freq_axis == time_axis:
        raise ValueError('Must specify differing time and frequency axes!')
    nseg = Zxx.shape[time_axis]
    if input_onesided:
        n_default = 2 * (Zxx.shape[freq_axis] - 1)
    else:
        n_default = Zxx.shape[freq_axis]
    if nperseg is None:
        nperseg = n_default
    else:
        nperseg = int(nperseg)
        if nperseg < 1:
            raise ValueError('nperseg must be a positive integer')
    if nfft is None:
        if input_onesided and nperseg == n_default + 1:
            nfft = nperseg
        else:
            nfft = n_default
    elif nfft < nperseg:
        raise ValueError('nfft must be greater than or equal to nperseg.')
    else:
        nfft = int(nfft)
    if noverlap is None:
        noverlap = nperseg // 2
    else:
        noverlap = int(noverlap)
    if noverlap >= nperseg:
        raise ValueError('noverlap must be less than nperseg.')
    nstep = nperseg - noverlap
    if time_axis != Zxx.ndim - 1 or freq_axis != Zxx.ndim - 2:
        if freq_axis < 0:
            freq_axis = Zxx.ndim + freq_axis
        if time_axis < 0:
            time_axis = Zxx.ndim + time_axis
        zouter = list(range(Zxx.ndim))
        for ax in sorted([time_axis, freq_axis], reverse=True):
            zouter.pop(ax)
        Zxx = np.transpose(Zxx, zouter + [freq_axis, time_axis])
    if isinstance(window, str) or type(window) is tuple:
        win = get_window(window, nperseg)
    else:
        win = np.asarray(window)
        if len(win.shape) != 1:
            raise ValueError('window must be 1-D')
        if win.shape[0] != nperseg:
            raise ValueError(f'window must have length of {nperseg}')
    ifunc = sp_fft.irfft if input_onesided else sp_fft.ifft
    xsubs = ifunc(Zxx, axis=-2, n=nfft)[..., :nperseg, :]
    outputlength = nperseg + (nseg - 1) * nstep
    x = np.zeros(list(Zxx.shape[:-2]) + [outputlength], dtype=xsubs.dtype)
    norm = np.zeros(outputlength, dtype=xsubs.dtype)
    if np.result_type(win, xsubs) != xsubs.dtype:
        win = win.astype(xsubs.dtype)
    if scaling == 'spectrum':
        xsubs *= win.sum()
    elif scaling == 'psd':
        xsubs *= np.sqrt(fs * sum(win ** 2))
    else:
        raise ValueError(f"Parameter scaling={scaling!r} not in ['spectrum', 'psd']!")
    for ii in range(nseg):
        x[..., ii * nstep:ii * nstep + nperseg] += xsubs[..., ii] * win
        norm[..., ii * nstep:ii * nstep + nperseg] += win ** 2
    if boundary:
        x = x[..., nperseg // 2:-(nperseg // 2)]
        norm = norm[..., nperseg // 2:-(nperseg // 2)]
    if np.sum(norm > 1e-10) != len(norm):
        warnings.warn('NOLA condition failed, STFT may not be invertible.' + (' Possibly due to missing boundary' if not boundary else ''), stacklevel=2)
    x /= np.where(norm > 1e-10, norm, 1.0)
    if input_onesided:
        x = x.real
    if x.ndim > 1:
        if time_axis != Zxx.ndim - 1:
            if freq_axis < time_axis:
                time_axis -= 1
            x = np.moveaxis(x, -1, time_axis)
    time = np.arange(x.shape[0]) / float(fs)
    return (time, x)

def savgol_coeffs(window_length, polyorder, deriv=0, delta=1.0, pos=None, use='conv', *, xp=None, device=None):
    if polyorder >= window_length:
        raise ValueError('polyorder must be less than window_length.')
    halflen, rem = divmod(window_length, 2)
    if pos is None:
        if rem == 0:
            pos = halflen - 0.5
        else:
            pos = halflen
    if not 0 <= pos < window_length:
        raise ValueError('pos must be nonnegative and less than window_length.')
    if use not in ['conv', 'dot']:
        raise ValueError("`use` must be 'conv' or 'dot'")
    xp = np_compat if xp is None else array_namespace(xp.empty(0))
    if deriv > polyorder:
        coeffs = xp.zeros(window_length, dtype=xp.float64, device=device)
        return coeffs
    x = xp.arange(-pos, window_length - pos, dtype=xp.float64, device=device)
    if use == 'conv':
        x = xp.flip(x)
    order = xp.reshape(xp.arange(polyorder + 1, dtype=xp.float64, device=device), (-1, 1))
    A = x ** order
    y = xp.zeros(polyorder + 1, dtype=xp.float64, device=device)
    y = xpx.at(y, deriv).set(float_factorial(deriv) / delta ** deriv)
    coeffs, _, _, _ = _pu._lstsq(A, y, xp=xp)
    return coeffs

def sosfreqz(*args, **kwargs):
    return freqz_sos(*args, **kwargs)

# --- helper: scipy.signal._filter_design.freqz_sos ---
def freqz_sos(sos, worN=512, whole=False, fs=2 * pi):
    xp = array_namespace(sos)
    fs = _validate_fs(fs, allow_none=False)
    sos, n_sections = _validate_sos(sos, xp)
    if n_sections == 0:
        raise ValueError('Cannot compute frequencies with no sections')
    h = 1.0
    for j in range(sos.shape[0]):
        row = sos[j, :]
        w, rowh = freqz(row[:3], row[3:], worN=worN, whole=whole, fs=fs)
        h *= rowh
    return (w, h)

@xp_capabilities()
def barthann(M, sym=True, *, xp=None, device=None):
    xp = _namespace(xp)
    if _len_guards(M):
        return xp.ones(M, dtype=xp.float64, device=device)
    M, needs_trunc = _extend(M, sym)
    n = xp.arange(0, M, dtype=xp.float64, device=device)
    fac = abs(n / (M - 1.0) - 0.5)
    w = 0.62 - 0.48 * fac + 0.38 * xp.cos(2 * xp.pi * fac)
    return _truncate(w, needs_trunc)

