@xp_capabilities(skip_backends=(('jax.numpy', 'item assignment'), ('dask.array', 'data-dependent output shapes')))
def chebwin(M, at, sym=True, *, xp=None, device=None):
    xp = _namespace(xp)
    if abs(at) < 45:
        warnings.warn('This window is not suitable for spectral analysis for attenuation values lower than about 45dB because the equivalent noise bandwidth of a Chebyshev window does not grow monotonically with increasing sidelobe attenuation when the attenuation is smaller than about 45 dB.', stacklevel=2)
    if _len_guards(M):
        return xp.ones(M, dtype=xp.float64, device=device)
    M, needs_trunc = _extend(M, sym)
    order = M - 1.0
    _val = xp.asarray(10 ** (abs(at) / 20.0), dtype=xp.float64, device=device)
    beta = xp.cosh(1.0 / order * xp.acosh(_val))
    k = xp.arange(M, dtype=xp.float64, device=device)
    x = beta * xp.cos(xp.pi * k / M)
    p = xp.zeros_like(x)
    p[x > 1] = xp.cosh(order * xp.acosh(x[x > 1]))
    p[x < -1] = (2 * (M % 2) - 1) * xp.cosh(order * xp.acosh(-x[x < -1]))
    p[abs(x) <= 1] = xp.cos(order * xp.acos(x[abs(x) <= 1]))
    if M % 2:
        w = xp.real(sp_fft.fft(p))
        n = (M + 1) // 2
        w = w[:n]
        w = xp.concat((xp.flip(w[1:n]), w))
    else:
        p = p * xp.exp(1j * xp.pi / M * xp.arange(M, dtype=xp.float64, device=device))
        w = xp.real(sp_fft.fft(p))
        n = M // 2 + 1
        w = xp.concat((xp.flip(w[1:n]), w[1:n]))
    w = w / xp.max(w)
    return _truncate(w, needs_trunc)

