# --- helper: scipy.signal.windows._windows._fftautocorr ---
def _fftautocorr(x):
    N = x.shape[-1]
    use_N = sp_fft.next_fast_len(2 * N - 1)
    x_fft = sp_fft.rfft(x, use_N, axis=-1)
    cxy = sp_fft.irfft(x_fft * x_fft.conj(), n=use_N)[:, :N]
    return cxy

