def block_array(blocks, *, format=None, dtype=None):
    return _block(blocks, format, dtype)

# --- helper: scipy.sparse._construct._block ---
def _block(blocks, format, dtype, return_spmatrix=False):
    blocks = np.asarray(blocks, dtype='object')
    if blocks.ndim != 2:
        raise ValueError('blocks must be 2-D')
    M, N = blocks.shape
    if format in (None, 'csr') and all((issparse(b) and b.format == 'csr' for b in blocks.flat)):
        if N > 1:
            blocks = [[_stack_along_minor_axis(blocks[b, :], 1)] for b in range(M)]
            blocks = np.asarray(blocks, dtype='object')
        A = _compressed_sparse_stack(blocks[:, 0], 0, return_spmatrix)
        if dtype is not None:
            A = A.astype(dtype, copy=False)
        return A
    elif format in (None, 'csc') and all((issparse(b) and b.format == 'csc' for b in blocks.flat)):
        if M > 1:
            blocks = [[_stack_along_minor_axis(blocks[:, b], 0) for b in range(N)]]
            blocks = np.asarray(blocks, dtype='object')
        A = _compressed_sparse_stack(blocks[0, :], 1, return_spmatrix)
        if dtype is not None:
            A = A.astype(dtype, copy=False)
        return A
    block_mask = np.zeros(blocks.shape, dtype=bool)
    brow_lengths = np.zeros(M, dtype=np.int64)
    bcol_lengths = np.zeros(N, dtype=np.int64)
    for i in range(M):
        for j in range(N):
            if blocks[i, j] is not None:
                A = coo_array(blocks[i, j])
                blocks[i, j] = A
                block_mask[i, j] = True
                if brow_lengths[i] == 0:
                    brow_lengths[i] = A._shape_as_2d[0]
                elif brow_lengths[i] != A._shape_as_2d[0]:
                    msg = f'blocks[{i},:] has incompatible row dimensions. Got blocks[{i},{j}].shape[0] == {A._shape_as_2d[0]}, expected {brow_lengths[i]}.'
                    raise ValueError(msg)
                if bcol_lengths[j] == 0:
                    bcol_lengths[j] = A._shape_as_2d[1]
                elif bcol_lengths[j] != A._shape_as_2d[1]:
                    msg = f'blocks[:,{j}] has incompatible column dimensions. Got blocks[{i},{j}].shape[1] == {A._shape_as_2d[1]}, expected {bcol_lengths[j]}.'
                    raise ValueError(msg)
    nnz = sum((block.nnz for block in blocks[block_mask]))
    if dtype is None:
        all_dtypes = [blk.dtype for blk in blocks[block_mask]]
        dtype = upcast(*all_dtypes) if all_dtypes else None
    row_offsets = np.append(0, np.cumsum(brow_lengths))
    col_offsets = np.append(0, np.cumsum(bcol_lengths))
    shape = (row_offsets[-1], col_offsets[-1])
    data = np.empty(nnz, dtype=dtype)
    idx_dtype = get_index_dtype([b.coords[0] for b in blocks[block_mask]], maxval=max(shape))
    row = np.empty(nnz, dtype=idx_dtype)
    col = np.empty(nnz, dtype=idx_dtype)
    nnz = 0
    ii, jj = np.nonzero(block_mask)
    for i, j in zip(ii, jj):
        B = blocks[i, j]
        idx = slice(nnz, nnz + B.nnz)
        data[idx] = B.data
        np.add(B.row, row_offsets[i], out=row[idx], dtype=idx_dtype)
        np.add(B.col, col_offsets[j], out=col[idx], dtype=idx_dtype)
        nnz += B.nnz
    if return_spmatrix:
        return coo_matrix((data, (row, col)), shape=shape).asformat(format)
    return coo_array((data, (row, col)), shape=shape).asformat(format)

@xp_capabilities()
def tukey(M, alpha=0.5, sym=True, *, xp=None, device=None):
    xp = _namespace(xp)
    if _len_guards(M):
        return xp.ones(M, dtype=xp.float64, device=device)
    if alpha <= 0:
        return xp.ones(M, dtype=xp.float64, device=device)
    elif alpha >= 1.0:
        return hann(M, sym=sym, xp=xp, device=device)
    M, needs_trunc = _extend(M, sym)
    n = xp.arange(0, M, dtype=xp.float64, device=device)
    width = int(math.floor(alpha * (M - 1) / 2.0))
    n1 = n[0:width + 1]
    n2 = n[width + 1:M - width - 1]
    n3 = n[M - width - 1:]
    w1 = 0.5 * (1 + xp.cos(xp.pi * (-1 + 2.0 * n1 / alpha / (M - 1))))
    w2 = xp.ones(n2.shape, device=device)
    w3 = 0.5 * (1 + xp.cos(xp.pi * (-2.0 / alpha + 1 + 2.0 * n3 / alpha / (M - 1))))
    w = xp.concat((w1, w2, w3))
    return _truncate(w, needs_trunc)

