    def __init__(self, grid_shape, *, boundary_conditions='neumann', dtype=np.int8):
        if boundary_conditions not in ('dirichlet', 'neumann', 'periodic'):
            raise ValueError(f"Unknown value {boundary_conditions!r} is given for 'boundary_conditions' parameter. The valid options are 'dirichlet', 'periodic', and 'neumann' (default).")
        self.grid_shape = grid_shape
        self.boundary_conditions = boundary_conditions
        N = np.prod(grid_shape)
        super().__init__(dtype=dtype, shape=(N, N))

    def _eigenvalue_ordering(self, m):
        grid_shape = self.grid_shape
        if m is None:
            indices = np.indices(grid_shape)
            Leig = np.zeros(grid_shape)
        else:
            grid_shape_min = min(grid_shape, tuple(np.ones_like(grid_shape) * m))
            indices = np.indices(grid_shape_min)
            Leig = np.zeros(grid_shape_min)
        for j, n in zip(indices, grid_shape):
            if self.boundary_conditions == 'dirichlet':
                Leig += -4 * np.sin(np.pi * (j + 1) / (2 * (n + 1))) ** 2
            elif self.boundary_conditions == 'neumann':
                Leig += -4 * np.sin(np.pi * j / (2 * n)) ** 2
            else:
                Leig += -4 * np.sin(np.pi * np.floor((j + 1) / 2) / n) ** 2
        Leig_ravel = Leig.ravel()
        ind = np.argsort(Leig_ravel)
        eigenvalues = Leig_ravel[ind]
        if m is not None:
            eigenvalues = eigenvalues[-m:]
            ind = ind[-m:]
        return (eigenvalues, ind)

    def eigenvalues(self, m=None):
        eigenvalues, _ = self._eigenvalue_ordering(m)
        return eigenvalues

    def _ev1d(self, j, n):
        if self.boundary_conditions == 'dirichlet':
            i = np.pi * (np.arange(n) + 1) / (n + 1)
            ev = np.sqrt(2.0 / (n + 1.0)) * np.sin(i * (j + 1))
        elif self.boundary_conditions == 'neumann':
            i = np.pi * (np.arange(n) + 0.5) / n
            ev = np.sqrt((1.0 if j == 0 else 2.0) / n) * np.cos(i * j)
        elif j == 0:
            ev = np.sqrt(1.0 / n) * np.ones(n)
        elif j + 1 == n and n % 2 == 0:
            ev = np.sqrt(1.0 / n) * np.tile([1, -1], n // 2)
        elif (j + 1) % 2 == 0:
            i = np.pi * (np.arange(n) + 0.5) / n
            ev = np.sqrt(2.0 / n) * np.sin(i * (j + 1))
        else:
            i = np.pi * (np.arange(n) + 0.5) / n
            ev = np.sqrt(2.0 / n) * np.cos(i * j)
        ev[np.abs(ev) < np.finfo(np.float64).eps] = 0.0
        return ev

    def _one_eve(self, k):
        phi = [self._ev1d(j, n) for j, n in zip(k, self.grid_shape)]
        result = phi[0]
        for phi in phi[1:]:
            result = np.tensordot(result, phi, axes=0)
        return np.asarray(result).ravel()

    def eigenvectors(self, m=None):
        _, ind = self._eigenvalue_ordering(m)
        if m is None:
            grid_shape_min = self.grid_shape
        else:
            grid_shape_min = min(self.grid_shape, tuple(np.ones_like(self.grid_shape) * m))
        N_indices = np.unravel_index(ind, grid_shape_min)
        N_indices = [tuple(x) for x in zip(*N_indices)]
        eigenvectors_list = [self._one_eve(k) for k in N_indices]
        return np.column_stack(eigenvectors_list)

    def toarray(self):
        grid_shape = self.grid_shape
        n = np.prod(grid_shape)
        L = np.zeros([n, n], dtype=np.int8)
        L_i = np.empty_like(L)
        Ltemp = np.empty_like(L)
        for ind, dim in enumerate(grid_shape):
            L_i[:] = 0
            np.einsum('ii->i', L_i[:dim, :dim])[:] = -2
            np.einsum('ii->i', L_i[:dim - 1, 1:dim])[:] = 1
            np.einsum('ii->i', L_i[1:dim, :dim - 1])[:] = 1
            if self.boundary_conditions == 'neumann':
                L_i[0, 0] = -1
                L_i[dim - 1, dim - 1] = -1
            elif self.boundary_conditions == 'periodic':
                if dim > 1:
                    L_i[0, dim - 1] += 1
                    L_i[dim - 1, 0] += 1
                else:
                    L_i[0, 0] += 1
            new_dim = dim
            if ind > 0:
                tiles = np.prod(grid_shape[:ind])
                for j in range(1, tiles):
                    L_i[j * dim:(j + 1) * dim, j * dim:(j + 1) * dim] = L_i[:dim, :dim]
                    new_dim += dim
            Ltemp[:new_dim, :new_dim] = L_i[:new_dim, :new_dim]
            tiles = int(np.prod(grid_shape[ind + 1:]))
            L_i[:new_dim, :new_dim] = 0
            idx = [x for x in range(tiles)]
            L_i.reshape((new_dim, tiles, new_dim, tiles))[:, idx, :, idx] = Ltemp[:new_dim, :new_dim]
            L += L_i
        return L.astype(self.dtype)

    def tosparse(self):
        N = len(self.grid_shape)
        p = np.prod(self.grid_shape)
        L = dia_array((p, p), dtype=np.int8)
        for i in range(N):
            dim = self.grid_shape[i]
            data = np.ones([3, dim], dtype=np.int8)
            data[1, :] *= -2
            if self.boundary_conditions == 'neumann':
                data[1, 0] = -1
                data[1, -1] = -1
            L_i = dia_array((data, [-1, 0, 1]), shape=(dim, dim), dtype=np.int8)
            if self.boundary_conditions == 'periodic':
                t = dia_array((dim, dim), dtype=np.int8)
                t.setdiag([1], k=-dim + 1)
                t.setdiag([1], k=dim - 1)
                L_i += t
            for j in range(i):
                L_i = kron(eye_array(self.grid_shape[j], dtype=np.int8), L_i)
            for j in range(i + 1, N):
                L_i = kron(L_i, eye_array(self.grid_shape[j], dtype=np.int8))
            L += L_i
        return L.astype(self.dtype)

    def _matvec(self, x):
        grid_shape = self.grid_shape
        N = len(grid_shape)
        X = x.reshape(grid_shape + (-1,))
        Y = -2 * N * X
        for i in range(N):
            Y += np.roll(X, 1, axis=i)
            Y += np.roll(X, -1, axis=i)
            if self.boundary_conditions in ('neumann', 'dirichlet'):
                Y[(slice(None),) * i + (0,) + (slice(None),) * (N - i - 1)] -= np.roll(X, 1, axis=i)[(slice(None),) * i + (0,) + (slice(None),) * (N - i - 1)]
                Y[(slice(None),) * i + (-1,) + (slice(None),) * (N - i - 1)] -= np.roll(X, -1, axis=i)[(slice(None),) * i + (-1,) + (slice(None),) * (N - i - 1)]
                if self.boundary_conditions == 'neumann':
                    Y[(slice(None),) * i + (0,) + (slice(None),) * (N - i - 1)] += np.roll(X, 0, axis=i)[(slice(None),) * i + (0,) + (slice(None),) * (N - i - 1)]
                    Y[(slice(None),) * i + (-1,) + (slice(None),) * (N - i - 1)] += np.roll(X, 0, axis=i)[(slice(None),) * i + (-1,) + (slice(None),) * (N - i - 1)]
        return Y.reshape(-1, X.shape[-1])

    def _matmat(self, x):
        return self._matvec(x)

    def _adjoint(self):
        return self

    def _transpose(self):
        return self

def bicg(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=None, M=None, callback=None):
    A, M, x, b = make_system(A, M, x0, b)
    bnrm2 = np.linalg.norm(b)
    atol, _ = _get_atol_rtol('bicg', bnrm2, atol, rtol)
    if bnrm2 == 0:
        return (b, 0)
    n = len(b)
    dotprod = np.vdot if np.iscomplexobj(x) else np.dot
    if maxiter is None:
        maxiter = n * 10
    matvec, rmatvec = (A.matvec, A.rmatvec)
    psolve, rpsolve = (M.matvec, M.rmatvec)
    rhotol = np.finfo(x.dtype.char).eps ** 2
    rho_prev, p, ptilde = (None, None, None)
    r = b - matvec(x) if x.any() else b.copy()
    rtilde = r.copy()
    for iteration in range(maxiter):
        if np.linalg.norm(r) < atol:
            return (x, 0)
        z = psolve(r)
        ztilde = rpsolve(rtilde)
        rho_cur = dotprod(rtilde, z)
        if np.abs(rho_cur) < rhotol:
            return (x, -10)
        if iteration > 0:
            beta = rho_cur / rho_prev
            p *= beta
            p += z
            ptilde *= beta.conj()
            ptilde += ztilde
        else:
            p = z.copy()
            ptilde = ztilde.copy()
        q = matvec(p)
        qtilde = rmatvec(ptilde)
        rv = dotprod(ptilde, q)
        if rv == 0:
            return (x, -11)
        alpha = rho_cur / rv
        x += alpha * p
        r -= alpha * q
        rtilde -= alpha.conj() * qtilde
        rho_prev = rho_cur
        if callback:
            callback(x)
    else:
        return (x, maxiter)

# --- helper: scipy.sparse.linalg._isolve.iterative._get_atol_rtol ---
def _get_atol_rtol(name, b_norm, atol=0.0, rtol=1e-05):
    if atol == 'legacy' or atol is None or atol < 0:
        msg = f"'scipy.sparse.linalg.{name}' called with invalid `atol`={atol}; if set, `atol` must be a real, non-negative number."
        raise ValueError(msg)
    atol = max(float(atol), float(rtol) * float(b_norm))
    return (atol, rtol)

def cg(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=None, M=None, callback=None):
    A, M, x, b = make_system(A, M, x0, b)
    bnrm2 = np.linalg.norm(b)
    atol, _ = _get_atol_rtol('cg', bnrm2, atol, rtol)
