def bicgstab(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=None, M=None, callback=None):
    A, M, x, b = make_system(A, M, x0, b)
    bnrm2 = np.linalg.norm(b)
    atol, _ = _get_atol_rtol('bicgstab', bnrm2, atol, rtol)
    if bnrm2 == 0:
        return (b, 0)
    n = len(b)
    dotprod = np.vdot if np.iscomplexobj(x) else np.dot
    if maxiter is None:
        maxiter = n * 10
    matvec = A.matvec
    psolve = M.matvec
    rhotol = np.finfo(x.dtype.char).eps ** 2
    omegatol = rhotol
    rho_prev, omega, alpha, p, v = (None, None, None, None, None)
    r = b - matvec(x) if x.any() else b.copy()
    rtilde = r.copy()
    for iteration in range(maxiter):
        if np.linalg.norm(r) < atol:
            return (x, 0)
        rho = dotprod(rtilde, r)
        if np.abs(rho) < rhotol:
            return (x, -10)
        if iteration > 0:
            if np.abs(omega) < omegatol:
                return (x, -11)
            beta = rho / rho_prev * (alpha / omega)
            p -= omega * v
            p *= beta
            p += r
        else:
            s = np.empty_like(r)
            p = r.copy()
        phat = psolve(p)
        v = matvec(phat)
        rv = dotprod(rtilde, v)
        if rv == 0:
            return (x, -11)
        alpha = rho / rv
        r -= alpha * v
        s[:] = r[:]
        if np.linalg.norm(s) < atol:
            x += alpha * phat
            return (x, 0)
        shat = psolve(s)
        t = matvec(shat)
        omega = dotprod(t, s) / dotprod(t, t)
        x += alpha * phat
        x += omega * shat
        r -= omega * t
        rho_prev = rho
        if callback:
            callback(x)
    else:
        return (x, maxiter)

