        msg = f"'scipy.sparse.linalg.{name}' called with invalid `atol`={atol}; if set, `atol` must be a real, non-negative number."
        raise ValueError(msg)
    atol = max(float(atol), float(rtol) * float(b_norm))
    return (atol, rtol)

def cgs(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=None, M=None, callback=None):
    A, M, x, b = make_system(A, M, x0, b)
    bnrm2 = np.linalg.norm(b)
    atol, _ = _get_atol_rtol('cgs', bnrm2, atol, rtol)
    if bnrm2 == 0:
        return (b, 0)
    n = len(b)
    dotprod = np.vdot if np.iscomplexobj(x) else np.dot
    if maxiter is None:
        maxiter = n * 10
    matvec = A.matvec
    psolve = M.matvec
    rhotol = np.finfo(x.dtype.char).eps ** 2
    r = b - matvec(x) if x.any() else b.copy()
    rtilde = r.copy()
    bnorm = np.linalg.norm(b)
    if bnorm == 0:
        bnorm = 1
    rho_prev, p, u, q = (None, None, None, None)
    for iteration in range(maxiter):
        rnorm = np.linalg.norm(r)
        if rnorm < atol:
            return (x, 0)
        rho_cur = dotprod(rtilde, r)
        if np.abs(rho_cur) < rhotol:
            return (x, -10)
        if iteration > 0:
            beta = rho_cur / rho_prev
            u[:] = r[:]
            u += beta * q
            p *= beta
            p += q
            p *= beta
            p += u
        else:
            p = r.copy()
            u = r.copy()
            q = np.empty_like(r)
        phat = psolve(p)
        vhat = matvec(phat)
        rv = dotprod(rtilde, vhat)
        if rv == 0:
            return (x, -11)
        alpha = rho_cur / rv
        q[:] = u[:]
        q -= alpha * vhat
        uhat = psolve(u + q)
        x += alpha * uhat
        r = b - matvec(x)
        rho_prev = rho_cur
        if callback:
            callback(x)
    else:
        return (x, maxiter)

