        raise ValueError(msg)
    atol = max(float(atol), float(rtol) * float(b_norm))
    return (atol, rtol)

def funm_multiply_krylov(f, A, b, *, assume_a='general', t=1.0, atol=0.0, rtol=1e-06, restart_every_m=None, max_restarts=20):
    if assume_a not in {'hermitian', 'general', 'her', 'gen'}:
        raise ValueError(f'scipy.sparse.linalg.funm_multiply_krylov: {assume_a} is not a recognized matrix structure')
    is_hermitian = assume_a == 'her' or assume_a == 'hermitian'
    if len(b.shape) != 1:
        raise ValueError("scipy.sparse.linalg.funm_multiply_krylov: argument 'b' must be a 1D array.")
    n = b.shape[0]
    if restart_every_m is None:
        restart_every_m = min(20, n)
    restart_every_m = int(restart_every_m)
    max_restarts = int(max_restarts)
    if restart_every_m <= 0:
        raise ValueError("scipy.sparse.linalg.funm_multiply_krylov: argument 'restart_every_m' must be positive.")
    if max_restarts <= 0:
        raise ValueError("scipy.sparse.linalg.funm_multiply_krylov: argument 'max_restarts' must be positive.")
    m = restart_every_m
    max_restarts = min(max_restarts, int(n / m) + 1)
    mmax = m * max_restarts
    bnorm = norm(b)
    atol, _ = _get_atol_rtol('funm_multiply_krylov', bnorm, atol, rtol)
    if bnorm == 0:
        y = np.array(b)
        return y
    internal_type = np.common_type(A, b)
    V = np.zeros((n, m + 1), dtype=internal_type, order='F')
    H = np.zeros((mmax + 1, mmax), dtype=internal_type, order='F')
    restart = 1
    if is_hermitian:
        breakdown, j = _funm_multiply_krylov_lanczos(A, b, bnorm, V, H[:m + 1, :m], m)
    else:
        breakdown, j = _funm_multiply_krylov_arnoldi(A, b, bnorm, V, H[:m + 1, :m], m)
    fH = f(t * H[:j, :j])
    y = bnorm * V[:, :j].dot(fH[:, 0])
    if breakdown:
        return y
    update_norm = norm(bnorm * fH[:, 0])
    while restart < max_restarts and update_norm > atol:
        begin = restart * m
        end = (restart + 1) * m
        if is_hermitian:
            breakdown, j = _funm_multiply_krylov_lanczos(A, V[:, m], 1, V, H[begin:end + 1, begin:end], m)
        else:
            breakdown, j = _funm_multiply_krylov_arnoldi(A, V[:, m], 1, V, H[begin:end + 1, begin:end], m)
        if breakdown:
            end = begin + j
            fH = f(t * H[:end, :end])
            y[:end] = y[:end] + bnorm * V[:, :m].dot(fH[begin:end, 0])
            return y
        fH = f(t * H[:end, :end])
        y = y + bnorm * V[:, :m].dot(fH[begin:end, 0])
        update_norm = norm(bnorm * fH[begin:end, 0])
        restart += 1
    return y

# --- helper: scipy.sparse.linalg._funm_multiply_krylov._funm_multiply_krylov_arnoldi ---
def _funm_multiply_krylov_arnoldi(A, b, bnorm, V, H, m):
    dotprod = np.vdot if np.iscomplexobj(b) else np.dot
    norm_tol = np.finfo(b.dtype.char).eps ** 2
    V[:, 0] = b / bnorm
    for k in range(0, m):
        V[:, k + 1] = A.dot(V[:, k])
        for i in range(0, k + 1):
            H[i, k] = dotprod(V[:, i], V[:, k + 1])
            V[:, k + 1] = V[:, k + 1] - H[i, k] * V[:, i]
        H[k + 1, k] = norm(V[:, k + 1])
        if H[k + 1, k] < norm_tol:
            return (True, k)
        V[:, k + 1] = V[:, k + 1] / H[k + 1, k]
    return (False, m)

# --- helper: scipy.sparse.linalg._funm_multiply_krylov._funm_multiply_krylov_lanczos ---
def _funm_multiply_krylov_lanczos(A, b, bnorm, V, H, m):
    dotprod = np.vdot if np.iscomplexobj(b) else np.dot
    norm_tol = np.finfo(b.dtype.char).eps ** 2
    V[:, 0] = b / bnorm
    for k in range(0, m):
        if k > 0:
            V[:, k + 1] = A.dot(V[:, k]) - H[k, k - 1] * V[:, k - 1]
        else:
            V[:, k + 1] = A.dot(V[:, k])
        H[k, k] = dotprod(V[:, k + 1], V[:, k])
        V[:, k + 1] = V[:, k + 1] - H[k, k] * V[:, k]
        H[k + 1, k] = norm(V[:, k + 1])
        if H[k + 1, k] < norm_tol:
            return (True, k)
        V[:, k + 1] = V[:, k + 1] / H[k + 1, k]
        if k < m - 1:
            H[k, k + 1] = H[k + 1, k]
    return (False, m)

def is_sptriangular(A):
    if not (issparse(A) and A.format in ('csc', 'csr', 'coo', 'dia', 'dok', 'lil')):
        warn('is_sptriangular needs sparse and not BSR format. Converting to CSR.', SparseEfficiencyWarning, stacklevel=2)
        A = csr_array(A)
    if A.format == 'dia':
        return (A.offsets.max() <= 0, A.offsets.min() >= 0)
    elif A.format == 'coo':
        rows, cols = A.coords
        return ((cols <= rows).all(), (cols >= rows).all())
    elif A.format == 'dok':
        return (all((c <= r for r, c in A.keys())), all((c >= r for r, c in A.keys())))
    elif A.format == 'lil':
        lower = all((col <= row for row, cols in enumerate(A.rows) for col in cols))
        upper = all((col >= row for row, cols in enumerate(A.rows) for col in cols))
        return (lower, upper)
    indptr, indices = (A.indptr, A.indices)
    N = len(indptr) - 1
    lower, upper = (True, True)
    for col in [N // 2, 0, -1]:
        rows = indices[indptr[col]:indptr[col + 1]]
        upper = upper and (col >= rows).all()
        lower = lower and (col <= rows).all()
        if not upper and (not lower):
            return (False, False)
    cols = np.repeat(np.arange(N), np.diff(indptr))
    rows = indices
    upper = upper and (cols >= rows).all()
    lower = lower and (cols <= rows).all()
    if A.format == 'csr':
        return (upper, lower)
    return (lower, upper)

def matrix_power(A, power):
    M, N = A.shape
    if M != N:
        raise TypeError('sparse matrix is not square')
    if isintlike(power):
        power = int(power)
        if power < 0:
            raise ValueError('exponent must be >= 0')
        if power == 0:
            return eye_array(M, dtype=A.dtype)
        if power == 1:
            return A.copy()
        tmp = matrix_power(A, power // 2)
        if power % 2:
            return A @ tmp @ tmp
        else:
            return tmp @ tmp
    else:
        raise ValueError('exponent must be an integer')

def gmres(A, b, x0=None, *, rtol=1e-05, atol=0.0, restart=None, maxiter=None, M=None, callback=None, callback_type=None):
    if callback is not None and callback_type is None:
        msg = "scipy.sparse.linalg.gmres called without specifying `callback_type`. The default value will be changed in a future release. For compatibility, specify a value for `callback_type` explicitly, e.g., ``gmres(..., callback_type='pr_norm')``, or to retain the old behavior ``gmres(..., callback_type='legacy')``"
        warnings.warn(msg, category=DeprecationWarning, stacklevel=3)
    if callback_type is None:
        callback_type = 'legacy'
    if callback_type not in ('x', 'pr_norm', 'legacy'):
        raise ValueError(f'Unknown callback_type: {callback_type!r}')
    if callback is None:
        callback_type = None
    A, M, x, b = make_system(A, M, x0, b)
    matvec = A.matvec
    psolve = M.matvec
    n = len(b)
    bnrm2 = np.linalg.norm(b)
    atol, _ = _get_atol_rtol('gmres', bnrm2, atol, rtol)
    if bnrm2 == 0:
        return (b, 0)
    eps = np.finfo(x.dtype.char).eps
    dotprod = np.vdot if np.iscomplexobj(x) else np.dot
    if maxiter is None:
        maxiter = n * 10
    if restart is None:
        restart = 20
    restart = min(restart, n)
    Mb_nrm2 = np.linalg.norm(psolve(b))
    ptol_max_factor = 1.0
    ptol = Mb_nrm2 * min(ptol_max_factor, atol / bnrm2)
    presid = 0.0
    lartg = get_lapack_funcs('lartg', dtype=x.dtype)
    v = np.empty([restart + 1, n], dtype=x.dtype)
    h = np.zeros([restart, restart + 1], dtype=x.dtype)
    givens = np.zeros([restart, 2], dtype=x.dtype)
    inner_iter = 0
    for iteration in range(maxiter):
        if iteration == 0:
            r = b - matvec(x) if x.any() else b.copy()
            if np.linalg.norm(r) < atol:
                return (x, 0)
        v[0, :] = psolve(r)
        tmp = np.linalg.norm(v[0, :])
        v[0, :] *= 1 / tmp
        S = np.zeros(restart + 1, dtype=x.dtype)
        S[0] = tmp
        breakdown = False
        for col in range(restart):
            av = matvec(v[col, :])
            w = psolve(av)
            h0 = np.linalg.norm(w)
            for k in range(col + 1):
                tmp = dotprod(v[k, :], w)
                h[col, k] = tmp
                w -= tmp * v[k, :]
            h1 = np.linalg.norm(w)
            h[col, col + 1] = h1
            v[col + 1, :] = w[:]
            if h1 <= eps * h0:
                h[col, col + 1] = 0
                breakdown = True
            else:
                v[col + 1, :] *= 1 / h1
            for k in range(col):
                c, s = (givens[k, 0], givens[k, 1])
                n0, n1 = h[col, [k, k + 1]]
                h[col, [k, k + 1]] = [c * n0 + s * n1, -s.conj() * n0 + c * n1]
            c, s, mag = lartg(h[col, col], h[col, col + 1])
            givens[col, :] = [c, s]
            h[col, [col, col + 1]] = (mag, 0)
            tmp = -np.conjugate(s) * S[col]
            S[[col, col + 1]] = [c * S[col], tmp]
            presid = np.abs(tmp)
            inner_iter += 1
            if callback_type in ('legacy', 'pr_norm'):
                callback(presid / bnrm2)
            if callback_type == 'legacy' and inner_iter == maxiter:
                break
            if presid <= ptol or breakdown:
                break
        if h[col, col] == 0:
            S[col] = 0
        y = np.zeros([col + 1], dtype=x.dtype)
        y[:] = S[:col + 1]
        for k in range(col, 0, -1):
            if y[k] != 0:
                y[k] /= h[k, k]
                tmp = y[k]
                y[:k] -= tmp * h[k, :k]
        if y[0] != 0:
            y[0] /= h[0, 0]
        x += y @ v[:col + 1, :]
        r = b - matvec(x)
        rnorm = np.linalg.norm(r)
        if callback_type == 'legacy' and inner_iter == maxiter:
            return (x, 0 if rnorm <= atol else maxiter)
        if callback_type == 'x':
            callback(x)
        if rnorm <= atol:
            break
        elif breakdown:
            break
        elif presid <= ptol:
            ptol_max_factor = max(eps, 0.25 * ptol_max_factor)
        else:
            ptol_max_factor = min(1.0, 1.5 * ptol_max_factor)
        ptol = presid * min(ptol_max_factor, atol / rnorm)
    info = 0 if rnorm <= atol else maxiter
    return (x, info)

# --- helper: scipy.sparse.linalg._isolve.iterative._get_atol_rtol ---
def _get_atol_rtol(name, b_norm, atol=0.0, rtol=1e-05):
    if atol == 'legacy' or atol is None or atol < 0:
        msg = f"'scipy.sparse.linalg.{name}' called with invalid `atol`={atol}; if set, `atol` must be a real, non-negative number."
        raise ValueError(msg)
    atol = max(float(atol), float(rtol) * float(b_norm))
    return (atol, rtol)

def lgmres(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=1000, M=None, callback=None, inner_m=30, outer_k=3, outer_v=None, store_outer_Av=True, prepend_outer_v=False):
    A, M, x, b = make_system(A, M, x0, b)
    if not np.isfinite(b).all():
        raise ValueError('RHS must contain only finite numbers')
    matvec = A.matvec
    psolve = M.matvec
    if outer_v is None:
        outer_v = []
    axpy, dot, scal = (None, None, None)
    nrm2 = get_blas_funcs('nrm2', [b])
    b_norm = nrm2(b)
    atol, rtol = _get_atol_rtol('lgmres', b_norm, atol, rtol)
    if b_norm == 0:
        x = b
        return (x, 0)
    ptol_max_factor = 1.0
    for k_outer in range(maxiter):
        r_outer = matvec(x) - b
        if callback is not None:
            callback(x)
        if axpy is None:
            if np.iscomplexobj(r_outer) and (not np.iscomplexobj(x)):
                x = x.astype(r_outer.dtype)
            axpy, dot, scal, nrm2 = get_blas_funcs(['axpy', 'dot', 'scal', 'nrm2'], (x, r_outer))
        r_norm = nrm2(r_outer)
        if r_norm <= max(atol, rtol * b_norm):
            break
        v0 = -psolve(r_outer)
        inner_res_0 = nrm2(v0)
        if inner_res_0 == 0:
            rnorm = nrm2(r_outer)
            raise RuntimeError(f'Preconditioner returned a zero vector; |v| ~ {rnorm:.1g}, |M v| = 0')
        v0 = scal(1.0 / inner_res_0, v0)
        ptol = min(ptol_max_factor, max(atol, rtol * b_norm) / r_norm)
        try:
            Q, R, B, vs, zs, y, pres = _fgmres(matvec, v0, inner_m, lpsolve=psolve, atol=ptol, outer_v=outer_v, prepend_outer_v=prepend_outer_v)
            y *= inner_res_0
            if not np.isfinite(y).all():
                raise LinAlgError()
        except LinAlgError:
            return (x, k_outer + 1)
        if pres > ptol:
            ptol_max_factor = min(1.0, 1.5 * ptol_max_factor)
        else:
            ptol_max_factor = max(1e-16, 0.25 * ptol_max_factor)
        dx = zs[0] * y[0]
        for w, yc in zip(zs[1:], y[1:]):
            dx = axpy(w, dx, dx.shape[0], yc)
        nx = nrm2(dx)
        if nx > 0:
            if store_outer_Av:
                q = Q.dot(R.dot(y))
                ax = vs[0] * q[0]
                for v, qc in zip(vs[1:], q[1:]):
                    ax = axpy(v, ax, ax.shape[0], qc)
                outer_v.append((dx / nx, ax / nx))
            else:
                outer_v.append((dx / nx, None))
        while len(outer_v) > outer_k:
            del outer_v[0]
        x += dx
    else:
        return (x, maxiter)
    return (x, 0)

def spbandwidth(A):
    if not (issparse(A) and A.format in ('csc', 'csr', 'coo', 'dia', 'dok')):
        warn('spbandwidth needs sparse format not LIL and BSR. Converting to CSR.', SparseEfficiencyWarning, stacklevel=2)
        A = csr_array(A)
    if A.format == 'dia':
        return (max(0, -A.offsets.min().item()), max(0, A.offsets.max().item()))
    if A.format in ('csc', 'csr'):
        indptr, indices = (A.indptr, A.indices)
        N = len(indptr) - 1
        gap = np.repeat(np.arange(N), np.diff(indptr)) - indices
        if A.format == 'csr':
            gap = -gap
    elif A.format == 'coo':
        gap = A.coords[1] - A.coords[0]
    elif A.format == 'dok':
        gap = [c - r for r, c in A.keys()] + [0]
        return (-min(gap), max(gap))
    return (max(-np.min(gap).item(), 0), max(np.max(gap).item(), 0))

def qmr(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=None, M1=None, M2=None, callback=None):
    A_ = A
    A, M, x, b = make_system(A, None, x0, b)
    bnrm2 = np.linalg.norm(b)
    atol, _ = _get_atol_rtol('qmr', bnrm2, atol, rtol)
    if bnrm2 == 0:
        return (b, 0)
    if M1 is None and M2 is None:
        if hasattr(A_, 'psolve'):

            def left_psolve(b):
                return A_.psolve(b, 'left')

            def right_psolve(b):
                return A_.psolve(b, 'right')

            def left_rpsolve(b):
                return A_.rpsolve(b, 'left')

            def right_rpsolve(b):
                return A_.rpsolve(b, 'right')
            M1 = LinearOperator(A.shape, matvec=left_psolve, rmatvec=left_rpsolve)
            M2 = LinearOperator(A.shape, matvec=right_psolve, rmatvec=right_rpsolve)
        else:

            def id(b):
                return b
            M1 = LinearOperator(A.shape, matvec=id, rmatvec=id)
            M2 = LinearOperator(A.shape, matvec=id, rmatvec=id)
    n = len(b)
    if maxiter is None:
        maxiter = n * 10
    dotprod = np.vdot if np.iscomplexobj(x) else np.dot
    rhotol = np.finfo(x.dtype.char).eps
    betatol = rhotol
    gammatol = rhotol
    deltatol = rhotol
    epsilontol = rhotol
    xitol = rhotol
    r = b - A.matvec(x) if x.any() else b.copy()
    vtilde = r.copy()
    y = M1.matvec(vtilde)
    rho = np.linalg.norm(y)
    wtilde = r.copy()
    z = M2.rmatvec(wtilde)
    xi = np.linalg.norm(z)
    gamma, eta, theta = (1, -1, 0)
    v = np.empty_like(vtilde)
    w = np.empty_like(wtilde)
    epsilon, q, d, p, s = (None, None, None, None, None)
    for iteration in range(maxiter):
        if np.linalg.norm(r) < atol:
            return (x, 0)
        if np.abs(rho) < rhotol:
            return (x, -10)
        if np.abs(xi) < xitol:
            return (x, -15)
        v[:] = vtilde[:]
        v *= 1 / rho
        y *= 1 / rho
        w[:] = wtilde[:]
        w *= 1 / xi
        z *= 1 / xi
        delta = dotprod(z, y)
        if np.abs(delta) < deltatol:
            return (x, -13)
        ytilde = M2.matvec(y)
        ztilde = M1.rmatvec(z)
        if iteration > 0:
            ytilde -= xi * delta / epsilon * p
            p[:] = ytilde[:]
            ztilde -= rho * (delta / epsilon).conj() * q
            q[:] = ztilde[:]
        else:
            p = ytilde.copy()
            q = ztilde.copy()
        ptilde = A.matvec(p)
        epsilon = dotprod(q, ptilde)
        if np.abs(epsilon) < epsilontol:
            return (x, -14)
        beta = epsilon / delta
        if np.abs(beta) < betatol:
            return (x, -11)
        vtilde[:] = ptilde[:]
        vtilde -= beta * v
        y = M1.matvec(vtilde)
        rho_prev = rho
        rho = np.linalg.norm(y)
        wtilde[:] = w[:]
        wtilde *= -beta.conj()
        wtilde += A.rmatvec(q)
        z = M2.rmatvec(wtilde)
        xi = np.linalg.norm(z)
        gamma_prev = gamma
        theta_prev = theta
        theta = rho / (gamma_prev * np.abs(beta))
        gamma = 1 / np.sqrt(1 + theta ** 2)
        if np.abs(gamma) < gammatol:
            return (x, -12)
        eta *= -(rho_prev / beta) * (gamma / gamma_prev) ** 2
        if iteration > 0:
            d *= (theta_prev * gamma) ** 2
            d += eta * p
            s *= (theta_prev * gamma) ** 2
            s += eta * ptilde
        else:
            d = p.copy()
            d *= eta
            s = ptilde.copy()
            s *= eta
        x += d
        r -= s
        if callback:
            callback(x)
    else:
        return (x, maxiter)

# --- helper: scipy.sparse.linalg._isolve.iterative._get_atol_rtol ---
def _get_atol_rtol(name, b_norm, atol=0.0, rtol=1e-05):
    if atol == 'legacy' or atol is None or atol < 0:
        msg = f"'scipy.sparse.linalg.{name}' called with invalid `atol`={atol}; if set, `atol` must be a real, non-negative number."
        raise ValueError(msg)
    atol = max(float(atol), float(rtol) * float(b_norm))
    return (atol, rtol)

def permute_dims(A, axes=None, copy=False):
    ndim = A.ndim
    if axes is None:
        axes = tuple(range(ndim)[::-1])
    elif len(axes) != ndim:
        raise ValueError(f'Incorrect number of axes: {ndim} instead of {A.ndim}')
    if not isinstance(axes, (tuple, list)):
        if not np.issubdtype(np.dtype(type(axes)), np.integer):
            raise TypeError(f'axis must be an integer/tuple of ints, not {type(axes)}')
        axes = (axes,)
    canon_axes = []
    for ax in axes:
        if not isintlike(ax):
            raise TypeError(f'axis must be an integer. (given {ax})')
        if ax < 0:
            ax += ndim
        if ax < 0 or ax >= ndim:
            raise ValueError('axis out of range for ndim')
        canon_axes.append(ax)
    if len(canon_axes) != len(set(canon_axes)):
        raise ValueError('duplicate value in axis')
    axes = canon_axes
    if axes == list(range(ndim)):
        return A if not copy else A.copy()
    A = A.tocoo(copy=copy)
    A._shape = tuple((A.shape[idx] for idx in axes))
    A.coords = tuple((A.coords[idx] for idx in axes))
    A.has_canonical_format = False
    return A

def safely_cast_index_arrays(A, idx_dtype=np.int32, msg=''):
    if not msg:
        msg = f'dtype {idx_dtype}'
    max_value = np.iinfo(idx_dtype).max
    if A.format in ('csc', 'csr'):
        if A.indptr[-1] > max_value:
            raise ValueError(f'indptr values too large for {msg}')
        if max(*A.shape) > max_value:
            if (A.indices > max_value).any():
                raise ValueError(f'indices values too large for {msg}')
        indices = A.indices.astype(idx_dtype, copy=False)
        indptr = A.indptr.astype(idx_dtype, copy=False)
        return (indices, indptr)
    elif A.format == 'coo':
        if max(*A.shape) > max_value:
            if any(((co > max_value).any() for co in A.coords)):
                raise ValueError(f'coords values too large for {msg}')
        return tuple((co.astype(idx_dtype, copy=False) for co in A.coords))
    elif A.format == 'dia':
        if max(*A.shape) > max_value:
            if (A.offsets > max_value).any():
                raise ValueError(f'offsets values too large for {msg}')
        offsets = A.offsets.astype(idx_dtype, copy=False)
        return offsets
    elif A.format == 'bsr':
        R, C = A.blocksize
        if A.indptr[-1] * R > max_value:
            raise ValueError('indptr values too large for {msg}')
        if max(*A.shape) > max_value:
            if (A.indices * C > max_value).any():
                raise ValueError(f'indices values too large for {msg}')
        indices = A.indices.astype(idx_dtype, copy=False)
        indptr = A.indptr.astype(idx_dtype, copy=False)
        return (indices, indptr)
    else:
        raise TypeError(f'Format {A.format} is not associated with index arrays. DOK and LIL have dict and list, not array.')

def swapaxes(A, axis1, axis2):
    axes = np.arange(A.ndim)
    try:
        axes[[axis1, axis2]] = axes[[axis2, axis1]]
    except IndexError as err:
        msg = str(err)
        msg = msg.removeprefix('index ').split(' axis ', 1)[0]
        raise ValueError(f'Invalid axis: {msg} ndim={A.ndim}')
    axes = tuple(axes)
    return permute_dims(A, axes=axes, copy=True)

