def splu(A, permc_spec=None, diag_pivot_thresh=None, relax=None, panel_size=None, options=None):
    if is_pydata_spmatrix(A):
        A_cls = type(A)

        def csc_construct_func(*a, cls=A_cls):
            return cls.from_scipy_sparse(csc_array(*a))
        A = A.to_scipy_sparse().tocsc()
    else:
        csc_construct_func = csc_array
    if not (issparse(A) and A.format == 'csc'):
        A = csc_array(A)
        warn('splu converted its input to CSC format', SparseEfficiencyWarning, stacklevel=2)
    A.sum_duplicates()
    A = A._asfptype()
    M, N = A.shape
    if M != N:
        raise ValueError('can only factor square matrices')
    indices, indptr = safely_cast_index_arrays(A, np.intc, 'SuperLU')
    _options = dict(DiagPivotThresh=diag_pivot_thresh, ColPerm=permc_spec, PanelSize=panel_size, Relax=relax)
    if options is not None:
        _options.update(options)
    if _options['ColPerm'] == 'NATURAL':
        _options['SymmetricMode'] = True
    return _superlu.gstrf(N, A.nnz, A.data, indices, indptr, csc_construct_func=csc_construct_func, ilu=False, options=_options)

def tfqmr(A, b, x0=None, *, rtol=1e-05, atol=0.0, maxiter=None, M=None, callback=None, show=False):
    dtype = A.dtype
    if np.issubdtype(dtype, np.int64):
        dtype = float
        A = A.astype(dtype)
    if np.issubdtype(b.dtype, np.int64):
        b = b.astype(dtype)
    A, M, x, b = make_system(A, M, x0, b)
    if np.linalg.norm(b) == 0.0:
        x = b.copy()
        return (x, 0)
    ndofs = A.shape[0]
    if maxiter is None:
        maxiter = min(10000, ndofs * 10)
    if x0 is None:
        r = b.copy()
    else:
        r = b - A.matvec(x)
    u = r
    w = r.copy()
    rstar = r
    v = M.matvec(A.matvec(r))
    uhat = v
    d = theta = eta = 0.0
    rho = np.inner(rstar.conjugate(), r).real
    rhoLast = rho
    r0norm = np.sqrt(rho)
    tau = r0norm
    if r0norm == 0:
        return (x, 0)
    atol, _ = _get_atol_rtol('tfqmr', r0norm, atol, rtol)
    for iter in range(maxiter):
        even = iter % 2 == 0
        if even:
            vtrstar = np.inner(rstar.conjugate(), v)
            if vtrstar == 0.0:
                return (x, -1)
            alpha = rho / vtrstar
            uNext = u - alpha * v
        w -= alpha * uhat
        d = u + theta ** 2 / alpha * eta * d
        theta = np.linalg.norm(w) / tau
        c = np.sqrt(1.0 / (1 + theta ** 2))
        tau *= theta * c
        eta = c ** 2 * alpha
        z = M.matvec(d)
        x += eta * z
        if callback is not None:
            callback(x)
        if tau * np.sqrt(iter + 1) < atol:
            if show:
                print(f'TFQMR: Linear solve converged due to reach TOL iterations {iter + 1}')
            return (x, 0)
        if not even:
            rho = np.inner(rstar.conjugate(), w)
            beta = rho / rhoLast
            u = w + beta * u
            v = beta * uhat + beta ** 2 * v
            uhat = M.matvec(A.matvec(u))
            v += uhat
        else:
            uhat = M.matvec(A.matvec(uNext))
            u = uNext
            rhoLast = rho
    if show:
        print(f'TFQMR: Linear solve not converged due to reach MAXIT iterations {iter + 1}')
    return (x, maxiter)

def distance_matrix(x, y, p=2.0, threshold=1000000):
    x = np.asarray(x)
    m, k = x.shape
    y = np.asarray(y)
    n, kk = y.shape
    if k != kk:
        raise ValueError(f'x contains {k}-dimensional vectors but y contains {kk}-dimensional vectors')
    if m * n * k <= threshold:
        return minkowski_distance(x[:, np.newaxis, :], y[np.newaxis, :, :], p)
    else:
        result = np.empty((m, n), dtype=float)
        if m < n:
            for i in range(m):
                result[i, :] = minkowski_distance(x[i], y, p)
        else:
            for j in range(n):
                result[:, j] = minkowski_distance(x, y[j], p)
        return result

# --- helper: scipy.spatial._kdtree.minkowski_distance ---
def minkowski_distance(x, y, p=2.0):
    x = np.asarray(x)
    y = np.asarray(y)
    if p == np.inf or p == 1:
        return minkowski_distance_p(x, y, p)
    else:
        return minkowski_distance_p(x, y, p) ** (1.0 / p)

def minkowski_distance(x, y, p=2.0):
    x = np.asarray(x)
    y = np.asarray(y)
    if p == np.inf or p == 1:
        return minkowski_distance_p(x, y, p)
    else:
        return minkowski_distance_p(x, y, p) ** (1.0 / p)

# --- helper: scipy.spatial._kdtree.minkowski_distance_p ---
def minkowski_distance_p(x, y, p=2.0):
    x = np.asarray(x)
    y = np.asarray(y)
    common_datatype = np.promote_types(np.promote_types(x.dtype, y.dtype), 'float64')
    x = x.astype(common_datatype)
    y = y.astype(common_datatype)
    if p == np.inf:
        return np.amax(np.abs(y - x), axis=-1)
    elif p == 1:
        return np.sum(np.abs(y - x), axis=-1)
    else:
        return np.sum(np.abs(y - x) ** p, axis=-1)

