# --- helper: scipy.stats._morestats._boxcox_llf ---
@_axis_nan_policy_factory(lambda x: x, n_outputs=1, default_axis=0, result_to_tuple=lambda x, _: (x,))
def _boxcox_llf(data, axis=0, *, lmb):
    xp = array_namespace(data)
    dtype = xp_result_type(lmb, data, force_floating=True, xp=xp)
    data = xp.asarray(data, dtype=dtype)
    N = data.shape[axis]
    if N == 0:
        return _get_nan(data, xp=xp)
    logdata = xp.log(data)
    if lmb == 0:
        logvar = xp.log(xp.var(logdata, axis=axis))
    else:
        logx = lmb * logdata
        logvar = _log_var(logx, xp, axis) - 2 * math.log(abs(lmb))
    res = (lmb - 1) * xp.sum(logdata, axis=axis) - N / 2 * logvar
    res = xp.astype(res, data.dtype, copy=False)
    res = res[()] if res.ndim == 0 else res
    return res

@xp_capabilities(np_only=True)
def boxcox_normmax(x, brack=None, method='pearsonr', optimizer=None, *, ymax=_BigFloat_singleton):
    x = np.asarray(x)
    if not np.all(np.isfinite(x) & (x >= 0)):
        message = 'The `x` argument of `boxcox_normmax` must contain only positive, finite, real numbers.'
        raise ValueError(message)
    end_msg = 'exceed specified `ymax`.'
    if ymax is _BigFloat_singleton:
        dtype = x.dtype if np.issubdtype(x.dtype, np.floating) else np.float64
        ymax = np.finfo(dtype).max / 10000
        end_msg = f'overflow in {dtype}.'
    elif ymax <= 0:
        raise ValueError('`ymax` must be strictly positive')
    if optimizer is None:
        if brack is None:
            brack = (-2.0, 2.0)

        def _optimizer(func, args):
            return optimize.brent(func, args=args, brack=brack)
    else:
        if not callable(optimizer):
            raise ValueError('`optimizer` must be a callable')
        if brack is not None:
            raise ValueError('`brack` must be None if `optimizer` is given')

        def _optimizer(func, args):

            def func_wrapped(x):
                return func(x, *args)
            return getattr(optimizer(func_wrapped), 'x', None)

    def _pearsonr(x):
        osm_uniform = _calc_uniform_order_statistic_medians(len(x))
        xvals = distributions.norm.ppf(osm_uniform)

        def _eval_pearsonr(lmbda, xvals, samps):
            y = boxcox(samps, lmbda)
            yvals = np.sort(y)
            r, prob = _stats_py.pearsonr(xvals, yvals)
            return 1 - r
        return _optimizer(_eval_pearsonr, args=(xvals, x))

    def _mle(x):

        def _eval_mle(lmb, data):
            return -boxcox_llf(lmb, data)
        return _optimizer(_eval_mle, args=(x,))

    def _all(x):
        maxlog = np.empty(2, dtype=float)
        maxlog[0] = _pearsonr(x)
        maxlog[1] = _mle(x)
        return maxlog
    methods = {'pearsonr': _pearsonr, 'mle': _mle, 'all': _all}
    if method not in methods.keys():
        raise ValueError(f'Method {method} not recognized.')
    optimfunc = methods[method]
    res = optimfunc(x)
    if res is None:
        message = 'The `optimizer` argument of `boxcox_normmax` must return an object containing the optimal `lmbda` in attribute `x`.'
        raise ValueError(message)
    elif not np.isinf(ymax):
        xmax, xmin = (np.max(x), np.min(x))
        if xmin >= 1:
            x_treme = xmax
        elif xmax <= 1:
            x_treme = xmin
        else:
            indicator = special.boxcox(xmax, res) > abs(special.boxcox(xmin, res))
            if isinstance(res, np.ndarray):
                indicator = indicator[1]
            x_treme = xmax if indicator else xmin
        mask = abs(special.boxcox(x_treme, res)) > ymax
        if np.any(mask):
            message = f'The optimal lambda is {res}, but the returned lambda is the constrained optimum to ensure that the maximum or the minimum of the transformed data does not ' + end_msg
            warnings.warn(message, stacklevel=2)
            constrained_res = _boxcox_inv_lmbda(x_treme, ymax * np.sign(x_treme - 1))
            if isinstance(res, np.ndarray):
                res[mask] = constrained_res
            else:
                res = constrained_res
    return res

# --- helper: scipy.stats._morestats._boxcox_inv_lmbda ---
def _boxcox_inv_lmbda(x, y):
    num = special.lambertw(-x ** (-1 / y) * np.log(x) / y, k=-1)
    return np.real(-num / np.log(x) - 1 / y)

# --- helper: scipy.stats._morestats._calc_uniform_order_statistic_medians ---
def _calc_uniform_order_statistic_medians(n):
    v = np.empty(n, dtype=np.float64)
    v[-1] = 0.5 ** (1.0 / n)
    v[0] = 1 - v[-1]
    i = np.arange(2, n)
    v[1:-1] = (i - 0.3175) / (n + 0.365)
    return v

# --- helper: scipy.stats._morestats.boxcox ---
@xp_capabilities(np_only=True)
def boxcox(x, lmbda=None, alpha=None, optimizer=None):
    x = np.asarray(x)
    if lmbda is not None:
        return special.boxcox(x, lmbda)
    if x.ndim != 1:
        raise ValueError('Data must be 1-dimensional.')
    if x.size == 0:
        return x
    if np.all(x == x[0]):
        raise ValueError('Data must not be constant.')
    if np.any(x <= 0):
        raise ValueError('Data must be positive.')
    lmax = boxcox_normmax(x, method='mle', optimizer=optimizer)
    y = boxcox(x, lmax)
    if alpha is None:
        return (y, lmax)
    else:
        interval = _boxcox_conf_interval(x, lmax, alpha)
        return (y, lmax, interval)

