def mode(a, axis=0, nan_policy='propagate', keepdims=False):
    xp = array_namespace(a)
    if not xp.isdtype(a.dtype, 'numeric'):
        message = 'Argument `a` is not recognized as numeric. Support for input that cannot be coerced to a numeric array was deprecated in SciPy 1.9.0 and removed in SciPy 1.11.0. Please consider `np.unique`.'
        raise TypeError(message)
