    def count_rank_tie(ranks):
        cnt = np.bincount(ranks).astype('int64', copy=False)
        cnt = cnt[cnt > 1]
        return (int((cnt * (cnt - 1) // 2).sum()), int((cnt * (cnt - 1.0) * (cnt - 2)).sum()), int((cnt * (cnt - 1.0) * (2 * cnt + 5)).sum()))
    size = x.size
    perm = np.argsort(y)
    x, y = (x[perm], y[perm])
    y = np.r_[True, y[1:] != y[:-1]].cumsum(dtype=np.intp)
    perm = np.argsort(x, kind='mergesort')
    x, y = (x[perm], y[perm])
    x = np.r_[True, x[1:] != x[:-1]].cumsum(dtype=np.intp)
    dis = _kendall_dis(x, y)
    obs = np.r_[True, (x[1:] != x[:-1]) | (y[1:] != y[:-1]), True]
    cnt = np.diff(np.nonzero(obs)[0]).astype('int64', copy=False)
    ntie = int((cnt * (cnt - 1) // 2).sum())
    xtie, x0, x1 = count_rank_tie(x)
    ytie, y0, y1 = count_rank_tie(y)
    tot = size * (size - 1) // 2
    if xtie == tot or ytie == tot:
        NaN = _get_nan(x, y)
        res = SignificanceResult(NaN, NaN)
        res.correlation = NaN
        return res
    con_minus_dis = tot - xtie - ytie + ntie - 2 * dis
    if variant == 'b':
        tau = con_minus_dis / np.sqrt(tot - xtie) / np.sqrt(tot - ytie)
    elif variant == 'c':
        minclasses = min(len(set(x)), len(set(y)))
        tau = 2 * con_minus_dis / (size ** 2 * (minclasses - 1) / minclasses)
    else:
        raise ValueError(f"Unknown variant of the method chosen: {variant}. variant must be 'b' or 'c'.")
    tau = np.minimum(1.0, max(-1.0, tau))
    if method == 'exact' and (xtie != 0 or ytie != 0):
        raise ValueError('Ties found, exact method cannot be used.')
    if method == 'auto':
        if (xtie == 0 and ytie == 0) and (size <= 33 or min(dis, tot - dis) <= 1):
            method = 'exact'
        else:
            method = 'asymptotic'
    if xtie == 0 and ytie == 0 and (method == 'exact'):
        pvalue = mstats_basic._kendall_p_exact(size, tot - dis, alternative)
    elif method == 'asymptotic':
        m = size * (size - 1.0)
        var = (m * (2 * size + 5) - x1 - y1) / 18 + 2 * xtie * ytie / m + x0 * y0 / (9 * m * (size - 2))
        z = con_minus_dis / np.sqrt(var)
        pvalue = _get_pvalue(z, _SimpleNormal(), alternative, xp=np)
    else:
        raise ValueError(f"Unknown method {method} specified.  Use 'auto', 'exact' or 'asymptotic'.")
    res = SignificanceResult(tau[()], pvalue[()])
    res.correlation = tau[()]
    return res

# --- helper: scipy.stats._stats_py._SimpleNormal ---
class _SimpleNormal:

    def cdf(self, x):
        return special.ndtr(x)

    def sf(self, x):
        return special.ndtr(-x)

    def isf(self, x):
        return -special.ndtri(x)

# --- helper: scipy.stats._stats_py._get_pvalue ---
def _get_pvalue(statistic, distribution, alternative, symmetric=True, xp=None):
    xp = array_namespace(statistic) if xp is None else xp
    if alternative == 'less':
        pvalue = distribution.cdf(statistic)
    elif alternative == 'greater':
        pvalue = distribution.sf(statistic)
    elif alternative == 'two-sided':
        pvalue = 2 * (distribution.sf(xp.abs(statistic)) if symmetric else xp.minimum(distribution.cdf(statistic), distribution.sf(statistic)))
    else:
        message = "`alternative` must be 'less', 'greater', or 'two-sided'."
        raise ValueError(message)
    return pvalue

# --- helper: scipy.stats._stats_py._pack_CorrelationResult ---
def _pack_CorrelationResult(statistic, pvalue, correlation):
    res = SignificanceResult(statistic, pvalue)
    res.correlation = correlation
    return res

# --- helper: scipy.stats._stats_py._unpack_CorrelationResult ---
def _unpack_CorrelationResult(res, _):
    return (res.statistic, res.pvalue, res.correlation)

