@_rename_parameter('mode', 'method')
def ks_2samp(data1, data2, alternative='two-sided', method='auto'):
    mode = method
    if mode not in ['auto', 'exact', 'asymp']:
        raise ValueError(f'Invalid value for mode: {mode}')
    alternative = {'t': 'two-sided', 'g': 'greater', 'l': 'less'}.get(alternative.lower()[0], alternative)
    if alternative not in ['two-sided', 'less', 'greater']:
        raise ValueError(f'Invalid value for alternative: {alternative}')
    MAX_AUTO_N = 10000
    if np.ma.is_masked(data1):
        data1 = data1.compressed()
    if np.ma.is_masked(data2):
        data2 = data2.compressed()
    data1 = np.sort(data1)
    data2 = np.sort(data2)
    n1 = data1.shape[0]
    n2 = data2.shape[0]
    if min(n1, n2) == 0:
        raise ValueError('Data passed to ks_2samp must not be empty')
    data_all = np.concatenate([data1, data2])
    cdf1 = np.searchsorted(data1, data_all, side='right') / n1
    cdf2 = np.searchsorted(data2, data_all, side='right') / n2
    cddiffs = cdf1 - cdf2
    argminS = np.argmin(cddiffs)
    argmaxS = np.argmax(cddiffs)
    loc_minS = data_all[argminS]
    loc_maxS = data_all[argmaxS]
    minS = np.clip(-cddiffs[argminS], 0, 1)
    maxS = cddiffs[argmaxS]
    if alternative == 'less' or (alternative == 'two-sided' and minS > maxS):
        d = minS
        d_location = loc_minS
        d_sign = -1
    else:
        d = maxS
        d_location = loc_maxS
        d_sign = 1
    g = math.gcd(n1, n2)
    n1g = n1 // g
    n2g = n2 // g
    prob = -np.inf
    if mode == 'auto':
        mode = 'exact' if max(n1, n2) <= MAX_AUTO_N else 'asymp'
    elif mode == 'exact':
        if n1g >= np.iinfo(np.int32).max / n2g:
            mode = 'asymp'
            warnings.warn(f"Exact ks_2samp calculation not possible with samples sizes {n1} and {n2}. Switching to 'asymp'.", RuntimeWarning, stacklevel=3)
    if mode == 'exact':
        success, d, prob = _attempt_exact_2kssamp(n1, n2, g, d, alternative)
        if not success:
            mode = 'asymp'
            warnings.warn(f'ks_2samp: Exact calculation unsuccessful. Switching to method={mode}.', RuntimeWarning, stacklevel=3)
    if mode == 'asymp':
        m, n = sorted([float(n1), float(n2)], reverse=True)
        en = m * n / (m + n)
        if alternative == 'two-sided':
            prob = distributions.kstwo.sf(d, np.round(en))
        else:
            z = np.sqrt(en) * d
            expt = -2 * z ** 2 - 2 * z * (m + 2 * n) / np.sqrt(m * n * (m + n)) / 3.0
            prob = np.exp(expt)
    prob = np.clip(prob, 0, 1)
    return KstestResult(np.float64(d), prob, statistic_location=d_location, statistic_sign=np.int8(d_sign))

# --- helper: scipy.stats._stats_py._KstestResult_to_tuple ---
def _KstestResult_to_tuple(res, _):
    return (*res, res.statistic_location, res.statistic_sign)

# --- helper: scipy.stats._stats_py._attempt_exact_2kssamp ---
def _attempt_exact_2kssamp(n1, n2, g, d, alternative):
    lcm = n1 // g * n2
    h = int(np.round(d * lcm))
    d = h * 1.0 / lcm
    if h == 0:
        return (True, d, 1.0)
    saw_fp_error, prob = (False, np.nan)
    try:
        with np.errstate(invalid='raise', over='raise'):
            if alternative == 'two-sided':
                if n1 == n2:
                    prob = _compute_prob_outside_square(n1, h)
                else:
                    prob = _compute_outer_prob_inside_method(n1, n2, g, h)
            elif n1 == n2:
                jrange = np.arange(h)
                prob = np.prod((n1 - jrange) / (n1 + jrange + 1.0))
            else:
                with np.errstate(over='raise'):
                    num_paths = _count_paths_outside_method(n1, n2, g, h)
                bin = special.binom(n1 + n2, n1)
                if num_paths > bin or np.isinf(bin):
                    saw_fp_error = True
                else:
                    prob = num_paths / bin
    except (FloatingPointError, OverflowError):
        saw_fp_error = True
    if saw_fp_error:
        return (False, d, np.nan)
    if not 0 <= prob <= 1:
        return (False, d, prob)
    return (True, d, prob)

