    k = xp.arange(n_moments, dtype=sample.dtype)
    prk = _prk(xpx.expand_dims(k, axis=tuple(range(1, sample.ndim + 1))), k)
    bk = _br(sample, r=k, xp=xp)
    n = sample.shape[-1]
    if n < bk.shape[-1]:
