    x = xp.expand_dims(x, axis=-2)
    x = xp.broadcast_to(x, x.shape[:-2] + (r.shape[0], n))
    x = xp.triu(x)
    j = xp.arange(n, dtype=x.dtype)
    n = xp.asarray(n, dtype=x.dtype)[()]
    return xp.vecdot(special.binom(j, r[:, xp.newaxis]), x, axis=-1) / special.binom(n - 1, r) / n

