    message = '`standardize` must be True or False.'
    if not np.issubdtype(standardize.dtype, np.bool_) or standardize.ndim != 0:
        raise ValueError(message)
    standardize = bool(standardize)
    sample = xp.moveaxis(sample, axis, -1)
