def hdquantiles_sd(data, prob=(0.25, 0.5, 0.75), axis=None):

    def _hdsd_1D(data, prob):
        xsorted = np.sort(data.compressed())
        n = len(xsorted)
        hdsd = np.empty(len(prob), float64)
        if n < 2:
            hdsd.flat = np.nan
        vv = np.arange(n) / float(n - 1)
        betacdf = beta.cdf
        for i, p in enumerate(prob):
            _w = betacdf(vv, n * p, n * (1 - p))
            w = _w[1:] - _w[:-1]
            mx_ = np.zeros_like(xsorted)
            mx_[1:] = np.cumsum(w * xsorted[:-1])
            mx_[:-1] += np.cumsum(w[::-1] * xsorted[:0:-1])[::-1]
            hdsd[i] = np.sqrt(mx_.var() * (n - 1))
        return hdsd
    data = ma.array(data, copy=False, dtype=float64)
    p = np.atleast_1d(np.asarray(prob))
    if axis is None:
        result = _hdsd_1D(data, p)
    else:
        if data.ndim > 2:
            raise ValueError(f"Array 'data' must be at most two dimensional, but got data.ndim = {data.ndim}")
        result = ma.apply_along_axis(_hdsd_1D, axis, data, p)
    return ma.fix_invalid(result, copy=False).ravel()

def mjci(data, prob=(0.25, 0.5, 0.75), axis=None):

    def _mjci_1D(data, p):
        data = np.sort(data.compressed())
        n = data.size
        prob = (np.array(p) * n + 0.5).astype(int)
        betacdf = beta.cdf
        mj = np.empty(len(prob), float64)
        x = np.arange(1, n + 1, dtype=float64) / n
        y = x - 1.0 / n
        for i, m in enumerate(prob):
            W = betacdf(x, m - 1, n - m) - betacdf(y, m - 1, n - m)
            C1 = np.dot(W, data)
            C2 = np.dot(W, data ** 2)
            mj[i] = np.sqrt(C2 - C1 ** 2)
        return mj
    data = ma.array(data, copy=False)
    if data.ndim > 2:
        raise ValueError(f"Array 'data' must be at most two dimensional, but got data.ndim = {data.ndim}")
    p = np.atleast_1d(np.asarray(prob))
    if axis is None:
        return _mjci_1D(data, p)
    else:
        return ma.apply_along_axis(_mjci_1D, axis, data, p)

