@xp_capabilities(np_only=True)
@_axis_nan_policy_factory(_pack_CorrelationResult, default_axis=None, n_samples=_weightedtau_n_samples, result_to_tuple=_unpack_CorrelationResult, paired=True, too_small=1, n_outputs=3, override={'nan_propagation': False})
def weightedtau(x, y, rank=True, weigher=None, additive=True):
    x = np.asarray(x).ravel()
    y = np.asarray(y).ravel()
    NaN = _get_nan(x, y)
    if x.size != y.size:
        raise ValueError('Array shapes are incompatible for broadcasting.')
    if not x.size:
        res = SignificanceResult(NaN, NaN)
        res.correlation = NaN
        return res
    if np.isnan(np.sum(x)):
        x = _toint64(x)
    if np.isnan(np.sum(y)):
        y = _toint64(y)
    if x.dtype != y.dtype:
        if x.dtype != np.int64:
            x = _toint64(x)
        if y.dtype != np.int64:
            y = _toint64(y)
    elif x.dtype not in (np.int32, np.int64, np.float32, np.float64):
        x = _toint64(x)
        y = _toint64(y)
    if rank is True:
        tau = np.asarray(_weightedrankedtau(x, y, None, weigher, additive) + _weightedrankedtau(y, x, None, weigher, additive))[()] / 2
        res = SignificanceResult(tau, NaN)
        res.correlation = tau
        return res
    if rank is False:
        rank = np.arange(x.size, dtype=np.intp)
    elif rank is not None:
        rank = np.asarray(rank).ravel()
        rank = _toint64(rank).astype(np.intp)
        if rank.size != x.size:
            raise ValueError(f'All inputs to `weightedtau` must be of the same size, found x-size {x.size} and rank-size {rank.size}')
    tau = np.asarray(_weightedrankedtau(x, y, rank, weigher, additive))[()]
    res = SignificanceResult(tau, NaN)
    res.correlation = tau
    return res

# --- helper: scipy.stats._stats_py._pack_CorrelationResult ---
def _pack_CorrelationResult(statistic, pvalue, correlation):
    res = SignificanceResult(statistic, pvalue)
    res.correlation = correlation
    return res

# --- helper: scipy.stats._stats_py._unpack_CorrelationResult ---
def _unpack_CorrelationResult(res, _):
    return (res.statistic, res.pvalue, res.correlation)

# --- helper: scipy.stats._stats_py._weightedtau_n_samples ---
def _weightedtau_n_samples(kwargs):
    rank = kwargs.get('rank', False)
    return 2 if isinstance(rank, bool) or rank is None else 3

@xp_capabilities(np_only=True)
def wasserstein_distance_nd(u_values, v_values, u_weights=None, v_weights=None):
    m, n = (len(u_values), len(v_values))
    u_values = asarray(u_values)
    v_values = asarray(v_values)
    if u_values.ndim > 2 or v_values.ndim > 2:
        raise ValueError('Invalid input values. The inputs must have either one or two dimensions.')
    if u_values.ndim != v_values.ndim:
        raise ValueError('Invalid input values. Dimensions of inputs must be equal.')
    if u_values.ndim == 1 and v_values.ndim == 1:
        return _cdf_distance(1, u_values, v_values, u_weights, v_weights)
    u_values, u_weights = _validate_distribution(u_values, u_weights)
    v_values, v_weights = _validate_distribution(v_values, v_weights)
    if u_values.shape[1] != v_values.shape[1]:
        raise ValueError('Invalid input values. If two-dimensional, `u_values` and `v_values` must have the same number of columns.')
    if np.any(np.isinf(u_values)) ^ np.any(np.isinf(v_values)):
        return np.inf
    elif np.any(np.isinf(u_values)) and np.any(np.isinf(v_values)):
        return np.nan
    A_upper_part = sparse.block_diag((np.ones((1, n)),) * m)
    A_lower_part = sparse.hstack((sparse.eye(n),) * m)
    A = sparse.vstack((A_upper_part, A_lower_part))
    A = sparse.coo_array(A)
    D = distance_matrix(u_values, v_values, p=2)
    cost = D.ravel()
    p_u = np.full(m, 1 / m) if u_weights is None else u_weights / np.sum(u_weights)
    p_v = np.full(n, 1 / n) if v_weights is None else v_weights / np.sum(v_weights)
    b = np.concatenate((p_u, p_v), axis=0)
    constraints = LinearConstraint(A=A.T, ub=cost)
    opt_res = milp(c=-b, constraints=constraints, bounds=(-np.inf, np.inf))
    return -opt_res.fun

# --- helper: scipy.stats._stats_py._cdf_distance ---
def _cdf_distance(p, u_values, v_values, u_weights=None, v_weights=None):
    u_values, u_weights = _validate_distribution(u_values, u_weights)
    v_values, v_weights = _validate_distribution(v_values, v_weights)
    u_sorter = np.argsort(u_values)
    v_sorter = np.argsort(v_values)
    all_values = np.concatenate((u_values, v_values))
    all_values.sort(kind='mergesort')
    deltas = np.diff(all_values)
    u_cdf_indices = u_values[u_sorter].searchsorted(all_values[:-1], 'right')
    v_cdf_indices = v_values[v_sorter].searchsorted(all_values[:-1], 'right')
    if u_weights is None:
        u_cdf = u_cdf_indices / u_values.size
    else:
        u_sorted_cumweights = np.concatenate(([0], np.cumsum(u_weights[u_sorter])))
        u_cdf = u_sorted_cumweights[u_cdf_indices] / u_sorted_cumweights[-1]
    if v_weights is None:
        v_cdf = v_cdf_indices / v_values.size
    else:
        v_sorted_cumweights = np.concatenate(([0], np.cumsum(v_weights[v_sorter])))
        v_cdf = v_sorted_cumweights[v_cdf_indices] / v_sorted_cumweights[-1]
    if p == 1:
        return np_vecdot(np.abs(u_cdf - v_cdf), deltas)
    if p == 2:
        return np.sqrt(np_vecdot(np.square(u_cdf - v_cdf), deltas))
    return np.power(np_vecdot(np.power(np.abs(u_cdf - v_cdf), p), deltas), 1 / p)

# --- helper: scipy.stats._stats_py._validate_distribution ---
def _validate_distribution(values, weights):
    values = np.asarray(values, dtype=float)
    if len(values) == 0:
        raise ValueError("Distribution can't be empty.")
    if weights is not None:
        weights = np.asarray(weights, dtype=float)
        if len(weights) != len(values):
            raise ValueError('Value and weight array-likes for the same empirical distribution must be of the same size.')
        if np.any(weights < 0):
            raise ValueError('All weights must be non-negative.')
        if not 0 < np.sum(weights) < np.inf:
            raise ValueError('Weight array-like sum must be positive and finite. Set as None for an equal distribution of weight.')
        return (values, weights)
    return (values, None)

