def yeojohnson_llf(lmb, data, *, axis=0, nan_policy='propagate', keepdims=False):
    kwargs = {}
    if keepdims is not False:
        kwargs['keepdims'] = keepdims
    if nan_policy != 'propagate':
        kwargs['nan_policy'] = nan_policy
