def apply_group_offloading(module: torch.nn.Module, onload_device: str | torch.device, offload_device: str | torch.device=torch.device('cpu'), offload_type: str | GroupOffloadingType='block_level', num_blocks_per_group: int | None=None, non_blocking: bool=False, use_stream: bool=False, record_stream: bool=False, low_cpu_mem_usage: bool=False, offload_to_disk_path: str | None=None, block_modules: list[str] | None=None, exclude_kwargs: list[str] | None=None) -> None:
    onload_device = torch.device(onload_device) if isinstance(onload_device, str) else onload_device
    offload_device = torch.device(offload_device) if isinstance(offload_device, str) else offload_device
    offload_type = GroupOffloadingType(offload_type)
    stream = None
    if use_stream:
        if torch.cuda.is_available():
            stream = torch.cuda.Stream()
        elif hasattr(torch, 'xpu') and torch.xpu.is_available():
            stream = torch.Stream()
        else:
            raise ValueError('Using streams for data transfer requires a CUDA device, or an Intel XPU device.')
    if not use_stream and record_stream:
        raise ValueError('`record_stream` cannot be True when `use_stream=False`.')
    if offload_type == GroupOffloadingType.BLOCK_LEVEL and num_blocks_per_group is None:
        raise ValueError("`num_blocks_per_group` must be provided when using `offload_type='block_level'.")
    _raise_error_if_accelerate_model_or_sequential_hook_present(module)
    if block_modules is None:
        block_modules = getattr(module, '_group_offload_block_modules', None)
    if exclude_kwargs is None:
        exclude_kwargs = getattr(module, '_skip_keys', None)
    config = GroupOffloadingConfig(onload_device=onload_device, offload_device=offload_device, offload_type=offload_type, num_blocks_per_group=num_blocks_per_group, non_blocking=non_blocking, stream=stream, record_stream=record_stream, low_cpu_mem_usage=low_cpu_mem_usage, offload_to_disk_path=offload_to_disk_path, block_modules=block_modules, exclude_kwargs=exclude_kwargs)
    _apply_group_offloading(module, config)

