from diffusers.hooks.context_parallel import lru_cache_unless_export

# Example 1: use default parameters (maxsize=128, typed=False)
# Decorate a simple function that computes Fibonacci numbers (recursive) to benefit from LRU caching.
@lru_cache_unless_export()
def fib(n: int) -> int:
    if n < 2:
        return n
    return fib(n - 1) + fib(n - 2)

# Call the decorated function
print('fib(10) =', fib(10))
# The decorated object wraps the original function; the original function is available at __wrapped__
print('underlying function name =', fib.__wrapped__.__name__)

