class AutoencoderOobleck(ModelMixin, AutoencoderMixin, ConfigMixin):
    _supports_gradient_checkpointing = False
    _supports_group_offloading = False

    @register_to_config
    def __init__(self, encoder_hidden_size=128, downsampling_ratios=[2, 4, 4, 8, 8], channel_multiples=[1, 2, 4, 8, 16], decoder_channels=128, decoder_input_channels=64, audio_channels=2, sampling_rate=44100):
        super().__init__()
        self.encoder_hidden_size = encoder_hidden_size
        self.downsampling_ratios = downsampling_ratios
        self.decoder_channels = decoder_channels
        self.upsampling_ratios = downsampling_ratios[::-1]
        self.hop_length = int(np.prod(downsampling_ratios))
        self.sampling_rate = sampling_rate
        self.encoder = OobleckEncoder(encoder_hidden_size=encoder_hidden_size, audio_channels=audio_channels, downsampling_ratios=downsampling_ratios, channel_multiples=channel_multiples)
        self.decoder = OobleckDecoder(channels=decoder_channels, input_channels=decoder_input_channels, audio_channels=audio_channels, upsampling_ratios=self.upsampling_ratios, channel_multiples=channel_multiples)
        self.use_slicing = False
        self.use_tiling = False
        self.tile_sample_min_length = sampling_rate * 30
        self.tile_sample_overlap = sampling_rate * 2
        self.tile_latent_min_length = 512
        self.tile_latent_overlap = 64

    def _encode(self, x: torch.Tensor) -> torch.Tensor:
        if self.use_tiling and x.shape[-1] > self.tile_sample_min_length:
            return self._tiled_encode(x)
        return self.encoder(x)

    @apply_forward_hook
    def encode(self, x: torch.Tensor, return_dict: bool=True) -> AutoencoderOobleckOutput | tuple[OobleckDiagonalGaussianDistribution]:
        if self.use_slicing and x.shape[0] > 1:
            encoded_slices = [self._encode(x_slice) for x_slice in x.split(1)]
            h = torch.cat(encoded_slices)
        else:
            h = self._encode(x)
        posterior = OobleckDiagonalGaussianDistribution(h)
        if not return_dict:
            return (posterior,)
        return AutoencoderOobleckOutput(latent_dist=posterior)

    def _tiled_encode(self, x: torch.Tensor) -> torch.Tensor:
        _B, _C, S = x.shape
        chunk = self.tile_sample_min_length
        overlap = self.tile_sample_overlap
        stride = chunk - 2 * overlap
        if stride <= 0:
            raise ValueError(f'tile_sample_min_length ({chunk}) must be greater than 2 * tile_sample_overlap ({overlap})')
        num_steps = math.ceil(S / stride)
        tiles = []
        hop = None
        for i in range(num_steps):
            core_start = i * stride
            core_end = min(core_start + stride, S)
            win_start = max(0, core_start - overlap)
            win_end = min(S, core_end + overlap)
            tile = self.encoder(x[:, :, win_start:win_end])
            if hop is None:
                hop = (win_end - win_start) / tile.shape[-1]
            trim_l = int(round((core_start - win_start) / hop))
            trim_r = int(round((win_end - core_end) / hop))
            end_idx = tile.shape[-1] - trim_r if trim_r > 0 else tile.shape[-1]
            tiles.append(tile[:, :, trim_l:end_idx])
        return torch.cat(tiles, dim=-1)

    def _decode(self, z: torch.Tensor, return_dict: bool=True) -> OobleckDecoderOutput | torch.Tensor:
        if self.use_tiling and z.shape[-1] > self.tile_latent_min_length:
            dec = self._tiled_decode(z)
        else:
            dec = self.decoder(z)
        if not return_dict:
            return (dec,)
        return OobleckDecoderOutput(sample=dec)

    def _tiled_decode(self, z: torch.Tensor) -> torch.Tensor:
        _B, _C, T = z.shape
        chunk = self.tile_latent_min_length
        overlap = self.tile_latent_overlap
        stride = chunk - 2 * overlap
        if stride <= 0:
            raise ValueError(f'tile_latent_min_length ({chunk}) must be greater than 2 * tile_latent_overlap ({overlap})')
        num_steps = math.ceil(T / stride)
        tiles = []
        upsample = None
        for i in range(num_steps):
            core_start = i * stride
            core_end = min(core_start + stride, T)
            win_start = max(0, core_start - overlap)
            win_end = min(T, core_end + overlap)
            tile = self.decoder(z[:, :, win_start:win_end])
            if upsample is None:
                upsample = tile.shape[-1] / (win_end - win_start)
            trim_l = int(round((core_start - win_start) * upsample))
            trim_r = int(round((win_end - core_end) * upsample))
            end_idx = tile.shape[-1] - trim_r if trim_r > 0 else tile.shape[-1]
            tiles.append(tile[:, :, trim_l:end_idx])
        return torch.cat(tiles, dim=-1)

    @apply_forward_hook
    def decode(self, z: torch.FloatTensor, return_dict: bool=True, generator=None) -> OobleckDecoderOutput | torch.FloatTensor:
        if self.use_slicing and z.shape[0] > 1:
            decoded_slices = [self._decode(z_slice).sample for z_slice in z.split(1)]
            decoded = torch.cat(decoded_slices)
        else:
            decoded = self._decode(z).sample
        if not return_dict:
            return (decoded,)
        return OobleckDecoderOutput(sample=decoded)

    def forward(self, sample: torch.Tensor, sample_posterior: bool=False, return_dict: bool=True, generator: torch.Generator | None=None) -> OobleckDecoderOutput | torch.Tensor:
        x = sample
        posterior = self.encode(x).latent_dist
        if sample_posterior:
            z = posterior.sample(generator=generator)
        else:
            z = posterior.mode()
        dec = self.decode(z).sample
        if not return_dict:
            return (dec,)
        return OobleckDecoderOutput(sample=dec)

