class AutoencoderTiny(ModelMixin, AutoencoderMixin, ConfigMixin):
    _supports_gradient_checkpointing = True

    @register_to_config
    def __init__(self, in_channels: int=3, out_channels: int=3, encoder_block_out_channels: tuple[int, ...]=(64, 64, 64, 64), decoder_block_out_channels: tuple[int, ...]=(64, 64, 64, 64), act_fn: str='relu', upsample_fn: str='nearest', latent_channels: int=4, upsampling_scaling_factor: int=2, num_encoder_blocks: tuple[int, ...]=(1, 3, 3, 3), num_decoder_blocks: tuple[int, ...]=(3, 3, 3, 1), latent_magnitude: int=3, latent_shift: float=0.5, force_upcast: bool=False, scaling_factor: float=1.0, shift_factor: float=0.0):
        super().__init__()
        if len(encoder_block_out_channels) != len(num_encoder_blocks):
            raise ValueError('`encoder_block_out_channels` should have the same length as `num_encoder_blocks`.')
        if len(decoder_block_out_channels) != len(num_decoder_blocks):
            raise ValueError('`decoder_block_out_channels` should have the same length as `num_decoder_blocks`.')
        self.encoder = EncoderTiny(in_channels=in_channels, out_channels=latent_channels, num_blocks=num_encoder_blocks, block_out_channels=encoder_block_out_channels, act_fn=act_fn)
        self.decoder = DecoderTiny(in_channels=latent_channels, out_channels=out_channels, num_blocks=num_decoder_blocks, block_out_channels=decoder_block_out_channels, upsampling_scaling_factor=upsampling_scaling_factor, act_fn=act_fn, upsample_fn=upsample_fn)
        self.latent_magnitude = latent_magnitude
        self.latent_shift = latent_shift
        self.scaling_factor = scaling_factor
        self.use_slicing = False
        self.use_tiling = False
        self.spatial_scale_factor = 2 ** out_channels
        self.tile_overlap_factor = 0.125
        self.tile_sample_min_size = 512
        self.tile_latent_min_size = self.tile_sample_min_size // self.spatial_scale_factor
        self.register_to_config(block_out_channels=decoder_block_out_channels)
        self.register_to_config(force_upcast=False)

    def scale_latents(self, x: torch.Tensor) -> torch.Tensor:
        return x.div(2 * self.latent_magnitude).add(self.latent_shift).clamp(0, 1)

    def unscale_latents(self, x: torch.Tensor) -> torch.Tensor:
        return x.sub(self.latent_shift).mul(2 * self.latent_magnitude)

    def _tiled_encode(self, x: torch.Tensor) -> torch.Tensor:
        sf = self.spatial_scale_factor
        tile_size = self.tile_sample_min_size
        blend_size = int(tile_size * self.tile_overlap_factor)
        traverse_size = tile_size - blend_size
        ti = range(0, x.shape[-2], traverse_size)
        tj = range(0, x.shape[-1], traverse_size)
        blend_masks = torch.stack(torch.meshgrid([torch.arange(tile_size / sf) / (blend_size / sf - 1)] * 2, indexing='ij'))
        blend_masks = blend_masks.clamp(0, 1).to(x.device)
        out = torch.zeros(x.shape[0], 4, x.shape[-2] // sf, x.shape[-1] // sf, device=x.device)
        for i in ti:
            for j in tj:
                tile_in = x[..., i:i + tile_size, j:j + tile_size]
                tile_out = out[..., i // sf:(i + tile_size) // sf, j // sf:(j + tile_size) // sf]
                tile = self.encoder(tile_in)
                h, w = (tile.shape[-2], tile.shape[-1])
                blend_mask_i = torch.ones_like(blend_masks[0]) if i == 0 else blend_masks[0]
                blend_mask_j = torch.ones_like(blend_masks[1]) if j == 0 else blend_masks[1]
                blend_mask = blend_mask_i * blend_mask_j
                tile, blend_mask = (tile[..., :h, :w], blend_mask[..., :h, :w])
                tile_out.copy_(blend_mask * tile + (1 - blend_mask) * tile_out)
        return out

    def _tiled_decode(self, x: torch.Tensor) -> torch.Tensor:
        sf = self.spatial_scale_factor
        tile_size = self.tile_latent_min_size
        blend_size = int(tile_size * self.tile_overlap_factor)
        traverse_size = tile_size - blend_size
        ti = range(0, x.shape[-2], traverse_size)
        tj = range(0, x.shape[-1], traverse_size)
        blend_masks = torch.stack(torch.meshgrid([torch.arange(tile_size * sf) / (blend_size * sf - 1)] * 2, indexing='ij'))
        blend_masks = blend_masks.clamp(0, 1).to(x.device)
        out = torch.zeros(x.shape[0], 3, x.shape[-2] * sf, x.shape[-1] * sf, device=x.device)
        for i in ti:
            for j in tj:
                tile_in = x[..., i:i + tile_size, j:j + tile_size]
                tile_out = out[..., i * sf:(i + tile_size) * sf, j * sf:(j + tile_size) * sf]
                tile = self.decoder(tile_in)
                h, w = (tile.shape[-2], tile.shape[-1])
                blend_mask_i = torch.ones_like(blend_masks[0]) if i == 0 else blend_masks[0]
                blend_mask_j = torch.ones_like(blend_masks[1]) if j == 0 else blend_masks[1]
                blend_mask = (blend_mask_i * blend_mask_j)[..., :h, :w]
                tile_out.copy_(blend_mask * tile + (1 - blend_mask) * tile_out)
        return out

    @apply_forward_hook
    def encode(self, x: torch.Tensor, return_dict: bool=True) -> AutoencoderTinyOutput | tuple[torch.Tensor]:
        if self.use_slicing and x.shape[0] > 1:
            output = [self._tiled_encode(x_slice) if self.use_tiling else self.encoder(x_slice) for x_slice in x.split(1)]
            output = torch.cat(output)
        else:
            output = self._tiled_encode(x) if self.use_tiling else self.encoder(x)
        if not return_dict:
            return (output,)
        return AutoencoderTinyOutput(latents=output)

    @apply_forward_hook
    def decode(self, x: torch.Tensor, generator: torch.Generator | None=None, return_dict: bool=True) -> DecoderOutput | tuple[torch.Tensor]:
        if self.use_slicing and x.shape[0] > 1:
            output = [self._tiled_decode(x_slice) if self.use_tiling else self.decoder(x_slice) for x_slice in x.split(1)]
            output = torch.cat(output)
        else:
            output = self._tiled_decode(x) if self.use_tiling else self.decoder(x)
        if not return_dict:
            return (output,)
        return DecoderOutput(sample=output)

    def forward(self, sample: torch.Tensor, return_dict: bool=True) -> DecoderOutput | tuple[torch.Tensor]:
        enc = self.encode(sample).latents
        scaled_enc = self.scale_latents(enc).mul_(255).round_().byte()
        unscaled_enc = self.unscale_latents(scaled_enc / 255.0)
        dec = self.decode(unscaled_enc).sample
        if not return_dict:
            return (dec,)
        return DecoderOutput(sample=dec)

