def get_1d_sincos_pos_embed_from_grid(embed_dim, pos, output_type='np', flip_sin_to_cos=False, dtype=None):
    if output_type == 'np':
        deprecation_message = "`get_1d_sincos_pos_embed_from_grid` uses `torch` and supports `device`. `from_numpy` is no longer required.  Pass `output_type='pt' to use the new version now."
        deprecate("output_type=='np'", '0.34.0', deprecation_message, standard_warn=False)
        return get_1d_sincos_pos_embed_from_grid_np(embed_dim=embed_dim, pos=pos)
    if embed_dim % 2 != 0:
        raise ValueError('embed_dim must be divisible by 2')
    if dtype is None:
        dtype = torch.float32 if pos.device.type == 'mps' else torch.float64
    omega = torch.arange(embed_dim // 2, device=pos.device, dtype=dtype)
    omega /= embed_dim / 2.0
    omega = 1.0 / 10000 ** omega
    pos = pos.reshape(-1)
    out = torch.outer(pos, omega)
    emb_sin = torch.sin(out)
    emb_cos = torch.cos(out)
    emb = torch.concat([emb_sin, emb_cos], dim=1)
    if flip_sin_to_cos:
        emb = torch.cat([emb[:, embed_dim // 2:], emb[:, :embed_dim // 2]], dim=1)
    return emb

# --- helper: diffusers.models.embeddings.get_2d_sincos_pos_embed_from_grid_np ---
def get_2d_sincos_pos_embed_from_grid_np(embed_dim, grid):
    if embed_dim % 2 != 0:
        raise ValueError('embed_dim must be divisible by 2')
    emb_h = get_1d_sincos_pos_embed_from_grid_np(embed_dim // 2, grid[0])
    emb_w = get_1d_sincos_pos_embed_from_grid_np(embed_dim // 2, grid[1])
    emb = np.concatenate([emb_h, emb_w], axis=1)
    return emb

class AdaLayerNorm(nn.Module):

    def __init__(self, embedding_dim: int, num_embeddings: int | None=None, output_dim: int | None=None, norm_elementwise_affine: bool=False, norm_eps: float=1e-05, chunk_dim: int=0):
        super().__init__()
        self.chunk_dim = chunk_dim
        output_dim = output_dim or embedding_dim * 2
        if num_embeddings is not None:
            self.emb = nn.Embedding(num_embeddings, embedding_dim)
        else:
            self.emb = None
        self.silu = nn.SiLU()
        self.linear = nn.Linear(embedding_dim, output_dim)
        self.norm = nn.LayerNorm(output_dim // 2, norm_eps, norm_elementwise_affine)

    def forward(self, x: torch.Tensor, timestep: torch.Tensor | None=None, temb: torch.Tensor | None=None) -> torch.Tensor:
        if self.emb is not None:
            temb = self.emb(timestep)
        temb = self.linear(self.silu(temb))
        if self.chunk_dim == 1:
            shift, scale = temb.chunk(2, dim=1)
            shift = shift[:, None, :]
            scale = scale[:, None, :]
        else:
            scale, shift = temb.chunk(2, dim=0)
        x = self.norm(x) * (1 + scale) + shift
        return x

class RMSNorm(nn.Module):

    def __init__(self, dim, eps: float, elementwise_affine: bool=True, bias: bool=False):
        super().__init__()
        self.eps = eps
        self.elementwise_affine = elementwise_affine
        if isinstance(dim, numbers.Integral):
            dim = (dim,)
        self.dim = torch.Size(dim)
        self.weight = None
        self.bias = None
        if elementwise_affine:
            self.weight = nn.Parameter(torch.ones(dim))
            if bias:
                self.bias = nn.Parameter(torch.zeros(dim))

    def forward(self, hidden_states):
        if is_torch_npu_available():
            import torch_npu
            if self.weight is not None:
                if self.weight.dtype in [torch.float16, torch.bfloat16]:
                    hidden_states = hidden_states.to(self.weight.dtype)
            hidden_states = torch_npu.npu_rms_norm(hidden_states, self.weight, epsilon=self.eps)[0]
            if self.bias is not None:
                hidden_states = hidden_states + self.bias
        else:
            input_dtype = hidden_states.dtype
            variance = hidden_states.to(torch.float32).pow(2).mean(-1, keepdim=True)
            hidden_states = hidden_states * torch.rsqrt(variance + self.eps)
            if self.weight is not None:
                if self.weight.dtype in [torch.float16, torch.bfloat16]:
                    hidden_states = hidden_states.to(self.weight.dtype)
                hidden_states = hidden_states * self.weight
                if self.bias is not None:
                    hidden_states = hidden_states + self.bias
            else:
                hidden_states = hidden_states.to(input_dtype)
        return hidden_states

def load_model_dict_into_meta(model, state_dict: OrderedDict, dtype: str | torch.dtype | None=None, model_name_or_path: str | None=None, hf_quantizer: DiffusersQuantizer | None=None, keep_in_fp32_modules: list | None=None, device_map: dict[str, int | str | torch.device] | None=None, unexpected_keys: list[str] | None=None, offload_folder: str | os.PathLike | None=None, offload_index: dict | None=None, state_dict_index: dict | None=None, state_dict_folder: str | os.PathLike | None=None) -> list[str]:
    is_quantized = hf_quantizer is not None
    empty_state_dict = model.state_dict()
    for param_name, param in state_dict.items():
        if param_name not in empty_state_dict:
            continue
        set_module_kwargs = {}
        if dtype is not None and torch.is_floating_point(param):
            if keep_in_fp32_modules is not None and any((module_to_keep_in_fp32 in param_name.split('.') for module_to_keep_in_fp32 in keep_in_fp32_modules)):
                param = param.to(torch.float32)
                set_module_kwargs['dtype'] = torch.float32
            elif hf_quantizer is not None and param.dtype == getattr(torch, 'float8_e4m3fn', None):
                pass
            else:
                param = param.to(dtype)
                set_module_kwargs['dtype'] = dtype
        if is_accelerate_version('>', '1.8.1'):
            set_module_kwargs['non_blocking'] = True
            set_module_kwargs['clear_cache'] = False
        old_param = model
        splits = param_name.split('.')
        for split in splits:
            old_param = getattr(old_param, split)
        if not isinstance(old_param, (torch.nn.Parameter, torch.Tensor)):
            old_param = None
        if old_param is not None:
            if dtype is None:
                param = param.to(old_param.dtype)
            if old_param.is_contiguous():
                param = param.contiguous()
        param_device = _determine_param_device(param_name, device_map)
        if empty_state_dict[param_name].shape != param.shape:
            if is_quantized and hf_quantizer.pre_quantized and hf_quantizer.check_if_quantized_param(model, param, param_name, state_dict, param_device=param_device):
                hf_quantizer.check_quantized_param_shape(param_name, empty_state_dict[param_name], param)
            else:
                model_name_or_path_str = f'{model_name_or_path} ' if model_name_or_path is not None else ''
                raise ValueError(f'Cannot load {model_name_or_path_str} because {param_name} expected shape {empty_state_dict[param_name].shape}, but got {param.shape}. If you want to instead overwrite randomly initialized weights, please make sure to pass both `low_cpu_mem_usage=False` and `ignore_mismatched_sizes=True`. For more information, see also: https://github.com/huggingface/diffusers/issues/1619#issuecomment-1345604389 as an example.')
        if param_device == 'disk':
            offload_index = offload_weight(param, param_name, offload_folder, offload_index)
        elif param_device == 'cpu' and state_dict_index is not None:
            state_dict_index = offload_weight(param, param_name, state_dict_folder, state_dict_index)
        elif is_quantized and hf_quantizer.check_if_quantized_param(model, param, param_name, state_dict, param_device=param_device):
            hf_quantizer.create_quantized_param(model, param, param_name, param_device, state_dict, unexpected_keys, dtype=dtype)
        else:
            set_module_tensor_to_device(model, param_name, param_device, value=param, **set_module_kwargs)
    return (offload_index, state_dict_index)

# --- helper: diffusers.models.model_loading_utils._determine_param_device ---
def _determine_param_device(param_name: str, device_map: dict[str, int | str | torch.device] | None):
    if device_map is None:
        return 'cpu'
    else:
        module_name = param_name
        while len(module_name) > 0 and module_name not in device_map:
            module_name = '.'.join(module_name.split('.')[:-1])
        if module_name == '' and '' not in device_map:
            raise ValueError(f"{param_name} doesn't have any device set.")
        return device_map[module_name]

class SD35AdaLayerNormZeroX(nn.Module):

    def __init__(self, embedding_dim: int, norm_type: str='layer_norm', bias: bool=True) -> None:
        super().__init__()
        self.silu = nn.SiLU()
        self.linear = nn.Linear(embedding_dim, 9 * embedding_dim, bias=bias)
        if norm_type == 'layer_norm':
            self.norm = nn.LayerNorm(embedding_dim, elementwise_affine=False, eps=1e-06)
        else:
            raise ValueError(f"Unsupported `norm_type` ({norm_type}) provided. Supported ones are: 'layer_norm'.")

    def forward(self, hidden_states: torch.Tensor, emb: torch.Tensor | None=None) -> tuple[torch.Tensor, ...]:
        emb = self.linear(self.silu(emb))
        shift_msa, scale_msa, gate_msa, shift_mlp, scale_mlp, gate_mlp, shift_msa2, scale_msa2, gate_msa2 = emb.chunk(9, dim=1)
        norm_hidden_states = self.norm(hidden_states)
        hidden_states = norm_hidden_states * (1 + scale_msa[:, None]) + shift_msa[:, None]
        norm_hidden_states2 = norm_hidden_states * (1 + scale_msa2[:, None]) + shift_msa2[:, None]
        return (hidden_states, gate_msa, shift_mlp, scale_mlp, gate_mlp, norm_hidden_states2, gate_msa2)

