class CustomOffloadHook(ModelHook):
    no_grad = False

    def __init__(self, execution_device: str | int | torch.device | None=None, other_hooks: list['UserCustomOffloadHook'] | None=None, offload_strategy: 'AutoOffloadStrategy' | None=None):
        self.execution_device = execution_device if execution_device is not None else PartialState().default_device
        self.other_hooks = other_hooks
        self.offload_strategy = offload_strategy
        self.model_id = None

    def set_strategy(self, offload_strategy: 'AutoOffloadStrategy'):
        self.offload_strategy = offload_strategy

    def add_other_hook(self, hook: 'UserCustomOffloadHook'):
        if self.other_hooks is None:
            self.other_hooks = []
        self.other_hooks.append(hook)

    def init_hook(self, module):
        return module.to('cpu')

    def pre_forward(self, module, *args, **kwargs):
        if module.device != self.execution_device:
            if self.other_hooks is not None:
                hooks_to_offload = [hook for hook in self.other_hooks if hook.model.device == self.execution_device]
                start_time = time.perf_counter()
                if self.offload_strategy is not None:
                    hooks_to_offload = self.offload_strategy(hooks=hooks_to_offload, model_id=self.model_id, model=module, execution_device=self.execution_device)
                end_time = time.perf_counter()
                logger.info(f' time taken to apply offload strategy for {self.model_id}: {end_time - start_time:.2f} seconds')
                for hook in hooks_to_offload:
                    logger.info(f'moving {self.model_id} to {self.execution_device}, offloading {hook.model_id} to cpu')
                    hook.offload()
                if hooks_to_offload:
                    clear_device_cache()
            module.to(self.execution_device)
        return (send_to_device(args, self.execution_device), send_to_device(kwargs, self.execution_device))

def summarize_dict_by_value_and_parts(d: dict[str, Any]) -> dict[str, Any]:
    value_to_keys = {}
    for key, value in d.items():
        value_tuple = tuple(value) if isinstance(value, list) else value
        if value_tuple not in value_to_keys:
            value_to_keys[value_tuple] = []
        value_to_keys[value_tuple].append(key)

    def find_common_prefix(keys: list[str]) -> str:
        if not keys:
            return ''
        if len(keys) == 1:
            return keys[0]
        key_parts = [k.split('.') for k in keys]
        common_length = 0
        for parts in zip(*key_parts):
            if len(set(parts)) == 1:
                common_length += 1
            else:
                break
        if common_length == 0:
            return ''
        return '.'.join(key_parts[0][:common_length])
    summary = {}
    for value_tuple, keys in value_to_keys.items():
        prefix = find_common_prefix(keys)
        if prefix:
            value = list(value_tuple) if isinstance(d[keys[0]], list) else value_tuple
            summary[prefix] = value
        else:
            summary[''] = value
    return summary

class ErnieImagePachifier(ConfigMixin):
    config_name = 'config.json'

    @register_to_config
    def __init__(self, patch_size: int=2):
        super().__init__()

    def pack_latents(self, latents: torch.Tensor) -> torch.Tensor:
        batch_size, num_channels, height, width = latents.shape
        patch_size = self.config.patch_size
        if height % patch_size != 0 or width % patch_size != 0:
            raise ValueError(f'Latent height and width must be divisible by {patch_size}, but got {height} and {width}')
        latents = latents.view(batch_size, num_channels, height // patch_size, patch_size, width // patch_size, patch_size)
        latents = latents.permute(0, 1, 3, 5, 2, 4)
        return latents.reshape(batch_size, num_channels * patch_size * patch_size, height // patch_size, width // patch_size)

    def unpack_latents(self, latents: torch.Tensor) -> torch.Tensor:
        batch_size, num_channels, height, width = latents.shape
        patch_size = self.config.patch_size
        latents = latents.reshape(batch_size, num_channels // (patch_size * patch_size), patch_size, patch_size, height, width)
        latents = latents.permute(0, 1, 4, 2, 5, 3)
        return latents.reshape(batch_size, num_channels // (patch_size * patch_size), height * patch_size, width * patch_size)

def format_text_input(prompts: list[str], system_message: str=None):
    cleaned_txt = [prompt.replace('[IMG]', '') for prompt in prompts]
