class HeliosChunkLoopWrapper(LoopSequentialPipelineBlocks):
    model_name = 'helios'

    @property
    def description(self) -> str:
        return 'Pipeline block that iterates over temporal chunks for progressive video generation. At each chunk iteration, it runs sub-blocks for preparation, denoising, and history updates.'

    @property
    def loop_inputs(self) -> list[InputParam]:
