class QwenImageAdditionalInputsStep(ModularPipelineBlocks):
    model_name = 'qwenimage'

    def __init__(self, image_latent_inputs: list[InputParam] | None=None, additional_batch_inputs: list[InputParam] | None=None):
        if image_latent_inputs is None:
            image_latent_inputs = [InputParam.template('image_latents')]
        if additional_batch_inputs is None:
            additional_batch_inputs = []
        if not isinstance(image_latent_inputs, list):
            raise ValueError(f'image_latent_inputs must be a list, but got {type(image_latent_inputs)}')
        else:
            for input_param in image_latent_inputs:
                if not isinstance(input_param, InputParam):
                    raise ValueError(f'image_latent_inputs must be a list of InputParam, but got {type(input_param)}')
        if not isinstance(additional_batch_inputs, list):
            raise ValueError(f'additional_batch_inputs must be a list, but got {type(additional_batch_inputs)}')
        else:
            for input_param in additional_batch_inputs:
                if not isinstance(input_param, InputParam):
                    raise ValueError(f'additional_batch_inputs must be a list of InputParam, but got {type(input_param)}')
        self._image_latent_inputs = image_latent_inputs
        self._additional_batch_inputs = additional_batch_inputs
        super().__init__()

    @property
    def description(self) -> str:
        summary_section = 'Input processing step that:\n  1. For image latent inputs: Updates height/width if None, patchifies, and expands batch size\n  2. For additional batch inputs: Expands batch dimensions to match final batch size'
        inputs_info = ''
        if self._image_latent_inputs or self._additional_batch_inputs:
            inputs_info = '\n\nConfigured inputs:'
            if self._image_latent_inputs:
                inputs_info += f'\n  - Image latent inputs: {[p.name for p in self._image_latent_inputs]}'
            if self._additional_batch_inputs:
                inputs_info += f'\n  - Additional batch inputs: {[p.name for p in self._additional_batch_inputs]}'
        placement_section = '\n\nThis block should be placed after the encoder steps and the text input step.'
        return summary_section + inputs_info + placement_section

    @property
    def expected_components(self) -> list[ComponentSpec]:
        return [ComponentSpec('pachifier', QwenImagePachifier, default_creation_method='from_config')]

    @property
    def inputs(self) -> list[InputParam]:
        inputs = [InputParam.template('num_images_per_prompt'), InputParam.template('batch_size'), InputParam.template('height'), InputParam.template('width')]
        inputs += self._image_latent_inputs + self._additional_batch_inputs
        return inputs

    @property
    def intermediate_outputs(self) -> list[OutputParam]:
        outputs = [OutputParam(name='image_height', type_hint=int, description='The image height calculated from the image latents dimension'), OutputParam(name='image_width', type_hint=int, description='The image width calculated from the image latents dimension')]
        if len(self._image_latent_inputs) > 0:
            outputs.append(OutputParam(name='height', type_hint=int, description='if not provided, updated to image height'))
            outputs.append(OutputParam(name='width', type_hint=int, description='if not provided, updated to image width'))
        for input_param in self._image_latent_inputs:
            outputs.append(OutputParam(name=input_param.name, type_hint=input_param.type_hint, description=input_param.description + ' (patchified and batch-expanded)'))
        for input_param in self._additional_batch_inputs:
            outputs.append(OutputParam(name=input_param.name, type_hint=input_param.type_hint, description=input_param.description + ' (batch-expanded)'))
        return outputs

    def __call__(self, components: QwenImageModularPipeline, state: PipelineState) -> PipelineState:
        block_state = self.get_block_state(state)
        for input_param in self._image_latent_inputs:
            image_latent_input_name = input_param.name
            image_latent_tensor = getattr(block_state, image_latent_input_name)
            if image_latent_tensor is None:
                continue
            height, width = calculate_dimension_from_latents(image_latent_tensor, components.vae_scale_factor)
            block_state.height = block_state.height or height
            block_state.width = block_state.width or width
            if not hasattr(block_state, 'image_height'):
                block_state.image_height = height
            if not hasattr(block_state, 'image_width'):
                block_state.image_width = width
            image_latent_tensor = components.pachifier.pack_latents(image_latent_tensor)
            image_latent_tensor = repeat_tensor_to_batch_size(input_name=image_latent_input_name, input_tensor=image_latent_tensor, num_images_per_prompt=block_state.num_images_per_prompt, batch_size=block_state.batch_size)
            setattr(block_state, image_latent_input_name, image_latent_tensor)
        for input_param in self._additional_batch_inputs:
            input_name = input_param.name
            input_tensor = getattr(block_state, input_name)
            if input_tensor is None:
                continue
            input_tensor = repeat_tensor_to_batch_size(input_name=input_name, input_tensor=input_tensor, num_images_per_prompt=block_state.num_images_per_prompt, batch_size=block_state.batch_size)
            setattr(block_state, input_name, input_tensor)
        self.set_block_state(state, block_state)
        return (components, state)

# --- helper: diffusers.modular_pipelines.qwenimage.inputs.calculate_dimension_from_latents ---
def calculate_dimension_from_latents(latents: torch.Tensor, vae_scale_factor: int) -> tuple[int, int]:
    if latents.ndim != 4 and latents.ndim != 5:
        raise ValueError(f'unpacked latents must have 4 or 5 dimensions, but got {latents.ndim}')
    latent_height, latent_width = latents.shape[-2:]
    height = latent_height * vae_scale_factor
    width = latent_width * vae_scale_factor
    return (height, width)

# --- helper: diffusers.modular_pipelines.qwenimage.inputs.repeat_tensor_to_batch_size ---
def repeat_tensor_to_batch_size(input_name: str, input_tensor: torch.Tensor, batch_size: int, num_images_per_prompt: int=1) -> torch.Tensor:
    if not isinstance(input_tensor, torch.Tensor):
        raise ValueError(f'`{input_name}` must be a tensor')
    if input_tensor.shape[0] == 1:
        repeat_by = batch_size * num_images_per_prompt
    elif input_tensor.shape[0] == batch_size:
        repeat_by = num_images_per_prompt
    else:
        raise ValueError(f'`{input_name}` must have have batch size 1 or {batch_size}, but got {input_tensor.shape[0]}')
    input_tensor = input_tensor.repeat_interleave(repeat_by, dim=0)
    return input_tensor

