class Flux2ImageProcessor(VaeImageProcessor):

    @register_to_config
    def __init__(self, do_resize: bool=True, vae_scale_factor: int=16, vae_latent_channels: int=32, do_normalize: bool=True, do_binarize: bool=False, do_convert_rgb: bool=True, do_convert_grayscale: bool=False):
        super().__init__(do_resize=do_resize, vae_scale_factor=vae_scale_factor, vae_latent_channels=vae_latent_channels, do_normalize=do_normalize, do_binarize=do_binarize, do_convert_rgb=do_convert_rgb, do_convert_grayscale=do_convert_grayscale)

    @staticmethod
    def check_image_input(image: PIL.Image.Image, max_aspect_ratio: int=8, min_side_length: int=64, max_area: int=1024 * 1024) -> PIL.Image.Image:
        if not isinstance(image, PIL.Image.Image):
            raise ValueError(f'Image must be a PIL.Image.Image, got {type(image)}')
        width, height = image.size
        if width < min_side_length or height < min_side_length:
            raise ValueError(f'Image too small: {width}×{height}. Both dimensions must be at least {min_side_length}px')
        aspect_ratio = max(width / height, height / width)
        if aspect_ratio > max_aspect_ratio:
            raise ValueError(f'Aspect ratio too extreme: {width}×{height} (ratio: {aspect_ratio:.1f}:1). Maximum allowed ratio is {max_aspect_ratio}:1')
        return image

    @staticmethod
    def _resize_to_target_area(image: PIL.Image.Image, target_area: int=1024 * 1024) -> PIL.Image.Image:
        image_width, image_height = image.size
        scale = math.sqrt(target_area / (image_width * image_height))
        width = int(image_width * scale)
        height = int(image_height * scale)
        return image.resize((width, height), PIL.Image.Resampling.LANCZOS)

    @staticmethod
    def _resize_if_exceeds_area(image, target_area=1024 * 1024) -> PIL.Image.Image:
        image_width, image_height = image.size
        pixel_count = image_width * image_height
        if pixel_count <= target_area:
            return image
        return Flux2ImageProcessor._resize_to_target_area(image, target_area)

    def _resize_and_crop(self, image: PIL.Image.Image, width: int, height: int) -> PIL.Image.Image:
        image_width, image_height = image.size
        left = (image_width - width) // 2
        top = (image_height - height) // 2
        right = left + width
        bottom = top + height
        return image.crop((left, top, right, bottom))

    @staticmethod
    def concatenate_images(images: list[PIL.Image.Image]) -> PIL.Image.Image:
        if len(images) == 1:
            return images[0].copy()
        images = [img.convert('RGB') if img.mode != 'RGB' else img for img in images]
        total_width = sum((img.width for img in images))
        max_height = max((img.height for img in images))
        background_color = (255, 255, 255)
        new_img = PIL.Image.new('RGB', (total_width, max_height), background_color)
        x_offset = 0
        for img in images:
            y_offset = (max_height - img.height) // 2
            new_img.paste(img, (x_offset, y_offset))
            x_offset += img.width
        return new_img

def get_closest_ratio(height: float, width: float, ratios: list, buckets: list):
    aspect_ratio = float(height) / float(width)
    diff_ratios = ratios - aspect_ratio
    if aspect_ratio >= 1:
        indices = [(index, x) for index, x in enumerate(diff_ratios) if x <= 0]
    else:
        indices = [(index, x) for index, x in enumerate(diff_ratios) if x >= 0]
    closest_ratio_id = min(indices, key=lambda pair: abs(pair[1]))[0]
    closest_size = buckets[closest_ratio_id]
    closest_ratio = ratios[closest_ratio_id]
    return (closest_size, closest_ratio)

def format_input(prompts: list[str], system_message: str=SYSTEM_MESSAGE, images: list[PIL.Image.Image, list[list[PIL.Image.Image]]] | None=None):
    cleaned_txt = [prompt.replace('[IMG]', '') for prompt in prompts]
    if images is None or len(images) == 0:
        return [[{'role': 'system', 'content': [{'type': 'text', 'text': system_message}]}, {'role': 'user', 'content': [{'type': 'text', 'text': prompt}]}] for prompt in cleaned_txt]
    else:
        assert len(images) == len(prompts), 'Number of images must match number of prompts'
        messages = [[{'role': 'system', 'content': [{'type': 'text', 'text': system_message}]}] for _ in cleaned_txt]
        for i, (el, images) in enumerate(zip(messages, images)):
            if images is not None:
                el.append({'role': 'user', 'content': [{'type': 'image', 'image': image_obj} for image_obj in images]})
            el.append({'role': 'user', 'content': [{'type': 'text', 'text': cleaned_txt[i]}]})
        return messages

class SplitInferenceModule(nn.Module):

    def __init__(self, module: nn.Module, split_size: int=1, split_dim: int=0, input_kwargs_to_split: list[str]=['hidden_states']) -> None:
        super().__init__()
        self.module = module
        self.split_size = split_size
        self.split_dim = split_dim
        self.input_kwargs_to_split = set(input_kwargs_to_split)

    def forward(self, *args, **kwargs) -> torch.Tensor | tuple[torch.Tensor]:
        split_inputs = {}
        for key in list(kwargs.keys()):
            if key not in self.input_kwargs_to_split or not torch.is_tensor(kwargs[key]):
                continue
            split_inputs[key] = torch.split(kwargs[key], self.split_size, self.split_dim)
            kwargs.pop(key)
        results = []
        for split_input in zip(*split_inputs.values()):
            inputs = dict(zip(split_inputs.keys(), split_input))
            inputs.update(kwargs)
            intermediate_tensor_or_tensor_tuple = self.module(*args, **inputs)
            results.append(intermediate_tensor_or_tensor_tuple)
        if isinstance(results[0], torch.Tensor):
            return torch.cat(results, dim=self.split_dim)
        elif isinstance(results[0], tuple):
            return tuple([torch.cat(x, dim=self.split_dim) for x in zip(*results)])
        else:
            raise ValueError("In order to use the SplitInferenceModule, it is necessary for the underlying `module` to either return a torch.Tensor or a tuple of torch.Tensor's.")

def extract_glyph_texts(prompt: str) -> list[str]:
    pattern = '\\"(.*?)\\"|“(.*?)”'
    matches = re.findall(pattern, prompt)
    result = [match[0] or match[1] for match in matches]
    result = list(dict.fromkeys(result)) if len(result) > 1 else result
    if result:
        formatted_result = '. '.join([f'Text "{text}"' for text in result]) + '. '
    else:
        formatted_result = None
    return formatted_result

