def convert_state_dict(unet_state_dict):
    converted_state_dict = {}
    for key in unet_state_dict:
        new_key = key
        for pattern, new_pattern in MAPPING.items():
            new_key = new_key.replace(pattern, new_pattern)
        for dyn_pattern, dyn_new_pattern in DYNAMIC_MAP.items():
            has_matched = False
            if fnmatch.fnmatch(new_key, f'*.{dyn_pattern}.*') and (not has_matched):
                star = int(new_key.split(dyn_pattern.split('.')[0])[-1].split('.')[1])
                if isinstance(dyn_new_pattern, tuple):
                    new_star = star + dyn_new_pattern[-1]
                    dyn_new_pattern = dyn_new_pattern[0]
                else:
                    new_star = star
                pattern = dyn_pattern.replace('*', str(star))
                new_pattern = dyn_new_pattern.replace('*', str(new_star))
                new_key = new_key.replace(pattern, new_pattern)
                has_matched = True
        converted_state_dict[new_key] = unet_state_dict[key]
    return converted_state_dict

def split_tensor_along_last_dim(tensor: torch.Tensor, num_partitions: int, contiguous_split_chunks: bool=False) -> list[torch.Tensor]:
    last_dim = tensor.dim() - 1
    last_dim_size = tensor.size()[last_dim] // num_partitions
    tensor_list = torch.split(tensor, last_dim_size, dim=last_dim)
    if contiguous_split_chunks:
        return tuple((chunk.contiguous() for chunk in tensor_list))
    return tensor_list

def split_quotation(prompt, quote_pairs=None):
    word_internal_quote_pattern = re.compile("[a-zA-Z]+'[a-zA-Z]+")
    matches_word_internal_quote_pattern = word_internal_quote_pattern.findall(prompt)
    mapping_word_internal_quote = []
    for i, word_src in enumerate(set(matches_word_internal_quote_pattern)):
        word_tgt = 'longcat_$##$_longcat' * (i + 1)
        prompt = prompt.replace(word_src, word_tgt)
        mapping_word_internal_quote.append([word_src, word_tgt])
    if quote_pairs is None:
        quote_pairs = [("'", "'"), ('"', '"'), ('‘', '’'), ('“', '”')]
    pattern = '|'.join([re.escape(q1) + '[^' + re.escape(q1 + q2) + ']*?' + re.escape(q2) for q1, q2 in quote_pairs])
    parts = re.split(f'({pattern})', prompt)
    result = []
    for part in parts:
        for word_src, word_tgt in mapping_word_internal_quote:
            part = part.replace(word_tgt, word_src)
        if re.match(pattern, part):
            if len(part):
                result.append((part, True))
        elif len(part):
            result.append((part, False))
    return result

