def stable_unclip_image_noising_components(original_config, clip_stats_path: str | None=None, device: str | None=None):
    noise_aug_config = original_config['model']['params']['noise_aug_config']
    noise_aug_class = noise_aug_config['target']
    noise_aug_class = noise_aug_class.split('.')[-1]
    if noise_aug_class == 'CLIPEmbeddingNoiseAugmentation':
        noise_aug_config = noise_aug_config.params
        embedding_dim = noise_aug_config.timestep_dim
        max_noise_level = noise_aug_config.noise_schedule_config.timesteps
        beta_schedule = noise_aug_config.noise_schedule_config.beta_schedule
        image_normalizer = StableUnCLIPImageNormalizer(embedding_dim=embedding_dim)
        image_noising_scheduler = DDPMScheduler(num_train_timesteps=max_noise_level, beta_schedule=beta_schedule)
        if 'clip_stats_path' in noise_aug_config:
            if clip_stats_path is None:
                raise ValueError('This stable unclip config requires a `clip_stats_path`')
            clip_mean, clip_std = torch.load(clip_stats_path, map_location=device)
            clip_mean = clip_mean[None, :]
            clip_std = clip_std[None, :]
            clip_stats_state_dict = {'mean': clip_mean, 'std': clip_std}
            image_normalizer.load_state_dict(clip_stats_state_dict)
    else:
        raise NotImplementedError(f'Unknown noise augmentor class: {noise_aug_class}')
    return (image_normalizer, image_noising_scheduler)

class WanAnimateImageProcessor(VaeImageProcessor):

    @register_to_config
    def __init__(self, do_resize: bool=True, vae_scale_factor: int=8, vae_latent_channels: int=16, spatial_patch_size: tuple[int, int]=(2, 2), resample: str='lanczos', reducing_gap: int=None, do_normalize: bool=True, do_binarize: bool=False, do_convert_rgb: bool=False, do_convert_grayscale: bool=False, fill_color: str | float | tuple[float, ...] | None=0):
        super().__init__()
        if do_convert_rgb and do_convert_grayscale:
            raise ValueError('`do_convert_rgb` and `do_convert_grayscale` can not both be set to `True`, if you intended to convert the image into RGB format, please set `do_convert_grayscale = False`.', ' if you intended to convert the image into grayscale format, please set `do_convert_rgb = False`')

    def _resize_and_fill(self, image: PIL.Image.Image, width: int, height: int) -> PIL.Image.Image:
        ratio = width / height
        src_ratio = image.width / image.height
        fill_with_image_data = self.config.fill_color is None
        fill_color = self.config.fill_color or 0
        src_w = width if ratio < src_ratio else image.width * height // image.height
        src_h = height if ratio >= src_ratio else image.height * width // image.width
        resized = image.resize((src_w, src_h), resample=PIL_INTERPOLATION[self.config.resample])
        res = PIL.Image.new('RGB', (width, height), color=fill_color)
        res.paste(resized, box=(width // 2 - src_w // 2, height // 2 - src_h // 2))
        if fill_with_image_data:
            if ratio < src_ratio:
                fill_height = height // 2 - src_h // 2
                if fill_height > 0:
                    res.paste(resized.resize((width, fill_height), box=(0, 0, width, 0)), box=(0, 0))
                    res.paste(resized.resize((width, fill_height), box=(0, resized.height, width, resized.height)), box=(0, fill_height + src_h))
            elif ratio > src_ratio:
                fill_width = width // 2 - src_w // 2
                if fill_width > 0:
                    res.paste(resized.resize((fill_width, height), box=(0, 0, 0, height)), box=(0, 0))
                    res.paste(resized.resize((fill_width, height), box=(resized.width, 0, resized.width, height)), box=(fill_width + src_w, 0))
        return res

    def get_default_height_width(self, image: PIL.Image.Image | np.ndarray | torch.Tensor, height: int | None=None, width: int | None=None) -> tuple[int, int]:
        if height is None:
            if isinstance(image, PIL.Image.Image):
                height = image.height
            elif isinstance(image, torch.Tensor):
                height = image.shape[2]
            else:
                height = image.shape[1]
        if width is None:
            if isinstance(image, PIL.Image.Image):
                width = image.width
            elif isinstance(image, torch.Tensor):
                width = image.shape[3]
            else:
                width = image.shape[2]
        max_area = width * height
        aspect_ratio = height / width
        mod_value_h = self.config.vae_scale_factor * self.config.spatial_patch_size[0]
        mod_value_w = self.config.vae_scale_factor * self.config.spatial_patch_size[1]
        height = round(np.sqrt(max_area * aspect_ratio)) // mod_value_h * mod_value_h
        width = round(np.sqrt(max_area / aspect_ratio)) // mod_value_w * mod_value_w
        return (height, width)

def dequantize_bnb_weight(weight: 'torch.nn.Parameter', state=None, dtype: 'torch.dtype'=None):
    if not isinstance(weight, torch.nn.Parameter):
        raise TypeError(f'Input weight should be of type nn.Parameter, got {type(weight)} instead')
    cls_name = weight.__class__.__name__
    if cls_name not in ('Params4bit', 'Int8Params'):
        return weight
    if cls_name == 'Params4bit':
        output_tensor = bnb.functional.dequantize_4bit(weight.data, weight.quant_state)
        msg = f'The model is going to be dequantized in {output_tensor.dtype} - if you want to upcast it to another dtype, make sure to pass the desired dtype when quantizing the model through `bnb_4bit_quant_type` argument of `BitsAndBytesConfig`'
        if dtype:
            msg = f'The model is going to be first dequantized in {output_tensor.dtype} and type-casted to {dtype}'
            output_tensor = output_tensor.to(dtype)
        logger.warning_once(msg)
        return output_tensor
    if state.SCB is None:
        state.SCB = weight.SCB
    if hasattr(bnb.functional, 'int8_vectorwise_dequant'):
        dequantized = bnb.functional.int8_vectorwise_dequant(weight.data, state.SCB)
    else:
        dequantized = weight.data * state.SCB.view(-1, 1) * 0.007874015718698502
    if dtype:
        dequantized = dequantized.to(dtype)
    return dequantized

def replace_with_bnb_linear(model, modules_to_not_convert=None, current_key_name=None, quantization_config=None):
    model, _ = _replace_with_bnb_linear(model, modules_to_not_convert, current_key_name, quantization_config)
    has_been_replaced = any((isinstance(replaced_module, (bnb.nn.Linear4bit, bnb.nn.Linear8bitLt)) for _, replaced_module in model.named_modules()))
    if not has_been_replaced:
        logger.warning('You are loading your model in 8bit or 4bit but no linear modules were found in your model. Please double check your model architecture, or submit an issue on github if you think this is a bug.')
    return model

# --- helper: diffusers.quantizers.bitsandbytes.utils._replace_with_bnb_linear ---
def _replace_with_bnb_linear(model, modules_to_not_convert=None, current_key_name=None, quantization_config=None, has_been_replaced=False):
    for name, module in model.named_children():
        if current_key_name is None:
            current_key_name = []
        current_key_name.append(name)
        if isinstance(module, nn.Linear) and name not in modules_to_not_convert:
            current_key_name_str = '.'.join(current_key_name)
            if not any((key + '.' in current_key_name_str or key == current_key_name_str for key in modules_to_not_convert)):
                with init_empty_weights():
                    in_features = module.in_features
                    out_features = module.out_features
                    if quantization_config.quantization_method() == 'llm_int8':
                        model._modules[name] = bnb.nn.Linear8bitLt(in_features, out_features, module.bias is not None, has_fp16_weights=quantization_config.llm_int8_has_fp16_weight, threshold=quantization_config.llm_int8_threshold)
                        has_been_replaced = True
                    elif quantization_config.llm_int8_skip_modules is not None and name in quantization_config.llm_int8_skip_modules:
                        pass
                    else:
                        extra_kwargs = {'quant_storage': quantization_config.bnb_4bit_quant_storage} if 'quant_storage' in list(signature(bnb.nn.Linear4bit).parameters) else {}
                        model._modules[name] = bnb.nn.Linear4bit(in_features, out_features, module.bias is not None, quantization_config.bnb_4bit_compute_dtype, compress_statistics=quantization_config.bnb_4bit_use_double_quant, quant_type=quantization_config.bnb_4bit_quant_type, **extra_kwargs)
                        has_been_replaced = True
                    model._modules[name].source_cls = type(module)
                    model._modules[name].requires_grad_(False)
        if len(list(module.children())) > 0:
            _, has_been_replaced = _replace_with_bnb_linear(module, modules_to_not_convert, current_key_name, quantization_config, has_been_replaced=has_been_replaced)
        current_key_name.pop(-1)
    return (model, has_been_replaced)

class GGUFLinear(nn.Linear):

    def __init__(self, in_features, out_features, bias=False, compute_dtype=None, device=None) -> None:
        super().__init__(in_features, out_features, bias, device)
        self.compute_dtype = compute_dtype
        self.device = device

    def forward(self, inputs: torch.Tensor):
        if ops is not None and self.weight.is_cuda and inputs.is_cuda:
            return self.forward_cuda(inputs)
        return self.forward_native(inputs)

    def forward_native(self, inputs: torch.Tensor):
        weight = dequantize_gguf_tensor(self.weight)
        weight = weight.to(self.compute_dtype)
        bias = self.bias.to(self.compute_dtype) if self.bias is not None else None
        output = torch.nn.functional.linear(inputs, weight, bias)
        return output

    def forward_cuda(self, inputs: torch.Tensor):
        quant_type = self.weight.quant_type
        output = _fused_mul_mat_gguf(inputs.to(self.compute_dtype), self.weight, quant_type)
        if self.bias is not None:
            output += self.bias.to(self.compute_dtype)
        return output

# --- helper: diffusers.quantizers.gguf.utils._fused_mul_mat_gguf ---
def _fused_mul_mat_gguf(x: torch.Tensor, qweight: torch.Tensor, qweight_type: int) -> torch.Tensor:
    if qweight_type in UNQUANTIZED_TYPES:
        weight = dequantize_gguf_tensor(qweight)
        return x @ weight.T
    if qweight_type in DEQUANT_TYPES:
        block_size, type_size = gguf.GGML_QUANT_SIZES[qweight_type]
        shape = (qweight.shape[0], qweight.shape[1] // type_size * block_size)
        weight = ops.ggml_dequantize(qweight, qweight_type, *shape)
        y = x @ weight.to(x.dtype).T
    else:
        qweight_type = gguf.GGMLQuantizationType(qweight_type)
        raise NotImplementedError(f'Unsupported GGUF quantization type: {qweight_type}')
    return y.as_tensor()

# --- helper: diffusers.quantizers.gguf.utils.dequantize_gguf_tensor ---
def dequantize_gguf_tensor(tensor):
    if not hasattr(tensor, 'quant_type'):
        return tensor
    quant_type = tensor.quant_type
    dequant_fn = dequantize_functions[quant_type]
    block_size, type_size = GGML_QUANT_SIZES[quant_type]
    tensor = tensor.as_tensor()
    tensor = tensor.view(torch.uint8)
    shape = _quant_shape_from_byte_shape(tensor.shape, type_size, block_size)
    n_blocks = tensor.numel() // type_size
    blocks = tensor.reshape((n_blocks, type_size))
    dequant = dequant_fn(blocks, block_size, type_size)
    dequant = dequant.reshape(shape)
    return dequant

class GGUFParameter(torch.nn.Parameter):

    def __new__(cls, data, requires_grad=False, quant_type=None):
        data = data if data is not None else torch.empty(0)
        self = torch.Tensor._make_subclass(cls, data, requires_grad)
        self.quant_type = quant_type
        block_size, type_size = GGML_QUANT_SIZES[quant_type]
        self.quant_shape = _quant_shape_from_byte_shape(self.shape, type_size, block_size)
        return self

    def as_tensor(self):
        return torch.Tensor._make_subclass(torch.Tensor, self, self.requires_grad)

    @staticmethod
    def _extract_quant_type(args):
        for arg in args:
            if isinstance(arg, list) and isinstance(arg[0], GGUFParameter):
                return arg[0].quant_type
            if isinstance(arg, GGUFParameter):
                return arg.quant_type
        return None

    @classmethod
    def __torch_function__(cls, func, types, args=(), kwargs=None):
        if kwargs is None:
            kwargs = {}
        result = super().__torch_function__(func, types, args, kwargs)
        if isinstance(result, torch.Tensor):
            quant_type = cls._extract_quant_type(args)
            return cls(result, quant_type=quant_type)
        elif type(result) in (list, tuple):
            quant_type = cls._extract_quant_type(args)
            wrapped = [cls(x, quant_type=quant_type) if isinstance(x, torch.Tensor) else x for x in result]
            return type(result)(wrapped)
        else:
            return result

# --- helper: diffusers.quantizers.gguf.utils._quant_shape_from_byte_shape ---
def _quant_shape_from_byte_shape(shape, type_size, block_size):
    return (*shape[:-1], shape[-1] // type_size * block_size)

def gumbel_noise(t: torch.Tensor, generator: torch.Generator | None=None) -> torch.Tensor:
    device = generator.device if generator is not None else t.device
    noise = torch.zeros_like(t, device=device).uniform_(0, 1, generator=generator).to(t.device)
    return -torch.log((-torch.log(noise.clamp(1e-20))).clamp(1e-20))

@dataclass
class BitsAndBytesConfig(QuantizationConfigMixin):
    _exclude_attributes_at_init = ['_load_in_4bit', '_load_in_8bit', 'quant_method']

    def __init__(self, load_in_8bit=False, load_in_4bit=False, llm_int8_threshold=6.0, llm_int8_skip_modules=None, llm_int8_enable_fp32_cpu_offload=False, llm_int8_has_fp16_weight=False, bnb_4bit_compute_dtype=None, bnb_4bit_quant_type='fp4', bnb_4bit_use_double_quant=False, bnb_4bit_quant_storage=None, **kwargs):
        self.quant_method = QuantizationMethod.BITS_AND_BYTES
        if load_in_4bit and load_in_8bit:
            raise ValueError('load_in_4bit and load_in_8bit are both True, but only one can be used at the same time')
        self._load_in_8bit = load_in_8bit
        self._load_in_4bit = load_in_4bit
        self.llm_int8_threshold = llm_int8_threshold
        self.llm_int8_skip_modules = llm_int8_skip_modules
        self.llm_int8_enable_fp32_cpu_offload = llm_int8_enable_fp32_cpu_offload
        self.llm_int8_has_fp16_weight = llm_int8_has_fp16_weight
        self.bnb_4bit_quant_type = bnb_4bit_quant_type
        self.bnb_4bit_use_double_quant = bnb_4bit_use_double_quant
        if bnb_4bit_compute_dtype is None:
            self.bnb_4bit_compute_dtype = torch.float32
        elif isinstance(bnb_4bit_compute_dtype, str):
            self.bnb_4bit_compute_dtype = getattr(torch, bnb_4bit_compute_dtype)
        elif isinstance(bnb_4bit_compute_dtype, torch.dtype):
            self.bnb_4bit_compute_dtype = bnb_4bit_compute_dtype
        else:
            raise ValueError('bnb_4bit_compute_dtype must be a string or a torch.dtype')
        if bnb_4bit_quant_storage is None:
            self.bnb_4bit_quant_storage = torch.uint8
        elif isinstance(bnb_4bit_quant_storage, str):
            if bnb_4bit_quant_storage not in ['float16', 'float32', 'int8', 'uint8', 'float64', 'bfloat16']:
                raise ValueError("`bnb_4bit_quant_storage` must be a valid string (one of 'float16', 'float32', 'int8', 'uint8', 'float64', 'bfloat16') ")
            self.bnb_4bit_quant_storage = getattr(torch, bnb_4bit_quant_storage)
        elif isinstance(bnb_4bit_quant_storage, torch.dtype):
            self.bnb_4bit_quant_storage = bnb_4bit_quant_storage
        else:
            raise ValueError('bnb_4bit_quant_storage must be a string or a torch.dtype')
        if kwargs and (not all((k in self._exclude_attributes_at_init for k in kwargs))):
            logger.warning(f'Unused kwargs: {list(kwargs.keys())}. These kwargs are not used in {self.__class__}.')
        self.post_init()

    @property
    def load_in_4bit(self):
        return self._load_in_4bit

    @load_in_4bit.setter
    def load_in_4bit(self, value: bool):
        if not isinstance(value, bool):
            raise TypeError('load_in_4bit must be a boolean')
        if self.load_in_8bit and value:
            raise ValueError('load_in_4bit and load_in_8bit are both True, but only one can be used at the same time')
        self._load_in_4bit = value

    @property
    def load_in_8bit(self):
        return self._load_in_8bit

    @load_in_8bit.setter
    def load_in_8bit(self, value: bool):
        if not isinstance(value, bool):
            raise TypeError('load_in_8bit must be a boolean')
        if self.load_in_4bit and value:
            raise ValueError('load_in_4bit and load_in_8bit are both True, but only one can be used at the same time')
        self._load_in_8bit = value

    def post_init(self):
        if not isinstance(self.load_in_4bit, bool):
            raise TypeError('load_in_4bit must be a boolean')
        if not isinstance(self.load_in_8bit, bool):
            raise TypeError('load_in_8bit must be a boolean')
        if not isinstance(self.llm_int8_threshold, float):
            raise TypeError('llm_int8_threshold must be a float')
        if self.llm_int8_skip_modules is not None and (not isinstance(self.llm_int8_skip_modules, list)):
            raise TypeError('llm_int8_skip_modules must be a list of strings')
        if not isinstance(self.llm_int8_enable_fp32_cpu_offload, bool):
            raise TypeError('llm_int8_enable_fp32_cpu_offload must be a boolean')
        if not isinstance(self.llm_int8_has_fp16_weight, bool):
            raise TypeError('llm_int8_has_fp16_weight must be a boolean')
        if self.bnb_4bit_compute_dtype is not None and (not isinstance(self.bnb_4bit_compute_dtype, torch.dtype)):
            raise TypeError('bnb_4bit_compute_dtype must be torch.dtype')
        if not isinstance(self.bnb_4bit_quant_type, str):
            raise TypeError('bnb_4bit_quant_type must be a string')
        if not isinstance(self.bnb_4bit_use_double_quant, bool):
            raise TypeError('bnb_4bit_use_double_quant must be a boolean')
        if self.load_in_4bit and (not version.parse(importlib.metadata.version('bitsandbytes')) >= version.parse('0.39.0')):
            raise ValueError('4 bit quantization requires bitsandbytes>=0.39.0 - please upgrade your bitsandbytes version')

    def is_quantizable(self):
        return self.load_in_8bit or self.load_in_4bit

    def quantization_method(self):
        if self.load_in_8bit:
            return 'llm_int8'
        elif self.load_in_4bit and self.bnb_4bit_quant_type == 'fp4':
            return 'fp4'
        elif self.load_in_4bit and self.bnb_4bit_quant_type == 'nf4':
            return 'nf4'
        else:
            return None

    def to_dict(self) -> dict[str, Any]:
        output = copy.deepcopy(self.__dict__)
        output['bnb_4bit_compute_dtype'] = str(output['bnb_4bit_compute_dtype']).split('.')[1]
        output['bnb_4bit_quant_storage'] = str(output['bnb_4bit_quant_storage']).split('.')[1]
        output['load_in_4bit'] = self.load_in_4bit
        output['load_in_8bit'] = self.load_in_8bit
        return output

    def __repr__(self):
        config_dict = self.to_dict()
        return f'{self.__class__.__name__} {json.dumps(config_dict, indent=2, sort_keys=True)}\n'

    def to_diff_dict(self) -> dict[str, Any]:
        config_dict = self.to_dict()
        default_config_dict = BitsAndBytesConfig().to_dict()
        serializable_config_dict = {}
        for key, value in config_dict.items():
            if value != default_config_dict[key]:
                serializable_config_dict[key] = value
        return serializable_config_dict

# --- helper: diffusers.quantizers.quantization_config.QuantizationConfigMixin ---
@dataclass
class QuantizationConfigMixin:
    quant_method: QuantizationMethod
    _exclude_attributes_at_init = []

    @classmethod
    def from_dict(cls, config_dict, return_unused_kwargs=False, **kwargs):
        config = cls(**config_dict)
        to_remove = []
        for key, value in kwargs.items():
            if hasattr(config, key):
                setattr(config, key, value)
                to_remove.append(key)
        for key in to_remove:
            kwargs.pop(key, None)
        if return_unused_kwargs:
            return (config, kwargs)
        else:
            return config

    def to_json_file(self, json_file_path: str | os.PathLike):
        with open(json_file_path, 'w', encoding='utf-8') as writer:
            config_dict = self.to_dict()
            json_string = json.dumps(config_dict, indent=2, sort_keys=True) + '\n'
            writer.write(json_string)

    def to_dict(self) -> dict[str, Any]:
        return copy.deepcopy(self.__dict__)

    def __iter__(self):
        for attr, value in copy.deepcopy(self.__dict__).items():
            yield (attr, value)

    def __repr__(self):
        return f'{self.__class__.__name__} {self.to_json_string()}'

    def to_json_string(self, use_diff: bool=True) -> str:
        if use_diff is True:
            config_dict = self.to_diff_dict()
        else:
            config_dict = self.to_dict()
        return json.dumps(config_dict, indent=2, sort_keys=True) + '\n'

    def update(self, **kwargs):
        to_remove = []
        for key, value in kwargs.items():
            if hasattr(self, key):
                setattr(self, key, value)
                to_remove.append(key)
        unused_kwargs = {key: value for key, value in kwargs.items() if key not in to_remove}
        return unused_kwargs

