class QuantizationMethod(str, Enum):
    BITS_AND_BYTES = 'bitsandbytes'
    GGUF = 'gguf'
    TORCHAO = 'torchao'
    QUANTO = 'quanto'
    MODELOPT = 'modelopt'

def fuzzy_match_size(config_name: str) -> str | None:
    config_name = config_name.lower()
    str_match = re.search('(\\d)weight', config_name)
    if str_match:
        return str_match.group(1)
    return None

class GGUFQuantizer(DiffusersQuantizer):
    use_keep_in_fp32_modules = True

    def __init__(self, quantization_config, **kwargs):
        super().__init__(quantization_config, **kwargs)
        self.compute_dtype = quantization_config.compute_dtype
        self.pre_quantized = quantization_config.pre_quantized
        self.modules_to_not_convert = quantization_config.modules_to_not_convert or []
        if not isinstance(self.modules_to_not_convert, list):
            self.modules_to_not_convert = [self.modules_to_not_convert]

    def validate_environment(self, *args, **kwargs):
        if not is_accelerate_available() or is_accelerate_version('<', '0.26.0'):
            raise ImportError("Loading GGUF Parameters requires `accelerate` installed in your environment: `pip install 'accelerate>=0.26.0'`")
        if not is_gguf_available() or is_gguf_version('<', '0.10.0'):
            raise ImportError('To load GGUF format files you must have `gguf` installed in your environment: `pip install gguf>=0.10.0`')

    def adjust_max_memory(self, max_memory: dict[str, int | str]) -> dict[str, int | str]:
        max_memory = {key: val * 0.9 for key, val in max_memory.items()}
        return max_memory

    def adjust_target_dtype(self, target_dtype: 'torch.dtype') -> 'torch.dtype':
        if target_dtype != torch.uint8:
            logger.info(f'target_dtype {target_dtype} is replaced by `torch.uint8` for GGUF quantization')
        return torch.uint8

    def update_torch_dtype(self, torch_dtype: 'torch.dtype') -> 'torch.dtype':
        if torch_dtype is None:
            torch_dtype = self.compute_dtype
        return torch_dtype

    def check_quantized_param_shape(self, param_name, current_param, loaded_param):
        loaded_param_shape = loaded_param.shape
        current_param_shape = current_param.shape
        quant_type = loaded_param.quant_type
        block_size, type_size = GGML_QUANT_SIZES[quant_type]
        inferred_shape = _quant_shape_from_byte_shape(loaded_param_shape, type_size, block_size)
        if inferred_shape != current_param_shape:
            raise ValueError(f'{param_name} has an expected quantized shape of: {inferred_shape}, but received shape: {loaded_param_shape}')
        return True

    def check_if_quantized_param(self, model: 'ModelMixin', param_value: 'GGUFParameter' | 'torch.Tensor', param_name: str, state_dict: dict[str, Any], **kwargs) -> bool:
        if isinstance(param_value, GGUFParameter):
            return True
        return False

    def create_quantized_param(self, model: 'ModelMixin', param_value: 'GGUFParameter' | 'torch.Tensor', param_name: str, target_device: 'torch.device', state_dict: dict[str, Any] | None=None, unexpected_keys: list[str] | None=None, **kwargs):
        module, tensor_name = get_module_from_name(model, param_name)
        if tensor_name not in module._parameters and tensor_name not in module._buffers:
            raise ValueError(f'{module} does not have a parameter or a buffer named {tensor_name}.')
        if tensor_name in module._parameters:
            module._parameters[tensor_name] = param_value.to(target_device)
        if tensor_name in module._buffers:
            module._buffers[tensor_name] = param_value.to(target_device)

    def _process_model_before_weight_loading(self, model: 'ModelMixin', device_map, keep_in_fp32_modules: list[str]=[], **kwargs):
        state_dict = kwargs.get('state_dict', None)
        self.modules_to_not_convert.extend(keep_in_fp32_modules)
        self.modules_to_not_convert = [module for module in self.modules_to_not_convert if module is not None]
        _replace_with_gguf_linear(model, self.compute_dtype, state_dict, modules_to_not_convert=self.modules_to_not_convert)

    def _process_model_after_weight_loading(self, model: 'ModelMixin', **kwargs):
        return model

    @property
    def is_serializable(self):
        return False

    @property
    def is_trainable(self) -> bool:
        return False

    @property
    def is_compileable(self) -> bool:
        return True

    def _dequantize(self, model):
        is_model_on_cpu = model.device.type == 'cpu'
        if is_model_on_cpu:
            logger.info('Model was found to be on CPU (could happen as a result of `enable_model_cpu_offload()`). So, moving it to accelerator. After dequantization, will move the model back to CPU again to preserve the previous device.')
            device = torch.accelerator.current_accelerator() if hasattr(torch, 'accelerator') else torch.cuda.current_device()
            model.to(device)
        model = _dequantize_gguf_and_restore_linear(model, self.modules_to_not_convert)
        if is_model_on_cpu:
            model.to('cpu')
        return model

class EMAModel:

    def __init__(self, parameters: Iterable[torch.nn.Parameter], decay: float=0.9999, min_decay: float=0.0, update_after_step: int=0, use_ema_warmup: bool=False, inv_gamma: float | int=1.0, power: float | int=2 / 3, foreach: bool=False, model_cls: Any | None=None, model_config: dict[str, Any] | None=None, **kwargs):
        if isinstance(parameters, torch.nn.Module):
            deprecation_message = 'Passing a `torch.nn.Module` to `ExponentialMovingAverage` is deprecated. Please pass the parameters of the module instead.'
            deprecate('passing a `torch.nn.Module` to `ExponentialMovingAverage`', '1.0.0', deprecation_message, standard_warn=False)
            parameters = parameters.parameters()
            use_ema_warmup = True
        if kwargs.get('max_value', None) is not None:
            deprecation_message = 'The `max_value` argument is deprecated. Please use `decay` instead.'
            deprecate('max_value', '1.0.0', deprecation_message, standard_warn=False)
            decay = kwargs['max_value']
        if kwargs.get('min_value', None) is not None:
            deprecation_message = 'The `min_value` argument is deprecated. Please use `min_decay` instead.'
            deprecate('min_value', '1.0.0', deprecation_message, standard_warn=False)
            min_decay = kwargs['min_value']
        parameters = list(parameters)
        self.shadow_params = [p.clone().detach() for p in parameters]
        if kwargs.get('device', None) is not None:
            deprecation_message = 'The `device` argument is deprecated. Please use `to` instead.'
            deprecate('device', '1.0.0', deprecation_message, standard_warn=False)
            self.to(device=kwargs['device'])
        self.temp_stored_params = None
        self.decay = decay
        self.min_decay = min_decay
        self.update_after_step = update_after_step
        self.use_ema_warmup = use_ema_warmup
        self.inv_gamma = inv_gamma
        self.power = power
        self.optimization_step = 0
        self.cur_decay_value = None
        self.foreach = foreach
        self.model_cls = model_cls
        self.model_config = model_config

    @classmethod
    def from_pretrained(cls, path, model_cls, foreach=False) -> 'EMAModel':
        _, ema_kwargs = model_cls.from_config(path, return_unused_kwargs=True)
        model = model_cls.from_pretrained(path)
        ema_model = cls(model.parameters(), model_cls=model_cls, model_config=model.config, foreach=foreach)
        ema_model.load_state_dict(ema_kwargs)
        return ema_model

    def save_pretrained(self, path):
        if self.model_cls is None:
            raise ValueError('`save_pretrained` can only be used if `model_cls` was defined at __init__.')
        if self.model_config is None:
            raise ValueError('`save_pretrained` can only be used if `model_config` was defined at __init__.')
        model = self.model_cls.from_config(self.model_config)
        state_dict = self.state_dict()
        state_dict.pop('shadow_params', None)
        model.register_to_config(**state_dict)
        self.copy_to(model.parameters())
        model.save_pretrained(path)

    def get_decay(self, optimization_step: int) -> float:
        step = max(0, optimization_step - self.update_after_step - 1)
        if step <= 0:
            return 0.0
        if self.use_ema_warmup:
            cur_decay_value = 1 - (1 + step / self.inv_gamma) ** (-self.power)
        else:
            cur_decay_value = (1 + step) / (10 + step)
        cur_decay_value = min(cur_decay_value, self.decay)
        cur_decay_value = max(cur_decay_value, self.min_decay)
        return cur_decay_value

    @torch.no_grad()
    def step(self, parameters: Iterable[torch.nn.Parameter]):
        if isinstance(parameters, torch.nn.Module):
            deprecation_message = 'Passing a `torch.nn.Module` to `ExponentialMovingAverage.step` is deprecated. Please pass the parameters of the module instead.'
            deprecate('passing a `torch.nn.Module` to `ExponentialMovingAverage.step`', '1.0.0', deprecation_message, standard_warn=False)
            parameters = parameters.parameters()
        parameters = list(parameters)
        self.optimization_step += 1
        decay = self.get_decay(self.optimization_step)
        self.cur_decay_value = decay
        one_minus_decay = 1 - decay
        context_manager = contextlib.nullcontext()
        if self.foreach:
            if is_transformers_available() and transformers.integrations.deepspeed.is_deepspeed_zero3_enabled():
                context_manager = deepspeed.zero.GatheredParameters(parameters, modifier_rank=None)
            with context_manager:
                params_grad = [param for param in parameters if param.requires_grad]
                s_params_grad = [s_param for s_param, param in zip(self.shadow_params, parameters) if param.requires_grad]
                if len(params_grad) < len(parameters):
                    torch._foreach_copy_([s_param for s_param, param in zip(self.shadow_params, parameters) if not param.requires_grad], [param for param in parameters if not param.requires_grad], non_blocking=True)
                torch._foreach_sub_(s_params_grad, torch._foreach_sub(s_params_grad, params_grad), alpha=one_minus_decay)
        else:
            for s_param, param in zip(self.shadow_params, parameters):
                if is_transformers_available() and transformers.integrations.deepspeed.is_deepspeed_zero3_enabled():
                    context_manager = deepspeed.zero.GatheredParameters(param, modifier_rank=None)
                with context_manager:
                    if param.requires_grad:
                        s_param.sub_(one_minus_decay * (s_param - param))
                    else:
                        s_param.copy_(param)

    def copy_to(self, parameters: Iterable[torch.nn.Parameter]) -> None:
        parameters = list(parameters)
        if self.foreach:
            torch._foreach_copy_([param.data for param in parameters], [s_param.to(param.device).data for s_param, param in zip(self.shadow_params, parameters)])
        else:
            for s_param, param in zip(self.shadow_params, parameters):
                param.data.copy_(s_param.to(param.device).data)

    def pin_memory(self) -> None:
        self.shadow_params = [p.pin_memory() for p in self.shadow_params]

    def to(self, device=None, dtype=None, non_blocking=False) -> None:
        self.shadow_params = [p.to(device=device, dtype=dtype, non_blocking=non_blocking) if p.is_floating_point() else p.to(device=device, non_blocking=non_blocking) for p in self.shadow_params]

    def state_dict(self) -> dict:
        return {'decay': self.decay, 'min_decay': self.min_decay, 'optimization_step': self.optimization_step, 'update_after_step': self.update_after_step, 'use_ema_warmup': self.use_ema_warmup, 'inv_gamma': self.inv_gamma, 'power': self.power, 'shadow_params': self.shadow_params}

    def store(self, parameters: Iterable[torch.nn.Parameter]) -> None:
        self.temp_stored_params = [param.detach().cpu().clone() for param in parameters]

    def restore(self, parameters: Iterable[torch.nn.Parameter]) -> None:
        if self.temp_stored_params is None:
            raise RuntimeError('This ExponentialMovingAverage has no `store()`ed weights to `restore()`')
        if self.foreach:
            torch._foreach_copy_([param.data for param in parameters], [c_param.data for c_param in self.temp_stored_params])
        else:
            for c_param, param in zip(self.temp_stored_params, parameters):
                param.data.copy_(c_param.data)
        self.temp_stored_params = None

    def load_state_dict(self, state_dict: dict) -> None:
        state_dict = copy.deepcopy(state_dict)
        self.decay = state_dict.get('decay', self.decay)
        if self.decay < 0.0 or self.decay > 1.0:
            raise ValueError('Decay must be between 0 and 1')
        self.min_decay = state_dict.get('min_decay', self.min_decay)
        if not isinstance(self.min_decay, float):
            raise ValueError('Invalid min_decay')
        self.optimization_step = state_dict.get('optimization_step', self.optimization_step)
        if not isinstance(self.optimization_step, int):
            raise ValueError('Invalid optimization_step')
        self.update_after_step = state_dict.get('update_after_step', self.update_after_step)
        if not isinstance(self.update_after_step, int):
            raise ValueError('Invalid update_after_step')
        self.use_ema_warmup = state_dict.get('use_ema_warmup', self.use_ema_warmup)
        if not isinstance(self.use_ema_warmup, bool):
            raise ValueError('Invalid use_ema_warmup')
        self.inv_gamma = state_dict.get('inv_gamma', self.inv_gamma)
        if not isinstance(self.inv_gamma, (float, int)):
            raise ValueError('Invalid inv_gamma')
        self.power = state_dict.get('power', self.power)
        if not isinstance(self.power, (float, int)):
            raise ValueError('Invalid power')
        shadow_params = state_dict.get('shadow_params', None)
        if shadow_params is not None:
            self.shadow_params = shadow_params
            if not isinstance(self.shadow_params, list):
                raise ValueError('shadow_params must be a list')
            if not all((isinstance(p, torch.Tensor) for p in self.shadow_params)):
                raise ValueError('shadow_params must all be Tensors')

