import torch
from diffusers.training_utils import cast_training_params

# Create a model where only some parameters require gradients
class PartialFreezeModel(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.trainable = torch.nn.Linear(5, 5)
        self.frozen = torch.nn.Linear(5, 5)
        # freeze the second layer
        for p in self.frozen.parameters():
            p.requires_grad = False

    def forward(self, x):
        return self.frozen(self.trainable(x))

model = PartialFreezeModel()

# Check requires_grad and dtype before
for name, p in model.named_parameters():
    print(name, 'requires_grad=', p.requires_grad, 'dtype=', p.dtype)

# Cast only the training parameters (those with requires_grad=True) to float16
cast_training_params(model, dtype=torch.float16)

# Verify that only trainable params were cast
