def cast_training_params(model: torch.nn.Module | list[torch.nn.Module], dtype=torch.float32):
    if not isinstance(model, list):
        model = [model]
    for m in model:
        for param in m.parameters():
            if param.requires_grad:
                param.data = param.to(dtype)

def compute_confidence_aware_loss(logits: torch.Tensor, labels: torch.Tensor, *, lambda_conf: float=0.0, temperature: float=1.0, per_token_weights: torch.Tensor | None=None, ignore_index: int=-100) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    if logits.ndim < 2:
        raise ValueError(f'`logits` must have at least 2 dims, got shape {tuple(logits.shape)}.')
    if labels.shape != logits.shape[:-1]:
        raise ValueError(f'`labels` shape must match `logits.shape[:-1]`, got labels={tuple(labels.shape)} logits={tuple(logits.shape)}.')
    if temperature <= 0:
        raise ValueError(f'`temperature` must be > 0, got {temperature}.')
    valid = labels.ne(ignore_index)
    if per_token_weights is None:
        weights = torch.ones_like(labels, dtype=logits.dtype)
    else:
        if per_token_weights.shape != labels.shape:
            raise ValueError(f'`per_token_weights` shape must match `labels` shape, got {tuple(per_token_weights.shape)} != {tuple(labels.shape)}.')
        weights = per_token_weights.to(dtype=logits.dtype)
    vocab_size = logits.shape[-1]
    per_token_nll = F.cross_entropy(logits.reshape(-1, vocab_size), labels.reshape(-1), reduction='none', ignore_index=ignore_index).reshape_as(labels)
    denom_sft = (weights * valid.to(weights.dtype)).sum().clamp_min(1)
    loss_sft = (per_token_nll * weights * valid.to(per_token_nll.dtype)).sum() / denom_sft
    if lambda_conf == 0.0:
        loss_conf = torch.zeros((), device=logits.device, dtype=loss_sft.dtype)
        return (loss_sft, loss_sft, loss_conf)
    with torch.no_grad():
        pred = logits.argmax(dim=-1)
        correct = valid & pred.eq(labels)
    scaled_logits = logits.float()
    if temperature != 1.0:
        scaled_logits = scaled_logits / float(temperature)
    probs = torch.softmax(scaled_logits, dim=-1)
    eps = torch.finfo(probs.dtype).tiny
    log_probs = torch.log(probs.clamp_min(eps))
    entropy = -(probs * log_probs).sum(dim=-1).to(dtype=logits.dtype)
    denom_conf = (weights * correct.to(weights.dtype)).sum().clamp_min(1)
    loss_conf = (entropy * weights * correct.to(entropy.dtype)).sum() / denom_conf
    loss = loss_sft + float(lambda_conf) * loss_conf
    return (loss, loss_sft, loss_conf)

def find_nearest_bucket(h, w, bucket_options):
    min_metric = float('inf')
    best_bucket_idx = None
    for bucket_idx, (bucket_h, bucket_w) in enumerate(bucket_options):
        metric = abs(h * bucket_w - w * bucket_h)
        if metric <= min_metric:
            min_metric = metric
            best_bucket_idx = bucket_idx
    return best_bucket_idx

def compute_density_for_timestep_sampling(weighting_scheme: str, batch_size: int, logit_mean: float=None, logit_std: float=None, mode_scale: float=None, device: torch.device | str='cpu', generator: torch.Generator | None=None):
    if weighting_scheme == 'logit_normal':
        u = torch.normal(mean=logit_mean, std=logit_std, size=(batch_size,), device=device, generator=generator)
        u = torch.nn.functional.sigmoid(u)
    elif weighting_scheme == 'mode':
        u = torch.rand(size=(batch_size,), device=device, generator=generator)
        u = 1 - u - mode_scale * (torch.cos(math.pi * u / 2) ** 2 - 1 + u)
    else:
        u = torch.rand(size=(batch_size,), device=device, generator=generator)
    return u

def compute_loss_weighting_for_sd3(weighting_scheme: str, sigmas=None):
    if weighting_scheme == 'sigma_sqrt':
        weighting = (sigmas ** (-2.0)).float()
    elif weighting_scheme == 'cosmap':
        bot = 1 - 2 * sigmas + 2 * sigmas ** 2
        weighting = 2 / (math.pi * bot)
    else:
        weighting = torch.ones_like(sigmas)
    return weighting

def free_memory():
    gc.collect()
    if torch.cuda.is_available():
        torch.cuda.empty_cache()
    elif torch.backends.mps.is_available():
        torch.mps.empty_cache()
    elif is_torch_npu_available():
        torch_npu.npu.empty_cache()
    elif hasattr(torch, 'xpu') and torch.xpu.is_available():
        torch.xpu.empty_cache()

def get_class_in_module(class_name, module_path, force_reload=False):
    name = os.path.normpath(module_path)
    if name.endswith('.py'):
        name = name[:-3]
    name = name.replace(os.path.sep, '.')
    module_file: Path = Path(HF_MODULES_CACHE) / module_path
    with _HF_REMOTE_CODE_LOCK:
        if force_reload:
            sys.modules.pop(name, None)
            importlib.invalidate_caches()
        cached_module: ModuleType | None = sys.modules.get(name)
        module_spec = importlib.util.spec_from_file_location(name, location=module_file)
        module: ModuleType
        if cached_module is None:
            module = importlib.util.module_from_spec(module_spec)
            sys.modules[name] = module
        else:
            module = cached_module
        module_spec.loader.exec_module(module)
    if class_name is None:
        return find_pipeline_class(module)
    return getattr(module, class_name)

# --- helper: diffusers.utils.dynamic_modules_utils.find_pipeline_class ---
def find_pipeline_class(loaded_module):
    from ..pipelines import DiffusionPipeline
    cls_members = dict(inspect.getmembers(loaded_module, inspect.isclass))
    pipeline_class = None
    for cls_name, cls in cls_members.items():
        if cls_name != DiffusionPipeline.__name__ and issubclass(cls, DiffusionPipeline) and (cls.__module__.split('.')[0] != 'diffusers'):
            if pipeline_class is not None:
                raise ValueError(f'Multiple classes that inherit from {DiffusionPipeline.__name__} have been found: {pipeline_class.__name__}, and {cls_name}. Please make sure to define only one in {loaded_module}.')
            pipeline_class = cls
    return pipeline_class

def get_fsdp_kwargs_from_accelerator(accelerator) -> dict:
    kwargs = {}
    fsdp_state = getattr(accelerator.state, 'fsdp_plugin', None)
    if fsdp_state is None:
        raise ValueError("Accelerate isn't configured to handle FSDP. Please update your installation.")
    fsdp_plugin = accelerator.state.fsdp_plugin
    if fsdp_plugin is None:
        kwargs['sharding_strategy'] = ShardingStrategy.FULL_SHARD
    else:
        kwargs['sharding_strategy'] = fsdp_plugin.sharding_strategy or ShardingStrategy.FULL_SHARD
    return kwargs

def parse_buckets_string(buckets_str):
    if not buckets_str:
        raise ValueError('Bucket string cannot be empty.')
    bucket_pairs = buckets_str.strip().split(';')
    parsed_buckets = []
    for pair_str in bucket_pairs:
        match = re.match('^\\s*(\\d+)\\s*,\\s*(\\d+)\\s*$', pair_str)
        if not match:
            raise ValueError(f"Invalid bucket format: '{pair_str}'. Expected 'height,width'.")
        try:
            height = int(match.group(1))
            width = int(match.group(2))
            if height <= 0 or width <= 0:
                raise ValueError('Bucket dimensions must be positive integers.')
            if height % 8 != 0 or width % 8 != 0:
                warnings.warn(f'Bucket dimension ({height},{width}) not divisible by 8. This might cause issues.')
            parsed_buckets.append((height, width))
        except ValueError as e:
            raise ValueError(f"Invalid integer in bucket pair '{pair_str}': {e}") from e
    if not parsed_buckets:
        raise ValueError('No valid buckets found in the provided string.')
    return parsed_buckets

def resolve_interpolation_mode(interpolation_type: str):
    if not is_torchvision_available():
        raise ImportError('Please make sure to install `torchvision` to be able to use the `resolve_interpolation_mode()` function.')
    if interpolation_type == 'bilinear':
        interpolation_mode = transforms.InterpolationMode.BILINEAR
    elif interpolation_type == 'bicubic':
        interpolation_mode = transforms.InterpolationMode.BICUBIC
    elif interpolation_type == 'box':
        interpolation_mode = transforms.InterpolationMode.BOX
    elif interpolation_type == 'nearest':
        interpolation_mode = transforms.InterpolationMode.NEAREST
    elif interpolation_type == 'nearest_exact':
        interpolation_mode = transforms.InterpolationMode.NEAREST_EXACT
    elif interpolation_type == 'hamming':
        interpolation_mode = transforms.InterpolationMode.HAMMING
    elif interpolation_type == 'lanczos':
        interpolation_mode = transforms.InterpolationMode.LANCZOS
    else:
        raise ValueError(f'The given interpolation mode {interpolation_type} is not supported. Currently supported interpolation modes are `bilinear`, `bicubic`, `box`, `nearest`, `nearest_exact`, `hamming`, and `lanczos`.')
    return interpolation_mode

def populate_model_card(model_card: ModelCard, tags: str | list[str] | None=None) -> ModelCard:
    if model_card.data.library_name is None:
        model_card.data.library_name = 'diffusers'
    if tags is not None:
        if isinstance(tags, str):
            tags = [tags]
        if model_card.data.tags is None:
            model_card.data.tags = []
        for tag in tags:
            model_card.data.tags.append(tag)
    return model_card

def remote_encode(endpoint: str, image: 'torch.Tensor' | Image.Image, scaling_factor: float | None=None, shift_factor: float | None=None) -> 'torch.Tensor':
    check_inputs_encode(endpoint, image, scaling_factor, shift_factor)
    kwargs = prepare_encode(image=image, scaling_factor=scaling_factor, shift_factor=shift_factor)
    response = requests.post(endpoint, **kwargs)
    if not response.ok:
        raise RuntimeError(response.json())
    output = postprocess_encode(response=response)
    return output

