def postprocess_encode(response: requests.Response):
    output_tensor = response.content
    parameters = response.headers
    shape = json.loads(parameters['shape'])
    dtype = parameters['dtype']
    torch_dtype = DTYPE_MAP[dtype]
    output_tensor = torch.frombuffer(bytearray(output_tensor), dtype=torch_dtype).reshape(shape)
    return output_tensor

# --- helper: diffusers.utils.remote_utils.prepare_encode ---
def prepare_encode(image: 'torch.Tensor' | Image.Image, scaling_factor: float | None=None, shift_factor: float | None=None):
    headers = {}
    parameters = {}
    if scaling_factor is not None:
        parameters['scaling_factor'] = scaling_factor
    if shift_factor is not None:
        parameters['shift_factor'] = shift_factor
    if isinstance(image, torch.Tensor):
        data = safetensors.torch._tobytes(image.contiguous(), 'tensor')
        parameters['shape'] = list(image.shape)
        parameters['dtype'] = str(image.dtype).split('.')[-1]
    else:
        buffer = io.BytesIO()
        image.save(buffer, format='PNG')
        data = buffer.getvalue()
    return {'data': data, 'params': parameters, 'headers': headers}

def wrap_with_fsdp(model: torch.nn.Module, device: str | torch.device, offload: bool=True, use_orig_params: bool=True, limit_all_gathers: bool=True, fsdp_kwargs: dict[str, Any] | None=None, transformer_layer_cls: set[type[torch.nn.Module]] | None=None) -> FSDP:
    logger = get_logger(__name__)
    if transformer_layer_cls is None:
        transformer_layer_cls = type(model.model.language_model.layers[0])
        logger.info(f'transformer_layer_cls is not provided, auto-inferred as {transformer_layer_cls.__name__}')
    auto_wrap_policy = partial(transformer_auto_wrap_policy, transformer_layer_cls={transformer_layer_cls})
    config = {'device_id': device, 'cpu_offload': CPUOffload(offload_params=offload) if offload else None, 'use_orig_params': use_orig_params, 'limit_all_gathers': limit_all_gathers, 'auto_wrap_policy': auto_wrap_policy}
    if fsdp_kwargs:
        config.update(fsdp_kwargs)
    fsdp_model = FSDP(model, **config)
    return fsdp_model

def unwrap_module(module):
    return module._orig_mod if is_compiled_module(module) else module

# --- helper: diffusers.utils.torch_utils.is_compiled_module ---
def is_compiled_module(module) -> bool:
    if is_torch_version('<', '2.0.0') or not hasattr(torch, '_dynamo'):
        return False
    return isinstance(module, torch._dynamo.eval_frame.OptimizedModule)

