class FunctionEvent(FormattedTimesMixin):

    def __init__(self, id, name, thread, start_us, end_us, overload_name=None, fwd_thread=None, input_shapes=None, stack=None, scope=0, use_device=None, cpu_memory_usage=0, device_memory_usage=0, is_async=False, is_remote=False, sequence_nr=-1, node_id=-1, device_type=DeviceType.CPU, device_index=0, device_resource_id=None, is_legacy=False, flops=None, trace_name=None, concrete_inputs=None, kwinputs=None, is_user_annotation=False, metadata_json=None):
        self.id: int = id
        self.node_id: int = node_id
        self.name: str = name
        self.overload_name: str = overload_name
        self.trace_name: str = trace_name
        self.time_range: Interval = Interval(start_us, end_us)
        self.thread: int = thread
        self.fwd_thread: Optional[int] = fwd_thread
        self.kernels: list[Kernel] = []
        self.count: int = 1
        self.cpu_children: list[FunctionEvent] = []
        self.cpu_parent: Optional[FunctionEvent] = None
        self.input_shapes: tuple[int, ...] = input_shapes
        self.concrete_inputs: list[Any] = concrete_inputs
        self.kwinputs: dict[str, Any] = kwinputs
        self.stack: list = stack
        self.scope: int = scope
        self.use_device: Optional[str] = use_device
        self.cpu_memory_usage: int = cpu_memory_usage
        self.device_memory_usage: int = device_memory_usage
        self.is_async: bool = is_async
        self.is_remote: bool = is_remote
        self.sequence_nr: int = sequence_nr
        self.device_type: DeviceType = device_type
        self.device_index: int = device_index
        self.device_resource_id: int = thread if device_resource_id is None else device_resource_id
        self.is_legacy: bool = is_legacy
        self.flops: Optional[int] = flops
        self.is_user_annotation: Optional[bool] = is_user_annotation
        self.self_cpu_percent = -1
        self.total_cpu_percent = -1
        self.total_device_percent = -1
        self.metadata_json = metadata_json

    def append_kernel(self, name, device, duration):
        if self.device_type != DeviceType.CPU:
            raise AssertionError('Expected device_type to be CPU')
        self.kernels.append(Kernel(name, device, duration))

    def append_cpu_child(self, child):
        if self.device_type != DeviceType.CPU:
            raise AssertionError('Expected device_type to be CPU')
        if not isinstance(child, FunctionEvent):
            raise AssertionError('Expected child to be a FunctionEvent')
        if child.device_type != DeviceType.CPU:
            raise AssertionError('Expected child device_type to be CPU')
        self.cpu_children.append(child)

    def set_cpu_parent(self, parent):
        if self.device_type != DeviceType.CPU:
            raise AssertionError('Expected device_type to be CPU')
        if not isinstance(parent, FunctionEvent):
            raise AssertionError('Expected parent to be a FunctionEvent')
        if parent.device_type != DeviceType.CPU:
            raise AssertionError('Expected parent device_type to be CPU')
        self.cpu_parent = parent

    @property
    def self_cpu_memory_usage(self):
        if self.is_async or self.device_type != DeviceType.CPU:
            return 0
        return self.cpu_memory_usage - sum((child.cpu_memory_usage for child in self.cpu_children))

    @property
    def self_device_memory_usage(self):
        if self.is_async or self.device_type != DeviceType.CPU:
            return 0
        return self.device_memory_usage - sum((child.device_memory_usage for child in self.cpu_children))

    @property
    @deprecated('`self_cuda_memory_usage` is deprecated. Use `self_device_memory_usage` instead.', category=FutureWarning)
    def self_cuda_memory_usage(self):
        return self.self_device_memory_usage

    @property
    def cpu_time_total(self):
        if self.device_type == DeviceType.CPU:
            return self.time_range.elapsed_us()
        else:
            return 0

    @property
    def self_cpu_time_total(self):
        if self.is_async or self.device_type != DeviceType.CPU:
            return 0
        return self.cpu_time_total - sum((child.cpu_time_total for child in self.cpu_children))

    @property
    def device_time_total(self):
        if self.is_async or not self.use_device:
            return 0
        if self.device_type == DeviceType.CPU:
            if not self.is_legacy:
                return sum((kinfo.duration for kinfo in self.kernels)) + sum((ch.device_time_total for ch in self.cpu_children))
            else:
                return sum((kinfo.duration for kinfo in self.kernels))
        else:
            if self.device_type not in [DeviceType.CUDA, DeviceType.PrivateUse1, DeviceType.MTIA, DeviceType.HPU, DeviceType.XPU]:
                raise AssertionError(f'Expected device_type to be CUDA, PrivateUse1, MTIA, HPU or XPU, but got {self.device_type}')
            return self.time_range.elapsed_us()

    @property
    @deprecated('`cuda_time_total` is deprecated. Use `device_time_total` instead.', category=FutureWarning)
    def cuda_time_total(self):
        return self.device_time_total

    @property
    def self_device_time_total(self):
        if self.is_async or not self.use_device:
            return 0
        if self.device_type == DeviceType.CPU:
            return self.device_time_total - sum((child.device_time_total for child in self.cpu_children))
        else:
            if self.device_type not in [DeviceType.CUDA, DeviceType.PrivateUse1, DeviceType.MTIA, DeviceType.HPU, DeviceType.XPU]:
                raise AssertionError(f'Expected device_type to be CUDA, PrivateUse1, MTIA, HPU or XPU, but got {self.device_type}')
            return self.device_time_total

    @property
    @deprecated('`self_cuda_time_total` is deprecated. Use `self_device_time_total` instead.', category=FutureWarning)
    def self_cuda_time_total(self):
        return self.self_device_time_total

    @property
    def key(self):
        return self.name

    def __repr__(self):
        device_name = self.use_device
        device_time = self.device_time_str
        device_memory_usage = self.device_memory_usage
        return f'<FunctionEvent id={self.id} name={self.name} overload_name={self.overload_name} device_type={self.device_type} node_id={self.node_id} cpu_time={self.cpu_time_str} start_us={self.time_range.start} end_us={self.time_range.end} cpu_children={str([child.id for child in self.cpu_children])} {device_name}_time={device_time} name={self.name} thread={self.thread} input_shapes={str(self.input_shapes)} cpu_memory_usage={self.cpu_memory_usage} {device_name}_memory_usage={device_memory_usage} is_async={self.is_async} is_remote={self.is_remote} seq_nr={self.sequence_nr} is_legacy={self.is_legacy}>'

# --- helper: torch.autograd.profiler_util.FormattedTimesMixin ---
class FormattedTimesMixin:
    cpu_time_str = _attr_formatter('cpu_time')
    device_time_str = _attr_formatter('device_time')
    cpu_time_total_str = _attr_formatter('cpu_time_total')
    device_time_total_str = _attr_formatter('device_time_total')
    self_cpu_time_total_str = _attr_formatter('self_cpu_time_total')
    self_device_time_total_str = _attr_formatter('self_device_time_total')

    @property
    def cpu_time(self):
        return 0.0 if self.count == 0 else 1.0 * self.cpu_time_total / self.count

    @property
    def device_time(self):
        return 0.0 if self.count == 0 else 1.0 * self.device_time_total / self.count

    @property
    @deprecated('`cuda_time` is deprecated, please use `device_time` instead.', category=FutureWarning)
    def cuda_time(self):
        return self.device_time

