def substitute_in_graph(original_fn: Callable[_P, _R], *, can_constant_fold_through: bool=False, skip_signature_check: bool=False) -> Callable[[Callable[_P, _R]], Callable[_P, _R]]:
    import torch._dynamo
    return torch._dynamo.substitute_in_graph(original_fn, can_constant_fold_through=can_constant_fold_through, skip_signature_check=skip_signature_check)

