# --- helper: torch.cuda._lazy_init ---
def _lazy_init():
    global _initialized, _queued_calls
    if is_initialized() or hasattr(_tls, 'is_initializing'):
        return
    with _initialization_lock:
        if is_initialized():
            return
        if _is_in_bad_fork():
            raise RuntimeError("Cannot re-initialize CUDA in forked subprocess. To use CUDA with multiprocessing, you must use the 'spawn' start method")
        if not hasattr(torch._C, '_cuda_getDeviceCount'):
            raise AssertionError('Torch not compiled with CUDA enabled')
        if _cudart is None:
            raise AssertionError('libcudart functions unavailable. It looks like you have a broken build?')
        torch._C._cuda_init()
        _tls.is_initializing = True
        _queued_calls.extend((calls for calls in _lazy_seed_tracker.get_calls() if calls))
        try:
            for queued_call, orig_traceback in _queued_calls:
                try:
                    queued_call()
                except Exception as e:
                    msg = f"CUDA call failed lazily at initialization with error: {str(e)}\n\nCUDA call was originally invoked at:\n\n{''.join(orig_traceback)}"
                    raise DeferredCudaCallError(msg) from e
        finally:
            delattr(_tls, 'is_initializing')
        _initialized = True

