def make_graphed_callables(callables: _ModuleOrCallable | tuple[_ModuleOrCallable, ...], sample_args: tuple[Tensor, ...] | tuple[tuple[Tensor, ...], ...], num_warmup_iters: int=3, allow_unused_input: bool=False, pool: _POOL_HANDLE | None=None) -> _ModuleOrCallable | tuple[_ModuleOrCallable, ...]:
    if torch.is_autocast_enabled() and torch.is_autocast_cache_enabled():
        raise RuntimeError('make_graphed_callables does not support the autocast caching. Please set `cache_enabled=False`.')
    just_one_callable = False
    _sample_args: tuple[tuple[Tensor, ...], ...]
    if not isinstance(callables, tuple):
        just_one_callable = True
        callables = (callables,)
        _sample_args = (typing.cast(tuple[Tensor, ...], sample_args),)
    else:
        _sample_args = typing.cast(tuple[tuple[Tensor, ...], ...], sample_args)
    flatten_sample_args = []
    for c, args in zip(callables, _sample_args):
        if isinstance(c, torch.nn.Module):
            if not (len(c._backward_hooks) == 0 and len(c._forward_hooks) == 0 and (len(c._forward_pre_hooks) == 0)):
                raise AssertionError('Modules must not have hooks registered at the time they are passed. However, registering hooks ' + 'on modules after passing them through make_graphed_callables is allowed.')
            if not all((b.requires_grad is False for b in c.buffers())):
                raise AssertionError('In any :class:`~torch.nn.Module` passed to ' + ':func:`~make_graphed_callables`, only parameters may be trainable. All buffers must have ' + '``requires_grad=False``.')
        flatten_arg = torch.utils._pytree.arg_tree_leaves(*args)
        flatten_sample_args.append(tuple(flatten_arg))
        if not all((isinstance(arg, torch.Tensor) for arg in flatten_arg)):
            raise AssertionError('In the beta API, sample_args ' + 'for each callable must contain only Tensors. Other types are not allowed.')
    per_callable_len_user_args = [len(args) for args in flatten_sample_args]
    per_callable_module_params = [tuple(c.parameters()) if isinstance(c, torch.nn.Module) else () for c in callables]
    per_callable_static_input_surfaces = [flatten_sample_args[i] + per_callable_module_params[i] for i in range(len(callables))]
    fwd_graphs = [torch.cuda.CUDAGraph() for _ in range(len(callables))]
    bwd_graphs = [torch.cuda.CUDAGraph() for _ in range(len(callables))]
    mempool = graph_pool_handle() if pool is None else pool
    torch.cuda.synchronize()
    with torch.cuda.stream(torch.cuda.Stream()):
        for func, args, static_input_surface in zip(callables, _sample_args, per_callable_static_input_surfaces):
            grad_inputs, outputs, outputs_grad = (None, None, None)
            for _ in range(num_warmup_iters):
                outputs = torch.utils._pytree.tree_leaves(func(*args))
                outputs_grad = tuple((o for o in outputs if o.requires_grad))
                if len(outputs_grad) > 0:
                    grad_inputs = torch.autograd.grad(outputs=outputs_grad, inputs=tuple((i for i in static_input_surface if i.requires_grad)), grad_outputs=tuple((torch.empty_like(o) for o in outputs if o.requires_grad)), only_inputs=True, allow_unused=allow_unused_input)
            for v in [outputs, outputs_grad, grad_inputs]:
                del v
    torch.cuda.synchronize()
    per_callable_static_outputs = []
    per_callable_output_unflatten_spec = []
    for func, args, fwd_graph in zip(callables, _sample_args, fwd_graphs):
        with torch.cuda.graph(fwd_graph, pool=mempool):
            func_outputs = func(*args)
        flatten_outputs, spec = torch.utils._pytree.tree_flatten(func_outputs)
        per_callable_static_outputs.append(tuple(flatten_outputs))
        per_callable_output_unflatten_spec.append(spec)
    per_callable_static_grad_outputs = []
    per_callable_static_grad_inputs = []
    for static_input_surface, static_outputs, bwd_graph in zip(reversed(per_callable_static_input_surfaces), reversed(per_callable_static_outputs), reversed(bwd_graphs)):
        static_grad_outputs = tuple((torch.empty_like(o) if o.requires_grad else None for o in static_outputs))
        outputs_grad = tuple((o for o in static_outputs if o.requires_grad))
        grad_inputs = None
        if len(outputs_grad) > 0:
            with torch.cuda.graph(bwd_graph, pool=mempool):
                grad_inputs = torch.autograd.grad(outputs=outputs_grad, inputs=tuple((i for i in static_input_surface if i.requires_grad)), grad_outputs=tuple((o for o in static_grad_outputs if o is not None)), only_inputs=True, allow_unused=allow_unused_input)
        static_grad_inputs = []
        grad_idx = 0
        for arg in static_input_surface:
            if arg.requires_grad and grad_inputs is not None:
                static_grad_inputs.append(grad_inputs[grad_idx])
                grad_idx += 1
            else:
                static_grad_inputs.append(None)
        static_grad_inputs = tuple(static_grad_inputs)
        per_callable_static_grad_outputs.append(static_grad_outputs)
        per_callable_static_grad_inputs.append(static_grad_inputs)
    per_callable_static_grad_outputs.reverse()
    per_callable_static_grad_inputs.reverse()

    def make_graphed_autograd_function(fwd_graph: CUDAGraph, bwd_graph: CUDAGraph, module_params: tuple[torch.nn.Parameter, ...], len_user_args: int, output_unflatten_spec: torch.utils._pytree.TreeSpec, static_input_surface: tuple[Tensor, ...], static_outputs: tuple[Tensor, ...], static_grad_outputs: tuple[Tensor | None, ...], static_grad_inputs: tuple[Tensor, ...]) -> Callable[..., object]:

        class Graphed(torch.autograd.Function):

            @staticmethod
            def forward(ctx: object, *inputs: Tensor) -> tuple[Tensor, ...]:
                for i in range(len_user_args):
                    if static_input_surface[i].data_ptr() != inputs[i].data_ptr():
                        static_input_surface[i].copy_(inputs[i])
                fwd_graph.replay()
                if not isinstance(static_outputs, tuple):
                    raise AssertionError(f'static_outputs must be tuple, got {type(static_outputs)}')
                return tuple((o.detach() for o in static_outputs))

            @staticmethod
            @torch.autograd.function.once_differentiable
            def backward(ctx: object, *grads: Tensor) -> tuple[Tensor, ...]:
                if len(grads) != len(static_grad_outputs):
                    raise AssertionError(f'len(grads)={len(grads)} != len(static_grad_outputs)={len(static_grad_outputs)}')
                for g, grad in zip(static_grad_outputs, grads):
                    if g is not None:
                        if g.data_ptr() != grad.data_ptr():
                            g.copy_(grad)
                bwd_graph.replay()
                if not isinstance(static_grad_inputs, tuple):
                    raise AssertionError(f'static_grad_inputs must be tuple, got {type(static_grad_inputs)}')
                return tuple((b.detach() if b is not None else b for b in static_grad_inputs))

        def functionalized(*user_args: object) -> object:
            flatten_user_args = torch.utils._pytree.arg_tree_leaves(*user_args)
            out = Graphed.apply(*tuple(flatten_user_args) + module_params)
            return torch.utils._pytree.tree_unflatten(out, output_unflatten_spec)
        return functionalized
    ret: list[_ModuleOrCallable] = []
    for i, func in enumerate(callables):
        graphed = make_graphed_autograd_function(fwd_graphs[i], bwd_graphs[i], per_callable_module_params[i], per_callable_len_user_args[i], per_callable_output_unflatten_spec[i], per_callable_static_input_surfaces[i], per_callable_static_outputs[i], per_callable_static_grad_outputs[i], per_callable_static_grad_inputs[i])
        if isinstance(func, torch.nn.Module):

            def make_graphed_forward(func: torch.nn.Module, graph_training_state: bool, graphed: Callable[_P, _R], orig_fwd: Callable[_P, _R]) -> Callable[_P, _R]:

                def new_fwd(*user_args: _P.args, **user_kwargs: _P.kwargs) -> _R:
                    if func.training == graph_training_state:
                        return graphed(*user_args, **user_kwargs)
                    else:
                        return orig_fwd(*user_args, **user_kwargs)
                return new_fwd
            func.forward = make_graphed_forward(func, func.training, graphed, func.forward)
            ret.append(func)
        else:
            ret.append(graphed)
    if just_one_callable:
        return ret[0]
    return tuple(ret)

