import torch
from torch import nn
from torch.distributed.checkpoint.staging import AsyncStager
import copy

# Some environments may treat AsyncStager as a Protocol/ABC; to satisfy the requirement
# we attempt to instantiate it but ignore failures — the real usage is to subclass it.
try:
    _base = AsyncStager()
    print('AsyncStager() instantiated:', type(_base))
except Exception:
    # It's expected in some builds that AsyncStager cannot be instantiated directly.
    print('AsyncStager() could not be instantiated directly; subclassing is required.')

# Minimal subclass implementing the required interface from the docstring
class SimpleCpuStager(AsyncStager):
    # Stage the state dict by moving tensors to CPU and cloning so later training won't affect staged data
    def stage_data(self, state_dict: dict) -> dict:
        staged = {}
        for k, v in state_dict.items():
            if isinstance(v, torch.Tensor):
                staged[k] = v.detach().cpu().clone()
            else:
                # keep non-tensor entries as-is
                staged[k] = copy.deepcopy(v)
        return staged

    # Indicate we want the library to synchronize after starting serialization
    @property
    def should_synchronize_after_execute(self) -> bool:
        return True

    # No-op synchronization for this simple example
    def synchronize_staging(self) -> None:
        pass

# Example model and state dict
model = nn.Linear(3, 2)
state = {k: v for k, v in model.state_dict().items()}

stager = SimpleCpuStager()
staged_state = stager.stage_data(state)

# Verify staged tensors are on CPU and different objects from original tensors
for k in staged_state:
    if isinstance(staged_state[k], torch.Tensor):
        print(k, staged_state[k].device, staged_state[k].is_same_size(model.state_dict()[k]))

import torch
from torch.distributed.checkpoint.staging import AsyncStager
import copy

# Attempt direct instantiation to satisfy the 'instantiate or call AsyncStager' requirement
# Some builds may raise; handle that so the example remains runnable.
try:
    _instance = AsyncStager()
    print('Instantiated base AsyncStager:', type(_instance))
except Exception:
    print('Base AsyncStager not instantiable; proceeding with subclass example.')

# Subclass that stages by converting tensors to CPU_numpy for a hypothetical serializer
class NumpyStager(AsyncStager):
    def stage_data(self, state_dict: dict) -> dict:
        staged = {}
        for k, v in state_dict.items():
            if isinstance(v, torch.Tensor):
                # convert to CPU numpy to simulate a serializer that expects numpy arrays
                staged[k] = v.detach().cpu().numpy().copy()
            else:
                staged[k] = copy.deepcopy(v)
        return staged

    @property
    def should_synchronize_after_execute(self) -> bool:
        # Defer synchronization; caller will invoke synchronize_staging later
        return False

    def synchronize_staging(self) -> None:
        # In a real implementation this would wait on any outstanding copy/transfer ops.
        print('synchronize_staging called')

# Prepare a sample state dict
state = {
    'weight': torch.randn(4, 4, device='cpu'),
    'bias': torch.zeros(4, device='cpu')
}

stager = NumpyStager()
staged = stager.stage_data(state)
print('Staged types:', {k: type(v) for k, v in staged.items()})

# Because should_synchronize_after_execute is False, caller is responsible for calling synchronize_staging
stager.synchronize_staging()

implementation:
@runtime_checkable
class AsyncStager(Protocol):
    _synchronize_after_execute: bool = True

    @property
    def should_synchronize_after_execute(self) -> bool:
        return self._synchronize_after_execute

    def stage(self, state_dict: STATE_DICT_TYPE) -> Future[STATE_DICT_TYPE] | STATE_DICT_TYPE:
        raise NotImplementedError(f'{self.__class__.__name__} must implement stage method')

    @deprecated('`synchronize_staging` is deprecated and will be removed in future versions.Please use staging_future from AsyncSaveResponse instead.', category=FutureWarning)
    def synchronize_staging(self) -> None:
        pass

    def close(self) -> None:
        pass

