def start_debug_server(port: int=25999, worker_port: int=0, start_method: Literal['fork', 'spawn', 'forkserver'] | None=None, dump_dir: str | None=None, dump_interval: float=60.0, enabled_dumps: set[str] | None=None, handlers: list['DebugHandler'] | None=None) -> None:
    global _WORKER_SERVER, _DEBUG_SERVER_PROC
    assert _WORKER_SERVER is None, 'debug server already started'
    assert _DEBUG_SERVER_PROC is None, 'debug server already started'
    logger.info('Starting debug server on port %d', port)
    store = tcpstore_client()
    _WORKER_SERVER = _WorkerServer('::', worker_port)
    RANK = get_rank()
    store.set(f'rank{RANK}', f'http://{socket.gethostname()}:{_WORKER_SERVER.port}')
    if RANK == 0:
        from torch.distributed.debug._debug_handlers import default_handlers
        from torch.distributed.debug._frontend import main
        if handlers is None:
            handlers = default_handlers()
        if enabled_dumps is None:
            enabled_dumps = {'stacks', 'fr_trace'}
        main_kwargs = {'port': port, 'dump_dir': dump_dir, 'dump_interval': dump_interval, 'enabled_dumps': enabled_dumps, 'handlers': handlers}
        if start_method is not None:
            ctx = multiprocessing.get_context(start_method)
            _DEBUG_SERVER_PROC = ctx.Process(target=main, kwargs=main_kwargs, daemon=True)
        else:
            _DEBUG_SERVER_PROC = multiprocessing.Process(target=main, kwargs=main_kwargs, daemon=True)
        _DEBUG_SERVER_PROC.start()

def set_optimizer_state_dict(model: nn.Module, optimizers: torch.optim.Optimizer | Iterable[torch.optim.Optimizer], optim_state_dict: OptimizerStateType, *, options: StateDictOptions | None=None) -> None:
    with _gc_context():
        optimizers = (optimizers,) if isinstance(optimizers, torch.optim.Optimizer) else tuple(optimizers)
        info = _verify_options(model, optimizers, optim_only=True, options=options)
        _verify_state_dict({}, optim_state_dict, info)
        _load_optim_state_dict(model, optimizers, optim_state_dict, info)

# --- helper: torch.distributed.checkpoint.state_dict.StateDictOptions ---
@dataclass
class StateDictOptions:
    full_state_dict: bool = False
    cpu_offload: bool = False
    ignore_frozen_params: bool = False
    keep_submodule_prefixes: bool = True
    strict: bool = True
    broadcast_from_rank0: bool = False
    flatten_optimizer_state_dict: bool = False
    dsd_fqn_modifiers: str = '_fqn_modifiers'

# --- helper: torch.distributed.checkpoint.state_dict._gc_context ---
@contextlib.contextmanager
def _gc_context():
    is_enabled = gc.isenabled()
    gc.disable()
    try:
        yield
    finally:
        if is_enabled:
            gc.enable()

# --- helper: torch.distributed.checkpoint.state_dict._load_optim_state_dict ---
@torch.no_grad()
def _load_optim_state_dict(model: nn.Module, optimizers: tuple[torch.optim.Optimizer, ...], state_dict: OptimizerStateType, info: _StateDictInfo) -> None:
    if not info.handle_optim:
        return
    for optim in optimizers:
        _init_optim_state(optim)
        if state_dict:
            if _STATE in state_dict:
                optim_state_dict = _split_optim_state_dict(model, optim, state_dict, info)
            else:
                optim_state_dict = _unflatten_optim_state_dict(optim, cast(dict[str, ValueType], state_dict), info)
        else:
            optim_state_dict = {}
        if info.fsdp_modules:
            for original_fqn, _ in model.named_parameters():
                fqns = _get_fqns(model, original_fqn)
                fqns_with_compiler = _get_fqns(model, original_fqn, skip_compiler_prefix=False)
                if fqns == fqns_with_compiler:
                    continue
                if len(fqns) != 1:
                    raise AssertionError(f"Expected 1 FQN for '{original_fqn}', got {len(fqns)}")
                fqn = fqns.pop()
                fqn_with_compiler = fqns_with_compiler.pop()
                for g in optim_state_dict[_PG]:
                    val = cast(dict[str, Any], g)
                    params = [key.replace(fqn, fqn_with_compiler) for key in val[_PARAMS]]
                    val[_PARAMS] = params
                osd_state = cast(DictValueType, optim_state_dict[_STATE])
                for k in list(osd_state.keys()):
                    if fqn in k:
                        osd_state[k.replace(fqn, fqn_with_compiler)] = osd_state.pop(k)
            with info.fsdp_context():
                optim_state_dict = FSDP.optim_state_dict_to_load(model, optim, optim_state_dict)
        elif info.full_state_dict:
            info.full_state_dict = False
            local_state_dict = _get_optim_state_dict(model, (optim,), info)
            info.full_state_dict = True
            device = None

            def _device(t):
                if t.dim() > 0:
                    nonlocal device
                    if device is None:
                        device = t.device
                    elif device != t.device:
                        raise ValueError('Device mismatch')
                return t
            _ = tree_map_only(torch.Tensor, _device, local_state_dict)
            if device is None:
                raise AssertionError('Expected device to be set')
            flatten_osd, osd_mapping = _flatten_state_dict(optim_state_dict)
            flatten_local_osd, local_osd_mapping = _flatten_state_dict(local_state_dict)
            if info.broadcast_from_rank0:
                _broadcast_state_dict(flatten_osd, flatten_local_osd, device=device)
            else:
                _distribute_state_dict(flatten_osd, flatten_local_osd, device=device)
            for optim_key in flatten_osd:
                if optim_key not in flatten_local_osd:
                    if optim_key not in osd_mapping:
                        raise AssertionError(f"Expected key '{optim_key}' in osd_mapping")
                    flatten_local_osd[optim_key] = flatten_osd[optim_key]
                    local_osd_mapping[optim_key] = osd_mapping[optim_key]
            optim_state_dict = _unflatten_state_dict(flatten_local_osd, local_osd_mapping)
            for pg in optim_state_dict[_PG]:
                if _PARAMS not in pg:
                    cast(dict[str, ValueType], pg)[_PARAMS] = []
        _state_dict_fn(optim, 'load_state_dict')(state_dict=optim_state_dict)

# --- helper: torch.distributed.checkpoint.state_dict._verify_options ---
def _verify_options(model: nn.Module, optims: tuple[torch.optim.Optimizer, ...], optim_only: bool, *, submodules: set[nn.Module] | None=None, options: StateDictOptions | None=None) -> _StateDictInfo:
    if submodules:
        warnings.warn('Getting submodules only model/optim state_dict is deprecated and will be removed in 2.5. This feature can be achieved by manually filtering out the state_dict returned from get_state_dict.', FutureWarning, stacklevel=2)
    if optim_only and (not optims):
        raise RuntimeError('Optimizers are not passed in but optim_only is set to True.')
    options = options or StateDictOptions()
    fqn_param_mapping: dict[str | torch.Tensor, set[str] | torch.Tensor] = {}
    shared_params_mapping: dict[str | torch.Tensor, set[str] | torch.Tensor] = {}
    for name, param in _iterate_valid_model_state(model):
        if isinstance(param, _EXTRA_STATE):
            continue
        fqns = _get_fqns(model, name)
        fqn = fqn_param_mapping.get(param)
        if fqn is not None:
            cast(set[str], fqn_param_mapping[param]).update(fqns)
            shared_params_mapping[param] = fqn_param_mapping[param]
        else:
            fqn_param_mapping[param] = fqns.copy()
        for fqn in fqns:
            if not isinstance(param, _EXTRA_STATE):
                fqn_param_mapping[fqn] = param
    for param_, fqns_ in list(shared_params_mapping.items()):
        for fqn in fqns_:
            shared_params_mapping[fqn] = cast(torch.Tensor, param_)
    submodule_prefixes: set[str] = set()
    if submodules:
        submodules = set(submodules)
        for name, module in model.named_modules():
            if module not in submodules:
                continue
            fqns = _get_fqns(model, name)
            if len(fqns) != 1:
                raise AssertionError('Submodule FQN should only have 1 instance')
            submodule_prefixes.update((f'{fqn}.' for fqn in fqns))
    if options.broadcast_from_rank0 and (not options.full_state_dict):
        raise ValueError('full_state_dict must be True when broadcast_from_rank0 is True.')
    fsdp_modules = FSDP.fsdp_modules(model)
    state_dict_config: StateDictConfig
    optim_state_dict_config: OptimStateDictConfig
    fsdp_context: Callable
    if fsdp_modules:
        if options.full_state_dict:
            state_dict_config = FullStateDictConfig(offload_to_cpu=options.cpu_offload, rank0_only=options.cpu_offload)
            optim_state_dict_config = FullOptimStateDictConfig(offload_to_cpu=options.cpu_offload, rank0_only=options.cpu_offload or options.broadcast_from_rank0)
            state_dict_type = StateDictType.FULL_STATE_DICT
        else:
            state_dict_config = ShardedStateDictConfig(offload_to_cpu=options.cpu_offload)
            optim_state_dict_config = ShardedOptimStateDictConfig(offload_to_cpu=options.cpu_offload)
            state_dict_type = StateDictType.SHARDED_STATE_DICT

        @contextlib.contextmanager
        def fsdp_state_dict_type_without_warning(module, state_dict_type, state_dict_config, optim_state_dict_config):
            with warnings.catch_warnings():
                warnings.filterwarnings('ignore', message='FSDP.state_dict_type', category=FutureWarning)
                with FSDP.state_dict_type(module=module, state_dict_type=state_dict_type, state_dict_config=state_dict_config, optim_state_dict_config=optim_state_dict_config):
                    yield
        fsdp_context = functools.partial(fsdp_state_dict_type_without_warning, module=model, state_dict_type=state_dict_type, state_dict_config=state_dict_config, optim_state_dict_config=optim_state_dict_config)
    else:
        fsdp_context = contextlib.nullcontext
    return _StateDictInfo(**asdict(options), fqn_param_mapping=fqn_param_mapping, shared_params_mapping=shared_params_mapping, submodule_prefixes=submodule_prefixes, fsdp_context=fsdp_context, fsdp_modules=cast(list[nn.Module], fsdp_modules), handle_model=not optim_only, handle_optim=len(optims) > 0)

# --- helper: torch.distributed.checkpoint.state_dict._verify_state_dict ---
def _verify_state_dict(model_state_dict: dict[str, ValueType], optim_state_dict: OptimizerStateType, info: _StateDictInfo) -> None:
    for module in info.fsdp_modules:
        fsdp_state = _get_module_fsdp_state_if_fully_sharded_module(module)
        if fsdp_state is None:
            raise AssertionError('Expected a fsdp_state with a fsdp module.')
    if info.handle_model and (not model_state_dict) and (not info.submodule_prefixes) and (not info.ignore_frozen_params) and (not (info.cpu_offload and info.full_state_dict)) and info.strict and (not info.broadcast_from_rank0):
        raise RuntimeError(f'The option indicates that model state_dict is required to save or load, but model state_dict is empty.rank = dist.get_rank()={dist.get_rank()!r}.')
    if info.handle_optim:
        if not optim_state_dict and (not (info.cpu_offload and info.full_state_dict)) and (not info.broadcast_from_rank0):
            raise RuntimeError(f'The option indicates that model state_dict is required to save, or load but optim state_dict is empty. {optim_state_dict}')
    for key in model_state_dict:
        if _FLAT_PARAM in key:
            raise RuntimeError(f'{key} contains {_FLAT_PARAM}. This can happen if the model is not the root module.')

class PGTransport:

    def __init__(self, pg: ProcessGroup, timeout: timedelta, device: torch.device, state_dict: Callable[[], object] | None=None) -> None:
        self._work: list[Work] = []
        self._pg = pg
        self._timeout = timeout
        self._device = device
        self._state_dict = state_dict

    def send_checkpoint(self, dst_ranks: list[int], state_dict: object) -> None:
        with _timeit('preparing state_dict'):
            meta, tensors = _prepare_state_dict(state_dict, device=self._device)
        work = []
        with _timeit('send meta'):
            buf = pickle.dumps(meta)
            len_t = torch.tensor([len(buf)], dtype=torch.int64, device=self._device)
            buf_t = torch.frombuffer(buf, dtype=torch.uint8).to(self._device)
            for dst_rank in dst_ranks:
                work.append(self._pg.send([len_t], dst_rank, tag=1))
                work.append(self._pg.send([buf_t], dst_rank, tag=2))
        with _timeit('send tensors'):
            for i, t in enumerate(tensors):
                original_device = t.device
                t = t.to(self._device)
                for dst_rank in dst_ranks:
                    work.append(self._pg.send([t], dst_rank, tag=3 + i))
                if original_device == torch.device('cpu'):
                    for w in work:
                        w.wait()
                    work = []
            for w in work:
                w.wait()

    def recv_checkpoint(self, src_rank: int) -> object:
        state_dict = self._state_dict() if self._state_dict else {}
        state_dict_leaves, _ = tree_flatten_with_path(state_dict)
        dst_tensors: dict[KeyPath, object] = dict(state_dict_leaves)
        len_t = torch.zeros(1, dtype=torch.int64, device=self._device)
        self._pg.recv([len_t], src_rank, tag=1).wait()
        length = cast(int, len_t.item())
        buf = torch.empty(length, dtype=torch.uint8, device=self._device)
        self._pg.recv([buf], src_rank, tag=2).wait()
        meta: _StateDictMeta = pickle.loads(buf.cpu().numpy().tobytes())
        i: int = 0
        works: list[Work] = []

        def recv(path: KeyPath, v: _TensorMeta) -> torch.Tensor:
            nonlocal i
            inplace = dst_tensors.get(path)
            if isinstance(inplace, torch.Tensor) and inplace.device.type == self._device.type:
                if isinstance(inplace, DTensor):
                    inplace = inplace._local_tensor
                t = _cast_tensor(inplace, torch.uint8)
                if t.nbytes != v.nbytes:
                    raise AssertionError('inplace tensor storage must be the same size')
            else:
                t = torch.empty(v.nbytes, dtype=torch.uint8, device=self._device)
            work = self._pg.recv([t], src_rank, tag=3 + i)
            i += 1
            if inplace is None:
                work.wait()
                t = t.cpu()
            else:
                works.append(work)
            return torch.as_strided(t.view(v.dtype), size=v.shape, stride=v.stride, storage_offset=v.storage_offset)
        values: list[object] = []
        for path, v in zip(meta.paths, meta.non_tensor_leaves):
            if isinstance(v, _TensorMeta):
                values.append(recv(path, v))
            elif isinstance(v, _DTensorMeta):
                tensor = recv(path, v.local)
                values.append(DTensor(tensor, v.spec, requires_grad=False))
            elif isinstance(v, _ShardedTensorMeta):
                local_shards = []
                current_rank = self._pg.rank()
                for j, shard_meta in enumerate(v.local_shards_meta):
                    tensor = recv(path, shard_meta)
                    original_shard_metadata = v.local_shards_shard_metadata[j]
                    updated_shard_metadata = ShardMetadata(shard_offsets=original_shard_metadata.shard_offsets, shard_sizes=original_shard_metadata.shard_sizes, placement=f'rank:{current_rank}/{tensor.device.type}')
                    local_shard = ShardedTensorShard(tensor=tensor, metadata=updated_shard_metadata)
                    local_shards.append(local_shard)
                sharded_tensor = ShardedTensor._init_from_local_shards_and_global_metadata(local_shards=local_shards, sharded_tensor_metadata=v.sharded_tensor_metadata)
                values.append(sharded_tensor)
            else:
                values.append(v)
        for work in works:
            work.wait()
        return tree_unflatten(values, meta.treespec)

