import torch

# Example: use stop_debug_server() guarded by attribute checks inside a function
# so this can be used in test harnesses or scripts that run across different environments.
def shutdown_debug_server():
    if not hasattr(torch.distributed, "debug"):
        return "debug module missing"
    debug_mod = torch.distributed.debug
    if not hasattr(debug_mod, "stop_debug_server"):
        return "stop_debug_server missing"
    try:
        debug_mod.stop_debug_server()
        return "stopped"
    except Exception as e:
        return f"error: {e}"

if __name__ == "__main__":
    result = shutdown_debug_server()
    print(result)

