def get_default_backend_for_device(device: str | torch.device) -> str:
    if isinstance(device, torch.device):
        device_str = device.type
    else:
        device_str = torch.device(device).type
    backend = Backend.default_device_backend_map.get(device_str)
    if backend is None:
        raise ValueError(f'Default backend not registered for device : {device}')
    return backend

# --- helper: torch.distributed.distributed_c10d.Backend ---
class Backend(str):
    UNDEFINED = 'undefined'
    GLOO = 'gloo'
    NCCL = 'nccl'
    UCC = 'ucc'
    MPI = 'mpi'
    XCCL = 'xccl'
    FAKE = 'fake'
    _BackendPlugin = namedtuple('_BackendPlugin', ['creator_fn', 'extended_api'])
    _plugins: dict[str, _BackendPlugin] = {}
    backend_list = [UNDEFINED, GLOO, NCCL, XCCL, UCC, MPI, FAKE]
    default_device_backend_map: dict[str, str] = {'cpu': GLOO, 'cuda': NCCL, 'xpu': XCCL, 'mps': GLOO}
    backend_capability: dict[str, list[str]] = {GLOO: ['cpu', 'cuda'], NCCL: ['cuda'], XCCL: ['xpu'], UCC: ['cpu', 'cuda'], MPI: ['cpu', 'cuda'], FAKE: ['cpu', 'cuda', 'hpu', 'xpu']}
    backend_type_map: dict[str, ProcessGroup.BackendType] = {UNDEFINED: ProcessGroup.BackendType.UNDEFINED, GLOO: ProcessGroup.BackendType.GLOO, NCCL: ProcessGroup.BackendType.NCCL, XCCL: ProcessGroup.BackendType.XCCL, UCC: ProcessGroup.BackendType.UCC, MPI: ProcessGroup.BackendType.MPI, FAKE: ProcessGroup.BackendType.CUSTOM}

    def __new__(cls, name: str):
        if not isinstance(name, str):
            raise ValueError('Backend constructor parameter must be string-ish')
        value = getattr(Backend, name.upper(), Backend.UNDEFINED)
        if value == Backend.UNDEFINED:
            value = name.lower()
        return value

    @classmethod
    def register_backend(cls, name, func, extended_api: bool=False, devices: str | list[str] | None=None) -> None:
        if not hasattr(Backend, name.upper()):
            setattr(Backend, name.upper(), name.lower())
        if name.lower() not in Backend.backend_list:
            Backend.backend_list.append(name.lower())
        if devices is not None:
            for device in devices:
                if device not in Backend.default_device_backend_map:
                    Backend.default_device_backend_map[device] = name.lower()
        Backend.backend_type_map[name.lower()] = ProcessGroup.BackendType.CUSTOM
        if devices is None:
            warnings.warn(f'Device capability of {name} unspecified, assuming `cpu` and `cuda` or `xpu`. Please specify it via the `devices` argument of `register_backend`.', stacklevel=2)
            Backend.backend_capability[name.lower()] = ['cpu', 'cuda', 'xpu'] if torch.xpu.is_available() else ['cpu', 'cuda']
        elif isinstance(devices, str):
            Backend.backend_capability[name.lower()] = [devices]
        else:
            Backend.backend_capability[name.lower()] = devices
        Backend._plugins[name.upper()] = Backend._BackendPlugin(func, extended_api)

def get_node_local_rank(fallback_rank: int | None=None) -> int:
    if 'LOCAL_RANK' in os.environ:
        return int(os.environ['LOCAL_RANK'])
    elif fallback_rank is not None:
        return int(fallback_rank)
    raise RuntimeError('LOCAL_RANK is not in the environment. Consider passing fallback_rank to allow `get_node_local_rank` to work, assuming you are not running in a multi-device context and want the code to run locally instead.')

@_exception_logger
def broadcast_object_list(object_list: list[Any], src: int | None=None, group: ProcessGroup | None=None, device: torch.device | None=None, group_src: int | None=None):
    group = _group_or_default_group(group)
    if src is None and group_src is None:
        src = 0
    group_src = _canonicalize_group_rank(group, src, group_src, return_global=False)
    if _rank_not_in_group(group):
        _warn_not_in_group('broadcast_object_list')
        return
    current_device = device or _get_object_coll_device(group)
    my_group_rank = group.rank()
    if my_group_rank == group_src:
        tensor_list, size_list = zip(*[_object_to_tensor(obj, current_device, group) for obj in object_list])
        object_sizes_tensor = torch.cat(size_list)
    else:
        object_sizes_tensor = torch.empty(len(object_list), dtype=torch.long, device=current_device)
    broadcast(object_sizes_tensor, group_src=group_src, group=group)
    if my_group_rank == group_src:
        if len(tensor_list) == 1:
            object_tensor = tensor_list[0]
        else:
            object_tensor = torch.cat(tensor_list)
    else:
        object_tensor = torch.empty(torch.sum(object_sizes_tensor).item(), dtype=torch.uint8, device=current_device)
    broadcast(object_tensor, group_src=group_src, group=group)
    offset = 0
    if my_group_rank != group_src:
        for i, obj_size in enumerate(object_sizes_tensor):
            obj_view = object_tensor[offset:offset + obj_size]
            obj_view = obj_view.type(torch.uint8)
            offset += obj_size
            object_list[i] = _tensor_to_object(obj_view, obj_size, group)

