import torch
from torch.distributed.elastic.multiprocessing.api import LogsDest

# Per-local-rank redirected stdout and stderr
stdouts = {0: '/tmp/worker0.out', 1: '/tmp/worker1.out'}
stderrs = {0: '/tmp/worker0.err', 1: '/tmp/worker1.err'}
logs = LogsDest(stdouts=stdouts, stderrs=stderrs)
# Use the fields
for rank, path in logs.stdouts.items():
    print(f'Rank {rank} stdout -> {path}')
for rank, path in logs.stderrs.items():
    print(f'Rank {rank} stderr -> {path}')

from torch.distributed.elastic.rendezvous.api import RendezvousGracefulExitError

# Instantiate without a message and raise it to signal a graceful exit
try:
    raise RendezvousGracefulExitError()
except RendezvousGracefulExitError as e:
    print('Caught graceful exit exception; message:', e)

from torch.distributed.elastic.rendezvous.api import RendezvousGracefulExitError

# Example function that may intentionally exit the rendezvous flow
def join_rendezvous(include_node: bool):
    if not include_node:
        # signal an intentional non-failure exit
        raise RendezvousGracefulExitError('this node is excluded from rendezvous')
    return 'joined'

for include in (False, True):
    try:
        result = join_rendezvous(include)
