def barrier(store, world_size: int, key_prefix: str, barrier_timeout: float=300, rank: int | None=None, rank_tracing_decoder: Callable[[int], str] | None=None, trace_timeout: float=10) -> None:
    if rank is None:
        assert rank_tracing_decoder is None, 'Tracing requires rank information'
    with store_timeout(store, barrier_timeout):
        last_member_key = _barrier_nonblocking(store=store, world_size=world_size, key_prefix=key_prefix)
        try:
            store.wait([last_member_key])
        except DistStoreError as e:
            if rank is None:
                raise e
            else:
                missing_ranks = _try_detecting_missing_ranks(store, world_size, key_prefix, rank, rank_tracing_decoder or (lambda x: str(x)), trace_timeout)
                if missing_ranks is not None:
                    raise DistStoreError('Timed out waiting on barrier on rank {}, for key prefix: {} (world_size={}, missing_ranks={}, timeout={})'.format(rank, key_prefix, world_size, f"[{', '.join(missing_ranks)}]", barrier_timeout)) from None
                else:
                    raise e

# --- helper: torch.distributed.elastic.utils.store._barrier_nonblocking ---
def _barrier_nonblocking(store, world_size: int, key_prefix: str) -> str:
    num_members_key = key_prefix + _NUM_MEMBERS
    last_member_key = key_prefix + _LAST_MEMBER_CHECKIN
    idx = store.add(num_members_key, 1)
    if idx == world_size:
        store.set(last_member_key, '<val_ignored>')
    return last_member_key

# --- helper: torch.distributed.elastic.utils.store._try_detecting_missing_ranks ---
def _try_detecting_missing_ranks(store, world_size: int, key_prefix: str, rank: int, rank_decoder: Callable[[int], str], trace_timeout: float) -> Iterable[str] | None:
    store.set(f'{key_prefix}{rank}{_TRACE}', '<val_ignored>')

    def _find_missing_ranks():
        missing_rank_info = set()
        ranks_missing = 0
        for i in range(1, world_size):
            if ranks_missing >= _MAX_TRACE_MISSING_RANKS:
                break
            try:
                if ranks_missing == 0:
                    store.wait([f'{key_prefix}{i}{_TRACE}'], timedelta(seconds=trace_timeout))
                else:
                    store.wait([f'{key_prefix}{i}{_TRACE}'], timedelta(milliseconds=1))
            except DistStoreError:
                ranks_missing += 1
                missing_rank_info.add(rank_decoder(i))
        return missing_rank_info

    def _checkin():
        try:
            store.wait([f'{key_prefix}{_TRACING_GATE}'])
            return [f'[<check rank 0 ({rank_decoder(0)}) for missing rank info>]']
        except DistStoreError:
            return None
    if rank == 0:
        missing_rank_info = _find_missing_ranks()
        store.set(f'{key_prefix}{_TRACING_GATE}', '<val_ignored>')
        return missing_rank_info
    else:
        return _checkin()

# --- helper: torch.distributed.elastic.utils.store.store_timeout ---
@contextmanager
def store_timeout(store, timeout: float):
    old_timeout = store.timeout
    store.set_timeout(timedelta(seconds=timeout))
    yield
    store.set_timeout(old_timeout)

