def build_collectives(all_entries: dict[int, list[dict[str, Any]]], _groups: dict[str, Group], _memberships: dict[str, set[Any]], _pg_guids: dict[tuple[str, int], str], version: str, mismatch_cap: int=10) -> tuple[list[Traceback], list[Collective], list[NCCLCall]]:
    tracebacks: list[Traceback] = []
    collectives: list[Collective] = []
    nccl_calls: list[NCCLCall] = []
    mismatch = {_groups[g].id: 0 for g in _groups}
    dumps_ranks = {int(key) for key in all_entries}
    '\n    - it doesn\'t matter what order I put collectives/ncclops into their table. we can later on re-sort it by start time\n    - there could be multiple options for the "first" collective to pair up (rank 0,1 might do a bcast while rank 2,3 do a bcast)\n    - within a group, the first collective must be the same on all ranks in the group, then it can be marked as a\n    collective and removed\n    '
    while all_entries:
        rank_iter = iter(all_entries)
        first_rank = next(rank_iter)
        other_ranks = list(rank_iter)
        if len(all_entries[first_rank]) == 0:
            all_entries.pop(first_rank)
            continue
        entries = all_entries[first_rank]
        current_entry = entries[0]
        desc = current_entry['process_group'][1]
        original_pg_name = current_entry['process_group'][0]
        pg_name = _pg_guids[original_pg_name, first_rank]
        expected_ranks = set(_memberships[pg_name])
        entry_state = EntryState(current_entry, expected_ranks)
        match_record = MatchStateRecord(expected_ranks=expected_ranks, other_ranks=other_ranks, entry_state=entry_state, candidate_ranks={first_rank}, candidate_idx={}, found_ranks=set(), found_idx={}, errors=set())
        major_v, minor_v = get_version_detail(version)
        find_coalesced_group = find_coalesced_group_p2p_only if major_v <= 2 and minor_v < 7 else find_coalesced_group_with_non_p2p
        maybe_coalesced_group = find_coalesced_group(pg_name, entries, _pg_guids, first_rank)
        if len(maybe_coalesced_group) > 1:
            num_coalesced_entries = len(maybe_coalesced_group)
            candidate_ranks = copy.deepcopy(expected_ranks)
            done_ranks = set()
            all_coalesced_entries = {}
            while candidate_ranks:
                curr = candidate_ranks.pop()
                done_ranks.add(curr)
                grp = find_coalesced_group(pg_name, all_entries[curr], _pg_guids, curr) if curr in all_entries else []
                all_coalesced_entries[curr] = grp
                for _, entry in grp:
                    op = Op(entry, _memberships, pg_name)
                    peer = None
                    if op.type == 'send':
                        assert op._src_g == curr, f'Send src error: {curr} expected but {op._src_g} is set'
                        peer = op._dst_g
                    elif op.type == 'recv':
                        assert op._dst_g == curr, f'Recv dst error: {curr} expected but {op._dst_g} is set'
                        peer = op._src_g
                    if peer and peer not in done_ranks:
                        candidate_ranks.add(peer)
            if major_v <= 2 and minor_v < 7:
                match = match_coalesced_groups_p2p_only(all_coalesced_entries, group_size=_groups[pg_name].size, groups=_groups, memberships=_memberships, _pg_guids=_pg_guids)
            else:
                match = match_coalesced_groups_with_non_p2p(copy.deepcopy(all_coalesced_entries), pg_info=(pg_name, desc), memberships=_memberships, _pg_guids=_pg_guids, mismatch=mismatch, dumps_ranks=dumps_ranks, version=version, collectives=collectives, match_record=match_record)
            if match and mismatch[pg_name] == 0:
                collectives.append(match_record.entry_state.to_collective(len(collectives)))
            else:
                mismatch[pg_name] += 1
            for r in all_coalesced_entries:
                idx_map = {r: i for i, _ in reversed(all_coalesced_entries[r])}
                nccl_calls.extend(reversed(match_record.entry_state.to_nccl_call(all_entries, idx_map, len(nccl_calls), collectives[-1].id if match else None)))
                for i, k in idx_map.items():
                    for _ in range(1, num_coalesced_entries):
                        all_entries[i].pop(k)
        else:
            check_current_entry_match(all_entries, _pg_guids, (pg_name, desc), current_entry, _memberships, mismatch, match_record)
            error_analysis(all_entries, match_record, dumps_ranks, first_rank, current_entry, mismatch, get_version_detail(version), pg_name)
            if match_record.found_ranks == expected_ranks and mismatch[pg_name] == 0:
                collectives.append(match_record.entry_state.to_collective(len(collectives)))
                idx_map = {r: match_record.found_idx[r] if r != first_rank else 0 for r in match_record.found_ranks}
                nccl_calls.extend(match_record.entry_state.to_nccl_call(all_entries, idx_map, len(nccl_calls), collectives[-1].id))
            else:
                logger.debug('appending a non-matching collective')
                idx_map = {r: match_record.candidate_idx[r] if r != first_rank else 0 for r in match_record.candidate_ranks}
                collectives.append(match_record.entry_state.to_collective(len(collectives), errors=match_record.errors, idx_map=idx_map, all_entries=all_entries))
                nccl_calls.extend(match_record.entry_state.to_nccl_call(all_entries, idx_map, len(nccl_calls), None))
        if mismatch[pg_name] > mismatch_cap:
            logger.error('Too many mismatches for process_group %s: %s aborting', pg_name, desc)
            break
    return (tracebacks, collectives, nccl_calls)

