        super().__init__()
        self.fc = nn.Linear(8, 8)

    def step(self, x: torch.Tensor) -> torch.Tensor:
        return torch.relu(self.fc(x))

class Model(nn.Module):
    def __init__(self):
        super().__init__()
        self.block = Block()

model = Model()
# Register the nested module's method; no-op for plain nn.Module
register_fsdp_forward_method(model.block, "step")

inp = torch.randn(4, 8)
out = model.block.step(inp)
print(out.mean().item())

implementation:
def register_fsdp_forward_method(module: nn.Module, method_name: str) -> None:
    if not isinstance(module, FSDPModule):
        return
    if not hasattr(module, method_name):
        raise ValueError(f'{type(module)} does not have a method {method_name}')
    orig_method = getattr(module, method_name)

    @functools.wraps(orig_method)
    def wrapped_method(self, *args, **kwargs):
        fsdp_state = self._get_fsdp_state()
        args, kwargs = fsdp_state._pre_forward(self, args, kwargs)
        out = orig_method(*args, **kwargs)
        return fsdp_state._post_forward(self, args, out)
    setattr(module, method_name, wrapped_method.__get__(module, type(module)))

class ShardedGradScaler(GradScaler):

    def __init__(self, device: str='cuda', init_scale: float=2.0 ** 16, backoff_factor: float=0.5, growth_factor: float=2.0, growth_interval: int=2000, enabled: bool=True, process_group: ProcessGroup | None=dist.group.WORLD) -> None:
        super().__init__(device, init_scale=init_scale, backoff_factor=backoff_factor, growth_factor=growth_factor, growth_interval=growth_interval, enabled=enabled)
        if self._enabled:
            self.process_group = process_group
            self._per_optimizer_states = defaultdict(_refresh_per_optimizer_state)

    @overload
    def scale(self, outputs: torch.Tensor) -> torch.Tensor:
        ...

    @overload
    def scale(self, outputs: list[torch.Tensor]) -> list[torch.Tensor]:
        ...

    @overload
    def scale(self, outputs: tuple[torch.Tensor, ...]) -> tuple[torch.Tensor, ...]:
        ...

    @overload
    def scale(self, outputs: Iterable[torch.Tensor]) -> Iterable[torch.Tensor]:
        ...

    def scale(self, outputs: torch.Tensor | Iterable[torch.Tensor]) -> torch.Tensor | Iterable[torch.Tensor]:
        if not self._enabled:
            return outputs
        if isinstance(outputs, torch.Tensor):
            if not _is_supported_device(outputs):
                raise AssertionError(f'Expected supported device, got {outputs.device}')
            if self._scale is None:
                self._lazy_init_scale_growth_tracker(outputs.device)
            if self._scale is None:
                raise AssertionError('Expected _scale to be initialized, got None')
            scaled_output = outputs * self._scale.to(device=outputs.device, non_blocking=True)
            return scaled_output.type(outputs.dtype)
        stash: list[_GeneralMultiDeviceReplicator] = []

        def apply_scale(val: torch.Tensor | Iterable[torch.Tensor]):
            if isinstance(val, torch.Tensor):
                if not _is_supported_device(val):
                    raise AssertionError(f'Expected supported device, got {val.device}')
                if len(stash) == 0:
                    if self._scale is None:
                        self._lazy_init_scale_growth_tracker(val.device)
                    if self._scale is None:
                        raise AssertionError('Expected _scale to be initialized, got None')
                    stash.append(_GeneralMultiDeviceReplicator(self._scale))
                scaled_val = val * stash[0].get(val.device)
                return scaled_val.type(val.dtype)
            if isinstance(val, abc.Iterable):
                iterator = map(apply_scale, val)
                if isinstance(val, (list, tuple)):
                    return type(val)(iterator)
                return iterator
            raise ValueError('outputs must be a Tensor or an iterable of Tensors')
        return apply_scale(outputs)

    def _unscale_grads_(self, optimizer: torch.optim.Optimizer, inv_scale: torch.Tensor, found_inf: torch.Tensor, allow_fp16: bool=True) -> dict[torch.device, torch.Tensor]:
        per_device_inv_scale = _GeneralMultiDeviceReplicator(inv_scale)
        per_device_found_inf = _GeneralMultiDeviceReplicator(found_inf)
        per_device_and_dtype_grads = defaultdict(lambda: defaultdict(list))
        with torch.no_grad():
            for group in optimizer.param_groups:
                for param in group['params']:
                    if param.grad is None:
                        continue
                    if not allow_fp16 and param.grad.dtype == torch.float16:
                        raise ValueError('Attempting to unscale FP16 gradients.')
                    if param.grad.is_sparse:
                        if param.grad.dtype is torch.float16:
                            param_grad_fp32 = param.grad.type(torch.float32).coalesce()
                            param.grad = param_grad_fp32.type(torch.float16)
                        to_unscale = param.grad._values()
                    else:
                        to_unscale = param.grad
                    per_device_and_dtype_grads[to_unscale.device][to_unscale.dtype].append(to_unscale)
            for device, per_dtype_grads in per_device_and_dtype_grads.items():
                for grads in per_dtype_grads.values():
                    torch._amp_foreach_non_finite_check_and_unscale_(grads, per_device_found_inf.get(device), per_device_inv_scale.get(device))
        if not per_device_found_inf._per_device_tensors:
            if self._scale is None:
                raise AssertionError('Expected _scale to be initialized, got None')
            per_device_found_inf.get(self._scale.device)
        return per_device_found_inf._per_device_tensors

    def unscale_(self, optimizer: torch.optim.Optimizer) -> None:
        if not self._enabled:
            return
        self._check_scale_growth_tracker('unscale_')
        optimizer_state = self._per_optimizer_states[id(optimizer)]
        if optimizer_state['stage'] is OptState.UNSCALED:
            raise RuntimeError('unscale_() has already been called on this optimizer since the last update().')
        elif optimizer_state['stage'] is OptState.STEPPED:
            raise RuntimeError('unscale_() is being called after step().')
        if self._scale is None:
            raise AssertionError('Expected _scale to be initialized, got None')
        inv_scale = self._scale.double().reciprocal().float()
        found_inf = torch.full((1,), 0.0, dtype=torch.float32, device=self._scale.device)
        optimizer_state['found_inf_per_device'] = self._unscale_grads_(optimizer, inv_scale, found_inf, True)
        optimizer_state['stage'] = OptState.UNSCALED
        optimizer_state = self._per_optimizer_states[id(optimizer)]
        works = []
        found_inf_on_cpus = []
        found_inf_on_devices = []
        for found_inf in optimizer_state['found_inf_per_device'].values():
            if self._device != 'cpu' and found_inf.device.type == 'cpu':
                found_inf_on_cpus.append(found_inf)
                found_inf_on_device = found_inf.to(self._device)
                found_inf_on_devices.append(found_inf_on_device)
                works.append(dist.all_reduce(found_inf_on_device, async_op=True, group=self.process_group))
            else:
                works.append(dist.all_reduce(found_inf, async_op=True, group=self.process_group))
        for work in works:
            work.wait()
        if found_inf_on_cpus:
            torch._foreach_copy_(found_inf_on_cpus, found_inf_on_devices)

    def _amp_update_scale_cpu_(self, found_inf: torch.Tensor) -> None:
        if self._scale is None or self._growth_tracker is None:
            raise AssertionError('Expected _scale and _growth_tracker to be initialized, got None')
        if found_inf.item() >= 1.0:
            self._scale *= self._backoff_factor
            self._growth_tracker.fill_(0)
        else:
            successful = self._growth_tracker + 1
            if successful == self._growth_interval:
                self._scale *= self._growth_factor
                self._growth_tracker.fill_(0)
            else:
                self._growth_tracker = successful

    def update(self, new_scale: float | torch.Tensor | None=None) -> None:
        if not self._enabled:
            return
        _scale, _growth_tracker = self._check_scale_growth_tracker('update')
        if new_scale is not None:
            if isinstance(new_scale, float):
                self._scale.fill_(new_scale)
            else:
                reason = 'new_scale should be a float or a 1-element torch.cuda.FloatTensor or torch.FloatTensor with requires_grad=False.'
                if new_scale.device.type != self._device:
                    raise AssertionError(reason)
                if new_scale.numel() != 1:
                    raise AssertionError(reason)
                if new_scale.requires_grad is not False:
                    raise AssertionError(reason)
                self._scale.copy_(new_scale)
        else:
            found_infs = [found_inf.to(device=_scale.device, non_blocking=True) for state in self._per_optimizer_states.values() for found_inf in state['found_inf_per_device'].values()]
            if len(found_infs) == 0:
                raise AssertionError('No inf checks were recorded prior to update.')
            found_inf_combined = found_infs[0]
            if len(found_infs) > 1:
                for i in range(1, len(found_infs)):
                    found_inf_combined += found_infs[i]
            if _scale.device.type == 'cpu':
                self._amp_update_scale_cpu_(found_inf_combined)
            else:
                torch._amp_update_scale_(self._scale, self._growth_tracker, found_inf_combined, self._growth_factor, self._backoff_factor, self._growth_interval)
        self._per_optimizer_states = defaultdict(_refresh_per_optimizer_state)

# --- helper: torch.distributed.fsdp.sharded_grad_scaler._GeneralMultiDeviceReplicator ---
class _GeneralMultiDeviceReplicator(_MultiDeviceReplicator):

    def __init__(self, master_tensor: torch.Tensor) -> None:
        if not _is_supported_device(master_tensor):
            raise AssertionError(f'Expected supported device, got {master_tensor.device}')
        self.master = master_tensor
        self._per_device_tensors: dict[torch.device, torch.Tensor] = {}

# --- helper: torch.distributed.fsdp.sharded_grad_scaler._is_supported_device ---
def _is_supported_device(tensor: torch.Tensor) -> bool:
    return tensor.is_cuda or tensor.device.type in ('xla', 'cpu', 'hpu', 'mtia', 'xpu', torch._C._get_privateuse1_backend_name())

# --- helper: torch.distributed.fsdp.sharded_grad_scaler._refresh_per_optimizer_state ---
def _refresh_per_optimizer_state() -> dict[str, Any]:
    return {'stage': OptState.READY, 'found_inf_per_device': {}}

