def generate_rank_to_stage_mapping(pp_size: int, num_stages: int, style: str='loop') -> dict[int, list[int]]:
    stage_to_rank = generate_stage_to_rank_mapping(pp_size, num_stages, style)
    rank_to_stages: dict[int, list[int]] = {}
    for stage_id, rank in stage_to_rank.items():
        if rank not in rank_to_stages:
            rank_to_stages[rank] = []
        rank_to_stages[rank].append(stage_id)
    for stages in rank_to_stages.values():
        stages.sort()
    return rank_to_stages

# --- helper: torch.distributed.pipelining._utils.generate_stage_to_rank_mapping ---
def generate_stage_to_rank_mapping(pp_size: int, num_stages: int, style: str='loop') -> dict[int, int]:
    mapping = {}
    if style == 'loop':
        for stage_index in range(num_stages):
            mapping[stage_index] = stage_index % pp_size
    elif style == 'v':
        if num_stages % pp_size != 0:
            raise ValueError(f'num_stages {num_stages} must be evenly divisible by pp_size {pp_size} for V schedules')
        rank_index = 0
        for stage_index in range(num_stages):
            mapping[stage_index] = rank_index
            if (stage_index + 1) % pp_size == 0:
                continue
            if stage_index // pp_size % 2 == 0:
                rank_index += 1
            else:
                rank_index -= 1
    else:
        raise ValueError(f'Style {style} is not supported.')
    return mapping

def map_debug_info(a: Argument) -> Argument:
    return torch.fx.node.map_aggregate(a, friendly_debug_info)

# --- helper: torch.distributed.pipelining._debug.friendly_debug_info ---
def friendly_debug_info(v: object) -> Argument:
    if isinstance(v, torch.Tensor):
        return f'Tensor({v.shape}, grad={v.requires_grad}, dtype={v.dtype})'
    else:
        return str(v)

def stage_backward(stage_output, output_grads, input_values, outputs_with_grads_idxs: list[int] | None=None) -> tuple[torch.Tensor | None, ...]:
    if outputs_with_grads_idxs is not None:
        stage_output = [stage_output[i] for i in outputs_with_grads_idxs]
        output_grads = [output_grads[i] for i in outputs_with_grads_idxs]
    try:
        stage_output_tensors: list[torch.Tensor] = []
        output_grad_tensors: list[torch.Tensor | None] = []

        def extract_tensors_with_grads(output_val, grad_val, extract_tensors_with_grads):
            if isinstance(output_val, torch.Tensor):
                if not output_val.requires_grad and output_val.grad_fn is None:
                    return
                if not isinstance(grad_val, (torch.Tensor, type(None))):
                    raise AssertionError(f'Expected Tensor or None gradient but got {type(grad_val)}')
                stage_output_tensors.append(output_val)
                output_grad_tensors.append(grad_val)
            elif isinstance(output_val, (tuple, list)):
                if grad_val is None:
                    return
                if not isinstance(grad_val, (tuple, list)):
                    raise AssertionError(f'grad_value expected to have type {type(output_val)} but got {type(grad_val)}')
                if not len(output_val) == len(grad_val):
                    raise AssertionError(f'Expected len(output_val) == len(grad_val), got {len(output_val)} != {len(grad_val)}')
                for ov, gv in zip(output_val, grad_val):
                    extract_tensors_with_grads(ov, gv, extract_tensors_with_grads)
            elif isinstance(output_val, dict):
                if grad_val is None:
                    return
                if not isinstance(grad_val, dict):
                    raise AssertionError(f'Expected dict, got {type(grad_val)}')
                if not set(output_val.keys()) == set(grad_val.keys()):
                    raise AssertionError(f'Expected keys {set(output_val.keys())}, got {set(grad_val.keys())}')
                for k in output_val:
                    extract_tensors_with_grads(output_val[k], grad_val[k], extract_tensors_with_grads)
            else:
                pass
        extract_tensors_with_grads(stage_output, output_grads, extract_tensors_with_grads)
        torch.autograd.backward(stage_output_tensors, grad_tensors=output_grad_tensors)
        grad_inputs: list[torch.Tensor | None] = []
        for val in input_values:
            if isinstance(val, torch.Tensor):
                grad_inputs.append(val.grad)
                val.grad = None
            else:
                grad_inputs.append(None)
        '\n        inputs_with_grad = []\n        for val in input_values:\n            if isinstance(val, torch.Tensor) and val.requires_grad:\n                inputs_with_grad.append(val)\n\n        grad_inputs = torch.autograd.grad(\n            stage_output_tensors, inputs_with_grad, output_grad_tensors,  # type: ignore[arg-type]\n        )\n        '
    except Exception as e:
        exc_msg = f'\n        Failed to run stage backward:\n        Stage output: {map_debug_info(stage_output)}\n        Output gradient: {map_debug_info(output_grads)}\n        Input: {map_debug_info(input_values)}\n        '
        raise RuntimeError(exc_msg) from e
    return tuple(grad_inputs)

@contract(state_cls=_ReplicateState)
def replicate(module: nn.Module, *, mesh: DeviceMesh | None=None, mp_policy: MixedPrecisionPolicy=MixedPrecisionPolicy(), offload_policy: OffloadPolicy=OffloadPolicy(), ignored_params: set[nn.Parameter] | None=None):
    torch._C._log_api_usage_once('torch.distributed._composable.replicate_with_fsdp')
    _validate_module(module)
    mesh = mesh or _init_default_mesh(mesh_dim_names=('replicate',))
    _validate_mesh(mesh)
    mesh_info = DDPMeshInfo(mesh, replicate_mesh_dim=0)
    device = _get_device_from_mesh(mesh)
    arg_module, modules, _, params, _ = _get_modules_and_states(module, device, ignored_params, is_composable_fn=is_composable_with_replicate, get_state_fn=_get_module_replicate_state)
    state = replicate.state(modules[0])
    state.init(modules, device, mp_policy)
    _init_param_group(state, params, modules, mesh_info, None, device, None, mp_policy, offload_policy)
    _apply_to_module(modules, cls_to_replicate_cls, ReplicateModule, 'Replicate', _unimplemented_deepcopy)
    return arg_module

# --- helper: torch.distributed._composable.replicate_with_fsdp.ReplicateModule ---
class ReplicateModule(FSDPModule):
    _orig_cls_mro_index: int = 3

# --- helper: torch.distributed._composable.replicate_with_fsdp._ReplicateState ---
class _ReplicateState(FSDPState):
    _state_name: str = 'Replicate'

    def __init__(self) -> None:
        super().__init__()
        self._state_ctx = _ReplicateStateContext()

    def _get_state_for_module(self, module: nn.Module) -> FSDPState | None:
        return _get_module_replicate_state(module)

    def init(self, modules: tuple[nn.Module, ...], device: torch.device, mp_policy: MixedPrecisionPolicy, auto_reshard_after_forward: bool=False) -> None:
        super().init(modules, device, mp_policy, auto_reshard_after_forward)

# --- helper: torch.distributed._composable.replicate_with_fsdp._get_module_replicate_state ---
def _get_module_replicate_state(module: nn.Module) -> _ReplicateState | None:
    state = _get_module_state(module)
    if isinstance(state, _ReplicateState):
        return state
    return None

# --- helper: torch.distributed._composable.replicate_with_fsdp._validate_mesh ---
def _validate_mesh(mesh: DeviceMesh) -> None:
    if mesh.ndim != 1:
        raise ValueError(f'replicate expects a 1D DeviceMesh but got {mesh}')

# --- helper: torch.distributed._composable.replicate_with_fsdp._validate_module ---
def _validate_module(module: nn.Module) -> None:
    if not is_composable_with_replicate(module):
        raise RuntimeError('Cannot apply `replicate()` on a Module already managed by `fully_shard`')
    _validate_module_common(module, 'replicate')

# --- helper: torch.distributed._composable.replicate_with_fsdp.is_composable_with_replicate ---
def is_composable_with_replicate(module: nn.Module) -> bool:
    registry = _get_registry(module)
    if registry is None:
        return True
    return 'fully_shard' not in registry

