def local_map(func: Callable | None=None, out_placements: OutputPlacements=None, in_placements: InputPlacements=None, in_grad_placements: InputPlacements=None, device_mesh: DeviceMesh | None=None, *, redistribute_inputs: bool=False):
    if func is None:

        def decorated(func):
            return local_map(func=func, out_placements=out_placements, in_placements=in_placements, in_grad_placements=in_grad_placements, device_mesh=device_mesh, redistribute_inputs=redistribute_inputs)
        return decorated
    return functools.partial(_local_map_wrapped, func, out_placements, in_placements, in_grad_placements, device_mesh, redistribute_inputs)

def register_sharding(op: OpOverload | list[OpOverload]):

    def custom_strategy(custom_sharding_fn: Callable[..., Sequence[tuple[PlacementList, PlacementList]]], op_schema: OpSchema) -> StrategyType:

        def strategy_to_spec(strategy: object) -> object:
            if isinstance(strategy, OpStrategy):
                return strategy.strategies[0].output_spec
            elif isinstance(strategy, TupleStrategy):
                return tuple((strategy_to_spec(s) for s in strategy.children))
            else:
                return strategy
        mesh = op_schema.get_mesh_from_args()
        args_schema = tuple((strategy_to_spec(i) for i in op_schema.args_schema))
        kwargs_schema = {k: strategy_to_spec(v) for k, v in op_schema.kwargs_schema.items()}
        acceptable_shardings = custom_sharding_fn(*args_schema, **kwargs_schema)
        single_mesh_dim_strategies: list[PlacementList] = []
        for output_specs, input_specs in acceptable_shardings:
            single_mesh_dim_strategies.append(output_specs + input_specs)
        return expand_to_full_mesh_op_strategy(mesh, op_schema, single_mesh_dim_strategies, input_index=len(op_schema.op._schema.returns), inplace_op=op_schema.is_inplace_op())

    def wrapper(custom_sharding_fn):

        def derive_schema_info(op):
            static_argnum = 100
            static_kwargkey: list[str] = []
            for i, arg in enumerate(op._schema.arguments):
                if isinstance(arg.type, torch.IntType) or (isinstance(arg.type, torch.OptionalType) and isinstance(arg.type.getElementType(), torch.IntType)):
                    static_argnum = min(i, static_argnum)
                    if arg.kwarg_only:
                        static_kwargkey.append(arg.name)
            return RuntimeSchemaInfo(static_argnum, static_kwargkey or None, needs_pytree=True)
        overloads = op if isinstance(op, list) else [op]
        for overload in overloads:
            DTensor._op_dispatcher.sharding_propagator.register_op_strategy(overload, partial(custom_strategy, custom_sharding_fn), derive_schema_info(overload))
        return custom_sharding_fn
    return wrapper

class Replicate(torch._C._distributed.Replicate):

    def __hash__(self) -> int:
        return -1

    def __repr__(self) -> str:
        return 'Replicate()'

    def __str__(self) -> str:
        return 'R'

    @classmethod
    def _make_replicate_tensor(cls, tensor: torch.Tensor, mesh: DeviceMesh, mesh_dim: int, src_data_rank: int | None=0) -> torch.Tensor:
        my_coordinate = mesh.get_coordinate()
        if my_coordinate is None:
            return tensor.new_empty(0, requires_grad=tensor.requires_grad)
        tensor = tensor.contiguous()
        if src_data_rank is not None:
            mesh_broadcast(tensor, mesh, mesh_dim=mesh_dim, group_src=src_data_rank)
        return tensor

    def _replicate_tensor(self, tensor: torch.Tensor, mesh: DeviceMesh, mesh_dim: int, src_data_rank: int | None=0) -> torch.Tensor:
        return Replicate._make_replicate_tensor(tensor, mesh, mesh_dim, src_data_rank)

class DTensorExtensions(FSDPExtensions):

    def __init__(self, device_handle) -> None:
        super().__init__()
        self.compute_stream = None
        self.device_handle = device_handle
        self.post_unflatten_transform = torch._dynamo.disable(self.post_unflatten_transform)

    def pre_flatten_transform(self, tensor: torch.Tensor) -> tuple[torch.Tensor, Any | None]:
        return _flatten_tensor(tensor)

    def post_unflatten_transform(self, tensor: torch.Tensor, param_extension: Any) -> torch.Tensor:
        stream = self.compute_stream or self.device_handle.current_stream()
        with self.device_handle.stream(stream):
            result = _unflatten_tensor(tensor, param_extension, device_handle=self.device_handle, compute_stream=self.compute_stream)
            _set_fsdp_flattened(result)
            return result

    def chunk_tensor(self, tensor: torch.Tensor, rank: int, world_size: int, num_devices_per_node: int, pg: dist.ProcessGroup, device: torch.device | None=None) -> torch.Tensor:
        return _chunk_tensor(tensor, rank, world_size, num_devices_per_node, pg)

    def chunk_dtensor(self, tensor: torch.Tensor, rank: int, device_mesh: DeviceMesh) -> torch.Tensor:
        return _chunk_dtensor(tensor, rank, device_mesh)

    def pre_load_state_dict_transform(self, tensor: torch.Tensor) -> tuple[torch.Tensor, list[Shard]]:
        return _pre_load_state_dict(tensor)

    def all_gather_dtensor(self, tensor: DTensor, parent_mesh: DeviceMesh | None) -> torch.Tensor:
        return _all_gather_dtensor(tensor, parent_mesh)

# --- helper: torch.distributed.tensor.parallel.fsdp._all_gather_dtensor ---
def _all_gather_dtensor(tensor: DTensor, parent_mesh: DeviceMesh | None) -> torch.Tensor:
    assert parent_mesh == tensor.device_mesh
    placements = list(copy.deepcopy(tensor.placements))
    for i in range(len(placements) - 1):
        placements[i] = Replicate()
    tensor = tensor.redistribute(device_mesh=tensor.device_mesh, placements=placements)
    return tensor.to_local()

# --- helper: torch.distributed.tensor.parallel.fsdp._chunk_dtensor ---
def _chunk_dtensor(tensor: torch.Tensor, rank: int, device_mesh: DeviceMesh) -> DTensor:
    root_mesh = device_mesh._get_root_mesh() if device_mesh is not None else None
    if root_mesh is None:
        raise RuntimeError('No parent device_mesh is found for FSDP device_mesh.')
    if root_mesh.ndim < 2:
        raise RuntimeError(f'Found parent device_mesh of ndim={root_mesh.ndim},', 'but meshes must be at least 2D.')
    tensor = tensor.detach().clone()
    if isinstance(tensor, torch.Tensor) and (not isinstance(tensor, DTensor)):
        replicate_placements = [Replicate() for _ in range(root_mesh.ndim)]
        shard_placements = [Replicate() for _ in range(root_mesh.ndim)]
        shard_placements[0] = DShard(0)
        return DTensor.from_local(tensor, root_mesh, replicate_placements, run_check=False).redistribute(device_mesh=root_mesh, placements=shard_placements)
    else:
        tp_placements = tensor.placements
        tp_placement = tp_placements[0]
        tensor = tensor.to_local()
        replicate_placements = [Replicate() for _ in range(root_mesh.ndim)]
        replicate_placements[-1] = tp_placement
        shard_placements = [Replicate() for i in range(root_mesh.ndim)]
        shard_placements[-2] = DShard(0)
        shard_placements[-1] = tp_placement
        return DTensor.from_local(tensor, root_mesh, replicate_placements, run_check=False).redistribute(device_mesh=root_mesh, placements=shard_placements)

# --- helper: torch.distributed.tensor.parallel.fsdp._chunk_tensor ---
def _chunk_tensor(tensor: torch.Tensor, rank: int, world_size: int, num_devices_per_node: int, pg: dist.ProcessGroup) -> torch.Tensor:
    if type(tensor) is ShardedTensor:
        assert len(tensor.local_shards()) == 1
        inner_param = tensor.local_tensor()
        inner_st = _create_chunk_sharded_tensor(inner_param, rank, world_size, num_devices_per_node, pg)
        outer_local_shard = tensor.local_shards()[0]
        shards: list[Shard] = [Shard(inner_st, copy.deepcopy(outer_local_shard.metadata))]
        st_meta = copy.deepcopy(tensor.metadata())
        st_meta.tensor_properties.requires_grad = False
        st_outer = ShardedTensor._init_from_local_shards_and_global_metadata(shards, sharded_tensor_metadata=st_meta, process_group=tensor._process_group, init_rrefs=False)
        return st_outer
    elif type(tensor) is DTensor:
        device_mesh = tensor.device_mesh
        assert device_mesh.ndim == 1, 'Only 1D DeviceMeshes currently handled'
        inner_param = tensor._local_tensor
        inner_st = _create_chunk_sharded_tensor(inner_param, rank, world_size, torch.accelerator.device_count(), pg)
        dt_pg = _get_dt_pg(tensor)
        shards = [Shard(inner_st, _create_shard_md_from_dt(tensor, dist.get_rank(dt_pg)))]
        st_meta = _create_sharded_tensor_md_from_dt(tensor, dt_pg)
        st_meta.tensor_properties.requires_grad = False
        st_outer = ShardedTensor._init_from_local_shards_and_global_metadata(shards, sharded_tensor_metadata=st_meta, process_group=dt_pg, init_rrefs=False)
        return st_outer
    else:
        return _create_chunk_sharded_tensor(tensor, rank, world_size, num_devices_per_node, pg)

# --- helper: torch.distributed.tensor.parallel.fsdp._pre_load_state_dict ---
def _pre_load_state_dict(tensor: torch.Tensor) -> tuple[torch.Tensor, list[Shard]]:
    shards = cast(ShardedTensor, tensor).local_shards()
    if len(shards) == 1 and type(shards[0].tensor) is ShardedTensor:
        inner_tensor = shards[0].tensor
        shards = inner_tensor.local_shards()
        tensor = inner_tensor
    return (tensor, shards if len(shards) > 0 else [])

class MixtureSameFamilyConstraint(Constraint):

    def __init__(self, base_constraint):
        if not isinstance(base_constraint, Constraint):
            raise AssertionError(f'base_constraint must be a Constraint, got {type(base_constraint).__name__}')
        self.base_constraint = base_constraint
        super().__init__()

    @property
    def is_discrete(self) -> bool:
        return self.base_constraint.is_discrete

    @property
    def event_dim(self) -> int:
        return self.base_constraint.event_dim

    def check(self, value):
        unsqueezed_value = value.unsqueeze(-1 - self.event_dim)
        result = self.base_constraint.check(unsqueezed_value)
        if value.dim() < self.event_dim:
            raise ValueError(f'Expected value.dim() >= {self.event_dim} but got {value.dim()}')
        num_dim_to_keep = value.dim() - self.event_dim
        result = result.reshape(result.shape[:num_dim_to_keep] + (-1,))
        result = result.all(-1)
        return result

    def __repr__(self):
        return f'{self.__class__.__name__}({repr(self.base_constraint)})'

# --- helper: torch.distributions.constraints.Constraint ---
class Constraint:
    is_discrete = False
    event_dim = 0

    def check(self, value):
        raise NotImplementedError

    def __repr__(self):
        return self.__class__.__name__[1:] + '()'

class GeneralizedPareto(Distribution):
    arg_constraints = {'loc': constraints.real, 'scale': constraints.positive, 'concentration': constraints.real}
    has_rsample = True

    def __init__(self, loc, scale, concentration, validate_args=None):
        self.loc, self.scale, self.concentration = broadcast_all(loc, scale, concentration)
        if isinstance(loc, Number) and isinstance(scale, Number) and isinstance(concentration, Number):
            batch_shape = torch.Size()
        else:
            batch_shape = self.loc.size()
        super().__init__(batch_shape, validate_args=validate_args)

    def expand(self, batch_shape, _instance=None):
        new = self._get_checked_instance(GeneralizedPareto, _instance)
        batch_shape = torch.Size(batch_shape)
        new.loc = self.loc.expand(batch_shape)
        new.scale = self.scale.expand(batch_shape)
        new.concentration = self.concentration.expand(batch_shape)
        super(GeneralizedPareto, new).__init__(batch_shape, validate_args=False)
        new._validate_args = self._validate_args
        return new

    def rsample(self, sample_shape=torch.Size()):
        shape = self._extended_shape(sample_shape)
        u = torch.rand(shape, dtype=self.loc.dtype, device=self.loc.device)
        return self.icdf(u)

    def log_prob(self, value):
        if self._validate_args:
            self._validate_sample(value)
        z = self._z(value)
        eq_zero = torch.isclose(self.concentration, torch.tensor(0.0))
        safe_conc = torch.where(eq_zero, torch.ones_like(self.concentration), self.concentration)
        y = 1 / safe_conc + torch.ones_like(z)
        where_nonzero = torch.where(y == 0, y, y * torch.log1p(safe_conc * z))
        log_scale = math.log(self.scale) if isinstance(self.scale, Real) else self.scale.log()
        return -log_scale - torch.where(eq_zero, z, where_nonzero)

    def log_survival_function(self, value):
        if self._validate_args:
            self._validate_sample(value)
        z = self._z(value)
        eq_zero = torch.isclose(self.concentration, torch.tensor(0.0))
        safe_conc = torch.where(eq_zero, torch.ones_like(self.concentration), self.concentration)
        where_nonzero = -torch.log1p(safe_conc * z) / safe_conc
        return torch.where(eq_zero, -z, where_nonzero)

    def log_cdf(self, value):
        return torch.log1p(-torch.exp(self.log_survival_function(value)))

    def cdf(self, value):
        return torch.exp(self.log_cdf(value))

    def icdf(self, value):
        loc = self.loc
        scale = self.scale
        concentration = self.concentration
        eq_zero = torch.isclose(concentration, torch.zeros_like(concentration))
        safe_conc = torch.where(eq_zero, torch.ones_like(concentration), concentration)
        logu = torch.log1p(-value)
        where_nonzero = loc + scale / safe_conc * torch.expm1(-safe_conc * logu)
        where_zero = loc - scale * logu
        return torch.where(eq_zero, where_zero, where_nonzero)

    def _z(self, x):
        return (x - self.loc) / self.scale

    @property
    def mean(self):
        concentration = self.concentration
        valid = concentration < 1
        safe_conc = torch.where(valid, concentration, 0.5)
        result = self.loc + self.scale / (1 - safe_conc)
        return torch.where(valid, result, nan)

    @property
    def variance(self):
        concentration = self.concentration
        valid = concentration < 0.5
        safe_conc = torch.where(valid, concentration, 0.25)
        result = self.scale ** 2 / ((1 - safe_conc) ** 2 * (1 - 2 * safe_conc))
        return torch.where(valid, result, nan)

    def entropy(self):
        ans = torch.log(self.scale) + self.concentration + 1
        return torch.broadcast_to(ans, self._batch_shape)

    @property
    def mode(self):
        return self.loc

    @constraints.dependent_property(is_discrete=False, event_dim=0)
    def support(self):
        lower = self.loc
        upper = torch.where(self.concentration < 0, lower - self.scale / self.concentration, inf)
        return constraints.interval(lower, upper)

class InverseGamma(TransformedDistribution):
    arg_constraints = {'concentration': constraints.positive, 'rate': constraints.positive}
    support = constraints.positive
    has_rsample = True
    base_dist: Gamma

    def __init__(self, concentration: Tensor | float, rate: Tensor | float, validate_args: bool | None=None) -> None:
        base_dist = Gamma(concentration, rate, validate_args=validate_args)
        neg_one = -base_dist.rate.new_ones(())
        super().__init__(base_dist, PowerTransform(neg_one), validate_args=validate_args)

    def expand(self, batch_shape, _instance=None):
        new = self._get_checked_instance(InverseGamma, _instance)
        return super().expand(batch_shape, _instance=new)

    @property
    def concentration(self) -> Tensor:
        return self.base_dist.concentration

    @property
    def rate(self) -> Tensor:
        return self.base_dist.rate

    @property
    def mean(self) -> Tensor:
        result = self.rate / (self.concentration - 1)
        return torch.where(self.concentration > 1, result, torch.inf)

    @property
    def mode(self) -> Tensor:
        return self.rate / (self.concentration + 1)

    @property
    def variance(self) -> Tensor:
        result = self.rate.square() / ((self.concentration - 1).square() * (self.concentration - 2))
        return torch.where(self.concentration > 2, result, torch.inf)

    def entropy(self):
        return self.concentration + self.rate.log() + self.concentration.lgamma() - (1 + self.concentration) * self.concentration.digamma()

class CustomDecompTable(dict[torch._ops.OperatorBase, Callable]):

    def __init__(self):
        super().__init__()
        from torch._decomp import _core_aten_decompositions_post_autograd
        self.decomp_table = _core_aten_decompositions_post_autograd()
        for op in _collect_all_valid_cia_ops_for_aten_namespace():
            if op not in PRESERVED_ATEN_CIA_OPS and op not in self.decomp_table:
                self.decomp_table[op] = _get_decomp_for_cia(op)
        self.deleted_custom_ops = set()
        self.has_materialized = False

    def __getitem__(self, key):
        self._materialize_if_needed()
        return self.decomp_table.__getitem__(key)

    def __setitem__(self, key, value) -> None:
        self.decomp_table.__setitem__(key, value)
        if key in self.deleted_custom_ops:
            self.deleted_custom_ops.remove(key)

    def keys(self):
        self._materialize_if_needed()
        return self.decomp_table.keys()

    def __delitem__(self, key) -> None:
        self.pop(key)

    def update(self, other_dict):
        for k, v in other_dict.items():
            self.decomp_table.__setitem__(k, v)

    def __missing__(self, key) -> bool:
        return not self.__contains__(key)

    def __contains__(self, key) -> bool:
        self._materialize_if_needed()
        return self.decomp_table.__contains__(key)

    def __len__(self) -> int:
        self._materialize_if_needed()
        return self.decomp_table.__len__()

    def __iter__(self):
        self._materialize_if_needed()
        return self.decomp_table.__iter__()

    def __reversed__(self):
        self._materialize_if_needed()
        return self.decomp_table.__reversed__()

    def copy(self) -> 'CustomDecompTable':
        new_dict = CustomDecompTable()
        new_dict.decomp_table = self.decomp_table.copy()
        new_dict.deleted_custom_ops = self.deleted_custom_ops.copy()
        new_dict.has_materialized = self.has_materialized
        return new_dict

    def pop(self, *args):

        def _pop_if_can(key):
            if _is_aten_op(key):
                return self.decomp_table.pop(key)
            if key in self.decomp_table:
                self.deleted_custom_ops.add(key)
                return self.decomp_table.pop(key)
            if key in self.deleted_custom_ops:
                raise KeyError(f"{key} doesn't exist in the table")
            self.deleted_custom_ops.add(key)
            return _get_decomp_for_cia(key)
        if len(args) == 1:
            return _pop_if_can(args[0])
        if len(args) == 2:
            try:
                return _pop_if_can(args[0])
            except KeyError:
                return args[1]

    def items(self):
        self._materialize_if_needed()
        return self.decomp_table.items()

    def materialize(self) -> dict[torch._ops.OperatorBase, Callable]:
        for op in _collect_all_valid_cia_ops():
            if _is_aten_op(op):
                continue
            elif op in self.decomp_table:
                continue
            elif op not in self.deleted_custom_ops:
                self.decomp_table[op] = _get_decomp_for_cia(op)
        self.has_materialized = True
        self.deleted_custom_ops = set()
        return {**self.decomp_table}

    def _materialize_if_needed(self) -> None:
        if not self.has_materialized:
            self.materialize()

class AdditionalInputs:

    def __init__(self):
        self._examples = []

    def add(self, args, kwargs=None):
        if type(args) is not tuple:
            raise AssertionError(f'Representative args {args} must be a tuple')
        if kwargs is not None and type(kwargs) is not dict:
            raise AssertionError(f'Representative kwargs {kwargs} must be None or a dict')
        self._examples.append((args, kwargs))

    def dynamic_shapes(self, m, args, kwargs=None):
        dynamic_shapes, *other_dynamic_shapes = [_tree_map_with_path(lambda path, t: tuple(t.shape) if isinstance(t, torch.Tensor) else t, _combine_args(m, args, kwargs)) for args, kwargs in [(args, kwargs), *self._examples]]

        def _mark_dynamism(v, *other_vs):
            if not all((type(v) is type(other) for other in other_vs)):
                raise ValueError(f'The following inputs were found to have differing types, so they cannot be marked as dynamic: {(v,) + other_vs}.')
            if isinstance(v, int) and (not isinstance(v, bool)):
                if all((other_v == v for other_v in other_vs)):
                    return None
                else:
                    return Dim.DYNAMIC
            else:
                if not all((other_v == v for other_v in other_vs)):
                    raise ValueError(f'The following inputs were found to have differing values, but they cannot be marked as dynamic: {(v,) + other_vs}.')
                return None
        return tree_map(_mark_dynamism, dynamic_shapes, *other_dynamic_shapes, is_leaf=lambda i: type(i) is int)

    def verify(self, ep):
        epm = ep.module()
        for args, kwargs in self._examples:
            torch.export._unlift._check_input_constraints_for_module(epm, args, kwargs or {})

# --- helper: torch.export.dynamic_shapes.Dim ---
class Dim:
    AUTO = _DimHint.AUTO()
    DYNAMIC = _DimHint.DYNAMIC()
    STATIC = _DimHint.STATIC()

    def __init__(self, name: str, *, min: int | None=None, max: int | None=None):
        from torch.utils._sympy.numbers import int_oo
        _min = 0 if min is None else min
        _max = int_oo if max is None else max
        if not _max > _min:
            raise AssertionError(f'Cannot create Dim with inconsistent min={min}, max={max}')
        if not name.isidentifier():
            raise AssertionError(f'Dim name must be a valid identifier, got {name}')
        self.__name__ = name
        self.min = _min
        self.max = _max

    def __add__(self, other) -> 'Dim':
        if type(other) is not int:
            raise NotImplementedError(f'Attempted to add {other} to {self.__name__}, where an integer was expected. (Only increasing linear operations with integer coefficients are supported.)')
        return self._derive(lambda x: x + other)

    def __radd__(self, other) -> 'Dim':
        return self + other

    def __sub__(self, other) -> 'Dim':
        if type(other) is not int:
            raise NotImplementedError(f'Attempted to subtract {other} from {self.__name__}, where an integer was expected. (Only increasing linear operations with integer coefficients are supported.)')
        return self._derive(lambda x: x - other)

    def __rsub__(self, other) -> 'Dim':
        raise NotImplementedError(f'Attempted to negate {self.__name__}. (Only increasing linear operations with integer coefficients are supported.)')

    def __mul__(self, other) -> 'Dim':
        if type(other) is not int or other <= 0:
            raise NotImplementedError(f'Attempted to multiply {other} with {self.__name__}, where a positive integer was expected. (Only increasing linear operations with integer coefficients are supported.)')
        return self._derive(lambda x: x * other)

    def __rmul__(self, other) -> 'Dim':
        return self * other

    def _derived_name(self, fn) -> str:
        from sympy import sympify
        return str(fn(sympify(self.__name__)))

    def _derive(self, fn) -> 'Dim':
        return _DerivedDim(self._derived_name(fn), self, fn)

    @staticmethod
    def _readable(name: str, min_: int, max_: int) -> str:
        from torch.utils._sympy.numbers import int_oo
        if min_ == 2:
            min_ = None
        if max_ == int_oo:
            max_ = None
        if min_ is None and max_ is None:
            return f"Dim('{name}')"
        if min_ is None:
            return f"Dim('{name}', max={max_})"
        if max_ is None:
            return f"Dim('{name}', min={min_})"
        return f"Dim('{name}', min={min_}, max={max_})"

    def __repr__(self):
        return Dim._readable(self.__name__, self.min, self.max)

# --- helper: torch.export.dynamic_shapes._combine_args ---
def _combine_args(f, args, kwargs) -> dict[str, Any]:
    if isinstance(f, ExportedProgram):
        f = f.module()
    signature = inspect.signature(f.forward) if isinstance(f, torch.nn.Module) else inspect.signature(f)
    kwargs = kwargs if kwargs is not None else {}
    return signature.bind(*args, **kwargs).arguments

# --- helper: torch.export.dynamic_shapes._tree_map_with_path ---
def _tree_map_with_path(func: Callable[..., Any], tree: Any, *dynamic_shapes: Any, tree_name: str | None=None) -> Any:

    def is_leaf(t):
        return _get_node_type(t) not in BUILTIN_TYPES

    def f(path, t, *dynamic_shapes):
        typ = _get_node_type(t)
        if typ in SUPPORTED_NODES:
            return tree_map_with_path(f, SUPPORTED_NODES[typ].flatten_fn(t)[0], *dynamic_shapes, is_leaf=is_leaf)
        else:
            return func(path, t, *dynamic_shapes)
    try:
        return tree_map_with_path(f, tree, *dynamic_shapes, is_leaf=is_leaf)
    except ValueError as e:
        if 'mismatch' in e.args[0]:
            if not dynamic_shapes:
                raise AssertionError('Cannot be a mismatch if there is no dynamic_shapes') from None
            if not tree_name:
                raise AssertionError('Must provide a tree_name when there might be a mismatch') from None

            def _key(type_, context, i):
                if type_ is dict:
                    return MappingKey(context[i])
                if type_ in (list, tuple):
                    if context is not None:
                        raise AssertionError(f'expected context to be None for type {type_}, got {context}')
                    return SequenceKey(i)
                raise AssertionError(f'Did not expect type {type_}')

            def raise_mismatch_error(msg):
                from torch._dynamo.exc import UserError, UserErrorType
                raise UserError(UserErrorType.INVALID_INPUT, f'Detected mismatch between the structure of `{tree_name}` and `dynamic_shapes`: {msg}', case_name='dynamic_shapes_validation')

            def _compare(treespec: TreeSpec, other_treespec: TreeSpec, path: KeyPath) -> None:
                rendered_path = keystr(path)
                if treespec.is_leaf():
                    return
                if other_treespec.is_leaf():
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {treespec.type}, but `dynamic_shapes{rendered_path}` is not')
                if treespec.type != other_treespec.type:
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` is a {treespec.type}, but `dynamic_shapes{rendered_path}` is a {other_treespec.type}')
                if treespec.num_children != other_treespec.num_children:
                    raise_mismatch_error(f'`{tree_name}{rendered_path}` has {treespec.num_children} elements, but `dynamic_shapes{rendered_path}` has {other_treespec.num_children} elements')
                if treespec.type is dict:
                    if set(treespec.context) != set(other_treespec.context):
                        raise_mismatch_error(f'`{tree_name}{rendered_path}` has keys {treespec.context}, but `dynamic_shapes{rendered_path}` has keys {other_treespec.context}')
                    _remap = dict(zip(other_treespec.context, other_treespec.children()))
                    other_children = [_remap[k] for k in treespec.context]
                else:
                    other_children = other_treespec.children()
                for i, (child, other_child) in enumerate(zip(treespec.children(), other_children)):
                    _compare(child, other_child, path + (_key(treespec.type, treespec.context, i),))
            treespec = tree_structure(tree, is_leaf=is_leaf)
            for other_tree in dynamic_shapes:
                other_treespec = tree_structure(other_tree, is_leaf)
                _compare(treespec, other_treespec, ())
        raise

def tree_map(func: Callable[..., Any], tree: PyTree, *rests: PyTree, is_leaf: Callable[[PyTree], bool] | None=None) -> PyTree:
    leaves, treespec = tree_flatten(tree, is_leaf=is_leaf)
    flat_args = [leaves] + [treespec.flatten_up_to(r) for r in rests]
    return treespec.unflatten(map(func, *flat_args))

# --- helper: torch.utils._pytree.tree_flatten ---
def tree_flatten(tree: PyTree, is_leaf: Callable[[PyTree], bool] | None=None) -> tuple[list[Any], TreeSpec]:

    def helper(node: PyTree, leaves: list[Any]) -> TreeSpec:
        if tree_is_leaf(node, is_leaf=is_leaf):
            leaves.append(node)
            return _LEAF_SPEC
        node_type = _get_node_type(node)
        flatten_fn = SUPPORTED_NODES[node_type].flatten_fn
        children, context = flatten_fn(node)
        subspecs = [helper(child, leaves) for child in children]
        return TreeSpec(node_type, context, subspecs)
    leaves: list[Any] = []
    treespec = helper(tree, leaves)
    return (leaves, treespec)

