    from ._trace import _export
    if not isinstance(mod, torch.nn.Module):
        raise ValueError(f'Expected `mod` to be an instance of `torch.nn.Module`, got {type(mod)}.')
    if isinstance(mod, torch.jit.ScriptModule):
