        if isinstance(e, (torch.fx.experimental.symbolic_shapes.GuardOnDataDependentSymNode, torch._subclasses.fake_tensor.UnsupportedOperatorException, torch._dynamo.exc.UserError, torch.fx.experimental.symbolic_shapes.ConstraintViolationError)):
