class InterpreterModuleDispatcher(_SubmoduleBase, torch.nn.Module):

    def __init__(self, attrs: set[str], call_modules: list[InterpreterModule]):
        super().__init__()
        if not call_modules:
            raise AssertionError('call_modules must not be empty')
        self._modules = call_modules[0]._modules
        for accessor in attrs:
            setattr(self, accessor, getattr(call_modules[0], accessor))
        self._ty = call_modules[0]._ty
        self._call_modules = call_modules
        self._num_calls = 0

    def forward(self, *args, **kwargs):
        call_module = self._call_modules[self._num_calls]
        self._num_calls = (self._num_calls + 1) % len(self._call_modules)
        try:
            return call_module(*args, **kwargs)
        except Exception:
            self._num_calls = 0
            raise

    def call_modules(self):
        return self._call_modules

    def print_readable(self, print_output=True, include_stride=False, include_device=False, colored=False):
        outputs = [mod.print_readable(print_output, include_stride, include_device, colored) for mod in self._call_modules]
        return '\n'.join(outputs)

# --- helper: torch.export.unflatten.InterpreterModule ---
class InterpreterModule(_SubmoduleBase, torch.nn.Module):
    graph_module: torch.fx.GraphModule | None

    def __init__(self, graph: torch.fx.Graph, ty: str | None=None):
        super().__init__()
        self.graph = graph
        self._ty = ty
        self.graph.owning_module = self
        self._run_with_interpreter = RUN_WITH_INTERPRETER

    def forward(self, *args, **kwargs):
        if self.graph_module is None:
            raise AssertionError("Didn't finalize this InterpreterModule")
        if not is_fx_symbolic_tracing() and (torch.compiler.is_dynamo_compiling() or not self._run_with_interpreter):
            return type(self.graph_module).forward(self, *args, **kwargs)
        else:
            if kwargs:
                arg_list = list(args)
                kwarg_names = self.arg_names[len(arg_list):]
                arg_list.extend((kwargs[kwarg_name] for kwarg_name in kwarg_names if kwarg_name in kwargs))
                if len(kwarg_names) != len(kwargs):
                    raise AssertionError(f'kwarg_names length {len(kwarg_names)} does not match kwargs length {len(kwargs)}')
                if len(arg_list) != len(self.arg_names):
                    raise AssertionError(f'arg_list length {len(arg_list)} does not match arg_names length {len(self.arg_names)}')
                args = tuple(arg_list)
            return torch.fx.Interpreter(self, graph=self.graph).run(*args, enable_io_processing=False)

    def finalize(self):
        self.__dict__['graph_module'] = torch.fx.GraphModule(self, self.graph)
        self.graph.lint()
        self.arg_names = []
        for node in self.graph.nodes:
            if node.op == 'placeholder':
                self.arg_names.append(node.target)

    def print_readable(self, print_output=True, include_stride=False, include_device=False, colored=False):
        return _print_readable(self, 'InterpreterModule', print_output, include_stride, include_device, colored)

