def functional_call(module: torch.nn.Module, parameter_and_buffer_dicts: dict[str, Tensor] | Sequence[dict[str, Tensor]], args: Any=None, kwargs: dict[str, Any] | None=None, *, tie_weights: bool=True, strict: bool=False) -> Any:
    if isinstance(parameter_and_buffer_dicts, dict):
        parameters_and_buffers = parameter_and_buffer_dicts
    elif isinstance(parameter_and_buffer_dicts, Sequence):
        if not all((isinstance(d, dict) for d in parameter_and_buffer_dicts)):
            raise ValueError('Expected all elements of parameter_and_buffer_dicts to be dictionaries')
        all_keys = [k for d in parameter_and_buffer_dicts for k in d]
        all_keys_counter: dict[str, int] = {}
        for k in all_keys:
            v = all_keys_counter.get(k, 0)
            all_keys_counter[k] = v + 1
        repeated_keys = [key for key, n in all_keys_counter.items() if n > 1]
        if len(repeated_keys) > 0:
            raise ValueError(f'{repeated_keys} appeared in multiple dictionaries; behavior of functional call is ambiguous')
        parameters_and_buffers = {k: v for d in parameter_and_buffer_dicts for k, v in d.items()}
    else:
        raise ValueError(f'Expected parameter_and_buffer_dicts to be a dict, or a list/tuple of dicts, but got {type(parameter_and_buffer_dicts)}')
    return nn.utils.stateless._functional_call(module, parameters_and_buffers, args, kwargs, tie_weights=tie_weights, strict=strict)

def unravel_index(indices: Tensor, shape: int | Sequence[int] | torch.Size) -> tuple[Tensor, ...]:
    if has_torch_function_unary(indices):
        return handle_torch_function(unravel_index, (indices,), indices, shape=shape)
    res_tensor = _unravel_index(indices, shape)
    return res_tensor.unbind(-1)

# --- helper: torch.functional._unravel_index ---
def _unravel_index(indices: Tensor, shape: int | Sequence[int]) -> Tensor:
    torch._check_type(not indices.is_complex() and (not indices.is_floating_point()) and (indices.dtype != torch.bool), lambda: f"expected 'indices' to be integer dtype, but got {indices.dtype}")
    torch._check_type(isinstance(shape, (int, torch.SymInt, Sequence)), lambda: f"expected 'shape' to be int or sequence of ints, but got {type(shape)}")
    if isinstance(shape, (int, torch.SymInt)):
        shape = torch.Size([shape])
    else:
        for dim in shape:
            torch._check_type(isinstance(dim, (int, torch.SymInt)), lambda: f"expected 'shape' sequence to only contain ints, but got {type(dim)}")
        shape = torch.Size(shape)
    torch._check_value(all((dim >= 0 for dim in shape)), lambda: f"'shape' cannot have negative values, but got {tuple(shape)}")
    coefs = list(reversed(list(itertools.accumulate(reversed(shape[1:] + torch.Size([1])), func=operator.mul))))
    return indices.unsqueeze(-1).floor_divide(torch.tensor(coefs, device=indices.device, dtype=torch.int64)) % torch.tensor(shape, device=indices.device, dtype=torch.int64)

def fuse(model: torch.nn.Module, inplace=False, no_trace=False) -> torch.nn.Module:
    patterns = [(nn.Conv1d, nn.BatchNorm1d), (nn.Conv2d, nn.BatchNorm2d), (nn.Conv3d, nn.BatchNorm3d), (nn.Linear, nn.BatchNorm1d)]
    if not inplace:
        model = copy.deepcopy(model)
    if not no_trace or not isinstance(model, torch.fx.GraphModule):
        fx_model = fx.symbolic_trace(model)
    else:
        fx_model = model
    modules = dict(fx_model.named_modules())
    new_graph = copy.deepcopy(fx_model.graph)
    for pattern in patterns:
        for node in new_graph.nodes:
            if matches_module_pattern(pattern, node, modules):
                if len(node.args[0].users) > 1:
                    continue
                first_layer = modules[node.args[0].target]
                bn = modules[node.target]
                if not bn.track_running_stats:
                    continue
                if pattern[0] in [nn.Conv1d, nn.Conv2d, nn.Conv3d]:
                    fused_layer = fuse_conv_bn_eval(first_layer, bn)
                else:
                    fused_layer = fuse_linear_bn_eval(first_layer, bn)
                replace_node_module(node.args[0], modules, fused_layer)
                node.replace_all_uses_with(node.args[0])
                new_graph.erase_node(node)
    return fx.GraphModule(fx_model, new_graph)

# --- helper: torch.fx.experimental.optimization.matches_module_pattern ---
def matches_module_pattern(pattern: Iterable[type], node: fx.Node, modules: dict[str, Any]):
    if len(node.args) == 0:
        return False
    nodes: tuple[Any, fx.Node] = (node.args[0], node)
    for expected_type, current_node in zip(pattern, nodes):
        if not isinstance(current_node, fx.Node):
            return False
        if current_node.op != 'call_module':
            return False
        if not isinstance(current_node.target, str):
            return False
        if current_node.target not in modules:
            return False
        if type(modules[current_node.target]) is not expected_type:
            return False
    return True

# --- helper: torch.fx.experimental.optimization.replace_node_module ---
def replace_node_module(node: fx.Node, modules: dict[str, Any], new_module: torch.nn.Module):
    if not isinstance(node.target, str):
        raise AssertionError(f'Expected str target, got {type(node.target)}')
    parent_name, name = _parent_name(node.target)
    modules[node.target] = new_module
    setattr(modules[parent_name], name, new_module)

def get_proxy_mode() -> Optional[ProxyTorchDispatchMode]:
    pre_dispatch_mode = torch._ops._get_dispatch_mode_pre_dispatch(torch._C._TorchDispatchModeKey.PROXY)
    mode = torch._C._get_dispatch_mode(torch._C._TorchDispatchModeKey.PROXY)
    if not (pre_dispatch_mode is None or mode is None):
        raise AssertionError(f'pre_dispatch_mode={pre_dispatch_mode}, mode={mode}')
