class ProxyTorchDispatchMode(TorchDispatchMode):

    @property
    def enable_tracing(self) -> bool:
        return True

    def __init__(self, tracer: _ProxyTracer, tracing_mode: str, pre_dispatch: bool=False, _allow_fake_constant: bool=False, _error_on_data_dependent_ops: bool=True) -> None:
        dk = torch._C.DispatchKey.PreDispatch if pre_dispatch else None
        super().__init__(dk)
        self.tracer = tracer
        self.tracing_mode = tracing_mode
        self.pre_dispatch = pre_dispatch
        self._allow_fake_constant = _allow_fake_constant
        self._error_on_data_dependent_ops = _error_on_data_dependent_ops
        self._mode_key = torch._C._TorchDispatchModeKey.PROXY
        self.enter_stack: list[Optional[ProxyTorchDispatchMode]] = []
        self.decomp_layers: int = 0
        self._invoke_subgraph_names: set[str] = set()
        self._invoke_subgraph_cache: dict[torch.fx.GraphModule | FunctionalizeCtxWrapper, str] = {}
        from torch._inductor import config
        self.emulate_precision_casts: bool = config.emulate_precision_casts

    @count
    def __torch_dispatch__(self, func: OpOverload, types: tuple[torch._C._TensorMeta, ...], args: tuple[object, ...]=(), kwargs: Optional[dict[str, object]]=None) -> object:
        with set_original_aten_op(func):
            kwargs = kwargs or {}
            if func == prim.device.default:
                return func(*args, **kwargs)
            return proxy_call(self, func, self.pre_dispatch, args, kwargs)

    def __enter__(self) -> Self:
        maybe_prev_proxy_mode = _unset_infra_mode(torch._C._TorchDispatchModeKey.PROXY)
        self.enter_stack.append(maybe_prev_proxy_mode)
        return super().__enter__()

    def __exit__(self, exc_type: Optional[type[BaseException]], exc_value: Optional[BaseException], traceback: Optional[types.TracebackType]) -> Optional[bool]:
        b = super().__exit__(exc_type, exc_value, traceback)
        mb_previous_proxy_mode = self.enter_stack.pop()
        if mb_previous_proxy_mode is not None:
            _push_mode(mb_previous_proxy_mode)
        return b

    @classmethod
    def is_infra_mode(cls) -> bool:
        return True

    def __sym_dispatch__(self, func: OpOverload, types: tuple[torch._C._TensorMeta, ...], args: tuple[object, ...], kwargs: dict[str, object]) -> object:
        if func is operator.mul:
            if isinstance(args[1], int) and args[1] == 1:
                return args[0]
            elif isinstance(args[0], int) and args[0] == 1:
                return args[1]
        if kwargs:
            raise AssertionError('Expected no keyword arguments')
        out = func(*args, **kwargs)
        _sym_register(self.tracer, func, args, out)
        return out

def autograd_would_have_decomposed(func: torch._ops.OpOverload, flat_args: Sequence[torch.Tensor | object]) -> bool:
    has_backend_registration = False
    for a in flat_args:
        if isinstance(a, torch.Tensor):
            backend_key = torch._C._parse_dispatch_key(torch._C._dispatch_key_for_device(a.device.type))
            if backend_key is None:
                raise AssertionError(f'failed to parse dispatch key for device {a.device.type}')
            has_backend_registration = torch._C._dispatch_has_kernel_for_dispatch_key(func.name(), backend_key)
            break
    return not has_backend_registration

