class MinMaxBase(Expr, LatticeOp):

    def __new__(cls, *original_args, **assumptions):
        from sympy.core.parameters import global_parameters
        evaluate = assumptions.pop('evaluate', global_parameters.evaluate)
        args = (sympify(arg) for arg in original_args)
        unique_summations_symbols = None if not evaluate else cls._satisfy_unique_summations_symbols(original_args)
        if evaluate:
            try:
                args = frozenset(cls._new_args_filter(args))
            except ShortCircuit:
                return cls.zero
            if unique_summations_symbols is None:
                args = cls._collapse_arguments(args, **assumptions)
                args = cls._find_localzeros(args, **assumptions)
        args = frozenset(args)
        if not args:
            return cls.identity
        if len(args) == 1:
            return list(args).pop()
        obj = Expr.__new__(cls, *ordered(args), **assumptions)
        obj._argset = args
        obj.unique_summations_symbols = unique_summations_symbols
        return obj

    @classmethod
    def _satisfy_unique_summations_symbols(cls, args) -> set[sympy.core.symbol.Symbol] | None:
        if len(args) != 2:
            return None
        lhs, rhs = (args[1], args[0]) if isinstance(args[1], MinMaxBase) else (args[0], args[1])
        if not _is_symbols_binary_summation(rhs):
            return None
        if _is_symbols_binary_summation(lhs):
            return cls._unique_symbols(args)
        if isinstance(lhs, MinMaxBase):
            lhs_unique_summations_symbols = getattr(lhs, 'unique_summations_symbols', None)
            if lhs_unique_summations_symbols is not None:
                return cls._unique_symbols([rhs], lhs_unique_summations_symbols)
        return None

    @classmethod
    def _unique_symbols(cls, args, initial_set: set[sympy.core.symbol.Symbol] | None=None) -> set[sympy.core.symbol.Symbol] | None:
        seen_symbols = set() if initial_set is None else initial_set
        for arg in args:
            for element in arg.atoms():
                if not isinstance(element, sympy.core.symbol.Symbol):
                    return None
                elif element in seen_symbols:
                    return None
                else:
                    seen_symbols.add(element)
        return seen_symbols

    @classmethod
    def _collapse_arguments(cls, args, **assumptions):
        if not args:
            return args
        args = list(ordered(args))
        if cls is Min:
            other = Max
        else:
            other = Min
        if args[0].is_number:
            sifted = mins, maxs = ([], [])
            for i in args:
                for v in walk(i, Min, Max):
                    if v.args[0].is_comparable:
                        sifted[isinstance(v, Max)].append(v)
            small = Min.identity
            for i in mins:
                v = i.args[0]
                if v.is_number and (v < small) == True:
                    small = v
            big = Max.identity
            for i in maxs:
                v = i.args[0]
                if v.is_number and (v > big) == True:
                    big = v
            if cls is Min:
                for arg in args:
                    if not arg.is_number:
                        break
                    if (arg < small) == True:
                        small = arg
            elif cls == Max:
                for arg in args:
                    if not arg.is_number:
                        break
                    if (arg > big) == True:
                        big = arg
            T = None
            if cls is Min:
                if small != Min.identity:
                    other = Max
                    T = small
            elif big != Max.identity:
                other = Min
                T = big
            if T is not None:
                for i in range(len(args)):
                    a = args[i]
                    if isinstance(a, other):
                        a0 = a.args[0]
                        if (a0 > T if other == Max else a0 < T) == True:
                            args[i] = cls.identity

        def do(ai, a):
            if not isinstance(ai, (Min, Max)):
                return ai
            cond = a in ai.args
            if not cond:
                return ai.func(*[do(i, a) for i in ai.args], evaluate=False)
            if isinstance(ai, cls):
                return ai.func(*[do(i, a) for i in ai.args if i != a], evaluate=False)
            return a
        for i, a in enumerate(args):
            args[i + 1:] = [do(ai, a) for ai in args[i + 1:]]

        def factor_minmax(args):
            is_other = lambda arg: isinstance(arg, other)
            other_args, remaining_args = sift(args, is_other, binary=True)
            if not other_args:
                return args
            arg_sets = [set(arg.args) for arg in other_args]
            common = set.intersection(*arg_sets)
            if not common:
                return args
            new_other_args = list(common)
            arg_sets_diff = [arg_set - common for arg_set in arg_sets]
            if all(arg_sets_diff):
                other_args_diff = [other(*s, evaluate=False) for s in arg_sets_diff]
                new_other_args.append(cls(*other_args_diff, evaluate=False))
            other_args_factored = other(*new_other_args, evaluate=False)
            return remaining_args + [other_args_factored]
        if len(args) > 1:
            args = factor_minmax(args)
        return args

    @classmethod
    def _new_args_filter(cls, arg_sequence):
        for arg in arg_sequence:
            if not isinstance(arg, Expr) or arg.is_extended_real is False or (arg.is_number and (not arg.is_comparable)):
                raise ValueError(f"The argument '{arg}' is not comparable.")
            if arg == cls.zero:
                raise ShortCircuit(arg)
            elif arg == cls.identity:
                continue
            elif arg.func == cls:
                yield from arg.args
            else:
                yield arg

    @classmethod
    def _find_localzeros(cls, values, **options):
        other_values = set()
        num_value = None
        for arg in values:
            if arg.is_Number:
                if num_value is None:
                    num_value = arg
                elif cls is Max:
                    num_value = max(num_value, arg)
                elif cls is Min:
                    num_value = min(num_value, arg)
                else:
                    raise AssertionError(f'impossible {cls}')
            else:
                other_values.add(arg)
        if num_value is None:
            return other_values
        if len(other_values) == 0:
            return {num_value}
        if len(other_values) == 1:
            other_value = next(iter(other_values))
            if num_value in (0.0, 0) and other_value.is_nonnegative:
                return other_values if cls is Max else {num_value}
            if num_value == 1 and other_value.is_positive:
                return other_values if cls is Max else {num_value}
        other_values.add(num_value)
        return other_values
