def canonicalize_bool_expr(expr: _T) -> _T:
    if not isinstance(expr, (sympy.Rel, sympy.And, sympy.Or, sympy.Not, sympy.Eq, sympy.Ne)):
        return expr
    if isinstance(expr, (sympy.And, sympy.Or, sympy.Not)):
        expr = sympy.logic.boolalg.to_cnf(expr)
    return _canonicalize_bool_expr_impl(expr)

# --- helper: torch.fx.experimental.symbolic_shapes._canonicalize_bool_expr_impl ---
def _canonicalize_bool_expr_impl(expr: SympyBoolean) -> SympyBoolean:
    if isinstance(expr, (sympy.And, sympy.Or)):
        return type(expr)(*map(canonicalize_bool_expr, expr.args))
    opposite = {sympy.Gt: sympy.Lt, sympy.Ge: sympy.Le}
    t: Union[type[Any]]
    if isinstance(expr, tuple(opposite.keys())):
        rhs = expr.lhs - expr.rhs
        t = opposite[type(expr)]
    else:
        if not isinstance(expr, (sympy.Lt, sympy.Le, sympy.Eq, sympy.Ne)):
            raise AssertionError(f'Expected Lt/Le/Eq/Ne, got {type(expr)}')
        rhs = expr.rhs - expr.lhs
        t = type(expr)

    def is_neg(t: sympy.Expr) -> bool:
        return t.is_Number and t.is_negative or (isinstance(t, sympy.Mul) and t.args[0].is_Number and t.args[0].is_negative)
    lhs = S.Zero
    rhs = _reduce_to_lowest_terms(rhs)
    if isinstance(rhs, sympy.Add):
        pos = []
        neg = []
        for term in rhs.args:
            if is_neg(term):
                neg.append(-term)
            else:
                pos.append(term)
        rhs = _sympy_from_args(sympy.Add, pos, sort=False, is_commutative=True)
        lhs = _sympy_from_args(sympy.Add, neg, sort=True, is_commutative=True)
    elif is_neg(rhs):
        lhs, rhs = (-rhs, S.Zero)
    return t(lhs, rhs, evaluate=False)

def has_free_unbacked_symbols(x: IterateExprs) -> bool:
    from sympy.core.traversal import iterargs
    for s in _iterate_exprs(x):
        for arg in iterargs(s):
            if arg.is_Symbol and symbol_is_type(arg, (SymT.UNBACKED_INT, SymT.UNBACKED_FLOAT)):
                return True
    return False

# --- helper: torch.fx.experimental.symbolic_shapes._iterate_exprs ---
def _iterate_exprs(val: IterateExprs) -> Iterator[sympy.Basic]:
    if isinstance(val, SymTypes):
        if is_symbolic(val):
            yield val.node.expr
    elif isinstance(val, SymNode):
        yield val.expr
    elif isinstance(val, sympy.Basic):
        yield val
    elif isinstance(val, (int, float, bool)):
        pass
    elif isinstance(val, (tuple, list)):
        for s in val:
            yield from _iterate_exprs(s)
    elif is_sparse_any(val):
        yield from _iterate_exprs(val.size())
    elif isinstance(val, torch.Tensor):
        yield from _iterate_exprs(val.size())
        yield from _iterate_exprs(val.stride())
        yield from _iterate_exprs(val.storage_offset())
    elif val is None:
        pass
    elif isinstance(val, torch.Generator) or is_opaque_value(val):
        pass
    elif isinstance(val, FakeScriptObject):
        pass
    else:
        raise AssertionError(f'cannot extract sympy expressions from {val} {type(val)}')

def cast_symbool_to_symint_guardless(symbool: Union[bool, torch.SymBool]) -> Union[int, torch.SymInt]:
    if isinstance(symbool, bool):
        return 1 if symbool else 0
    int_sym = _sympy_cast_symbool_to_symint_guardless(symbool.node.expr)
    return symbool.node.shape_env.create_symintnode(int_sym, hint=int(symbool.node.require_hint()) if has_hint(symbool) else None)

# --- helper: torch.fx.experimental.symbolic_shapes._sympy_cast_symbool_to_symint_guardless ---
def _sympy_cast_symbool_to_symint_guardless(x: SympyBoolean) -> sympy.Expr:
    return sympy.Piecewise((1, x), (0, True))

# --- helper: torch.fx.experimental.symbolic_shapes.has_hint ---
def has_hint(a: Scalar) -> bool:
    if isinstance(a, SymTypes):
        return a.node.has_hint()
    return True

