def is_accessor_node(node: torch.fx.Node) -> bool:
    if node.op == 'call_method' and isinstance(node.args[0], torch.fx.Node) and isinstance(node.args[0].meta.get('example_value'), torch.Tensor) and (node.target in ['size', 'stride', 'storage_offset', 'item']):
        return True
    if node.op == 'call_function' and node.target in [torch.ops.aten.sym_size, torch.ops.aten.sym_size.default, torch.ops.aten.sym_size.int, torch.ops.aten.sym_stride, torch.ops.aten.sym_stride.default, torch.ops.aten.sym_stride.int, torch.ops.aten.sym_storage_offset, torch.ops.aten.sym_storage_offset.default, torch.ops.aten.sym_numel.default]:
        return True
    return False

def has_static_value(a: Union[SymBool, SymFloat, SymInt, bool, float, int]) -> bool:
    if not isinstance(a, BoolLike + FloatLike + IntLike):
        raise AssertionError(f'Expected BoolLike/FloatLike/IntLike, got {type(a)}')
    if isinstance(a, BoolLike) and is_concrete_bool(a) or (isinstance(a, FloatLike) and is_concrete_float(a)) or (isinstance(a, IntLike) and is_concrete_int(a)):
        return True
    if not isinstance(a, py_sym_types):
        raise AssertionError(f'Expected py_sym_types, got {type(a)}')
    return a.node.shape_env.bound_sympy(a.node.expr).is_singleton()

# --- helper: torch.fx.experimental.symbolic_shapes.is_concrete_bool ---
def is_concrete_bool(a: BoolLikeType) -> bool:
    if not isinstance(a, (SymBool, bool)):
        raise AssertionError(f'Expected SymBool or bool, got {type(a)}')
    if isinstance(a, bool):
        return True
    if isinstance(a.node.expr, (sympy.logic.boolalg.BooleanTrue, sympy.logic.boolalg.BooleanFalse)):
        return True
    return False

# --- helper: torch.fx.experimental.symbolic_shapes.is_concrete_float ---
def is_concrete_float(a: FloatLikeType) -> bool:
    if not isinstance(a, (SymFloat, float)):
        raise AssertionError(f'Expected SymFloat or float, got {type(a)}')
    if isinstance(a, float):
        return True
    if isinstance(a.node.expr, sympy.core.numbers.Float):
        return True
    return False

# --- helper: torch.fx.experimental.symbolic_shapes.is_concrete_int ---
def is_concrete_int(a: IntLikeType) -> bool:
    if not isinstance(a, (SymInt, int)):
        raise AssertionError(f'Expected SymInt or int, got {type(a)}')
    if isinstance(a, int):
        return True
    if isinstance(a.node.expr, sympy.core.numbers.Integer):
        return True
    return False

def is_traceable_wrapper_subclass(t: object) -> TypeIs[TensorWithFlatten]:
