def sym_eq(x: _T, y: _T) -> BoolLikeType:
    if isinstance(x, (tuple, list)) and isinstance(y, (list, tuple)):
        if len(x) != len(y):
            return False
        return functools.reduce(operator.and_, map(sym_eq, x, y), True)
    elif isinstance(x, (int, torch.SymInt)) and isinstance(y, (int, torch.SymInt)):
        return x == y
    else:
        raise AssertionError(f'unexpected sym_eq between {type(x)} {type(y)}')

@compatibility(is_backward_compatible=False)
class FxGraphDrawer:

    def __init__(self, graph_module: torch.fx.GraphModule, name: str, ignore_getattr: bool=False, ignore_parameters_and_buffers: bool=False, skip_node_names_in_args: bool=True, parse_stack_trace: bool=False, dot_graph_shape: Optional[str]=None, normalize_args: bool=False):
        self._name = name
        self.dot_graph_shape = dot_graph_shape if dot_graph_shape is not None else 'record'
        self.normalize_args = normalize_args
        _WEIGHT_TEMPLATE['shape'] = self.dot_graph_shape
        self._dot_graphs = {name: self._to_dot(graph_module, name, ignore_getattr, ignore_parameters_and_buffers, skip_node_names_in_args, parse_stack_trace)}
        for node in graph_module.graph.nodes:
            if node.op != 'call_module':
                continue
            leaf_node = self._get_leaf_node(graph_module, node)
            if not isinstance(leaf_node, torch.fx.GraphModule):
                continue
            self._dot_graphs[f'{name}_{node.target}'] = self._to_dot(leaf_node, f'{name}_{node.target}', ignore_getattr, ignore_parameters_and_buffers, skip_node_names_in_args, parse_stack_trace)

    def get_dot_graph(self, submod_name=None) -> pydot.Dot:
        if submod_name is None:
            return self.get_main_dot_graph()
        else:
            return self.get_submod_dot_graph(submod_name)

    def get_main_dot_graph(self) -> pydot.Dot:
        return self._dot_graphs[self._name]

    def get_submod_dot_graph(self, submod_name) -> pydot.Dot:
        return self._dot_graphs[f'{self._name}_{submod_name}']

    def get_all_dot_graphs(self) -> dict[str, pydot.Dot]:
        return self._dot_graphs

    def _get_node_style(self, node: torch.fx.Node) -> dict[str, str]:
        template = {'shape': self.dot_graph_shape, 'fillcolor': '#CAFFE3', 'style': '"filled,rounded"', 'fontcolor': '#000000'}
        if node.op in _COLOR_MAP:
            template['fillcolor'] = _COLOR_MAP[node.op]
        else:
            target_name = node._pretty_print_target(node.target)
            target_hash = int(hashlib.md5(target_name.encode(), usedforsecurity=False).hexdigest()[:8], 16)
            template['fillcolor'] = _HASH_COLOR_MAP[target_hash % len(_HASH_COLOR_MAP)]
        return template

    def _get_leaf_node(self, module: torch.nn.Module, node: torch.fx.Node) -> torch.nn.Module:
        py_obj = module
        if not isinstance(node.target, str):
            raise AssertionError(f'Expected str target, got {type(node.target)}')
        atoms = node.target.split('.')
        for atom in atoms:
            if not hasattr(py_obj, atom):
                raise RuntimeError(str(py_obj) + ' does not have attribute ' + atom + '!')
            py_obj = getattr(py_obj, atom)
        return py_obj

    def _typename(self, target: Any) -> str:
        if isinstance(target, torch.nn.Module):
            ret = torch.typename(target)
        elif isinstance(target, str):
            ret = target
        else:
            ret = _get_qualified_name(target)
        return ret.replace('{', '\\{').replace('}', '\\}')

    def _shorten_file_name(self, full_file_name: str, truncate_to_last_n: int=2):
        splits = full_file_name.split('/')
        if len(splits) >= truncate_to_last_n:
            return '/'.join(splits[-truncate_to_last_n:])
        return full_file_name

    def _get_node_label(self, module: torch.fx.GraphModule, node: torch.fx.Node, skip_node_names_in_args: bool, parse_stack_trace: bool) -> str:

        def _get_str_for_args_kwargs(arg):
            if isinstance(arg, tuple):
                prefix, suffix = ('|args=(\\l', ',\\n)\\l')
                arg_strs_list = [_format_arg(a, max_list_len=8) for a in arg]
            elif isinstance(arg, dict):
                prefix, suffix = ('|kwargs={\\l', ',\\n}\\l')
                arg_strs_list = [f'{k}: {_format_arg(v, max_list_len=8)}' for k, v in arg.items()]
            else:
                return ''
            if skip_node_names_in_args:
                arg_strs_list = [a for a in arg_strs_list if '%' not in a]
            if len(arg_strs_list) == 0:
                return ''
            arg_strs = prefix + ',\\n'.join(arg_strs_list) + suffix
            if len(arg_strs_list) == 1:
                arg_strs = arg_strs.replace('\\l', '').replace('\\n', '')
            return arg_strs.replace('{', '\\{').replace('}', '\\}')
        label = '{' + f'name=%{node.name}|op_code={node.op}\n'
        if node.op == 'call_module':
            leaf_module = self._get_leaf_node(module, node)
            label += '\\n' + self._typename(leaf_module) + '\\n|'
            extra = ''
            if hasattr(leaf_module, '__constants__'):
                extra = '\\n'.join([f'{c}: {getattr(leaf_module, c)}' for c in leaf_module.__constants__])
            label += extra + '\\n'
        else:
            label += f'|target={self._typename(node.target)}' + '\\n'
            if self.normalize_args:
                try:
                    args, kwargs = normalize_function(node.target, node.args, node.kwargs, normalize_to_only_use_kwargs=True)
                except Exception:
                    args, kwargs = (node.args, node.kwargs)
            else:
                args, kwargs = (node.args, node.kwargs)
            if len(args) > 0:
                label += _get_str_for_args_kwargs(args)
            if len(kwargs) > 0:
                label += _get_str_for_args_kwargs(kwargs)
            label += f'|num_users={len(node.users)}' + '\\n'
        tensor_meta = node.meta.get('tensor_meta')
        label += self._tensor_meta_to_label(tensor_meta)
        buf_meta = node.meta.get('buf_meta', None)
        if buf_meta is not None:
            label += f'|buf={buf_meta.name}' + '\\n'
            label += f'|n_origin={buf_meta.n_origin}' + '\\n'
        if parse_stack_trace and node.stack_trace is not None:
            parsed_stack_trace = _parse_stack_trace(node.stack_trace)
            fname = self._shorten_file_name(parsed_stack_trace.file)
            label += f'|file={fname}:{parsed_stack_trace.lineno} {parsed_stack_trace.code}' + '\\n'
        return label + '}'

    def _tensor_meta_to_label(self, tm) -> str:
        if tm is None:
            return ''
        elif isinstance(tm, TensorMetadata):
            return self._stringify_tensor_meta(tm)
        elif isinstance(tm, list):
            result = ''
            for item in tm:
                result += self._tensor_meta_to_label(item)
            return result
        elif isinstance(tm, dict):
            result = ''
            for v in tm.values():
                result += self._tensor_meta_to_label(v)
            return result
        elif isinstance(tm, tuple):
            result = ''
            for item in tm:
                result += self._tensor_meta_to_label(item)
            return result
        else:
            raise RuntimeError(f'Unsupported tensor meta type {type(tm)}')

    def _stringify_tensor_meta(self, tm: TensorMetadata) -> str:
        result = ''
        if not hasattr(tm, 'dtype'):
            print('tm', tm)
        result += '|' + 'dtype' + '=' + str(tm.dtype) + '\\n'
        result += '|' + 'shape' + '=' + str(tuple(tm.shape)) + '\\n'
        result += '|' + 'requires_grad' + '=' + str(tm.requires_grad) + '\\n'
        result += '|' + 'stride' + '=' + str(tm.stride) + '\\n'
        if tm.is_quantized:
            if tm.qparams is None:
                raise AssertionError('qparams is None for quantized tensor')
            if 'qscheme' not in tm.qparams:
                raise AssertionError('qscheme not in qparams')
            qscheme = tm.qparams['qscheme']
            if qscheme in {torch.per_tensor_affine, torch.per_tensor_symmetric}:
                result += '|' + 'q_scale' + '=' + str(tm.qparams['scale']) + '\\n'
                result += '|' + 'q_zero_point' + '=' + str(tm.qparams['zero_point']) + '\\n'
            elif qscheme in {torch.per_channel_affine, torch.per_channel_symmetric, torch.per_channel_affine_float_qparams}:
                result += '|' + 'q_per_channel_scale' + '=' + str(tm.qparams['scale']) + '\\n'
                result += '|' + 'q_per_channel_zero_point' + '=' + str(tm.qparams['zero_point']) + '\\n'
                result += '|' + 'q_per_channel_axis' + '=' + str(tm.qparams['axis']) + '\\n'
            else:
                raise RuntimeError(f'Unsupported qscheme: {qscheme}')
            result += '|' + 'qscheme' + '=' + str(tm.qparams['qscheme']) + '\\n'
        return result

    def _get_tensor_label(self, t: torch.Tensor) -> str:
        return str(t.dtype) + str(list(t.shape)) + '\\n'

    def _to_dot(self, graph_module: torch.fx.GraphModule, name: str, ignore_getattr: bool, ignore_parameters_and_buffers: bool, skip_node_names_in_args: bool, parse_stack_trace: bool) -> pydot.Dot:
        dot_graph = pydot.Dot(name, rankdir='TB')
        buf_name_to_subgraph = {}
        for node in graph_module.graph.nodes:
            if ignore_getattr and node.op == 'get_attr':
                continue
            style = self._get_node_style(node)
            dot_node = pydot.Node(node.name, label=self._get_node_label(graph_module, node, skip_node_names_in_args, parse_stack_trace), **style)
            current_graph = dot_graph
            buf_meta = node.meta.get('buf_meta', None)
            if buf_meta is not None and buf_meta.n_origin > 1:
                buf_name = buf_meta.name
                if buf_name not in buf_name_to_subgraph:
                    buf_name_to_subgraph[buf_name] = pydot.Cluster(buf_name, label=buf_name)
                current_graph = buf_name_to_subgraph.get(buf_name)
            current_graph.add_node(dot_node)

            def get_module_params_or_buffers():
                for pname, ptensor in chain(leaf_module.named_parameters(), leaf_module.named_buffers()):
                    pname1 = node.name + '.' + pname
                    label1 = pname1 + '|op_code=get_' + 'parameter' if isinstance(ptensor, torch.nn.Parameter) else 'buffer' + '\\l'
                    dot_w_node = pydot.Node(pname1, label='{' + label1 + self._get_tensor_label(ptensor) + '}', **_WEIGHT_TEMPLATE)
                    dot_graph.add_node(dot_w_node)
                    dot_graph.add_edge(pydot.Edge(pname1, node.name))
            if node.op == 'call_module':
                leaf_module = self._get_leaf_node(graph_module, node)
                if not ignore_parameters_and_buffers and (not isinstance(leaf_module, torch.fx.GraphModule)):
                    get_module_params_or_buffers()
        for subgraph in buf_name_to_subgraph.values():
            subgraph.set('color', 'royalblue')
            subgraph.set('penwidth', '2')
            dot_graph.add_subgraph(subgraph)
        for node in graph_module.graph.nodes:
            if ignore_getattr and node.op == 'get_attr':
                continue
            for user in node.users:
                dot_graph.add_edge(pydot.Edge(node.name, user.name))
        return dot_graph

def lazy_format_graph_code(name, gm, maybe_id=None, **kwargs):

    def format_name():
        if maybe_id is not None:
            return f'{name} {maybe_id}'
        else:
            return name
    if 'print_output' not in kwargs:
        kwargs['print_output'] = False
    if 'colored' in kwargs:
        try:
            if not sys.stdout.isatty():
                kwargs['colored'] = False
        except AttributeError:
            kwargs['colored'] = False
    return LazyString(lambda: _format_graph_code(f'===== {format_name()} =====\n', gm.forward.__code__.co_filename, gm.print_readable(**kwargs)))

# --- helper: torch.fx._utils._format_graph_code ---
def _format_graph_code(name, filename, graph_str):
    return f'TRACED GRAPH\n {name} {filename} {graph_str}\n'

@compatibility(is_backward_compatible=False)
def move_non_tensor_nodes_on_boundary(subgraphs) -> None:
    node_to_subgraph: dict[torch.fx.Node, int] = {}
    for i, subgraph in enumerate(subgraphs):
        for node in subgraph.nodes:
            node_to_subgraph[node] = i

    def get_children_in_graph(node: torch.fx.Node) -> list[torch.fx.Node]:
        return [user for user in node.users if user.op in CALLABLE_NODE_OPS and user in node_to_subgraph]

    def get_parents_in_graph(node: torch.fx.Node) -> list[torch.fx.Node]:
        return [arg for arg in node.all_input_nodes if arg.op in CALLABLE_NODE_OPS and arg in node_to_subgraph]

    def has_children_in_other_subgraph(node: torch.fx.Node, current_subgraph_idx: int) -> bool:
        children = get_children_in_graph(node)
        return any((node_to_subgraph[child] != current_subgraph_idx for child in children))

    def can_move_node_and_dependencies(node: torch.fx.Node, from_subgraph: int, to_subgraph: int) -> tuple[bool, set[torch.fx.Node]]:
        nodes_to_move = set()
        visited = set()
        can_move = True

        def dfs(current_node):
            nonlocal can_move, nodes_to_move
            if current_node in visited:
                return
            visited.add(current_node)
            if current_node not in node_to_subgraph:
                return
            current_subgraph = node_to_subgraph[current_node]
            if current_subgraph == to_subgraph:
                return
            elif current_subgraph == from_subgraph:
                nodes_to_move.add(current_node)
            else:
                can_move = False
                return
            children = get_children_in_graph(current_node)
            for child in children:
                if can_move:
                    dfs(child)
        dfs(node)
        return (can_move, nodes_to_move)
    for subgraph_idx, subgraph in enumerate(subgraphs):
        if not subgraph.is_acc:
            continue
        queue: list[torch.fx.Node] = []
        processed: set[torch.fx.Node] = set()
        for node in subgraph.nodes:
            if is_node_output_tensor(node):
                continue
            if has_children_in_other_subgraph(node, subgraph_idx):
                queue.append(node)
        while queue:
            current_node = queue.pop(0)
            if current_node in processed:
                continue
            processed.add(current_node)
            if current_node not in node_to_subgraph or node_to_subgraph[current_node] != subgraph_idx:
                continue
            children = get_children_in_graph(current_node)
            if len(children) == 0:
                raise AssertionError('Only node that has children in other subgraph can be moved')
            target_subgraph_candidates = set()
            for child in children:
                child_subgraph = node_to_subgraph[child]
                if child_subgraph != subgraph_idx:
                    target_subgraph_candidates.add(child_subgraph)
            if len(target_subgraph_candidates) != 1:
                print(f'Cannot move non-tensor node {current_node.name} on boundary because it has children in multiple subgraphs')
                continue
            target_subgraph = target_subgraph_candidates.pop()
            can_move, nodes_to_move = can_move_node_and_dependencies(current_node, subgraph_idx, target_subgraph)
            if can_move:
                for node_to_move in nodes_to_move:
                    subgraph.nodes.remove(node_to_move)
                    subgraphs[target_subgraph].nodes.append(node_to_move)
                    node_to_subgraph[node_to_move] = target_subgraph
                    print(f"In order move the non-tensor node {current_node.name} on boundary, moved node {node_to_move.name} from {('acc' if subgraph.is_acc else 'gpu')}_{subgraph_idx} to {('acc' if subgraphs[target_subgraph].is_acc else 'gpu')}_{target_subgraph}")
                parents = get_parents_in_graph(current_node)
                for parent in parents:
                    if not is_node_output_tensor(parent) and parent not in processed and (parent in node_to_subgraph) and (node_to_subgraph[parent] == subgraph_idx):
                        if not has_children_in_other_subgraph(parent, subgraph_idx):
                            raise AssertionError(f'Parent {parent.name} should have children in another subgraph')
                        queue.append(parent)

class CacheArtifactManager:
    _new_cache_artifacts: CacheArtifactsResult = defaultdict(list)
    _seen_artifacts: OrderedSet[CacheArtifact] = OrderedSet()
    _serializer: AppendingByteSerializer[tuple[str, list[CacheArtifact]]] = AppendingByteSerializer(serialize_fn=_serialize_single_cache)
    _cache_info: CacheInfo = CacheInfo()

    @classmethod
    def clear(cls) -> None:
        cls._new_cache_artifacts.clear()
        cls._seen_artifacts.clear()
        cls._serializer.clear()
        cls._cache_info.clear()

    @classmethod
    @contextmanager
    def with_fresh_cache(cls) -> Generator[None, None, None]:
        original_new_cache_artifacts = cls._new_cache_artifacts
        original_seen_artifacts = cls._seen_artifacts
        original_serializer = cls._serializer
        original_cache_info = cls._cache_info
        cls._new_cache_artifacts = defaultdict(list)
        cls._seen_artifacts = OrderedSet()
        cls._serializer = AppendingByteSerializer(serialize_fn=_serialize_single_cache)
        cls._cache_info = cls._cache_info.__class__()
        try:
            yield
        finally:
            cls._new_cache_artifacts = original_new_cache_artifacts
            cls._seen_artifacts = original_seen_artifacts
            cls._serializer = original_serializer
            cls._cache_info = original_cache_info

    @classmethod
    def record_artifact(cls, artifact_type: str, key: str, content: Any) -> None:
        artifact = CacheArtifactFactory.encode_create(artifact_type, key, content)
        if artifact in cls._seen_artifacts:
            return
        log.debug('Recording %s', str(artifact))
        cls._new_cache_artifacts[artifact_type].append(artifact)
        cls._seen_artifacts.add(artifact)

    @classmethod
    def need_serialize(cls) -> bool:
        return len(cls._new_cache_artifacts) != 0

    @classmethod
    def serialize(cls) -> Optional[tuple[bytes, CacheInfo]]:
        for artifact in chain(*cls._new_cache_artifacts.values()):
            log.debug('saving: %s', artifact)
            cls._cache_info.add(artifact)
        if cls._cache_info.empty():
            return None
        try:
            info = copy.deepcopy(cls._cache_info)
            cls._serializer.extend(cls._new_cache_artifacts.items())
            artifact_bytes = cls._serializer.to_bytes()
            cls._new_cache_artifacts.clear()
            return (artifact_bytes, info)
        except Exception:
            log.warning('Failed to pickle cache artifacts', exc_info=True)
        return None

    @staticmethod
    def deserialize(serialized_artifacts: bytes) -> Optional[CacheArtifactsResult]:
        try:
            CacheArtifactManager._ensure_cache_artifacts_registered()
            artifacts = dict(AppendingByteSerializer.to_list(serialized_artifacts, deserialize_fn=_deserialize_single_cache))
        except Exception:
            log.warning('Failed to un-pickle cache artifacts', exc_info=True)
            return None
        return artifacts

    @staticmethod
    def populate_caches(artifacts: CacheArtifactsResult) -> CacheInfo:
        info = CacheInfo()
        for artifact in chain(*artifacts.values()):
            log.debug('writing: %s', artifact)
            info.add(artifact)
            artifact.populate_cache()
        return info

    @classmethod
    def _ensure_cache_artifacts_registered(cls) -> None:
        from torch._dynamo.package import PrecompileCacheArtifact
        from torch._dynamo.pgo import PGOCacheArtifact
        from torch._functorch._aot_autograd.autograd_cache import AOTAutogradCacheArtifact
        from torch._inductor.codecache import InductorCacheArtifact
        from torch._inductor.runtime.autotune_cache import AutotuneCacheArtifact

