@dataclasses.dataclass(frozen=True)
class CacheArtifact(ABC):
    key: str
    content: bytes = dataclasses.field(repr=False)

    @staticmethod
    def serialize(writer: BytesWriter, cls: 'CacheArtifact') -> None:
        writer.write_str(cls.key)
        writer.write_bytes(cls.content)

    @staticmethod
    def deserialize(artifact_type: str, reader: BytesReader) -> 'CacheArtifact':
        key = reader.read_str()
        content = reader.read_bytes()
        return CacheArtifactFactory.create(artifact_type, key, content)

    @staticmethod
    def encode(content: Any) -> bytes:
        if not isinstance(content, bytes):
            raise AssertionError(f'Expected bytes, got {type(content)}')
        return content

    @abstractmethod
    def populate_cache(self) -> None:
        pass

    @staticmethod
    def type() -> str:
        raise RuntimeError('CacheArtifact is an abstract class, please use a subclass')

# --- helper: torch.compiler._cache.CacheArtifactFactory ---
class CacheArtifactFactory:
    _artifact_types: dict[str, type[CacheArtifact]] = {}

    @classmethod
    def register(cls, artifact_cls: type[CacheArtifact]) -> type[CacheArtifact]:
        artifact_type_key = artifact_cls.type()
        if artifact_cls.type() in cls._artifact_types:
            raise AssertionError(f'Artifact of type={artifact_type_key} already registered in mega-cache artifact factory')
        cls._artifact_types[artifact_type_key] = artifact_cls
        setattr(CacheInfo, f'{artifact_type_key}_artifacts', property(lambda self: self.artifacts[artifact_type_key]))
        return artifact_cls

    @classmethod
    def _get_artifact_type(cls, artifact_type_key: str) -> type[CacheArtifact]:
        if artifact_type_key not in cls._artifact_types:
            raise AssertionError(f'Artifact of type={artifact_type_key} not registered in mega-cache artifact factory')
        return cls._artifact_types[artifact_type_key]

    @classmethod
    def create(cls, artifact_type_key: str, key: str, content: bytes) -> CacheArtifact:
        artifact_cls = cls._get_artifact_type(artifact_type_key)
        return artifact_cls(key, content)

    @classmethod
    def encode_create(cls, artifact_type_key: str, key: str, content: Any) -> CacheArtifact:
        artifact_cls = cls._get_artifact_type(artifact_type_key)
        return artifact_cls(key, artifact_cls.encode(content))

# --- helper: torch.compiler._cache.CacheInfo ---
@dataclasses.dataclass
class CacheInfo:
    artifacts: defaultdict[str, list[str]] = dataclasses.field(default_factory=lambda: defaultdict(list))

    @property
    def inductor_artifacts(self) -> list[str]:
        ...

    @property
    def autotune_artifacts(self) -> list[str]:
        ...

    @property
    def aot_autograd_artifacts(self) -> list[str]:
        ...

    @property
    def pgo_artifacts(self) -> list[str]:
        ...

    @property
    def precompile_artifacts(self) -> list[str]:
        ...

    def add(self, artifact: CacheArtifact) -> None:
        self.artifacts[artifact.type()].append(artifact.key)

    def clear(self) -> None:
        self.artifacts.clear()

    def empty(self) -> bool:
        return not self.artifacts

# --- helper: torch.compiler._cache._deserialize_single_cache ---
def _deserialize_single_cache(reader: BytesReader) -> 'tuple[str, list[CacheArtifact]]':
    artifacts = []
    artifact_type_key = reader.read_str()
    num_artifacts = reader.read_uint64()
    for _ in range(num_artifacts):
        artifacts.append(CacheArtifact.deserialize(artifact_type_key, reader))
    return (artifact_type_key, artifacts)

# --- helper: torch.compiler._cache._serialize_single_cache ---
def _serialize_single_cache(writer: BytesWriter, cls: 'tuple[str, list[CacheArtifact]]') -> None:
    writer.write_str(cls[0])
    writer.write_uint64(len(cls[1]))
    for artifact in cls[1]:
        CacheArtifact.serialize(writer, artifact)

@compatibility(is_backward_compatible=False)
class NodeEventTracker:

    def __init__(self, tracker_mode, dump_prefix):
        self.tracker_mode = tracker_mode
        self.dump_prefix = dump_prefix
        self.events = []
        self.node_events = {}
        self.writer = print

    def add(self, node: torch.fx.Node, desc: str, dep: Optional[torch.fx.Node]=None):
        event = NodeEvent(node, desc, dep)
        self.events.append(event)
        if node.name not in self.node_events:
            self.node_events[node.name] = []
        self.node_events[node.name].append(len(self.events) - 1)

    def print_node(self, node_name, recursive=False, tab='', writer=None):
        if not writer:
            writer = self.writer
        for idx in self.node_events.get(node_name, []):
            event = self.events[idx]
            writer(tab + event.to_str())
            if recursive and event.dep is not None:
                self.print_node(event.dep.name, recursive=True, tab='| ' + tab, writer=writer)

    def to_dict(self):
        ret: dict[str, list[str]] = {}
        for name in self.node_events:
            ret[name] = []
            for idx in self.node_events.get(name, []):
                event = self.events[idx]
                ret[name].append(event.to_str())
        return ret

    def print_all(self, writer=None):
        if not writer:
            writer = self.writer
        for name in self.node_events:
            writer(f'Node: {name}:')
            self.print_node(name, recursive=False, tab='  ', writer=writer)

    def dump(self):
        trace_structured('artifact', metadata_fn=lambda: {'name': 'fx_net_acc_splitter_finder_events', 'encoding': 'json'}, payload_fn=lambda: json.dumps(self.to_dict()))

        def writeln(f):

            def fn(x):
                return f.write(x + '\n')
            return fn
        if self.tracker_mode >= 1:
            with open(self.dump_prefix + ALL_SUFFIX, 'w') as f:
                self.print_all(writeln(f))

        def dump_selected_nodes(nodes):
            with open(self.dump_prefix + NODES_SUFFIX, 'w') as f:
                for node_name in nodes:
                    writeln(f'===== Tracking node {node_name} =====')
                    self.print_node(node_name, recursive=True, tab='|-', writer=writeln(f))
                    writeln(f'===== End of tracking node {node_name} =====')
        if self.tracker_mode == 2 or self.tracker_mode == 3:
            nodes = os.environ.get(ENV_FX_NET_ACC_SPLITTER_TRACKER_TRACKED_NODES, '').split(',') if self.tracker_mode == 2 else [name for name, events in self.node_events.items() if len(events) > 1]
            dump_selected_nodes(nodes)

