    anchor: Node
    nodes_map: dict[Node, Node]
    replacements: list[Node]

# --- helper: torch.fx.subgraph_rewriter._replace_pattern ---
def _replace_pattern(gm: GraphModule, pattern: Union[Callable, Graph, GraphModule], replacement: Union[Callable, Graph, GraphModule, None]=None, match_filters: Optional[list[Callable[['InternalMatch', Graph, Graph], bool]]]=None, ignore_literals: bool=False, replacement_callback: Optional[Callable[['InternalMatch', Graph, Graph], Graph]]=None, node_name_match: str='') -> list[ReplacedPatterns]:
    from torch.fx.passes.utils.matcher_utils import InternalMatch, SubgraphMatcher
    if match_filters is None:
        match_filters = []
    original_graph: Graph = gm.graph
    if isinstance(pattern, GraphModule):
        pattern_graph = pattern.graph
    elif isinstance(pattern, Graph):
        pattern_graph = pattern
    else:
        pattern_graph = symbolic_trace(pattern).graph
    matcher = SubgraphMatcher(pattern_graph, match_output=False, match_placeholder=False, remove_overlapping_matches=True, ignore_literals=ignore_literals)
    _matches: list[InternalMatch] = matcher.match(original_graph, node_name_match=node_name_match)
    _matches = [m for m in _matches if all((match_filter(m, original_graph, pattern_graph) for match_filter in match_filters))]
    if isinstance(replacement, GraphModule):
        common_replacement_graph = replacement.graph
    elif isinstance(replacement, Graph):
        common_replacement_graph = replacement
    elif callable(replacement):
        common_replacement_graph = symbolic_trace(replacement).graph
    else:
        if replacement_callback is None:
            raise AssertionError('Must provide either a replacement GraphModule or a replacement callback')
        common_replacement_graph = None
    match_changed_node: dict[Node, Node] = {}
    match_and_replacements = []
    for match in _matches:
        if replacement_callback is not None:
            replacement_graph = replacement_callback(match, original_graph, pattern_graph)
        else:
            if common_replacement_graph is None:
                raise AssertionError('Must provide either a replacement GraphModule or a replacement callback')
            replacement_graph = common_replacement_graph
        replacement_placeholders = [n for n in replacement_graph.nodes if n.op == 'placeholder']
        if len(match.placeholder_nodes) != len(replacement_placeholders):
            raise AssertionError(f'Placeholder count mismatch: {len(match.placeholder_nodes)} vs {len(replacement_placeholders)}')
        val_map: dict[Node, Node] = {}
        for rn, gn in zip(replacement_placeholders, match.placeholder_nodes):
            if isinstance(gn, Node):
                val_map[rn] = match_changed_node.get(gn, gn)
                if gn != val_map[rn]:
                    gn_ind = match.placeholder_nodes.index(gn)
                    match.placeholder_nodes[gn_ind] = match_changed_node[gn]
                    map_key = list(match.nodes_map.keys())[list(match.nodes_map.values()).index(gn)]
                    match.nodes_map[map_key] = match_changed_node[gn]
            else:
                val_map[rn] = gn
        user_nodes: set[Node] = set()
        for n in match.returning_nodes:
            user_nodes.update(n.users)
        first_user_node = None
        if len(user_nodes) == 0:
            first_user_node = None
        elif len(user_nodes) == 1:
            first_user_node = next(iter(user_nodes))
        else:
            for n in original_graph.nodes:
                if n in user_nodes:
                    first_user_node = n
                    break
        first_next_node = None
        if first_user_node is None:
            next_node = None
            for n in reversed(original_graph.nodes):
                if n in match.returning_nodes:
                    first_next_node = next_node
                    break
                else:
                    next_node = n
        insert_point = first_user_node if first_user_node is not None else first_next_node
        if insert_point is None:
            raise AssertionError("The insert point can't be None")
        with original_graph.inserting_before(insert_point):
            copied_returning_nodes = original_graph.graph_copy(replacement_graph, val_map)
        if isinstance(copied_returning_nodes, Node):
            copied_returning_nodes = (copied_returning_nodes,)
        replacement_nodes: list[Node] = [v for v in val_map.values() if v not in match.placeholder_nodes]
        if len(match.returning_nodes) != len(copied_returning_nodes):
            raise AssertionError(f'Returning nodes count mismatch: {len(match.returning_nodes)} vs {len(copied_returning_nodes)}')
        for gn, copied_node in zip(match.returning_nodes, copied_returning_nodes):
            gn.replace_all_uses_with(copied_node)
            match_changed_node[gn] = copied_node
        for node in reversed(pattern_graph.nodes):
            if node.op != 'placeholder' and node.op != 'output':
                gn = match.nodes_map[node]
                gm.graph.erase_node(gn)
        match_and_replacements.append(ReplacedPatterns(anchor=match.anchors[0], nodes_map=match.nodes_map, replacements=replacement_nodes))
    gm.recompile()
    if isinstance(replacement, torch.nn.Module):
        _replace_attributes(gm, replacement)
    return match_and_replacements

def get_kernel(op: _op_identifier, dispatch_key: str | torch.DispatchKey) -> torch._C._SafeKernelFunction:
    if not isinstance(op, (str, torch._ops.OpOverload)):
        raise ValueError(f'get_kernel({op}): got unexpected type for op: {type(op)}')
    if isinstance(op, torch._ops.OpOverload):
        op = op._name
    if isinstance(dispatch_key, str):
        try:
            dispatch_key = torch._C.DispatchKey.__members__[dispatch_key]
        except KeyError:
            raise ValueError(f'Invalid dispatch key: {dispatch_key}') from None
    return torch._C._dispatch_get_computed_kernel_for_dispatch_key(op, dispatch_key)

@exposed_in('torch.library')
def infer_schema(prototype_function: typing.Callable, /, *, mutates_args, op_name: Optional[str]=None) -> str:
    UNKNOWN_MUTATES = 'unknown'
    pf_globals = prototype_function.__globals__
    pf_locals = None
    sig = inspect.signature(prototype_function)

    def error_fn(what):
        raise ValueError(f'infer_schema(func): {what} Got func with signature {sig})')

    def convert_type_string(annotation_type: str):
        try:
            return eval(annotation_type, pf_globals, pf_locals)
        except Exception:
            error_fn(f'Unsupported type annotation {annotation_type}. It is not a type.')

    def unstringify_types(tys: tuple[Union[type[object], str], ...]) -> tuple[tuple[typing.Any, ...], bool]:
        res = []
        changed = False
        for ty in tys:
            ty, ty_changed = unstringify_type(ty)
            res.append(ty)
            changed |= ty_changed
        if changed:
            return (tuple(res), True)
        else:
            return (tys, False)

    def unstringify_type(ty: Union[type[object], str]) -> tuple[typing.Any, bool]:
        if isinstance(ty, str):
            return (convert_type_string(ty), True)
        elif (origin := typing.get_origin(ty)):
            args, args_changed = unstringify_types(typing.get_args(ty))
            if args_changed:
                return (GenericAlias(origin, args), True)
        return (ty, False)
    params = []
    seen_args = set()
    saw_kwarg_only_arg = False
    for idx, (name, param) in enumerate(sig.parameters.items()):
        if not supported_param(param):
            error_fn('We do not support positional-only args, varargs, or varkwargs.')
        if param.kind == inspect.Parameter.KEYWORD_ONLY:
            if not saw_kwarg_only_arg:
                params.append('*')
                saw_kwarg_only_arg = True
        if param.annotation is inspect.Parameter.empty:
            error_fn(f'Parameter {name} must have a type annotation.')
        annotation_type, _ = unstringify_type(param.annotation)
        schema_type = None
        if annotation_type not in SUPPORTED_PARAM_TYPES:
            if is_opaque_type(annotation_type):
                schema_type = _OPAQUE_TYPES[annotation_type].class_name
            elif annotation_type == torch._C.ScriptObject:
                error_fn(f"Parameter {name}'s type cannot be inferred from the schema as it is a ScriptObject. Please manually specify the schema using the `schema=` kwarg with the actual type of the ScriptObject.")
            elif hasattr(annotation_type, '__origin__') and annotation_type.__origin__ is tuple:
                list_type = tuple_to_list(annotation_type)
                example_type_str = '\n\n'
                if list_type in SUPPORTED_PARAM_TYPES:
                    example_type_str = f'For example, {list_type}.\n\n'
                error_fn(f'Parameter {name} has unsupported type {param.annotation}. We do not support Tuple inputs in schema. As a workaround, please try to use List instead. {example_type_str}The valid types are: {SUPPORTED_PARAM_TYPES.keys()}.')
            else:
                error_fn(f'Parameter {name} has unsupported type {param.annotation}. The valid types are: {SUPPORTED_PARAM_TYPES.keys()}.')
        else:
            schema_type = SUPPORTED_PARAM_TYPES[annotation_type]
        if schema_type is None:
            raise AssertionError(f'schema_type is None for param {name}')
        if type(mutates_args) is str:
            if mutates_args != UNKNOWN_MUTATES:
                raise ValueError("mutates_args must either be a sequence of the names of the arguments that are mutated or the string 'unknown'. ")
            if schema_type.startswith('Tensor'):
                schema_type = f"Tensor(a{idx}!){schema_type[len('Tensor'):]}"
        elif name in mutates_args:
            if not schema_type.startswith('Tensor'):
                error_fn(f'Parameter {name} is in mutable_args but only Tensors or collections of Tensors can be mutated')
            schema_type = f"Tensor(a{idx}!){schema_type[len('Tensor'):]}"
        seen_args.add(name)
        if param.default is inspect.Parameter.empty:
            params.append(f'{schema_type} {name}')
        else:
            default_repr = None
            if param.default is None or isinstance(param.default, (int, float, bool)):
                default_repr = str(param.default)
            elif isinstance(param.default, (str, torch.device)):
                default_repr = f'"{param.default}"'
            elif isinstance(param.default, torch.dtype):
                dtype_repr = str(param.default)
                torch_dot = 'torch.'
                if not dtype_repr.startswith(torch_dot):
                    raise AssertionError(f"dtype repr {dtype_repr!r} must start with 'torch.'")
                default_repr = dtype_repr[len(torch_dot):]
            else:
                error_fn(f'Parameter {name} has an unsupported default value type {type(param.default)}. Please file an issue on GitHub so we can prioritize this.')
            params.append(f'{schema_type} {name}={default_repr}')
    if mutates_args != UNKNOWN_MUTATES:
        mutates_args_not_seen = set(mutates_args) - seen_args
        if len(mutates_args_not_seen) > 0:
            error_fn(f"{mutates_args_not_seen} in mutates_args were not found in the custom op's signature. mutates_args should contain the names of all args that the custom op mutates, or just the string 'unknown' if you don't know.")
    return_annotation, _ = unstringify_type(sig.return_annotation)
    ret = parse_return(return_annotation, error_fn)
    if op_name is not None:
        return f"{op_name}({', '.join(params)}) -> {ret}"
    return f"({', '.join(params)}) -> {ret}"

