@exposed_in('torch.library')
def custom_op(name: str, fn: Optional[Callable]=None, /, *, mutates_args: Union[str, Iterable[str]], device_types: device_types_t=None, schema: Optional[str]=None, tags: Optional[Sequence[_C.Tag]]=None) -> Union[Callable[[Callable[..., object]], 'CustomOpDef'], 'CustomOpDef']:

    def inner(fn: Callable[..., object]) -> CustomOpDef:
        import torch
        if schema is None:
            schema_str = torch.library.infer_schema(fn, mutates_args=mutates_args)
        else:
            schema_str = schema
        namespace, opname = name.split('::')
        result = CustomOpDef(namespace, opname, schema_str, fn, tags)
        if schema is not None:
            expected = set()
            for arg in result._opoverload._schema.arguments:
                if arg.alias_info is not None and arg.alias_info.is_write:
                    expected.add(arg.name)
            if expected != set(mutates_args):
                raise ValueError(f'Attempted to create a custom op with `mutates_args={mutates_args}` and `schema={schema}. The schema suggests that the op mutates {expected}which is different from what was provided to us in `mutates_args`. Please make these consistent.')
        result.register_kernel(device_types)(fn)
        return result
    if fn is None:
        return inner
    return inner(fn)

def register_autograd(op: _op_identifier, backward: Callable, /, *, setup_context: Callable | None=None, lib=None) -> None:
    if not isinstance(op, (str, torch._ops.OpOverload, torch._library.custom_ops.CustomOpDef)):
        raise ValueError(f'register_autograd({op}): got unexpected type for op: {type(op)}')
    if isinstance(op, torch._ops.OpOverload):
        op = op._name
    opdef = _maybe_get_opdef(op)
    if opdef is not None:
        opdef.register_autograd(backward, setup_context=setup_context)
        return
    if not isinstance(op, str):
        raise AssertionError(f'op must be str at this point, got {type(op).__name__}')
    qualname = op
    op = torch._library.utils.lookup_op(qualname)
    schema = op._schema
    if not _library.utils.is_functional_schema(schema):
        raise RuntimeError(f'Cannot register autograd formula for non-functional operator {op} with schema {schema}. Please create a functional operator and register an autograd formula for that.')
    if _library.utils.has_kwarg_only_tensors(schema):
        raise NotImplementedError(f'register_autograd with kwarg-only Tensor args. In the original definition of the op, please make your tensors not kwarg-only. Got: {schema}')
    info = _library.autograd.Info(backward, setup_context)
    autograd_kernel = _library.autograd.make_autograd_impl(op, info)
    namespace, opname = torch._library.utils.parse_namespace(qualname)
    if lib is None:
        lib = Library(namespace, 'FRAGMENT')
        _keep_alive.append(lib)
    lib.impl(opname, autograd_kernel, 'Autograd', with_keyset=True)

# --- helper: torch.library.Library ---
class Library:

    def __init__(self, ns, kind, dispatch_key=''):
        from torch.fx.operator_schemas import _SCHEMA_TO_SIGNATURE_CACHE
        if kind not in ('IMPL', 'DEF', 'FRAGMENT'):
            raise ValueError('Unsupported kind: ', kind)
        if ns in _reserved_namespaces and (kind == 'DEF' or kind == 'FRAGMENT'):
            raise ValueError(ns, ' is a reserved namespace. Please try creating a library with another name.')
        frame = traceback.extract_stack(limit=2)[0]
        filename, lineno = (frame.filename, frame.lineno)
        self.m: Any | None = torch._C._dispatch_library(kind, ns, dispatch_key, filename, lineno)
        self.ns = ns
        self._op_defs: set[str] = set()
        self._op_impls: set[str] = set()
        self._registration_handles: list[torch._library.utils.RegistrationHandle] = []
        self.kind = kind
        self.dispatch_key = dispatch_key
        weakref.finalize(self, _del_library, _impls, self._op_impls, _defs, self._op_defs, self._registration_handles, self.m, _SCHEMA_TO_SIGNATURE_CACHE)

    def __repr__(self):
        return f'Library(kind={self.kind}, ns={self.ns}, dispatch_key={self.dispatch_key})>'

    def define(self, schema, alias_analysis='', *, tags=()):
        if alias_analysis not in ['', 'FROM_SCHEMA', 'CONSERVATIVE']:
            raise RuntimeError(f'Invalid alias_analysis type {alias_analysis}')
        if self.m is None:
            raise AssertionError('Library object has been destroyed')
        if isinstance(tags, torch.Tag):
            tags = (tags,)
        name = schema.split('(')[0]
        packet_name = name.split('.')[0] if '.' in name else name
        has_preexisting_packet = hasattr(torch.ops, self.ns) and hasattr(getattr(torch.ops, self.ns), packet_name)
        result = self.m.define(schema, alias_analysis, tuple(tags))
        name = schema.split('(')[0]
        qualname = self.ns + '::' + name
        if has_preexisting_packet:
            ns = getattr(torch.ops, self.ns)
            packet = getattr(ns, packet_name)
            torch._ops._refresh_packet(packet)
        self._op_defs.add(qualname)
        _defs.add(qualname)
        return result

    def _register_fake(self, op_name, fn, _stacklevel=1, *, allow_override=False):
        source = torch._library.utils.get_source(_stacklevel + 1)
        frame = sys._getframe(_stacklevel)
        caller_module = inspect.getmodule(frame)
        caller_module_name = None if caller_module is None else caller_module.__name__
        if caller_module_name is not None and caller_module_name.startswith('torchvision.'):
            caller_module_name = None
        qualname = f'{self.ns}::{op_name}'
        entry = torch._library.simple_registry.singleton.find(qualname)
        if caller_module_name is not None:
            func_to_register = _check_pystubs_once(fn, qualname, caller_module_name)
        else:
            func_to_register = fn
        handle = entry.fake_impl.register(func_to_register, source, lib=self, allow_override=allow_override)
        self._registration_handles.append(handle)

    def _register_torch_dispatch_rule(self, op_name, torch_dispatch_class, fn):
        qualname = f'{self.ns}::{op_name}'
        entry = torch._library.simple_registry.singleton.find(qualname)
        handle = entry.torch_dispatch_rules.register(torch_dispatch_class, fn)
        self._registration_handles.append(handle)

    def _impl_with_aoti_compile(self, op_name, dispatch_key=''):
        if dispatch_key == '':
            dispatch_key = self.dispatch_key
        if not torch.DispatchKeySet(dispatch_key).has(torch._C.DispatchKey.Dense):
            raise AssertionError(f'dispatch_key {dispatch_key} does not have Dense in its keyset')
        if isinstance(op_name, str):
            name = op_name
        elif isinstance(op_name, OpOverload):
            name = op_name._schema.name
            overload_name = op_name._schema.overload_name
            if overload_name != '':
                name = name + '.' + overload_name
        else:
            raise RuntimeError('_impl_with_aoti_compile should be passed either a name or an OpOverload object as the first argument')
        key = self.ns + '/' + name.split('::')[-1] + '/' + dispatch_key
        if key in _impls:
            raise RuntimeError("This is not allowed since there's already a kernel registered from python overriding {}'s behavior for {} dispatch key and {} namespace.".format(name.split('::')[-1], dispatch_key, self.ns))
        if self.m is None:
            raise AssertionError('Library object has been destroyed')
        impl_fn: Callable = self.m.impl_with_aoti_compile
        impl_fn(self.ns, name.split('::')[-1], dispatch_key)
        _impls.add(key)
        self._op_impls.add(key)

    def impl(self, op_name, fn, dispatch_key='', *, with_keyset=False, allow_override=False):
        if not callable(fn):
            raise TypeError(f'Input function is required to be a callable but found type {type(fn)}')
        if dispatch_key == '':
            dispatch_key = self.dispatch_key
        if isinstance(op_name, str):
            name = op_name
        elif isinstance(op_name, OpOverload):
            name = op_name._schema.name
            overload_name = op_name._schema.overload_name
            if overload_name != '':
                name = name + '.' + overload_name
        else:
            raise RuntimeError('impl should be passed either a name or an OpOverload object as the first argument')
        key = self.ns + '/' + name.split('::')[-1] + '/' + dispatch_key
        if not allow_override and key in _impls:
            raise RuntimeError("This is not allowed since there's already a kernel registered from python overriding {}'s behavior for {} dispatch key and {} namespace.".format(name.split('::')[-1], dispatch_key, self.ns))
        if dispatch_key == 'Meta':
            dispatcher_op_name = name
            if '::' not in dispatcher_op_name:
                dispatcher_op_name = f'{self.ns}::{dispatcher_op_name}'
            if torch._C._dispatch_has_kernel_for_dispatch_key(dispatcher_op_name, 'CompositeImplicitAutograd'):
                raise RuntimeError(f"We should not register a meta kernel directly to the operator '{name}', because it has a CompositeImplicitAutograd kernel in core. Instead we should let the operator decompose, and ensure that we have meta kernels for the base ops that it decomposes into.")
        if self.m is None:
            raise AssertionError('Library object has been destroyed')
        self.m.impl(name, dispatch_key if dispatch_key != '' else 'CompositeImplicitAutograd', fn, with_keyset)
        _impls.add(key)
        self._op_impls.add(key)

    def fallback(self, fn, dispatch_key='', *, with_keyset=False):
        if dispatch_key == '':
            dispatch_key = self.dispatch_key
        if self.ns != '_':
            raise RuntimeError(f'Fallback can only be registered using library fragment on the global namespace "_" but it is {self.ns}')
        if dispatch_key == '':
            raise AssertionError('dispatch_key must not be empty for fallback')
        if self.m is None:
            raise AssertionError('Library object has been destroyed')
        self.m.fallback(dispatch_key, fn, with_keyset)

    def _register_effectful_op(self, op_name: str, effect: EffectType | None):
        from torch._higher_order_ops.effects import _register_effectful_op as hoo_register_effect
        handle = hoo_register_effect(op_name, effect)
        self._registration_handles.append(handle)

    def _destroy(self):
        if self.m is not None:
            self.m.reset()
        self.m = None
        for handle in self._registration_handles:
            handle.destroy()
        self._registration_handles.clear()
        global _impls
        _impls -= self._op_impls
        for name in self._op_defs:
            ns, name_with_overload = name.split('::')
            name = name_with_overload.split('.')[0]
            if not hasattr(torch.ops, ns):
                continue
            namespace = getattr(torch.ops, ns)
            if not hasattr(namespace, name):
                continue
            delattr(namespace, name)
            namespace._dir.remove(name)

def is_masked_tensor(obj: Any, /) -> TypeIs['MaskedTensor']:
    return isinstance(obj, MaskedTensor)

# --- helper: torch.masked.maskedtensor.core.MaskedTensor ---
class MaskedTensor(torch.Tensor):

    @staticmethod
    def __new__(cls, data, mask, requires_grad=False):
        if is_masked_tensor(data) or not torch.is_tensor(data):
            raise TypeError('data must be a Tensor')
        if is_masked_tensor(mask) or not torch.is_tensor(mask):
            raise TypeError('mask must be a Tensor')
        kwargs = {'device': data.device, 'dtype': data.dtype, 'layout': data.layout, 'requires_grad': requires_grad, 'dispatch_sizes_strides_policy': 'strides', 'dispatch_layout': True}
        warnings.warn('The PyTorch API of MaskedTensors is in prototype stage and will change in the near future. Please open a Github issue for features requests and see our documentation on the torch.masked module for further information about the project.', UserWarning, stacklevel=2)
        if data.requires_grad:
            warnings.warn('It is not recommended to create a MaskedTensor with a tensor that requires_grad. To avoid this, you can use data.detach().clone()', UserWarning, stacklevel=2)
        return torch.Tensor._make_wrapper_subclass(cls, data.size(), **kwargs)

    def _preprocess_data(self, data, mask):
        from .._ops import _sparse_coo_where, _sparse_csr_where
        if data.layout != mask.layout:
            raise TypeError('data and mask must have the same layout.')
        if data.layout == torch.sparse_coo:
            data = data.coalesce()
            mask = mask.coalesce()
            if data._nnz() != mask._nnz():
                data = _sparse_coo_where(mask, data, torch.tensor(0))
        elif data.layout == torch.sparse_csr:
            if data._nnz() != mask._nnz():
                data = _sparse_csr_where(mask, data, torch.tensor(0))
        self._masked_data = data.clone()
        self._masked_mask = mask.clone()

    def _validate_members(self):
        data = self._masked_data
        mask = self.get_mask()
        if type(data) is not type(mask):
            raise TypeError(f'data and mask must have the same type. Got {type(data)} and {type(mask)}')
        if data.layout not in {torch.strided, torch.sparse_coo, torch.sparse_csr}:
            raise TypeError(f'data layout of {data.layout} is not supported.')
        if data.layout == torch.sparse_coo:
            if not _tensors_match(data.indices(), mask.indices(), exact=True):
                raise ValueError('data and mask are both sparse COO tensors but do not have the same indices.')
        elif data.layout == torch.sparse_csr:
            if not _tensors_match(data.crow_indices(), mask.crow_indices(), exact=True) or not _tensors_match(data.col_indices(), mask.col_indices(), exact=True):
                raise ValueError('data and mask are both sparse CSR tensors but do not share either crow or col indices.')
        if mask.dtype != torch.bool:
            raise TypeError('mask must have dtype bool.')
        if not (data.dtype == torch.float16 or data.dtype == torch.float32 or data.dtype == torch.float64 or (data.dtype == torch.bool) or (data.dtype == torch.int8) or (data.dtype == torch.int16) or (data.dtype == torch.int32) or (data.dtype == torch.int64)):
            raise TypeError(f'{data.dtype} is not supported in MaskedTensor.')
        if data.dim() != mask.dim():
            raise ValueError('data.dim() must equal mask.dim()')
        if data.size() != mask.size():
            raise ValueError('data.size() must equal mask.size()')

    def __init__(self, data, mask, requires_grad=False):
        self._preprocess_data(data, mask)
        self._validate_members()

    @staticmethod
    def _from_values(data, mask):

        class Constructor(torch.autograd.Function):

            @staticmethod
            def forward(ctx, data, mask):
                return MaskedTensor(data, mask)

            @staticmethod
            def backward(ctx, grad_output):
                return (grad_output, None)
        result = Constructor.apply(data, mask)
        return result

    def _set_data_mask(self, data, mask):
        self._masked_data = data
        self._masked_mask = mask
        self._validate_members()

    def __repr__(self):
        formatter = '{0:8.4f}'
        if self.dim() == 0:
            scalar_data = self.get_data().item()
            data_formatted = formatter.format(scalar_data) if isinstance(scalar_data, float) else str(scalar_data)
            if not self.get_mask().item():
                data_formatted = '--'
            return 'MaskedTensor(' + data_formatted + ', ' + str(self.get_mask().item()) + ')'
        s = _masked_tensor_str(self.get_data(), self.get_mask(), formatter)
        s = '\n'.join(('  ' + si for si in s.split('\n')))
        return 'MaskedTensor(\n' + s + '\n)'

    @classmethod
    def __torch_function__(cls, func, types, args=(), kwargs=None):
        kwargs = kwargs or {}
        from ._ops_refs import _MASKEDTENSOR_FUNCTION_TABLE
        if func in _MASKEDTENSOR_FUNCTION_TABLE:
            return _MASKEDTENSOR_FUNCTION_TABLE[func](*args, **kwargs)
        if not all((issubclass(cls, t) for t in types)):
            return NotImplemented
        with torch._C.DisableTorchFunctionSubclass():
            ret = func(*args, **kwargs)
            if func in get_default_nowrap_functions():
                return ret
            else:
                return torch._tensor._convert(ret, cls)

    @classmethod
    def unary(cls, fn, data, mask):
        return MaskedTensor(fn(data), mask)

    @classmethod
    def __torch_dispatch__(cls, func, types, args, kwargs):
        func = func.overloadpacket
        from ._ops_refs import _MASKEDTENSOR_DISPATCH_TABLE
        if func in _MASKEDTENSOR_DISPATCH_TABLE:
            return _MASKEDTENSOR_DISPATCH_TABLE[func](*args, **kwargs)
        msg = f'{func.__name__} is not implemented in __torch_dispatch__ for MaskedTensor.\nIf you would like this operator to be supported, please file an issue for a feature request at https://github.com/pytorch/maskedtensor/issues with a minimal reproducible code snippet.\nIn the case that the semantics for the operator are not trivial, it would be appreciated to also include a proposal for the semantics.'
        warnings.warn(msg, stacklevel=2)
        return NotImplemented

    def __lt__(self, other):
        if is_masked_tensor(other):
            return MaskedTensor(self.get_data() < _get_data(other), self.get_mask())
        return MaskedTensor(self.get_data() < other, self.get_mask())

    def to_tensor(self, value):
        return self.get_data().masked_fill(~self.get_mask(), value)

    def get_data(self):

        class GetData(torch.autograd.Function):

            @staticmethod
            def forward(ctx, self):
                return self._masked_data.detach()

            @staticmethod
            def backward(ctx, grad_output):
                if is_masked_tensor(grad_output):
                    return grad_output
                return MaskedTensor(grad_output, self.get_mask())
        return GetData.apply(self)

    def get_mask(self):
        return self._masked_mask

    def is_sparse_coo(self):
        return self.layout == torch.sparse_coo

    def is_sparse_csr(self):
        return self.layout == torch.sparse_csr

    @property
    def is_sparse(self):
        return self.is_sparse_coo() or self.is_sparse_csr()

def register_fake(op: _op_identifier, func: Callable | None=None, /, *, lib: Library | None=None, _stacklevel: int=1, allow_override: bool=False):
    if not isinstance(op, (str, torch._ops.OpOverload, torch._library.custom_ops.CustomOpDef)):
        raise ValueError(f'register_fake({op}): got unexpected type for op: {type(op)}')
    if isinstance(op, torch._ops.OpOverload):
        op = op._name
    opdef = _maybe_get_opdef(op)
    if opdef is not None:
        if func is None:
            return opdef.register_fake
        else:
            return opdef.register_fake(func)
    if not isinstance(op, str):
        raise AssertionError(f'op must be str at this point, got {type(op).__name__}')
    stacklevel = _stacklevel

    def register(func):
        namespace, op_name = torch._library.utils.parse_namespace(op)
        if lib is None:
            use_lib = Library(namespace, 'FRAGMENT')
            _keep_alive.append(use_lib)
        else:
            use_lib = lib
        use_lib._register_fake(op_name, func, _stacklevel=stacklevel + 1, allow_override=allow_override)
        return func
    if func is None:
        return register
    else:
        stacklevel += 1
        return register(func)

