def narrow(tensor: Tensor, dim: int, start: int | Tensor, length: int | Tensor, layout=torch.strided) -> Tensor:
    if not isinstance(start, (int, SymInt, Tensor)):
        raise RuntimeError('start must be an integer or a tensor')
    if not isinstance(length, (int, SymInt, Tensor)):
        raise RuntimeError('length must be an integer or a tensor')
    if layout == torch.strided:
        if isinstance(start, Tensor) or isinstance(length, Tensor):
            raise RuntimeError('start and length must be integers for the strided layout NT impl')
        nt = as_nested_tensor(torch.unbind(tensor), layout=torch.strided).narrow(dim, start, length)
    elif layout == torch.jagged:
        if dim != 1:
            raise RuntimeError('jagged layout only supports dim=1')
        from torch.nested._internal.nested_tensor import jagged_from_tensor_and_lengths
        if isinstance(start, (int, SymInt)):
            start = torch.tensor([start], device=tensor.device, dtype=torch.int64)
        if isinstance(length, (int, SymInt)):
            length = torch.tensor([length], device=tensor.device, dtype=torch.int64)
        nt, _, _ = jagged_from_tensor_and_lengths(tensor, start, length)
    else:
        raise RuntimeError(f'Specified layout is unsupported for nested narrow: {layout}')
    return nt

# --- helper: torch.nested.as_nested_tensor ---
def as_nested_tensor(ts: Tensor | list[Tensor] | tuple[Tensor, ...], dtype: DType | None=None, device: Device | None=None, layout=None) -> Tensor:
    is_tensor_list = isinstance(ts, (list, tuple)) and all((isinstance(t, Tensor) for t in ts))
    if not isinstance(ts, Tensor) and (not is_tensor_list):
        raise TypeError('as_nested_tensor(): Expected first argument to be a tensor or a list / tuple of tensors ')
    if is_tensor_list and (not isinstance(ts, list)):
        ts = list(ts)
    if isinstance(ts, Tensor) and ts.dim() < 2:
        raise RuntimeError('as_nested_tensor(): Expected tensor argument to have dim() > 1')
    if isinstance(ts, Tensor) and ts.is_nested:
        if layout == ts.layout:
            return ts.to(device=device, dtype=dtype)
        else:
            raise RuntimeError('as_nested_tensor(): Converting between nested tensor layouts is not supported')
    if layout is None:
        layout = torch.strided
    if layout == torch.strided:
        if isinstance(ts, Tensor):
            buffer = ts.contiguous().view(-1).to(device=device, dtype=dtype)
            nested_sizes = torch.tensor([t.shape for t in ts])
            return torch._nested_view_from_buffer(buffer, nested_sizes, *torch._nested_compute_contiguous_strides_offsets(nested_sizes))
        else:
            if not isinstance(ts, list):
                raise AssertionError(f'Expected ts to be a list, but got {type(ts).__name__}')
            return torch._nested_tensor_from_tensor_list(ts, dtype, None, device, None)
    elif layout == torch.jagged:
        if isinstance(ts, Tensor):
            if device is None:
                device = ts.device
            values = ts.contiguous().flatten(0, 1).to(device=device, dtype=dtype)
            batch_size = ts.shape[0]
            seq_len = ts.shape[1]
            offsets = torch.arange(0, batch_size * seq_len + 1, seq_len, device=device, dtype=torch.int64)
            from torch.nested._internal.nested_tensor import nested_view_from_values_offsets
            return nested_view_from_values_offsets(values, offsets, min_seqlen=seq_len, max_seqlen=seq_len)
        else:
            from torch.nested._internal.nested_tensor import jagged_from_list
            if not isinstance(ts, list):
                raise AssertionError(f'Expected ts to be a list, but got {type(ts).__name__}')
            nt, _ = jagged_from_list(ts, offsets=None, device=device, dtype=dtype)
            return nt
    else:
        raise RuntimeError(f'Specified layout is unsupported for nested tensors: {layout}')

def nested_tensor_from_jagged(values: Tensor, offsets: Tensor | None=None, lengths: Tensor | None=None, jagged_dim: int | None=None, min_seqlen: int | None=None, max_seqlen: int | None=None) -> Tensor:
    from torch.fx._symbolic_trace import is_fx_tracing
    if is_fx_tracing():
        raise RuntimeError('torch.nested.nested_tensor_from_jagged does not support tracing with fx.symbolic_trace. Use fx.wrap to wrap the function that calls nested_tensor_from_jagged.')
    if offsets is None:
        if lengths is None:
            raise RuntimeError('nested_tensor_from_jagged(): At least one of offsets or lengths is required.')
        else:
            offsets = F.pad(lengths.cumsum(0), (1, 0))
            lengths = None
    if jagged_dim is None:
        jagged_dim = 1
    elif jagged_dim < 1:
        raise ValueError(f'Expected jagged_dim >=1, but got {jagged_dim}.')
    from torch.nested._internal.nested_tensor import nested_view_from_values_offsets_lengths
    return nested_view_from_values_offsets_lengths(values, offsets, lengths, ragged_idx=jagged_dim, min_seqlen=min_seqlen, max_seqlen=max_seqlen)

def activate_flash_attention_impl(impl: str | _FlashAttentionImpl) -> None:
    global _FLASH_ATTENTION_ACTIVE, _FLASH_ATTENTION_IMPLS
    restore_flash_attention_impl(_raise_warn=False)
    register_fn = _FLASH_ATTENTION_IMPLS.get(impl)
    if register_fn is None:
