    functools.update_wrapper(_no_grad_wrapper, func)
    return _no_grad_wrapper

def pad_sequence(sequences: Tensor | list[Tensor], batch_first: bool=False, padding_value: float=0.0, padding_side: str='right') -> Tensor:
