import torch
from typing import Any, List, Tuple, Optional

# Example 1: register a simple Point class as a pytree node using flatten_fn / unflatten_fn
class Point:
    def __init__(self, x: torch.Tensor, y: torch.Tensor) -> None:
        self.x = x
        self.y = y

def flatten_point(instance: Point) -> Tuple[List[Any], Any]:
    # return list of leaves and a context (here store dtype as context)
    return [instance.x, instance.y], {"dtype": instance.x.dtype}

def unflatten_point(flattened_leaves: List[Any], context: Any) -> Point:
    x, y = flattened_leaves
    # context could be used to restore metadata; not strictly necessary here
    return Point(x, y)

# Call the API exactly as named
result = torch.return_types.register_pytree_node(
    Point,
    flatten_point,
    unflatten_point,
    serialized_type_name="examples.Point",
)

# The call itself registers the type globally for PyTorch's pytree utilities.
print("registered Point ->", result)

