@_disable_dynamo_if_unsupported(single_tensor_fn=_single_tensor_nadam)
def nadam(params: list[Tensor], grads: list[Tensor], exp_avgs: list[Tensor], exp_avg_sqs: list[Tensor], mu_products: list[Tensor], state_steps: list[Tensor], decoupled_weight_decay: bool=False, foreach: bool | None=None, capturable: bool=False, differentiable: bool=False, has_complex: bool=False, maximize: bool=False, *, beta1: float, beta2: float, lr: float, weight_decay: float, momentum_decay: float, eps: float) -> None:
    if not all((isinstance(t, torch.Tensor) for t in state_steps)):
        raise RuntimeError('API has changed, `state_steps` argument must contain a list of singleton tensors')
    if not all((isinstance(t, torch.Tensor) for t in mu_products)):
        raise RuntimeError('API has changed, `mu_products` argument must contain a list of singleton tensors')
    if foreach is None:
        _, foreach = _default_to_fused_or_foreach(params, differentiable, use_fused=False)
    if foreach and torch.jit.is_scripting():
        raise RuntimeError('torch.jit.script not supported with foreach optimizers')
    if foreach and (not torch.jit.is_scripting()):
        func = _multi_tensor_nadam
    else:
        func = _single_tensor_nadam
    func(params, grads, exp_avgs, exp_avg_sqs, mu_products, state_steps, beta1=beta1, beta2=beta2, lr=lr, weight_decay=weight_decay, momentum_decay=momentum_decay, maximize=maximize, decoupled_weight_decay=decoupled_weight_decay, eps=eps, capturable=capturable, differentiable=differentiable, has_complex=has_complex)

class SGD(Optimizer):

    def __init__(self, params: ParamsT, lr: float | Tensor=0.001, momentum: float=0, dampening: float=0, weight_decay: float | Tensor=0, nesterov: bool=False, *, maximize: bool=False, foreach: bool | None=None, differentiable: bool=False, fused: bool | None=None) -> None:
        if isinstance(lr, Tensor) and lr.numel() != 1:
            raise ValueError('Tensor lr must be 1-element')
        if lr < 0.0:
            raise ValueError(f'Invalid learning rate: {lr}')
        if momentum < 0.0:
            raise ValueError(f'Invalid momentum value: {momentum}')
        if weight_decay < 0.0:
            raise ValueError(f'Invalid weight_decay value: {weight_decay}')
        defaults = {'lr': lr, 'momentum': momentum, 'dampening': dampening, 'weight_decay': weight_decay, 'nesterov': nesterov, 'maximize': maximize, 'foreach': foreach, 'differentiable': differentiable, 'fused': fused}
        if nesterov and (momentum <= 0 or dampening != 0):
            raise ValueError('Nesterov momentum requires a momentum and zero dampening')
        super().__init__(params, defaults)
        if fused:
            self._step_supports_amp_scaling = True
            self._need_device_dtype_check_for_fused = True
            if differentiable:
                raise RuntimeError('`fused` does not support `differentiable`')
            if foreach:
                raise RuntimeError('`fused` and `foreach` cannot be `True` together.')

    def __setstate__(self, state):
        super().__setstate__(state)
        for group in self.param_groups:
            group.setdefault('nesterov', False)
            group.setdefault('maximize', False)
            group.setdefault('foreach', None)
            group.setdefault('differentiable', False)
            group.setdefault('fused', False)

    def _init_group(self, group, params, grads, momentum_buffer_list):
        has_sparse_grad = False
        for p in group['params']:
            if p.grad is not None:
                if group['fused'] and getattr(self, '_need_device_dtype_check_for_fused', True):
                    _device_dtype_check_for_fused(p)
                    self._need_device_dtype_check_for_fused = False
                params.append(p)
                grads.append(p.grad)
                if p.grad.is_sparse:
                    has_sparse_grad = True
                if group['momentum'] != 0:
                    state = self.state[p]
                    momentum_buffer_list.append(state.get('momentum_buffer'))
        return has_sparse_grad

    @_use_grad_for_differentiable
    def step(self, closure=None):
        loss = None
        if closure is not None:
            with torch.enable_grad():
                loss = closure()
        for group in self.param_groups:
            params: list[Tensor] = []
            grads: list[Tensor] = []
            momentum_buffer_list: list[Tensor | None] = []
            has_sparse_grad = self._init_group(group, params, grads, momentum_buffer_list)
            sgd(params, grads, momentum_buffer_list, weight_decay=group['weight_decay'], momentum=group['momentum'], lr=group['lr'], dampening=group['dampening'], nesterov=group['nesterov'], maximize=group['maximize'], has_sparse_grad=has_sparse_grad, foreach=group['foreach'], fused=group['fused'], grad_scale=getattr(self, 'grad_scale', None), found_inf=getattr(self, 'found_inf', None))
            if group['momentum'] != 0:
                for p, momentum_buffer in zip(params, momentum_buffer_list, strict=True):
                    state = self.state[p]
                    state['momentum_buffer'] = momentum_buffer
        return loss

# --- helper: torch.optim.sgd.sgd ---
def sgd(params: list[Tensor], d_p_list: list[Tensor], momentum_buffer_list: list[Tensor | None], has_sparse_grad: bool=False, foreach: bool | None=None, fused: bool | None=None, grad_scale: Tensor | None=None, found_inf: Tensor | None=None, *, weight_decay: float, momentum: float, lr: float, dampening: float, nesterov: bool, maximize: bool) -> None:
    if foreach is None and fused is None:
        if not torch.jit.is_scripting():
            fused, foreach = _default_to_fused_or_foreach(params, differentiable=False, use_fused=False)
        else:
            foreach = False
            fused = False
    if foreach is None:
        foreach = False
    if fused is None:
        fused = False
    if foreach and torch.jit.is_scripting():
        raise RuntimeError('torch.jit.script not supported with foreach optimizers')
    if fused and torch.jit.is_scripting():
        raise RuntimeError('torch.jit.script not supported with fused optimizers')
    if foreach and (not torch.jit.is_scripting()):
        func = _multi_tensor_sgd
    elif fused and (not torch.jit.is_scripting()):
        func = _fused_sgd
    else:
        func = _single_tensor_sgd
    func(params, d_p_list, momentum_buffer_list, weight_decay=weight_decay, momentum=momentum, lr=lr, dampening=dampening, nesterov=nesterov, has_sparse_grad=has_sparse_grad, maximize=maximize, grad_scale=grad_scale, found_inf=found_inf)

class set_default_mmap_options:

    def __init__(self, flags: int) -> None:
        if IS_WINDOWS:
            raise RuntimeError('Changing the default mmap options is currently not supported for Windows')
        if flags != MAP_PRIVATE and flags != MAP_SHARED:
            raise ValueError(f'Invalid argument in function set_default_mmap_options, expected mmap.MAP_PRIVATE or mmap.MAP_SHARED, but got {flags}')
        from torch.utils.serialization import config
        self.prev = config.load.mmap_flags
        config.load.mmap_flags = flags

    def __enter__(self) -> None:
        pass

    def __exit__(self, exc_type: Any, exc_value: Any, traceback: Any) -> None:
        from torch.utils.serialization import config
        config.load.mmap_flags = self.prev

def set_crc32_options(compute_crc32: bool):
    from torch.utils.serialization import config
    config.save.compute_crc32 = compute_crc32

def sym_ite(b, t, f):
    if overrides.has_torch_function((b, t, f)):
        return overrides.handle_torch_function(sym_ite, (b, t, f), b, t, f)
    if not isinstance(b, (SymBool, builtins.bool)):
        raise AssertionError(f'expected SymBool or bool, got {type(b)}')
    if type(t) is not type(f):
        raise AssertionError(f'type mismatch: {type(t)} vs {type(f)}')
    if isinstance(b, SymBool):
        return b.__sym_ite__(t, f)
    return t if b else f

# --- helper: torch.SymBool ---
class SymBool:

    def __init__(self, node):
        self.node = node

    def __bool__(self):
        return self.node.bool_()

    def __int__(self):
        return builtins.int(self.node.bool_())

    def __and__(self, other) -> 'SymBool':
        raise TypeError('type stub not overridden')

    def __or__(self, other) -> 'SymBool':
        raise TypeError('type stub not overridden')

    def __sym_not__(self) -> 'SymBool':
        raise TypeError('type stub not overridden')

    def __sym_ite__(self, then_val, else_val):
        raise TypeError('type stub not overridden')

    def __eq__(self, other) -> builtins.bool:
        raise TypeError('type stub not overridden')

    def __repr__(self):
        return self.node._graph_repr()

    def _sympy_(self):
        return self.node.expr

    def __hash__(self):
        if self.node.is_constant():
            return hash(self.node.bool_())
        else:
            return hash(builtins.bool(self))

    def __sym_float__(self):
        from torch.fx.experimental.sym_node import wrap_node
        return wrap_node(self.node.sym_float())

def typename(obj: _Any, /) -> str:
    if isinstance(obj, torch.Tensor):
        return obj.type()
    module = getattr(obj, '__module__', '') or ''
    qualname = ''
    if hasattr(obj, '__qualname__'):
        qualname = obj.__qualname__
    elif hasattr(obj, '__name__'):
        qualname = obj.__name__
    else:
        module = obj.__class__.__module__ or ''
        qualname = obj.__class__.__qualname__
    if module in {'', 'builtins'}:
        return qualname
    return f'{module}.{qualname}'

def generate_methods_for_privateuse1_backend(for_tensor: bool=True, for_module: bool=True, for_packed_sequence: bool=True, for_storage: bool=False, unsupported_dtype: list[torch.dtype] | None=None) -> None:
    custom_backend_name = _get_privateuse1_backend_name()
    if for_tensor:
        _generate_tensor_methods_for_privateuse1_backend(custom_backend_name)
    if for_module:
        _generate_module_methods_for_privateuse1_backend(custom_backend_name)
    if for_storage:
        _generate_storage_methods_for_privateuse1_backend(custom_backend_name, unsupported_dtype)
    if for_packed_sequence:
        _generate_packed_sequence_methods_for_privateuse1_backend(custom_backend_name)

# --- helper: torch.utils.backend_registration._generate_module_methods_for_privateuse1_backend ---
def _generate_module_methods_for_privateuse1_backend(custom_backend_name: str) -> None:
    if not hasattr(torch.Tensor, custom_backend_name):
        raise RuntimeError(f"Can not automatically generate {custom_backend_name}() method for torch.nn.Module.Because torch.Tensor doesn't has the method {custom_backend_name}().For this error, you can try setting for_tensor=True.")

    def wrap_module_to(self: torch.nn.modules.module.T, device: int | torch.device | None=None) -> torch.nn.modules.module.T:
        return self._apply(lambda t: getattr(t, custom_backend_name)(device))
    _check_register_once(torch.nn.Module, custom_backend_name)
    setattr(torch.nn.Module, custom_backend_name, wrap_module_to)

# --- helper: torch.utils.backend_registration._generate_packed_sequence_methods_for_privateuse1_backend ---
def _generate_packed_sequence_methods_for_privateuse1_backend(custom_backend_name: str) -> None:
    if not hasattr(torch.Tensor, f'is_{custom_backend_name}') or not hasattr(torch.Tensor, custom_backend_name):
        raise RuntimeError(f"Can not automatically generate is_{custom_backend_name}() or {custom_backend_name}() method for torch.nn.utils.rnn.PackedSequence.Because torch.Tensor doesn't has the method is_{custom_backend_name}()or {custom_backend_name}().For this error, you can try setting for_tensor=True.")

    @property
    def wrap_tensor_backend(self: torch.nn.utils.rnn.PackedSequence) -> bool:
        return self.data.device.type == custom_backend_name
    _check_register_once(torch.nn.utils.rnn.PackedSequence, f'is_{custom_backend_name}')
    setattr(torch.nn.utils.rnn.PackedSequence, f'is_{custom_backend_name}', wrap_tensor_backend)

    def wrap_module_to(self: torch.nn.utils.rnn.PackedSequence, *args, **kwargs) -> torch.nn.utils.rnn.PackedSequence:
        ex = torch.tensor((), dtype=self.data.dtype, device=self.data.device).to(*args, **kwargs)
        if ex.device.type == custom_backend_name:
            return self.to(*args, **kwargs)
        kwargs.update({'device': custom_backend_name})
        return self.to(*args, **kwargs)
    _check_register_once(torch.nn.utils.rnn.PackedSequence, custom_backend_name)
    setattr(torch.nn.utils.rnn.PackedSequence, custom_backend_name, wrap_module_to)

# --- helper: torch.utils.backend_registration._generate_storage_methods_for_privateuse1_backend ---
def _generate_storage_methods_for_privateuse1_backend(custom_backend_name: str, unsupported_dtype: list[torch.dtype] | None=None) -> None:

    @property
    def wrap_storage_backend(self: torch.storage._StorageBase) -> bool:
        return self.device.type == custom_backend_name
    _check_register_once(torch.storage._StorageBase, f'is_{custom_backend_name}')
    setattr(torch.storage._StorageBase, f'is_{custom_backend_name}', wrap_storage_backend)

    def wrap_storage_to(self, device=None, non_blocking=False):
        device_idx = _normalization_device(custom_backend_name, device)
        if getattr(self, f'is_{custom_backend_name}'):
            if self.get_device() == device_idx:
                return self
        if self.is_sparse:
            raise RuntimeError(f'Can not support a sparse storage move to {custom_backend_name} backend')
        untyped_storage = torch.UntypedStorage(self.size(), device=torch.device(f'{custom_backend_name}:{device_idx}'))
        untyped_storage.copy_(self, non_blocking)
        return untyped_storage
    _check_register_once(torch.storage._StorageBase, custom_backend_name)
    setattr(torch.storage._StorageBase, custom_backend_name, wrap_storage_to)

    @property
    def wrap_typed_storage_backend(self: torch.storage.TypedStorage) -> bool:
        torch.storage._warn_typed_storage_removal()
        return self._untyped_storage.device.type == custom_backend_name
    _check_register_once(torch.TypedStorage, f'is_{custom_backend_name}')
    setattr(torch.storage.TypedStorage, f'is_{custom_backend_name}', wrap_typed_storage_backend)

    def wrap_typed_storage_to(self: torch.storage.TypedStorage, device=None, non_blocking=False, **kwargs) -> torch.storage.TypedStorage:
        torch.storage._warn_typed_storage_removal()
        if unsupported_dtype and self.dtype in unsupported_dtype:
            raise RuntimeError(f'Cannot create {custom_backend_name} storage as {self.dtype} dtype is not supported by this backend')
        custom_backend_storage: torch.UntypedStorage = getattr(self._untyped_storage, custom_backend_name)(device, non_blocking, **kwargs)
        return self._new_wrapped_storage(custom_backend_storage)
    _check_register_once(torch.TypedStorage, custom_backend_name)
    setattr(torch.TypedStorage, custom_backend_name, wrap_typed_storage_to)

# --- helper: torch.utils.backend_registration._generate_tensor_methods_for_privateuse1_backend ---
def _generate_tensor_methods_for_privateuse1_backend(custom_backend_name: str) -> None:

    @property
    def wrap_tensor_backend(self: torch.Tensor) -> bool:
        if has_torch_function_unary(self):
            return handle_torch_function(wrap_tensor_backend.__get__, (self,), self)
        return self.device.type == custom_backend_name
    _check_register_once(torch.Tensor, f'is_{custom_backend_name}')
    wrap_tensor_backend.fget.__name__ = f'is_{custom_backend_name}'
    setattr(torch.Tensor, f'is_{custom_backend_name}', wrap_tensor_backend)

    def wrap_tensor_to(self: torch.Tensor, device: int | torch.device | None=None, non_blocking=False, **kwargs) -> torch.Tensor:
        if has_torch_function_unary(self):
            return handle_torch_function(wrap_tensor_to, (self,), self, device=device, non_blocking=False, **kwargs)
        device_idx = _normalization_device(custom_backend_name, device)
        return self.to(device=torch.device(f'{custom_backend_name}:{device_idx}'), non_blocking=non_blocking, **kwargs)
    _check_register_once(torch.Tensor, custom_backend_name)
    wrap_tensor_to.__name__ = custom_backend_name
    setattr(torch.Tensor, custom_backend_name, wrap_tensor_to)

class SparseSemiStructuredTensorCUSPARSELT(SparseSemiStructuredTensor):
    BACKEND = 'cusparselt'
    _DTYPE_SHAPE_CONSTRAINTS = {torch.float8_e4m3fn: _SEMI_STRUCTURED_SPARSE_CONFIG(32, 32, 16, 16), torch.int8: _SEMI_STRUCTURED_SPARSE_CONFIG(32, 32, 16, 16), torch.float16: _SEMI_STRUCTURED_SPARSE_CONFIG(16, 16, 8, 8), torch.bfloat16: _SEMI_STRUCTURED_SPARSE_CONFIG(16, 16, 8, 8)}

    @classmethod
    def from_dense(cls, original_tensor: torch.Tensor) -> 'SparseSemiStructuredTensorCUSPARSELT':
        cls._validate_device_dim_dtype_shape(original_tensor)
        return cls(shape=original_tensor.shape, packed=torch._cslt_compress(original_tensor), meta=None, packed_t=None, meta_t=None, compressed_swizzled_bitmask=None, fuse_transpose_cusparselt=SparseSemiStructuredTensor._FUSE_TRANSPOSE, alg_id_cusparselt=SparseSemiStructuredTensor._DEFAULT_ALG_ID, requires_grad=original_tensor.requires_grad)

    @classmethod
    def prune_dense_static_sort(cls, original_tensor: torch.Tensor, algorithm='') -> 'SparseSemiStructuredTensor':
        packed, meta, packed_t, meta_t, compressed_swizzled_bitmask = torch._sparse_semi_structured_tile(original_tensor, algorithm=algorithm, use_cutlass=False)
        packed = packed.view(original_tensor.shape[0], -1)
        packed_t = packed_t.view(original_tensor.shape[1], -1)
        return cls(original_tensor.shape, packed=packed, meta=meta, packed_t=packed_t, meta_t=meta_t, compressed_swizzled_bitmask=compressed_swizzled_bitmask, requires_grad=False)

    def _mm(self, B: torch.Tensor, *, bias: torch.Tensor | None=None, **kwargs) -> torch.Tensor:
        if isinstance(B, SparseSemiStructuredTensor):
            raise ValueError('`SparseSemiStructuredTensor @ SparseSemiStructuredTensor` is not supported by the hardware')
        if self.ndim != 2 or B.ndim != 2:
            raise NotImplementedError(f'`{self.__class__.__name__}` matmul: Broadcasting is not implemented')
        if B.dtype != self.dtype:
            raise NotImplementedError(f'`{self.__class__.__name__}` matmul: trying to do `A={tuple(self.shape)} @ B={tuple(B.shape)}`, with A.dtype={self.dtype} and B.dtype={B.dtype}. This operation is only supported when A and B have the same data type.')
        if bias is not None and bias.dtype != self.dtype:
            raise NotImplementedError(f'`{self.__class__.__name__}` matmul: trying to do `A={tuple(self.shape)} @ B={tuple(B.shape)} + C`, with A.dtype=B.dtype={self.dtype} and C.dtype={B.dtype}. This operation is only supported when A, B and C have the same data type.')
        if self.dtype == torch.float8_e4m3fn:
            raise NotImplementedError(f'`{self.__class__.__name__}` matmul: trying to do `A={tuple(self.shape)} @ B={tuple(B.shape)}`, with A.dtype=B.dtype={self.dtype}. mm is not supported for float8_e4m3fn, please use `torch._scaled_mm` instead.')
        if self.packed is None:
            raise NotImplementedError(f'`{self.__class__.__name__}` matmul: operation is not supported')
        else:
            res = torch._cslt_sparse_mm(self.packed, B, bias=bias, transpose_result=self.fuse_transpose_cusparselt, alg_id=self.alg_id_cusparselt)
            return res.t() if self.fuse_transpose_cusparselt else res

# --- helper: torch.sparse.semi_structured.SparseSemiStructuredTensor ---
class SparseSemiStructuredTensor(torch.Tensor):
    _DEFAULT_ALG_ID: int = 0
    _DTYPE_SHAPE_CONSTRAINTS: dict[torch.dtype, _SEMI_STRUCTURED_SPARSE_CONFIG]
    _FORCE_CUTLASS: bool = False
    _FUSE_TRANSPOSE: bool = False
    _PROTOTYPE_WARNING_SHOWN: bool = False
