def _checkpoint_without_reentrant_generator(fn, preserve_rng_state=True, context_fn: Callable[[], Tuple[ContextManager, ContextManager]]=noop_context_fn, determinism_check: str=_DEFAULT_DETERMINISM_MODE, debug: bool=False, early_stop: bool=True, *args, **kwargs):
