    else:
        raise ValueError(f'determinism_check should be one of {list(_allowed_determinism_checks_to_fns.keys())}, but got {determinism_check}')
    device_type = _infer_device_type(*args)
    device_module = _get_device_module(device_type)
    forward_context, recompute_context = context_fn()
    if _is_compiling(fn, args, kwargs) and context_fn is not noop_context_fn:
        if not isinstance(forward_context, TorchDispatchMode) or not isinstance(recompute_context, TorchDispatchMode):
            raise AssertionError('In torch.compile mode, `context_fn` arg passed to `torch.utils.checkpoint` must generate a tuple of two `TorchDispatchMode`s.')
    device_autocast_kwargs, cpu_autocast_kwargs = _get_autocast_kwargs(device_type=device_type)
    if preserve_rng_state:
        fwd_cpu_state = torch.get_rng_state()
        had_device_in_fwd = False
        if getattr(device_module, '_initialized', False):
            had_device_in_fwd = True
            fwd_devices, fwd_device_states = get_device_states(*args)
    from torch.overrides import _get_current_function_mode_stack
    from torch.utils._device import DeviceContext
    device_ctx = next(filter(lambda mode: isinstance(mode, DeviceContext), reversed(_get_current_function_mode_stack())), contextlib.nullcontext())

    def recompute_fn(*inputs) -> None:
        kwargs, *args = inputs
        rng_devices = []
        if preserve_rng_state and had_device_in_fwd:
            rng_devices = fwd_devices
        with torch.random.fork_rng(devices=rng_devices, enabled=preserve_rng_state, device_type=device_type):
            if preserve_rng_state:
                torch.set_rng_state(fwd_cpu_state)
                if had_device_in_fwd:
                    set_device_states(fwd_devices, fwd_device_states, device_type=device_type)
            device_autocast_ctx = torch.amp.autocast(device_type=device_type, **device_autocast_kwargs) if torch.amp.is_autocast_available(device_type) else contextlib.nullcontext()
            with device_autocast_ctx, torch.amp.autocast('cpu', **cpu_autocast_kwargs), recompute_context, device_ctx:
                fn(*args, **kwargs)
    new_frame = _CheckpointFrame(recompute_fn, _enable_checkpoint_early_stop if _enable_checkpoint_early_stop is not None else early_stop, unpack_error_cb, metadata_fn)
    dummy = torch.empty((0,), requires_grad=True)
    new_frame.input_saver = _NoopSaveInputs.apply(dummy, kwargs, *args)
    if new_frame.input_saver.grad_fn is None:
        yield
        return
    with _checkpoint_hook(new_frame), forward_context:
        yield
    new_frame.forward_completed = True
    if getattr(device_module, '_initialized', False) and preserve_rng_state and (not had_device_in_fwd):
        raise RuntimeError("PyTorch's device state was initialized in the forward pass of a Checkpoint, which is not allowed. Please open an issue if you need this feature.")
    return

