def get_pip_packages(run_lambda, patterns=None):
    if patterns is None:
        patterns = PIP_PATTERNS + COMMON_PATTERNS + NVIDIA_PATTERNS + ONEAPI_PATTERNS
    pip_version = 'pip3' if sys.version_info.major == 3 else 'pip'
    os.environ['PIP_DISABLE_PIP_VERSION_CHECK'] = '1'
    out = run_and_read_all(run_lambda, [sys.executable, '-mpip', 'list', '--format=freeze'])
    if out is None:
        return (pip_version, out)
    filtered_out = '\n'.join((line for line in out.splitlines() if any((name in line for name in patterns))))
    return (pip_version, filtered_out)

# --- helper: torch.utils.collect_env.run_and_read_all ---
def run_and_read_all(run_lambda, command):
    rc, out, _ = run_lambda(command)
    if rc != 0:
        return None
    return out

def create_selective_checkpoint_contexts(policy_fn_or_list, allow_cache_entry_mutation=False):
    if isinstance(policy_fn_or_list, list):
        for op in policy_fn_or_list:
            if not isinstance(op, (torch._ops.OpOverload, torch._ops.HigherOrderOperator)):
                _extra_msg = 'Please update the OpOverloadPacket to a specific OpOverload.For example, if you have `torch.ops.aten.mm`, change it to `torch.ops.aten.mm.default`.' if isinstance(op, torch._ops.OpOverloadPacket) else ''
                raise ValueError(f'Expected op in `op_list` to be an OpOverload but got: {op} of type {type(op)}. {_extra_msg}')

        def policy_fn(ctx, op, *args, **kwargs):
            if op in policy_fn_or_list:
                return CheckpointPolicy.MUST_SAVE
            else:
                return CheckpointPolicy.PREFER_RECOMPUTE
    elif callable(policy_fn_or_list):
        policy_fn = policy_fn_or_list
    else:
        raise TypeError('policy_fn_or_list must be either a function or a list of ops.')
    storage: Dict[Any, List[Any]] = defaultdict(list)
    return (_CachingTorchDispatchMode(policy_fn, storage), _CachedTorchDispatchMode(policy_fn, storage, allow_cache_entry_mutation))

