class _CachedTorchDispatchMode(TorchDispatchMode):

    @classmethod
    def ignore_compile_internals(cls):
        return True

    def __init__(self, policy_fn, storage, allow_cache_entry_mutation) -> None:
        self.policy_fn = policy_fn
        self.storage = storage
        self.allow_cache_entry_mutation = allow_cache_entry_mutation

    def __torch_dispatch__(self, func, types, args=(), kwargs=None):
        if func in SAC_IGNORED_OPS:
            return func(*args, **kwargs)
        kwargs = {} if kwargs is None else kwargs
        policy = self.policy_fn(SelectiveCheckpointContext(is_recompute=True), func, *args, **kwargs)
        if isinstance(policy, bool):
            policy = _policy_from_bool(policy)
        is_compiling = _is_compiling(func, args, kwargs)
        if policy in (CheckpointPolicy.MUST_SAVE, CheckpointPolicy.PREFER_SAVE) or is_compiling:
            storage = self.storage.get(func)
            if storage is None:
                raise RuntimeError(f'{func} encountered during backward, but not found in storage')
            if len(storage) == 0:
                raise RuntimeError('Trying to backward an extra time. You are only allowed to backward once on any region computed under selective activation checkpoint.')
            out = tree_map(lambda x: x.get_val(self.allow_cache_entry_mutation), storage.pop(0))
        else:
            out = func(*args, **kwargs)
        return out

