def _accepted_compilers_for_platform() -> list[str]:
    return ['clang++', 'clang'] if IS_MACOS else ['g++', 'gcc', 'gnu-c++', 'gnu-cc', 'clang++', 'clang']

# --- helper: torch.utils.cpp_extension._is_binary_build ---
def _is_binary_build() -> bool:
    return not BUILT_FROM_SOURCE_VERSION_PATTERN.match(torch.version.__version__)

# --- helper: torch.utils.cpp_extension.check_compiler_ok_for_platform ---
def check_compiler_ok_for_platform(compiler: str) -> bool:
    if IS_WINDOWS:
        return True
    compiler_path = shutil.which(compiler)
    if compiler_path is None:
        return False
    compiler_path = os.path.realpath(compiler_path)
    if any((name in compiler_path for name in _accepted_compilers_for_platform())):
        return True
    env = os.environ.copy()
    env['LC_ALL'] = 'C'
    try:
        version_string = subprocess.check_output([compiler, '-v'], stderr=subprocess.STDOUT, env=env).decode(*SUBPROCESS_DECODE_ARGS)
    except subprocess.CalledProcessError:
        version_string = subprocess.check_output([compiler, '--version'], stderr=subprocess.STDOUT, env=env).decode(*SUBPROCESS_DECODE_ARGS)
    if IS_LINUX:
        pattern = re.compile('^COLLECT_GCC=(.*)$', re.MULTILINE)
        results = re.findall(pattern, version_string)
        if len(results) != 1:
            return 'clang version' in version_string
        compiler_path = os.path.realpath(results[0].strip())
        if os.path.basename(compiler_path) == 'c++' and 'gcc version' in version_string:
            return True
        return any((name in compiler_path for name in _accepted_compilers_for_platform()))
    if IS_MACOS:
        return version_string.startswith('Apple clang')
    return False

def verify_ninja_availability() -> None:
    if not is_ninja_available():
        raise RuntimeError('Ninja is required to load C++ extensions (pip install ninja to get it)')

# --- helper: torch.utils.cpp_extension.is_ninja_available ---
def is_ninja_available() -> bool:
    try:
        subprocess.check_output(['ninja', '--version'])
    except Exception:
        return False
    else:
        return True

