# Instantiate the Sampler base class (no parameters)
base_sampler = sampler_module.Sampler()
print(type(base_sampler))

# Define a tiny dataset and a concrete sampler subclass that implements __iter__
class SimpleDataset(Dataset):
    def __init__(self, n):
        self.data = list(range(n))
    def __len__(self):
        return len(self.data)
    def __getitem__(self, idx):
        return self.data[idx]

class ReverseSampler(sampler_module.Sampler):
    def __init__(self, data_source):
        super().__init__()
        self.data_source = data_source
    def __iter__(self):
        # yield indices in reverse order
        return iter(range(len(self.data_source) - 1, -1, -1))
    def __len__(self):
        return len(self.data_source)

dataset = SimpleDataset(5)
rev_sampler = ReverseSampler(dataset)
print(list(iter(rev_sampler)))  # prints indices in reverse: [4, 3, 2, 1, 0]

