_s = sampler_module.Sampler()
print('Instantiated base Sampler:', isinstance(_s, sampler_module.Sampler))

# Batch-style sampler: yields lists of indices
class BatchSamplerExample(sampler_module.Sampler):
    def __init__(self, data_source, batch_size):
        super().__init__()
        self.data_source = data_source
        self.batch_size = batch_size
    def __len__(self):
        return (len(self.data_source) + self.batch_size - 1) // self.batch_size
    def __iter__(self):
        n = len(self.data_source)
        for i in range(0, n, self.batch_size):
            yield list(range(i, min(i + self.batch_size, n)))

