class XIELUActivation(nn.Module):

    def __init__(self, alpha_p_init=0.8, alpha_n_init=0.8, beta=0.5, eps=-1e-06, dtype=torch.bfloat16, with_vector_loads=False):
        super().__init__()
        self.alpha_p = nn.Parameter(torch.log(torch.expm1(torch.tensor(alpha_p_init, dtype=dtype))).unsqueeze(0))
        self.alpha_n = nn.Parameter(torch.log(torch.expm1(torch.tensor(alpha_n_init - beta, dtype=dtype))).unsqueeze(0))
        self.register_buffer('beta', torch.tensor(beta, dtype=dtype))
        self.register_buffer('eps', torch.tensor(eps, dtype=dtype))
        self.with_vector_loads = with_vector_loads
        self._beta_scalar = float(beta)
        self._eps_scalar = float(eps)
        self._xielu_cuda_obj = None
        try:
            import xielu.ops
            self._xielu_cuda_obj = torch.classes.xielu.XIELU()
            msg = 'Using experimental xIELU CUDA.'
            try:
                from torch.compiler import allow_in_graph
                self._xielu_cuda_fn = allow_in_graph(self._xielu_cuda)
                msg += ' Enabled torch._dynamo for xIELU CUDA.'
            except Exception as err:
                msg += f' Could not enable torch._dynamo for xIELU ({err}) - this may result in slower performance.'
                self._xielu_cuda_fn = self._xielu_cuda
            logger.warning_once(msg)
        except Exception as err:
            logger.warning_once(f'CUDA-fused xIELU not available ({err}) – falling back to a Python version.\nFor CUDA xIELU (experimental), `pip install git+https://github.com/nickjbrowning/XIELU`')

    def _xielu_python(self, x: Tensor) -> Tensor:
        alpha_p = nn.functional.softplus(self.alpha_p)
        alpha_n = self.beta + nn.functional.softplus(self.alpha_n)
        return torch.where(x > 0, alpha_p * x * x + self.beta * x, (torch.expm1(torch.min(x, self.eps)) - x) * alpha_n + self.beta * x)

    def _xielu_cuda(self, x: Tensor) -> Tensor:
        original_shape = x.shape
        while x.dim() < 3:
            x = x.unsqueeze(0)
        if x.dim() > 3:
            x = x.view(-1, 1, x.size(-1))
        if original_shape != x.shape:
            logger.warning_once('Warning: xIELU input tensor expects 3 dimensions but got (shape: %s). Reshaping to (shape: %s).', original_shape, x.shape)
        result = self._xielu_cuda_obj.forward(x, self.alpha_p.to(x.dtype), self.alpha_n.to(x.dtype), self._beta_scalar, self._eps_scalar, self.with_vector_loads)
        return result.view(original_shape)

    def forward(self, input: Tensor) -> Tensor:
        if self._xielu_cuda_obj is not None and input.is_cuda:
            if not is_torchdynamo_compiling():
                return self._xielu_cuda_fn(input)
            else:
                logger.warning_once('torch._dynamo is compiling, using Python version of xIELU.')
        return self._xielu_python(input)

def get_user_field(question: str, default_value: str | None=None, convert_to: Callable | None=None, fallback_message: str | None=None) -> Any:
    if not question.endswith(' '):
        question = question + ' '
    if default_value is not None:
        question = f'{question} [{default_value}] '
    valid_answer = False
    while not valid_answer:
        answer = input(question)
        if default_value is not None and len(answer) == 0:
            answer = default_value
        if convert_to is not None:
            try:
                answer = convert_to(answer)
                valid_answer = True
            except Exception:
                valid_answer = False
        else:
            valid_answer = True
        if not valid_answer:
            print(fallback_message)
    return answer

