class ErnieSplitAndDecoupleTextVisionExperts(ConversionOps):

    def __init__(self, stack_dim: int=0, concat_dim: int=1):
        self.stack_dim = stack_dim
        self.concat_dim = concat_dim

    @torch.no_grad()
    def convert(self, input_dict: dict[str, list[torch.Tensor]], source_patterns: list[str], target_patterns: list[str], config, **kwargs) -> dict[str, list[torch.Tensor]]:
        fused_modules = len(target_patterns)
        valid_keys = input_dict.keys()
        split_tensors = []
        for key in source_patterns:
            if key not in valid_keys:
                raise ValueError(f'Expected pattern {key} in collected tensors but only found tensors for: {valid_keys}')
            split_tensors.append(input_dict[key][0].chunk(fused_modules, dim=self.concat_dim))
        decoupled = {}
        for idx, key in enumerate(target_patterns):
            tensor_groups = [list(torch.unbind(tensor_group[idx], dim=self.stack_dim)) for tensor_group in split_tensors]
            tensor_list = list(chain.from_iterable(tensor_groups))
            targets = [key.replace('*', f'{i}') for i in range(len(tensor_list))]
            decoupled |= dict(zip(targets, tensor_list))
        return decoupled

    @property
    def reverse_op(self) -> ConversionOps:
        return ErnieFuseAndSplitTextVisionExperts(stack_dim=self.stack_dim, concat_dim=self.concat_dim)

# --- helper: transformers.core_model_loading.ConversionOps ---
class ConversionOps:

    def __repr__(self):
        if hasattr(self, 'dim'):
            return f'{self.__class__.__name__}(dim={self.dim})'
        else:
            return f'{self.__class__.__name__}'

    @abstractmethod
    def convert(self, input_dict: dict[str, Any], source_patterns: list[str], target_patterns: list[str], **kwargs) -> dict[str, list[torch.Tensor]]:
        raise NotImplementedError

    @property
    def reverse_op(self) -> ConversionOps:
        raise NotImplementedError

# --- helper: transformers.core_model_loading.ErnieFuseAndSplitTextVisionExperts ---
class ErnieFuseAndSplitTextVisionExperts(ConversionOps):

    def __init__(self, stack_dim: int=0, concat_dim: int=1):
        self.stack_dim = stack_dim
        self.concat_dim = concat_dim

    def split_list_into_chunks(self, tensor_list: list[torch.Tensor], chunks: int=2):
        split_size = math.ceil(len(tensor_list) / chunks)
        return [tensor_list[i * split_size:(i + 1) * split_size] for i in range(chunks)]

    @torch.no_grad()
    def convert(self, input_dict: dict[str, list[torch.Tensor]], source_patterns: list[str], target_patterns: list[str], config, **kwargs) -> dict[str, list[torch.Tensor]]:
        valid_keys = input_dict.keys()
        split_and_fused = defaultdict(list)
        for key in source_patterns:
            if key not in valid_keys:
                raise ValueError(f'Expected pattern {key} in collected tensors but only found tensors for: {valid_keys}')
            tensors = input_dict.get(key, [])
            split_tensor_lists = self.split_list_into_chunks(tensors, chunks=len(target_patterns))
            stacked_tensors = (torch.stack(tensor_group, dim=self.stack_dim) for tensor_group in split_tensor_lists)
            for idx, tensor_group in enumerate(stacked_tensors):
                split_and_fused[target_patterns[idx]].append(tensor_group)
        for k, v in split_and_fused.items():
            split_and_fused[k] = torch.cat(v, dim=self.concat_dim)
        return split_and_fused

    @property
    def reverse_op(self) -> ConversionOps:
        return ErnieSplitAndDecoupleTextVisionExperts(stack_dim=self.stack_dim, concat_dim=self.concat_dim)

def build_glob_alternation(globs: list[WeightRenaming | WeightConverter | str]) -> tuple[re.Pattern, dict[str, str], dict[str, str]]:
    src_group_to_glob: dict[str, str] = {}
    tgt_group_to_glob: dict[str, str] = {}
    branches: list[str] = []
    i = 0
    for glob in globs:
        if isinstance(glob, (WeightRenaming, WeightConverter)):
            for src in glob.source_patterns:
                group_name = f'g{i}'
                src_group_to_glob[group_name] = src
                i += 1
                body = src.replace('*', '.*')
                branches.append(f'(?P<{group_name}>{body})')
                tgt_group_to_glob[group_name] = glob.target_patterns[0]
        else:
            group_name = f'g{i}'
            src_group_to_glob[group_name] = glob
            i += 1
            body = glob
            body = body.replace('*', '.*')
            branches.append(f'(?P<{group_name}>{body})')
            tgt_group_to_glob[group_name] = glob
    alternation = re.compile('|'.join(branches))
    return (alternation, src_group_to_glob, tgt_group_to_glob)

# --- helper: transformers.core_model_loading.WeightConverter ---
class WeightConverter(WeightTransform):
    __slots__ = ('operations',)

    def __init__(self, source_patterns: str | list[str], target_patterns: str | list[str], operations: list[ConversionOps]):
        super().__init__(source_patterns, target_patterns)
        self.operations: list[ConversionOps] = operations
        if bool(len(self.source_patterns) - 1) + bool(len(self.target_patterns) - 1) >= 2:
            if not any((isinstance(op, _INTERNAL_MANY_TO_MANY_CONVERSIONS) for op in self.operations)):
                raise ValueError(f'source keys={self.source_patterns}, target_patterns={self.target_patterns} but you can only have one to many, one to one or many to one.')
        if not self.operations:
            raise ValueError('WeightConverter requires at least one operation.')

    def convert(self, layer_name: str, model=None, config=None, hf_quantizer=None, loading_info: LoadStateDictInfo | None=None):
        collected_tensors = self.materialize_tensors()
        for op in self.operations:
            with log_conversion_errors(layer_name, loading_info, (len(collected_tensors), layer_name), op):
                collected_tensors = op.convert(collected_tensors, source_patterns=self.source_patterns, target_patterns=self.target_patterns, full_layer_name=layer_name, model=model, config=config, missing_keys=loading_info.missing_keys if loading_info else None)
        full_name = layer_name
        if '.*.' in layer_name:
            full_name = layer_name.replace('.*.', '.0.')
        try:
            prefix, _, suffix = next((full_name.partition(k) for k in collected_tensors.keys() if k in full_name))
            collected_tensors = {prefix + k + suffix: v for k, v in collected_tensors.items()}
        except StopIteration:
            pass
        if hf_quantizer is not None and self.quantization_operation is not None:
            with log_conversion_errors(layer_name, loading_info, (len(collected_tensors), layer_name), self.quantization_operation):
                collected_tensors = self.quantization_operation.convert(collected_tensors, source_patterns=self.source_patterns, target_patterns=self.target_patterns, full_layer_name=layer_name, config=config, model=model, missing_keys=loading_info.missing_keys if loading_info else None)
        return collected_tensors

# --- helper: transformers.core_model_loading.WeightRenaming ---
class WeightRenaming(WeightTransform):
    __slots__ = ()

    def convert(self, layer_name: str, model=None, config=None, hf_quantizer=None, loading_info: LoadStateDictInfo | None=None):
        collected_tensors = self.materialize_tensors()
        target_key = self.target_patterns[0]
        collected_tensors = {target_key: collected_tensors[self.source_patterns[0]]}
        if hf_quantizer is not None and self.quantization_operation is not None:
            with log_conversion_errors(layer_name, loading_info, (len(collected_tensors), layer_name), self.quantization_operation):
                collected_tensors = self.quantization_operation.convert(collected_tensors, source_patterns=self.source_patterns, target_patterns=self.target_patterns, full_layer_name=target_key, model=model, config=config, missing_keys=loading_info.missing_keys if loading_info else None)
        return collected_tensors

class SplitModulelist(ConversionOps):

    def __init__(self, dim: int=0):
        self.dim = dim

    @torch.no_grad
    def convert(self, input_dict: dict[str, torch.Tensor], source_patterns: list[str], target_patterns: list[str], **kwargs) -> dict[str, torch.Tensor]:
        all_tensors = {}
        for source_pattern, tensors in input_dict.items():
            tensor = tensors[0] if isinstance(tensors, list) else tensors
            sizes = tensor.size(self.dim)
            targets = self.get_target_patterns(input_dict, source_pattern, target_patterns, sizes)
            chunks = torch.chunk(tensor, sizes, dim=self.dim)
            all_tensors.update({target: chunk.squeeze() for target, chunk in zip(targets, chunks)})
        return all_tensors

    def get_target_patterns(self, input_dict: dict, source_pattern: str, target_patterns: list[str], sizes: int) -> list[str]:
        if len(input_dict) == 1:
            if len(target_patterns) == 1:
                return [target_patterns[0].replace('*', f'{i}') for i in range(sizes)]
            else:
                raise ValueError('Undefined Operation encountered!')
        else:
            return [source_pattern.replace('*', f'{i}') for i in range(sizes)]

    @property
    def reverse_op(self) -> ConversionOps:
        return MergeModulelist(self.dim)

# --- helper: transformers.core_model_loading.ConversionOps ---
class ConversionOps:

    def __repr__(self):
        if hasattr(self, 'dim'):
            return f'{self.__class__.__name__}(dim={self.dim})'
        else:
            return f'{self.__class__.__name__}'

    @abstractmethod
    def convert(self, input_dict: dict[str, Any], source_patterns: list[str], target_patterns: list[str], **kwargs) -> dict[str, list[torch.Tensor]]:
        raise NotImplementedError

    @property
    def reverse_op(self) -> ConversionOps:
        raise NotImplementedError

# --- helper: transformers.core_model_loading.MergeModulelist ---
class MergeModulelist(ConversionOps):

    def __init__(self, dim: int=0):
        self.dim = dim

    @torch.no_grad
    def convert(self, input_dict: dict[str, list[torch.Tensor]], source_patterns: list[str], target_patterns: list[str], **kwargs) -> dict[str, torch.Tensor]:
        merged: dict[str, torch.Tensor] = {}
        for source_pattern, tensors in input_dict.items():
            target_pattern = self.get_target_pattern(input_dict, source_pattern, target_patterns)
            merged[target_pattern] = torch.stack(tensors, dim=self.dim)
        return merged

    def get_target_pattern(self, input_dict: dict, source_pattern: str, target_patterns: list[str]) -> str:
        if len(input_dict) == 1:
            if len(target_patterns) == 1:
                return target_patterns[0]
            else:
                raise ValueError('Undefined Operation encountered!')
        else:
            return source_pattern

    @property
    def reverse_op(self) -> ConversionOps:
        return SplitModulelist(self.dim)

def get_model_conversion_mapping(model: PreTrainedModel, key_mapping: dict[str, str] | None=None, hf_quantizer: HfQuantizer | None=None, add_legacy: bool=True) -> list[WeightTransform]:
    from .modeling_utils import PreTrainedModel
    weight_conversions = []
    if key_mapping is not None:
        weight_conversions = [WeightRenaming(source_patterns=k, target_patterns=v) for k, v in key_mapping.items()]
    seen_model_types = set()
    for name, submodule in model.named_modules():
        if isinstance(submodule, PreTrainedModel) and submodule.config.model_type not in seen_model_types:
            conversions = extract_weight_conversions_for_model(submodule, name)
            if conversions is not None:
                weight_conversions.extend(conversions)
                seen_model_types.add(submodule.config.model_type)
    if add_legacy:
        weight_conversions.extend(get_checkpoint_conversion_mapping('legacy'))
    if hf_quantizer is not None:
        weight_conversions.extend(hf_quantizer.get_weight_conversions())
    return weight_conversions

# --- helper: transformers.conversion_mapping.extract_weight_conversions_for_model ---
def extract_weight_conversions_for_model(model: PreTrainedModel, model_prefix: str) -> list[WeightTransform] | None:
    model_type = getattr(model.config, 'model_type', None)
    if model_type is not None:
        model_specific_conversions = get_checkpoint_conversion_mapping(model_type)
        if model_specific_conversions is not None and model_prefix != '':
            for i, conversion in enumerate(model_specific_conversions):
                if isinstance(conversion, PrefixChange):
                    model_specific_conversions[i] = conversion.with_submodel_prefix(model_prefix)
        return model_specific_conversions
    return None

# --- helper: transformers.conversion_mapping.get_checkpoint_conversion_mapping ---
def get_checkpoint_conversion_mapping(model_type):
    global _checkpoint_conversion_mapping_cache
    if _checkpoint_conversion_mapping_cache is None:
        _checkpoint_conversion_mapping_cache = _build_checkpoint_conversion_mapping()
    return deepcopy(_checkpoint_conversion_mapping_cache.get(model_type))

def dot_natural_key(s: str):
    result = []
    for p in s.split('.'):
        if p.isdigit():
            result.append((0, int(p)))
        else:
            result.append((1, p))
    return result

def process_source_pattern(source_pattern: str, target_pattern: str) -> str:
    if target_pattern.startswith('^'):
        source_pattern = f'^{source_pattern}' if not source_pattern.startswith('^') else source_pattern
    if target_pattern.endswith('$'):
        source_pattern = f'{source_pattern}$' if not source_pattern.endswith('$') else source_pattern
    return source_pattern

class DebugUnderflowOverflow:

    def __init__(self, model, max_frames_to_save=21, trace_batch_nums=None, abort_after_batch_num=None):
        if trace_batch_nums is None:
            trace_batch_nums = []
        self.model = model
        self.trace_batch_nums = trace_batch_nums
        self.abort_after_batch_num = abort_after_batch_num
        self.frames = collections.deque([], max_frames_to_save)
        self.frame = []
        self.batch_number = 0
        self.total_calls = 0
        self.detected_overflow = False
        self.prefix = '                 '
        self.analyse_model()
        self.register_forward_hook()

    def save_frame(self, frame=None):
        if frame is not None:
            self.expand_frame(frame)
        self.frames.append('\n'.join(self.frame))
        self.frame = []

    def expand_frame(self, line):
        self.frame.append(line)

    def trace_frames(self):
        print('\n'.join(self.frames))
        self.frames = []

    def reset_saved_frames(self):
        self.frames = []

    def dump_saved_frames(self):
        print(f'\nDetected inf/nan during batch_number={self.batch_number}')
        print(f'Last {len(self.frames)} forward frames:')
        print(f"{'abs min':8} {'abs max':8} metadata")
        print('\n'.join(self.frames))
        print('\n\n')
        self.frames = []

    def analyse_model(self):
        self.module_names = {m: name for name, m in self.model.named_modules()}

    def analyse_variable(self, var, ctx):
        if torch.is_tensor(var):
            self.expand_frame(get_abs_min_max(var, ctx))
            if detect_overflow(var, ctx):
                self.detected_overflow = True
        elif var is None:
            self.expand_frame(f"{'None':>17} {ctx}")
        else:
            self.expand_frame(f"{'not a tensor':>17} {ctx}")

    def batch_start_frame(self):
        self.expand_frame(f'\n\n{self.prefix} *** Starting batch number={self.batch_number} ***')
        self.expand_frame(f"{'abs min':8} {'abs max':8} metadata")

    def batch_end_frame(self):
        self.expand_frame(f'{self.prefix} *** Finished batch number={self.batch_number - 1} ***\n\n')

    def create_frame(self, module, input, output):
        self.expand_frame(f'{self.prefix} {self.module_names[module]} {module.__class__.__name__}')
        for name, p in module.named_parameters(recurse=False):
            self.analyse_variable(p, name)
        if isinstance(input, tuple):
            for i, x in enumerate(input):
                self.analyse_variable(x, f'input[{i}]')
        else:
            self.analyse_variable(input, 'input')
        if isinstance(output, tuple):
            for i, x in enumerate(output):
                if isinstance(x, tuple):
                    for j, y in enumerate(x):
                        self.analyse_variable(y, f'output[{i}][{j}]')
                else:
                    self.analyse_variable(x, f'output[{i}]')
        else:
            self.analyse_variable(output, 'output')
        self.save_frame()

    def register_forward_hook(self):
        self.model.apply(self._register_forward_hook)

    def _register_forward_hook(self, module):
        module.register_forward_hook(self.forward_hook)

    def forward_hook(self, module, input, output):
        last_frame_of_batch = False
        trace_mode = self.batch_number in self.trace_batch_nums
        if trace_mode:
            self.reset_saved_frames()
        if self.total_calls == 0:
            self.batch_start_frame()
        self.total_calls += 1
        if module == self.model:
            self.batch_number += 1
            last_frame_of_batch = True
        self.create_frame(module, input, output)
        if trace_mode:
            self.trace_frames()
        if last_frame_of_batch:
            self.batch_start_frame()
        if self.detected_overflow and (not trace_mode):
            self.dump_saved_frames()
            raise ValueError('DebugUnderflowOverflow: inf/nan detected, aborting as there is no point running further. Please scroll up above this traceback to see the activation values prior to this event.')
        if self.abort_after_batch_num is not None and self.batch_number > self.abort_after_batch_num:
            raise ValueError(f'DebugUnderflowOverflow: aborting after {self.batch_number} batches due to `abort_after_batch_num={self.abort_after_batch_num}` arg')

# --- helper: transformers.debug_utils.detect_overflow ---
def detect_overflow(var, ctx):
    detected = False
    if torch.isnan(var).any().item():
        detected = True
        print(f'{ctx} has nans')
    if torch.isinf(var).any().item():
        detected = True
        print(f'{ctx} has infs')
    if 0:
        n100 = var[torch.ge(var.abs(), 100)]
        if n100.numel() > 0:
            print(f'{ctx}:  n100={n100.numel()}')
        n1000 = var[torch.ge(var.abs(), 1000)]
        if n1000.numel() > 0:
            print(f'{ctx}: n1000={n1000.numel()}')
        n10000 = var[torch.ge(var.abs(), 10000)]
        if n10000.numel() > 0:
            print(f'{ctx}: n10000={n10000.numel()}')
    if 0:
        print(f'min={var.min():9.2e} max={var.max():9.2e}')
    if 0:
        print(f'min={var.min():9.2e} max={var.max():9.2e} var={var.var():9.2e} mean={var.mean():9.2e} ({ctx})')
    return detected

# --- helper: transformers.debug_utils.get_abs_min_max ---
def get_abs_min_max(var, ctx):
    abs_var = var.abs()
    return f'{abs_var.min():8.2e} {abs_var.max():8.2e} {ctx}'

class BatchFeature(UserDict):

    def __init__(self, data: dict[str, Any] | None=None, tensor_type: None | str | TensorType=None, skip_tensor_conversion: list[str] | set[str] | None=None):
        super().__init__(data)
        self.skip_tensor_conversion = skip_tensor_conversion
        self.convert_to_tensors(tensor_type=tensor_type)

    def __getitem__(self, item: str) -> Any:
        if isinstance(item, str):
            return self.data[item]
        else:
            raise KeyError('Indexing with integers is not available when using Python based feature extractors')

    def __getattr__(self, item: str):
        try:
            return self.data[item]
        except KeyError:
            raise AttributeError

    def __getstate__(self):
        return {'data': self.data}

    def __setstate__(self, state):
        if 'data' in state:
            self.data = state['data']

    def _get_is_as_tensor_fns(self, tensor_type: str | TensorType | None=None):
        if tensor_type is None:
            return (None, None)
        if not isinstance(tensor_type, TensorType):
            tensor_type = TensorType(tensor_type)
        if tensor_type == TensorType.PYTORCH:
            if not is_torch_available():
                raise ImportError('Unable to convert output to PyTorch tensors format, PyTorch is not installed.')
            import torch

            def as_tensor(value):
                if torch.is_tensor(value):
                    return value
                if isinstance(value, (list, tuple)) and len(value) > 0 and torch.is_tensor(value[0]):
                    return torch.stack(value)
                if isinstance(value, (list, tuple)) and len(value) > 0:
                    if isinstance(value[0], np.ndarray):
                        value = np.array(value)
                    elif isinstance(value[0], (list, tuple)) and len(value[0]) > 0 and isinstance(value[0][0], np.ndarray):
                        value = np.array(value)
                if isinstance(value, np.ndarray):
                    return torch.from_numpy(value)
                else:
                    return torch.tensor(value)
            is_tensor = torch.is_tensor
        else:

            def as_tensor(value, dtype=None):
                if isinstance(value, (list, tuple)) and isinstance(value[0], (list, tuple, np.ndarray)):
                    value_lens = [len(val) for val in value]
                    if len(set(value_lens)) > 1 and dtype is None:
                        value = as_tensor([np.asarray(val) for val in value], dtype=object)
                return np.asarray(value, dtype=dtype)
            is_tensor = is_numpy_array
        return (is_tensor, as_tensor)

    def convert_to_tensors(self, tensor_type: str | TensorType | None=None, skip_tensor_conversion: list[str] | set[str] | None=None):
        if tensor_type is None:
            return self
        is_tensor, as_tensor = self._get_is_as_tensor_fns(tensor_type)
        skip_tensor_conversion = skip_tensor_conversion if skip_tensor_conversion is not None else self.skip_tensor_conversion
        for key, value in self.items():
            if skip_tensor_conversion and key in skip_tensor_conversion:
                continue
            if not _is_tensor_or_array_like(value):
                continue
            try:
                if not is_tensor(value):
                    tensor = as_tensor(value)
                    self[key] = tensor
            except Exception as e:
                if key == 'overflowing_values':
                    raise ValueError(f"Unable to create tensor for '{key}' with overflowing values of different lengths. Original error: {str(e)}") from e
                raise ValueError(f"Unable to convert output '{key}' (type: {type(value).__name__}) to tensor: {str(e)}\nYou can try:\n  1. Use padding=True to ensure all outputs have the same shape\n  2. Set return_tensors=None to return Python objects instead of tensors") from e
        return self

    def to(self, *args, **kwargs) -> 'BatchFeature':
        requires_backends(self, ['torch'])
        import torch
        device = kwargs.get('device')
        non_blocking = kwargs.get('non_blocking', False)
        if device is None and len(args) > 0:
            arg = args[0]
            if is_torch_dtype(arg):
                pass
            elif isinstance(arg, str) or is_torch_device(arg) or isinstance(arg, int):
                device = arg
            else:
                raise ValueError(f'Attempting to cast a BatchFeature to type {str(arg)}. This is not supported.')

        def maybe_to(v):
            if isinstance(v, torch.Tensor) and torch.is_floating_point(v):
                return v.to(*args, **kwargs)
            elif isinstance(v, torch.Tensor) and device is not None:
                return v.to(device=device, non_blocking=non_blocking)
            elif isinstance(v, (list, tuple)):
                return type(v)((maybe_to(item) for item in v))
            else:
                return v
        self.data = {k: maybe_to(v) for k, v in self.items()}
        return self

class PatchEmbeddingsFusionSpec(ModuleFusionSpec):
    target_modules_patterns = ('(^|\\.)patch_embed$',)

    def is_fusable(self, module: nn.Module) -> bool:
        if not isinstance((proj := getattr(module, 'proj', None)), nn.Conv3d):
            return False
        return proj.stride == proj.kernel_size and proj.padding == (0, 0, 0) and (proj.dilation == (1, 1, 1)) and (proj.groups == 1)

    def make_fused_class(self, original_cls: type[nn.Module]) -> type[nn.Module]:
        fused_cls = type(f'Fused{original_cls.__name__}', (_FusedPatchEmbeddingMixin, original_cls), {})
        fused_cls.__qualname__ = f'Fused{original_cls.__qualname__}'
        return fused_cls

    def make_transforms(self, config: 'PretrainedConfig') -> list[WeightTransform]:
        vision_config = getattr(config, 'vision_config', config)
        patch_size = vision_config.patch_size
        if isinstance(patch_size, int):
            patch_size = (patch_size, patch_size)
        kernel_size = (vision_config.temporal_patch_size, *tuple(patch_size))
        in_channels = vision_config.in_channels
        return [WeightConverter(source_patterns='patch_embed\\.proj\\.weight$', target_patterns='patch_embed\\.linear_proj\\.weight$', operations=[Conv3dToLinear(in_channels=in_channels, kernel_size=kernel_size)]), WeightRenaming(source_patterns='patch_embed\\.proj\\.bias$', target_patterns='patch_embed\\.linear_proj\\.bias$')]

