@dataclass
class DataCollatorForLanguageModeling(DataCollatorMixin):
    tokenizer: PreTrainedTokenizerBase
    mlm: bool = True
    whole_word_mask: bool = False
    mlm_probability: float | None = 0.15
    mask_replace_prob: float = 0.8
    random_replace_prob: float = 0.1
    pad_to_multiple_of: int | None = None
    return_tensors: str = 'pt'
    seed: int | None = None

    def __post_init__(self):
        if self.mlm:
            if self.tokenizer.mask_token is None:
                raise ValueError('This tokenizer does not have a mask token which is necessary for masked language modeling. You should pass `mlm=False` to train on causal language modeling instead.')
            if self.mlm_probability is None or self.mlm_probability < 0 or self.mlm_probability > 1:
                raise ValueError('mlm_probability should be between 0 and 1.')
            self.mlm_probability = float(self.mlm_probability)
        elif self.whole_word_mask:
            raise ValueError('Whole word masking can only be used with mlm=True.If you want to use whole word masking, please set mlm=True.')
        if self.mask_replace_prob + self.random_replace_prob > 1:
            raise ValueError('The sum of mask_replace_prob and random_replace_prob should not exceed 1')
        if self.mask_replace_prob < 0 or self.mask_replace_prob > 1:
            raise ValueError('mask_replace_prob should be between 0 and 1.')
        if self.random_replace_prob < 0 or self.random_replace_prob > 1:
            raise ValueError('random_replace_prob should be between 0 and 1.')
        if self.whole_word_mask:
            if not self.tokenizer.is_fast:
                warnings.warn('Whole word masking depends on offset mapping which is only natively available with fast tokenizers.', UserWarning)
            if self.mask_replace_prob < 1:
                warnings.warn('Random token replacement is not supported with whole word masking. Setting mask_replace_prob to 1.')
                self.mask_replace_prob = 1
                self.random_replace_prob = 0
        self.mask_replace_prob = float(self.mask_replace_prob)
        self.random_replace_prob = float(self.random_replace_prob)
        self.generator = None

    def get_generator(self, seed):
        if self.return_tensors == 'pt':
            import torch
            return torch.Generator().manual_seed(seed)
        else:
            return np.random.default_rng(seed)

    def create_rng(self):
        if mp.current_process().name == 'MainProcess':
            self.generator = self.get_generator(self.seed)
        else:
            import torch
            worker_info = torch.utils.data.get_worker_info()
            if worker_info is None:
                error_string = ('Worker process information is not available for seeding the generator. This may be because', 'you are using multiprocessing without using a PyTorch DataLoader. The `seed` parameter can', 'only be used when using multiprocessing with a PyTorch DataLoader. Please either use a', 'single process or use a PyTorch DataLoader with multiple workers.')
                raise ValueError(error_string)
            self.generator = self.get_generator(self.seed + worker_info.id)

    def torch_call(self, examples: list[list[int] | Any | dict[str, Any]]) -> dict[str, Any]:
        if self.seed and self.generator is None:
            self.create_rng()
        if isinstance(examples[0], Mapping):
            batch = pad_without_fast_tokenizer_warning(self.tokenizer, examples, return_tensors='pt', pad_to_multiple_of=self.pad_to_multiple_of)
        else:
            batch = {'input_ids': _torch_collate_batch(examples, self.tokenizer, pad_to_multiple_of=self.pad_to_multiple_of)}
        special_tokens_mask = batch.pop('special_tokens_mask', None)
        offset_mapping = batch.pop('offset_mapping', None)
        if self.mlm:
            batch['input_ids'], batch['labels'] = self.torch_mask_tokens(batch['input_ids'], special_tokens_mask=special_tokens_mask, offset_mapping=offset_mapping)
        else:
            labels = batch['input_ids'].clone()
            if self.tokenizer.pad_token_id is not None:
                labels[labels == self.tokenizer.pad_token_id] = -100
            batch['labels'] = labels
        return batch

    def torch_mask_tokens(self, inputs: Any, special_tokens_mask: Any | None=None, offset_mapping: Any | None=None) -> tuple[Any, Any]:
        import torch
        labels = inputs.clone()
        probability_matrix = torch.full(labels.shape, self.mlm_probability)
        if special_tokens_mask is None:
            special_tokens_mask = [self.tokenizer.get_special_tokens_mask(val, already_has_special_tokens=True) for val in labels.tolist()]
        if self.whole_word_mask:
            word_ids, no_mask_mask = self._calc_word_ids_and_prob_mask(to_numpy(offset_mapping), to_numpy(special_tokens_mask))
            no_mask_mask = torch.tensor(no_mask_mask, dtype=torch.bool)
        else:
            no_mask_mask = special_tokens_mask.bool() if isinstance(special_tokens_mask, torch.Tensor) else torch.tensor(special_tokens_mask, dtype=torch.bool)
        probability_matrix.masked_fill_(no_mask_mask, value=0.0)
        masked_indices = torch.bernoulli(probability_matrix, generator=self.generator).bool()
        if self.whole_word_mask:
            masked_indices = torch.BoolTensor(self._whole_word_mask(word_ids, masked_indices))
        labels[~masked_indices] = -100
        indices_replaced = torch.bernoulli(torch.full(labels.shape, self.mask_replace_prob), generator=self.generator).bool() & masked_indices
        inputs[indices_replaced] = self.tokenizer.convert_tokens_to_ids(self.tokenizer.mask_token)
        if self.mask_replace_prob == 1 or self.random_replace_prob == 0:
            return (inputs, labels)
        remaining_prob = 1 - self.mask_replace_prob
        random_replace_prob_scaled = self.random_replace_prob / remaining_prob
        indices_random = torch.bernoulli(torch.full(labels.shape, random_replace_prob_scaled), generator=self.generator).bool() & masked_indices & ~indices_replaced
        random_words = torch.randint(len(self.tokenizer), labels.shape, dtype=torch.long, generator=self.generator)
        inputs[indices_random] = random_words[indices_random]
        return (inputs, labels)

    def numpy_call(self, examples: list[list[int] | Any | dict[str, Any]]) -> dict[str, Any]:
        if self.seed and self.generator is None:
            self.create_rng()
        if isinstance(examples[0], Mapping):
            batch = pad_without_fast_tokenizer_warning(self.tokenizer, examples, return_tensors='np', pad_to_multiple_of=self.pad_to_multiple_of)
        else:
            batch = {'input_ids': _numpy_collate_batch(examples, self.tokenizer, pad_to_multiple_of=self.pad_to_multiple_of)}
        special_tokens_mask = batch.pop('special_tokens_mask', None)
        offset_mapping = batch.pop('offset_mapping', None)
        if self.mlm:
            batch['input_ids'], batch['labels'] = self.numpy_mask_tokens(batch['input_ids'], special_tokens_mask=special_tokens_mask, offset_mapping=offset_mapping)
        else:
            labels = np.copy(batch['input_ids'])
            if self.tokenizer.pad_token_id is not None:
                labels[labels == self.tokenizer.pad_token_id] = -100
            batch['labels'] = labels
        return batch

    def numpy_mask_tokens(self, inputs: Any, special_tokens_mask: Any | None=None, offset_mapping: Any | None=None) -> tuple[Any, Any]:
        labels = np.copy(inputs)
        probability_matrix = np.full(labels.shape, self.mlm_probability)
        if special_tokens_mask is None:
            special_tokens_mask = [self.tokenizer.get_special_tokens_mask(val, already_has_special_tokens=True) for val in labels.tolist()]
        if self.whole_word_mask:
            word_ids, no_mask_mask = self._calc_word_ids_and_prob_mask(to_numpy(offset_mapping), to_numpy(special_tokens_mask))
        else:
            no_mask_mask = special_tokens_mask.astype(bool) if isinstance(special_tokens_mask, np.ndarray) else np.array(special_tokens_mask, dtype=bool)
        probability_matrix[no_mask_mask] = 0
        if self.generator:
            masked_indices = self.generator.binomial(1, probability_matrix, size=probability_matrix.shape).astype(bool)
        else:
            masked_indices = np.random.binomial(1, probability_matrix, size=probability_matrix.shape).astype(bool)
        if self.whole_word_mask:
            masked_indices = self._whole_word_mask(word_ids, masked_indices)
        labels[~masked_indices] = -100
        if self.generator:
            indices_replaced = self.generator.binomial(1, self.mask_replace_prob, size=labels.shape).astype(bool) & masked_indices
        else:
            indices_replaced = np.random.binomial(1, self.mask_replace_prob, size=labels.shape).astype(bool) & masked_indices
        inputs[indices_replaced] = self.tokenizer.mask_token_id
        if self.mask_replace_prob == 1 or self.random_replace_prob == 0:
            return (inputs, labels)
        remaining_prob = 1 - self.mask_replace_prob
        random_replace_prob_scaled = self.random_replace_prob / remaining_prob
        if self.generator:
            indices_random = self.generator.binomial(1, random_replace_prob_scaled, size=labels.shape).astype(bool) & masked_indices & ~indices_replaced
            random_words = self.generator.integers(low=0, high=len(self.tokenizer), size=np.count_nonzero(indices_random), dtype=np.int64)
        else:
            indices_random = np.random.binomial(1, random_replace_prob_scaled, size=labels.shape).astype(bool) & masked_indices & ~indices_replaced
            random_words = np.random.randint(low=0, high=len(self.tokenizer), size=np.count_nonzero(indices_random), dtype=np.int64)
        inputs[indices_random] = random_words
        return (inputs, labels)

    @staticmethod
    def _calc_word_ids_and_prob_mask(offsets: np.ndarray[np.ndarray[tuple[int, int]]], special_tokens_mask: np.ndarray[np.ndarray[int]]) -> tuple[np.ndarray[np.ndarray[int]], np.ndarray[np.ndarray[int]]]:
        token_starts = offsets[:, :, 0]
        token_ends = offsets[:, :, 1]
        prev_token_ends = np.roll(token_ends, 1, axis=1)
        prev_token_ends[:, 0] = -1
        prev_token_special = np.roll(special_tokens_mask, 1, axis=1)
        prev_token_special[:, 0] = 0
        special_tokens_mask = special_tokens_mask.astype(bool)
        is_new_word = ~special_tokens_mask & ((token_starts != prev_token_ends) | (prev_token_special == 1))
        word_ids = np.cumsum(is_new_word, axis=1)
        word_ids[special_tokens_mask] = -1
        prob_mask = ~is_new_word
        return (word_ids, prob_mask)

    @staticmethod
    def _whole_word_mask(word_ids: np.ndarray[np.ndarray[int]], mask: Any) -> Any:
        mask = to_numpy(mask)
        valid_ids = word_ids != -1
        same_word = (word_ids[:, :, None] == word_ids[:, None, :]) & valid_ids[:, :, None] & valid_ids[:, None, :]
        return np.any(same_word & mask[:, None, :], axis=2)

def pad_to_interval(size: int, interval_size: int, max_value: int) -> int:
    if interval_size <= 0:
        return max_value
    padded = ceil(size / interval_size) * interval_size if size > 0 else interval_size
    return min(padded, max_value)

class CudaGraphBuffer:

    def __init__(self, max_size: int) -> None:
        if max_size <= 0:
            raise ValueError(f'max_size must be positive, but got {max_size}')
        self.max_size = max_size
        self._storage: OrderedDict[tuple[int, ...], torch.cuda.CUDAGraph] = OrderedDict()

    def __del__(self) -> None:
        original_max_size = self.max_size
        self.max_size = 1
        self.plan_for_new_graph(silent=True)
        self.max_size = original_max_size

    def get_graph(self, key: tuple[int, ...]) -> torch.cuda.CUDAGraph | None:
        graph = self._storage.get(key)
        if graph is not None:
            self._storage.move_to_end(key)
        return graph

    def plan_for_new_graph(self, silent: bool=False) -> None:
        while len(self._storage) >= self.max_size:
            evicted_key, evicted_graph = self._storage.popitem(last=False)
            if not silent:
                logger.info(f'Evicting graph for evicted_key = {evicted_key!r}')
            evicted_graph.reset()

    def set_graph(self, key: tuple[int, ...], graph: torch.cuda.CUDAGraph) -> None:
        self.plan_for_new_graph()
        self._storage[key] = graph

class BarkEosPrioritizerLogitsProcessor(LogitsProcessor):

    def __init__(self, eos_token_id: int | list[int] | torch.Tensor, min_eos_p: float, device: str='cpu'):
        if not isinstance(eos_token_id, torch.Tensor):
            if isinstance(eos_token_id, int):
                eos_token_id = [eos_token_id]
            eos_token_id = torch.tensor(eos_token_id, device=device)
        self.eos_token_id = eos_token_id
        if torch.is_floating_point(eos_token_id) or (eos_token_id < 0).any():
            raise ValueError(f'`eos_token_id` has to be a list of positive integers, but is {eos_token_id}')
        if min_eos_p is not None and min_eos_p <= 0:
            raise ValueError(f'`min_eos_p` has to be a positive float, but is {min_eos_p}')
        self.min_eos_p = min_eos_p

    @add_start_docstrings(LOGITS_PROCESSOR_INPUTS_DOCSTRING)
    def __call__(self, input_ids: torch.LongTensor, scores: torch.FloatTensor) -> torch.FloatTensor:
        scores_processed = scores
        if self.min_eos_p:
            probs = torch.nn.functional.softmax(scores.float(), dim=-1)
            early_stop_scores = torch.ones_like(scores) * -float('inf')
            early_stop_scores[:, self.eos_token_id] = scores[:, self.eos_token_id]
            do_early_stop = probs[:, self.eos_token_id] > self.min_eos_p
            do_early_stop = torch.any(do_early_stop, dim=1, keepdim=True)
            scores_processed = torch.where(do_early_stop, early_stop_scores, scores)
        return scores_processed

