class AsyncTextIteratorStreamer(TextStreamer):

    def __init__(self, tokenizer: PreTrainedTokenizerBase, skip_prompt: bool=False, timeout: float | None=None, **decode_kwargs: Any):
        super().__init__(tokenizer, skip_prompt, **decode_kwargs)
        self.text_queue = asyncio.Queue()
        self.stop_signal = None
        self.timeout = timeout
        self.loop = asyncio.get_running_loop()
        timeout_context = getattr(asyncio, 'timeout', None)
        self.has_asyncio_timeout = sys.version_info >= (3, 11) and callable(timeout_context)
        self.asyncio_timeout = timeout_context if self.has_asyncio_timeout else None

    def on_finalized_text(self, text: str, stream_end: bool=False):
        self.loop.call_soon_threadsafe(self.text_queue.put_nowait, text)
        if stream_end:
            self.loop.call_soon_threadsafe(self.text_queue.put_nowait, self.stop_signal)

    def __aiter__(self):
        return self

    async def __anext__(self):
        try:
            if self.has_asyncio_timeout and self.asyncio_timeout is not None:
                async with self.asyncio_timeout(self.timeout):
                    value = await self.text_queue.get()
            else:
                value = await asyncio.wait_for(self.text_queue.get(), timeout=self.timeout)
        except asyncio.TimeoutError:
            raise TimeoutError()
        else:
            if value == self.stop_signal:
                raise StopAsyncIteration()
            else:
                return value

# --- helper: transformers.generation.streamers.TextStreamer ---
class TextStreamer(BaseStreamer):

    def __init__(self, tokenizer: PreTrainedTokenizerBase, skip_prompt: bool=False, **decode_kwargs: Any):
        self.tokenizer = tokenizer
        self.skip_prompt = skip_prompt
        self.decode_kwargs = decode_kwargs
        self.token_cache: list[int] = []
        self.print_len = 0
        self.next_tokens_are_prompt = True

    def put(self, value):
        if len(value.shape) > 1 and value.shape[0] > 1:
            raise ValueError('TextStreamer only supports batch size 1')
        elif len(value.shape) > 1:
            value = value[0]
        if self.skip_prompt and self.next_tokens_are_prompt:
            self.next_tokens_are_prompt = False
            return
        self.token_cache.extend(value.tolist())
        text = cast(str, self.tokenizer.decode(self.token_cache, **self.decode_kwargs))
        if text.endswith('\n'):
            printable_text = text[self.print_len:]
            self.token_cache = []
            self.print_len = 0
        elif len(text) > 0 and self._is_chinese_char(ord(text[-1])):
            printable_text = text[self.print_len:]
            self.print_len += len(printable_text)
        else:
            printable_text = text[self.print_len:text.rfind(' ') + 1]
            self.print_len += len(printable_text)
        self.on_finalized_text(printable_text)

    def end(self):
        if len(self.token_cache) > 0:
            text = cast(str, self.tokenizer.decode(self.token_cache, **self.decode_kwargs))
            printable_text = text[self.print_len:]
            self.token_cache = []
            self.print_len = 0
        else:
            printable_text = ''
        self.next_tokens_are_prompt = True
        self.on_finalized_text(printable_text, stream_end=True)

    def on_finalized_text(self, text: str, stream_end: bool=False):
        print(text, flush=True, end='' if not stream_end else None)

    def _is_chinese_char(self, cp):
        if cp >= 19968 and cp <= 40959 or (cp >= 13312 and cp <= 19903) or (cp >= 131072 and cp <= 173791) or (cp >= 173824 and cp <= 177983) or (cp >= 177984 and cp <= 178207) or (cp >= 178208 and cp <= 183983) or (cp >= 63744 and cp <= 64255) or (cp >= 194560 and cp <= 195103):
            return True
        return False

class BayesianDetectorWatermarkedLikelihood(nn.Module):

    def __init__(self, watermarking_depth: int):
        super().__init__()
        self.watermarking_depth = watermarking_depth
        self.beta = torch.nn.Parameter(-2.5 + 0.001 * torch.randn(1, 1, watermarking_depth))
        self.delta = torch.nn.Parameter(0.001 * torch.randn(1, 1, self.watermarking_depth, watermarking_depth))

    def _compute_latents(self, g_values: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        x = torch.repeat_interleave(torch.unsqueeze(g_values, dim=-2), self.watermarking_depth, axis=-2)
        x = torch.tril(x, diagonal=-1)
        logits = (self.delta[..., None, :] @ x.type(self.delta.dtype)[..., None]).squeeze() + self.beta
        p_two_unique_tokens = torch.sigmoid(logits)
        p_one_unique_token = 1 - p_two_unique_tokens
        return (p_one_unique_token, p_two_unique_tokens)

    def forward(self, g_values: torch.Tensor) -> torch.Tensor:
        p_one_unique_token, p_two_unique_tokens = self._compute_latents(g_values)
        return 0.5 * ((g_values + 0.5) * p_two_unique_tokens + p_one_unique_token)

class StopStringCriteria(StoppingCriteria):

    def __init__(self, tokenizer: PreTrainedTokenizerBase, stop_strings: str | list[str]):
        if isinstance(stop_strings, str):
            stop_strings = [stop_strings]
        self.stop_strings: tuple[str, ...] = tuple(stop_strings)
        vocab = tokenizer.get_vocab()
        token_list, token_indices = (tuple(vocab.keys()), tuple(vocab.values()))
        self.embedding_vec, self.max_valid_positions, self.max_valid_end_lens = self.clean_and_embed_tokens_with_cache(token_list, token_indices, tokenizer)
        self.maximum_token_len = max((len(stop_string) for stop_string in self.stop_strings))
        self.num_stop_strings = len(self.stop_strings)
        self.target_lens = torch.tensor([len(stop_string) for stop_string in stop_strings], dtype=torch.int32)

    def clean_and_embed_tokens_with_cache(self, token_list, token_indices, tokenizer):
        if (token_list, token_indices, self.stop_strings) in STOP_STRING_EMBEDDING_CACHE:
            embedding_vec, max_valid_positions, max_valid_end_lens = STOP_STRING_EMBEDDING_CACHE[token_list, token_indices, self.stop_strings]
            STOP_STRING_EMBEDDING_CACHE.move_to_end((token_list, token_indices, self.stop_strings))
        else:
            clean_token_list, clean_token_indices = self.clean_tokenizer_vocab(tokenizer)
            embedding_vec, max_valid_positions, max_valid_end_lens = self._stop_string_create_embedding_vec(clean_token_list, clean_token_indices, self.stop_strings)
            STOP_STRING_EMBEDDING_CACHE[token_list, token_indices, self.stop_strings] = (embedding_vec, max_valid_positions, max_valid_end_lens)
            if len(STOP_STRING_EMBEDDING_CACHE) > 8:
                STOP_STRING_EMBEDDING_CACHE.popitem(last=False)
        return (embedding_vec, max_valid_positions, max_valid_end_lens)

    @staticmethod
    def clean_tokenizer_vocab(tokenizer, static_prefix='abcdef'):
        vocab = tokenizer.get_vocab()
        clean_token_list = []
        clean_token_indices = []
        sentence_base = tokenizer(static_prefix, add_special_tokens=False)['input_ids']
        tokens_base = [tokenizer._convert_id_to_token(tok) for tok in sentence_base]
        for token, token_idx in vocab.items():
            token_string = tokenizer.convert_tokens_to_string(tokens_base + [token])
            token_string = token_string[token_string.index(static_prefix) + len(static_prefix):]
            clean_token_list.append(token_string)
            clean_token_indices.append(token_idx)
        return (tuple(clean_token_list), tuple(clean_token_indices))

    @staticmethod
    def _stop_string_get_matching_positions(token_list, token_indices, stop_strings) -> tuple[dict[str, dict[str, list[int]]], dict[str, dict[str, list[int]]]]:
        token_valid_positions = {}
        token_end_overlaps = {}
        for stop_string in stop_strings:
            reversed_stop_string = stop_string[::-1]
            token_valid_positions[stop_string] = {}
            token_end_overlaps[stop_string] = {}
            for token, tok_idx in zip(token_list, token_indices):
                reversed_token = token[::-1]
                matching_positions = []
                possible_end_lengths = []
                for i in range(1 - len(token), len(stop_string)):
                    if i < 0:
                        tok = reversed_token[-i:]
                        i = 0
                    else:
                        tok = reversed_token
                    stop = reversed_stop_string[i:i + len(tok)]
                    if tok.startswith(stop):
                        if i == 0:
                            possible_end_lengths.append(min(len(tok), len(stop)))
                        else:
                            matching_positions.append(i)
                if matching_positions:
                    token_valid_positions[stop_string][tok_idx] = matching_positions
                if possible_end_lengths:
                    token_end_overlaps[stop_string][tok_idx] = possible_end_lengths
        return (token_valid_positions, token_end_overlaps)

    @staticmethod
    def _stop_string_create_embedding_vec(token_list, token_indices, stop_strings) -> dict[str, torch.Tensor]:
        token_valid_positions, token_end_overlaps = StopStringCriteria._stop_string_get_matching_positions(token_list, token_indices, stop_strings)
        all_valid_positions = [len(val) for positions in token_valid_positions.values() for val in positions.values()]
        max_valid_positions = max(all_valid_positions) if all_valid_positions else 1
        valid_end_lens = [len(val) for positions in token_end_overlaps.values() for val in positions.values()]
        if not valid_end_lens:
            raise ValueError('Stop string preprocessing was unable to identify tokens matching one or more of the supplied stop string(s). This is most often caused by the stop strings containing unusual characters that are not in the tokenizer vocabulary.')
        max_valid_end_lens = max(valid_end_lens)
        vec_size = len(stop_strings) * (max_valid_positions + max_valid_end_lens) + 1
        gather_vec = np.full((max(token_indices) + 2, vec_size), dtype=np.int32, fill_value=-1)
        for i, stop_string in enumerate(stop_strings):
            positions = token_valid_positions[stop_string]
            end_lens = token_end_overlaps[stop_string]
            for token_idx, valid_positions in positions.items():
                gather_vec[token_idx, max_valid_positions * i:max_valid_positions * i + len(valid_positions)] = valid_positions
            for token_idx, possible_end_lens in end_lens.items():
                gather_vec[token_idx, max_valid_positions * len(stop_strings) + max_valid_end_lens * i:max_valid_positions * len(stop_strings) + max_valid_end_lens * i + len(possible_end_lens)] = possible_end_lens
            for token, token_idx in zip(token_list, token_indices):
                gather_vec[token_idx, -1] = len(token)
        gather_vec = torch.tensor(gather_vec, dtype=torch.int32)
        return (gather_vec, max_valid_positions, max_valid_end_lens)

    @add_start_docstrings(STOPPING_CRITERIA_INPUTS_DOCSTRING)
    def __call__(self, input_ids: torch.LongTensor, scores: torch.FloatTensor, **kwargs) -> torch.Tensor:
        self.embedding_vec = self.embedding_vec.to(input_ids.device)
        self.target_lens = self.target_lens.to(input_ids.device)
        input_ids = input_ids[:, -self.maximum_token_len:]
        flipped_ids = torch.flip(input_ids, (1,))
        flipped_ids = torch.clamp(flipped_ids, max=self.embedding_vec.size(0) - 1)
        max_valid_positions = self.max_valid_positions
        embedded = F.embedding(flipped_ids, self.embedding_vec)
        valid_positions = embedded[:, 1:, :max_valid_positions * self.num_stop_strings].unflatten(-1, (self.num_stop_strings, -1))
        end_lengths = embedded[:, :1, max_valid_positions * self.num_stop_strings:-1].unflatten(-1, (self.num_stop_strings, -1))
        lengths = embedded[:, 1:, None, -1:]
        lengths = lengths.expand((-1, -1, end_lengths.shape[-2], end_lengths.shape[-1]))
        lengths_with_ends = torch.cat([end_lengths, lengths], dim=1)
        cumsum = lengths_with_ends.cumsum(dim=1)
        initial_match = end_lengths > 0
        later_match = torch.any(cumsum[:, :-1, :, None] == valid_positions[:, :, :, :, None], axis=-2)
        match = torch.cat([initial_match, later_match], dim=1)
        mask = (~match).cumsum(dim=1, dtype=torch.int32)
        mask = mask == 0
        string_matches = torch.amax(cumsum * mask, dim=(1, -1)) >= self.target_lens[None, :]
        return torch.any(string_matches, dim=-1)

# --- helper: transformers.generation.stopping_criteria.StoppingCriteria ---
class StoppingCriteria(ABC):

    @add_start_docstrings(STOPPING_CRITERIA_INPUTS_DOCSTRING)
    def __call__(self, input_ids: torch.LongTensor, scores: torch.FloatTensor, **kwargs) -> torch.BoolTensor:
        raise NotImplementedError('StoppingCriteria needs to be subclassed')

def compute_module_total_buffer_size(model: nn.Module, hf_quantizer: 'HfQuantizer | None'=None):
    module_sizes, _ = compute_module_sizes(model, hf_quantizer, buffers_only=True)
    return module_sizes.get('', 0)

# --- helper: transformers.integrations.accelerate.compute_module_sizes ---
def compute_module_sizes(model: 'PreTrainedModel', hf_quantizer: 'HfQuantizer | None'=None, buffers_only: bool=False, only_modules: bool=True) -> tuple[dict[str, int], dict[str, int]]:
    all_module_sizes = defaultdict(int)
    leaves_module_sizes = defaultdict(int)
    if buffers_only:
        iterator = model.named_buffers()
    else:

        def all_tensors():
            yield from model.named_parameters()
            yield from model.named_buffers()
        iterator = all_tensors()
    tied_keys = getattr(model, 'all_tied_weights_keys', {}).keys()
    for name, param in iterator:
        if name in tied_keys:
            continue
        if hf_quantizer is not None:
            dtype_size = hf_quantizer.param_element_size(model, name, param)
        else:
            dtype_size = param.element_size()
        size = param.numel() * dtype_size
        name_parts = name.split('.')
        for idx in range(len(name_parts)):
            all_module_sizes['.'.join(name_parts[:idx])] += size
        if '.' in name:
            leaves_module_sizes[name.rsplit('.', 1)[0]] += size
        if not only_modules:
            all_module_sizes[name] += size
    return (all_module_sizes, leaves_module_sizes)

@dataclass()
class SizeDict:
    height: int | None = None
    width: int | None = None
    longest_edge: int | None = None
    shortest_edge: int | None = None
    max_height: int | None = None
    max_width: int | None = None

    def __getitem__(self, key):
        if hasattr(self, key):
            return getattr(self, key)
        raise KeyError(f'Key {key} not found in SizeDict.')

    def get(self, key, default=None):
        if hasattr(self, key) and getattr(self, key) is not None:
            return getattr(self, key)
        return default

    def __iter__(self):
        for f in fields(self):
            val = getattr(self, f.name)
            if val is not None:
                yield (f.name, val)

    def __hash__(self):
        return hash((self.height, self.width, self.longest_edge, self.shortest_edge, self.max_height, self.max_width))

    def __contains__(self, key):
        return hasattr(self, key) and getattr(self, key) is not None

    def __setitem__(self, key, value):
        if not hasattr(self, key):
            raise KeyError(f'Key {key} is not a valid field of SizeDict.')
        object.__setattr__(self, key, value)

    def __eq__(self, other):
        if isinstance(other, dict):
            return dict(self) == other
        if isinstance(other, SizeDict):
            return tuple((getattr(self, f.name) for f in fields(self))) == tuple((getattr(other, f.name) for f in fields(self)))
        return NotImplemented

    def __or__(self, other) -> 'SizeDict':
        if isinstance(other, dict | SizeDict):
            merged = dict(self)
            merged.update(dict(other))
            return SizeDict(**merged)
        return NotImplemented

    def __ror__(self, other) -> dict:
        if isinstance(other, dict):
            merged = dict(other)
            merged.update(dict(self))
            return merged
        return NotImplemented

def get_max_memory(max_memory: dict[int | str, int | str] | None=None):
    final_max_memory = accelerate_max_memory(max_memory)
    for device_name in final_max_memory:
        if isinstance(device_name, int):
            if is_torch_xpu_available():
                unused_memory = torch.xpu.memory_reserved(device_name) - torch.xpu.memory_allocated(device_name)
            elif torch.cuda.is_available():
                unused_memory = torch.cuda.memory_reserved(device_name) - torch.cuda.memory_allocated(device_name)
            else:
                unused_memory = 0
            final_max_memory[device_name] += unused_memory
        if max_memory is not None and device_name in max_memory:
            final_max_memory[device_name] = min(max_memory[device_name], final_max_memory[device_name])
    if max_memory is None and 'cpu' in final_max_memory:
        final_max_memory['cpu'] *= 0.9
    return final_max_memory

def get_patch_output_size(image, target_resolution, input_data_format):
    original_height, original_width = get_image_size(image, channel_dim=input_data_format)
    target_height, target_width = target_resolution
    scale_w = target_width / original_width
    scale_h = target_height / original_height
    if scale_w < scale_h:
        new_width = target_width
        new_height = min(math.ceil(original_height * scale_w), target_height)
    else:
        new_height = target_height
        new_width = min(math.ceil(original_width * scale_h), target_width)
    return (new_height, new_width)

class WatermarkDetector:

    def __init__(self, model_config: 'PreTrainedConfig', device: str, watermarking_config: Union['WatermarkingConfig', dict], ignore_repeated_ngrams: bool=False, max_cache_size: int=128):
        if not isinstance(watermarking_config, dict):
            watermarking_config = watermarking_config.to_dict()
        self.bos_token_id = model_config.bos_token_id if not model_config.is_encoder_decoder else model_config.decoder_start_token_id
        self.greenlist_ratio = watermarking_config['greenlist_ratio']
        self.ignore_repeated_ngrams = ignore_repeated_ngrams
        self.processor = WatermarkLogitsProcessor(vocab_size=model_config.vocab_size, device=device, **watermarking_config)
        self._get_ngram_score_cached = lru_cache(maxsize=max_cache_size)(self._get_ngram_score)

    def _get_ngram_score(self, prefix: torch.LongTensor, target: int):
        greenlist_ids = self.processor._get_greenlist_ids(prefix)
        return target in greenlist_ids

    def _score_ngrams_in_passage(self, input_ids: torch.LongTensor):
        batch_size, seq_length = input_ids.shape
        selfhash = int(self.processor.seeding_scheme == 'selfhash')
        n = self.processor.context_width + 1 - selfhash
        indices = torch.arange(n).unsqueeze(0) + torch.arange(seq_length - n + 1).unsqueeze(1)
        ngram_tensors = input_ids[:, indices]
        num_tokens_scored_batch = np.zeros(batch_size)
        green_token_count_batch = np.zeros(batch_size)
        for batch_idx in range(ngram_tensors.shape[0]):
            frequencies_table = collections.Counter(ngram_tensors[batch_idx])
            ngram_to_watermark_lookup = {}
            for ngram_example in frequencies_table:
                prefix = ngram_example if selfhash else ngram_example[:-1]
                target = ngram_example[-1]
                ngram_to_watermark_lookup[ngram_example] = self._get_ngram_score_cached(prefix, target)
            if self.ignore_repeated_ngrams:
                num_tokens_scored_batch[batch_idx] = len(frequencies_table.keys())
                green_token_count_batch[batch_idx] = sum(ngram_to_watermark_lookup.values())
            else:
                num_tokens_scored_batch[batch_idx] = sum(frequencies_table.values())
                green_token_count_batch[batch_idx] = sum((freq * outcome for freq, outcome in zip(frequencies_table.values(), ngram_to_watermark_lookup.values())))
        return (num_tokens_scored_batch, green_token_count_batch)

    def _compute_z_score(self, green_token_count: np.ndarray, total_num_tokens: np.ndarray) -> np.ndarray:
        expected_count = self.greenlist_ratio
        numer = green_token_count - expected_count * total_num_tokens
        denom = np.sqrt(total_num_tokens * expected_count * (1 - expected_count))
        z = numer / denom
        return z

    def _compute_pval(self, x, loc=0, scale=1):
        z = (x - loc) / scale
        return 1 - 0.5 * (1 + np.sign(z) * (1 - np.exp(-2 * z ** 2 / np.pi)))

    def __call__(self, input_ids: torch.LongTensor, z_threshold: float=3.0, return_dict: bool=False) -> WatermarkDetectorOutput | np.ndarray:
        if input_ids[0, 0] == self.bos_token_id:
            input_ids = input_ids[:, 1:]
        if input_ids.shape[-1] - self.processor.context_width < 1:
            raise ValueError(f'Must have at least `1` token to score after the first min_prefix_len={self.processor.context_width} tokens required by the seeding scheme.')
        num_tokens_scored, green_token_count = self._score_ngrams_in_passage(input_ids)
        z_score = self._compute_z_score(green_token_count, num_tokens_scored)
        prediction = z_score > z_threshold
        if return_dict:
            p_value = self._compute_pval(z_score)
            confidence = 1 - p_value
            return WatermarkDetectorOutput(num_tokens_scored=num_tokens_scored, num_green_tokens=green_token_count, green_fraction=green_token_count / num_tokens_scored, z_score=z_score, p_value=p_value, prediction=prediction, confidence=confidence)
        return prediction

# --- helper: transformers.generation.watermarking.WatermarkDetectorOutput ---
@dataclass
class WatermarkDetectorOutput:
    num_tokens_scored: np.ndarray | None = None
    num_green_tokens: np.ndarray | None = None
    green_fraction: np.ndarray | None = None
    z_score: np.ndarray | None = None
    p_value: np.ndarray | None = None
    prediction: np.ndarray | None = None
    confidence: np.ndarray | None = None

def register_dynamic_cache_export_support():
    try:
        torch.utils._pytree.register_pytree_node(DynamicCache, lambda dynamic_cache: torch.utils._pytree._dict_flatten(_get_cache_dict(dynamic_cache)), _unflatten_dynamic_cache, serialized_type_name=f'{DynamicCache.__module__}.{DynamicCache.__name__}', flatten_with_keys_fn=lambda dynamic_cache: torch.utils._pytree._dict_flatten_with_keys(_get_cache_dict(dynamic_cache)))
        torch.fx._pytree.register_pytree_flatten_spec(DynamicCache, lambda cache, spec: torch.fx._pytree._dict_flatten_spec(_get_cache_dict(cache), spec))
    except ValueError as e:
        if 'already registered as pytree node' not in str(e):
            raise

# --- helper: transformers.integrations.executorch._get_cache_dict ---
def _get_cache_dict(cache: DynamicCache):
    if any((not isinstance(layer, (DynamicLayer, DynamicSlidingWindowLayer)) for layer in cache.layers)):
        raise RuntimeError('This pytree flattening function should only be applied to DynamicCache')
    if not is_torch_greater_or_equal_than_2_6:
        logging.warning('DynamicCache + torch.export is tested on torch 2.6.0+ and may not work on earlier versions.')
    return {'key_cache': [layer.keys for layer in cache.layers if layer.keys is not None], 'value_cache': [layer.values for layer in cache.layers if layer.values is not None]}

# --- helper: transformers.integrations.executorch._unflatten_dynamic_cache ---
def _unflatten_dynamic_cache(values, context: torch.utils._pytree.Context):
    dictionary = torch.utils._pytree._dict_unflatten(values, context)
    cache = DynamicCache()
    key_list = dictionary.get('key_cache', [])
    value_list = dictionary.get('value_cache', [])
    for idx in range(max(len(key_list), len(value_list))):
        key = key_list[idx] if idx < len(key_list) else None
        value = value_list[idx] if idx < len(value_list) else None
        cache.update(key, value, idx)
    return cache

def w8a8_fp8_matmul(A: torch.Tensor, B: torch.Tensor, As: torch.Tensor, Bs: torch.Tensor, block_size: list[int], output_dtype: torch.dtype=torch.float32) -> torch.Tensor:
    if block_size is not None and block_size[0] == block_size[1] == 128:
        try:
            _load_deepgemm_kernel()
            global deepgemm_fp8_matmul
        except ImportError:
            logger.warning_once('DeepGEMM kernel is not available or compatible, falling back to Triton finegrained-fp8 kernel. To use DeepGEMM FP8 matmul, ensure you have a Hopper (SM90+) or newer GPU with CUDA runtime 12.3+, and that the `kernels` package is installed and up to date (`pip install -U kernels`).')
        else:
            A_2d = A.view(-1, A.shape[-1])
            As_2d = As.view(-1, As.shape[-1])
            output = torch.empty(A_2d.shape[0], B.shape[0], device=A.device, dtype=output_dtype)
            deepgemm_fp8_matmul((A_2d, As_2d.float()), (B, Bs.float()), output)
            return output.view(A.shape[:-1] + (B.shape[0],))
    _load_triton_kernel()
    global triton_fp8_matmul
    return triton_fp8_matmul(A, B, As, Bs, block_size, output_dtype)

# --- helper: transformers.integrations.finegrained_fp8._load_deepgemm_kernel ---
def _load_deepgemm_kernel():
    global _deepgemm_available, deepgemm_fp8_matmul, deepgemm_grouped_fp8_matmul, deepgemm_per_token_cast_to_fp8
    if _deepgemm_available is not None:
        if not _deepgemm_available:
            raise ImportError('DeepGEMM kernel is not available (previous load attempt failed).')
        return
    _deepgemm_available = False
    if not torch.cuda.is_available():
        raise ImportError('DeepGEMM kernel requires CUDA, but CUDA is not available. Use a different `experts_implementation`.')
    major = torch.cuda.get_device_capability()[0]
    if major < 9:
        raise ImportError(f'DeepGEMM requires a Hopper (SM90+) or newer GPU, but the current device has compute capability {major}.x. Use a different `experts_implementation`.')
    cuda_major, cuda_minor = get_cuda_runtime_version()
    if cuda_major < 12 or (cuda_major == 12 and cuda_minor < 3):
        raise ImportError(f'DeepGEMM requires CUDA runtime 12.3+, but found {cuda_major}.{cuda_minor}. Please upgrade your CUDA toolkit or use a different `experts_implementation`.')
    kernel = lazy_load_kernel('deep-gemm')
    deepgemm_fp8_matmul = getattr(kernel, 'fp8_gemm_nt', None)
    deepgemm_grouped_fp8_matmul = getattr(kernel, 'm_grouped_fp8_gemm_nt_contiguous', None)
    deepgemm_per_token_cast_to_fp8 = resolve_internal_import(kernel, chained_path='utils.per_token_cast_to_fp8')
    missing = [name for name, attr in [('fp8_gemm_nt', deepgemm_fp8_matmul), ('m_grouped_fp8_gemm_nt_contiguous', deepgemm_grouped_fp8_matmul), ('utils.per_token_cast_to_fp8', deepgemm_per_token_cast_to_fp8)] if attr is None]
    if missing:
        raise ImportError(f"DeepGEMM kernel is missing required functions: {', '.join(missing)}. Please update the `kernels` package (`pip install -U kernels`).")
    _deepgemm_available = True

# --- helper: transformers.integrations.finegrained_fp8._load_triton_kernel ---
def _load_triton_kernel():
    global _triton_available, triton_fp8_act_quant, triton_fp8_matmul, triton_batched_fp8_matmul, triton_grouped_fp8_matmul
    if _triton_available is not None:
        if not _triton_available:
            raise ImportError('finegrained-fp8 kernel is not available (previous load attempt failed).')
        return
    _triton_available = False
    kernel = lazy_load_kernel('finegrained-fp8')
    triton_fp8_matmul = getattr(kernel, 'w8a8_fp8_matmul', None)
    triton_fp8_act_quant = getattr(kernel, 'fp8_act_quant', None)
    triton_batched_fp8_matmul = getattr(kernel, 'w8a8_fp8_matmul_batched', None)
    triton_grouped_fp8_matmul = getattr(kernel, 'w8a8_fp8_matmul_grouped', None)
    missing = [name for name, attr in [('w8a8_fp8_matmul', triton_fp8_matmul), ('fp8_act_quant', triton_fp8_act_quant), ('w8a8_fp8_matmul_batched', triton_batched_fp8_matmul), ('w8a8_fp8_matmul_grouped', triton_grouped_fp8_matmul)] if attr is None]
    if missing:
        raise ImportError(f"finegrained-fp8 kernel is missing required functions: {', '.join(missing)}. Please update the `kernels` package (`pip install -U kernels`).")
    _triton_available = True

def get_head_shapes(config) -> tuple[int | list[int], int | list[int]]:
    if hasattr(config, 'global_head_dim'):
        head_dim = [config.global_head_dim if layer == 'full_attention' else config.head_dim for layer in config.layer_types[:-config.num_kv_shared_layers]]
        num_heads = [config.num_global_key_value_heads if layer == 'full_attention' and config.attention_k_eq_v else config.num_key_value_heads for layer in config.layer_types[:-config.num_kv_shared_layers]]
    else:
        head_dim = getattr(config, 'head_dim', config.hidden_size // config.num_attention_heads)
        num_heads = getattr(config, 'num_key_value_heads', config.num_attention_heads)
    return (num_heads, head_dim)

def replace_with_bnb_linear(model: torch.nn.Module, modules_to_not_convert: list[str] | None=None, quantization_config=None, pre_quantized=False):
    has_been_replaced = False
    for module_name, module in model.named_modules():
        if not should_convert_module(module_name, modules_to_not_convert):
            continue
        new_module = None
        with torch.device('meta'):
            if isinstance(module, Conv1D) or type(module) is nn.Linear:
                if isinstance(module, Conv1D):
                    in_features, out_features = module.weight.shape
                else:
                    in_features = module.in_features
                    out_features = module.out_features
                if quantization_config.quantization_method() == 'llm_int8':
                    new_module = bnb.nn.Linear8bitLt(in_features, out_features, module.bias is not None, has_fp16_weights=quantization_config.llm_int8_has_fp16_weight, threshold=quantization_config.llm_int8_threshold)
                    if pre_quantized:
                        new_module.weight.data = new_module.weight.data.to(dtype=torch.int8)
                else:
                    new_module = bnb.nn.Linear4bit(in_features, out_features, module.bias is not None, quantization_config.bnb_4bit_compute_dtype, compress_statistics=quantization_config.bnb_4bit_use_double_quant, quant_type=quantization_config.bnb_4bit_quant_type, quant_storage=quantization_config.bnb_4bit_quant_storage)
                    if pre_quantized:
                        new_module.weight.data = new_module.weight.data.to(dtype=quantization_config.bnb_4bit_quant_storage)
                if new_module is not None:
                    new_module.source_cls = type(module)
                    new_module.requires_grad_(False)
                    model.set_submodule(module_name, new_module)
                    has_been_replaced = True
    if not has_been_replaced:
        logger.warning('You are loading your model using eetq but no linear modules were found in your model. Please double check your model architecture, or submit an issue on github if you think this is a bug.')
    return model

def get_target_dtype(query: torch.Tensor, module: torch.nn.Module) -> torch.dtype:
    if query.dtype == torch.float32:
        if torch.is_autocast_enabled('cuda'):
            return torch.get_autocast_dtype('cuda')
        elif hasattr(module.config, '_is_quantized'):
            return module.config.dtype
        else:
            return next((layer for layer in module.modules() if isinstance(layer, torch.nn.Linear))).weight.dtype
    return None

