def paged_attention_forward(module: torch.nn.Module, q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, attention_mask: torch.Tensor | None, cache: PagedAttentionCache, cu_seq_lens_q: torch.Tensor, cu_seq_lens_k: torch.Tensor | dict[str, torch.Tensor], max_seqlen_q: int, max_seqlen_k: int | dict[str, int], block_table: torch.Tensor | None, **kwargs) -> tuple[torch.Tensor, None]:
    flash_attn_varlen_func, flash_attn_with_kvcache = lazy_import_paged_flash_attention(module.config._attn_implementation)
    sliding_window = (-1, -1) if not getattr(module, 'sliding_window', False) else (module.sliding_window - 1, 0)
    layer_type = 'full_attention' if sliding_window == (-1, -1) else 'sliding_attention'
    if isinstance(cu_seq_lens_k, dict):
        cu_seq_lens_k = cu_seq_lens_k[layer_type]
        max_seqlen_k = max_seqlen_k[layer_type]
    if block_table is None:
        k, v = cache.update(key_states=k, value_states=v, layer_idx=module.layer_idx, read_index=kwargs['read_index'], write_index=kwargs['write_index'])
        custom_kwargs = {'s_aux': kwargs.get('s_aux')} if 's_aux' in kwargs else {}
        attn_output = flash_attn_varlen_func(q.transpose(1, 2).squeeze(0).contiguous(), k.contiguous(), v.contiguous(), cu_seq_lens_q.to(torch.int32), cu_seq_lens_k.to(torch.int32).clone(), max_seqlen_q, max_seqlen_k, softmax_scale=module.scaling, causal=True, window_size=sliding_window, **custom_kwargs)
        if isinstance(attn_output, tuple):
            attn_output = attn_output[0]
    else:
        flash_kwargs = {'s_aux': kwargs['s_aux']} if 's_aux' in kwargs else {}
        attn_output = _paged_decode_forward(module, q, k, v, cache, cu_seq_lens_k, sliding_window, flash_attn_with_kvcache, block_table, **flash_kwargs)
    return (attn_output, None)

# --- helper: transformers.integrations.flash_paged._paged_decode_forward ---
@torch.compiler.disable
def _paged_decode_forward(module: torch.nn.Module, q: torch.Tensor, k: torch.Tensor, v: torch.Tensor, cache: PagedAttentionCache, cu_seq_lens_k: torch.Tensor, sliding_window: tuple[int, int], flash_attn_with_kvcache, block_table: torch.Tensor, **flash_kwargs) -> torch.Tensor:
    group_idx, layer_idx_in_group = cache.layer_index_to_group_indices[module.layer_idx]
    k_cache = cache.key_cache[layer_idx_in_group].view(-1, cache.block_size, cache.num_key_value_heads, cache.head_dim)
    v_cache = cache.value_cache[layer_idx_in_group].view(-1, cache.block_size, cache.num_key_value_heads, cache.head_dim)
    q = q.permute(2, 0, 1, 3).contiguous()
    k = k.permute(2, 0, 1, 3).contiguous()
    v = v.permute(2, 0, 1, 3).contiguous()
    batch_size = k.size(0)
    cache_seqlens = (cu_seq_lens_k[1:batch_size + 1] - cu_seq_lens_k[:batch_size] - 1).to(torch.int32)
    flash_kwargs[cache.get_block_table_key(flash_attn_with_kvcache)] = block_table[group_idx]
    attn_output = flash_attn_with_kvcache(q=q, k_cache=k_cache, v_cache=v_cache, k=k, v=v, cache_seqlens=cache_seqlens, softmax_scale=module.scaling, causal=True, window_size=sliding_window, **flash_kwargs)
    if isinstance(attn_output, tuple):
        attn_output = attn_output[0]
    return attn_output.squeeze(1)

def swizzle_mxfp4_convertops(blocks, scales, module, proj, target_device, triton_kernels_hub):
    PrecisionConfig, FlexCtx, InFlexData = (triton_kernels_hub.matmul_ogs.PrecisionConfig, triton_kernels_hub.matmul_ogs.FlexCtx, triton_kernels_hub.matmul_ogs.InFlexData)
    local_experts = blocks.size(0)
    if getattr(target_device, 'type', target_device) == 'cpu' and hasattr(torch, 'accelerator') and (torch.accelerator.current_accelerator() is not None):
        target_device = torch.accelerator.current_accelerator().type
    blocks = blocks.to(target_device).contiguous()
    scales = scales.to(target_device).contiguous()
    if proj == 'gate_up_proj':
        blocks = blocks.reshape(local_experts, module.intermediate_size * 2, -1)
    else:
        blocks = blocks.reshape(local_experts, -1, module.intermediate_size // 2)
    with on_device(target_device):
        triton_weight_tensor, weight_scale = swizzle_mxfp4(blocks.transpose(-2, -1), scales.transpose(-2, -1), triton_kernels_hub)
    if proj == 'gate_up_proj':
        triton_weight_tensor.shape = torch.Size([local_experts, module.hidden_size, module.intermediate_size * 2])
    else:
        triton_weight_tensor.shape = torch.Size([local_experts, module.intermediate_size, module.hidden_size])
    if proj in module._parameters:
        del module._parameters[proj]
    setattr(module, proj, triton_weight_tensor)
    setattr(module, f'{proj}_precision_config', PrecisionConfig(weight_scale=weight_scale, flex_ctx=FlexCtx(rhs_data=InFlexData())))

# --- helper: transformers.integrations.mxfp4.on_device ---
@contextmanager
def on_device(dev):
    if is_torch_available():
        import torch
        if isinstance(dev, torch.Tensor):
            dev = dev.device
        elif isinstance(dev, str):
            dev = torch.device(dev)
        dev_type = getattr(dev, 'type', None)
        if dev_type == 'cuda':
            with torch.cuda.device(dev):
                yield
                return
        if dev_type == 'xpu' and hasattr(torch, 'xpu'):
            with torch.xpu.device(dev):
                yield
                return
    yield

# --- helper: transformers.integrations.mxfp4.swizzle_mxfp4 ---
def swizzle_mxfp4(w, w_scale, triton_kernels_hub):
    FP4, convert_layout, wrap_torch_tensor = (triton_kernels_hub.tensor.FP4, triton_kernels_hub.tensor.convert_layout, triton_kernels_hub.tensor.wrap_torch_tensor)
    layout = triton_kernels_hub.tensor_details.layout
    StridedLayout = triton_kernels_hub.tensor_details.layout.StridedLayout
    value_layout, value_layout_opts = layout.make_default_matmul_mxfp4_w_layout(mx_axis=1)
    w = convert_layout(wrap_torch_tensor(w, dtype=FP4), value_layout, **value_layout_opts)
    w_scale = convert_layout(wrap_torch_tensor(w_scale), StridedLayout)
    return (w, w_scale)

