class PeftConcatenate(Concatenate):

    @torch.no_grad
    def convert(self, input_dict: dict[str, list[torch.Tensor]], source_patterns: list[str], target_patterns: list[str], full_layer_name: str, **kwargs) -> dict[str, list[torch.Tensor]]:
        dims = [v.dim() for v in input_dict.values()]
        if set(dims) not in ({2}, {3}):
            raise ValueError(f'To convert this LoRA adapter, the LoRA weights all need to have either 2 or 3 dims, got {set(dims)}')
        ordered_tensors = [input_dict[source_pattern] for source_pattern in source_patterns if source_pattern in input_dict]
        if len(ordered_tensors) != len(input_dict):
            missing = set(input_dict) - set(source_patterns)
            raise ValueError(f'Collected tensors contain keys not present in source_patterns. Unexpected keys: {sorted(missing)}; source_patterns={source_patterns}')
        if set(dims) == {2}:
            output_dict = {full_layer_name: torch.block_diag(*ordered_tensors)}
        else:
            out = _block_diag_3d(ordered_tensors)
            out = torch.permute(out, (2, 0, 1))
            out = out.flatten(0, 1)
            out = out.T
            output_dict = {full_layer_name: out}
        return output_dict

    @property
    def reverse_op(self) -> ConversionOps:
        raise NotImplementedError('Reversing PEFT LoRA MoE conversions is not supported yet.')

# --- helper: transformers.integrations.peft._block_diag_3d ---
def _block_diag_3d(tensors: list[torch.Tensor]) -> torch.Tensor:
    if len(tensors) < 2:
        raise ValueError(f'_block_diag_3d expects at least 2 tensors, got {len(tensors)}')
    if any((t.dim() != 3 for t in tensors)):
        raise ValueError('_block_diag_3d expects all tensors to be 3d.')
    num_experts = tensors[0].shape[0]
    if any((t.shape[0] != num_experts for t in tensors)):
        raise ValueError('All tensors passed to _block_diag_3d must have the same number of experts.')
    lora_b_block_diag = []
    for i in range(num_experts):
        lora_b_block_diag.append(torch.block_diag(*[tensor[i] for tensor in tensors]))
    return torch.stack(lora_b_block_diag, dim=0)

class KubeflowCallback(TrainerCallback):
    _MIN_UPDATE_INTERVAL = 5.0
    _TOKEN_CACHE_DURATION = 300.0
    _ENV_SERVER_URL = 'KUBEFLOW_TRAINER_SERVER_URL'
    _ENV_CA_CERT = 'KUBEFLOW_TRAINER_SERVER_CA_CERT'
    _ENV_TOKEN_PATH = 'KUBEFLOW_TRAINER_SERVER_TOKEN'

    def __init__(self):
        if not is_kubeflow_available():
            raise RuntimeError('KubeflowCallback requires KUBEFLOW_TRAINER_SERVER_URL environment variable to be set. This is automatically set when running inside a Kubeflow TrainJob with TrainJobRuntimeStatus enabled.')
        self._initialized = False
        self._metrics = {}
        self._start_time = None
        self._last_update_time = 0.0
        self._cached_token = None
        self._token_read_time = 0.0
        self._ssl_context = None
        self._ssl_context_initialized = False
        logger.debug('[Kubeflow] Callback initialized')

    def _get_ssl_context(self):
        import ssl
        if self._ssl_context_initialized:
            return self._ssl_context
        ca_file = os.environ.get(self._ENV_CA_CERT)
        if ca_file:
            try:
                self._ssl_context = ssl.create_default_context(cafile=ca_file)
            except Exception as e:
                logger.warning(f'[Kubeflow] Failed to create SSL context with CA file {ca_file}: {e}')
                self._ssl_context = None
        self._ssl_context_initialized = True
        return self._ssl_context

    def _get_token(self):
        import time
        now = time.monotonic()
        if self._cached_token and now - self._token_read_time < self._TOKEN_CACHE_DURATION:
            return self._cached_token
        token_path = os.environ.get(self._ENV_TOKEN_PATH)
        if not token_path or not os.path.exists(token_path):
            logger.debug(f'[Kubeflow] Token file not found: {token_path}')
            return None
        try:
            with open(token_path) as f:
                self._cached_token = f.read().strip()
                self._token_read_time = now
                return self._cached_token
        except OSError as e:
            logger.debug(f'[Kubeflow] Failed to read token file: {e}')
            return None

    def _update_status(self, progress_percent=None, estimated_time_remaining=None, metrics=None, force=False):
        import json
        import time
        import urllib.request
        from datetime import datetime, timezone
        try:
            url = os.environ.get(self._ENV_SERVER_URL)
            if not url:
                return False
            now = time.monotonic()
            if not force and now - self._last_update_time < self._MIN_UPDATE_INTERVAL:
                return False
            self._last_update_time = now
            token = self._get_token()
            if not token:
                return False
            trainer_status = {'lastUpdatedTime': datetime.now(timezone.utc).isoformat()}
            if progress_percent is not None:
                trainer_status['progressPercentage'] = max(0, min(100, progress_percent))
            if estimated_time_remaining is not None:
                trainer_status['estimatedRemainingSeconds'] = max(0, int(estimated_time_remaining))
            if metrics:
                trainer_status['metrics'] = [{'name': str(k), 'value': str(v)} for k, v in metrics.items()]
            data = json.dumps({'trainerStatus': trainer_status}).encode('utf-8')
            headers = {'Authorization': f'Bearer {token}', 'Content-Type': 'application/json'}
            req = urllib.request.Request(url, data=data, headers=headers, method='POST')
            with urllib.request.urlopen(req, timeout=5, context=self._get_ssl_context()) as resp:
                return resp.status == 200
        except Exception as e:
            logger.debug(f'[Kubeflow] Failed to update status: {e}')
            return False

    def on_train_begin(self, args, state, control, **kwargs):
        if not state.is_world_process_zero:
            return
        import time
        self._start_time = time.time()
        self._metrics = {}
        self._initialized = True
        logger.debug(f'[Kubeflow] Training started, max_steps={state.max_steps}')
        self._update_status(progress_percent=0, metrics={'total_steps': state.max_steps} if state.max_steps else None, force=True)

    def on_log(self, args, state, control, logs=None, **kwargs):
        if not self._initialized or not state.is_world_process_zero or logs is None:
            return
        for key, value in logs.items():
            if isinstance(value, (int, float)):
                self._metrics[key] = value

    def on_step_end(self, args, state, control, **kwargs):
        if not self._initialized or not state.is_world_process_zero:
            return
        if not state.max_steps or state.max_steps <= 0:
            return
        import time
        progress = int(state.global_step / state.max_steps * 100)
        progress = min(progress, 99)
        eta_seconds = None
        if self._start_time and state.global_step > 0:
            elapsed = time.time() - self._start_time
            avg_time_per_step = elapsed / state.global_step
            remaining_steps = state.max_steps - state.global_step
            eta_seconds = int(avg_time_per_step * remaining_steps)
        metrics = {**self._metrics, 'current_step': state.global_step, 'total_steps': state.max_steps}
        if state.epoch is not None:
            metrics['current_epoch'] = round(state.epoch, 2)
        self._update_status(progress_percent=progress, estimated_time_remaining=eta_seconds, metrics=metrics)

    def on_train_end(self, args, state, control, **kwargs):
        if not self._initialized or not state.is_world_process_zero:
            return
        logger.debug('[Kubeflow] Training completed')
        self._update_status(progress_percent=100, estimated_time_remaining=0, metrics=self._metrics, force=True)

# --- helper: transformers.integrations.integration_utils.is_kubeflow_available ---
def is_kubeflow_available():
    if os.getenv('DISABLE_KUBEFLOW_INTEGRATION', 'FALSE').upper() == 'TRUE':
        return False
    return os.getenv('KUBEFLOW_TRAINER_SERVER_URL') is not None

class SinqDeserialize(ConversionOps):

    def __init__(self, hf_quantizer):
        self.hf_quantizer = hf_quantizer

    def convert(self, input_dict: dict[str, Any], model: torch.nn.Module | None=None, full_layer_name: str | None=None, **kwargs) -> dict[str, torch.Tensor]:
        for k, v in list(input_dict.items()):
            if isinstance(v, list):
                input_dict[k] = v[0]
        W_q = input_dict.get('.W_q')
        meta = input_dict.get('.meta')
        bias = input_dict.get('.bias')
        if W_q is None or meta is None:
            v = next(iter(input_dict.values()))
            if isinstance(v, list):
                v = v[0]
            return {full_layer_name: v}
        module, _ = get_module_from_name(model, full_layer_name)
        state = {'W_q': W_q, 'meta': meta}
        if bias is not None:
            state['bias'] = bias
        module.load_state_dict(state)
        module._is_hf_initialized = True
        return {}

def activate_neftune(model, neftune_noise_alpha, accelerator=None):
    if accelerator is not None:
        unwrapped_model = accelerator.unwrap_model(model)
    else:
        unwrapped_model = model
    if _is_peft_model(unwrapped_model):
        embeddings = unwrapped_model.base_model.model.get_input_embeddings()
    else:
        embeddings = unwrapped_model.get_input_embeddings()
    embeddings.neftune_noise_alpha = neftune_noise_alpha
    hook_handle = embeddings.register_forward_hook(neftune_post_forward_hook)
    return hook_handle

# --- helper: transformers.integrations.neftune.neftune_post_forward_hook ---
def neftune_post_forward_hook(module, input, output):
    if module.training:
        dims = torch.tensor(output.size(1) * output.size(2))
        mag_norm = module.neftune_noise_alpha / torch.sqrt(dims)
        output = output + torch.zeros_like(output).uniform_(-mag_norm, mag_norm)
    return output

def convert_peft_config_for_transformers(peft_config, model: torch.nn.Module, conversions: list[Any] | None):
    from peft import PeftType
    if peft_config.peft_type != PeftType.LORA:
        return peft_config
    if not hasattr(model, 'config'):
        return peft_config
    if not hasattr(model.config, 'model_type'):
        return peft_config
    peft_config = copy.deepcopy(peft_config)
    model_type = getattr(model.config, 'model_type', None)
    if get_checkpoint_conversion_mapping(model_type) is not None:
        peft_config = _convert_peft_config_moe(peft_config, model_type)
    return peft_config

# --- helper: transformers.integrations.peft._convert_peft_config_moe ---
def _convert_peft_config_moe(peft_config, model_type: str):
    base_model_type = _MODEL_TO_CONVERSION_PATTERN.get(model_type, None)
    if base_model_type is None:
        return peft_config
    target_module_mapping = _MOE_TARGET_MODULE_MAPPING.get(base_model_type)
    if target_module_mapping is None:
        return peft_config
    fused_targets = _MOE_FUSED_TARGETS.get(base_model_type, {})
    peft_config.target_parameters = set(peft_config.target_parameters or [])
    peft_config.target_modules = set(peft_config.target_modules or [])
    if not hasattr(peft_config, 'rank_pattern') or peft_config.rank_pattern is None:
        peft_config.rank_pattern = {}
    if not hasattr(peft_config, 'alpha_pattern') or peft_config.alpha_pattern is None:
        peft_config.alpha_pattern = {}
    new_target_parameters = peft_config.target_parameters.copy()
    remaining_target_modules = set()
    matched_targets: dict[str, set[str]] = {new_name: set() for new_name in fused_targets}
    for target in peft_config.target_modules:
        mapped_new_name = None
        mapped_old_name = None
        for old_name, new_name in target_module_mapping.items():
            if target == old_name or target.endswith(f'.{old_name}'):
                mapped_new_name = new_name
                mapped_old_name = old_name
                break
        if mapped_new_name is None:
            remaining_target_modules.add(target)
            continue
        new_target_parameters.add(mapped_new_name)
        if mapped_new_name in fused_targets and mapped_old_name is not None:
            matched_targets.setdefault(mapped_new_name, set()).add(mapped_old_name)
    for new_name, required_old_targets in fused_targets.items():
        present_targets = matched_targets.get(new_name, set())
        if 0 < len(present_targets) < len(required_old_targets):
            missing = ', '.join(sorted(required_old_targets - present_targets))
            present = ', '.join(sorted(present_targets))
            raise ValueError(f'Cannot convert PEFT target(s) {present} without also targeting {missing} because they are fused into {new_name}.')
        if len(present_targets) == len(required_old_targets) and len(required_old_targets) > 1:
            peft_config.rank_pattern[f'.*\\.{re.escape(new_name)}'] = peft_config.r * len(required_old_targets)
            peft_config.alpha_pattern[f'.*\\.{re.escape(new_name)}'] = peft_config.lora_alpha * len(required_old_targets)
    peft_config.target_parameters = new_target_parameters
    peft_config.target_modules = remaining_target_modules
    return peft_config

class ReplicatedWithGradAllReduce(TensorParallelLayer):

    def _prepare_input_fn(self, mod, inputs, device_mesh):
        return inputs

    def _prepare_output_fn(self, mod, outputs, device_mesh):
        return outputs

    def shard_tensor(self, param, tensor_idx=None, device=None, dtype=None):
        return param[...].to(device=device, dtype=dtype)

    def prepare_module_tp(self, module, device_mesh, **kwargs):

        def _backward_hook(mod, grad_input, grad_output, mesh=device_mesh):
            for param in mod.parameters():
                if param.grad is not None:
                    all_reduce_forward(param.grad, mesh)
        module.register_full_backward_hook(_backward_hook)

