def _lazy_imports(implementation: str | None, attention_wrapper: Callable | None=None, allow_all_kernels: bool=False):
    is_fa2 = is_flash_attn_2_available()
    is_fa3 = is_flash_attn_3_available()
    is_fa4 = is_flash_attn_4_available()
    pad_input, unpad_input = (_pad_input, _unpad_input)
    is_paged, implementation = split_attention_implementation(implementation)
    if implementation == 'flash_attention_2' and is_fa2 or (implementation is None and is_fa2 and (not is_fa3) and (not is_fa4)):
        from flash_attn import flash_attn_func, flash_attn_varlen_func, flash_attn_with_kvcache
        from flash_attn.bert_padding import pad_input, unpad_input
    elif is_torch_npu_available():
        from .integrations.npu_flash_attention import npu_flash_attn_func as flash_attn_func
