        from .integrations.npu_flash_attention import npu_flash_attn_with_kvcache as flash_attn_with_kvcache
    elif implementation == 'flash_attention_3' or (implementation is None and is_fa3 and (not is_fa4)):
        from flash_attn_interface import flash_attn_func, flash_attn_varlen_func, flash_attn_with_kvcache
    elif implementation == 'flash_attention_4' or (implementation is None and is_fa4):
        from flash_attn.cute import flash_attn_func, flash_attn_varlen_func
        flash_attn_with_kvcache = None
    else:
        from .integrations.hub_kernels import load_and_register_attn_kernel
        kernel_repo = FLASH_ATTN_KERNEL_FALLBACK.get(implementation, implementation)
        kernel_implementation = f'paged|{implementation}' if is_paged else kernel_repo
        kernel = load_and_register_attn_kernel(kernel_implementation, attention_wrapper, allow_all_kernels=allow_all_kernels)
        flash_attn_func = getattr(kernel, 'flash_attn_func', None)
        flash_attn_varlen_func = getattr(kernel, 'flash_attn_varlen_func', None)
        flash_attn_with_kvcache = getattr(kernel, 'flash_attn_with_kvcache', None)
        if flash_attn_varlen_func is None:
            raise ValueError(f'Could not find the currently requested flash attention implementation at `{implementation}`.Make sure that you request a valid kernel from the hub, e.g. `kernels-community/flash-attn2`.')
        if flash_attn_func is None:
            logger.warning(f'The loaded flash attention implementation at `{implementation}` only supports varlen, i.e. it can only be used with continuous batching and does not support the full functionality for the base transformers generation methods.')
        if flash_attn_with_kvcache is None:
            logger.warning(f'The loaded flash attention implementation at `{implementation}` does not support block tables, so the full performances of continuous batching will not be achieved, only the varlen path will be used.')
    return (flash_attn_func, flash_attn_varlen_func, flash_attn_with_kvcache, pad_input, unpad_input)

