def add_generation_mixin_to_remote_model(model_class):
    if 'torch.nn.modules.module.Module' not in str(model_class.__mro__):
        return model_class
    if 'GenerationMixin' in str(model_class.__bases__):
        return model_class
    has_custom_generate_in_class = hasattr(model_class, 'generate') and 'GenerationMixin' not in str(getattr(model_class, 'generate'))
    has_custom_prepare_inputs = hasattr(model_class, 'prepare_inputs_for_generation') and 'GenerationMixin' not in str(getattr(model_class, 'prepare_inputs_for_generation'))
    if has_custom_generate_in_class or has_custom_prepare_inputs:
        model_class_with_generation_mixin = type(model_class.__name__, (model_class, GenerationMixin), {**model_class.__dict__})
        return model_class_with_generation_mixin
    return model_class

class MecabTokenizer:

    def __init__(self, do_lower_case=False, never_split=None, normalize_text=True, mecab_dic: str | None='unidic_lite', mecab_option: str | None=None):
        self.do_lower_case = do_lower_case
        self.never_split = never_split if never_split is not None else []
        self.normalize_text = normalize_text
        try:
            import fugashi
        except ModuleNotFoundError as error:
            raise error.__class__('You need to install fugashi to use MecabTokenizer. See https://pypi.org/project/fugashi/ for installation.')
        mecab_option = mecab_option or ''
        if mecab_dic is not None:
            if mecab_dic == 'ipadic':
                try:
                    import ipadic
                except ModuleNotFoundError as error:
                    raise error.__class__('The ipadic dictionary is not installed. See https://github.com/polm/ipadic-py for installation.')
                dic_dir = ipadic.DICDIR
            elif mecab_dic == 'unidic_lite':
                try:
                    import unidic_lite
                except ModuleNotFoundError as error:
                    raise error.__class__('The unidic_lite dictionary is not installed. See https://github.com/polm/unidic-lite for installation.')
                dic_dir = unidic_lite.DICDIR
            elif mecab_dic == 'unidic':
                try:
                    import unidic
                except ModuleNotFoundError as error:
                    raise error.__class__('The unidic dictionary is not installed. See https://github.com/polm/unidic-py for installation.')
                dic_dir = unidic.DICDIR
                if not os.path.isdir(dic_dir):
                    raise RuntimeError('The unidic dictionary itself is not found. See https://github.com/polm/unidic-py for installation.')
            else:
                raise ValueError('Invalid mecab_dic is specified.')
            mecabrc = os.path.join(dic_dir, 'mecabrc')
            mecab_option = f'-d "{dic_dir}" -r "{mecabrc}" ' + mecab_option
        self.mecab = fugashi.GenericTagger(mecab_option)

    def tokenize(self, text, never_split=None, **kwargs):
        if self.normalize_text:
            text = unicodedata.normalize('NFKC', text)
        never_split = self.never_split + (never_split if never_split is not None else [])
        tokens = []
        for word in self.mecab(text):
            token = word.surface
            if self.do_lower_case and token not in never_split:
                token = token.lower()
            tokens.append(token)
        return tokens

def get_image_processor_class_from_name(class_name: str):
    if class_name == 'BaseImageProcessorFast':
        from ...image_processing_backends import TorchvisionBackend
        return TorchvisionBackend
    for mapping in IMAGE_PROCESSOR_MAPPING._extra_content.values():
        for extractor_class in mapping.values():
            if isinstance(extractor_class, type) and getattr(extractor_class, '__name__', None) == class_name:
                return extractor_class
    for model_type, extractors_dict in IMAGE_PROCESSOR_MAPPING_NAMES.items():
        if class_name in extractors_dict.values():
            module_name = model_type_to_module_name(model_type)
            module = importlib.import_module(f'.{module_name}', 'transformers.models')
            try:
                return getattr(module, class_name)
            except AttributeError:
                continue
    main_module = importlib.import_module('transformers')
    if hasattr(main_module, class_name):
        return getattr(main_module, class_name)
    return None

def rolling_polynomial_hash(token_tensor, prime: int=1000000007):
    prime_tensor = torch.tensor(prime, dtype=torch.int64, device=token_tensor.device)
    powers = torch.arange(token_tensor.shape[-1], device=token_tensor.device)
    prime_powers = prime_tensor ** powers
    return torch.sum(token_tensor * prime_powers, dim=-1)

class CodeLlamaTokenizer(TokenizersBackend):
    vocab_files_names = VOCAB_FILES_NAMES
    padding_side = 'left'
    model_input_names = ['input_ids', 'attention_mask']
    model = BPE

    def __init__(self, vocab: str | dict[str, int] | None=None, merges: str | list[str] | None=None, clean_up_tokenization_spaces=False, unk_token='<unk>', bos_token='<s>', eos_token='</s>', prefix_token='▁<PRE>', middle_token='▁<MID>', suffix_token='▁<SUF>', eot_token='▁<EOT>', fill_token='<FILL_ME>', additional_special_tokens=None, use_default_system_prompt: bool=False, add_prefix_space: bool | None=True, add_bos_token: bool=True, **kwargs):
        self.add_prefix_space = add_prefix_space if add_prefix_space is not None else True
        self.use_default_system_prompt = use_default_system_prompt
        additional_special_tokens = additional_special_tokens or []
        for token in [prefix_token, middle_token, suffix_token, eot_token, fill_token]:
            additional_special_tokens += [token] if token is not None else []
        self._vocab = vocab if vocab is not None else {str(unk_token): 0, str(bos_token): 1, str(eos_token): 2}
        self._merges = merges or []
        self._tokenizer = Tokenizer(BPE(vocab=self._vocab, merges=self._merges, fuse_unk=True, byte_fallback=True, dropout=None, unk_token=str(unk_token)))
        prepend_scheme = 'first' if self.add_prefix_space else 'never'
        self._tokenizer.pre_tokenizer = pre_tokenizers.Metaspace(replacement='▁', prepend_scheme=prepend_scheme, split=False)
        self._tokenizer.decoder = decoders.Sequence([decoders.Replace('▁', ' '), decoders.ByteFallback(), decoders.Fuse(), decoders.Strip(content=' ', left=1)])
        super().__init__(clean_up_tokenization_spaces=clean_up_tokenization_spaces, unk_token=unk_token, bos_token=bos_token, eos_token=eos_token, use_default_system_prompt=use_default_system_prompt, add_prefix_space=add_prefix_space, prefix_token=prefix_token, middle_token=middle_token, suffix_token=suffix_token, eot_token=eot_token, fill_token=fill_token, add_bos_token=add_bos_token, additional_special_tokens=additional_special_tokens, **kwargs)
        self._prefix_token = prefix_token
        self._middle_token = middle_token
        self._suffix_token = suffix_token
        self._eot_token = eot_token
        self.fill_token = fill_token

    @property
    def prefix_token(self):
        return self._prefix_token

    @property
    def prefix_id(self):
        if self._prefix_token is None:
            return None
        return self.convert_tokens_to_ids(self.prefix_token)

    @property
    def middle_token(self):
        return self._middle_token

    @property
    def middle_id(self):
        if self._middle_token is None:
            return None
        return self.convert_tokens_to_ids(self.middle_token)

    @property
    def suffix_token(self):
        return self._suffix_token

    @property
    def suffix_id(self):
        if self._suffix_token is None:
            return None
        return self.convert_tokens_to_ids(self.suffix_token)

    @property
    def eot_id(self):
        if self._eot_token is None:
            return None
        return self.convert_tokens_to_ids(self.eot_token)

    @property
    def eot_token(self):
        return self._eot_token

    def set_infilling_processor(self, reset, suffix_first=False, add_special_tokens=True):
        if reset:
            self._tokenizer.normalizer = normalizers.Sequence([normalizers.Prepend(prepend='▁'), normalizers.Replace(pattern=' ', content='▁')])
            self.update_post_processor()
            return
        self._tokenizer.normalizer = normalizers.Replace(pattern=' ', content='▁')
        pair = [self.bos_token] if self.add_bos_token and add_special_tokens else []
        special_tokens = [(self.bos_token, self.bos_token_id)] if self.add_bos_token and add_special_tokens else []
        if suffix_first:
            pair += [self.prefix_token, self.suffix_token, '$B', self.middle_token, '$A']
            special_tokens += [(self.prefix_token, self.prefix_id), (self.suffix_token, self.suffix_id), (self.middle_token, self.middle_id)]
        else:
            pair += [self.prefix_token, '$A', self.suffix_token, '$B', self.middle_token]
            special_tokens += [(self.prefix_token, self.prefix_id), (self.suffix_token, self.suffix_id), (self.middle_token, self.middle_id)]
        if self.add_eos_token and add_special_tokens:
            pair += [self.eos_token]
            special_tokens += [(self.eos_token, self.eos_token_id)]
        self._tokenizer.post_processor = processors.TemplateProcessing(single='$A', pair=pair, special_tokens=special_tokens)

    def tokenize(self, text, suffix=None, suffix_first=False, **kwargs):
        if self.fill_token is not None and self.fill_token in text and (suffix is None):
            text, suffix = text.split(self.fill_token)
        if suffix is None or len(suffix) < 1:
            return super().tokenize(text, **kwargs)
        if None in (self.prefix_id, self.middle_id, self.suffix_id):
            raise ValueError(f'The input either includes a `prefix` and a `suffix` used for the infilling task,  or can be split on the {self.fill_token} token, creating a suffix and prefix, but the model does not support `infilling`.')
        self.set_infilling_processor(False, suffix_first=suffix_first, add_special_tokens=False)
        kwargs.pop('text_pair', None)
        kwargs.pop('pair', None)
        result = super().tokenize(' ' + text, pair=suffix, **kwargs)
        self.set_infilling_processor(True)
        return result

    def _encode_plus(self, text, text_pair=None, suffix=None, suffix_first=False, add_special_tokens=True, **kwargs):
        is_infilling = False
        if suffix is not None:
            text_pair = suffix
            is_infilling = True
        elif 'suffix' in kwargs:
            text_pair = kwargs.pop('suffix')
            is_infilling = True
        if isinstance(text, str) and self.fill_token is not None and (self.fill_token in text) and (text_pair is None):
            text, text_pair = text.split(self.fill_token)
            is_infilling = True
        if not is_infilling:
            return super()._encode_plus(text, text_pair=text_pair, add_special_tokens=add_special_tokens, **kwargs)
        if text_pair is None or (isinstance(text_pair, str) and len(text_pair) < 1) or (isinstance(text_pair, list) and len(text_pair) == 0):
            return super()._encode_plus(text, text_pair=text_pair, add_special_tokens=add_special_tokens, **kwargs)
        if None in (self.prefix_id, self.middle_id, self.suffix_id):
            raise ValueError(f'The input includes a `prefix` and a `suffix` used for the infilling task, the `prefix_id, middle_id, suffix_id` must all be initialized. Current values : {(self.prefix_id, self.middle_id, self.suffix_id)}')
        self.set_infilling_processor(False, suffix_first=suffix_first, add_special_tokens=add_special_tokens)
        kwargs.pop('text_pair', None)
        if isinstance(text, str):
            text = ' ' + text
        elif isinstance(text, list):
            text = [' ' + t if isinstance(t, str) else t for t in text]
        result = super()._encode_plus(text, text_pair=text_pair, add_special_tokens=True, **kwargs)
        self.set_infilling_processor(True)
        return result

@auto_docstring(custom_intro='\n    Following the ColPali approach, ColModernVBert leverages VLMs to construct efficient multi-vector embeddings directly\n    from document images (“screenshots”) for document retrieval. The model is trained to maximize the similarity\n    between these document embeddings and the corresponding query embeddings, using the late interaction method\n    introduced in ColBERT.\n\n    Using ColModernVBert removes the need for potentially complex and brittle layout recognition and OCR pipelines with\n    a single model that can take into account both the textual and visual content (layout, charts, ...) of a document.\n\n    ColModernVBert is trained on top of ModernVBert, and was introduced in the following paper:\n    [*ModernVBERT: Towards Smaller Visual Document Retrievers*](https://arxiv.org/abs/2510.01149).\n\n    ColModernVBert is part of the ColVision model family, which was introduced with ColPali in the following paper:\n    [*ColPali: Efficient Document Retrieval with Vision Language Models*](https://huggingface.co/papers/2407.01449).\n    ')
class ColModernVBertForRetrieval(ColPaliForRetrieval):

    def __init__(self, config: ColModernVBertConfig):
