    @can_return_tuple
    @auto_docstring
    def forward(self, input_ids: torch.LongTensor | None=None, pixel_values: torch.FloatTensor | None=None, attention_mask: torch.Tensor | None=None, **kwargs: Unpack[TransformersKwargs]) -> ColModernVBertForRetrievalOutput:
