def apply_tesseract(image: 'np.ndarray | torch.Tensor', lang: str | None, tesseract_config: str | None=None, input_data_format: str | ChannelDimension | None=None):
    requires_backends(apply_tesseract, ['pytesseract'])
    if hasattr(image, 'cpu'):
        image = image.cpu().numpy()
    elif not isinstance(image, np.ndarray):
        image = np.array(image)
    tesseract_config = tesseract_config if tesseract_config is not None else ''
    pil_image = to_pil_image(image, input_data_format=input_data_format)
    image_width, image_height = pil_image.size
    data = pytesseract.image_to_data(pil_image, lang=lang, output_type='dict', config=tesseract_config)
    words, left, top, width, height = (data['text'], data['left'], data['top'], data['width'], data['height'])
    irrelevant_indices = [idx for idx, word in enumerate(words) if not word.strip()]
    words = [word for idx, word in enumerate(words) if idx not in irrelevant_indices]
    left = [coord for idx, coord in enumerate(left) if idx not in irrelevant_indices]
    top = [coord for idx, coord in enumerate(top) if idx not in irrelevant_indices]
    width = [coord for idx, coord in enumerate(width) if idx not in irrelevant_indices]
    height = [coord for idx, coord in enumerate(height) if idx not in irrelevant_indices]
    actual_boxes = []
    for x, y, w, h in zip(left, top, width, height):
        actual_box = [x, y, x + w, y + h]
        actual_boxes.append(actual_box)
    normalized_boxes = []
    for box in actual_boxes:
        normalized_boxes.append(normalize_box(box, image_width, image_height))
    assert len(words) == len(normalized_boxes), 'Not as many words as there are bounding boxes'
    return (words, normalized_boxes)

def get_best_fit(image_size: tuple[int, int], possible_resolutions: torch.Tensor, resize_to_max_canvas: bool=False) -> tuple[int, int]:
    original_height, original_width = image_size
    target_heights, target_widths = (possible_resolutions[:, 0], possible_resolutions[:, 1])
    scale_w = target_widths / original_width
    scale_h = target_heights / original_height
    scales = torch.where(scale_h > scale_w, scale_w, scale_h)
    upscaling_options = scales[scales >= 1]
    if len(upscaling_options) > 0:
        if resize_to_max_canvas:
            selected_scale = torch.max(upscaling_options)
        else:
            selected_scale = torch.min(upscaling_options)
    else:
        downscaling_options = scales[scales < 1]
        selected_scale = torch.max(downscaling_options)
    chosen_canvas = possible_resolutions[scales == selected_scale]
    if len(chosen_canvas) > 1:
        areas = chosen_canvas[:, 0] * chosen_canvas[:, 1]
        optimal_idx = torch.argmin(areas)
        optimal_canvas = chosen_canvas[optimal_idx]
    else:
        optimal_canvas = chosen_canvas[0]
    return optimal_canvas

def get_factors(dividend: int) -> set[int]:
    factors_set = set()
    for i in range(1, int(dividend ** 0.5) + 1):
        if dividend % i == 0:
            factors_set.add(i)
            factors_set.add(dividend // i)
    return factors_set

def convert_aspect_ratios_to_ids(aspect_ratios: list[list[tuple[int, int]]], max_image_tiles: int, device: Optional['torch.device']=None) -> 'torch.Tensor':
    batch_size = len(aspect_ratios)
    max_num_images = max((len(row) for row in aspect_ratios))
    supported_aspect_ratios = get_all_supported_aspect_ratios(max_image_tiles)
    aspect_ratios_ids = torch.zeros((batch_size, max_num_images), dtype=torch.long, device=device)
    for i, sample_aspect_ratios in enumerate(aspect_ratios):
        for j, (num_tiles_h, num_tiles_w) in enumerate(sample_aspect_ratios):
            aspect_ratios_ids[i, j] = supported_aspect_ratios.index((num_tiles_h, num_tiles_w)) + 1
    return aspect_ratios_ids

