    def crop_image_to_patches(self, image: np.ndarray, min_patches: int, max_patches: int, use_covering_area_grid: bool=True, covering_threshold: float=0.9, patch_size: SizeDict | None=None, resample: 'PILImageResampling | None'=None):
        input_data_format = infer_channel_dimension_format(image)
        image = to_channel_dimension_format(image, ChannelDimension.FIRST, input_data_format)
        patch_size_height, patch_size_width = (patch_size.height, patch_size.width)
        original_height, original_width = image.shape[-2:]
        if use_covering_area_grid:
            num_columns, num_rows = get_min_tile_covering_grid((original_height, original_width), target_patch_size=patch_size_height, max_image_tiles=max_patches, covering_threshold=covering_threshold)
        else:
            num_columns, num_rows = get_optimal_tiled_canvas((original_height, original_width), (patch_size_height, patch_size_width), min_patches, max_patches)
        target_width = patch_size_width * num_columns
        target_height = patch_size_height * num_rows
        num_blocks = num_columns * num_rows
        resized_image = self.resize(image, SizeDict(height=target_height, width=target_width), resample=resample)
        processed_images = []
        for i in range(num_blocks):
            column = i % num_columns
            row = i // num_columns
            box = (column * patch_size_width, row * patch_size_height, (column + 1) * patch_size_width, (row + 1) * patch_size_height)
            patch_image = resized_image[:, box[1]:box[3], box[0]:box[2]]
            processed_images.append(patch_image)
        if len(processed_images) != 1:
            thumbnail_img = self.resize(image, patch_size, resample=resample)
            processed_images.insert(0, thumbnail_img)
        return (processed_images, [num_rows, num_columns])

    def _preprocess(self, images: list[np.ndarray], do_resize: bool, size: SizeDict, resample: 'PILImageResampling | None', do_center_crop: bool, crop_size: SizeDict, do_rescale: bool, rescale_factor: float, do_normalize: bool, image_mean: float | list[float] | None, image_std: float | list[float] | None, return_tensors: str | TensorType | None, crop_to_patches: bool=False, min_patches: int=1, max_patches: int=12, use_covering_area_grid: bool=True, **kwargs) -> BatchFeature:
        if crop_to_patches and max_patches > 1:
            processed_images = []
            grids = []
            for image in images:
                patches, grid = self.crop_image_to_patches(image, min_patches, max_patches, patch_size=size, use_covering_area_grid=use_covering_area_grid, resample=resample)
                processed_images.extend(patches)
                grids.append(grid)
            images = processed_images
        else:
            grids = [[1, 1] for _ in range(len(images))]
        processed_images = []
        for image in images:
            if do_resize:
                image = self.resize(image, size=size, resample=resample)
            if do_center_crop:
                image = self.center_crop(image, crop_size)
            if do_rescale:
                image = self.rescale(image, rescale_factor)
            if do_normalize:
                image = self.normalize(image, image_mean, image_std)
            processed_images.append(image)
        return BatchFeature(data={'pixel_values': processed_images, 'grids': grids}, tensor_type=return_tensors)

