class RelativePositionBiasBase(nn.Module, ABC):

    def __init__(self, num_heads=None, relative_attention_num_buckets=32, bidirectional=True, scaling_factor=1, max_distance=128, level='tokens', augmentation=False, prefix_bucket=False, expand=False):
        super().__init__()
        self.prefix_bucket = prefix_bucket
        self.augmentation = augmentation
        self.level = level
        self.max_distance = max_distance
        self.scaling_factor = scaling_factor
        self.bidirectional = bidirectional
        self.num_heads = num_heads
        self.expand = expand
        self.relative_attention_num_buckets = relative_attention_num_buckets
        extra_head = 2 if prefix_bucket and (not self.expand) else 0
        self.relative_attention_bias = nn.Embedding(self.relative_attention_num_buckets + extra_head, self.num_heads)

    @abstractmethod
    def prepare_input(self, attention_mask: Tensor | None=None, bbox: dict[str, Any] | None=None) -> Tensor:
        pass

    def get_bucket(self, attention_mask: Tensor | None=None, bbox: dict[str, Any] | None=None) -> Tensor:
        relative_position = self.prepare_input(attention_mask, bbox)
        rp_bucket: Tensor = get_relative_position_bucket(relative_position, bidirectional=self.bidirectional, num_buckets=self.relative_attention_num_buckets, max_distance=self.max_distance)
        return rp_bucket

    def get_relative_position(self, positions):
        context_position = positions[:, :, None]
        memory_position = positions[:, None, :]
        relative_position = memory_position - context_position
        if self.augmentation and self.training:
            relative_position *= random.uniform(*AUGMENTATION_RANGE)
        relative_position *= self.scaling_factor
        return relative_position.to(torch.long)

    def forward(self, attention_mask: Tensor | None=None, bbox: dict[str, Any] | None=None) -> Tensor:
        if self.expand and self.prefix_bucket:
            new_bias = nn.Embedding(self.relative_attention_num_buckets + 2, self.num_heads)
            new_bias.weight.data[:self.relative_attention_num_buckets] = self.relative_attention_bias.weight.data
            new_bias.weight.data[self.relative_attention_num_buckets:] = 0.1
            self.relative_attention_bias = new_bias
            self.expand = False
        rp_bucket = self.get_bucket(attention_mask, bbox)
        if self.prefix_bucket:
            if rp_bucket.size(0) == 1 and attention_mask.size(0) > 1:
                rp_bucket = rp_bucket.repeat(attention_mask.size(0), 1, 1)
            is_prefix = bbox[:, :, 1] < 0
            num_prefix = is_prefix.sum(-1)
            for idx, num_prefix_row in enumerate(num_prefix.cpu().numpy()):
                rp_bucket[idx, :num_prefix_row, num_prefix_row:] = self.relative_attention_num_buckets
                rp_bucket[idx, num_prefix_row:, :num_prefix_row] = self.relative_attention_num_buckets + 1
        values: Tensor = self.relative_attention_bias(rp_bucket)
        if values.dim() != 4:
            raise ValueError('Wrong dimension of values tensor')
        values = values.permute([0, 3, 1, 2])
        return values

class VibeVoiceAcousticTokenizerCausalConvTranspose1d(nn.Module):

    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, cache_key: str, stride: int=1):
        super().__init__()
        self.convtr = nn.ConvTranspose1d(in_channels, out_channels, kernel_size, stride)
        self.stride = stride
        self.cache_key = cache_key
        self.in_channels = in_channels
        self.padding_total = kernel_size - stride
        self.causal_padding = kernel_size - 1
        self.left_pad = self.causal_padding

    def forward(self, hidden_states: torch.Tensor, padding_cache: Optional['VibeVoiceAcousticTokenizerConv1dPaddingCache']=None) -> torch.Tensor:
        time_dim = hidden_states.shape[-1]
        if padding_cache is not None:
            hidden_states = padding_cache.update(hidden_states, self.cache_key, self)
        hidden_states = self.convtr(hidden_states)
        if self.padding_total > 0:
            hidden_states = hidden_states[..., :-self.padding_total]
        if padding_cache is not None:
            expected_new_output = time_dim * self.stride
            if hidden_states.shape[2] >= expected_new_output:
                hidden_states = hidden_states[:, :, -expected_new_output:]
        return hidden_states

def box_to_center_and_scale(box: tuple | list | np.ndarray, image_width: int, image_height: int, normalize_factor: float=200.0, padding_factor: float=1.25):
    top_left_x, top_left_y, width, height = box[:4]
    aspect_ratio = image_width / image_height
    center = np.array([top_left_x + width * 0.5, top_left_y + height * 0.5], dtype=np.float32)
    if width > aspect_ratio * height:
        height = width * 1.0 / aspect_ratio
    elif width < aspect_ratio * height:
        width = height * aspect_ratio
    scale = np.array([width / normalize_factor, height / normalize_factor], dtype=np.float32)
    scale = scale * padding_factor
    return (center, scale)

def soft_cap(values: torch.Tensor, cap_value: float | torch.Tensor | None=None) -> torch.Tensor:
    if cap_value is None:
        return values
    return cap_value * torch.tanh(values / cap_value)

class VitPoseNaiveMoe(nn.ModuleList):

    def __init__(self, config):
        super().__init__()
        self.num_experts = config.num_experts
        self.part_features = config.part_features
        hidden_features = int(config.hidden_size * config.mlp_ratio)
        part_features = config.part_features
        for _ in range(self.num_experts):
            self.append(nn.Linear(hidden_features, part_features))

    def forward(self, hidden_state, indices):
        expert_hidden_state = torch.zeros_like(hidden_state[:, :, -self.part_features:])
        for i in range(self.num_experts):
            selected_index = indices == i
            current_hidden_state = self[i](hidden_state) * selected_index
            expert_hidden_state = expert_hidden_state + current_hidden_state
        return expert_hidden_state

def wang_init_method(n_layers, dim):
    std = 2 / n_layers / dim ** (1 / 2)

    def init_(tensor):
        return init.normal_(tensor, mean=0.0, std=std)
    return init_

class xLSTMRMSNorm(nn.Module):

    def __init__(self, num_features: int, eps: float=1e-06, use_weight: bool=True, use_bias: bool=False, force_float32_reductions: bool=True):
        super().__init__()
        self.num_features = num_features
        self.eps = eps
        self.force_float32_reductions = force_float32_reductions
        if use_weight:
            self.weight = nn.Parameter(torch.ones(num_features))
        else:
            self.weight = None
        if use_bias:
            self.bias = nn.Parameter(torch.zeros(num_features))
        else:
            self.bias = None

    def _apply_weight_bias(self, x: torch.Tensor) -> torch.Tensor:
        if self.weight is not None:
            x = x * self.weight
        if self.bias is not None:
            x = x + self.bias
        return x

    def _rms_normalize(self, x: torch.Tensor) -> torch.Tensor:
        in_dtype = x.dtype
        if self.force_float32_reductions:
            x = x.float()
        x = x * torch.rsqrt(x.pow(2).mean(dim=-1, keepdim=True) + self.eps)
        return x.to(in_dtype)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = self._rms_normalize(x)
        x = self._apply_weight_bias(x)
        return x

def patch_output_recorders(model: nn.Module) -> None:
    mapping = get_patch_mapping()
    if not mapping:
        return
    for submodule in model.modules():
        if hasattr(submodule, '_can_record_outputs') and submodule._can_record_outputs is not None:
            for output, recorder in submodule._can_record_outputs.items():
                if isinstance(recorder, OutputRecorder):
                    replacement_class = _find_replacement_class(recorder.target_class.__name__, mapping)
                    if replacement_class is not None:
                        recorder.target_class = replacement_class
                elif isinstance(recorder, type):
                    replacement_class = _find_replacement_class(recorder.__name__, mapping)
                    if replacement_class is not None:
                        submodule._can_record_outputs[output] = replacement_class

# --- helper: transformers.monkey_patching._find_replacement_class ---
def _find_replacement_class(class_name: str, mapping: dict[str, type[nn.Module]]) -> type[nn.Module] | None:
    if class_name in mapping:
        return mapping[class_name]
    for pattern, replacement_class in mapping.items():
        if pattern == class_name:
            continue
        compiled_pattern = _compile_pattern(pattern)
        if compiled_pattern is not None and compiled_pattern.search(class_name):
            return replacement_class
    return None

# --- helper: transformers.monkey_patching.get_patch_mapping ---
def get_patch_mapping() -> dict[str, type[nn.Module]]:
    with _monkey_patch_lock:
        return _monkey_patch_mapping_cache.copy()

class GreedyLR:

    def __init__(self, optimizer: Optimizer, mode: str='min', factor: float=0.95, patience: int=10, threshold: float=1e-06, threshold_mode: str='abs', cooldown: int=0, warmup: int=0, min_lr: float | list[float]=0.001, max_lr: float | list[float]=1.0, eps: float=1e-08, verbose: bool=False, smooth: bool=False, window_size: int=50, reset_start: int=500) -> None:
        if factor >= 1.0:
            raise ValueError('Factor should be < 1.0.')
        if not isinstance(optimizer, Optimizer):
            raise TypeError(f'{type(optimizer).__name__} is not an Optimizer')
        self.optimizer = optimizer
        self.factor = factor
        self.patience = patience
        self.verbose = verbose
        self.cooldown = cooldown
        self.warmup = warmup
        self.cooldown_counter = 0
        self.warmup_counter = 0
        self.mode = mode
        self.threshold = threshold
        self.threshold_mode = threshold_mode
        self.eps = eps
        self.smooth = smooth
        self.window_size = window_size
        self.reset_start = reset_start
        self.reset_start_original = reset_start
        self.last_epoch = 0
        if isinstance(min_lr, (list, tuple)):
            if len(min_lr) != len(optimizer.param_groups):
                raise ValueError(f'expected {len(optimizer.param_groups)} min_lrs, got {len(min_lr)}')
            self.min_lrs = list(min_lr)
        else:
            self.min_lrs = [min_lr] * len(optimizer.param_groups)
        if isinstance(max_lr, (list, tuple)):
            if len(max_lr) != len(optimizer.param_groups):
                raise ValueError(f'expected {len(optimizer.param_groups)} max_lrs, got {len(max_lr)}')
            self.max_lrs = list(max_lr)
        else:
            self.max_lrs = [max_lr] * len(optimizer.param_groups)
        self._init_lrs = [group['lr'] for group in optimizer.param_groups]
        self._last_lr = self._init_lrs.copy()
        self.best: float = float('inf') if mode == 'min' else float('-inf')
        self.num_bad_epochs = 0
        self.num_good_epochs = 0
        if mode not in ('min', 'max'):
            raise ValueError(f'mode {mode} is unknown!')
        if threshold_mode not in ('rel', 'abs'):
            raise ValueError(f'threshold mode {threshold_mode} is unknown!')
        self._streaming_avg: StreamingAverage | None = None
        if smooth:
            self._streaming_avg = StreamingAverage(window_size)

    def step(self, metrics: float, epoch: int | None=None) -> None:
        current = float(metrics)
        if self.smooth and self._streaming_avg is not None:
            current = self._streaming_avg.streamavg(current)
        if epoch is None:
            epoch = self.last_epoch + 1
        self.last_epoch = epoch
        if self.cooldown_counter > 0:
            self.cooldown_counter -= 1
            self.num_bad_epochs = 0
            self.num_good_epochs = 0
        elif self.warmup_counter > 0:
            self.warmup_counter -= 1
            self.num_bad_epochs = 0
            self.num_good_epochs = 0
        else:
            if self.is_better(current, self.best):
                self.best = current
                self.num_bad_epochs = 0
                self.num_good_epochs += 1
            else:
                self.num_bad_epochs += 1
                self.num_good_epochs = 0
            if self.num_good_epochs > self.patience:
                self._increase_lr(epoch)
                self.warmup_counter = self.warmup
                self.num_good_epochs = 0
            elif self.num_bad_epochs > self.patience:
                self._reduce_lr(epoch)
                self.cooldown_counter = self.cooldown
                self.num_bad_epochs = 0
        self._last_lr = [group['lr'] for group in self.optimizer.param_groups]

    def is_better(self, current: float, best: float) -> bool:
        if self.mode == 'min':
            if self.threshold_mode == 'rel':
                return current < best * (1.0 - self.threshold)
            else:
                return current < best - self.threshold
        elif self.threshold_mode == 'rel':
            return current > best * (1.0 + self.threshold)
        else:
            return current > best + self.threshold

    def _reduce_lr(self, epoch: int) -> None:
