import transformers.utils.generic as generic

# Example 3: Retry only on a specific exception type
@generic.retry(max_retries=3, exceptions=(ValueError,))
def parse_number(s):
    # Raises ValueError for invalid input; will be retried up to 3 times
    if not hasattr(parse_number, "attempts"):
        parse_number.attempts = 0
    parse_number.attempts += 1
    if parse_number.attempts < 2:
        # simulate transient bad input that becomes correct on retry
        raise ValueError("bad number format")
    return int(s)

