def retry(max_retries=5, initial_delay=1.0, max_delay=30.0, jitter=True, exceptions=(Exception,)):

    def decorator(func):

        @wraps(func)
        def wrapper(*args, **kwargs):
            delay = initial_delay
            for attempt in range(1, max_retries + 1):
                try:
                    return func(*args, **kwargs)
                except exceptions as exc:
                    if attempt == max_retries:
                        raise
                    sleep_for = min(delay, max_delay)
                    if jitter:
                        sleep_for *= random.uniform(0.8, 1.2)
                    logger.info(f'[{func.__name__}] attempt {attempt}/{max_retries} failed: {exc}\nRetrying in {sleep_for:.1f}s...')
                    time.sleep(sleep_for)
                    delay = min(delay * 2, max_delay)
        return wrapper
    return decorator

def fetch__all__(file_content) -> list[str]:
    if '__all__' not in file_content:
        return []
    start_index = None
    lines = file_content.splitlines()
    for index, line in enumerate(lines):
        if line.startswith('__all__'):
            start_index = index
    if start_index is None:
        return []
    lines = lines[start_index:]
    if not lines[0].startswith('__all__'):
        raise ValueError('fetch__all__ accepts a list of lines, with the first line being the __all__ variable declaration')
    if lines[0].endswith(']'):
        return [obj.strip('"\' ') for obj in lines[0].split('=')[1].strip(' []').split(',')]
    else:
        _all: list[str] = []
        for __all__line_index in range(1, len(lines)):
            if lines[__all__line_index].strip() == ']':
                return _all
            else:
                _all.append(lines[__all__line_index].strip('"\', '))
        return _all

