def get_hasher(algorithm='default'):
    if hasattr(algorithm, 'algorithm'):
        return algorithm
    elif algorithm == 'default':
        return get_hashers()[0]
    else:
        hashers = get_hashers_by_algorithm()
        try:
            return hashers[algorithm]
        except KeyError:
            raise ValueError("Unknown password hashing algorithm '%s'. Did you specify it in the PASSWORD_HASHERS setting?" % algorithm)

# --- helper: django.contrib.auth.hashers.identify_hasher ---
def identify_hasher(encoded):
    if len(encoded) == 32 and '$' not in encoded or (len(encoded) == 37 and encoded.startswith('md5$$')):
        algorithm = 'unsalted_md5'
    elif len(encoded) == 46 and encoded.startswith('sha1$$'):
        algorithm = 'unsalted_sha1'
    else:
        algorithm = encoded.split('$', 1)[0]
    return get_hasher(algorithm)

# --- helper: django.contrib.auth.hashers.is_password_usable ---
def is_password_usable(encoded):
    return encoded is None or not encoded.startswith(UNUSABLE_PASSWORD_PREFIX)

