def format_sse_event(*, data_str: Annotated[str | None, Doc('\n            Pre-serialized data string to use as the `data:` field.\n            ')]=None, event: Annotated[str | None, Doc('\n            Optional event type name (`event:` field).\n            ')]=None, id: Annotated[str | None, Doc('\n            Optional event ID (`id:` field).\n            ')]=None, retry: Annotated[int | None, Doc('\n            Optional reconnection time in milliseconds (`retry:` field).\n            ')]=None, comment: Annotated[str | None, Doc('\n            Optional comment line(s) (`:` prefix).\n            ')]=None) -> bytes:
    lines: list[str] = []
    if comment is not None:
        for line in comment.splitlines():
            lines.append(f': {line}')
    if event is not None:
        lines.append(f'event: {event}')
    if data_str is not None:
        for line in data_str.splitlines():
            lines.append(f'data: {line}')
    if id is not None:
        lines.append(f'id: {id}')
    if retry is not None:
        lines.append(f'retry: {retry}')
    lines.append('')
    lines.append('')
    return '\n'.join(lines).encode('utf-8')

class ScriptInfo:

    def __init__(self, app_import_path: str | None=None, create_app: t.Callable[..., Flask] | None=None, set_debug_flag: bool=True, load_dotenv_defaults: bool=True) -> None:
        self.app_import_path = app_import_path
        self.create_app = create_app
        self.data: dict[t.Any, t.Any] = {}
        self.set_debug_flag = set_debug_flag
        self.load_dotenv_defaults = get_load_dotenv(load_dotenv_defaults)
        "Whether default ``.flaskenv`` and ``.env`` files should be loaded.\n\n        ``ScriptInfo`` doesn't load anything, this is for reference when doing\n        the load elsewhere during processing.\n\n        .. versionadded:: 3.1\n        "
        self._loaded_app: Flask | None = None

    def load_app(self) -> Flask:
        if self._loaded_app is not None:
            return self._loaded_app
        app: Flask | None = None
        if self.create_app is not None:
            app = self.create_app()
        elif self.app_import_path:
            path, name = (re.split(':(?![\\\\/])', self.app_import_path, maxsplit=1) + [None])[:2]
            import_name = prepare_import(path)
            app = locate_app(import_name, name)
        else:
            for path in ('wsgi.py', 'app.py'):
                import_name = prepare_import(path)
                app = locate_app(import_name, None, raise_if_not_found=False)
                if app is not None:
                    break
        if app is None:
            raise NoAppException("Could not locate a Flask application. Use the 'flask --app' option, 'FLASK_APP' environment variable, or a 'wsgi.py' or 'app.py' file in the current directory.")
        if self.set_debug_flag:
            app.debug = get_debug_flag()
        self._loaded_app = app
        return app

