from datetime import datetime
from typing import Annotated

from pydantic import BaseModel, ValidationError
from pydantic.functional_validators import WrapValidator


def validate_timestamp(v, handler):
    if v == 'now':
        # bypass inner validation and return current time
        return datetime.now()
    try:
        return handler(v)
    except ValidationError:
        # on inner-validation failure, return a default datetime
        return datetime(2000, 1, 1)


MyTimestamp = Annotated[datetime, WrapValidator(validate_timestamp)]


class Model(BaseModel):
    a: MyTimestamp


# returns current time
print(Model(a='now').a)
# invalid input -> default
print(Model(a='invalid').a)

from typing import Annotated

from pydantic import BaseModel
from pydantic.functional_validators import WrapValidator


# wrap validator that converts strings to ints before inner validation
def coerce_int(v, handler):
    if isinstance(v, str):
        try:
            v = int(v)
        except ValueError:
            # let inner validation handle the error
            return handler(v)
    return handler(v)


# provide json_schema_input_type to influence schema generation (optional)
MyInt = Annotated[int, WrapValidator(coerce_int, int)]


class Model(BaseModel):
    value: MyInt


print(Model(value='42').value)  # -> 42
print(Model(value=7).value)     # -> 7

