def is_fwd_ref(type_: _AnnotationScanType, check_generic: bool=False, check_for_plain_string: bool=False) -> TypeGuard[ForwardRef]:
    if check_for_plain_string and isinstance(type_, str):
        return True
    elif isinstance(type_, _type_instances.ForwardRef):
        return True
    elif check_generic and is_generic(type_):
        return any((is_fwd_ref(arg, True, check_for_plain_string=check_for_plain_string) for arg in type_.__args__))
